export default [{"id":4717,"title":"ابن رشيد يبسط نفوذه على بلاد الوشم وسدير  .","date":["العام الهجري :1301","العام الميلادي :1883"],"text":"حاول عبدُ الله بن فيصل إخضاعَ أهل المجمعة واستردادَ سلطتِه عليهم، لكنَّه فَشِلَ أمام تحالُف أهل المنطقة مع ابن رشيد وآل مهنا، فمُنِيَت قواتُه بخسائِرَ فادحةٍ في الأرواحِ، فبَسَط ابن رشيد نفوذَه على الوشم وسدير، وعيَّنَ لها حاكِمًا من قِبَلِه، وكاتبَ البلدانَ المجاورةَ لتدخُلَ في طاعته، ولَمَّا أرسل عبدُ الله أخاه محمدًا لابن رشيد للتفاهمِ معه والتفاوض، جلَا ابنُ رشيد عن الوشمِ إكرامًا له، ودليلًا على حُسنِ نيَّتِه، وأرسل معه هدايا ثمينة للإمامِ عبد الله ووعده بالمسالَمةِ."},{"id":4718,"title":"انتصار الثورة المهدية في السودان .","date":["العام الهجري :1302","العام الميلادي :1884"],"text":"طلب اللورد كرومر المندوب السامي البريطاني بمصرَ مِن الضابط تشارلز جورج غوردون الإشرافَ على إخلاء السودان من القواتِ المصرية تمهيدًا لاحتلالها، ولكن غوردون رفض ذلك الطلبَ وأعلن أنَّ القواتِ الإنجليزيةَ والمصريةَ المشتركة بالخرطوم سوف تتحَرَّكُ للقضاء على الثورة المهدية، وكان ذلك منه غطرسةً وتكبُّرًا دفع ثمنَهما حياتَه؛ تحرَّكت قواتُ المهدي باتجاه الخرطوم أواخِرَ سنة 1301هـ 1884م، وأرسل المهديُّ مندوبًا من عنده يطلُبُ من غوردون تسليمَ الخرطوم، فرفض وأبى واستكبر بشدة، فضرب المهديون حصارًا شديدًا على المدينة، وعندها تحرَّكت الحكومة الإنجليزية برئاسةِ جلادستون وأرسلت قواتٍ لنجدة الحاميةِ المصرية في السودانِ، وذلك في أوائل سنة 1302هـ 1885م، وعندها قرَّر المهديون اقتحامَ المدينة فاقتحموها في 12 ربيع الآخر سنة 1302هـ، وكان رأسُ غوردون هو أوَّلَ رأسٍ قُطِعَ في هذه المعركة التي أصبحت بعدها السودان كلُّها خاضعةً للحركة المهدية، وكان لسقوطِ الخرطوم ومقتَل غوردون صدًى عظيمًا في إنجلترا، ولكِنَّ ثمار الحركة لم تكتَمِلْ؛ إذ مات زعيمُها بعد ذلك بقليلٍ."},{"id":4719,"title":"فرنسا تستقل باستعمار غينيا .","date":["العام الهجري :1302","العام الميلادي :1884"],"text":"بدا نفوذُ فرنسا في غينيا منذ عام 1254هـ / 1838م؛ حيثُ تدخَّلت بسبب الاختلاف مع أحد أمراء القبائل حولَ تجارةِ الرقيقِ، وفي عام 1270هـ / 1854م أرادت أن تَحولَ بين بريطانيا وبين رَبطِ منطقة غامبيا بمنطقة سيراليون باحتلالِ جهات غينيا؛ لذا أسرعت فرنسا واحتلَّت مدينة دوبريكا وما حولها لتقطَعَ على بريطانيا الطريقَ، وفي هذا العام عُقِدَ مؤتمر برلين، ونتيجتُه استقَلَّت فرنسا بأنحاء غينيا وأخذت تتوسَّعُ بجهات غينيا كلِّها، واحتَلَّت جزيرة تومبو التي تقَعُ عليها عاصمة البلاد الحالية كوناكري."},{"id":4720,"title":"التنافس على فارس والخليج بين الإنجليز والروس .","date":["العام الهجري :1302","العام الميلادي :1884"],"text":"كانت مَطامِعُ روسيا ومنذ عهد بطرس الأكبر الوصولَ إلى مياه الخليج العربي، والسيطرةَ على بلاد فارس المجاوِرة، والحُصولَ على قاعدة بحرية في الخليج العربي، وكانت بريطانيا هي المنافِسَ لروسيا؛ حيث استطاعت الملاحةُ في نهر الكارون، وعَقَدت الاتفاقيات مع الشاه، ومن جانبٍ آخر قام الروس بتسخير جيشٍ لحماية الشاه من الانقلابات والتمرُّدات العسكرية، فأصبح الروسُ لهم نفوذٌ في الشمال من إيران، ومن البريطانيين في الجنوب، وقامت بريطانيا بتقوية مراكزها التجارية على الموانئ مِثل بندر عباس والمحمرة وبوشهر، ومع ذلك أبدت رغبتَها في التعاون مع الروس لإيجادِ منفذٍ تجاريٍّ لها في شمال فارس، وفي الوقت نفسِه حَرَصت على عدم تقوِّي الروس في الجنوب حتى لا يُصبِحوا منافسين لها، فكانت تعمَلُ على إثارة الولايات للتمَرُّد على الولاية المركزية، وأما الروسُ فكان مشروعُ سكة الحديد إلى الكويتِ مِن البحر المتوسط مثيرًا لقلق البريطانيين، فقامت بريطانيا بتوقيع معاهدة مع الكويت بجَعلِها تحت الحماية البريطانية، وردًّا على الأمر حاولت روسيا التقرُّبَ من الكويت وحاولت الاستيلاءَ على ميناء بندر عباس وبعض الجزر الواقعة في مضيق هرمز، فأسست شركاتٍ للملاحة بين موانئ البحر الأسود وموانئ الخليج العربي، وفتحت قنصلياتٍ في بوشهر والبصرة, وهكذا كانت الدولتانِ تتنافسان مع الشاهِ بعَقدِ الاتفاقيات التجارية والامتيازات النفطية والتنقيبِ، حتى تطوَّرت الأمور وعَقَدت الدولتان الروسية والبريطانية اتفاقًا يحدِّدُ مناطِقَ نفوذ كلٍّ منهما على فارس؛ حيث كانت حصةُ روسيا أكبَرَ من بريطانيا."},{"id":4721,"title":"وفاة القائد الإنجليزي غوردون  .","date":["العام الهجري :1302","العام الميلادي :1884"],"text":"هو اللواءُ تشارلز جورج غوردون المعروف بلقب (غوردون الصين) و(غوردون باشا) و(غوردون الخرطوم). ولِدَ بلندن عام 1833م.كان غوردون ضابطًا وإداريًّا في الجيش البريطاني، وتنقَّلَ في عدد من المهام القيادية العسكرية البريطانية، فعُيِّن في سلاحِ الهندسة الملكية، واشترك في حربِ القرم وعمُرُه واحد وعشرون عامًا، ثم اشترك في حربِ الصين؛ حيث أسهم في الاستيلاء على بكِّين، ثم تولى قيادة الجيش الصينيالذي قمع ثورة تيبنج. وفي سنة (1874 م) عيَّنه الخديوي إسماعيل حاكمًا عامًّا للسودان، وظَلَّ في منصبه سبع سنوات، وعندما طلب منه المندوبُ السامي البريطاني بمصر اللورد كرومر الانسحابَ مِن مصر رفَضَ وأبى واستكبر بشدة، فبدأت جيوشُ المهدية بحصار الخرطوم، وكان غوردون عَمِلَ على تحصين المدينة بالأسلاك الشائكة وتقوية القلاع وزرع الألغام. وكانت حاميةُ الخرطوم مكونة من مصريين وأتراك وبعض السودانيين، فجاء المهدي بجمعٍ يقَدَّرُ بأكثر من مائة ألف مقاتل، وكان غوردون قبل أن يشتدَّ عليه الحصار أرسل إلى حكومتِه طالبًا حملة تفتح الطريقَ بينه وبين مصر لسَحبِ الحاميات، ثم اضطره الحصار للمناداة بحملةِ إنقاذٍ؛ حيث تحرَّكت حملة الإنقاذ من القاهرة بقيادة اللورد ولزلي وعندما عَلِمَت قوات المهدية بهذه الحملة عَمِلَت دون تمكينها مِن الوصول إلَّا حين تحرِّرُ الخرطوم، وفي 25يناير 1885 بدأ أنصارُ المهدي يَعبُرون النيل الأبيض للَّحاقِ بجيش عبد الرحيم النجومي الذي كان يحاصِرُ الخرطوم من جهة الجنوب، وفي صباح يوم 26 يناير تمكَّنت قوات المهدية من دخول الخرطوم عَنوةً وقَتْل غوردون داخِلَ ساحة القصر. وكان لسقوط الخرطومِ ومقتل غوردون صدًى عظيمًا في بريطانيا عمومًا، وفي مجلس العموم خصوصًا."},{"id":4722,"title":"صدور قرار بريطاني بإخلاء الحاميات المصرية من ميناء زيلع الصومالي .","date":["العام الهجري :1302","الشهر القمري : محرم","العام الميلادي :1884"],"text":"قرَّرت بريطانيا إخلاءَ الحاميات المصرية مِن ميناء زيلع الصومالي، وقرَّرت أن تكونَ إدارةُ ساحل الصومال الممتد من \"زيلع\" حتى \"رأس حافون\" تابعةً مباشرة لحكومة الهند الخاضعة لبريطانيا."},{"id":4723,"title":"وفاة محمد أحمد المهدي السوداني .","date":["العام الهجري :1302","الشهر القمري : رمضان","العام الميلادي :1885"],"text":"هو محمد أحمد بن عبد الله، المهدي السوداني الثَّائر، وقائدُ الحركة المهدية ومؤسِّسُها. كان لحركته أثرٌ كبير في حياة السودانِ السياسية. ولِدَ في جزيرةٍ تابعة لدنقلة سنة 1259هـ، من أسرةٍ اشتهر أنها حُسينية النَّسَبِ. وكان أبوه فقيهًا، فتعلَّم منه القراءةَ والكتابة، وحفِظَ القرآنَ وهو في الثانية عشرة من عمره. ومات أبوه وهو صغير، فعَمِلَ مع عمه في نجارةِ السُّفن مدةً قصيرةً، وذهب إلى الخرطوم، فقرأ الفِقهَ والتفسيرَ، وتصوَّفَ وانقطع في جزيرة أبا في النيل الأبيض مدة خمسة عشر عامًا للعبادة والدرسِ والتدريس. وكثُرَ مريدوه، واشتهر بالصلاحِ. وسافر إلى (كردفان) فنشر فيها (رسالة) من تأليفِه يدعو بها إلى تطهيرِ البلاد من مفاسِدِ الحكَّام, وجاءه عبد الله بن محمد التعايشي فبايعه على القيامِ بدعوتِه. وقَوِيَت عصبيَّةُ المهدي بقبيلة (البقَّارة) وقد تزوَّج منها, وتلقَّب سنة 1298هـ (1881 م) بالمهديِّ المنتظر، وكتب إلى فُقهاء السودان يدعوهم لنصرتِه. وانبَثَّ أتباعُه (ويُعرفون بالدراويش أو الأنصار) بين القبائِلِ يحضُّون على الجهادِ. حاولت الحكومةُ المصرية والإنجليزُ القضاءَ عليه وعلى حركتِه، لكِنَّ كثرةَ أتباعِه وحماسَهم لحركتِه التي تسعى لرفعِ الظلم الواقع على السودانيين كلَّف المصريين والإنجليز الكثيرَ من الدماء على رأسِها القائدُ الإنجليزي غوردون، عندما هاجم بعضُ أتباع المهدي (الخرطوم) وفيها غوردون باشا فقتلوه وحملوا رأسَه على حَربةٍ (سنة 1302هـ)، وانقاد السودان كلُّه للمهدي. أرسل إلى الخديوي والسلطان عبد الحميد ومَلِكة إنجلترا يشعِرُهم بدولته ومقر سلطنتِه، وضربَ النقودَ. ولكِنَّه لم يلبث أن مات بالجدري في (أم درمان) وقد أوصى بالخلافة من بعده لعبد الله التعايشي. كان المهدي طويلًا أسمرَ بخضرة، ضَخْمَ الجثة، عظيمَ الهامة، واسِعَ الجبهة، أقنى الأنف، واسعَ الفم والعينين، مستديرَ اللحية، خفيفَ العارِضَينِ، أسنانه كاللؤلؤ، يتعَمَّمُ على قلنسوة من نوعِ ما يتعمَّمُ عليه أهلُ مكة، وعمامتُه كبيرةٌ مُنفَرِجةٌ من الأمام، يُرسِلُ عذبةً منها على مَنكِبِه الأيسر.وكان فطِنًا فصيحًا قويَّ الحجة، إذا خطب خلبَ لُبَّ مَن يستمِعُ إليه."},{"id":4724,"title":"محمد بن سعود ينتصر على عمه الإمام عبد الله بن فيصل .","date":["العام الهجري :1305","العام الميلادي :1887"],"text":"في الوقتِ الذي نجح فيه ابنُ رشيد في بسطِ نفوذِه ليشمَلَ بلادَ الوشم وسدير كان محمدُ بن سعود ينازِعُ عَمَّه الإمامَ عبد الله على الحُكمِ، بحُجَّةِ أنَّه الوريثُ الشرعيُّ لوالِدِه، فدارت بينهما عدةُ معارك انتهت في هذه السنة بتغَلُّبِ أبناء سعود على عَمِّهم عبد الله، ودخلوا الرياض واعتقلوا عمَّهم عبد الله وسَجَنوه."},{"id":4725,"title":"ابن رشيد يبسط نفوذه على الرياض  .","date":["العام الهجري :1305","العام الميلادي :1887"],"text":"كان الإمامُ عبد الله والمعركةُ دائرة بينه وبين ابنِ أخيه محمد بن سعود أرسل إلى محمَّدِ ابن رشيد يستنجِدُ به ويطلب منه القدومَ لنُصرتِه فلبَّى طلَبَه فزحف إلى الرياضِ على رأسِ قوةٍ كبيرةٍ، ففرَّ أبناء سعود إلى الخَرج كعادتِهم عندما يهدِّدُهم الخطر، فدخل ابنُ رشيد الرياض وأخرج عبدَ الله من السجن بعد أن أصيبَ بمرضٍ في سجنِه، ثم عاد إلى حائل ومعه الإمامُ عبد الله، وعيَّنَ على الرياض قائِدَه سالم بن سبهان وتفاوض مع أولادِ سعود أن تبقى لهم الخَرجُ على شرطِ أن لا يعتَدُوا على الرياضِ."},{"id":4726,"title":"إيطاليا تستولي على إرتريا .","date":["العام الهجري :1305","العام الميلادي :1887"],"text":"لما كانت إيطاليا الفاشية مُصَمِّمةً على إقامةِ إمبراطورية استعمارية، فقد قامت بغزو إثيوبيا في 3 تشرين الأول 1935 وأرغمت هيلاسيلاسي على اللجوءِ إلى المنفى في أيار 1936. وضَمَّت إيطاليا إثيوبيا إلى إرتريا التي كانت آنذاك مستعمرةً إيطاليةً، وضمَّت إلى الاثنين الصومال الإيطالي، وكونت من الثلاثة أفريقيا الشرقيةَ الإيطاليةَ."},{"id":4727,"title":"عزل سالم بن سبهان عن حكم الرياض .","date":["العام الهجري :1305","العام الميلادي :1887"],"text":"ضجَّ الناسُ في الرياض من سياسةِ ابنِ سبهان، ومما زاد غضَبَهم عليه قتلُه لأبناءِ سعودٍ الثلاثة: محمد، وعبد الله، وسعد، الأمر الذي أغضب أيضًا آل سعود وابن رشيد، فقام بعزلِه، وعيَّنَ بدلًا عنه فهَّاد بن عبادة بن رخيص."},{"id":4728,"title":"احتلال الصومال وتقسيمه بين ثلاث دول استعمارية .","date":["العام الهجري :1305","العام الميلادي :1887"],"text":"بعد أن احتَلَّت بريطانيا مصرَ أرادت أن تحُلَّ محلَّ القواتِ المصرية في شرقيَّ أفريقيا وانتهزت الحركةَ المهديةَ في السودان ففَصَلت سواحِلَ البحر الأحمر وبلادَ الصومال عن مصرَ، وحَلَّت القواتُ البريطانيةُ محلَّ القوات المصرية في زيلع عام 1302هـ وأمَّا جنوبيُّ الصومالِ فكان مع القواتِ الإيطالية، ولم تكُنْ بريطانيا تريدُ أن تدخُلَ في خلافات مع فرنسا وإيطاليا فاتَّفَقت مع فرنسا عام 1306هـ / 1888م على إنهاء الخلافِ بينهما في مناطِقِ الصومال وسواحلِها، واقتسام النفوذِ في شماليِّ الصومالِ وزنجبار، وشاركتهما في ذلك ألمانيا وإيطاليا، فأخذت بريطانيا القِسمَ الأوسط من شرقي إفريقيا ساحل كينيا وساحل الصومال على خليج عدن (الصومال الإنجليزي)، وأخذت إيطاليا الساحِلَ الشماليَّ مِن شرقي إفريقيا (الصومال الإيطالي)، وأخذت فرنسا جيبوتي (الصومال الفرنسي) وأُعطِيَت الحبشة القسم الغربي من الصومال (الأوغادين) فقُسِّمَت الصومال أبشَعَ تقسيمٍ؛ نكايةً بأهلِه المسلمين"},{"id":4729,"title":"إنزال الغواصة عبد الحميد إلى البحر .","date":["العام الهجري :1305","الشهر القمري : رجب","العام الميلادي :1888"],"text":"أنزلت الدولةُ العثمانية الغوَّاصةَ \"عبد الحميد \" إلى البحرِ، وكان اسمُها \"تحت البحر\" وهي أوَّلُ غوَّاصةٍ تُصنَعُ في المملكة المتَّحِدة، بُدئَ بتصنيعِها في عام 1886م، وتعمَلُ بالطاقة البخارية، وتعتبَرُ من جيل الغوَّاصات التي بُنِيَت في وقتٍ مبكر في إنجلترا، وأدخلتها الدولةُ العثمانية للخِدمةِ ضمن أسطولِها الحربيِّ بعد إجراء تجارِبِ الغَوصِ والارتفاعِ والسير، ثم أُدخِلَت هذه الغواصة \"الطوربيدات\"، وكانت الدولةُ العثمانية من أوائِلِ الدُّوَلِ في تدعيم الغوَّاصاتِ بالطوربيداتِ."},{"id":4730,"title":"معاهدة القسطنطينية .","date":["العام الهجري :1306","الشهر القمري : صفر","العام الميلادي :1888"],"text":"أفلحت الضغوطُ الفرنسيَّةُ في حملِ كلٍّ من ألمانيا والنمسا والمجر وأسبانيا وإيطاليا وهولندا وروسيا والإمبراطورية العثمانية وبريطانيا على توقيعِ معاهدةِ القُسطنطينية في 29 أكتوبر 1888م، والتي تقضي مادتُها الأولى بضمان حريةِ الملاحةِ في قناة السويس واستمرارِها في أوقات الحربِ والسِّلمِ، وكفالتِها لكلِّ سفينةٍ حربية أو تجارية أيًّا كان العَلَمُ الذي ترفعُه، واتِّفاق الأطراف السامية المتعاقِدَة بعدمِ التدخُّلِ بأيِّ شَكلٍ مِن الأشكال لعرقلة الملاحةِ في القناة. واتَّفَقت أطرافُ المعاهدةِ على الامتناعِ عن القيامِ بممارسةِ حقوق الحربِ، أو الدخولِ في أيِّ مواجهاتٍ عسكريةٍ أو أي عملٍ آخَرَ مِن شأنِه تعطيلُ الملاحةِ في القناة، أو المساسُ بسلامةِ مَوانيها، وعدم قيام المتحاربين في أوقات الحربِ باستخدامِ القناة وموانيها في إقلاع أو هبوط القواتِ وشَحنِ أو تفريغِ الذخائِرِ والموادِّ الحربيةِ، والتزام الأطراف السامية المتعاقدة بعدم السماحِ لأيِّ سفُنٍ حربية بالبقاءِ في القناةِ، وخَوَّلت المادتان 9، 10 مصرَ باتخاذ الإجراءاتِ اللازمة لتنفيذِ بنود هذه المعاهدةِ، وتأمين الدفاعِ عن مصر واستقرارِ النِّظام العامِّ فيها. ومع ذلك جاءت المادة 11 لتقرِّرَ بأنَّ هذه الإجراءات يجِبُ ألَّا تخِلَّ بحرية الملاحة في القناةِ، وقضت المعاهدةُ كذلك بأن تعتبر مبدأ المساواة ركنًا أساسيًّا من أركانِها، وبأنَّ الالتزاماتِ الواردةَ فيها لا تقيَّدُ بأجَلِ الالتزامِ الممنوح للشركة العالمية لقناة السويسِ البحريةِ."},{"id":4731,"title":"عبد الرحمن بن فيصل يتولى الحكم في الرياض اسميا .","date":["العام الهجري :1307","العام الميلادي :1889"],"text":"تولى عبدُ الرحمنِ بنُ فيصل حُكمَ الرياض بعد وفاةِ أخيه عبد الله؛ لأنَّ أخاه محمدًا وهو أكبر منه لم يكن له مطمَعٌ في الحُكمِ، وطلب عبد الرحمن من ابنِ رشيد أن يعزِلَ فهَّاد ابن رخيص عن إمارة الرياضِ فقابل ابن رشيد هذا الطَّلَبَ بتحَدٍّ، فعزل ابن رخيص وعيَّنَ ابنَ سبهان العدوَّ اللدودَ لابن سعود."},{"id":4732,"title":"وفاة الإمام عبد الله بن فيصل بن تركي .","date":["العام الهجري :1307","الشهر القمري : ربيع الآخر","العام الميلادي :1889"],"text":"هو الإمامُ عبد الله بن فيصل بن تركي بن عبد الله بن محمد بن سعود بن محمد بن مقرن، ثالث حكَّام الدولة السعودية الثانية، بويع بالرِّياضِ بعد وفاةِ والده سنة 1282هـ وخالفه أخوه سعود، فنشبت بينهما معارِكُ استولى سعودٌ في آخرها سنة 1287هـ على الرياض. وخُلِعَ عبد الله، فلجأ إلى التركِ في الأحساءِ فلم يطمئنُّوا إليه، فابتعد عنهم، وجمع بعضَ القبائِلِ وأعاد الكَرَّة على أخيه سعود. فاقتتلا في وقعةِ الجزعة من أراضي نجد، وفشل عبد الله، فقَصِدَ عتيبة مبتعدًا عن الرياض. ومات سعود سنة 1291 هـ وولِيَ بعدَه أخوهما عبد الرحمن، فزحف إليه عبدُ الله، فنزل له عبد الرحمن عن الإمامةِ. ودخل الرياضَ فكان حُكمُه الثاني من 1291 - 1301 هـ / 1874 - 1884 م، فثار عليه أبناءُ أخيه سعود وهاجموا الرياض، فظَفِروا به وحبسوه فيها. ودبَّت الفوضى، فقَوِيَت شوكة محمد ابن الرَّشِيد صاحِبِ حائل فهاجم الرياض، وفرَّ أبناء سعود إلى الخرج، وأفرج ابنُ رشيد عن عبد الله واصطحبه معه إلى حائل، فأقام عنده إلى سنة 1307هـ، وأذن له ابنُ الرَّشيدِ بالعودة إلى بلَدِه الرياض مع أخيه عبد الرحمن، فلم يستقِرَّ غيرَ يوم واحد ووافته منيَّتُه فيها، فتولى عبد الرحمن بن فيصل الحُكمَ بعده."},{"id":4733,"title":"وفاة الوزير خير الدين باشا التونسي  .","date":["العام الهجري :1307","الشهر القمري : جمادى الآخرة","العام الميلادي :1890"],"text":"هو الوزيرُ المؤرِّخُ خير الدين باشا التونسي، مِن رجال الإصلاحِ السياسيِّ الإسلامي، وهو شركسيُّ الأصل من القوقازي، ولِدَ سنة 1225هـ، قَدِمَ إلى تونس صغيرًا، وقضى بها مُعظَمَ حَياتِه، اتَّصَل بصاحبِها (الباي أحمد) وأثرى وتعلَّم بعض اللغات وتقلَّد مناصِبَ عديدةً عالية آخِرُها منصب رئيسِ الوزراء، وبسَعيِه أُعلِنَ دستور المملكة التونسية سنة 1284 هـ - 1867م، ولكنَّه ظَلَّ حِبرًا على ورق. وفي سنة1294 هـ - 1877م قام بعدة إصلاحاتٍ، وقاوم الحُكمَ الاستبداديَّ، وعَمِلَ على إقامة العدل، وساهم في وضعِ قوانين مجلس الشورى الذي أصبح رئيسًا له سنة 1861م، وأمام ازديادِ فسادِ الوضع السياسي في البلاد نتيجةَ سوءِ تصَرُّف المسؤولين وسَرِقاتهم قدَّم خير الدين استقالتَه من جميع وظائفِه سنة 1862، واستغرقت فترةُ انقطاعه سبع سنوات، انعزل فيها في بستانِه يتأمَّلُ ويكتب، ثم خرج إلى الأستانة وتقَرَّب من السلطان عبد الحميد العثماني، فولاه الصدارةَ العظمى سنة 1295 هـ فحاول إصلاحَ الأمورِ، فأعياه، فاستقال سنة 1296هـ ونُصِب (عضوًا) في مجلس الأعيان، فاستمَرَّ إلى أن توفي بالأستانة. له كتابٌ في سياسة الإصلاحِ مَعروفٌ باسم \"أقوم المسالك في معرفة أحوال الممالك\"."},{"id":4734,"title":"وفاة الأمير العلامة صديق حسن خان القنوجي  .","date":["العام الهجري :1307","الشهر القمري : جمادى الآخرة","العام الميلادي :1890"],"text":"هو الإمامُ العلَّامةُ الأميرُ السيد الشريف المحقِّقُ محيي السنة وقامِعُ البدعة: أبو الطيب محمد صديق بن حسن بن علي بن لطف الله القنوجي البخاري، نزيل بهوبال، ويرجع نَسَبُه إلى زين العابدين بن علي بن الحسين السبط بن علي بن أبي طالب. ولِدَ في بلدة \"بريلي\" موطِنِ جَدِّه من جهةِ الأمِّ، عام 1248هـ ولما بلغ السادسةَ مِن عمره توفِّيَ والدُه، فرحل مع أمِّه إلى قِنَّوج موطِنِ آبائهِ بالهندِ، فنشأ فيها في حجرِ أمِّه يتيمًا فقيرًا على العَفافِ والطهارة، وتلقَّى الدروس في علومٍ شتى على صفوةٍ مِن علماءِ قِنَّوج ونواحيها وغيرهم. درسَ صِدِّيق على شيوخٍ كثيرين من مشايخِ الهند واليمن، واستفاد منهم في علومِ القرآن والحديثِ وغيرهما، ولقد أجازه شيوخٌ كثيرون ذكَرَهم في ثَبتِه \"سلسة العَسْجَد في مشايخ السند\". وله تلاميذ كثيرون درَسوا عليه واستجازوه، وبعد عودتِه مِن الحجازِ إلى الهند انتقل العلامةُ صِدِّيق حسن خان من (قنوج) إلى مدينة (بهوبال) في ولاية (مادهيا براديش) في وسط الهند، وقد ذاع صيتُه في تلك الأيام، كإمام في العلومِ الإسلامية، ومؤلِّفٍ بارع في العلوم العقليَّةِ والنَّقلية، وكاتبٍ قديرٍ في اللغات العربية والفارسية والأوردية، ومجتهدٍ متواصلٍ في الدرس والتأليف والتدوين، ولم يلبَثْ أن تزوَّجَ بأميرة بهوبال (شاهجان بيجوم) التي كانت تحكُمُها حينذاك، تزوَّجَت به لَمَّا عَلِمَت من شَرَفِ نَسَبِه وغزارة عِلمِه واستقامة سيرتِه، سنة 1287هـ، وجعلَتْه مُعتَمِدَ المهامِّ، ومنحته أقطاعًا من الأرضِ الخراجيَّة تغلُّ له خمسين ألف ربيَّة في كلِّ سنة، وخلعت عليه ولقَّبَتْه الدولةُ البريطانيةُ الحاكِمةُ بالهند نواب أمير الملك سيد محمد صديق حسن خان بهادر، ومنحته حَقَّ التعظيم في أرض الهند بطولِها وعرضِها بإطلاقِ المدافِعِ سَبعَ عشرة طلقةً، وخلَعَت عليه بالخِلَعِ الفاخرةِ، ومنَحَه السلطانُ عبد الحميد خان الوسامِ المجيدي من الدرجةِ الثانية. عَمِلَ صديق خان وزيرًا لزوجته الأميرة (شاهجان بيجوم) ونائبًا عنها. كان زواجُ العلَّامة صديق حسن خان بالأميرة شاهجان وتلقُّبه بأمير بهوبال نقطةَ تحوُّلٍ لا في حياتِه العلميَّةِ فقط، بل في النشاطِ العلميِّ والعهد التأليفي في الهند كلِّها، فكان له موهبةٌ فائقةٌ في الكتابة وفي التأليف، حتى قيل إنَّه كان يكتُبُ عَشَرات الصفحاتِ في يوم واحد، ويكمِلُ كتابًا ضخمًا في أيام قليلة، ومنها كتب نادرةٌ على منهج جديد، وعندما ساعدته الظروفُ المَنصبيَّةُ والاقتصادية على بذل المالِ الكثيرِ في طَبعِها وتوزيعِها، تكَلَّلت مساعيه العلمية بنجاحٍ منقطعِ النظير. من مؤلَّفاتِه: فتح البيان في مقاصد القرآن، ونيل المرام من تفسير آيات الأحكام، والدين الخالص (جمع فيه آيات التوحيد الواردة في القرآن، ولم يغادر آيةً منها إلا أتى عليها بالبيان الوافي)، وعون الباري بحَلِّ أدلة البخاري (شرح كتاب التجريد)، والسراج الوهاج في كشف مطالب صحيح مسلم بن الحجَّاج، والحِرز المكنون من لفظ المعصوم المأمون (في الحديث)، والرحمة المهداة إلى من يريد زيادةَ العلمِ على أحاديثِ المِشكاة، والجنة في الأسوة الحسنة بالسنَّة،(في اتباع السنة)، الحِطَّة في ذكر الصحاح الستة، والروضة الندية شرح الدرر البهية للقاضي محمد اليمني الشوكاني، وفتح العلام شرح بلوغ المرام لابن حجر العسقلاني، وحصول المأمول من علم الأصول (تلخيص إرشاد الفحول للشوكاني) (في أصول الفقه)، وقطف الثمر في بيان عقيدة أهل الأثر، وغيرها كثير، قال عبد الحي الطالبي: \"له مصنَّفاتٌ كثيرةٌ ومؤلَّفاتٌ شهيرة في التفسير والحديث، والفقه والأصول، والتاريخ والأدب، قلَّما يتَّفِقُ مثلُها لأحدٍ من العلماء، وكان سريعَ الكتابةِ حُلوَ الخَطِّ، يكتب كراستين في مجلسٍ واحدٍ بخَطٍّ خفيٍّ في ورقٍ عالٍ، ولكنه لا تخلو تأليفاتُه عن أشياءَ، إما تلخيص أو تجريد، أو نقل من لسانٍ إلى لسان آخر، وكان كثيرَ النقل عن القاضي الشوكاني، وابن القيم، وشيخه ابن تيمية الحراني، وأمثالهم، شديدَ التمَسُّك بمختاراتهم، وقد اعتراه مرَضُ الاستسقاء، واشتدَّ به المرضُ وأعياه العلاجُ واعتراه الذهولُ والإغماء، وكانت أناملُه تتحَرَّك كأنَّه مشغول بالكتابة، فلما كان نصفُ الليل فاضت على لسانِه كلمةُ أحِبُّ لقاءَ اللهِ، قالها مرة أو مرتين، وطلب الماءَ واحتُضِرَ، وفاضت نفسه، وكان ذلك في ليلة التاسع والعشرين من جمادى الآخرة سنة 1307هـ، وله من العُمرِ تِسعٌ وخمسون سنة وثلاثة أشهر وستة أيام، وشُيِّعَت جنازته في جمعٍ حاشدٍ، وصلِّيَ عليه ثلاث مرات، و كان قد أوصى بأن يُدفَنَ على طريقةِ السُّنَّة، فنُفِّذَت وصيَّتُه."},{"id":4735,"title":"وفاة القائد الأمير رابح الزبير .","date":["العام الهجري :1307","الشهر القمري : رمضان","العام الميلادي :1890"],"text":"هو الأميرُ رابح بنُ فضل الله أو رابِحُ الزبير، كان زعيمًا سودانيًّا، وُلِدَ في عائلةٍ عربية في حلفاية الملوك، أحدِ ضواحي الخرطوم، كان والدهُ زعيمًا أو مَلِكًا على إحدى القبائل التي استوطَنَت مِنطقةَ بحر الغزال، التحق رابح بجيش \"الزبير\" إلَّا أنه عند بلوغه سن العشرين سافَر رابِحٌ إلى القاهرة، والتحق بجيش الخديوي إسماعيل في مصر، وعَمِلَ في سلاح الفرسان غيرِ النظاميِّين المصري أثناء حملةِ الحبشة، وقد أُصيبَ في تلك الحملة فأُبعِدَ عن الخدمة بالجيشِ، فآثر العودةَ إلى بلادِه، وكان والِدُه قد توفِّيَ قبل عودته، فانضمَّ رابحٌ إلى جيش الزبير، وأصبح في خدمتِه، حتى عُدَّ من كبار معاونيه المقرَّبين له؛ ولشِدَّةِ قُربِه من الزبير كان يسمَّى برابح الزبير وعُرِفَ به أكثر من رابح بن فضل الله، ولَمَّا توفي الزبير تولى رابحٌ قيادة الجيش، وتمكَّن من إقامة مملكةٍ إسلامية في منطقة \"تشاد\"، كانت عاصمتُها مدينة \"ديكوا\" ومات بعد قيام الفرنسيِّين بغزو مملكتِه والدخولِ إلى العاصمةِ \"ديكوا\" وقَتْلِه في المعركةِ."},{"id":4736,"title":"محاولة ابن سبهان التخلص من عبد الرحمن بن فيصل  .","date":["العام الهجري :1307","الشهر القمري : ذي الحجة","العام الميلادي :1890"],"text":"أراد الأميرُ سالمُ بنُ سبهان حاكِمُ الرياض مِن قِبَل ابنِ رشيد التخلُّصِ من عبد الرحمن بن فيصل، فدبَّرَ مؤامرةً لتنفيذها يومَ عيد الأضحى، إلَّا أن عبد الرحمن اكتشَفَها، فلما دخل ابن سبهان القصرَ على عبد الرحمنِ اعتَقَله هو ومن معه، وظل ابن سبهان في السِّجنِ إلى أن أُطلِقَ سَراحُه فيما بعدُ بطَلَبٍ مِن ابن رشيد."},{"id":4737,"title":"حصار ابن رشيد للرياض  .","date":["العام الهجري :1308","العام الميلادي :1890"],"text":"حاول عبدُ الرحمن بنُ فيصل أن يستعيدَ سُلطتَه على مناطِقِ القصيم، فاستنجد بأهالي القصيمِ ضِدَّ محمد ابن رشيد الذي لم يمهِلْ هذا الحِلفَ حتى ينضجَ، فجَرَّد حملةً عسكرية قويةً مِن البدو والحضر، واتجه لمحاصرة الرياضِ لإنهاء حُكمِ آل سعود، وانتهى الحصارُ بعد 40 يومًا بصُلحٍ حَضَره من قِبَلِ عبد الرحمن أخوه محمد، والشيخ عبد الله بن عبد اللطيف آل الشيخ قاضي الرياض، وحضر المفاوضاتِ الأميرُ عبد العزيز بن عبد الرحمن، وكان عمرُه لا يتجاوز 10 سنوات، ومن أهم بنود الصلح: فكُّ ابن رشيد حصارَه للرياضِ، والرحيل إلى حائل, وأن تكون السلطةُ الفِعليَّةُ في الرياضِ لآل سعود دون تدخُّلِ ابنِ رشيد، وإطلاقِ سَراحِ سالم بن سبهان من السِّجنِ."},{"id":4738,"title":"معركة المليداء بين ابن رشيد وأهل القصيم .","date":["العام الهجري :1308","الشهر القمري : جمادى الأولى","العام الميلادي :1891"],"text":"قرَّر محمَّدُ ابن رشيد أن يصفِّيَ حساباتِه مع أهل بُرَيدة بعد فَشَل فتح الرياض، فأعَدَّ حملةً مِن عُربان شمر وحرب، والتقى بقواتِ القصيم في مكانٍ يدعى القرعا، وانتصر عليه أهلُ القصيم فاحتال عليهم وانسحب إلى سهلية، فلما لحق به أهلُ القصيمِ انقَضَّ عليهم وهزمهم وقَتَل منهم 1000 رجلٍ، وكان عبد الرحمن بن فيصل قد جهَّز جيشًا لمساعدة مؤيِّديه من أهل القصيم إلَّا أنه وصله خبَرُ هزيمتهم قبل أن يصِلَ إليهم، فرجع إلى الرياض وقرَّر الخروج منها لمعرفته بالنتيجةِ الحتميَّةِ أنَّ ابنَ رشيد لن يتأخَّرَ عن دخولِ الرياضِ والسيطرة عليها، فخرج بعائلته إلى الصحراء الشرقية قُربَ الأحساء, وعُرِفَت هذه المعركة بمعركة المليداء، وهي من أكبر المعارك التي مكَّنَت لابن رشيد من بَسطِ سيطرتِه على نجدٍ، ومهَّدَت لانهيارِ الدولة السعودية الثانية تمامًا."},{"id":4739,"title":"سقوط مسقط وعُمان في يد الإنجليز .","date":["العام الهجري :1309","العام الميلادي :1891"],"text":"استمَرَّت السيطرةُ البرتغاليَّةُ في عمان منذ بدايةِ القرنِ السادسَ عشَرَ وحتى عام 1060هـ /1650م حين استطاعت أسرةُ اليعاربةِ تحريرَ أرضِ عمان بطردِ البرتغاليِّين مِن معاقِلِهم في مسقط ومطرح، وكان ذلك التحريرُ ثمرةَ الكفاحِ والإرادةِ العُمانية التي استثمرت تنافُسَ وصراعَ الإنجليز والهولنديِّين مع البرتغاليين؛ لتخرُجَ منه في المنتَصَف الأوَّلِ من القرن السابع عشر أقوى قوَّةٍ بحرية محليَّةٍ في غَربِ المحيط الهندي، قادرةً على إنهاءِ السيطرةِ البرتغالية. وكانت إنجلترا قد برزت منذ أواخِرِ القَرنِ السادس عشر كقُوَّةٍ بحرية ضاربةٍ بين القوى الأوروبية، وراحت تفَتِّشُ عن سبيل الوصول إلى مناهلِ الثراء الشرقية، وكسر الاحتكار البرتغالي، فكانت (إدوارد بانوتي) أول سفينة إنجليزية قامت بزيارة زنجبار عام 1000هـ /1591م وظهرت نتائِجُ زياراتها بعد تسعِ سنوات، حين تشكَّلَت شركةُ الهند الشرقية الإنجليزية التي تأسَّسَت بموجِبِ مَرسومٍ مَلكيٍّ صدر في 1009هـ /1600م والتي اقترن بها نشاطُ إنجلترا التجاري والبحري فيما بعدُ. بدأت شركة الهندِ الشرقية تمارِسُ نشاطاتِها بدُخولِ مَنطقةِ الخليج العربي، وكان هدفُها من دخولها لهذه المنطقةِ بيعَ الأصواف الإنجليزية في إيران مقابِلَ الحصول على الحريرِ، وبذلك التقت مصالحُ كُلٍّ مِن إنجلترا والفُرسِ لمهاجمة العدو البرتغاليِّ المشتركِ، وقد بلغ الخطَرُ الإنجليزي الفارسي على مركزِ الهُجومِ المشترك الذي شَنَّه الإنجليز والفرس على هرمز، كذلك تعاون الإنجليز مع الهولنديين لإزاحة منافسةِ البرتغاليَّة، فنجح أسطولٌ إنجليزي هولندي مؤلَّفٌ مِن ثماني سفن في دَحْرِ الأسطول البرتغالي بالقُربِ مِن هرمز في عام 1035هـ /1625م."},{"id":4740,"title":"معركة حريملاء ونهاية الدولة السعودية الثانية .","date":["العام الهجري :1309","العام الميلادي :1891"],"text":"بعد معركة المليداء سنة 1308 أخذ الإمامُ عبد الرحمن ما أمكَنَه أخذُه من ممتلكاتِه في الرياض، وخرج بأسرتِه منها، واتَّجَه إلى المناطق الواقعة بين واحة يبرين والأحساء، لبُعدِها عن متناولِ ابن رشيد، ولوجودِ قبائل متعاطِفة معه، ومناوِئة لخَصمِه ابن رشيد، مِثلُ العجمان وآل مرة، ولكِنَّ صعوبة حياة الصحراء على نِساءِ أُسرتِه وأطفاله أجبَرَت الإمامَ عبد الرحمن على إرسالِ ابنه عبد العزيز إلى الشيخ عيسى بن خليفة حاكِمِ البحرين طالبًا منه أن يقبَلَ إقامةَ أسرته لديه، ورحَّبَ الشيخُ عيسى بالطلب، فذهب أطفالُ الإمام ونساؤه إلى البحرين، ليلقَوا كرم الضيافة هناك. حاول عبدُ الرحمن أن يستعيدَ الرياض, فجمع أنصارَه من أعراب البادية، وصَحِبَه إبراهيم بن مهنا أبا الخيل، أميرُ بُرَيدة مع عددٍ مِن أهلِها, وهاجم الإمامُ عبد الرحمن مع أتباعِه بلدةَ الدلم واستولوا عليها وطَرَدوا من كان فيها من أتباعِ محمد بن رشيد. ثم توجَّه إلى الرياض، ودخلها سنة 1309ه،ـ ومن الرياضِ سار الإمام عبد الرحمن إلى المحمل، ونزل في حريملاء شمالَ الرياضِ والتقى بابن رشيد في معركةٍ فاصلة انهزم فيها عبد الرحمن وقُتِلَ عدد من رجالِه وأنصاره، ودخل ابنُ رشيد الرياض، وبعد هذه المعركةِ تبَدَّدت آمال عبد الرحمن بن فيصل، وعاد إلى مخيَّمِه في البادية، وكانت وقعةُ حريملاء آخِرَ معارك أئمَّةِ الدولة السعودية الثانية، وبها انتهت دولةُ آل سعود في مرحلتِها الثانيةِ."},{"id":4741,"title":"انتقال عبد الرحمن بن فيصل إلى الكويت .","date":["العام الهجري :1309","العام الميلادي :1891"],"text":"بعد مَعركةِ حُريملاء انتقل عبد الرحمن بن فيصل مع أسرتِه إلى يبرين في الأحساء ومنها إلى البحرين، حتى وصلوا إلى الكويت واستقروا بها حيث خصص لهم راتباً شهرياً قدره ستون ليرة عثمانية وظَلَّ فيها عشر سنوات حتى استطاع ابنُه عبد العزيز أن يستعيدَ الرِّياضَ مِن آلِ رشيد سنة 1319هـ / 1902م."},{"id":4742,"title":"وفاة الخديوي توفيق بن إسماعيل والي مصر .","date":["العام الهجري :1309","الشهر القمري : رجب","العام الميلادي :1892"],"text":"هو الخديوي محمد توفيق بن إسماعيل بن إبراهيم بن محمد علي باشا، حاكِمُ مصرَ والسودان، وحفيدُ محمد علي باشا، وكان قد تسلَّم الحُكمَ سنة 1296هـ - 1879م، بعد أن أجبَرَ الإنجليز والفرنسيون أباه الخديوي إسماعيل على تَركِ مَنصِبِه، وذلك عندما حاول استدراكَ ما فاته، وبعد أن أغرق البلادَ في ديونٍ أجنبيةٍ ضَخمةٍ مَهَّدت السبيلَ للأوروبيِّين التدخُّلَ في شئون البلاد، حاول إسماعيلُ التصَدِّيَ للنفوذ الأجنبي، فأجبروه على تركِ مَنصِبِه لأكبر أبنائه توفيق. منذ تولِّي توفيق الحُكمَ عَلِمَ أن بقاءَه مرهون برضا الأجانبِ عليه خاصةً إنجلترا وفرنسا، وعَلِمَ السلطان عبد الحميد الثاني ذلك منه، فحاول تضييقَ سُلُطاتِه والمزايا التي كانت ممنوحةً لأبيه إسماعيل مِن قَبلُ، ولكنَّ إنجلترا وفرنسا أفشَلَتا خطة السلطان عبد الحميد، ليس عطفًا على الخديوي توفيق، ولكِنْ منعًا لزيادةِ نفوذ عبد الحميد الذي سيعَطِّل مشروعات الأجانب في احتلالِ مصر. وقد وقَعَت عِدَّةُ أحداث خطيرة في عهد الخديوي توفيق نتيجةَ اتِّباعه لسياسة الولاءِ الكامِلِ للإنجليز والاستبدادِ المُطلَق على المصريِّين، فصار بذلك أسوأَ الحُكَّام في تاريخِ مِصرَ الحديثِ؛ حيث أدَّت هذه السياسة لاستقالةِ الوزارة الوطنية التي يمثِّلُها «شريف باشا» وتعيين وزارة موالية للإنجليز برئاسة النصراني الأرمني «نوبار باشا» ثم َّنصرانيٍّ آخر، وهذه الوزارةُ الموالية للأجانب عَمِلَت على زيادة التدخُّل الأجنبي في البلادِ تحت ستار سدادِ الديون، وأقدَمَت وزارةُ رياض باشا على بيعِ حِصَّة مصر في قناة السويس لإنجلترا. أثارت هذه السياسةُ نِقمةَ الشَّعبِ والجيش، وعَمَد رياض باشا ووزيرُ حربيته عثمان رفقي على تأخيرِ ترقيةِ الضبَّاط الوطنيين وكُلُّهم مُسلمون، وبدا أنَّه مخَطَّط خارجي لإضعافِ الجيشِ المصري، فقامت ثورةُ أحمد عرابي الشهيرة سنة 1298هـ -1881م، وعَزَلت وزارة رياض باشا، ووقعت أحداثٌ خطيرة قام الإنجليزُ بتدبيرها لاستثارة الوطنيين خاصَّةً أحمد عرابي الذي أصبح وزيرًا للحربيَّة في الوزارة الجديدة، وحاول رئيسُ الوزارة شريف باشا إقناعَ أحمد عرابي أن إنجلترا وفرنسا تستدرجُ مِصرَ للصدام؛ ليكون ذلك مبررًا لاحتلالِ البلَدِ، فلم يُفلِحْ فاستقال، ولم يفهَمْ عُرابي ما يخطِّطُ له الإنجليزُ، وأقدم على استثارة إنجلترا بتقويةِ دفاعات الإسكندريَّةِ، فقَصَفت إنجلترا ميناءَ الإسكندرية والمدينة، وأعلن الخديوي عزلَ عرابي، فخلع عرابي طاعَتَه، واستثار الشعبَ المصريَّ للدفاع عن البلاد، ولكَنَّه هُزِمَ في معركة التل الكبير سنة 1299هـ - 1882م، ووقعت مِصرُ أسيرةَ الاحتلال الإنجليزي. وقد توفِّيَ الخديوي توفيق في 6 رجب سنة 1309هـ - 8 يناير 1892م."},{"id":4743,"title":"قيام أول مجمع لغوي في العالم العربي .","date":["العام الهجري :1309","الشهر القمري : شوال","العام الميلادي :1892"],"text":"قام أوَّلُ مَجمَعٍ لُغويٍّ في العالَم العربي، واتَّخَذَ من قصر \"محمد توفيق البكري\" بمصرَ مقرًّا له، وقد ضَمَّ هذا المجمَعَ أعيانَ اللغة، وغيرَهم، مثلُ: محمد توفيق البكري، ومحمد عبده، والشنقيطي، وحفني ناصف، وحمزة فتح الله، والمويلحي. ولم يستمِرَّ هذا المجمع لمدةٍ طويلة؛ فقد أُسدلَ الستار عليه بعد شهورٍ قليلة."},{"id":4744,"title":"الملك عبد العزيز بن عبد الرحمن في الكويت .","date":["العام الهجري :1310","العام الميلادي :1892"],"text":"بعد سُقوطِ الدَّولةِ السعودية الثانية في نجدٍ، تنقَّل عبد العزيز وهو في العاشرةِ مِن عُمُرِه مع أسرة أبيه من الرياضِ إلى شمالِ الربع الخالي حول يبرين، ثم البحرين، ومنها إلى الكويت، فقد وصلها مع نساءِ أُسرتِهم قبلَ وصول والِدِه، ونزلوا في دارٍ مؤلَّفٍ مِن ثلاث غرف أعدَّها لهم مبارك الصباح، وشهد عبد العزيز مع حداثةِ سِنِّه حادثةَ اغتيال مبارك الصباح -بمشاركة أحد أبنائه له- شيخ الكويت وأميرها أخوه الأكبر محمد الصباح، وكذلك قُتِل الأخ الأصغر جراح، ليستولي مبارك على إمارة الكويت وذلك عام 1313ه. فكانت الكويت مدرسَتَه التي تلقَّى فيها فنَّ السياسة العملية، وكانت أيامَ الشيخ مبارك الصباح المليئة بالمناوراتِ والمحاوراتِ تنطَبِعُ مقَدِّماتُها ونتائِجُها في ذهنه، وحين آنَسَ فيه مبارك صفاتِ الألمعي اللَّبِق، قَرَّبه منه، وفسح له المجالَ لحُضورِ مجالسه والاستمتاع إلى أحاديثِه مع ممثِّلي الحكومات الإنجليزية والروسية والألمانية والتركية، وظَلَّ عبد العزيز في الكويت تراوِدُه أحلام عودة أمجاد آبائه وأجداده في نجدٍ، حتى تحقَّق حِلمُه عندما تمكَّنَ مِن استعادة الرياض مِن ابن رشيد سنة 1319ه."},{"id":4745,"title":"تولي مبارك الصباح إمارة الكويت .","date":["العام الهجري :1313","العام الميلادي :1895"],"text":"عندما ثار الأخُ الأوسَطُ مبارك بن صباح الصباح على أخيه الأكبر الشيخِ محمد أمير الكويتِ وقَتَله وقَتَل معه الأخَ الأصغَرَ جراحًا في ليلة واحدةٍ، تولى بعدها الشيخُ مبارك الصباح سُدَّة الإمارة في الكويتِ، وقيل: إنَّ الشيخ خزعل حاكِمَ المحمرة عاصِمةِ الأحواز كان له دورٌ في تشجيعِ مبارك على تصفية أخويه ليتفَرَّدَ بإمارةِ الكويتِ!"},{"id":4746,"title":"وفاةُ ناصر الدين شاه ملك فارس وتولي مظفر الدين شاه  .","date":["العام الهجري :1313","الشهر القمري : ذي الحجة","العام الميلادي :1896"],"text":"هو مَلِكُ فارس ناصر الدين شاه بن محمد ميرزا القاجار، الحاكِمُ الرابع في أسرة القاجار الشيعية في فارس. وُلِدَ في 6 صفر 1247 هـ/ 17 يوليو 1831 في قرية كُهنَمار بالقرب من تبريز، وكان أبوه محمد ميرزا وأمُّه ملك جهان خانم المعروفة بمهد العليا. حكَمَ فارس من 1848م، ولم يكُنْ وصولُ ناصر الدين للعرش إلَّا بمساعدة القنصل البريطاني في تبريز، وفي عهدِه تمَّ قَمعُ الحركة البابية وقتل الباب. بحَثَ ناصر الدين عن المجدِ العسكري فاستولى على هيرات، ولكِنَّ القواتِ الهنديةَ البريطانيةَ أجبَرَته على الانسحابِ، وفى الشطرِ الثاني من حُكمِه ألغى الصدارةَ العظمى (رياسة الوزراء) وتولَّاها هو بنفسِه، وبدأ حركةَ إصلاحٍ وتحديثٍ، كما قام برحلاتٍ إلى أوربا سجَّلها في يوميات تبَيِّن مدى إعجابه بالحضارة الأوربية، وأدَّى ازدياد النفوذ الأجنبي -خاصة البريطاني- في فارس إلى اضطراباتٍ شعبيَّةٍ أدَّت إلى اغتيالِه في 18 ذو القعدة 1313 هـ الموافق أول مايو 1896 داخِلَ مزار الشاه عبد العظيم. قُتِلَ ناصر الدين شاه بعد أن حكَمَ نصف قرن تقريبًا، وتولى بعده مظفر الدين شاه الذي تولى الأمورَ في الثامِنِ من حزيران سنة 1896م يعني بعد شهرٍ وعدة أيام من موتِ ناصر شاه."},{"id":4747,"title":"معركة فركة في السودان بين المهديين والجيش المصري .","date":["العام الهجري :1313","الشهر القمري : ذي الحجة","العام الميلادي :1896"],"text":"قامت الحركةُ المهديَّةُ بالسودان وسيطَرَت على جميع أجزائِها ما عدا دارفور، واضطرَّ الإنجليز للانسحابِ من البلاد ومعهم انسحب الجيشُ المصري تحت ضغطٍ شديدٍ من إنجلترا، وذلك سنة 1302هـ، وبعد ذلك بعامٍ واحد توفِّيَ زعيم الحركة « محمد المهدي» وجاءت على البلادِ سنواتٌ عجافٌ، وأخذت إنجلترا تخطِّطُ للعودة إلى السودان، وأخذت في تشكيل جيشٍ مصري تحت قياداتٍ إنجليزيةٍ؛ من أجل تنفيذِ هذا الغرض، وتقدم هذا الجيشُ بأمرٍ مباشرٍ مِن المندوب السامي الإنجليزي دون علمِ الحكومة المصرية، فلما عَلِمَ الخديوي «عباس حلمي» بالخبر غَضِبَ بشدةٍ، ولكنه استسلم للأمرِ الواقع في النهاية. قاد الجنرال «كتشنر» وهو ضابط إنجليزي من سلاحِ المهندسين جيشًا قوامُه عشرة آلاف مقاتل في أكمَلِ سلاح وأتمِّ استعداد، وتجمَّع الجيش في وادي حلفا وتحرَّك في اتجاه أرض السودان، وذلك في ذي القعدة سنة 1313هـ. وفي يوم 26 من ذي الحجة 1313هـ وقعت معركةُ «فركة» بين الجيش المصري الكبير وجيش الحركة المهدية الملقَّب بالأنصار، فقُتِلَ ثمانمائة مقاتل من بينهم قائدُ الجيش «حمودة» وجُرِحَ خمسمائة، وأُسِرَ ستمائة، وانسحب بقيةُ الجيشِ نحو «دنقلة»، وكانت هذه المعركة فاتحةَ انهيار الحركة المهدية وبدايةَ النهايةِ لحُكمِهم السودانَ."},{"id":4748,"title":"ظهور كتاب الدولة اليهودية لهيرتزل .","date":["العام الهجري :1314","العام الميلادي :1896"],"text":"المؤسِّسُ الحقيقي للصهيونية اليهوديَّة السياسية هو (تيودور هرتزل) 1860-1904م، الذي كان منهجُه يكمُنُ في توظيف اليهودِ لحلِّ مشاكل الغرب والنَّظَر إلى المسألة اليهودية كمُشكلةٍ سياسيةٍ دوليةٍ غربيةٍ تجتَمِعُ كُلُّ الأمم المتحضِّرة (أي الغربية) لمناقشتِها وإيجاد حلٍّ لها، لكن ذلك سيتمُّ بمراقبة الرأي العام الغربي، وبمعاونة صادقةٍ مِن الحكومات المعنيَّة. دعا هرتزل إلى هجرةٍ يهودية عَلَنية بمساعدة دولة أوروبيَّة كبرى معتَمِدًا على فقراء اليهود الذين يشكِّلون قوةً عاملةً رخيصةً، ومُشجِّعًا البرجوازية اليهودية على الهجرة؛ لأنَّها ستجد في الوطن الجديد مجالًا لممارسةِ حرِّيتِها بعيدةً عن منافسة البرجوازية الأوروبية. ويُعتَبَرُ كتاب هرتزل دولة اليهود الذي صدر سنة 1896م ذا أثرٍ كبيرٍ في تشكُّل الحركة الصهيونية الحديثة وتطورها، وقبل أن يَنشُرَ كتابُه قام بنشاطٍ فعَّال التقى خلالَه شخصياتٍ يهوديةً ثريَّةً بحث معها مشروعَ الدولة اليهودية، مثل: المليونير الشهير (البارون هيرش)، كما التقى مع عدد من القادة البريطانيين الصهيونيين في لندن سنة 1895م، منهم (صموئيل منونتامو) الثري اليهودي، والنائب في مجلس العُموم عن حزب الأحرار، ودوَّن إثرَ لقائِه معه بعضَ الأفكار المتعلِّقة بفلسطين الكبرى بدَلَ القديمة. وحاول مرارًا الاتصالَ بالسلطان العثماني لحثِّه على منحِ اليهودِ فلسطينَ."},{"id":4749,"title":"إنشاء مكتبة الجامع الأزهر الشريف  .","date":["العام الهجري :1314","العام الميلادي :1896"],"text":"كان لكلِّ رواقٍ في الأزهر مكتبةٌ خاصةٌ به، وكان بعضُ أهل الخير يَقِفون الكتُبَ فيها، ولكنها لم تكُنْ خاضِعةً لأيِّ نظامٍ، وكانت معظمُ الكتب في النحو، فاقترح الشيخُ محمد عبده عضوُ مجلس إدارة الأزهر في حينِها من ضِمنِ إصلاحاتِه أن يكون للأزهرِ مَكتبةٌ خاصَّةٌ متكامِلةٌ منظَّمةٌ، تجمَعُ شَتاتَ الكُتُبِ المتفَرِّقة في الأروقة التي ذهب كثيرٌ منها إلى أوربا عن طريقِ سماسرة الكتُبِ ومَن لا أمانة له من الذين كانوا يبيعون المخطوطاتِ، بل إنَّ بعض المكتبات التابعة للأزهر كانت في الحارات وبعضُها في الحوانيت، فتقَدَّم بفكرة المكتبة إلى مجلسِ إدارة الأزهرِ، فنالت القبولَ من أعضائه واختير المكانُ المناسب، وكُتِبَ لديوان الأوقاف الذي يتولى الإشرافَ على شؤون الأزهرِ، ثم نُفِّذَت الفكرةُ فعلًا في شعبان مِن هذا العام ولاقت في البدايةِ صُعوبةً في إقناع أهل الأروقةِ بفائدةِ المكتبة العامَّةِ وضَمِّ مكتباتِهم إليها، كما وُجِدَت صعوبات في ترميمِ الكتب، ولم يُكتَفَ بما جُمِعَ من الأروقة بل دُعِيَ العلماءُ والعظماء للمشاركة في تكوين المكتبة، فوَهَب بعضُ المشايخ مكتباتِهم الخاصةَ لها، مثل الشيخ حسونة النواوي رئيس مجلس إدارة الأزهر، وورثة سليمان باشا أباظة بمكتبةِ والِدِهم، وهي من أنفَسِ المكتبات الخاصة، وتشغَلُ المكتبة الأزهرية الآن ثلاثةَ أمكِنَة؛ اثنان منها داخِلَ الأزهر، وهما المدرسة الأقبغاوية، والمدرسة الطيبرسية، والثالث خارج الأزهر ملاصِق له وهو الطابِقُ الثاني من بناء أنشأته مشيخةُ الجامع الأزهر سنة 1936م كمُلحَق للإدارة العامة المجاورة للأزهرِ، وعدد الكتب التي بدأت بها المكتبة سنة 1897م هو 7703 كتابًا في سبعة وعشرين فنًّا، وبلغت سنة 1943م ثمانية وخمسين فنًّا وعدد الكتب 90075 مجلدًا، وفيها أكثر من اثنتي عشرة مكتبة خاصة، وتختَصُّ المكتبة بكثرة المخطوطات التي بلغت سنة 1943م 24000 مجلدٍ مخطوطٍ."},{"id":4750,"title":"وفاة جمال الدين الأفغاني .","date":["العام الهجري :1314","الشهر القمري : شوال","العام الميلادي :1897"],"text":"هو محمد جمال الدين بن صفدر -وتكتب صفتر- الحسيني الأفغاني الأسد آبادي، كان فيلسوفًا سياسيًّا، وكاتبًا وخطيبًا وصحفيًّا، ولد في شعبان 1254هـ / أكتوبر 1838م بأسد آباد بالقربِ من همذان من أعمال فارس، وقيل إنه ولد بأسد آباد الأفغانية؛ ولذا اختُلِفَ في أصل نسب أسرتِه، هل هو فارسي إيراني أم أفغاني, وقيل إنه من أسرة أفغانية عريقة ينتهي نسَبُها إلى الحسين بن علي رضي الله عنه, نشأ الأفغاني في كابول عاصمة الأفغان. وتعلَّم فيها بدايةَ تلقيه العلمَ اللغتينِ العربيةَ والفارسية، ودرَس القرآن وشيئًا من العلومِ الإسلامية، وفي سِنِّ الثامنة لفت أنظارَ من حوله بذكائه الشديد، مما جعل والِدَه يحفِّزُه إلى التعلم، وفي أوائل سنة 1266هـ / 1849م وقد بلغ الثانية عشرة من عمره انتقل به والده إلى طهران، وفي طهران سأل جمال الدين عن أكبَرِ علمائها في ذلك الوقت، فقيل له: إنه \"أقاسيد صادق\" فتوجَّه مباشرةً إلى مجلسه، ودار حوارٌ بينهما في مسألةٍ علميةٍ، فأُعجِبَ الشيخ من علمه وجرأتِه مع صِغَرِ سنه، فأقبل عليه وضمَّه إلى صدره وقبَّلَه، ثم أرسَلَ إلى والده يستدعيه، وأمره أن يشتريَ له عباءةً وعمامة، ثم قام الشيخُ بلَفِّ العمامة ووضَعَها بيده فوقَ رأسه تكريمًا له، واعتزازًا بعلمِه. ثم ترك جمال الدين طهران، وسافر مع والدِه -إلى مركز الشيعية العلمي- في النَّجفِ بالعراق في نفس العام، ومكث فيها أربعَ سنوات درس فيها العلومَ الإسلامية وغيرها؛ فدرس التفسير والحديث، والفلسفة والمنطق وعلم الكلام، وأصول الفقه، والرياضة، والطب والتشريح، والنجوم. وقرأ في اللغةِ والأدبِ، والتاريخ والتصوف، والشريعة، وظهر حُبُّه الشديد للمناقشة في المسائل الدينية، أتقن الأفغانيُّ الحديث باللغة العربية والأفغانية والفارسية والسنسكريتية والتركية، وتعلم الفرنسية والإنجليزية والروسية، وإذا تكَلَّم بالعربية فلغتُه فصحى، وهو واسِعُ الاطِّلاع على العلومِ القديمة والحديثة، كريمُ الأخلاقِ كبيرُ العقل، وعندما بلغ الثامنة عشرة أتمَّ دراستَه للعلوم، وظلَّ الأفغاني طوال حياته حريصًا على العلمِ والتعلُّم، وبرزت فيه هوايةُ التَّرحالِ والأسفار. فسافر إلى الهندِ لدراسة بعض العلوم العصرية، ثم عاد إلى أفغانستان. كان الأفغانيُّ يُظهِرُ في عمله السياسي مناهَضةَ استبداد الحكَّام ومناوأة الاستعمار عمومًا والإنجليزيِّ خصوصًا في كلِّ مكانٍ ينزِلُ فيه. حينما وقع خلافٌ بين الأمراء الأفغان انحاز جمال الدين إلى محمد أعظم خان الذي كان له بمثابةِ وزيرِ دولة، وحدث صدامٌ بين جمال الدين وبين الإنجليز، فرحل عن أفغانستان أو طرَدَه الإنجليزُ منها سنة 1285ه ـ/ 1868م، ومر بالهندِ في طريقِه فكان الإنجليز يمنعون العُلَماءَ وطلبة العلم الجلوسَ معه، فخرج منها إلى مصر حيث أقام بها مدةً قصيرة تردَّد في أثنائها على الأزهرِ، وكان بيته مزارًا لكثيرٍ مِن الطلاب والدارسين خاصةً السوريين. ثم دعاه السُّلطانُ العثماني عبد العزيز إلى زيارةِ الدولة العثمانية فأجاب الدعوة، وسافر إلى الأستانة في عهدِ الصدر عالي باشا، فعَظُم أمرُه بها، وذاعت شهرتُه وارتفعت منزلته، ثم عُيِّن جمالُ الدين وهو في الأستانة عضوًا في مجلس المعارِفِ الأعلى، وهناك لقِيَ معارضة وهجومًا من بعضِ علماء الأستانة وخطباءِ المساجد الذين لم يرُقْهم كثير من آرائِه وأقواله، وخاصة من شيخِ الإسلام حسين فهمي أفندي، فطُلب من الأفغاني أن يرحَلَ، فخرج من الأستانة عائدًا إلى مصر، فأقام فيها بضعَ سنوات خاض فيها غِمارَ السياسة المصرية، ودعا المصريِّين إلى ضرورةِ تنظيم أمورِ الحُكمِ، وتأثَّرَ به في مصر عددٌ من رموز الحركة الأدبيَّةِ والسياسية، منهم: محمد عبده، ومحمود سامي البارودي، وغيرهما، فقد أُعجِبوا بفكره وجرأتِه في مناهضة الاستبداد والاستعمار، ويُذكرُ أن للأفغان دورًا في إعطاء دفعةٍ قويةٍ للنَّهضةِ الأدبيَّةِ الحديثة بمصر، فلمَّا تولى الخديوي توفيق باشا حُكمَ البلاد أمَرَ بإخراجه مِن مِصرَ، فأُخرِجَ بطريقة عنيفةٍ بأمرٍ مِن الخديوي بعد أن أقام في مِصرَ نحوَ ثماني سنوات. انتقل إلى الهند سنة 1296هـ / 1879م، ثمَّ طُرِدَ من الهند بأمرٍ مِن الإنجليز، فاتَّجَه إلى أوروبا واختار أن يبدأ بلندن، ومنها انتَقَل إلى باريس، فشرع في تعلُّم الفرنسية فيها، وبذل كثيرًا من الجُهدِ والتصميمِ حتى خطا خطواتٍ جيدةً في تعلُّمِها، ثم اتصل بتلميذِه الشيخ محمد عبده المنفيِّ حينَها في بيروت، ودعاه إلى الحُضورِ إلى باريس، وأصدرا معًا جريدة \"العُروة الوثقى\"، ولكِنَّها ما لَبِثَت أن توقَّفَت عن الصدور بعد أن أُوصِدَت أمامَها أبوابُ كُلٍّ مِن مصر والسودان والهند، بأمرٍ مِن الحكومةِ الإنجليزيةِ, ثمَّ دعاه شاه إيران \"ناصر الدين\" للحُضورِ إلى طهران، واحتفى به وقَرَّبه، وهناك نال الأفغانيُّ تقدير الإيرانيين وحَظِيَ بحُبِّهم، ومالوا إلى تعاليمِه وأفكارِه، ثمَّ ذهب إلى روسيا فأقام فيها ثلاثَ سنواتٍ تنَقَّل بين موسكو وعاصمتِها بطرسبرج آنذاك، وزار كييف، والتقى بقيصرِها ألكسندر الثالث، ثمَّ أمر القيصَرُ بطَردِه من روسيا، فعاد مرةً أخرى لإيران بطلَبٍ من الشاه ناصر الدين، ثم انقَلَب عليه فطَرَده من إيران، فرحل إلى البصرة، ومنها إلى لندن للمرَّة الثانية؛ حيث اتخذ من جريدة \"ضياء الخافقين\" منبرًا للهُجومِ على الشاه ناصر الدين، وكشف ما آلت إليه أحوالُ إيران في عَهدِه، انتظم جمالُ الدين في سِلكِ الماسونيَّةِ بطَلبٍ منه؛ زعم أنَّ ذلك يُفسِحُ له المجالَ أمامَ أعماله السياسيَّةِ، وقد انتُخِبَ رئيسًا لمحفل \"كوكب الشرق\" سنة 1295هـ / 1878م، وقيل إنه استقال منه فيما بعدُ. يُعتَبَرُ الأفغانيُّ في نظرِ مُريديه وطنيًّا كبيرًا، بينما يَنظُرُ إليه خصومُه على أنَّه مهَيِّجٌ خطير، فقد كان له أثَرٌ كبير في الحركاتِ الحُرَّة والحركات الدستورية التي قامت في الدُّوَلِ العربية والإسلامية، وكان يَرمي من إثارة الخواطِرِ إلى تحريرِ هذه الدُّوَلِ من النفوذ الأوربي واستغلالِ الأوروبيِّين، ثم بعد ذلك النهوض بها نهوضًا ذاتيًّا من الداخل متوسِّلًا في ذلك بإدخالِ النظُمِ الحُرَّة إليها، كما كان يهدفُ إلى جمع كَلِمةِ الدول الإسلامية بما فيها فارس الشيعيَّة تحت راية خلافةٍ واحدةٍ، وإقامةِ إمبراطوريةٍ إسلاميةٍ قويةٍ تستطيعُ الوقوفَ في وجهِ التدَخُّلِ الأوربي؛ ولذلك دعاه السلطانُ عبد الحميد الثاني في عهدِه وقَرَّبه إليه وتعاون معه في تسويقِ فكرة الجامعة الإسلامية، ثم انقلب عليه السلطانُ عبد الحميد الثاني لَمَّا شك في علاقتِه بالإنجليز. لم يُكثِرِ الأفغاني من التصنيف اعتمادًا على ما كان يبُثُّه في نفوس العاملين، وانصرافًا إلى الدعوة بالسِّرِّ والعلن. له تاريخ الأفغان، ورسالة الرد على الدهريين، ترجمها إلى العربية تلميذه الشيخ محمد عبده, وجمع محمد باشا المخزومي كثيرًا من آرائه في كتاب خاطرات جمال الدين الأفغاني، ولمحمد سلام مدكور كتاب جمال الدين الأفغاني باعث النهضة الفكرية في الشرق. توفِّيَ الأفغاني في الأستانة بعد أن أُصيب بمرَضِ السرطان في فَكِّه، عن عمرٍ بلغ نحو ستين عامًا، وقد ثار الجدَلُ حول وفاته، وشكَّك البعضُ في أسبابها، وأشار آخرون إلى أنه اغتيلَ بالسمِّ. وكانت وفاته في 5 من شوال 1314هـ / 10 من مارس 1897م. قال عنه الفيلسوفُ إرنست رينان الذي التقى به وحاوَرَه: \"قد خُيِّلَ إليَّ مِن حريَّةِ فِكرِه ونبالةِ شِيَمِه وصراحتِه وأنا أتحدث إليه، أنَّني أرى وجهًا لوجهِ أحدِ مَن عرفتُهم من القُدَماء، وأنني أشهَدُ ابنَ سينا أو ابنَ رشد, أو أحدَ أولئك الملاحدة العِظامِ الذين ظلُّوا خمسة قرون يعملونَ على تحريرِ الإنسانيةِ مِن الإسارِ\" وتبقى شخصيةُ الأفغاني يحومُ حولَها كثيرٌ مِن الشُّكوكِ!"},{"id":4751,"title":"إعلان الدولة العثمانية الحرب على اليونان .","date":["العام الهجري :1314","الشهر القمري : ذي القعدة","العام الميلادي :1897"],"text":"أعلنت الدَّولةُ العثمانية الحربَ على اليونان بعد حروبِ العِصاباتِ التي شنَّها اليونانيون في عددٍ مِن الإيالات (الولايات) العُثمانية، وقد استمَرَّت هذه الحرب شهرًا، وانتصرت فيها الدولةُ العثمانية التي أفنت الجيشَ اليونانيَّ في معركة \"برنار\" ووصلت إلى أبواب العاصمةِ أثينا."},{"id":4752,"title":"انتصار الجيش العثماني على الجيش اليوناني في معركة \"جتالجه\" .","date":["العام الهجري :1314","الشهر القمري : ذي الحجة","العام الميلادي :1897"],"text":"انتصر الجيشُ العثماني على الجَيشِ اليوناني الذي يقودُه الأمير \"قسطنطين\" وليُّ عهد اليونان في معركةِ \"جتالجه\". ومكَّنَت انتصارات العثمانيين على اليونان من اقترابِ الجَيشِ العثماني إلى مسافة 150 كم من العاصمةِ أثينا."},{"id":4753,"title":"حادثة فاشودة في جنوب السودان .","date":["العام الهجري :1315","العام الميلادي :1897"],"text":"حادثُ فاشودة كان من أسبابِ الخلافِ بين انجلترا وفرنسا في السيطرةِ على أعالي النيلِ، هو تصميمُ الخديوي إسماعيل على الوصولِ إلى أعماقِ الجنوب السوداني عند تأسيسِه مديرية خَطِّ الاستواء على حدودِ أوغندا ليسيطِرَ على كلِّ مجرى نهرِ النيل والامتداد في أعماقِ القارَّة. وقد أصبحت تلك المناطِقُ ضِمنَ الوجود المصري في السودانِ، وكانت الإمبراطوريةُ الفرنسيةُ بدَورِها تتحَرَّك باتجاهِ مَنطِقةِ جنوب السودان هي الأخرى؛ حيث كان القائِدُ الفرنسي مارشان قد وصل إلى فاشودة بعد عامين من خروجِه من مدينة برازافيل في الكونغو على رأسِ جنودِ سينغاليين مجتازًا ثلاثةَ آلاف كيلومتر في جوف القارة؛ بهَدَفِ ضَمِّ أعالي النيل إلى الإمبراطورية الفرنسية؛ لتلتقي قواتُه مع قواتِ كتشنر الذي كان بعد انتصارِه على الحركة المهدية واحتلالِ الخرطوم انطلق على مركَبٍ بخاري ومعه عددٌ من الجنود المصريين والسودانيين متَّجهًا إلى فاشودة، حيث وصل بعد يومين من وصولِ مارشان. وعندما التقى الطرفانِ أعلم كتشنر القائِدَ الفرنسي بأنَّ عليه العودةَ إلى بلاده وتَرْكَ فاشودة؛ لأن الأرض التي يَقِفون عليها هي أرضٌ مِصريَّةٌ، وأن الخِلافَ هو بين مصر وفرنسا، وقد استقبل كتشنر خَصمَه الفرنسي بلباسِ ضابطٍ مِصريٍّ، وتحت العلم المصري. كانت مرحلة صراعات بين الدُّوَلِ الاستعمارية حول السودان ومنطقةِ القرن الأفريقي ووسط أفريقيا. وكانت نقطةُ الالتقاءِ هي فاشودة التي انتهت بدونِ معركةٍ عَسكريةٍ، وكانت عنوانًا لتقسيم المنطقة وَفقَ نظرية الاتفاقاتِ الوُدِّية والتي تبلورت بعد سنواتٍ قليلةٍ فيما سمِّيَ بالاتفاق الوُدي لتقسيمِ الدُّوَل العربية أو المستعمرات بين الدُّوَل الاستعمارية! بعد صراعاتٍ حاولت فرنسا خلالَها هي الأخرى الاتصالَ بالثورة المهدية والطَّلَب منها رفعَ العَلَم الفرنسي فوقَ فاشودة قبل أن تقومَ بمساندة الثورة المهديَّة في مواجهة بريطانيا، وبعد مواجهةِ فاشودة انتهت الأوضاعُ إلى الاستقرار على تقسيم \"السودان العظيم\" إلى مناطِقِ نفوذ وقَعَ فيها السودان الحاليُّ الذى نعرفه تحتَ الاحتلال الانجليزي. أخذت إيطاليا (بيلول) شمال خليج (عصب)، والمنطقة الساحلية قرب (مصوع) إرتريا الحالية, وأخذت الحبشةَ مدينة (هرو)، وانتزعت إنجلترا الجهاتِ المطِلَّةَ على بحيرة فيكتوريا، ووضعت فيها أساسًا لمستعمرة أوغندا كمركزٍ لِمُستعمراتِها الأفريقيةِ، وأخرجت إنجلترا فرنسا من فاشودة تحت العَلَمِ والجيش المصري إلى المناطِقِ الأخرى في جوف القارة، وهى التي أصبحت تسيطِرُ على تشاد فعليًّا."},{"id":4754,"title":"وفاة الأمير محمد ابن رشيد حاكم نجد وجبل شمر .","date":["العام الهجري :1315","العام الميلادي :1897"],"text":"هو الأميرُ محمدُ بنُ عبد الله بن علي بن رشيد، من شمر، أكبَرُ أمراءِ آل رشيد أيامَ حُكمِهم في حائل وما حولها. كان أبوه عبدُ الله قد لجأ إلى آل سعودٍ وأقامه الأميرُ فيصل بن تركي بن عبد الله أميرًا على حائل، وتوفِّيَ بها سنة 1263هـ، وخلفه ابنُه طلال فتوفي سنة 1283 وخَلَفه أخوه متعب فقتله ولَدَا أخيه بندر وبدر ابنا طلال سنة 1285، وقام محمد سنة 1288 فقتل خمسةً من أبناء أخيه طلال بينهم بندر وبدر، وترك سادسًا لهم اسمه نايف لصغر سنه، وتوطَّدَت له الإمارة. وامتَدَّ حُكمُه إلى أطراف العراق ومشارف الشام، ونواحي المدينة واليمامة وما يلي اليمن. وغلب على نجدٍ، وانتهز فرصةَ الخلاف بين أمراء آلِ سعود، فأدخل نجدًا في طاعتِه بعد أن قضى على دولتِهم في مرحلتها الثانية سنة 1309ه. وأَمِنَت المسالك في أيامِه، وفكَّرَ في إنشاءِ ميناء بحريٍّ لنجد، فحالت منيَّتُه دون ذلك. توفِّيَ بحائلٍ ولم يُعقِب ولدًا، فلمَّا مات خلفه ابنُ أخيه عبد العزيز بن متعب الذي قُتِلَ في المواجهة مع الملك عبد العزيز في معركة روضة مهنا بالقصيم سنة 1324."},{"id":4755,"title":"محاولة اليهود إغراء السلطان عبد الحميد الثاني بهجرتهم إلى فلسطين .","date":["العام الهجري :1315","العام الميلادي :1897"],"text":"في هذا العام زار الإمبراطورُ الألمانيُّ ويلهلم استانبولَ فلَحِقَه هرتزل وتمكَّن من مقابلتِه في القدس وطلَبَ مساعدتَه بشأن الهجرة إلى فلسطين، وبعد توسُّط السفارة الألمانية في استانبول تقَدَّم هرتزل وبصُحبتِه الحاخام اليهوديُّ موشيه ليفي مِن السلطان عبد الحميد الثاني قائلًا: مولانا صاحِبَ الشوكة جلالةَ السلطانِ، لقد وكَّلَنا عبيدُكم اليهودُ بتقديم أسمى آيات التبجيل والرجاءِ، عبيدُكم المخلِصون اليهودُ يقَبِّلون الترابَ الذي تدوسونه ويَستعطِفونكم للهجرةِ إلى فلسطين المقدَّسة، ولقاء أوامِرِكم العالية الجليلة نرجو التفضُّلَ بقَبولِ هديَّتِكم خمس ملايين ليرة ذهبية، فما كان من الخليفةِ إلَّا أن أمر بطردِهم، كما جاء في مذكرات هرتزل، بلِّغوا هرتزل ألا يبذُلَ بعد اليوم شيئًا من المحاولة في هذا الأمرِ؛ أمرِ دُخولِ فلسطين، والتوطُّن فيها؛ فإنِّي لست مستعدًّا لأن أتخلى عن شبرٍ واحدٍ من هذه البلاد لتذهَبَ إلى الغيرِ، فالبلاد ليست ملكي بل هي مِلكٌ لشعبي، روى ترابها بدمائِه، فلْتحتفِظ اليهودُ بملايينهم من الذهَبِ. وأصدر أمرًا بمنع هجرة اليهود إلى فلسطين، فاتخذوا قرارًا بخَلعِه وحاولوا استخدامَ المنظَّمات السرية الأرمنية، وفوَّضوا عمانوئيل قره صو الذي يتمتَّع بجنسية عثمانية وإيطالية، والذي أصبح نائبًا عن ولاية سلانيك بتلك المهمَّة، فكان هذا اليهودي ممن اشترك مع الوافدِ الذي دخل على الخليفة ليبلِّغَه قرارَ عَزلِه."},{"id":4756,"title":"انعقاد المؤتمر الصهيوني الأول في بازل بسويسرا .","date":["العام الهجري :1315","الشهر القمري : ربيع الأول","العام الميلادي :1897"],"text":"بدأت الجمعيَّاتُ السرِّيَّةُ وغيرُ السريَّةِ تنتَشِرُ في البلادِ، والأفكارُ الغربية المواليةُ للغربِ والمعاديةُ لفِكرةِ الخلافة تنتَشِرُ، وبدأت التنظيماتُ العسكريَّةُ تنمو وتتَّسِعُ دائرتُها بسرعةٍ، وبدأ الخطَرُ اليهودي يَبرُز بشكلٍ واضحٍ سواء عن طريقِ يهود الدونمة، أو عن طريقِ الماسونيَّة، أو عن طريق اليهودِ من الخارج؛ إذ ساعدوا الجمعيَّاتِ السريَّةَ، وكان اليهودُ قد دَعَوا إلى اجتماعٍ لبَحثِ قضيَّتِهم وعَقْدِ المؤتمر الذي دَعَوا إليه في بازل - أو بال- بسويسرا عام 1315هـ ورأوا في المؤتمَرِ أن يعملوا على تأسيسِ وطَنٍ قوميٍّ لهم يجمعون فيه أبناءَ عقيدتِهم الذين يُضطَهدون في العالم نتيجةَ تصَرُّفاتِهم وآرائِهم وعقائِدِهم الخاصة بهم سواءٌ أكانت ابتزازًا للأموال أم تسخيرًا للجِنسِ لحسابِ تحقيقِ مآرِبِهم أم قتلًا للأبرياء للحُصولِ على الدماء لعمَلِ فطيرتِهم في عيدِهم المقَدَّس، وأصَرَّ هرتزل يومذاك على أن تكون فلسطين هي الوطَنَ القوميَّ لهم، فأُعطِيَ الصلاحياتِ مِن أجلِ تحقيق غاياتهم، فنشأت الفكرةُ الصهيونيَّةُ، وأصبح هرتزل يتَّصِلُ بالسلطانِ عبد الحميد الثاني من أجلِ ذلك."},{"id":4757,"title":"توقيع الدولة العثمانية معاهدة استانبول مع اليونان .","date":["العام الهجري :1315","الشهر القمري : رجب","العام الميلادي :1897"],"text":"وقَّعت الدولةُ العثمانيةُ مُعاهدةَ استانبول مع اليونان، بعد الحَربِ التي نَشَبت بين الجانبين وكَسَبتْها الدولةُ العُثمانية، ونصَّت المعاهدةُ على أنْ تدفَعَ اليونان لاستانبول غراماتٍ حربيَّةً ضَخمةً."},{"id":4758,"title":"بريطانيا تفرض حمايتها على الكويت .","date":["العام الهجري :1316","العام الميلادي :1898"],"text":"بعد أن استطاع الشيخُ مبارك آل الصباح الاستيلاءَ على حُكمِ الكويت أبقى العلمَ العُثمانيَّ مرفوعًا في الكويت ليخَفِّفَ نقمةَ النَّاسِ عليه من قَتلِه لأخويه محمد وجراح ليستفردَ بالحكم، ومن جانبِ الدولة العثمانية فإنها لم تكنْ واثقةً به، ومنعًا لاعتراف أيِّ دولة باستقلاله عيَّنَتْه قائمقام في الكويت، أمَّا البريطانيون فكانوا يتخوَّفون من أمرين: من الحكومة العثمانية التي بدأت تعَزِّزُ قواتها في البصرة، وبدأت نواياها تتَّجِهُ إلى ضمِّ الكويت رسميًّا لها، وعدم تركها على وَضعِها، ومن طرفٍ آخَرَ تتخَوَّف من روسيا التي باتت تزاحمُها على الخليج العربي بالتقرُّبِ من الكويت لأخذِ الامتيازات وإنشاء محطاتٍ للفحم في الموانئ، فحاولت بريطانيا عن طريقِ المقيم البريطاني عقدَ اتفاقية مع مبارك الصباح، فتَمَّ إبرام اتفاقية مضمونُها عدم استقبال مبارك لأيِّ مبعوث دولة أجنبية، وتمت هذه الاتفاقيَّةُ بسريَّةٍ تامَّةٍ، وحاولت بريطانيا أيضًا أن تزيدَ عدد السفن البحرية الحربية بحُجَّةِ حماية الخليج العربي أمام الكويتِ، وحاول العثمانيون أن يتولَّوا بأنفُسِهم إدارة ميناء الكويت، ورفض ذلك مبارك فأرسل العثمانيون قوةً عسكريةً بحجَّةِ إقامة دارٍ للجمارك ومَدِّ خطٍّ للتلغراف، وفي الوقت نفسه قام البريطانيون بإعلامِ العثمانيين بأنَّ الكويتَ له استقلالُه، وأنَّ الأمور ستُصبِحُ خطيرةً إذا ما قام العثمانيون بإنشاءِ دار الجمارك في الكويت دون موافقةِ بريطانيا، وأصدر البريطانيون أوامِرَهم للمقيم البريطاني في الخليجِ العربي بالضغطِ على مبارك وتهديدِه حتى لا يتصَرَّفَ دون استشارةِ حكومة الهند، ثم إنَّ محاولات الدولة العثمانية لفَرضِ سُلطتِها على الكويت جَعَلت مباركًا يتصل بقائِدِ السفينة البريطانية سفنكس طالبًا منه إعلان الحكومة البريطانية بتجديدِ الحمايةِ الدائمةِ على الكويت، ورفضت بريطانيا ذلك أولًا، ثم استاء البابُ العالي من مبارك، فأصدر مرسومًا بنفيه من الكويت، ولكِنَّه استنجد بالسفُنِ البريطانية ليخَلِّصوه من هذا المرسوم، وبعد أن قام كرزن برحلةٍ إلى الخليج العربي والتي أدَّت إلى تركيز النفوذ البريطاني في الخليجِ بعد مناقشةٍ قوية مع الدولة العثمانية، تمَّ إعلانُ الحمايةِ البريطانية للكويت والتي أصبحت الكويت بموجِبِه منطقةَ نفوذٍ بريطانية، وتم تعيينُ ممَثِّل سياسي فيها، هو الضابط نوكس."},{"id":4759,"title":"الدعاية للقومية التركية بغرض إلغاء الخلافة الإسلامية .","date":["العام الهجري :1316","العام الميلادي :1898"],"text":"كان السُّلطانُ عبد الحميد الثاني قد أعلن الدستورَ سنة 1876م لكنه بعد سنتين عَلَّق الدستور وعطَّل البرلمانَ العثماني لَمَّا رأى أنَّ أكثَرَ الموالين للدستور من المفتونيين بأوربا وسياستِها وعلى صلةٍ بالساسة الأوربيين، ويعادون القانونَ الإسلاميَّ، ويطلقون على أنفُسِهم اسمَ الدستوريين، فانطلقوا يعملون على نشرِ أفكارِهم وبدؤوا بتأسيسِ الجَمعيَّاتِ السرِّية التي كان من أشهَرِها وأولها جمعية الاتحاد والترقي، التي تأسَّست في باريس هذا العام، وجمعية الحرية، في سلانيك في 1323هـ ثم اندمجتا معًا ولم يقتَصِرِ الأمرُ على المدنيين، بل إنَّ العسكريين أيضًا كانوا ينضَمُّون لهذه الجمعيَّات، وكانت أقدم الجمعيَّات هي الجمعيَّاتِ الشعبيَّة العثمانية التي تأسَّست منذ عام 1282هـ، وكانت علنيَّة غيرَ سرية، أمَّا التنظيماتُ العسكرية فكان تنظيمُ نيازي بك، ورائف بك، وحسين بك، وصلاح الدين بك، وكانت الحكومةُ مهتمَّةً في ذلك الوقت بالحَدِّ من خطَرِ مخطَّطاتِ اليهود سواءٌ كانوا من الدونمة، أو من الماسونية، أو من الخارج، الذين يدعمون هذه الجمعيَّات السريَّة، وكانت المعارَضةُ في الداخل من الأحرارِ العثمانيين الذين يريدون السيرَ على المنهجِ الأوربي لا المنهجِ الإسلاميِّ مفتونين بالحضارة الأوربية، ويظنون أنَّ طريقَها يكون بالتخلِّي عن الإسلامِ، ومن طرفٍ آخَرَ كانت المعارَضاتُ من القوميين غيرِ الأتراك الذين بدؤوا بالظهورِ وتكوين الجمعيات أيضًا الخاصة بهم، التي نشأت كرَدِّ فعل على القوميين الأتراك الذين بدؤوا ينشُرون ويعملون على جَعلِ الدولة العثمانية دولةً تركيةً بحتةً لا دَخْلَ للعرب فيها، مثل: جمعية تركيا الفتاة، وجمعية الوطن والحرية، التي كان منها مصطفى كمال أتاتورك، ثمَّ بدأت الثوراتُ تُظهِرُ الرغبةَ في خلعِ السلطانِ عبد الحميد."},{"id":4760,"title":"استعادة الجيش المصري الإنجليزي السودان .","date":["العام الهجري :1316","الشهر القمري : ربيع الآخر","العام الميلادي :1898"],"text":"بعد أن سيطر المهديُّون على السودان كلِّها وجاءت الأوامِرُ الإنجليزية للمصريين بالانسحابِ مِن السودان، ثمَّ أخذت إنجلترا بالعمل لاستعادة السودانِ، ووافق ذلك هزيمةَ إيطاليا أمام الحبشة، فاستنجدت إيطاليا بإنجلترا فتشَكَّل الجيشُ المصري الإنجليزيُّ، وتجمَّعَ في حلفا في ذي القعدة 1313هـ / أيار 1896م ليستعيدَ السودان، وقاد الجيشَ كتشنر الضابِطَ الإنجليزيَّ، ثم أُعطِيَت الأوامِرُ للتقَدُّمِ إلى السودان، وحدث صدامٌ أوَّلًا بين دوريةٍ مِن هذا الجيشِ والأنصارِ، ثمَّ حَدَثت معركةُ فركة في السادس والعشرين من ذي الحجة / حزيران، ولم يكن عددُ السودانيين يزيدُ على ثلاثة آلافٍ، على حين كان الجيشُ المقابِلُ عشرةَ آلاف بعتاده الكامِلِ، فقُتِلَ من السودانيين قائِدُهم حمودة ومعه ثمانمائة مقاتل، وأُسِرَ سِتُّمائة وتراجَعَ البقيَّةُ إلى دنقلة، ثمَّ جَرت اتصالاتٌ سريَّةٌ بين الضبَّاط الإنجليز وأعيان كردفان وزعيم الكبابيش وعبد الله ولد سعدٍ زعيم قبيلة الجعليين؛ لإعادة الحكم المصري، غيرَ أنَّ الجيش المصري قد أُصيب بكارثة انتشار الكوليرا في صفوفِه، ووجد أميرُ دنقلة أنَّه لا يستطيعُ الصمود أمامَ الغزاة فأخلى مدينتَه ودخَلَها كتشنر دون مقاومةٍ، ووصل مدينة مروى ومد الإنجليزُ خطًّا حديديًّا بسرعة بين حلفا وأبو حمد، وحاولت قوةٌ مهدية المقاومةَ في أبو حمد غيرَ أنَّها قد هُزِمَت أمام قوة السلاح رغمَ ما قدَّمت من تضحية، وكذلك انسحب أمير بربر إلى أم درمان، وجاءت قوةٌ من الجيش المصري من سواكِن على البحر الأحمر وتقَدَّمت نحو الداخل وأخذت مدينةَ كسلا من أيدي الإيطاليين، وذلك في 26 رجب 1315هـ / 20 ديسمبر 1897م، وانتصر كتشنر على قائدِ الجيش السوداني محمود في بلدة النخيلة على نهر عطبرة في 15 ذي القعدة 1315هـ / 6 نيسان 1898م وتقدَّم الإنجليزُ بجنودِهم المصريين نحو الجنوبِ وجَرَت معركةُ كرري في ربيع الثاني 1316هـ / أيلول 1898م وقُتِلَ فيها عشرة آلافٍ مِن الأنصارِ أتباعِ حركةِ المهديِّ، ودخل كتشنر الخرطومَ ورُفِع عليها العَلمانِ المصريُّ والإنجليزي، وتم التفاهمُ مع الفرنسيين في فاشودة."},{"id":4761,"title":"الاتفاقية المصرية السودانية .","date":["العام الهجري :1316","الشهر القمري : رمضان","العام الميلادي :1899"],"text":"بعد أن استعاد الجيشُ المصري الإنجليزي السودانَ، تم التوقيعُ على الحُكم الثنائي للسودان، وذلك بين كرومر المندوب السامي الإنجليزيِّ في مصر ووزيرِ خارجية مصر بطرس غالي، وقد كانت الاتفاقيَّةُ بشأنِ إدارة السودان في المستقبَلِ، وأُطلِقَ لفظُ السودان في هذه الاتفاقية على جميع الأراضي الواقعة جنوبَ خَطِّ العرض 22 شمالًا، وأن يُرفَعَ العلمان البريطاني والمصري في البَرِّ والبحر في جميع أنحاء السودان عدا سواكن، فلا يُرفَعُ إلا العلمُ المصري، وغيرها من البنود التي تتضَمَّن تبعيةَ السودان لمصر. وعَمِلَت إنجلترا على إقحامِ مِصرَ مع أنَّه فعليًّا الأمر للإنجليز؛ من أجلِ فرنسا، وأُطلِقَ على الحُكم بالثنائي يعني بين مصر وإنجلترا، وهذا أيضًا ينهي السيادة العثمانية على السودانِ."},{"id":4762,"title":"ظهور حركة محمد الصومالي ودورها في مواجهة الإنجليز .","date":["العام الهجري :1317","العام الميلادي :1899"],"text":"واجه الاستعماران البريطانيُّ والإيطاليُّ ثورةَ الزعيم محمَّد عبد الله حسن الذي تلقَّب بمهدي الصومال. الذي استطاع أن يقاوِمَ المستعمرين لمدةِ عشرين عامًا كبَّدَهم أثناءَها الخسائِرَ الفادحة. وكانت بدايةُ هذه المقاومة هذا العام. وقد استطاع محمدُ عبد الله «الملا المجنون» (لقب أطلقه عليه الإنجليز) انتزاع حَقِّ السيادة على مناطقَ عديدةٍ. وفي عام 1913م. ألحقت قواتُه هزيمةً نكراء بالقوات الإنجليزية التي كان يقودُها الكولونيل «كورفيلدو» الذي قُتِلَ أثناء المعركة. وكان محمد عبد الله حسن قد أجرى عدةَ أحلافٍ مع العثمانيين وإمبراطور الحبشة (ليدجي يسوع الذي اعتنق الإسلام وفقد جرَّاءَ ذلك عرشَه). وقد استطاع ونستون تشرشل بإصداره الأمرَ باستعمال الطيرانِ الحربيِّ ضِدَّ الزعيم الصومالي عام 1920م الذي تعرَّضَت منطقته للقَصفِ الشديد، فتكَبَّدت قواتُه خسائِرَ كبيرة إلَّا أنه نجا من الموتِ، فلجأ إلى أثيوبيا حيث توفِّيَ هناك عام 1921م. استمَرَّت مقاومةُ المهدي محمد عبد الله حسن من عام 1908م حتى عام 1920م. ونجا من الموتِ عام 1920م إلَّا أنَّ قواتِه العسكريةَ أُصيبت بانهيارٍ كاملٍ."},{"id":4763,"title":"وقوع السودان تحت السيطرة المصرية البريطانية .","date":["العام الهجري :1317","العام الميلادي :1899"],"text":"منذ أن دخلت بريطانيا إلى مصرَ وهي تعمَلُ على فصل السودان عن مصرَ، ولم تستطع إنجلترا أن تقمَعَ الثورات باسمِ المصريين، فقامت بإجلاء العساكِرِ المصرية من السودان بحُجَّةِ ولائِهم لأحمد عرابي لا للخديوي توفيق، وبصعوبةِ المواصلات للسودان، وأصَرَّ كرومر المندوبُ الإنجليزيُّ على إجبارِ الحكومة المصرية على قَبولِ الجلاء، ولكنَّه صار جلاءً مؤقَّتًا؛ ففي سنة 1896م جاءت حملةُ كتشنر التي انتهت بعد معركةِ أم درمان سنة 1898م برفع العلمِ الإنجليزي والمصري في الخرطوم، وفَرَضت في اتفاقية سنة 1899م نظامَ الحكم الثنائي المصري الإنجليزي، بمعنى دخولها شريكًا أساسيًّا في امتلاك البلادِ، وتقرَّرَ أن يكونَ تعيينُ حاكم عموم السودان بأمرِ الخديوي، ولكِنْ بترشيح بريطاني."},{"id":4764,"title":"استيلاء الإنجليز على السودان بعد القضاء على حركة المهدي .","date":["العام الهجري :1317","العام الميلادي :1899"],"text":"أجبرت إنجلترا حكومةَ مِصرَ على سَحبِ جَيشِها من السودانِ بعد انتصارِ ثورة المهدي، وقاد كيتشنر مع عددٍ مِن الضباط الإنجليز حملةَ الجيش المصري لإعادةِ احتلال السودان من عام 1896م حتى عام 1898م؛ حيث انهزم المهديُّون في معركةِ أم درمان الفاصلة، فأجبر الإنجليز مصرَ على توقيع اتفاقية هذا العام (بحجَّة أن السودان قد أُعيدَ فتحه بدعمٍ مِن البلدين) فنصَّت الاتفاقيَّةُ على رفع العَلَمين المصري والإنجليزي. وعلى تعيينِ حاكمٍ عَسكريٍّ للسودان تختارُه بريطانيا ويعَيِّنُه الخديوي، ويفصل بالطريقة ذاتها. وكان كيتشنر أولَ حاكمٍ عسكريٍّ عامٍّ هناك، كما احتفظ لمصرَ في السودان بفرقةٍ عسكرية, وفي عام 1924م بدأت التظاهراتُ والاحتجاجات تعُمُّ مصر والسودان، أدَّت إلى اغتيال الحاكم العام للسودان أثناءَ زيارتِه لمصر، فاستغل الإنجليزُ مقتلَ اللواء الإنجليزي لي أوليفير فيتزماورس ستاك السردار (قائد) الجيش المصري في السودان، ما أدَّى إلى ردٍّ عنيفٍ تمثَّل بمنع مشاركة مصر في حُكمِ السودان حسَبَ معاهدة 1899م، فأجبر الإنجليزُ حُكومةَ مِصرَ على سحبِ فرقتِها العسكرية من السودان، ولكِنَّ بعضَ الوحدات المصرية ما لَبِثَت أن عادت بعد معاهدة 1936م. وفي الفترةِ التي نالت فيها مِصرُ استقلالها، تنامت حركاتُ المعارَضة في السودان. وقد نجح البريطانيون في مَطلَعِ العشرينايت في تكوين تيارٍ سوداني قوي معادٍ لمصرَ، وحمل شعار: «السودانُ للسودانيين» وأدَّت التحوُّلاتُ السياسية السودانية في الثلاثينيات إلى تصدُّعِ هذا الحِلْف، ذلك أنَّ نفوذَ حَركةِ المهدي وقُوى تحالفِها مع البريطانيين أدَّى هذا إلى إثارةِ حَفيظةِ الميرغني الذي قرَّر نكايةً بالإنجليز التحالُفَ مع القوى الوطنية «مؤتمر الخريجين» وراحوا ينادون من جديدٍ بالوَحدةِ مع مصر، إلَّا أنَّ خيبات الأمل والضَّرَبات التي كسرت الصورةَ المثالية لمصر عند السودانيين توالت، وخاصةً عند الشباب الذي سافر للتعلم في القاهرة. وكانت الضربةُ الثانيةُ بعد معاهدة 1936م بين مصر وبريطانيا التي أعادت إلى مصرَ شيئًا من نفوذِها على السودان. فقد صدمت هذه المعاهدةُ السودانيين؛ لأنَّها لم تذكُرْ لهم أيَّ دور، هذا ما أعاد بعثَ الحركة الوطنية التي وإن كانت تتطلَّعُ إلى مصر، إلَّا أنَّها أدركت أنَّ مِصرَ لا يمكِنُ الاعتماد عليها كليًّا لتعَبِّرَ عن صوت السودانيين. بعد ذلك حصل منعطَفٌ كبير وهو ثورة 23 يوليو 1952م في مصر، وبروز اللواء محمد نجيب، الذي كان يتمَتَّعُ بشعبية واسعة في السودان؛ حيث اعتُبِرَ أنَّه نِصفُ سودانيٍّ، وبعده مجيء جمال عبد الناصر، فأعطت هذه الثورةُ دفعةً قويةً لتيار الوَحدةِ بعد تراجُعِه كثيرًا. وكانت الثورةُ مُتجاوِبةً مع الوَحدويِّين السودانيين، وكان قادتُها على قدر كبير من التفَهُّم والوعي لمطامِحِ الحركة الوطنية السودانية، وتمكَّنوا في الوقت نفسِه من طمأنة حزبِ الأمة والاستقلاليين إلى نوايا مصرَ، ولم يتردَّدوا في توقيعِ اتفاق مع كلِّ الأحزاب السودانية في عام 1953م لمنح السودان حقَّ تقريرِ مَصيرِه."},{"id":4765,"title":"قيام حملة ضخمة تمنع بيع الأراضي للمهاجرين اليهود في فلسطين .","date":["العام الهجري :1318","العام الميلادي :1900"],"text":"شَهِدَ هذا العامُ حملةً ضَخمةً لجَمعِ التوقيعات على عرائِضَ تَمنَعُ بَيعَ الأراضي للمهاجرين اليهود في فلسطين. وكانت لكتاباتِ الشيخ رشيد رضا على صفحاتِ جريدة المنار، وغيره، أثرٌ كبير في زيادةِ وعي الجماهير بما يدورُ في فلسطين."},{"id":4766,"title":"صدور أمر بإنشاء سكة حديد الحجاز لخدمة الحجاج .","date":["العام الهجري :1318","الشهر القمري : محرم","العام الميلادي :1900"],"text":"أصدر السُّلطانُ العثماني عبد الحميد الثاني أمرًا سلطانيًّا بإنشاء سكة حديد الحجاز؛ لخدمة حجاج بيت الله الحرام، واستمَرَّ الخَطُّ في العمل تسعَ سنوات، وتعرَّض بعدها للتخريبِ أثناء الثورة العربية، ولم تُفلِح محاولات إعادته للحياةِ مرةً أخرى، وكانت تنحَصِرُ أهداف السلطان عبد الحميد في إنشاءِ الخط الحجازي في هدَفَين أساسيَّين مترابطين: أولهما: خدمةُ الحجاج بإيجادِ وسيلةِ سفَرٍ عصرية يتوفَّرُ فيها الأمن والسرعة والراحة. أما الهدف الثاني: فدَعمُ حركة الجامعة الإسلاميَّة التي كانت تهدفُ إلى تكتيل جميعِ المسلمين وتوحيدِ صُفوفِهم خَلْفَ الدولة العثمانية؛ لمواجَهةِ الأطماع الأوروبيَّةِ في العالم الإسلامي. وقامت حركة الجامعة الإسلامية على دعامتين أساسيَّتين، هما: الخلافةُ والحَجُّ؛ لذلك أراد أن يتَّخِذَ من الحجِّ وسيلةً عملية كي يلتَفَّ المسلمون حولَ الخلافة، وربط إنشاء الخط الحديدي الحجازي بحركة الجامعة. وقد واجه المشروعُ صعوباتٍ تمويلية، منها ضخامةُ تكلفته التي قُدِّرَت بنحو 3,5 ملايين ليرة عثمانية، مع وجود الأزمةِ المالية التي تواجِهُها الدولة العثمانية، فوجَّه السلطان عبد الحميد نداءً إلى العالم الإسلامي عبر سكرتيره \"عزت باشا العابد\" للتبَرُّع للمشروع. ولقِيَ هذا النداء استجابةً تلقائية من مسلمي العالَم وانهالت التبَرُّعات، وكان اتِّساعُ نطاق هذه التبرعات مَظهرًا عمليًّا لحركةِ الجامعة الإسلامية. وانتقلت حماسةُ إنشاء الخط الحجازي إلى العالم الإسلامي، وكان مسلمو الهند مِن أكثر المسلمين حماسةً له، وهو ما أثار غضَبَ بريطانيا، فوضعت العراقيلَ أمام حملات جمعِ التبرُّعات حتى إنها رفضت أن يرتديَ المسلمون الهنود الذين اكتَتَبوا في الخطِّ الأوسمةَ والنياشين العثمانية. ولم تقتَصِر تبرعات وإعانات المسلمين على الفترات التي استغرقها بناءُ الخط فحسب، بل استمَرَّ دَفعُها بعد وصولِه إلى المدينة النبوية؛ أملًا في استكمال مدِّه إلى مكة المكرمة., وابتدأ العمَلُ في منطقة المزيريب من أعمال حواران ببلاد الشام، ثم قرَّرت الحكومة العثمانية إيصالَ الخط الحجازي إلى دمشق؛ لذلك قرَّرت إنشاءَ خَطِّ درعا - دمشق، وباشرت العمَلَ من دمشق ومزيريب في وقتٍ واحد. واحتفل ببدء المشروع في جمادى الآخرة من هذا العام, وقد استمرَّت سكة حديد الحجاز تعمل بين دمشق والمدينة ما يقرُبُ مِن تسع سنوات نقلت خلالها التجار والحجاج، وعندما نَشَبَت الحرب العالمية الأولى ظهرت أهميَّةُ الخط وخطورته العسكرية على بريطانيا؛ فعندما تراجَعَت القوات العثمانية أمامَ الحملات البريطانية، كان الخطُّ الحجازي عاملًا هامًّا في ثبات العثمانيين في جنوبي فلسطين نحو عامين في وجه القواتِ البريطانية المتفَوِّقة. وعندما نشبت الثورة العربيَّةُ بقيادة الشريف حسين واستولَت على مُعظَم مدن الحجاز، لم تستَطِعْ هذه القواتُ الثائرة السيطرةَ على المدينة بسَبَبِ اتصالها بخط السكة الحديدية، ووصول الإمداداتِ إليها، واستطاعت حاميةُ المدينة العثمانية أن تستَمِرَّ في المقاومة بعد انتهاءِ الحرب العالمية بشهرين؛ لذلك لجأ الشريف حسين -تنفيذًا لمشورة ضابط الاستخبارات البريطاني لورانس- إلى تخريبِ الخطِّ ونَسفِ جُسورِه وانتزاع قُضبانِه في عِدَّةِ أجزاءٍ منه."},{"id":4767,"title":"معركة الصريف ومحاولة الملك عبد العزيز الأولى لاستعادة الرياض  .","date":["العام الهجري :1318","الشهر القمري : ذي القعدة","العام الميلادي :1901"],"text":"انتهت الدولة السعوديُة الثانية عام 1308هـ واستطاع محمدُ ابنُ رشيد السيطرةَ على كل المناطق التي كانت تحت حُكمِ آل سعود في نجدٍ وما حولها، وبقِيَ الأمرُ على ذلك إلى عام 1319هـ، وكان كُلَّ هذه الفترة عبدُالرحمن بن فيصل مع أسرتِه في الكويت، ثمَّ إن أمير حائل عبد العزيز بن متعب استعَدَّ لقتال الشيخ مبارك أميرِ الكويت، فاقترح عبد العزيز بن عبد الرحمن بن فيصل على الشيخِ مبارك أن يسيرَ بقوَّةٍ إلى الرياضِ فيأخُذَها من آلِ رشيدٍ، فتَضعُف قوَّتُهم عن محاربةِ الشيخ مبارك، فلاقى ذلك قبولًا عنده، فلمَّا اتجَه الشيخُ مبارك بقواتِه إلى جهة القصيم واشتَبَك مع ابن رشيد في معركةٍ حامية بالقُربِ مِن مكانٍ يُسمَّى بالصريف على مقربةٍ مِن الطرفية في القصيم، كان عبد العزيز قد سار بقوةٍ إلى الرياض ـ وحاصَرَها ولم يستَطِعْ دُخولَها، فاضطر للانسحابِ منها، ثمَّ عودته إلى الكويت بعد أن بلَغَه هزيمة الشيخ مبارك أمامَ ابن رشيد في معركةِ الصريفِ."},{"id":4768,"title":"ظهور بروتوكولات حكماء صهيون وخطرها على العالم الإسلامي .","date":["العام الهجري :1319","العام الميلادي :1901"],"text":"تعتبَرُ بروتوكولات حُكَماءِ صهيون من أخطَرِ الكتُبِ المنتَشِرة حولَ العالم، ذلك أنَّها تتحَدَّثُ عن خطةٍ مَرسومةٍ وجاهزةٍ وُضِعَت للسيطرةِ على العالم. يقالُ إنَّ مَن وضع هذه البروتوكلات هم رجالُ المال والاقتصاد اليهود؛ لتخريب المسيحيةِ والبابوية، ثم الإسلام؛ للسيطرةِ على العالم أكمَلَ، وذلك خلال مئة سنةٍ مِن تاريخ وَضعِها، يُقالُ: إنَّها كُتِبَت عام 1897 في بازل بسويسرا، أي: في العام نفسه الذي عُقِدَ فيه المؤتمر الصهيوني الأوَّلُ، بل ويزعم البعضُ أنَّ تيودور هرتزل تلاها على المؤتمرِ وأنَّها نوقِشَت فيه، وقد تعدَّدَت المصادِرُ التي تتكلَّمُ عن مصدر البروتوكولات...فمن قائلٍ إنَّ واضِعَها رجلٌ غامِضٌ في الجيشِ الروسي ليوقِعَ باليهودِ الذين عارضوا الدولةَ القيصريةَ، وذلك للإيقاعِ بهم في روسيا، إلى قائلٍ إنَّ أصلَها قد جاء من أوروبا، ولكِنْ لم تُعرَفْ حقيقةُ واضِعِها؛ لأنَّها لم تُرفَق باسم أحد أو بتوقيعِه. وبغضِّ النظر عن كلِّ هذه الأقاويل فإنَّ البروتوكولات يهوديَّةٌ، وعندما ظهرت بروتوكولات حكماء صهيون (وكان ذلك في روسيا في مطلعِ القرن الماضي، ولعله ما جعل البعضَ يعتقد أنَّ أصلَها روسيا) أحدَثَت ردَّةَ فعلٍ كبيرةً في أوساطِ العالم وضجَّةً عظمى بين الحكَّام اليهود حول العالم، وعلى رأسهم هرتزل الذي صرَّح بأن ظهورَها في ذلك الوقتِ يشكِّلُ خطرًا كبيرًا على كلِّ اليهود حول العالم، وأن أحدًا ما أخرجها من قُدسِ الأقداس الذي لا يُسمَحُ لكبارِ الحكَّام اليهود برؤيتِها فيه، ويقال: إنَّ أوَّلَ ظُهورٍ لها كان على يد صحفيَّة فرنسيَّة اختطفَتْها من أحد الزعماءِ اليهود أثناء لقاءٍ صَحفيٍّ جمعهما، ولكنَّها لم تترجَمْ أوَّلَ مَرَّةٍ إلا باللغة الروسية بعد انتقالها إلى هذه الأخيرةِ، ومنها إلى الولايات المتحدة وبريطانيا، أمَّا على الصعيد العسكري فقد هبَّت مئات الفِرَق في الجيش الروسي (بأمرٍ مِن الحكومة القيصرية) لتقتُلَ آلاف اليهود وتحرقَ منازِلَهم وتصادِرَ أموالهم. ويظَلُّ الجدلُ قائمًا في معرفة مصدرِ هذه البرتوكولات وصِحَّتِها."},{"id":4769,"title":"دخول الملك عبد العزيز الرياض واستعادة حكم نجد .","date":["العام الهجري :1319","الشهر القمري : شوال","العام الميلادي :1902"],"text":"بعد إخفاقِ الملك عبد العزيز في المحاولةِ الأولى لاستعادةِ الرِّياضِ، ازداد إصرارًا على انتزاع الرياضِ مِن ابن رشيد واستعادةِ حُكمِ آل سعود، فأعاد الكرَّةَ مرةً أخرى في هذا العام. فاستطاع دخولَ الرياض، وقَتَل عجلانَ بن محمد العجلان أميرَ الرياضِ مِن قِبَلِ ابنِ رشيد، بعد خوضِ مغامرةٍ جَريئةٍ قام بها مع أربعينَ رجلًا من أقربائِه وأتباعِه في الليلة الخامسة من شوال. أعلن عبد العزيز بعدها حُكمَه للرياضِ ونهايةَ حُكم ابن رشيد, وأوَّلُ عملٍ قام به هو إعادةُ إصلاحِ ما تهَدَّم من أسوارِ الرِّياضِ؛ ليجعلَها حصينةً أمامَ أي محاولةِ لاسترجاع ابن رشيد حُكمَها, ثم اتَّجه إلى الخرج والدلم وضَمَّهما لحُكمِه، وذلك سنة 1320ه ليؤمٍّن وجوده في الرياضِ."},{"id":4770,"title":"قيام جمعية الاتحاد والترقي بعقد مؤتمر بعنوان \"مؤتمر أحرار العثمانية \" .","date":["العام الهجري :1319","الشهر القمري : شوال","العام الميلادي :1902"],"text":"عقَدَت جمعية الاتحاد والترقي مؤتمرًا لها في باريس بعنوان \"مؤتمر أحرار العثمانية\" استمَرَّ خمسة أيام، جمع فيه المعارضون لنظامِ السلطان عبد الحميد الثاني، واتخذ المؤتمَرُ عِدَّةَ قرارات؛ منها: أن تؤسَّسَ في الإمبراطورية العثمانية إداراتٌ محليةٌ مستقِلَّة على أساس القوميات. وجمعيةُ الاتحاد والترقي نشأت كجمعيَّةٍ سرية باسم (اتحاد عثماني جمعيت) في عام 1889 لمجموعةٍ من طلاب كلية الطب، وهم إبراهيم طمو، عبد الله جودت، إسحاق سكوتي، وحسين زاده علي. ثم أصبحت منظمةً سياسيةً أسَّسها بهاء الدين شاكر بين أعضاء تركيا الفتاة عام 1906م، وأثناء انهيارِ الدولة العثمانية سيطرت الجمعيَّةُ على السُّلطةِ بين عامي 1908 إلى 1918م."},{"id":4771,"title":"فرنسا تحتل موريتانيا .","date":["العام الهجري :1320","العام الميلادي :1902"],"text":"كانت موريتانيا تتبَعُ دولة السنغال وتتبَعُ المغربَ، فبعض مناطق موريتانيا تتبع السنغال، وبعضها يتبع المغرب، وكانت عبارةً عن إماراتٍ صغيرة وغيرِ موحَّدة فيما بينها؛ لذا كانت تخضَعُ للدول الكبيرة التي تقوم في المنطقة، وهذا ما شجَّع الصليبيين المستعمرين للتقَدُّم من السواحل إلى الداخلِ، ولم يجد الاستعمارُ الفرنسيُّ الذي سيطر على المغرب إلَّا إمارات مفكَّكة، وخاصةً بعد أن أُعطِيَت منطقة السنغال إلى فرنسا إثرَ الحروب النابليونية، وأخذ الفرنسيون يتحرَّكون بحذَرٍ نحوَ الداخل عبرَ نهر السنغال، واستطاع الفرنسيون حمايةَ بعضِ القبائل المتنازِعة، فكان هذا أوائِلَ التدخل، وكانت أسبانيا أيضًا منافِسةً لفرنسا وبَقِيَت المعارك بين القبائل والفرنسيين أكثَرَ مِن عامين حتى تمكَّن الفرنسيون من بَسطِ نفوذِهم على منطقةِ أدرار، وأمرُ المغرب كان قد ضَعُف أيضًا، وكان أحمد هبة الله ابن الشيخ ماء العينين في منطقة موريتانيا دعا للجهادِ وحاول الهجومَ على مراكش، فدخلها عَنوةً وبويع سلطانًا للمغرب الأقصى، ثم أرسلت فرنسا جيشًا اندحر أمامَ قوات هبة الله، ثم عادت مرةً أخرى فأرسَلَت جيشًا ضخمًا أخرجه من مراكش، وطاردته، وبمساعدة عدة جنود من المغرب والجزائر والسنغال ومالي وبدعم الطيران والمدفعية وصل الجيشُ إلى تنزيت وتمكَّنَ الفرنسيون منها."},{"id":4772,"title":"رفض السلطان عبد الحميد الثاني اقتراحًا بإنشاء جامعة يهودية في القدس .","date":["العام الهجري :1320","الشهر القمري : محرم","العام الميلادي :1902"],"text":"رفضَ السلطانُ عبد الحميد الثاني اقتراحًا من \"تيودور هرتزل\" مؤسِّس الحركة الصهيونية بإنشاء جامعة يهودية في القدس. وهرتزل يهوديٌّ نمساوي رأَسَ أوَّلَ مؤتمر صهيوني في بازل بسويسرا عام 1879م. يقول السلطان عبد الحميد: \"لليهودِ قُوَّةٌ في أوروبا أكثَر مِن قوَّتِهم في الشرق؛ لهذا فان أكثَرَ الدول الأوربية تحبِّذُ هجرة اليهود إلى فلسطين؛ لتتخَلَّصَ من العِرق السامي الذي زاد كثيرًا، ولكنْ لدينا عددٌ كاف من اليهود، فإذا كنَّا نريد أن يبقى العنصرُ العربيُّ متفوقًا، فعلينا أن نصرِفَ النظرَ عن فكرةِ توطين المهاجرين في فلسطين، وإلَّا فإن اليهودَ إذا استوطنوا أرضًا تملَّكوا كافة قدراتِها خلال وقتٍ قصيرٍ، وبذا نكون قد حكَمْنا على إخواننا في الدينِ بالموتِ المحتَّم، لن يستطيعَ رئيس الصهاينة (هرتزل) أن يقنِعَني بأفكارِه، وقد يكونُ قوله: (ستُحَلُّ المشكلةُ اليهودية يوم يقوى فيه اليهوديُّ على قيادة محراثِه بيده) صحيحًا في رأيه أنه يسعى لتأمينِ أرض لإخوانه اليهودِ، لكنه ينسى أن الذكاءَ ليس كافيًا لحل جميعِ المشاكِلِ، لن يكتفي الصهاينةُ بممارسة الأعمال الزراعية في فلسطين، بل يريدون أمورًا أخرى، مثل: تشكيل حكومة، وانتخاب ممثِّلين. إنَّني أدرك أطماعَهم جيدًا، لكنَّ اليهود سطحيُّون في ظنِّهم أنني سأقبَلُ بمحاولاتهم، وكما أنني أقدِّرُ في رعايانا من اليهود خِدْماتهم لدى الباب العالي، فإني أعادي أمانيَّهم وأطماعَهم في فلسطين\" انتهى كلامه رحمه الله، فصار هرتزل دائمًا يبعث على لسانِ كلِّ مؤتمر يهودي برقيةً للسلطان عبد الحميد يحيِّيه فيها ويؤكِّدُ له ولاء اليهود باعتبارِهم من رعاياه، وكان يعلَمُ حَقَّ العلم أنه لا وزنَ له ولا لليهودِ عند عبد الحميد، فرأى هرتزل دعْمَ مركزه عن طريق تبنِّي دولة أوربية كبرى تقبَلُ الضغط على السلطانِ من أجل الإذن لليهودِ بإقامة وطنٍ لهم في فلسطين، فراسل مسؤولين إنجليزًا يطلُبُ منهم تبنِّي فكرة إقامة وطن قومي لليهود في فلسطين."},{"id":4773,"title":"وفاة عبد الرحمن الكواكبي .","date":["العام الهجري :1320","الشهر القمري : ربيع الأول","العام الميلادي :1902"],"text":"هو عبد الرحمن بن أحمد بن مسعود الكواكبي، ويلقَّب بالسيد الفراتي، مِن رجالِ الأدب والاجتماع والسياسة، وهو من رواد الحركةِ القومية العربيَّة، ولد في 23 شوال سنة 1271هـ في مدينة حلب، وتعَلَّم بها، وكانت له مكانةٌ مرموقة في بلَدِه، يقصدُه أصحابُ الحاجات لقضائِها، ويلجأُ إليه أرباب المشاكلِ لحلِّها، بل كان رجالُ الحكم يستشيرونه أحيانًا فيُبدي رأيَه في جرأة وشجاعة. أنشأ في حلب جريدة (الشهباء) فأغلقَتْها الحكومةُ؛ لهجومه على العثمانيين وطَلَبِه استقلالَ العرب عنهم، ثم أنشأ جريدةَ (الاعتدال) فعُطِّلت كذلك من قِبَل الحكومة، وأُسنِدَت إليه مناصِبَ عديدة. سجنه العثمانيون بسببِ موقِفِه منهم، وتشجيعِه للعرب على الانفصالِ عن الدولة العثمانية، وحكَموا عليه بالقتل إلَّا أن الرأيَ العامَّ جعل العثمانيين يُطلِقون سراحَه، وخَسِرَ جميع ماله، فرحل إلى مصر. وساح إلى بلاد العربِ وشرقي إفريقية وبعض بلاد الهند. واستقَرَّ في القاهرة إلى أن توفي. له من الكتب ((أم القرى))، و ((طبائع الاستبداد))، وكان لهما عند صدورهما دويٌّ كبيرٌ، ألَّف أيضًا كتاب ((العظمة لله))، و((صحائف قريش))، إلى غير ذلك، توفي في القاهرة، ودُفِنَ فيها."},{"id":4774,"title":"ضم الملك عبد العزيز الخرج والدلم .","date":["العام الهجري :1320","الشهر القمري : ربيع الأول","العام الميلادي :1902"],"text":"بعد أن سيطرَ الملك عبد العزيز على الرياض في شوال عام 1319هـ، رَمَّم أسوارَها وحَصَّنها؛ لاحتمال مهاجمة ابن رشيد لها، ثم اتجه إلى الخرج والدلم وجمع حولَه مؤيديه من أهل الخرج والحوطة والفرعة؛ رغبة في استدراج ابن رشيد إلى جنوب الرياض، ولَمَّا اتجه ابن رشيد إلى الرياض وعَلِمَ بتحصينها وأنَّ الملك عبدالعزيز في الخرج، توجه إلى الخرج واشتبك معه في عدَّةِ وقائِعَ دون أن يتحَقَّقَ له أيُّ نصر عليه، إلى أن انهزم ابن رشيد في السلمية فانسحب إلى حفر الباطن، وعاد الملك عبدالعزيز إلى الرياض بعد أن ثبَتَت سيادتُه على الخرج وما حولها."},{"id":4775,"title":"إخماد الجيش العثماني لثورة البلغار في مقدونيا .","date":["العام الهجري :1320","الشهر القمري : جمادى الآخرة","العام الميلادي :1902"],"text":"أخمد الجيشُ العثماني الثورةَ التي قام بها البلغار في مقدونيا، والتي كانت تابعةً للدولة العثمانية، وتبلغ مساحتُها 96 ألف كم مربع، ويبلُغُ عدد سكانها 4 ملايين نسمةٍ، وكانت تحتوي على أعراقٍ وأديانٍ متعَدِّدة."},{"id":4776,"title":"استيلاء البريطانيين على مدينة \"كانو\" في شمال نيجيريا .","date":["العام الهجري :1320","الشهر القمري : ذي القعدة","العام الميلادي :1903"],"text":"استولى البريطانيون على مدينة \"كانو\" في شمالِ نيجيريا، وكان مُعظَمُ جنوب نيجيريا قد خضَعَ للحماية البريطانية منذ عام 1900م. كانت مدينة \"كانو\" تحتَ حُكم أميرٍ مُسلمٍ، وكانت مركزًا تجاريًّا وعسكريًّا مهمًّا في شمالِ نيجيريا. وهاجر عددٌ غير قليل من مواطنيها نتيجةً لهذا الغزو الاستعماري، من دارِ الكُفرِ إلى دار الإسلامِ (الحجاز والسودان) وتحمِلُ الولايةُ التي توجَدُ فيها هذه المدينةُ (وهي عاصمتها) هذا الاسم، ولاية \"كانو\"، ويبلغ تَعدادُ سكَّانِها حوالي (15) مليون نسمة."},{"id":4777,"title":"تولي الشيخ علي بن محمد بن أحمد الببلاوي مشيخة الجامع الأزهر .","date":["العام الهجري :1320","الشهر القمري : ذي الحجة","العام الميلادي :1903"],"text":"تولَّى الشيخُ علي بن محمد بن أحمد الببلاوي مشيخةَ الجامع الأزهر. والببلاوي تعلَّم في الأزهرِ ودرس فيه، وتولى نِظارةَ دار الكتب. وعُيِّن نقيبًا للأشرافِ خَلَفًا لمحمد توفيق البكري، ولم يمكُثْ في مشيخة الأزهر طويلًا؛ بسبب معارضةِ الخديوي عباس حلمي لجهودِ الببلاوي في إدخال تغييراتٍ على الأزهَرِ."},{"id":4778,"title":"ظهور الفرقة القاديانية في الهند .","date":["العام الهجري :1321","العام الميلادي :1903"],"text":"إنَّ مما قام به الإنجليز في الهند لتوطيدِ بقائهم وسيطرتهم فيها أنْ عَمِلوا على إنشاءِ الفِرَق الضالَّة، أو على الأقلِّ دعمها أو السكوت عنها وتَرْكها تنشُرُ ضلالها، فكان مما عَمِلَته أن شجَّعَت مرزا غلام أحمد القادياني على إحياءِ ما دعا إليه المَلِك المغولي في الهند جلال الدين أكبر شاه المتوفَّى عام 1014ه. فأنشأ مرزا غلام القاديانية، وكتب البراهينَ الأحمدية، ثم تطوَّر أمره فادَّعى عام 1322هـ أنَّه المهدي المنتظَرُ، وأعلن أنَّ الإنجليز هم أولو الأمر، فيَجِبُ طاعتهم، ولا يصِحُّ الخروجُ عليهم ولا قتالُهم ولا الجهاد ضِدَّهم مع أحدٍ، وعَمِلَ على التوفيق بين الأديان، فادعى أنَّه يتقَمَّصُ روح المسيح عليه السلام وروحَ الإله كرشنا ربِّ الخير عند الهندوس!! وأصبح له أتباعٌ, وقَوِيَ أمرُه، وكان البريطانيون يدعمونه ويحمونه، ثم لَمَّا توفِّيَ عام 1326هـ انقَسَمت جماعتُه إلى قسمين: الأحمدية وتدَّعي أنه كان رجلًا مُصلِحًا، والقاديانية: وتقول بنبُوَّتِه وتدعو إلى ما كان عليه من أفكارٍ ومعتقداتٍ باطلةٍ."},{"id":4779,"title":"ضم الملك عبد العزيز بلدان الوشم وسدير  .","date":["العام الهجري :1321","الشهر القمري : ربيع الأول","العام الميلادي :1903"],"text":"بعد أن استقرَّ حُكمُ الملك عبد العزيز في الرياض والخرج والدلم وما حولها، اتجه نحو شمال الرياض وقصَدَ بلاد الوشم وسدير والمجمعة التي كانت خاضعةً لحكم ابن رشيد، فدارت اشتباكات بين حاميات ابن رشيد وسرايا الملك عبد العزيز، نتج عنهما ضمُّ الإقليمين إلى حكم الملك عبدالعزيز ما عدا بلدة المجمعة التي ظلت محافِظةً على ولائها لابن رشيد، ولم تخضع إلا بعد مقتَلِه في روضةِ مهنا سنة 1324هـ ودخول القصيم تحت حكمِ الملك عبد العزيز."},{"id":4780,"title":"مهاجمة القوات البريطانية لقوات الدراويش أتباع مهدي الصومال .","date":["العام الهجري :1321","الشهر القمري : شوال","العام الميلادي :1904"],"text":"هاجمت القواتُ البريطانية قواتِ الدراويش التابعةَ لمهدي الصومال سيد محمد بن عبد الله، الذي كان يلقِّبُه الاستعمار بـالملَّا المجنون. واستمر المهديُّ في مقاومة الاستعمار البريطاني في الصومال حتى عام 1920 عندما لجأت بريطانيا إلى الطيرانِ لقَصفِ مواقِعِ الثوار أتباع مهدي الصومال، ثمَّ جاءت وفاةُ المهدي سيد محمد التي انتهت بها ثورتُه الإسلاميَّةُ."},{"id":4781,"title":"الدولة العثمانية تفاوض الملك عبد العزيز بن سعود في القصيم .","date":["العام الهجري :1322","العام الميلادي :1904"],"text":"أثناء معارك القصيم مع ابن رشيد أصبح وضع الملك عبد العزيز بن سعود قويًّا خاصةً بعد معركة الشنانة. واتضح للعثمانيين فشَلُ تجربتهم العسكرية في تلك المنطقة، وأدركوا أنَّ الأمر ليس بالسهولة التي صوَّرها لهم ابنُ رشيد، وأنَّ عليهم مراجعةَ حساباتهم تجاه الملك عبدالعزيز الذي اتضح أنه يتمتَّعُ بشعبية واسعة في القصيم وفي نجد كلها، فأرادت الدولة أن يكون لها يدٌ داخِلَ الجزيرة بالتدخُّل في حلِّ مشكلة القصيم سلميًّا بين الطرفين، فأرسلت أحمد فيضي باشا، وصدقي باشا، وطلبا من مبارك أن يتوسَّط لهم عند الإمام عبد الرحمن بن فيصل؛ من أجل قبول حاميات الدولة في القصيم، وأن تكون القصيم على الحياد بين ابن رشيد والملك عبدالعزيز، وقَبِلَ عبد الرحمن هذا العرضَ بشرط أن يعرِضَه على أهل نجد وابنه عبد العزيز، إلَّا أن أهل نجد رفضوا فكرة بقاء القصيم على الحياد، وكذلك رفضوا وجودَ أي حامية للدولة العثمانية في القصيم، ففَشِلت محاولاتُ المفاوضات خاصَّةً بعد ثورة الإمام يحيى حميد الدين في صنعاء ضِدَّهم  فاضطرت الدولةُ العثمانية أن تكَلِّفَ أحمد فيضي باشا بالتوجُّه إلى اليمن سريعًا."},{"id":4782,"title":"وفاة الصحفي اليهودي تيودور هرتزل زعيم المنظمة الصهيونية العالمية .","date":["العام الهجري :1322","العام الميلادي :1904"],"text":"هو تيودور هرتزل (بنيامين زئيف هرتزل) صحفيٌّ يهوديٌّ نمساويٌّ مَجَري، مؤسِّسُ الصهيونية السياسية المعاصِرة. ولِدَ في بودابست 1860م، وتلقَّى تعليمًا يطابقُ روحَ التنوير الألماني اليهودي السائدِ في تلك الفترة، الذي يغلِبُ عليه في صُلبِه الطابَعُ الغربي النصراني حتى سنة 1878م. اشتغل هرتزل بالصحافةِ في باريس كمراسِلٍ للصحيفة الفيينية المهمَّة آنذاك من عام 1891 إلى 1896م وحينها تشكَّلَت أفكارُه الصهيونية بعد أن عايش قضيَّةَ دريفوس، وهو نقيبٌ فرنسي يهودي اتُّهِمَ بالخيانةِ العُظمى بأنَّه أرسل ملفاتٍ فرنسيَّةً سرِّيةً إلى ألمانيا, فانقسم المجتمَعُ الفرنسي بين مؤيِّد له ومقتَنِعٍ ببراءتِه، ومعارضٍ يصِفُه بالخيانِة والعَمالة. كان المجتَمَعُ الفرنسي حينها يعادي الساميةَ وشديدَ الكراهية للإمبراطورية الألمانية. تابع هرتزل أحداثَ قضيةَ دريفوس في مراسلاتِه الصحفية, وهرتزل اليهوديُّ المندمج مع الأوربيين أصبح يفكِّرُ في المشكلة اليهودية وفي ضرورةِ إيجاد حلٍّ غيِر اندماج وانصهار اليهودِ في مجتمعات أوروبا الشرقيَّة والغربية، فالتيارُ المعادي للسَّامية، ورغبةُ اليهود في إثبات وجودِهم كشعب، يدعوان إلى البحثِ عن بديلٍ للاندماج، فجاءت الإجابةُ في الكُتَيِّب الذي انتهى من تأليفه يوم 17 يونيو 1895 والذي نُشِرَ سنة 1896 تحت عنوان: (الدولة اليهودية). وإن لم يجِدِ الكُتَيِّب صدًى واسعًا في البداية إلَّا أنه وَضَع فعلًا حجرَ الأساس لظهورِ الصهيونية السياسيَّة وتأسيسِ الحركة الصهيونية بعد انعقادِ المؤتمر الصهيوني الأول في بازل بسويسرا عام 1897م، والذي دعا لعقده هرتزل، وجمع له أساطينَ اليهود من حاخامات يهود وسياسيين وإعلاميين ورجال أعمال، وانتُخِبَ فيه هرتزل رئيسًا للمنظَّمة الصهيونية العالمية، وأُعطِيَ الصلاحيَّات في السعيِ لإقامة وطنٍ قومي لليهود في فلسطين، ووُعِدَ بالدعم المادي لتحقيقِ هذا الغرض، وبدأ بمقابلة عددٍ مِن شخصيات عديدةٍ من دول مختلفة، مثل: القيصر الألماني، و السلطان العثماني عبد الحميد الثاني؛ بحثًا عن مؤيدين للمشروع الصهيوني. لكنَّ جهودَه فَشِلت وتَرَكت المجال مفتوحًا لمواصلة العمل على تأسيس الدولة اليهودية, وهلك هرتزل هذا العامَ بمدينةِ فيلاخ في النمسا."},{"id":4783,"title":"معركة البكيرية .","date":["العام الهجري :1322","الشهر القمري : ربيع الآخر","العام الميلادي :1904"],"text":"وقعت هذه المعركة بين قوات عبد العزيز بن متعب بن رشيد وقوات الملك عبد العزيز بن سعود، كان ابن رشيد قد قام بمصادرةِ ما وَجَد من إبل العقيلات من أهل القصيم الذين كانوا يجوبون البلاد للتجارة بين العراق والشام ومصر وشبه الجزيرة العربية، وحمَّل عليها قسمًا كبيرًا مما حصل عليه من أطعمةٍ ومُؤَن وأسلحة نقلها من العراق إلى نجد، وأسرع إلى القصيمِ بمن اجتمع لديه من البدو خاصَّةً من قبيلة شمر، وفئات من الحضر وعساكر الدولة من عراقيين وسوريين، ونشب القتالُ بين الطرفين، ورَجَحت كِفَّةُ ابن رشيد في بداية المعركة؛ إذ ركَّز نيران مدافعه ضِدَّ القسم الذي يقوده الملك عبدالعزيز؛ مما ألحق به خسائِرَ بشرية كبيرة وأرهق قواته، اضطرَّ بعدها الملك عبدالعزيز إلى التراجُعِ إلى جهة بلدة المذنب، ولكِنَّ أهل القصيم لم يعلموا بتراجع الملك عبدالعزيز، وحقَّقوا تقدُّمًا ضِدَّ الجنود النظاميين المحارِبين في صفوف ابن رشيد، فحوَّلوا الهزيمة إلى نصر، وأسَرُوا عددًا من أولئك الجنود وغَنِموا بعضَ المدافع وعادوا إلى البكيرية مع الليل، وعلى الرغم من ذلك فإن قواتِ ابن رشيد ظلَّت متماسكةً وثابتة، وانتقل بقواته حيث عسكر في الشنانة مركز قوَّاته في القصيم."},{"id":4784,"title":"معركة الشنانة  .","date":["العام الهجري :1322","الشهر القمري : رجب","العام الميلادي :1904"],"text":"وقعت هذه المعركة بين قوات الملك عبد العزيز وحاكم حائل عبد العزيز بن متعب بن رشيد، بمحافظة الشنانة بالقصيم، وبدعمٍ مِن أهل الشنانة انتصرت فيها قوات الملك عبد العزيز، وكانت هذه المعركة قاصمةَ الظهر لابن رشيد الذي تحوَّل بعدها من الهجوم إلى الدفاع. وقد قام ابن رشيد وقواته بتخريبِ الشنانة وقطْع نخيلها وتعذيب أهلها نظيرَ وقوفِهم في وجهِه ودعْمِهم للملك عبد العزيز."},{"id":4785,"title":"وفاة الشاعر محمود سامي البارودي .","date":["العام الهجري :1322","الشهر القمري : شوال","العام الميلادي :1904"],"text":"هو الشاعِرُ محمود سامي باشا بن حسن حسني بن عبد الله البارودي المصري, جركسي الأصلِ من سلالةِ المقام السيفي نوروز الأتابكي. ولِدَ بالقاهرة سنة 1255ه، وهو من أوائِلِ من نهض بالشعرِ العربيِّ في عصرنا الحاضر، كان البارودي إلى جانبِ موهبتِه الشعريَّةِ رجلًا عَسكريًّا وسياسيًّا، وهو من تلاميذِ جمال الدين الأفغاني وممَّن تأثَّر بفِكرِه وطرحِه السياسيِّ، رحل الباروديُّ إلى الأستانة فأتقَنَ الفارسيَّةَ والتركية، وله فيهما قصائِدُ، ثم عاد إلى مصر فكان من قوَّاد الحملتينِ المصريتينِ لِمساعدة تركيا الأولى في ثورة (كريد) سنة 1868م، والثانية في الحرب الروسية سنة 1877م، ولَمَّا حدثت (الثورة العُرابية) كان في صفوفِ الثائرين. تقلَّد منصِبَ الوَزارةِ، ورأَسَ الوزارةَ العُرابية، وبعد فَشلِها نفِيَ مع قادتها إلى سريلانكا، وبعد عودته من منفاه سنة 1317هـ مكث بضعَ سنواتٍ ثمَّ توفِّيَ بالقاهرةِ سنة 1322هـ"},{"id":4786,"title":"إخضاع الإنجليز مسلمي البنغال لسيطرة الهندوس .","date":["العام الهجري :1323","العام الميلادي :1905"],"text":"قام الإنجليزُ بتقسيمِ البنغال إلى قِسمَين غربي وشرقي، وذلك على أساسٍ دينيٍّ بين المسلمين والهندوس، وعارض الهندوس هذا التقسيمَ؛ إذ فقدوا حسَبَ رأيهم السيطرةَ على ولاية مهمةٍ، وعَمَّهم الحزن وأضربوا واجتَمَعوا عند صَنمِهم كالي، إله التدمير -حسب عقليَّتِهم- وتعاهدوا على مقاطعةِ البضائعِ الإنجليزية، وطالب المسلِمون في العام التالي بإجراءِ انتخاباتٍ منفصلة، وتَرْك الانتخابات المشتركة، وذهب وفدٌ منهم لمقابلة نائبِ الملك في مقرِّه الصيفي في سيملا، وقد سُرَّ المسلمون بتقسيم البنغال، إلَّا أن الأمرَ لم يدُمْ طويلًا؛ ففي عام 1329هـ / 1911م أُلغي هذا التقسيمُ على لسان الملك جورج في حفلةِ تتويجه إمبراطورًا في مدينة دلهي؛ ليبقى المسلمون تحت سيطرةِ الهندوس ونفوذِهم."},{"id":4787,"title":"مؤتمر الجزيرة الخاصة بالمغرب .","date":["العام الهجري :1323","العام الميلادي :1905"],"text":"كان من محاولات فرنسا للتدخُّلِ في المغرب دون أن تواجِهَ الخصومَ الأوربيين أنْ عَقَدت الاتفاقياتِ معهم، فعقدت مع إيطاليا اتفاقًا بأن تترك لها طرابلس، ثم عقدت مع بريطانيا اتفاقًا على أن تتركَ لها حرية التصرُّفِ في مصر مع بقاء معاهدة إنجلترا القديمة مع مراكش ساريةَ المفعول، ولاقت هذه الاتفاقيةُ قَبولًا أسبانيًّا لكنَّها لاقت رفضًا ألمانيًّا؛ حيث جاء الإمبراطور غليوم إلى طنجة في هذا العام وألقى خطابًا أعلن فيه صداقة ألمانيا لسلطان مراكش، ولوَّح بالتهديد لمن يعتدي على السلطان وبلادِه، وحاول إحباطَ المؤامرة الفرنسية الإنجليزية الأسبانية، ثم حاول السلطانُ عبد العزيز ومجلِسُ أعيانه أن يعرِضوا أمرَ مراكش على مؤتمرٍ دولي إضعافًا للنفوذ الفرنسي، وانعقد مؤتمرُ الجزيرة في ذي القعدة 1323ه إلى ربيع الثاني 1324هـ، وحضره ممثِّلو خمس عشرة دولة، ومِن أهمِّ ما جاء فيه أنَّه تمَّ الاعتراف بسيادة السلطان واستقلالِه ووَحدةِ أراضيه، ومساواة الدُّوَل جميعًا في تجارتها مع مراكش، وتشكيل قوةٍ من الشُّرطة لحفظ الأمن الداخلي تكونُ فرنسية أسبانية بإمرة سويسريةٍ، وتوضَعُ الجمارك تحت رقابةٍ دولية، وتوزَّعُ امتيازاتُ المشروعات الاقتصادية بين شركاتِ مختَلفِ الدول، ولم يقنَعِ المغاربة بقراراتِ هذا المؤتمر؛ لذلك ثاروا على سلطانهم وخَلَعوه."},{"id":4788,"title":"تعرض السلطان العثماني عبد الحميد الثاني لمحاولة اغتيال فاشلة .","date":["العام الهجري :1323","الشهر القمري : جمادى الأولى","العام الميلادي :1905"],"text":"تعرَّض السلطانُ العثماني عبد الحميد الثاني لمحاولةِ اغتيالٍ فاشلةٍ دَبَّرها الأرمن بإيعازٍ وتشجيعٍ مِن الحركة الصهيونية اليهودية العالَمية، وعُرِفَ هذا الحادِثُ في التاريخ العثماني باسم \"حادث القنبلة\". كلَّف يهود سويسرا إدوارد جورج اليهوديَّ الفرنسيَّ الجنسية بالتعاونِ مع أعضاء جمعية الطاشناق الماسونية الأرمنية لإدخالِ عَرَبة إلى استانبول، فوصلت إلى استانبول قِطعةً قطعةً، وتمَّ تركيبُها لتكون قنبلةَ جحيمٍ تنفَجِرُ في الوقتِ الذى يخرجُ فيه السلطان عبد الحميد من مسجِدِ محمد الفاتح بعد صلاةِ الجمعة، فانفَجَرت، ولم يتِمَّ لهم ما أرادوا، وجرَّاء هذا التفجيرِ لقيَ عشرون شَخصًا مَصرعُهم، وقُبِضَ على المنَفِّذين الأرمن بالبابِ العالي، فتدخَّل السفير الأرمن لحمايتهم بحُجَّة الامتيازات الأجنبية، وتمَّ له ما أراد. ولم يكُنْ حادِثُ القنبلة المحاوَلةَ الوحيدة للأرمن لاغتيالِ السلطان عبد الحميد."},{"id":4789,"title":"وفاة الشيخ محمد عبده .","date":["العام الهجري :1323","الشهر القمري : جمادى الأولى","العام الميلادي :1905"],"text":"هو الشيخُ محمد عبده بن حسن خير الله مِن آلِ التركماني، مفتي الدِّيارِ المصريَّةِ، وأحَدُ دُعاةِ ما يسمى بالنهضة والإصلاح في العالمِ العربي والإسلاميِّ، وأحدُ رموزِ دعاةِ التجديدِ في الفِقهِ الإسلاميِّ، ساهمَ بعد التقائه بأستاذِه جمال الدين الأفغاني في إنشاءِ حركة فكريةٍ تجديديةٍ في أواخر القرن التاسع عشر وبدايات القرن العشرين، تهدفُ إلى القضاء على الجُمودِ الفِكريِّ والحضاريِّ، وإعادةِ إحياء الأمَّة الإسلاميَّة لِتُواكِبَ مُتطلباتِ العصرِ. ولِدَ محمد عبده سنة 1849م مِن أبٍ تركماني وأم مصريةٍ في قرية محلة نصر بمركز شبراخيت في محافظة البحيرة, ونشأ في محلةِ نصر (بالبحيرة) وأحَبَّ في صباه الفروسيَّةَ والرمايةَ والسباحة. وتعلَّمَ بالجامِعِ الأحمدي بطنطا، ثم بالأزهرِ. تصَوَّف وتفلسَفَ، وعَمِلَ في التعليم، وكتَبَ في الصُّحُفِ. في سنة 1866م التحق بالجامِعِ الأزهر، وفي سنة 1877م حصل على الشهادة العالمية، وفي سنة 1879م عَمِلَ مدرسًا للتاريخِ في مدرسة دار العلوم، وفي سنة 1882 م اشترك في ثورة أحمد عرابي ضِدَّ الإنجليز، وبعد فَشَلِ الثورة حُكِمَ عليه بالسجنِ ثمَّ بالنفي إلى بيروتِ لِمدة ثلاث سنوات، ثم سافر بدعوةٍ مِن أستاذه جمال الدين الأفغاني إلى باريس سنة 1884 م، وأسَّسا صحيفةَ العروة الوثقى، وفي سنة 1885 م غادر باريسَ إلى بيروت، وفي ذات العام أسَّسَ جمعية سرِّية بنفس الاسم: العروة الوثقى. قيل إنَّها ذات صلة بالمحافلِ الماسونية العالمية تحت زعمِ التقريبِ بين الأديان. وفي سنة 1886م اشتغل بالتدريسِ في المدرسة السُّلطانية في بيروت، وفي سنة 1889م-1306هـ عاد محمد عبده إلى مصر بعفوٍ مِن الخديوي توفيق، ووساطةِ تلميذه سعد زغلول، وبعد إلحاحِ الأميرة نازلي فاضل على اللورد كرومر كي يعفوَ عنه ويأمُرَ الخديوي توفيقًا أن يُصدِرَ العَفوَ عنه، أصدر الخديوي قرارَ العفوِ بعد أن اشترط اللورد كرومر على محمَّد عبده ألَّا يعمَلَ في السياسة، فقَبِلَ. وفي سنة 1889م عُيِّنَ قاضيًا بمحكمة بنها، ثم انتقل إلى محكمة الزقازيق، ثم محكمة عابدين، ثم ارتقى إلى منصبِ مُستشار في محكمةِ الاستئنافِ عام 1891م، وفي 3 يونيو عام 1899م (24 محرم عام 1317هـ) عيِّنَ في منصِبِ المفتي، وتبعًا لذلك أصبح عُضوًا في مجلس الأوقافِ الأعلى. وفي 25 يونيو عام 1890م عين عضوًا في مجلسِ شورى القوانين. وفي سنة 1900م (1318هـ) أسَّس جمعيةَ إحياء العلوم العربية لنشر المخطوطاتِ. وزار العديدَ من الدول الأوروبية والعربية. وقد تأثَّر به عددٌ من قادةِ النهضةِ الحديثةِ في الفكر والسياسة والعلم، منهم: محمد رشيد رضا، وسعد زغلول، وعبد الحميد بن باديس، وعبد الرحمن الكواكبي، وغيرهم, وفي الساعة الخامسة مساء يوم 7 جمادى الأولى توفِّي الشيخ بالإسكندرية بعد معاناةٍ مِن مرض السرطان عن سبع وخمسين سنة، ودُفِنَ بالقاهرة."},{"id":4790,"title":"حادثة قرية دنشواي في مصر .","date":["العام الهجري :1324","العام الميلادي :1906"],"text":"في يومِ الأربعاء الثالث عشر من يونيو 1906م كانت قرية دنشواي تعيشُ في هدوء حتى دخَلَها على غير موعدٍ عددٌ من أفرادِ كتيبةٍ إنجليزيَّةٍ كانت تتحَرَّك من القاهرة إلى الإسكندرية، وبدؤوا في اصطياد الحمام الذي يربِّيه الأهالي، وبجوارِ أجران القمح -موضع يُداس فيه القَمحُ- التي لا تخلو من وجودِ أصحابها بجوارِها، وبينما هم كذلك أصابت رصاصةٌ زوجةَ مؤذِّن القرية (صاحب أحدِ الأجران) وأشعلت رصاصةٌ ثانيةٌ النَّارَ في جرن القمحِ، فهبَّت القريةُ كُلُّها في وجهِ الغُرَباءِ الذين اعتَدَوا على قريتِهم وأشعلوا فيها النيرانَ، وجرت مواجهةٌ محدودةٌ بين الأهالي والغرباءِ أصيب على إثرِها عددٌ من الأهالي، بينما فرَّ أحَدُ الضباطِ هاربًا تحت الشمسِ الحارقة وأصابته ضربةُ شمس أودت بحياتِه. طار الخبَرُ إلى أهل الحُكمِ وبلغت الأنباءُ الكتيبةَ الإنجليزيةَ التي كانت على مَقرُبة من موقع الحادث، فصدرت الأوامِرُ إليها بالتحرُّكِ لنجدة أفرادها، وتقدَّموا إلى دنشواي في هجومٍ انتقاميٍّ على أهالي القرية العزَّلِ، وجرت الاعتقالاتُ العشوائيةُ، وتم نصبُ المشانِقِ قبل المحاكَمةِ نَفسِها، وتجلَّت مظاهرُ انتقام جيشِ الاحتلال من قريةٍ مِصرية عَزلاءَ حاولت الدفاعَ عن نفسها ضِدَّ غرباءَ دخلوها بلا استئذانٍ، وعاثوا فيها فسادًا ولهوًا وعبثًا! حتى صدر في العشرين من يونيو قرارُ وزير الحقَّانية النَّصراني بطرس غالي باشا بتشكيل المحكمة لمحاكمة 59 متهمًا وترأَّس المحاكَمةَ بُطرس غالي نفسُه، وكان عضوًا بها أحمد فتحي بك زغلول (شقيق سعد زغلول) مع ثلاثة قضاة من الإنجليز، وقام إبراهيمُ الهلباوي بدور المدَّعي العام، وبعد أسبوع من تاريخه صدرت الأحكامُ القاسية بإعدامِ أربعةٍ مِن أهالي دنشواي والسجنِ المؤبَّد لاثنين، والأشغال الشاقة لمُدَد أخرى مع جَلدِ عدَدٍ من المتهمين، وتم التنفيذ بطريقةٍ غاية في البشاعةِ والهمجيَّة؛ حيث تمَّ حَشدُ الأهالي لمشاهدة المجزرة البَشِعة، ثمَّ إن مصطفى كامل قام بأكبر حملةٍ في أوروبا يفضحُ فيها جرائِمَ الإنجليز في مصرَ، ويطالب بالجلاءِ والاستقلال، ومِمَّا كتبه في هذه الفترة مقالٌ نشرته (الفيجارو) الفرنسية."},{"id":4791,"title":"معركة روضة مهنا .","date":["العام الهجري :1324","الشهر القمري : صفر","العام الميلادي :1906"],"text":"حدثت بين قوات إمارة جبل شمر بقيادة عبد العزيز بن متعب آل رشيد يسانده 200 جندي عثماني، وبين قوات الملك عبد العزيز في روضة مهنا بمنطقة القصيم، حيث دارت اشتباكاتٌ ليلية خفيفة وعنيفة قُتِلَ فيها ابن رشيد على يدِ أهل القصيم عندما دخل وسطَ قواتِ الملك عبد العزيز ظنًّا منه أنهم قواتُه، فانهالوا عليه ببنادقهم فخَرَّ صريعا وقطَعوا رأسَه ووصلوا به إلى بريدة ثم عنيزة، وانتهت المعركة بانتصار الملك عبد العزيز بعد مصرعِ ابن رشيد وانسحاب القوات العثمانية من القصيم بأمانٍ، مقابل تسليم مدافعهم لقوات الملك عبد العزيز الذي أعلن سيادتَه على القصيم بأكملِه."},{"id":4792,"title":"وفاة الأمير عبد العزيز بن متعب ابن رشيد أمير جبل شمر .","date":["العام الهجري :1324","الشهر القمري : صفر","العام الميلادي :1906"],"text":"هو الأمير عبد العزيز بن متعب بن عبد الله العلي الرشيد مِن الجعفر من قبيلة شمر من أمراء آل رشيد أصحاب حائل وما حولها بنجد. وَلِيَها بعد وفاة عمه محمد بن عبد الله الرشيد سنة 1315هـ، كان من أشجع العرب في عصره، وأصلَبِهم عودًا. بدأ حكمه في ظل قبولٍ تامٍّ له من قِبَل الأهالي وأفراد أسرته، وكان ذا ميول عسكرية وتوسُّعية، فاهتمَّ كثيرًا بالشأنِ العسكريِّ وكوَّن جيشًا عَزَّز به جميعَ مناطق نفوذه. له وقائِعُ وغاراتٌ كثيرة مع مبارك بن صباح صاحب الكويت، والملك عبد العزيز بن سعود، وأمير المنتفق. وفي أيامه استرجع منه الملك عبد العزيز مدينةَ الرياض سنة 1319هـ، وظلَّ ابن رشيد يصاوِلُ خصومَه، ويقابِلُ الغارات بمثلها، إلى أن قُتِلَ في روضة المهنا بالقصيم. خَلَفَه في إمارة حائل بعد مقتله ابنُه متعب."},{"id":4793,"title":"تعديل الحدود بين الدولة العثمانية ومصر .","date":["العام الهجري :1324","الشهر القمري : شعبان","العام الميلادي :1906"],"text":"تمَّ تعديلُ الحدود بين الدولة العثمانية ومصرَ على أساسِ حدود مصرَ الحاليَّةِ في سيناء، وتمَّ اعتبار \"طابا\" ضِمنَ الأراضي المصرية، و\"العَقَبة\" ضمن الأراضي العُثمانية."},{"id":4794,"title":"ثورة المغرب يقودها عبد الكريم الخطابي ضد الأسبان والفرنسيين .","date":["العام الهجري :1325","العام الميلادي :1907"],"text":"ظهر الأميرُ محمد عبد الكريم الخطَّابي عام 1921 م في منطقة الريف، واستطاع أن يفجِّرَ الثورة فيها ضدَّ الأسبان وأن يحقِّقَ العديد من الانتصارات على الأسبان، وأصبح وجودُ الأسبان قاصرًا على مدينة تطوان وبعض الموانئ والحصون في الجبال، وأسَّسَ الأميرُ إدارةً منظمة للمناطِقِ المحرَّرة وحكَمَها حكمًا شبيهًا بالحُكمِ الجُمهوري الرئاسي، وألَّف مجلِسًا لرؤساء القبائل، وجعل الوزراءَ مسؤولين أمام هذا المجلس، وأعلن الخطابيُّ أنَّ أهداف حكومتِه هي طرد الأسبان والفرنسيين من المغرب، وتحريرُ باقي بلاد المغرب العربي. ولم يقتصِرْ جهاد الأمير على القتالِ ضِدَّ الأسبانِ، بل إنَّه استخدم جمهوريةَ الريف التي شكَّلَها في الضغطِ على القوات الفرنسية، وتحريضِ القبائل على التمَرُّد والعصيان في منطقة النفوذ الفرنسي، بدءًا من عام 1925م، وبدأت الصدماتُ المتواليةُ تقعُ بين الأمير والقوات الفرنسية، وأوقع بالفرنسيين خسائِرَ فادحة. وكان من الطبيعيِّ إزاء تلك القوَّةِ الصاعدة التي تمتلِكُ قائدًا كُفئًا ومقاتلين شجعان: أن تتجَمَّعَ القوى الاستعمارية ضِدَّها، فتَمَّ عَقدُ مؤتمر بين أسبانيا وفرنسا في مدريد عام 1925م لتنسيق الأعمالِ الحربيَّة بينهما ضِدَّ الأمير عبد الكريم الخطابي، وتدفَّقَت القوات الفرنسية والأسبانية على المغربِ، بل وأيضًا تم استخدامُ بعض المرتزقة من الطيارين الأمريكان في تلك المعركة، وحَشَدت فرنسا وأسبانيا قواتِها البحريةَ والبرية والجويةَ كمحاولة للقضاء على الأميرِ، واستطاع الأميرُ أن يصمُدَ من مايو 1925م إلى مايو 1926م أي: عامًا كاملًا، أمام جحافِلِ دولتين أوربيتين، هما فرنسا وأسبانيا، وأخيرًا تم القضاءُ على قوات الأمير، وسقط في الأسْرِ."},{"id":4795,"title":"إنشاء خط لسكة الحديد بين المدينة المنورة ودمشق .","date":["العام الهجري :1325","العام الميلادي :1907"],"text":"عَمِلَ السلطانُ عبد الحميد على كَسبِ الشعوب الإسلامية عن طريقِ الاهتمامِ بكلِّ مؤسَّساتها الشرعيَّة والعِلميَّة، والتبَرُّع لها بالأموالِ والمِنَح، ورَصد المبالغ الطائلة لإصلاحِ الحَرَمين، وترميمِ المساجِدِ وزَخرفتها، وأخذ السلطانُ يستميل إليه مسلمي العربِ بكلِّ الوسائِلِ، فكوَّن له من العَرَبِ حرسًا خاصًّا، وعيَّنَ بعضَ الموالين له منهم في وظائِفَ كبرى، وأبدى السلطان عبد الحميد اهتمامًا بالغًا بإنشاءِ الخطوطِ الحديديةِ في مختَلِفِ أنحاءِ الدولة العثمانية، مُستهدفًا من ورائها تحقيقَ ثلاثةِ أغراضٍ: 1- ربطُ أجزاءِ الدولة المتباعدةِ مع بعضٍ؛ ممَّا يساعِدُ على نجاح فكرةِ الوَحدةِ العُثمانية، والجامعة الإسلامية، والسيطرة الكاملة على الولاياتِ التي تتطلَّبُ تقويةَ قَبضةِ الدولة عليها. 2- إجبارُ تلك الولاياتِ على الاندماجِ في الدولةِ والخضوعِ للقوانينِ العَسكرية التي تنُصُّ على وجوبِ الاشتراكِ في الدفاعِ عن الخلافةِ بتقديمِ المالِ والرِّجال. 3- تسهيلُ مُهمَّةِ الدفاع عن الدولة في أيَّةِ جبهةٍ من الجبهاتِ التي تتعرَّضُ للعدوانِ؛ لأنَّ مَدَّ الخطوطِ الحديديَّةِ سيُساعِدُ على سرعةِ توزيع القواتِ العثمانية وإيصالِها إلى الجبهاتِ.وكانت سكةُ حديد الحجاز من أهمِّ الخطوط الحديدية التي أُنشِئت في عهدِ السلطان عبد الحميد؛ ففي سنة 1900م بدأ بتشييدِ خطٍّ حديدي من دمشق إلى المدينة؛ للاستعاضة به عن طريق القوافِلِ الذي كان يستغرِقُ من المسافرين حوالي أربعين يومًا، وطريقِ البحرِ الذي يستغرقُ حوالي اثنى عشر يومًا من ساحلِ الشامِ إلى الحجاز، وكان يستغرِقُ من المسافرين أربعة أو خمسة أيام على الأكثَرِ، ولم يكن الغَرَضُ من إنشاء هذا الخطِّ مجرَّدَ خدمة حجَّاج بيت الله الحرام وتسهيل وصولهم إلى مكَّة والمدينة، وإنما كان السلطان عبد الحميد يرمي من ورائِه أيضًا إلى أهدافٍ سياسيةٍ وعسكريةٍ؛ فمن الناحية السياسية خَلَق المشروعُ في أنحاء العالم الإسلامي حماسةً دينيةً كبيرةً؛ إذ نشر السلطانُ على المسلمين في كافة أنحاء الأرضِ بيانًا يناشِدُهم فيه المساهمةَ بالتبَرُّع لإنشاء هذا الخط، وقد افتتح السلطانُ عبد الحميد قائمةَ التبرعات بمبلغ (خمسين ألفًا ذهبًا عثمانيًّا من جيبه الخاصِّ) وتقَرَّر دفع (مائة ألف) ذهب عثماني من صندوق المنافع، وأُسِّست الجمعيَّاتُ الخيرية، وتسابق المسلمون من كلِّ جهةٍ للإعانة على إنشائِها بالأنفُسِ والأموالِ، ورغم احتياجِ المشروع لبعض الفنِّيين الأجانب في إقامة الجسور والأنفاق، فإنَّهم لم يُستخدَموا إلا إذا اشتَدَّت الحاجة إليهم، مع العلمِ بأنَّ الأجانب لم يشتركوا إطلاقًا في المشروع، ابتداءً من محطةِ الأخضر -على بعد 760 كليو مترًا جنوب دمشق- وحتى نهايةِ المشروع؛ ذلك لأنَّ لجنة المشروع استغنت عنهم واستبدلت بهم فنيين مصريين. وبلغ عدد العمال غير المَهَرة عام 1907م (7500) عاملًا. وبلغ إجمالي تكاليف المشروع (4.283.000) ليرة عثمانية. وتم إنشاءُ المشروع في زمنٍ وتكاليف أقلَّ مما لو تعمله الشركات الأجنبية في أراضي الدولةِ العثمانية، وفي أغسطس سنة 1908م وصل الخطُّ الحديدي إلى المدينة المنورة، وكان مفروضًا أن يتِمَّ مَدُّه بعد ذلك إلى مكةَ، لكنْ حدث أن توقَّف العملُ فيه؛ لأنَّ شريف مكة -وهو الحسين بن علي- خشِيَ على سُلطاته في الحجاز من بطشِ الدولة العثمانية، فنهض لعرقلةِ مَدِّ المشروع إلى مكَّةَ، وكانت مقَرَّ إمارتِه وقوَّته. فبقيت نهايةُ الخط عند المدينة المنورة، حتى إذا قامت الحرب العالمية الأولى عَمِلَ الإنجليزُ بالتحالف مع القوات العربية التي انضَمَّت إليهم بقيادة فيصل ابن الشريف حسين بن علي على تخريبِ سكةِ حديد الحجاز، وكان أوَّلُ قطار قد وصل إلى محطة سكة الحديد في المدينة المنورة من دمشق الشام يوم 22 (أغسطس) 1908م، وكان بمثابة تحقيقِ حُلمٍ مِن الأحلام بالنسبة لمئات الملايين من المسلمين في أنحاء العالم كافة؛ فقد اختصر القِطارُ في رحلته التي استغرَقَت ثلاثة أيام، وقطع فيها 814 ميلًا مشقَّاتِ رحلةٍ كانت تستغرق في السابق أكثَرَ من خمسة أسابيعَ، ويسَّرت على المسلمين القيامِ بأداء فريضة الحَجِّ."},{"id":4796,"title":"تمرد قبيلة مطير بزعامة فيصل الدويش وتحالفها مع ابن رشيد .","date":["العام الهجري :1325","العام الميلادي :1907"],"text":"تمرَّد بعضُ رؤساء عشائر قبيلة مطير على الملك عبدالعزيز، وتحالفوا مع أمير بريدة محمد بن عبد الله أبا الخيل، على أن يكونوا من أنصار ابن رشيد ضِدَّ الملك عبدالعزيز الذي تحالف مع قبيلة عتيبة خصوم مطير وشمر، فنشبت قربَ مدينة المجمعة في سدير معركةٌ بين قبيلة مطير بقيادة فيصل الدويش وقوات الملك عبدالعزيز المكَوَّنة بالأساس من قبيلة عتيبة. وهُزمت مطيرٌ، وأصيب فيصل الدويش بجراحٍ في هذه المعركة، فطلب الصلح وأعرب عن خضوعِه للملك عبدالعزيز."},{"id":4797,"title":"إنشاء مدرسة القضاء الشرعي بمصر .","date":["العام الهجري :1325","الشهر القمري : صفر","العام الميلادي :1907"],"text":"ساءت أحوالُ المحاكم الشرعيةِ في مصر، بعد أن بدأ محمد علي باشا وخلفاؤه في تغييرِ الوضع القضائي المستقِرِّ في البلاد منذ مئات السنين، بإيجاد كيانٍ جديدٍ لا يعتَمِدُ على القضاء الشرعيِّ، بل يتَّجِهُ إلى التَّقنين الأوربيِّ الحديث، وانحصر دورُ المحاكم الشرعية في نظَرِ قضايا الأحوال الشخصيَّة والمواريث والوقفِ، وتسلَّل إليها الفسادُ بعد أن أدارت لها الدولةُ ظَهرَها ولم تقَدِّمْ إليها يدَ العون. وظل الأمرُ على هذا النحو من الإهمال إلى أن قامت نظارةُ الحقانية (العدل) بانتدابِ محمد عبده لتفَقُّد أحوال المحاكِمِ الشرعية، ومعرفة أدوائها، ووضْعِ أفضلَ السبل لعلاجِها. فقدَّم تقريرًا لِما وصلت إليه أحوالُ تلك المحاكِمِ من سوء الحال في الأماكِنِ والمباني والأثاث، وضَعْف في مستوى القُضاة والكَتَبة، وقصورِ المرافعاتِ فيها. وفي الوقتِ نفسِه كشَفَ التقريرُ عن تقصير الحكومةِ تجاه هذه المحاكِمِ، وإهمالها لشأنها حتى وصلت إلى ما هي عليه من ضَعفٍ وفسادٍ. وتضَمَّن التقريرُ وسائل النهوض بتلك المحاكِمِ مِن توسيع اختصاصاتِها، وعدمِ تقييدها في إصدارِ الأحكامِ بالمذهبِ الحنفيِّ، والنهوض بمستوى القُضاة وتحسين مرتَّباتهم، وانتقاء العناصِرِ الجيدة للعمل في هذا الميدان، وتسهيلِ إجراءات التقاضي، وخُتِمَ التقريرُ بطلب إنشاء معهدٍ خاص يُختارُ طَلَبتُه ممن يدرسونَ في الأزهر، ويُعَدَّوُن إعدادا خاصا لتولي منصب القضاء. ثمَّ تشكَّلت لجنةٌ برئاسة ناظر الحقانية (وزير العدل) وعضوية قاضي البلاد، وشيخ الجامع الأزهر، والمفتي، وأحد أعضاء محكمة مصر العليا؛ للنظر في التقرير, فصدر منشورٌ في 16 صفر بإنشاء مدرسةِ القضاء الشرعي، وانقسمت المدرسةُ إلى قسمين: الأول: لتخريج الكَتَبة، والثاني: لتخريجِ القُضاة والمحامين. وظلت المدرسةُ قائِمةً حتى ألغيت في سنة (1347هـ / 1928م) وأُلحِقَت بالجامعة الأزهرية الناشئة."},{"id":4798,"title":"معركة الطرفية .","date":["العام الهجري :1325","الشهر القمري : شعبان","العام الميلادي :1907"],"text":"نكث أميرُ بُريدة محمد بن عبد الله أبا الخيل عَهدَه مع الملك عبد العزيز بن سعود، واتَّفق مع أمير حائل سلطان الحمود بن رشيد على أن يكونا يدًا واحدةً عليه. كذلك ازداد أبا الخيل قوةً بقدوم فيصل الدويش زعيم قبيلة مطير إليه، الذي عاهده على الوقوفِ معه. وسارع الملك عبد العزيز في التحرُّك إلى القصيم، ووصل عُنيزةَ التي هَبَّ أهلُها إليه، وخرج لمهاجمة سلطان ابن رشيد في بُريدة، وحصلت مناوشات لم تسفِرْ عن دخول الملك عبد العزيز البلدة. وأقبل فيصل الدويش يناصر ابن رشيد وأبا الخيل. فتصدى له الملك عبد العزيز وهزمه وطارد فلوله حتى بلدة الطرفية، التي كان يخيِّمُ بها، واستولى على معسكره. وسار ابن رشيد وأبا الخيل مع فلول فيصل الدويش إلى مهاجمة الملك عبدالعزيز في الطرفية، فهزمهم، وعادوا منهزمين إلى بُريدة، وتشَتَّت شملهم. وبعد ذلك عاد سلطان الحمود بن رشيد إلى حائل، ورجع الملك عبدالعزيز إلى الرياض."},{"id":4799,"title":"نشوء الأحزاب السياسية العربية بمصر .","date":["العام الهجري :1325","الشهر القمري : رمضان","العام الميلادي :1907"],"text":"كان الناسُ في مِصرَ على تيارات ثلاثة، تيار \"الحركة الوطنية\"، وكانت ضِدَّ الاحتلالِ الإنجليزيِّ وتيار \"جماعةِ الاحتلال\" التي تتلقَّى الدعم الإنجليزيَّ وتعيش عليه، وتيار \"جماعة قصر عابدين\" التي تؤيِّد الخديوي الذي يكرَهُ الاحتلالَ لكِنَّه راضِخٌ له، وبدأت وسائِلُ إعلام كلُّ تيارٍ بالصِّراعِ، وبناءً على هذه التيارات نشأت الأحزابُ السياسية، فأُعلِنَ في 16 رمضان عن تأسيس \"الحزب الوطني\"، رغم قيامِه فعليًّا قبل هذا التاريخِ، ويتزعَّمُه مصطفى كامل، ويرى العمَلَ على الاستقلالِ ضِمنَ دولةِ الخلافةِ العثمانية، ومن الضروريِّ وجودُ حِزبٍ واحدٍ تنضوي تحت لوائِه كلُّ العناصر الوطنية لمقاومةِ المحتَلِّين، وظهر \"حزب الأمة\" في 11 شعبان بعد أن تحوَّلت شركةُ الجريدة إلى حزبٍ، و \"حزبُ الملاكِ\" ورئيسُه محمود سليمان ويرى الاستقلالَ الكامِلَ وضرورة الاشتراك في الحُكمِ، وكان تأثيرُ محمد عبده واضحًا على هذا الحزبِ، الذي كان ليِّنًا معتدلًا مع الاحتلال ومعاديًا للخديوي، وبرز \"حزبُ الإصلاح على المبادئ الدستورية\" ورئيسُه علي يوسف، ويعدُّ هذا الحزبُ حِزبَ الخديوي عباس حلمي، أو حزب القصر، ومِن مُهمَّتِه السرية تفتيتُ حزبِ الأمة، وهذه الأحزابُ الثلاثةُ في مصرَ قُبَيل الحرب العالمية الأولى، وربما كان أكبَرُها وأهمها هو الحزب الوطني."},{"id":4800,"title":"وفاة المشير محمد رؤوف باشا قائد الجيش العثماني .","date":["العام الهجري :1326","العام الميلادي :1908"],"text":"هو المشيرُ محمد رؤوف باشا بن عبدي باشا الجركسي، قائِدُ الجيش العثماني. ولِدَ في استانبول عام 1832م، وتلقَّى علومَه العسكريَّةَ في الأكاديميَّةِ الحربية في استانبول. شارك في المعارِكِ التي جرت في كُلٍّ مِن البوسنة والقَرم تحت قيادة عمر باشا. التحق بمدرسةِ سانت سير الفرنسية العسكرية، ثم التحَقَ بأركان حربِ الجيش العثماني، وحصل على رُتبة الباشوية. تمَّت ترقيته في عام 1869م إلى رتبة مُشير. تولَّى منصب الوالي في كلٍّ من كريت، وإيشكودرا، وكاستامونو، وبغداد، وسيلانيك والبوسنة. أصبح قائدًا عامًّا للجيش العثماني في أثناء حربِ البلقان في عام 1877م، ونجح في هزيمة الصربِ وحلفائِها أمام مدينة بلغراد. ولَمَّا صدر الدستور العثماني الأول عُيِّن وزيرًا للبحرية العثمانية، وقد أُصيب في إحدى المعاركِ التي كان يخوضُها، فاضطُرَّ الأطباءُ إلى بتر ساقه، ولكنَّه تحامل على نفسِه ولم يترك ميدانَ المعركة، وظلَّ مستمرًّا في قيادته للقوات العُثمانية. وقد قُوبِلَت شجاعته بالتقدير والاحترام، فأنعَمَ عليه السلطان بلقب (سِر عسكر) وهو أكبَرُ ألقاب الدولة العثمانية. عَهِد إليه السلطان العثماني بمهمَّة خاصَّة كسفير خاص فوق العادةِ لدى الإمبراطور ألكسندر الثاني قُبَيل عقد مؤتمر برلين. عاد لتولِّي قيادة الجيش العثماني مرةً أخرى، وظلَّ في هذا المنصب الهامِّ إلى أن توفي عن 82 عامًا. وهو جدُّ الوجيه المصري محمد علي رؤوف، زوج الأميرة فائزة شقيقة الملك فاروق ملك مصر السابق."},{"id":4801,"title":"احتلال النمسا البوسنة والهرسك .","date":["العام الهجري :1326","العام الميلادي :1908"],"text":"رفضت البوسنة والهرسك دعوةَ مندوبيها لحضور المجلس النيابي المنعقد في استانبول، مع أنَّها لا تزال تابعةً اسميًّا للدولة العثمانية، واتجهت نحو الصرب، وكانت النمسا تطمَعُ أن تضمَّهما لها، فاتفقت مع روسيا سرًّا على أن تضمَّهما إليها مقابِلَ أن تكون الملاحة لروسيا حُرَّةً في البوسفور والدردنيل، وفعلًا قامت النمسا بضَمِّ البوسنة والهرسك إليها، ولم تستطع روسيا فِعلَ شَيءٍ لمعارضة الدول الأوربية لأطماع روسيا في المضائق، ثم قامت الدولةُ العثمانية بالاعتراف للنمسا بهذا الضمِّ، وتخلَّت لها عن البوسنة والهرسك مقابِلَ تخلي النمسا عن حقوقِها في سنجق نوفي بازار، وكانت النمسا أَمِنَت جانب البلغار بأن أيَّدَتْها ودعَمَتْها في مطالبتها بالاستقلالِ."},{"id":4802,"title":"وفاة الزعيم الوطني مصطفى كامل .","date":["العام الهجري :1326","الشهر القمري : محرم","العام الميلادي :1908"],"text":"هو مصطفى كامل بن علي محمد، زعيمٌ سياسيٌّ وكاتبٌ مصريٌّ وأحد روَّاد التحرير في مِصرَ، وُلِدَ سنة 1291ه في قرية كتامة التابعة لمركز بسيون بمحافظة الغربية، وكان أبوه علي محمد مِن ضبَّاطِ الجيش المصري، وقد رُزِقَ بابنه مصطفى وهو في الستينَ مِن عمره، ويعتبر مصطفى مؤسِّسَ الحزب الوطني المصري الذي تألَّف برنامجُه السياسي من عِدَّة موادَّ؛ أهمها: المطالبةُ باستقلال مصر ضِمنَ دولة الخلافةِ العثمانية، وإيجادُ دستورٍ يكفُلُ الرقابة البرلمانية على الحكومةِ وأعمالها، ونشرُ التعليم، وبثُّ الشعور الوطني. وأنشأ جريدةَ اللواء، وكان مِن المنادين بإعادة إنشاءِ الجامعة الإسلامية، كما أنَّه كان من أكبر المناهضينَ للاستعمارِ، وعُرِفَ بدورِه الكبيرِ في مجالات النهضةِ، مثل: نشر التعليم، وإنشاء الجامعة الوطنية، وكان حزبُه ينادي برابطةٍ أوثَقَ بالدولة العثمانية، وأدَّت مجهوداتُ مصطفى كامل في فَضحِ جرائم الاحتلالِ والتنديدِ بها في المحافِلِ الدولية، خاصَّةً بعد مذبحةِ دنشواي التي أدَّت إلى سقوط اللورد كرومر المندوب السامي البريطاني في مصرَ. توفِّيَ في مصر عن عمر يناهز 34 عامًا. رغم أنَّه عاش ثمانيَ سنوات فقط في القرن العشرين فإنَّ بصماته امتَدَّت حتى منتصف القرنِ."},{"id":4803,"title":"رضوخ السلطان العثماني عبد الحميد الثاني لجمعية الاتحاد والترقي .","date":["العام الهجري :1326","الشهر القمري : جمادى الأولى","العام الميلادي :1908"],"text":"لم يعُدْ تنظيمُ الاتحاد والترقي خافيًا على الدولة ولا على الناسِ، بل قَوِيَت شوكتُهم العسكرية وألَّفوا عصاباتٍ في وجهِ الحكومة؛ إذ كان من ضِمن أعضائِه ضباطٌ كبار من الجيش الحكومي، وكان هذا التنظيمُ يسيطِرُ على الفيلق الأوَّلِ مِن الجيش الحكومي، وكذلك الفيلق الثاني والثالث، أما الرابع فكان فيه أنصارٌ لهم، فأرسل رجالُ الاتحاد والترقي البرقياتِ مِن كبريات المدن في الجهة الأوربية (سلانيك ومناستر وسكوب وسيرز) إلى الصدرِ الأعظم يهدِّدون فيها بالزَّحفِ على استانبول إن لم يُعلَن الدستور الذي كان قد وُضِعَ سابقًا عام 1876م من قِبَل مدحت باشا، وهو من كبارِ مؤسِّسي تنظيم الاتحاد والترقي، فدعا السلطانُ عبد الحميد الثاني مجلسَ الوزراء إلى الانعقاد، إلَّا أن رجال الاتحاد والترقي أعلنوا عن الحريةِ في سلانيك ومناستر بشعارات الماسونية (العدالة والمساواة والأخوة)، واضطرَّ السلطان أن يصدِرَ أوامره بمنحِ الدستور، وأعلن الدستور والحريات، وصدر العفو العامُّ، وفُتِحَت أبواب السجون، واجتمع المجلِسُ وفاز فيه الاتحاديون بأغلبيةٍ كبيرة، وتسلم أحمد رضا رئاسةَ المجلس، وهو مؤسِّسُ جمعية تركيا الفتاة، ويعتبر تنظيمُ الاتحاد والترقي هو الجناحَ العسكريَّ للجمعية."},{"id":4804,"title":"ضم البوسنة والهرسك إلى النمسا .","date":["العام الهجري :1326","الشهر القمري : رمضان","العام الميلادي :1908"],"text":"أعلن القيصرُ النمساوي فرانتس جوزيف الأول ضَمَّ بلاد البوسنة والهرسك ذات الأغلبية المسلِمة إلى بلاده بعد 30 عامًا من احتلالِها واغتصابِها مِن الدولة العثمانية، وذلك في إطارِ خِطَّةِ تقسيم أملاكِ الدولة العثمانية."},{"id":4805,"title":"إعلان بلغاريا انفصالها عن الدولة العثمانية .","date":["العام الهجري :1326","الشهر القمري : رمضان","العام الميلادي :1908"],"text":"أعلنت بلغاريا انفصالَها عن الدولة العثمانية، كما أعلنت قيامَ نظام الحكم المَلَكي فيها من جانبٍ واحد. وقد وافقت الدولةُ العثمانية على هذا الاستقلال في ربيع الأول 1327هـ مقابِلَ حصولها على 5 ملايين ليرة ذهبية. كانت مساحةُ بلغاريا آنذاك أكثَرَ من 96 ألف كم2، ويزيد عددُ سكانها على 4 ملايين نسمة."},{"id":4806,"title":"افتتاح السلطان عبد الحميد الثاني مجلس المبعوثان (النواب) .","date":["العام الهجري :1326","الشهر القمري : ذي القعدة","العام الميلادي :1908"],"text":"افتتح السلطانُ عبد الحميد الثاني مجلِسَ المبعوثان (النواب) الذي كان النائبُ فيه يسمى (مبعوثًا) والذي ضمَّ 275 نائبًا، منهم 140 نائبًا تركيًّا، و60 عربيًّا، وعدد من النواب اليهود والنصارى والأرمن والصرب والبلغار والألبان."},{"id":4807,"title":"افتتاح الجامعة المصرية الأهلية رسميًّا .","date":["العام الهجري :1326","الشهر القمري : ذي القعدة","العام الميلادي :1908"],"text":"افتُتِحَت الجامعةُ المصريَّةُ الأهلية رسميًّا برئاسةِ الأمير أحمد فؤاد، وكانت البداياتُ الأولى لها متواضِعةً، ثم أخذت تتوسَّعُ نتيجة دعمِ كثيرٍ مِن المؤسَّسات والأفراد لها، ثم تحوَّلت الجامعة إلى جامعةٍ حكومية سنة 1344هـ/ 1925م باسم الجامعة المصرية، وهي التي تُعرَفُ الآن بجامعة القاهرة."},{"id":4808,"title":"خلع السلطان عبد الحميد الثاني آخر الخلفاء العثمانيين فعليًّا .","date":["العام الهجري :1327","العام الميلادي :1909"],"text":"بعد فوزِ الاتحاديِّين بأغلبيةٍ كبيرةٍ وإعلان الدستور أرادوا أن يُتِمُّوا خطَطَهم الراميةَ إلى خلع الخليفة، فبدؤوا يثيرونَ الفوضى والقلاقِلَ في الدولة بطُرُق غير مباشرة، وادَّعى رجال الاتحاد أنَّ الدستورَ معرَّضٌ للإلغاء والحريةَ مهدَّدةٌ؛ لذا فقد تقَدَّم الجيشُ المرابط في سلانيك بإمرةِ محمود شوكت لحماية الدستورِ والمجلس النيابي، عِلماً أنه كان فيه عناصِرُ أجنبية ترتدي الزيَّ العسكري، ووصل الجيشُ إلى العاصمة، فألقى الحصارَ عليها، ثمَّ سار إلى مقر إسماعيل حقي رئيس الجيش النظامي فقتَلوه ومَن معه، ثم ساروا إلى قصر يلدز مقَرِّ السلطان، فقاموا فيه بمذبحة بلا سببٍ ونهبوا القصرَ، ثم شكَّل المجلِسُ النيابيُّ مجلِسًا أطلقوا عليه اسمَ المجلس الملكي، فاجتمع مع مجلسِ الحركة وقَرَّروا خَلْعَ السلطان عبد الحميد باستصدار فتوى من شيخِ الإسلام، واستدعى المجلِسُ الصدر الأعظم توفيق باشا لتكليفِه بإبلاغ القرار إلى الخليفة فرفَضَ، فكلف المجلسُ وفدًا من الفريق البحري عارف حكمت، وآرام الأرمني، وعمانوئيل قره صو اليهودي، وأسعد طوبطاني، وذهب الوفد إلى الخليفة، وقرأ الفتوى، فتقَبَّل السلطان ذلك مع إنكارِه إحضارَهم عمانوئيل اليهودي معهم، خاصَّةً أن عمانوئيل هذا سبق أن زار السلطانَ مع هرتزل في وفدٍ يهوديٍّ يستأذنونه في الهجرةِ إلى فلسطين، فرفض طلبهم وإغراءَهم له، وأمر بطردِهم، فتوعَّد عمانوئيل السلطانَ بأنَّ هذا الرفض سيكَلِّفُه كثيرًا. نُقِلَ السلطانُ إلى سلانيك مع أسرته ومرافقيه، وبقي تحت حراسةِ الاتحاديين حتى حرب البلقان، ثم نُقِلَ إلى قصر بكلربكي في استانبول، وبقي فيه إلى أن توفي عام 1336هـ وكانت مُدَّةُ خلافته أكثر من ثلاث وثلاثين سنة، وتسلَّم الحكمَ صوريًّا أخوه محمد رشاد."},{"id":4809,"title":"عهد الاتحاديين في تركيا .","date":["العام الهجري :1327","العام الميلادي :1909"],"text":"بعد خَلعِ السلطانِ عبد الحميد الثاني أصبح كُلُّ شيء في الخلافةِ بيَدِ الاتحاديِّين، أمَّا الخليفةُ محمد رشاد فكان صورةً، غيرَ أن الأمر لم يطُلْ؛ إذ لم يتعاقَبْ على الخلافة سوى ثلاثة خلفاء، وكانت الدولةُ قد اشتركت في الحربِ العالمية الأولى بجانب ألمانيا، فهُزِمَت وتجزَّأت، وغادر البلادَ رِجالُ الاتحاد البارزين، أو الذين بيَدِهم الأمرُ والنهي، وجاء إلى الحُكمِ مصطفى كمال، وفي أيامِ الخليفة محمد رشاد الذي عُيِّنَ بدل عبد الحميد جرت الانتخاباتُ النيابية عام 1330هـ وفاز الاتحاديون وانتَشَرت الدعوة القوميَّة، وبدأت شعاراتُ الاتحاد والترقي في المساواة تذهَبُ هدرًا بعَدَمِ تَساوي الترك مع بقية العناصِرِ التي تؤلِّفُ الدولةَ العثمانية، وبدأت المهاتراتُ الصحفيةُ، وظهر الاختلافُ بين الدعوة المركزية واللامركزية، وتعني أن تأخُذَ الولايات غيرُ التركية استقلالًا ذاتيًّا، وتبقي خاضعة خارجيًّا لاستانبول، وتبنَّى الاتحاديون المركزيةَ، وبدأت التياراتُ الفكريةُ تتخَبَّطُ ويُشعِلُ نارَها اليهودُ والنصارى!"},{"id":4810,"title":"مظاهرة في عاصمة الخلافة العثمانية تطالب بالعودة إلى الشريعة .","date":["العام الهجري :1327","الشهر القمري : ربيع الأول","العام الميلادي :1909"],"text":"اشتعلت المظاهراتُ في عاصمةِ دولةِ الخلافةِ العُثمانية تطالِبُ بإلغاءِ الدستور، والعودةِ إلى الشريعةِ الإسلاميةِ، وإسقاطِ حُكومةِ الاتحادِ والترقي، التي تسلَّطَت على السلطانِ عبد الحميد الثاني وخلَعَتْه."},{"id":4811,"title":"وفاة بطرس باشا غالي رئيس وزراء مصر .","date":["العام الهجري :1328","الشهر القمري : صفر","العام الميلادي :1910"],"text":"هو بطرس باشا نيروز غالي، ولِدَ في عام 1262هـ/ 1847م قبطيٌّ من نصارى مصر. كان والده نيروز غالي ناظرًا للدائرة السَّنِيَّة لشقيق الخديوي إسماعيل في الصعيد. تلقَّى تعليمه في كلية البابا كيرلس الرابع. نشأ محبًّا للإنجليز؛ مِمَّا مهَّد لعمله في وزارة مصطفى فهمي، ثمَّ تولى منصب رئيس وزراء مصر من 12 نوفمبر 1908 إلى 1910م. اتُّهِم بمحاباته للإنجليز على حساب مصلحة مصر؛ فقد لعِبَ بطرس غالي دورًا مشبوهًا في مشروع مدِّ امتياز قناة السويس لصالح الإنجليز، الذي كان يهدف لمدِّها أربعين عامًا أخرى، وفي جلسة مناقشة مَدِّ الامتياز حضر شخصٌ يدعى \"إبراهيم ناصف الورداني\" وكان من أعضاء الحزب الوطني، وتأثَّرَ بما دار من مناقشات في تلك الجلسة وخرج منها عازمًا على وضع حدٍّ ونهايةٍ لمشروع هذا القانون، يتلخَّصُ في اغتيال بطرس غالي. وقد قام إبراهيم الورداني باغتيال بطرس غالي أمام وزارة الحقَّانية في الساعة الواحدة ظهرًا يوم 11 من صفر؛ حيث أطلق عليه الورداني ستَّ رصاصات أصابت اثنتان منها رقبَتَه، واعترف بقيامه بقتل بطرس غالي؛ لأنَّه في نظره خائن، بسبب ما قام به في اتفاق الحُكم الثنائي، ومشروع قانون مدِّ امتياز قناة السويس، وقانون المطبوعات. ورئاسته لمحكمة دنشواي، وبطرس باشا غالي هو والد بطرس غالي الدبلوماسي المصري، والأمين العام السادس للأمم المتحدة."},{"id":4812,"title":"نشر الدولة العثمانية \"قانون الكنائس\" .","date":["العام الهجري :1328","الشهر القمري : جمادى الآخرة","العام الميلادي :1910"],"text":"قامت الدولة العثمانية بنشر \"قانون الكنائس\" الذي صار حُكمًا بين الأقليَّات البلغارية والصربية واليونانية الموجودة في مقدونيا في منطقة البلقان."},{"id":4813,"title":"وفاة المهدي قائد المقاومة الصومالية .","date":["العام الهجري :1329","العام الميلادي :1910"],"text":"هو محمد عبد الله حسن نور صومالي، قاد الجهاد ضِدَّ الاحتلال الإنجليزي والإيطالي والأثيوبي في مطلع القرنِ العشرينَ، وُلِدَ سنة 1856م، سماه الإنجليز «الملا المجنون» عندما واجه الاستعمارين البريطاني والإيطالي، واستطاع أن يقاوم المستعمرين لمدة عشرين عامًا، كبَّدهم أثناءها الخسائِرَ الفادحة، وانتزع حقَّ السيادة على مناطِقَ عديدة، خاض محمد بن عبد الله 270 موقعة في الجهاد ضدَّ البريطانيين انتصر في معظمها. في العام 1920م تعرض محمد بن عبد الله لقصف من الطيران البريطاني استهدف مواقِعَهم في مدينة جالكاسيو غرب الصومال، فاستطاع أن يصِلَ إلى أثيوبيا ثم توفِّيَ فيها."},{"id":4814,"title":"صلح دعان بين الزيديين في اليمن والعثمانيين .","date":["العام الهجري :1329","العام الميلادي :1910"],"text":"تزعَّم المتوكِّلُ يحيى بن المنصور محمد بن حميد الدين اليمنيين؛ لمقارعة الأتراك، وتمكَّن من حصار صنعاء وأجبر الأتراك أخيرًا على الصلح المشهور بصلح دعان ضمن بنود كثيرة على الاعتراف به حاكمًا وحيدًا للطائفة الزيدية في اليمن مقابِلَ اعترافه بالسيادة العثمانية على اليمن، وهو ما جعل حربَه للأتراك تبدو وكأنها فقط لنيل الاعتراف بسلطته الدينية والسياسية على المناطق التي ينتشِرُ فيها المذهب الزيدي، وقد نفرت إثرَ ذلك قبائِلُ يمنية منه متهمةً إياه بأنَّه صار حليفًا للأتراك، واتجهت إلى منافِسِه محمد الإدريسي في صبيا بعسير، حيث كان محمد الإدريسي قد استثمر مكانة أسرته الدينية ليؤسِّسَ دولة الأدارسة في أعالي الشمال الغربي لليمن، وليبدأ بلعبِ دور في أحداث التاريخ اليمني الحديث."},{"id":4815,"title":"عقد المؤتمر المصري بالقاهرة تحت رعاية الإنجليز .","date":["العام الهجري :1329","الشهر القمري : ربيع الآخر","العام الميلادي :1911"],"text":"قُبَيل انتهاء المؤتمر القبطي بمصر نشرت بعضُ الصحفِ أنباءً عن تكوينِ لجنةٍ بالإسكندرية تضُمُّ بعضَ الأعيان في الأقاليم، مكلَّفةً بعقد مؤتمر ديني يضمُّ مندوبين عن المسلمين واليهود المصريين والنصارى؛ للنظر في المسألة القبطية. وفي ذات الوقت دارت اجتماعاتٌ في القاهرة بين عددٍ كبيرٍ مِن المشتغلين بالمسائل العامة، ومنهم فريق من حزب الأمة؛ لمناقشة المسألة القبطية ونتائج انعقاد المؤتمر القبطي في أسيوط، ودعا هؤلاء لجنةَ الإسكندرية لمشاركتهم في عقد اجتماع عام. وفي 8 ربيع الأول تم عقدُ اجتماع ضم عددًا من الشخصيات العامة، وقرَّروا تأليف وفد من 12 شخصية للتوجُّه إلى منزل مصطفى فهمي باشا رئيس الوزراء المصري الأسبق؛ ليعرضوا عليه رئاسة المؤتمر، وقرَّر هؤلاء تسميةَ المؤتمر بالمؤتمر المصري. وقد أرادت الشخصياتُ التي دعت إلى المؤتمر أن يدورَ في إطار الوحدة الوطنية، وأن يبحثَ المؤتمر الشؤون المصريةَ جميعًا بما فيها مطالب القبط. وعقدت اللجنةُ التحضيريةُ للمؤتمر أولى جلساتها بمنزل \"علي شعراوي\"، وقرَّرت حصرَ مقاصد المؤتمر في النظر في الشؤون العامة والاقتصادية والاجتماعية والأدبية، ومناقشة مطالب القبط وتمحيصها، وقرَّرت أنه لا يجوز للمؤتمر الاشتغالُ بالمسائل السياسية. وعُقِدَ المؤتمر المصري يوم السبت 30 ربيع الآخر -أي: بعد انعقاد المؤتمر القبطي بـ52 يومًا- في القاهرة بضاحية مصر الجديدة. وتم عقدُ جَلستين تحضيريتين في منزل \"علي شعراوي\" اتفق فيهما على الأُطُر الأساسية التي سيناقشها المؤتمر، واتفقوا أنَّ هناك رابطًا يجمع المسلمين والأقباط هو رابِطُ المصرية، وأن هذا الرابط هو المعيار الأصيل في المحاسبة!!! وأنَّ هذا الرابط يفرِضُ على الجميع البحثَ عن السبل التي تقود إلى الوفاق الوطني بين عنصرَيِ الأمة المصرية. وأشيرَ في تقريرٍ أعدَّته اللجنةُ التحضيرية لهذا المؤتمر، إلى أنَّ الحضور في مؤتمر أسيوط القبطي يستصغرون ما في أيديهم من السلطةِ ويستكثرون ما في أيدي المسلمين، وأن هؤلاء عوَّلوا وحدهم على أن يكونوا أمةً مستقلَّةً من دون المصريين، وتذرَّعوا بتلك المطالب حتى يَصِلوا بمعونة بريطانيا وفرنسا إلى أن تكون لهم السيادةُ على الأكثرية المسلِمة. وقد كان انعقادُ المؤتمر بتشجيع من المعتمد البريطاني في القاهرة \"إلدن جورست\"، وكان هدفُ الإنجليز منه هو إشعالَ الفتنة بين المسلمين والأقباط في الوقت الذي يكسبُ فيه الإنجليز الطرفين معًا؛ ولذا أصدر \"جورست\" تعليماتِه بعقد المؤتمر المصري. واستفاد الاحتلالُ مِن عقد المؤتمرين القبطي والمصري كمؤتمرين انقساميَّين، إلا أنَّ استفادته من المؤتمر المصري كانت أكبر؛ لأنَّ تجميع كل هذه الأحزاب والقوى المصرية دون أن يكونَ لها موقِفٌ من الاحتلال أو حتى معارضة له هو انتصارٌ لسياسة الاحتلال التي حرصت على ألَّا يأخذ المؤتمر أيَّ طابع سياسي، وأنَّ الوقيعة بين المسلمين والأقباط ما هي إلا زيادةٌ في قبضة الاستعمار على الجميع، ولجوء الجماهير إلى الهدوء والاستكانة حتى لا تُتَّهمَ بالتعصُّبِ والإرهاب!"},{"id":4816,"title":"إرسال الإمبراطور الألماني طرادًا بحريًّا إلى ميناء أغادير المغربية .","date":["العام الهجري :1329","الشهر القمري : رجب","العام الميلادي :1911"],"text":"أرسل الإمبراطور الألماني جليوم طرادًا بحريًّا إلى ميناء أغادير المغربية؛ وذلك احتجاجًا على سياسة فرنسا في المغرب، فما كان من فرنسا إلا أن تنازلت لألمانيا عن الكاميرون، فأقرَّ لها الإمبراطور باحتلال مراكش."},{"id":4817,"title":"وفاة الزعيم أحمد عرابي قائد الثورة العرابية .","date":["العام الهجري :1329","الشهر القمري : رمضان","العام الميلادي :1911"],"text":"هو الزعيم المصري أحمد عرابي بن محمد عرابي بن محمد وافي بن محمد غنيم من قبيلة المحامدة، انتقل جَدُّهم من بطائح العراق إلى مصر في أواسط القرن السابع للهجرة. ولِدَ في قرية (هرية رزنة) من قرى الزقازيق بمصر، وجاور في الأزهر سنتين، ثم انتظم جنديًّا في الجيش سنة 1271هـ وبلغ رتبة (أميرالاي) في أيام الخديوي توفيق. وهو قائد الثورة العرابية ومفجِّرُها ضِدَّ الخديوي توفيق. وقد فشلت هذه الثورة؛ وذلك نتيجة لخيانة بعض عناصر الثورة له، وتدخُّل القوات البريطانية لحماية الخديوي. ثم نفوا عرابي باشا إلى جزيرة سيلان 1300ه/1882م حيث مكث 19 عامًا. وأُطلِقَ في أيام الخديوي عباس سنة 1319 فعاد إلى مصر وتوفي بالقاهرة. له تقرير عن ثورته، ومذكرات سماها كشف الستار عن سر الأسرار."},{"id":4818,"title":"إبلاغ إيطاليا الدولةَ العثمانية بضرورة تسهيل احتلالها لليبيا .","date":["العام الهجري :1329","الشهر القمري : شوال","العام الميلادي :1911"],"text":"أبلغت إيطاليا الحكومةَ العثمانية عن نيَّتِها باحتلال ليبيا، وطلبت منها تسهيلَ الاحتلال بحجَّة حماية رعاياها من الاضطهاد العثماني، والمحافظة على المصالح الاقتصادية للإيطاليين. وكان الموقِفُ العثماني في ظل عهد جماعة الاتحاد والترقي ضعيفًا جدًّا أمام التهديد الإيطالي، فاكتفت بدعوة إيطاليا للجلوس إلى طاولة المفاوضات تجنبًا لاستخدام القوة. ولكن الحكومة الإيطالية رفضت ذلك؛ لعدة أسباب، من أهمها: أ- ضعف الموقف الحربي العثماني في ليبيا. ب- الموقف الإيطالي المدعوم من قِبَل الدول الأوروبية باستثناء ألمانيا والنمسا. جـ- ما كانت تتمتع به إيطاليا من قوة بحرية وبرية. د- ضعف الموقف الداخلي في ليبيا؛ إذ إنَّ المقاومة العسكرية في ليبيا كانت محدودةَ الطاقات والإمكانات بالنسبة للهجوم الإيطالي المركَّز."},{"id":4819,"title":"الإيطاليون يستعمرون ليبيا .","date":["العام الهجري :1329","الشهر القمري : ذي القعدة","العام الميلادي :1911"],"text":"كانت إيطاليا تطمَحُ بالسيطرة على طرابلس، وخاصةً بعد أن احتلَّت فرنسا تونس عام 1299هـ وبدأت إيطاليا تعقِدُ الاتفاقات السياسية مع الدول الأوربية الأخرى، مثل إسبانيا وفرنسا وإنجلترا والنمسا، ثم انصرفت إلى تهيئة الوضعِ داخِلَ ليبيا، فعَمِلَت على شراء الأراضي وإنشاء المشروعات الزراعية، وإرسال البعثات النصرانية الكاثوليكية، وفتح المدارس الإيطالية، وتأسيس شركات النقل بين البلدين، ومسْح السواحل بحجَّة البحث عن الإسفنج البحري، وفي عام 1238هـ قدمت إيطاليا إنذارًا للدولة العثمانية اتهمتها بعرقلة المساعي لتحضير الشعب الليبي، ولا تريد إضاعة الوقت بالمفاوضات،وإنما قررت احتلالَ ذلك الجزء من شمالي إفريقيا، واحتَجَّ الباب العالي لدى الدول الأوربية التي كانت على علمٍ مُسبق ومدبَّر بالموضوع، وأعلنت الدولةُ العثمانية رفضَ الإنذار غيرَ أن إيطاليا حاصرت سواحل طرابلس وبرقة؛ كي لا يصِلَ إليها أي مساعدة من تركيا، وكذا حاصرت إنجلترا الحدود البرية من جهة مصر رغم تظاهرها بالحياد، وبدأ الأسطول الإيطالي في السابع من شوال 1329هـ / 30 أيلول 1911م بقصف مدينة درنة، وفي اليوم التالي قُصِفَت طرابلس وتمَّ إنزال القوات التي احتلت طرابلس وبنغازي والخمس، ولم ينقَضِ الشهر حتى احتل الطليان طرابلس وبنغازي ودرنة، وعرفت البلاد باسم ليبيا، وأعلنت روما ضمَّ هذا الجزء من شمالي إفريقيا إليها، وبدأت المقاومة تشتد حتى ألجأت المستعمرين إلى الساحلِ، وتقدَّم العثمانيون بقيادة عزيز المصري، والمتطوِّعون بقيادة أنور باشا وأخيه نوري وعمه خليل، والسكان ومنهم السنوسيون، ووصلوا إلى طرابلس وانتصروا على الطليان في بنغازي، وهدَّدت إيطاليا باحتلال استانبول، فأرسلت بارجتين حربيتين إليها، واحتَلَّت بعض الجزر وضربت ميناءَ بيروت واضطرت الدولة إلى عقدِ معاهدة مع إيطاليا وانسحبت من ليبيا وتركت المجاهدين وحدَهم بالميدان، وحدثت معاهدةُ السلم عام 1329هـ ولم تعترف الدولة العثمانية بالاحتلال الإيطالي، وإنما تعهدت بسحب موظفيها وجنودها، وصدر قرار سلطاني بإعطاء ليبيا الاستقلال الذاتي، وتعهدت إيطاليا بإعطاء الحرية الدينية والعفو العام وقَبول ممثل عثماني، ولم تنفذ إيطاليا أيَّ بند من بنود الاتفاقية!!"},{"id":4820,"title":"جرائم الاحتلال الإيطالي بحق الليبيين .","date":["العام الهجري :1329","الشهر القمري : ذي القعدة","العام الميلادي :1911"],"text":"عندما اجتاحت القوات الإيطالية طرابلس قبضت على ألوف من أهلها في بيوتهم ونفتهم بدون أدنى مسوِّغ إلى جزر إيطاليا؛ حيث مات أكثرهم من سوء المعاملة. وأباد الإيطاليون في غير ميدان الحرب كل ليبي يزيد عمره على (14) سنة، وأحرقوا يوم 26 تشرين الأول أكتوبر أحياءً خلف بنك روما، وبعد أن ذبحوا كثيرًا من السكان بينهم النساء والشيوخ والأطفال، في اليوم التالي وصف أحد المراسلين ما وقع عليه بصرُه بقوله: (صادفت 50 جنديًّا يقودون ستة من الليبيين إلى خرابة يستعملها الجنود لقضاء الحاجة، ولما أدخلوهم إليها اشترك الضباط والجنود في قتلهم بالمسدسات والبنادق، وما كدت أفِرُّ من هذا المشهد حتى رأيت ما هو أشد هولًا، وهو طائفة من الجنود يسوقون (50) ليبيًّا بين رجال وأطفال، وأدخلوهم إلى مكان قد تهدم، وبدأ الضباط يقتنصون هذا الصيد الكريه بمسدساتهم وبنادق جنودهم مدة عشرين دقيقة. وكلما سَمِعوا أنينًا من جثة أعادوا عليها النار حتى انقطع الأنين!). واستمر الجيش الإيطالي ثلاثة أيام يطلق الرصاص على كل من يلقاه من الليبيين. فهلك عددٌ من النساء والأطفال، وبلغ مجموع القتل خلال ثلاثة أيام أربعةَ آلاف ليبي. ولما كانت (واحة جغبوب) هي مركز السادة السنوسية، فقد حرص الإيطاليون على إبادةِ رجال الدين فيها، ومحو معالم الإسلام. وأصدرت الحكومةُ الإيطالية أمرًا بإقفال جميع الكتاتيب التي تعَلِّم الأطفالَ أمور دينهم، وتحفِّظُهم القرآن الكريم."},{"id":4821,"title":"انتفاضة مسلمي تونس ضد الاحتلال الفرنسي .","date":["العام الهجري :1329","الشهر القمري : ذي القعدة","العام الميلادي :1911"],"text":"انتفض المُسلمون في تونس ضِدَّ الاحتلال الفرنسي؛ وذلك بسبب إصرار الفرنسيين على نبشِ قبور موتى المسلمين بهدفِ مَدِّ خط حديدي عبر مقبرة \"الزلاج\"."},{"id":4822,"title":"حرب البلقان الأولى مع العثمانيين واستقلال بلاد البلقان .","date":["العام الهجري :1330","العام الميلادي :1911"],"text":"رفضت البوسنة والهرسك دعوةَ مندوبيها لحضور المجلس النيابي في استانبول عام 1327هـ مع أنها لا تزال تتبع الدولة العثمانية اسمًا، واتجهت نحو الصرب، وهذا ما أثار النمسا التي اتفقت مع روسيا سرًّا على أن تضم البوسنة والهرسك إليها مقابِلَ إبقاء مضائق البوسفور والدردنيل مفتوحةً دائمًا لروسيا، وبالفعل قامت النمسا باحتلالهما، وزاد العداء بين النمسا والصرب، وأما إيطاليا فكان لها مطامِعُ فيهما، فعقدت أيضًا اتفاقًا سريًّا مع روسيا للوقوف بوجه النمسا إذا استمرَّت بتعديها على البلقان، وأعلن الجبل الأسود الحربَ على الدولة العثمانية هذا العام، ووقف بجانبه أعضاء التحالف البلقاني، وهم صربيا وبلغاريا واليونان، وتمكنوا من إحراز النصر على العثمانيين، واستعملوا الطائراتِ لأول مرة وقصفوا مدينة أدرنة، وفقدت الدولة العثمانية معظمَ أراضيها في أوربا، ثم بعد وقف القتال جرى الاتفاقُ على استقلال ألبانيا، وقُسِّمَت الأراضي الباقية التي كانت للعثمانيين بين أعضاء التحالف البلقاني، وعُرِفَت هذه الحرب باسم حربِ البلقان الأولى."},{"id":4823,"title":"ملك أفغانستان يدعو لحملة تبرع لدعم الشعب الليبي ضد إيطاليا .","date":["العام الهجري :1330","العام الميلادي :1911"],"text":"دعا جلالةُ ملك أفغانستان حبيب الله خان جميعَ وجوه مملكته ورجال حكومته وأعيانها وتجارها، دعاهم لاجتماع عظيم، وعَرَض عليهم القضيةَ الطرابلسية وما يعانيه المسلمون في طرابلس الغرب من الظلم والعدوان، ودعاهم إلى الإنفاق وجمْع الأموال وفتْح كتاب أسماه كتاب (إغاثة يتامى وشهداء ومجروحي مجاهدي طرابلس الغرب) وقال لهم: افتحوا كيس همَّتكم وبلُّوا قلوبكم بماء الشفقة الأخوية، أعينوا يتامى وأيامى أولئك المجاهدين الذين جادوا بأرواحهم لأجل حفظ وطنهم وشَرَفِ مِلَّتِهم، أعينوهم على الأقل بلفائف يشدُّون بها جروحَهم، لا تنظروا إلى قلة ما تعطونه من المال وكثرته، أعطوا ما تتمكنون من إعطائه وأثبتوا أسماءكم في هذا الكتاب، إن الله لا يُضيعُ أجر من أحسن عملًا. وقد تبرع هو بمبلغ عشرين ألف روبية، وكان يقول وكله حماس: ألا ليتني قريب منهم أمدهم بالفعل لا بالقول، ألا ليتني طائرٌ أطير لمساعدة إخواني المسلمين."},{"id":4824,"title":"دعم العالم الإسلامي للشعب الليبي في جهاده ضد الاحتلال الإيطالي .","date":["العام الهجري :1330","العام الميلادي :1911"],"text":"أبلى الشعب الليبي بلاءً حسنًا في جهاده ضد المحتل الإيطالي الصليبي، فلما طارت أخبارُ معارك بنغازي وطرابلس ودرنة إلى العالم أجمع، ورأت حكومة الأتراك أنَّ الشعب الليبي جديرٌ بالمساعدة وجادٌّ في جهاده وكفاحه ضِدَّ العدو، أرسلوا الإمدادات، فقام أنور باشا وزير الحربية التركية باختيار مجموعاتٍ من الشباب الليبي، واستقبلهم في استانبول لتعليمهم النظم السياسية والعسكرية الجديدة؛ ليُشرِفوا على قيادة الجيش الوطني، وتدافع المجاهدون المسلمون من كل مكان إلى ميدان القتال عن طِيبِ خاطر، وجاد المسلمون الخيِّرون بأموالهم وأعزِّ ما ملكت أيديهم، وفاضت قرائِحُ الشعراء وأقلام الكتَّاب بما أوحته ضمائرهم، وقامت الصحفُ، وفي طليعتها المؤيد الغراء المصرية بدورها، وكانت هذه الصحف حلقةَ الاتصال بين جهاد الليبيين والعالم الإسلامي، وكانت المساعدات تأتي إلى مصر ثم تُرسَل إلى المجاهدين، وكان الأميرُ عمر طوسون في مصر، ووالدة الخديوي (أم المحسنين) وخَلْفَهم مسلمو مصر قد وقفوا بما يملكون لدعم الشعب الليبي ماديًّا ومعنويًّا، فكانت أم المحسنين تنفق الأموال والمُؤَن، والملابس والأدوية، والقوافل المحمَّلة للمجاهدين، وعندما قابلت الوفد الذي تسلَّم هذه المواد والمؤن قالت: (إنني لم أفعل شيئًا يُذكَر في جانب ما يقوم به أولئك المجاهِدون في سبيل الله، وإنني قلقة لأنني لم أسمع منذ أيام خبرًا عن ميدان القتال) وكان الليبيون الذين هاجروا إلى مصر من عشرات السنين قد وقفوا وقفةَ رجل واحد بالمال والرجال، وكان أحمد الباسل من وجهاء مصر سندًا قويًّا لحركة الجهاد في ليبيا، وبدأت وفود المتطوِّعين من مصر والعالم الإسلامي تترى لمساعدة إخوانهم المسلمين في ليبيا، ووصلت البعثاتُ الطبية من تركيا ومصر، فقامت بدورها خيرَ قيام، كما وصل عددٌ من مراسِلي صحف إسلامية، ووصل الأمير شكيب أرسلان على رأس بعثة طبية كان عدد جمالها التي تحمل الأثقال من المؤن والأدوية 650 جملًا يصحبُه خمسة أشخص من أخصِّ رجاله، قد تطوعوا للجهاد ببرقة، ومن بين المتبرعين مسلمو أندونيسيا، ومسلمو الهند، وحاكم قطر الشيخ قاسم محمد؛ فقد تبرع للمجاهدين بعشرين ألف روبية، وملك أفغانستان حبيب الله خان وشعبه، وأهل البحرين، وجاء إلى ميدان القتال كلٌّ من محمد حلمي، وعبد المعطي صالح ضابط مصري، وعارف بك والي البصرة سابقًا، ونشأت بك أحد كبار رجالات تركيا المشهورين، ومحمد طاهر أفندي مصري، وغيرهم كثير!!"},{"id":4825,"title":"الاستعمار الفرنسي والإسباني على المغرب .","date":["العام الهجري :1330","العام الميلادي :1911"],"text":"عندما ساعد الملِكُ عبد الرحمن بن هشام العلوي الأميرَ عبد القادر الجزائريَّ في مقاومته الاحتلالَ الفرنسي للجزائر، احتجَّت فرنسا على هذه المساعدة، واحتَلَّت مدينة وجدة مقابل ذلك، ثم احتلَّ الإسبان مدينة تطوان لكنَّهم خرجوا منها بعد دفع أموال باهظة لهم، وفي أيام الحسن الأول عُقِدَت معاهدةُ مدريد عام 1298هـ وأصبح لمدينة طنجة مجلس صحي يتناوب رئاستَه قنصلا فرنسا وإسبانيا وأعلنت فرنسا عام 1300هـ الحمايةَ على المغرب، وكانت المعاهدة التي وقَّعها عبد العزيز الملك المخلوع مع الفرنسيين عام 1330هـ الذين أعادوه لمكانه، ولما تولى عبد العزيز بن الحسن الأول أخذ في تبذير الأموال ممَّا ألزمه الاقتراضَ من البنوك الأوربية وخاصة بنك فرنسا فأخذت فرنسا تتحيَّن الفرصة ومقابلها إسبانيا التي تملك أجزاءً ومدنًا على السواحل المغربية، مثل سبتة ومليلة، وهي لا تزال تحت الحكم الإسباني، واتفقت فرنسا وإسبانيا على اقتسام الصحراء المغربية، وتفاهمت فرنسا مع إيطاليا عام 1339هـ على أن تترك لفرنسا حرية العمل بالمغرب مقابل ترك الحرية لإيطاليا حرية العمل بطرابلس، وهكذا مع إنجلترا في مصر، ودخلت القوات الفرنسية لنجدة السلطان عبد الحفيظ، فاحتلت فاس في 1339هـ ثم احتلت مكناس والرباط ومراكش، وبعدها أعلنت الحماية على المغرب!"},{"id":4826,"title":"النمسا أول الدول الأوروبية اعترافًا بالدين الإسلامي في البلاد. .","date":["العام الهجري :1330","العام الميلادي :1911"],"text":"اعترفت النمسا بالإسلامِ كدين رسمي في البلاد في عهد القيصر فرانس جوزيف، وهو ما منحهم ميزاتٍ كبيرة استنادًا إلى نصوص الدستور الذي يساوي بين الجالية المسلِمة وغيرها من معتنقي الديانات الأخرى. وضَمِنَ الاعتراف الرسمي بالدين الإسلامي حقوقَ الجالية المسلمة في مواضِعَ مختلفة، مثل حرية ممارسة الشعائر الدينية، وحرية المسلمين في تنظيم الرعاية الدينية الخاصة بهم، وحصول مؤسَّساتهم على حق حماية جميع أنشطتها الاجتماعية والثقافية والمالية. واستنادًا إلى هذه الحقوق تمكَّنت الأقلية المسلمة من رعاية أبنائها بالمدارس؛ ليصل عدد المستفيدين من دعم الدولة لدروس الدين الإسلامي حوالي 40 ألف تلميذٍ في مراحل التعليم المختلفة."},{"id":4827,"title":"مواجهة البحرينيين للبعثة الأمريكية التنصيرية .","date":["العام الهجري :1330","العام الميلادي :1911"],"text":"كانت حملات التنصير قد وصلت إلى البحرين عام 1893م وتأسَّست أولُ مدرسة للتعليم بالأسلوب الغربي الحديث في البحرين على يدِ البعثة، وفي عام 1894 افتتحت الإرساليةُ الأمريكية مكتبةً عامةً لها بالمنامة وبدأت عمَلَها في تقديم بعضِ الصُّحُفِ والكتُبِ لروَّادِها، ثم أنشأت الإرساليةُ الأمريكيةُ مستشفى ماسون التذكارية، ودكانًا لبيع الإنجيل، وحينها كان مجلِسُ الشيخ إبراهيم بن محمد آل خليفة ابن حاكم البحرين يُعَدُّ من أهم المنتديات الثقافية في البحرين آنذاك، كما كان مُقبِل بن عبد الرحمن الذكير واحدًا من أهمِّ مُثقَّفي البحرين المشاركين والفعَّالين في المجلس، وحينها رأى كلٌّ مِن مقبل الذكير، ويوسف كانو ضرورةَ تأسيس نادي أدبي إسلامي، واستضافة أحد العلماء الكبار؛ لمقاومة هذه الحَمَلات التخريبية في البلادِ، من خلال أنشطة هذا النادي، فتوصَّلا بعد تحرٍّ إلى أن أفضَلَ من يمكنه تسلم إدارة النادي هو الشيخ العلامة محمد بن عبد العزيز المانع الوهيبي التميمي، وأنه لا بدَّ من العمل على إحضاره من مقر إقامته بالبصرة، وبعد أسابيع من المراسلات حضر الشيخ المانع من البصرة حاملًا معه خبرةَ أساتذته في مقاومة التبشير، الذين تتلمذ على أيديهم في مِصرَ والعراق، أمثال الشيخ محمد رشيد رضا. تسلم الشيخ المانع منصِبَه كمدير للنادي الأدبي الإسلامي بمجرد وصوله، وقد عَرَض عليه مقبل الذكير أن يجعَلَ له مدرسة للتعليم الإسلامي تكون مُلَحقةً بالنادي الإسلامي، فكان النادي في بداية تأسيسه عبارةً عن صفين دراسيين لتدريس العلوم الشرعية وبعض العلوم الحديثة، كما توفر في النادي غرفةُ مطالعة ومكتبة، فكان للشيخ المانع دورٌ فاعل في نشر العلوم الإسلامية في المنامة، وظلَّ الشيخ هناك أربع سنوات يدرِّس شباب \"النادي الإسلامي\" جُلَّ العلوم الإسلامية؛ مِن قرآنٍ، وفقه، ولغة، ورياضية كالعلوم الفلكية والفرائض، وأصبح النادي ملتقًى لرواد العلم والمثقفين في المنامة والبلدان المجاورة لها، كما أصبح مكانًا يتدارس فيه الأهالي أساليبَ التبشير وسُبُلَ مقاومته، ولم يكن النادي الإسلامي مجردَ مكان للثقافة والنقاشات الأدبية فحسب، بل كان مقرًّا للتواصل الفكري والعلمي مع الشعوب الإسلامية، والمراسَلات بين المفكِّرين والمثقَّفين والعلماء في البحرين والشارقة والقاهرة."},{"id":4828,"title":"معاهدة طهران بين الدولة العثمانية وإيران بشأن الحدود .","date":["العام الهجري :1330","الشهر القمري : محرم","العام الميلادي :1912"],"text":"جرت عِدَّةُ معاهدات بشأن الحدود بين الدولتين العثمانية والإيرانية، ومنها: معاهدة أرضروم الثانية 1263هـ غير أنَّها فشلت واستمَرَّت الاشتباكات على الحدود، وفشلت لجنة التخطيط بناءً على المعاهدة المذكورة في إنهاء المشكلة، كما بدأ الخلاف في تفسير نصوص المعاهدة، وكانت كلٌّ من إنجلترا وروسيا ترغبان في إنهاء هذا الموضوع؛ حيث أصبحت المنطقة ساحةَ نفوذ لكلٍّ مِن الدولتين، فدعا ذلك لإجراء مفاوضات مباشِرة بتوسط إنجلترا وروسيا، وانتهت باتفاق طهران في اليوم الأول من عام 1330هـ/ 21 ديسمبر، وتضَمَّن خمس نقاط: تعيين لجنة مشتركة لتثبيت الحدود. تزويد أعضاء اللجنة بجميع الوثائق والبيانات المطلوبة. في حال الفشل في تفسير النصوص وحَلِّ القضايا تحالُ إلى محكمة التحكيم في لاهاي. تكون معاهدة أرضروم الثانية الأساسَ الذي تستند إليه قرارات اللجنة. لا يتخذ أي من الطرفين من احتلال الأراضي المتنازع عليها حجة قانونية للاحتفاظ بها والسيطرة عليها. واستمرَّت المفاوضات أكثرَ مِن خمسة أشهر دون الوصولِ إلى اتفاق، وتقرر استمرارُ المباحثات في استانبول، ولكن الأحداث الجارية من الحرب العالمية وغيرها أوقفت الموضوع."},{"id":4829,"title":"ثورة أحمد وهبة ضد فرنسا في المغرب .","date":["العام الهجري :1330","الشهر القمري : ربيع الآخر","العام الميلادي :1912"],"text":"فرض الفرنسيون الحمايةَ على المغرب، وبعد أيامٍ مِن فرض الحماية قام المغاربة بثورةٍ عارمة في فاس ثار فيها الجيشُ والشعب، تزعَّمها المجاهِدُ أحمد هبة الله ابن الشيخ ماء العينين، وكانت الانتصارات فيها سِجالًا بين الفريقين، وانتهى الأمرُ بوفاة الرجل، وتمكن الفرنسيون من بسطِ نفوذهم على المغرب أثناء الحربِ العالمية الأولى."},{"id":4830,"title":"انسحاب الدولة العثمانية من الحرب الليبية وتوقيع معاهدة مع إيطاليا .","date":["العام الهجري :1330","الشهر القمري : ذي القعدة","العام الميلادي :1912"],"text":"بعد أن أعلنت إيطاليا الحرب على الدولة العثمانية، وهي الحرب التي عُرِفت بالحرب الإيطالية - الطرابلسية. حاصر الأسطول الإيطالي مدينةَ طرابلس الغرب مدةَ ثلاثة أيام، بعدها سقطت المدينةُ بيد المستعمرين الإيطاليين. ولم تتوفر للمقاومة الشعبية القوة اللازمة لقهر الإيطاليين ورَدِّهم على أعقابهم. كما لم تكن قدرةُ الدولة العثمانية القتالية بالمستوى المطلوب، ولم تكن القوة بين الطرفين متكافئة، ورغم المقاومة العثمانية المحلية التي قادها السنوسيون إلا أن الإيطاليين تمكنوا من احتلال ليبيا عام 1911م. وأثناء الحرب -وكوسيلة ضغط على الدولة العثمانية- نقل الإيطاليون الحرب ضِدَّ مواقع عثمانية أخرى، فضرب الأسطول الإيطالي مينائَي بيروت والحديدة. واحتلوا جزيرة رودس في البحر الأبيض المتوسط، ثم احتلُّوا مجموعة جزر الدوديكانيز. وهاجمت السفنُ الإيطالية الحربية ممَرَّ الدردنيل وغير ذلك من المواقع العثمانية الأخرى. ورأت الدولةُ العثمانية أنها وقعت في حرب لا قدرةَ لها عليها. ولاحت في الأفق بوادِرُ حرب جديدة ضِدَّ الدولة العثمانية في البلقان. فاضطرت الدولةُ العثمانية إلى قبول المفاوضات مع الإيطاليين، وأمام الأزمات الداخلية والعسكرية والاقتصادية التي مرَّت بها الدولة العثمانية رأت حكومةُ مختار باشا الغازي أن تصِلَ بالمفاوضات مع إيطاليا إلى نتيجة حاسمة، فأرسلت وزيرَ الزراعة العثماني وزوَّدته بصلاحيات واسعة، وتم الاتفاق على عقد معاهدة صلح بين الدولة العثمانية والحكومة الإيطالية في 18 أكتوبر عام 1912م بعد توسُّط من قِبَل حكومة بريطانيا، وقد عُرِفَت تلك المعاهدة باسم معاهدة أوشي لوزان. وقد حوت إحدى عشرة مادة. تعهَّدت فيها الدولتان بإيقاف حالة الحرب بينهما، وسحْب القوات من جبهات القتال، فتسحب الدولة العثمانية قواتِها من طرابلس وبرقة، وتسحب إيطاليا قواتها وسفنها من الجزر العثمانية التي احتلَّتها في بحر إيجة. كما أن الدولة العثمانية سحبت جميع الموظفين الإداريين العاملين في ليبيا. وأعلن السلطان العثماني منح ليبيا استقلالًا تامًّا، أي: أن السلطان العثماني جرَّد الدولة العثمانية من كل أنواع السيادة على ليبيا. وبالمقابل أعلنت إيطاليا جَعْلَ ليبيا خاضعةً تمامًا للسيادة الإيطالية. وقد جاء توقيعُ معاهدة أوشي لوزان بعد أن احتل الفرنسيون الجزائر وتونس، واحتل البريطانيون مصر، وأصبحت الدولة العثمانية مطوَّقة في إفريقيا. وهكذا نفذ الأوروبيون اتفاقياتِهم السرية الرامية إلى تقسيم شمال إفريقيا فيما بينهم!"},{"id":4831,"title":"اقتسام فرنسا وإسبانيا شمال أفريقيا (مراكش) .","date":["العام الهجري :1331","العام الميلادي :1912"],"text":"في أعقاب الوحدة الألمانية عام 1286هـ/ 1870م. وذلك عندما بدأت ألمانيا تعاني من مشكلة عدم تملُّكها للمستعمرات أسوةً ببريطانيا وفرنسا حتى تستطيع تصريفَ منتجاتها، والحصول على المواد الخام اللازمة لصناعتها وإنشاء أسواق لها فيها، ومن هنا بدأت ألمانيا تتطلَّعُ للبحث عن مستعمرات لها في خارج أوروبا؛ ونتيجة لذلك بدأ التنافس بينها وبين فرنسا من أجل مراكش فتصَدَّت فرنسا لهذه المحاولة، وذلك بربط نفسها بعدة اتفاقات مع بعض دول أوروبا، فعقدت اتفاقًا مع إيطاليا على أن تطلق إيطاليا يد فرنسا في مراكش مقابل أن تطلق فرنسا يد إيطاليا في طرابلس وبرقة. كما عقدت فرنسا اتفاقًا مع إسبانيا عام 1317هـ/ 1900م اتفقتا فيه على اقتسام الأجزاء الجنوبية من مراكش فتحصل إسبانيا على منطقة الريف التي تشمل الشريط الساحلي من مراكش المقابِل للساحل الإسباني عند جبل طارق، بينما تحصل فرنسا على ما تبقَّى من مراكش. وفي أوائل عام 1324هـ/ 1906م تم الاتفاق على عقدِ مؤتمر دولي في بلدة الجزيرة الخضراء لدراسة الأوضاع في مراكش. وفيه تم الاعتراف بسيادة مراكش، وتقرَّر إنشاء قوة بوليسية من فرنسا وإسبانيا للمحافظة على الأمن في مراكش."},{"id":4832,"title":"نشأةُ الأرطاوية أول هجر الإخوان في جزيرة العرب .","date":["العام الهجري :1331","العام الميلادي :1912"],"text":"الأرطاوية موقع على طريق القوافل من الكويت إلى القصيم بالقرب من الزلفي، فيه مجموعة من الآبار، وأول من سكنها كان عددٌ من أهالي مدينة حرمة يقَدَّر عددهم بثلاثين رجلًا، وكانوا قد ارتحلوا في هذا العام من حرمة إلى الأرطاوية؛ بسبب نزاع دبَّ بينهم وبين أهلها حول تشدُّدهم الديني. فلما لم يطِبْ لهم المقام في حرمة اختاروا موضِعَ الأرطاوية حيث الآبار والموارد وجودة المرعى، ثم نزلها إحدى عشائر العريمات وشيخها قويعد بن الصريمة، وهي قسم من قبيلة حرب، بعد أن باعوا خيلها وجمالها وما عندها من العروض والأموال في سوق الكويت وغيره، وهبطت الأرطاوية فبَنَت فيها الدور وشرعت تُعنى بأمرين: الزراعة والعلم، وقد أهمل أفرادُها كلَّ شيء سواهما. ثم بعد معركة جراب أعطيت الأرطاوية لفيصل الدويش وجماعته من مطير الذي يعتبر المؤسِّس الحقيقي والزعيم لهجرة الأرطاوية، ثم بعد ذلك نشأت هجرة الغطغط وبعده تتابع نشوءُ الهجر."},{"id":4833,"title":"هجر الإخوان في عهدُ الملك عبد العزيز .","date":["العام الهجري :1331","العام الميلادي :1912"],"text":"كانت الأرطاوية أول هجرة نشأت في نجد سنة 1329هـ حيث تولى رئاستها زعيم مطير فيصل الدويش , والتي تقع في الطريق بين الكويت والقصيم بقرب الزلفي ثم بعده نشأت هجرة الغطغط والتي تقع جنوب غربي الرياض حيث سكنها جزء من عتيبة تحت قيادة سلطان بن بجاد , ثم تتابع نشوء الهجر التي استوطنتها قبائل الجزيرة العربية بتشجيع ودعم الملك عبدالعزيز لها حيث وفر لهم المياه بحفر الآبار وبناء المساجد وتوفير المؤن الغذائية لهم والأعلاف لدوابهم كما أرسال إليهم العلماء وطلبة العلم يعلمونهم الدين وذلك لتحقيق عدة أغراض : منها الحد من تمرد هذه القبائل على سلطان الملك عبدالعزيز, واستثمار قوتهم العسكرية في إتمام توحيد الجزيرة العربية وقد بلغ عدد الهجر حوالي 200 هجرة ممتد في جميع أطراف ووسط الجزيرة العربية , ويبدوا أن بداية نشأة الهجر كحركة عسكرية أحيطت بشيء من الكتمان حتى أن جميع الرحالة الأجانب الذين كانوا يجوبون أرجاء جزيرة العرب من عام 1912م لم يلفت نظرهم في هذه الهجر أي حراك يدل على أنها تمثل ثكنات عسكرية سيكون لها شأن في تقرير عدد من التحولات السياسية على الرغم أن هؤلاء الرحالة كان من أهم مهامهم رصد أي نمو لقوة عسكرية أو تحركات جديدة في المنطقة . غيرَ أنَّ هذه الهجَر أورثت الملِكَ عبدالعزيز مشكلةَ تمويلها ماديًّا؛ فبعد أن باع أولئك الباديةُ جمالَهم وصاروا يتعصَّبونَ بالعِصابة البيضاءِ وأقاموا في الهجَر لا يعمَلونَ شَيئًا في أيامِ السِّلمِ؛ أصبحوا عالةً على الملك عبد العزيز, فأرسل لهم العُلَماءَ والوعَّاظَ يُعَلِّمونهم العِلمَ الشَّرعيَّ والتاريخ وسِيَرَ السَّلَفِ، ويرغِّبونَهم في العمَلِ. وكانت أول مشاركة عسكرية للإخوان مع الملك عبدالعزيز في معركة جراب 1914م ولكنهم ظهروا كقوة ضاربة بجانب الملك عبدالعزيز في معركة تربة 1919م حيث قلبوا موازين القوى داخل الجزيرة العربية لصالح الملك عبدالعزيز ضد خصومة لذلك كان للإخوان دور واضح في ضم كل من حائل وعسير والحجاز، واستمر الإخوان مصدر قوة للملك عبدالعزيز إلى أن حدث الخلاف معهم حول عدد من القضايا العصرية التي أدت إلى نهايتهم في معركة السبلة."},{"id":4834,"title":"ضم الملك عبدالعزيز الأحساء .","date":["العام الهجري :1331","الشهر القمري : جمادى الأولى","العام الميلادي :1913"],"text":"بدأ الملك عبدالعزيز بالاستعداد في القيام بدخول الأحساء فاتفق مع بعض كبار رجالات أسر الأحساء في تنفيذ عملية الفتح. غادر الملك عبدالعزيز الرياض بقواته إلى الأحساء ووصل الرقيقة ومعه 600 جندي ثم وصل الكوت من الناحية الغربية ثم اجتاز أسوار المدينة بعد أن فاجأ الحامية التركية التي سرعان ما أذعنت له بالاستسلام ثم أجلاها إلى البحرين، ولقي عبدالعزيز ترحيب السكان به، ورغم معرفة الملك عبدالعزيز موقف بريطانيا الرافض لضمه الأحساء إلا أنه لم يثنه ذلك من عزمه على دخولها."},{"id":4835,"title":"اغتيال رئيس الوزراء العثماني محمود شوكت .","date":["العام الهجري :1331","الشهر القمري : رجب","العام الميلادي :1913"],"text":"هو محمود شوكت باشا بن سليمان طالب العمري الفاروقي بالولاء، وهو قائِدٌ عراقي، ولي رئاسةَ الوزراء في الدولة العثمانية، وعَلَت شهرتُه في حركة الدستور العثماني. ولِدَ ببغداد سنة 1275ه وكان أبوه متصرفًا في المنتفق، فتعلَّم بها ثم بالمدرسة الحربية في الأستانة، وتقدَّم في المناصب العسكرية إلى أن أعطِيَ لقب فريق، وعيِّن واليًا لقوصوه، فقائدًا للفيلق الثالث بسلانيك. وكان من أعضاء جمعية (تركيا الفتاة) السِّرية التي كان هدفها في ذلك العهد القضاءَ على استبداد السلطان عبد الحميد الثاني. ونجحت الجمعية في إعلان (الدستور) وقامت على إثره فتنة (الرجعيين) في إبريل (1908) فزحف محمود شوكت بفيلقه من سلانيك على العاصمة (الأستانة) فدخلها عنوةً بعد يومين، وخلع السلطان عبد الحميد، وولَّى محمد رشاد، وتألَّفت وزارة كان محمود شوكت وزيرَ الحربية فيها، ثم أسندت إليه الصدارة العظمى (رئاسة الوزراء) واشتَدَّت في أيامه وما قبلها سيطرةُ الاتحاديين، وهم المظهر العلني لتركيا الفتاة، وجاهروا بسياسة تتريك العناصر، ولم يكن محمود شوكت (وهو جركسي الأصل، عربي المنبت) من أنصارِهم في تلك السياسة، اغتيل شوكت أمام نظارة الحربية، والذي صعد إلى الوزارة قبل 5 أشهر في إطار انقلاب نظَّمته جماعةُ الاتحاد والترقي، واتخذ الاتحاديون حادثَ الاغتيال وسيلةً لتصفية المعارضة، حيث أُعدم 29 شخصًا."},{"id":4836,"title":"حرب البلقان الثانية .","date":["العام الهجري :1331","الشهر القمري : رجب","العام الميلادي :1913"],"text":"نشبت حرب البلقان الثانية، وكان سببها هو رغبة بلغاريا في انتزاع إقليم مقدونيا الشمالية من صربيا، وقد انتهت هذه الحرب بعد 42 يومًا من اشتعالها، بمعاهدة \"بوخارست\" في أغسطس 1913م.كان الصرب والبلغار يأملون أن تساعدهم روسيا في المستقبل؛ لذلك تنصَّلوا من وعودهم للنمسا في عدم القيام بدعاية للجامعة الصربية والدولة السلافية الكبرى في داخل النمسا والمجر، وانتهى الأمر بتكوين العصبة البلقانية التي تضمُّ بلغاريا واليونان والصرب، وحذَّرت الدول الكبرى هذه العصبةَ مِن أي محاولة لتمزيق ممتلكات الدولة العثمانية في البلقان، غير أن الصربَ أعلنوا الحربَ على العثمانيين في (ذي القعدة 1330هـ/ أكتوبر 1912م) فاشتعلت الحربُ في البلقان، وفي ستة أسابيع انتزعت العصبة البلقانية جميعَ أراضي العثمانيين في أوروبا ما عدا القسطنطينية. وأثارت هذه الانتصارات النمسا التي دعت إلى عقد مؤتمر دولي، وكان أهمُّ غرض للنمسا هو حرمانَ الصرب من منفذٍ بحري مباشر على بحر الأدرياتيك، وأصبحت ألبانيا مركزًا للصراع الدبلوماسي الشديد بين النمسا وروسيا، لكِنَّ المشكلة سُوِّيت بإقامة دولة مستقلة في ألبانيا تحكمُها ألمانيا، ووقّعت معاهدة لندن التي حصرت الأملاك العثمانية في أوروبا في القسطنطينية وشبه جزيرة غاليبولي. ولم يكد مدادُ معاهدة لندن يجِفُّ حتى نشبت الحرب بين دول العصبة البلقانية الثلاث على مغانم الحرب، وتدخَّلت الدولة العثمانية ورومانيا في تلك الحرب، وتدخَّلت الدول الكبرى لتحقيق مصالحها، خاصةً روسيا والنمسا، وانتهت الحرب البلقانية الثانية بهزيمة بلغاريا وضعفها، وتنامي قوة صربيا، وتزعزُع مكانةِ النمسا الدولية؛ لذلك فكَّرت النمسا في سحق صربيا عسكريًّا لتفادي خطر تكوين دولة صربيا الكبرى، وبالتالي تسبَّبت الحروب البلقانية في زيادة التوتر داخل الكتلتين الأوروبيتين المتصارعتين: الحلف الثلاثي، والوفاق الثلاثي، والاستعداد لمواجهة عسكرية كبرى."},{"id":4837,"title":"توقيع معاهدة بين الدولة العثمانية وبريطانيا .","date":["العام الهجري :1331","الشهر القمري : رجب","العام الميلادي :1913"],"text":"وقَّعت بريطانيا والدولةُ العثمانية معاهدةً تتضَمَّنُ اعتراف الدولة العثمانية باستقلال الكويت وترسيم خرائط حدودية بين البلدين واعتراف الدولة العثمانية بملكية الكويت على جُزُر مثل وربة وبوبيان ومسكان وفيلكا وعوهة وكبر، واعترفت بحقِّ شيخ الكويت في الحصول على الزكاة من القبائل المحيطة بالكويت بمسافة 362 كيلومترًا. ولكِنْ بعد نشوب الحرب العالمية الأولى التي أصبحت فيها بريطانيا والدولة العثمانية أعداء تمَّ إقرار أن المعاهدة لا تعني شيئًا، وأعلنت بريطانيا بأن الكويت إمارة مستقلة تحت الحماية البريطانية."},{"id":4838,"title":"مصر تحت الحماية البريطانية .","date":["العام الهجري :1332","العام الميلادي :1913"],"text":"تعرَّضت مصر للاحتلال الإنجليزي ثلاثَ مرات؛ الأولى بحجة إخراج الفرنسيين من مصر؛ لعجز الدولة العثمانية وحدها عن إخراجهم، والثانية سنة 1807م وكانت من أخلاط من الجنود، والثالثة كانت سنة 1882م وبقيت أكثر من ثلاث وسبعين سنة، فعاصر الاحتلال البريطاني حكم خمسة من حكام أسرة محمد علي هم: توفيق، وإسماعيل، وحلمي الثاني، وحسين كامل، وفؤاد، وفاروق، واستطال إلى الأيام الأولى من الحُكم الجمهوري في مصر، وإذا كانت السيادة العثمانية قد زالت عن مصرَ مِن الناحية الواقعية في سنة 1914م وتأييد زوالها من الناحية الدولية في معاهدة سيفر سنة 1920م، ثم معاهدة لوزان سنة 1923م، فاستمر الاحتلالُ تحت عدة مسميات من احتلال مؤقَّت، إلى حماية مقنَّعة، ثم حماية واقعية، ثم حماية سافرة، ثم استقلال شكلي، ثم تحالف بريطاني مصري."},{"id":4839,"title":"عزل بريطانيا للخديوي عباس حلمي عن عرش مصر .","date":["العام الهجري :1332","الشهر القمري : صفر","العام الميلادي :1914"],"text":"قامت بريطانيا بعزل الخديوي عباس حلمي عن عرش مصر، وتعيين عمه \"حسين كامل\" وأطلقت عليه لقب سلطان؛ نكاية بالسلطان العثماني، وذلك بعد قرارها بإعلان الحماية على مصر. وكان ذلك الإجراءُ في إطار سياسة بريطانيا الرامية إلى عزل مصر عن الدولة العثمانية التي كانت قد دخلت الحربَ العالمية الأولى ضدَّ إنجلترا ودول الحلفاء."},{"id":4840,"title":"مراسلات حسين مكماهون بين بريطانيا والشريف حسين .","date":["العام الهجري :1332","الشهر القمري : شعبان","العام الميلادي :1914"],"text":"استغَلَّت بريطانيا المشكلةَ التي بدأت تحدُثُ بين الأتراك والعرب، فعملت بريطانيا لإغراء الشريف حسين وإعداده نفسيًّا للثورة على الدولة العثمانية، وأبدَوا استعدادهم لمساعدته في قضيته، فبدأ الشريف حسين بإرسال رسالته الأولى إلى السير هنري مكماهون نائب ملك بريطانيا في مصر في 14 تموز 1915م ثم تبِعَتْها رسائل أخرى، وكلها خمس رسائل، كان آخرها رد مكماهون في آذار 1916م، وكان الإنجليز يزيدون في تبجيل الشريف ويداهنونه ويجارونه في مطامِعِه وأحلامه، ولا يبذلون رغمَ كُلِّ ذلك أيَّ وعد صريح، ولا يجيبونه إجاباتٍ واضحةً صريحة، ويكتفون بجواب شفوي من حامل الرسالة فيما لا يريدون أن يتقيَّدوا فيه بوعد مكتوب، وكانت نظرةُ الشريف حسين إسلامية؛ مما جعل الإنجليز ينصرفون عنه إلى ابنه فيصل في زعامة الثورة، حتى سماه لورنس نبيَّ الوطنية، وتمَّت جميع تلك المراسلات باللغة العربية وبأسلوب غامض معقَّد، وكانت المراسلات من الطرفين تُترجَم إلى لغة الطرف الآخر، ورفضت بريطانيا نشرَ نسخة معتمدة رسمية للنصوص كاملةً باللغة الإنجليزية؛ بحجة أن ذلك يضرُّ بالمصلحة العامة؛ وذلك لأن هذه المراسلات أصبحت الخلافَ الأساسي حول فلسطين؛ إذ لم يثبت أن فلسطين قد نُصَّ عليها صراحةً أو ضمنًا في تحفُّظات مكماهون رغم أنَّ بريطانيا كانت ترى أن فلسطين من ضمن المناطق المستثناة من سوريا، ونصب الشريف حسين نفسَه ممثلًا للعرب في آسيا، وتعهدت بريطانيا له بأن يكون ملكُهم بخلافة إسلامية، وكأنها صاحبة الحَلِّ والعقد، وتنازل حسين عن ولايتَي إسكندرون ومرسين والمناطق الشمالية السورية، ووافق على مصالح فرنسا في ولاية بيروت لِما بعد الحرب، وعلى مصالح بريطانيا في البصرة وبغداد، وقَبِلَ بكوادر استشارية من دُول الحلفاء لتشكيل هيئة إدارية قومية من الإنجليز، وكانت النتيجةُ أن سَخَّرت بريطانيا العربَ لقتال العثمانيين في بلاد الشام بدل أن يخوضَ هذه الحرب الإنجليزُ والفرنسيون، وكان من غايات الإنجليز من ثورة الحسين تعطيلُ الجهاد الإسلامي الذي أعلنه الأتراكُ باسم السلطان في استانبول، فعندما يعلِنُ الشريف حسين الثورة سيسمع له المسلمون أكثَرَ مِن سماعهم للسلطان التركي بحُكمِ نسب حُسين الشَّريف."},{"id":4841,"title":"اندلاع الحرب العالمية الأولى (العظمى) وانضمام تركيا إلى جانب ألمانيا .","date":["العام الهجري :1332","الشهر القمري : رمضان","العام الميلادي :1914"],"text":"انقسم المعسكر الأوربي إلى قسمين؛ الأول: ضَمَّ دولَ المحور: ألمانيا، والنمسا، وبلغاريا، وانضمت لهم الدولةُ العثمانية بسبب تعاملها مع ألمانيا في المجال العسكري؛ حيث كانوا هم مدرِّبي الجيوش العثمانية، والقسم الثاني: دول الحلفاء، ضم: إنجلترا، وفرنسا، وروسيا، وإيطاليا، ورومانيا، واليونان، واليابان، و كانت تسمَّى بالحرب العظمى، وبعد قيام الحرب العالمية الثانية عُرِفَت بالحرب العالمية الأولى، بينما الأمريكان يسمونها بالحرب الأوروبية. استطاع الإنجليز بمراسلات مكماهون ممثل بريطانيا مع الشريف حسين أن يضمُّوا العرب لمعسكرهم، أعلنت الدولة العثمانية في بداية الحرب العالمية الأولى يوم 3 أغسطس 1914 حيادَها، وهو ما صرَّح به الصدرُ الأعظم للسفير البريطاني، رغم وجود بَعثة عسكرية بريطانية في استانبول لإعادة تنظيم القوات المسلحة للدولة على مستوى مشابِه للنَّسَق الألماني."},{"id":4842,"title":"انضمام الدولة العثمانية إلى جانب دول المحور في الحرب العالمية الأولى .","date":["العام الهجري :1332","الشهر القمري : ذي الحجة","العام الميلادي :1914"],"text":"حاول الحلفاءُ إبقاءَ الدولة العثمانية على الحياد بإغرائِها بالقروض المالية، وإلغاء الامتيازات الأجنبية التي كانت قائمةً والتي كانت سببًا في كثير من المشكلات الداخلية، والسماح للبحَّارة الألمان بالعودة إلى ألمانيا، غيرَ أنَّ حكومة الاتحاد والترقي رفضت هذا كلَّه، وألغت الامتيازاتِ الأجنبيةَ بنفسها، وقدَّمت مذكِّرةً للحلفاء تطلب منهم إلغاء الامتيازات الأجنبية، وخروج إنجلترا من مصر، وإعادة الجُزُر في بحر إيجة للدولة العثمانية، ومنع روسيا من التدخُّل في الشؤون الداخلية للدولة العثمانية. حاول الحلفاء التأخرَ في رد الجواب، وانقطعت العلاقاتُ. وكانت ألمانيا قد تقدَّمت في الأراضي الفرنسية، ولكنها توقَّفت عند نهر المارن أحد روافد نهر السين الذي يمرُّ من العاصمة باريس، فرأى الألمان يومذاك أن يضغطوا على الدولة العثمانية كي تشتركَ في الحرب إلى جانِبِهم، فعرضوا على الاتحاديين قرضًا ماليًّا بمبلغ خمسة ملايين ليرة ذهبية عثمانية مقابِلَ دخولهم إلى جانبهم، فأمر وزيرُ الحربية أنور باشا الأسطولَ العثماني بالتحَرُّك إلى البحر الأسود وضَرْب مرافئ روسيا على البحر الأسود، فلم يوافِقْ وزير البحرية جمال باشا، وكاد الخلافُ يقع بينهما إلا أن جمال عاد وامتثل لرأي أنور، وخاصةً أن القرض الألماني كان من أهم المغريات له. أعلنت الدولةُ العثمانية دخولَها الحربَ وانضمامَها إلى دول المحور ضِدَّ الحلفاء.كانت السيطرةُ على مقاليد الحكم في الدولة بيد الاتحاديين منذ عزل السلطان عبد الحميد الثاني؛ لذلك كان السلطان العثماني محمد الخامس رشاد ضِدَّ الحرب، ولكِنْ ليس له من الأمر شيءٌ، وأُجبر السلطانُ على قبول الأمر، وأعلن الجهاد الإسلامي ضد دول الحلفاء، لكن هذا الإعلان لم يجد صدًى عند المسلمين لعِلمِهم أنَّ الألمان نصارى مثل أعدائِهم من الحُلُفاء، فكُلُّهم كفَّار، فلم الخوض وإراقةُ دماء المسلمين في خصومةٍ بين الكُفَّار!! واشتعلت نارُ الحرب بين الحلفاء والدولة العثمانية على عِدَّةِ جبهات وقد جمعت الدولة بعد التعبئة نصف مليون جندي تحت السلاح وربع مليون تحت التدريب، والاحتفاظ بمائتي ألف جندي حول العاصمة والدردنيل، وأُرسل إلى فلسطين أربعون ألفًا وأكثر من مئة ألف على شكل قطعات موزعة في سوريا والقوقاز، وهاجم العثمانيون الروسَ مِن ناحية القوقاز لتخفيفِ الضغط عن الألمان غيرَ أنهم فَشِلوا وتراجعوا إلى أرضورم، أما على الجبهة المصرية فأرادت الدولةُ قطع قناة السويس عن إنجلترا، ولكِنْ تأخَّر مسيرُهم إليها بسبب فرار كثيرٍ مِن الجيش الشامي، فاضطر أن يستبدل به آخر من الأناضول؛ ولصعوبة إيصال المدافع إلى سيناء، ولإبقاء قطعات على سواحل الشام للخَوفِ من النصارى الكاثوليك التابعين لفرنسا، وأكثرهم في بيروت، ومن النصارى الأرثوذكس التابعين للروس، وهم متوزِّعون في بلاد الشام، ثم وصلت القوات العثمانية إلى القناة التي كان يحميها الهنودُ، ونَفِدَت الذخيرة العثمانية ولم تستطِعْ فعل شيء، فرجعت لقواعدها في غزة ومعان، وبعد شهرين جرت محاولةٌ أخرى للهجوم، وقاد الألمان العملياتِ ولكِنَّهم فشلوا أيضًا وأُعيدت الكَرَّة بعد ثلاثة أشهر وأيضًا فَشِلت، وأما على صعيد اليمن فكان الهدفُ هو قطع الطريق على الإنجليز إلى الهند ولم تنجح أيضًا، وعلى جبهة الدردنيل فقد كانت محصنةً من البر والبحر، وكانت قواتُ الحلفاء قريبةً من المضيق وقامت القوات العثمانية بالهجومِ عليها، لكنهم فشلوا أيضًا، وأما الإنجليز الذين استطاعوا جرَّ العرب لهم فتحركوا وهاجموا العثمانيين في سيناء وجبل الدروز وبعلبك، وتراجع الجيش العثماني وأصيب بالمجاعة أيضًا، وتقدَّم الإنجليز في فلسطين بقيادة الجنرال اللنبي ودخلوا القدس وأعلن يومها اللنبي صليبيته، فقال: الآن انتهت الحروب الصليبية، ثم قام الإنجليز بالهجوم على نابلس فتراجع الألمان والعثمانيون، ووصل الفيلق العربي بقيادة فيصل بن الحسين بمساعده لورانس الإنجليزي ودخلوا معان ودمشق، فأصبحت بلاد الشام في قبضة فيصل والإنجليز، وأما المعارك على مضيق الدردنيل فكانت متوازيةً، فلم ترجح كفَّة أيٍّ من المعسكرين على الآخر مع بدء ظهور مصطفى كمال ولمعان نجمه في هذه المعارك، ومع انسحاب العثمانيين من الشام والعراق بدأ الضعفُ يظهر عليهم وعلى حلفائهم الألمان إلى أن التقى المسؤولون العثمانيون مع الإنجليز على ظهر الباخرة الإنجليزية أغامنون، ووُضِعَت شروط هدنة مودروس، وأعلنت الدولة استسلامَها، فكان الاتحاديون في أثناء حكمهم القصير قد أضاعوا كلَّ أجزاء الدولة في أوربا؛ حيث استقلت بلغاريا، واحتَلَّت النمسا البوسنةَ والهرسك، وأخذ اليونانيون جزيرةَ كريت، واحتلت إيطاليا بعض جزر البحر المتوسط، وهكذا ضَعُفت الدولة العثمانية، وأصبحت على شفا الهاوية، وازداد ضعفها على ما كانت عليه."},{"id":4843,"title":"وفاة الشيخ شبلي النعماني أحد علماء الهند .","date":["العام الهجري :1332","الشهر القمري : ذي الحجة","العام الميلادي :1914"],"text":"هو الشيخ شبلي حبيب الله بن سراج الدولة النعماني، أحد علماء الهند. اعتنى به والدُه الشيخ \"حبيب الله\"؛ حيث كان من العلماء، فنشأ محبًّا للعلم. رحل شبلي في طلب العلم، وتنقل بين لكنو ودلهي ولاهور ورامبور وسهارنبور وغيرها من المدن الهندية، فدرس الأدب والفقه، والحديث وعلوم الفارسية والأدبية والعربية، كما درس الهندسة والمنطق والفلسفة، وتلقَّى العلم على عدد من شيوخ الهند، منهم الشيخ \"محمد فاروق الجرياكوتي\"، والشيخ \"أحمد علي\"، والشيخ \"إرشاد حسين\"، والشيخ \"فيض الحسن\". وعندما بلغ التاسعة عشرة من عمره سنة (1293هـ/1876م) قرَّر شبلي أداء فريضة الحج، وهناك اتصل بعددٍ مِن علماء الحجاز، وأتم تعليمَه بالأراضي المقدسة، ثم عاد بعد ذلك إلى \"أعظم كره\" حيث عمل بالمحاماة لفترة قصيرة، ولكنه لم يستطع أن يندمِجَ في تلك المهنة طويلًا، وسرعان ما تركها ليعمَلَ بوظيفة أخرى، إلا أنه لم يستطِعْ أن يعيش بعيدًا عن البحث والدراسات، فدعاه حنينه للعلم وشوقه للمعرفة إلى التفرغ للقراءة والاطلاع، فترك الوظائف العامة وعكَفَ على المطالعة والدراسة والبحث، ثم ما لبث أن بدأ في الكتابة والتصنيف، وظهرت مواهبه وقدراته في التأليف ونظْم الشعر، وبدأ اسمُه يلمع ويشتهر ذِكرُه بين قراءة الأردية والفارسية. عَمِلَ في جامعة عليكرة، واشتغل بالدعوةِ والدفاع عن الإسلام، وشارك في تأسيسِ ندوة العلماء بمدينة لكنو."},{"id":4844,"title":"موقف الملك عبد العزيز من أطراف الصراع في الحرب العالمية الأولى  .","date":["العام الهجري :1333","العام الميلادي :1914"],"text":"عندما اندلعت الحربُ العالمية الأولى بعث الملك عبدالعزيز برسائل إلى كل من الشريف حسين في مكَّةَ، وسعود بن صالح في حائل، والشيخ مبارك الصباح في الكويت، يقترح عليهم عقدَ لقاء بين حكَّام العرب للحيلولة دون جَرِّهم إلى العمليات الحربية، وتوقيع معاهدة مع الدول الكبرى لضمان تقريرِ مصير البلاد العربية، ولم تكن مصالحُهم متوافقةً آنذاك؛ لذلك تعذَّر وضعُ موقفٍ مشترك؛ فأمير حائل ردَّ بأنه سيقاتل مع الدولة العثمانية ضَدَّ من يقاتلها. وعلى الرغم من إعلان الملك عبدالعزيز موقِفَ الحياد من الحرب إلا أن حكومة بريطانيا في الهند أرسلت إليه تطلُبُ منه التعاونَ معهم في الاستيلاء على البصرة مقابِلَ اعترافها به حاكمًا على نجد والأحساء، وحمايته من أي هجوم يأتيه من البحر، ومساعدته ضِدَّ أي انتقام من الدولة العثمانية، إلا أن الملك عبدالعزيز أجابهم بأنه سيظلُّ على الحياد ويترك جميع خياراتِه مفتوحةً، وفي المقابل حاول العثمانيون استمالةَ الملك عبدالعزيز عن طريق طالب النقيب، إلا أنه أخفَقَ، وبعد أن استولت بريطانيا على البصرة ، كرَّر العثمانيون محاولتهم لاستمالة الملك عبدالعزيز وأرسلوا وفدًا من المدينة المنورة يحمل 10 آلاف ليرة لإقناعه بتأييد الدولة العثمانية إلا أن الملك عبدالعزيز اعتذر بأنَّه عاجز عن مقاومة الإنجليز، ولكِنَّه وعد بعدم إعاقة تجَّار نجد عن تزويد الجيش التركي بالأغذية، فصارت قوافل الأتراك طوال الحرب تجتاز أراضيه من الشام إلى عسير واليمن؛ ونتيجةً لهذا الموقف فالملك عبدالعزيز لم يقم بمهاجمة الدولة العثمانية في العراق كما أراد الإنجليز، ولم يحارب الشريف حسين بالحجاز كما أراد العثمانيون."},{"id":4845,"title":"إعلان إنجلترا فصل مصر عن الدولة العثمانية .","date":["العام الهجري :1333","العام الميلادي :1914"],"text":"كانت إنجلترا قد احتلَّت مصر، ولكِنْ مع ذلك بقي الولاةُ عليها من قِبَل الدولة العثمانية، وبقيت تابعةً اسمًا ورسميًّا للدولة العثمانية، ثم بعد أن اندلعت الحرب العالمية الأولى قامت إنجلترا بسبب ظروفِ الحرب بفَرضِ الحماية على مصر لتبعيَّتِها الرسمية للعثمانيين، ولأن العثمانيين وقفوا بجانب ألمانيا ضِدَّ الحلفاء الذين من بينهم إنجلترا، وأعلنت كذلك فَصْلَ مصر عن الدولة العثمانية رسميًّا، وخلعت الخديوي عباس حلمي، وعيَّنَت مكانه حسين كامل، ولقبته بالسلطان نكاية بسلطانِ العثمانيين ومضاهاةً له في سبيل ما لو أعلن سلطانُ العثمانيين الجهادَ، فسيُعلِنُ هذا السلطان الجهادَ، فيتشتت النَّاسُ بين الجهادين أيَّهما يتبعون، ومنعت من الاجتماعات وراقبت الصحفَ وألغت الأحزابَ، وسَخَّرت اقتصاد البلاد لمصلحة الجيش الإنجليزي، وفرضت على الشعب تعبيد الطرق وحفْر الآبار ومدِّ أنابيب المياه."},{"id":4846,"title":"إنشاء معاهدة حدودية بين الدولة العثمانية وبريطانيا .","date":["العام الهجري :1333","العام الميلادي :1914"],"text":"تمَّ إنشاءُ معاهدة حدودية بين الدولةِ العثمانيةِ وبريطانيا؛ لتعيينِ الحدودِ بين شمال اليمن العثماني، وجنوب اليمن البريطاني، وكانت هذه المعاهَدةُ بالنسبة لبريطانيا أهمَّ حَدَثٍ بعد احتلال عدَن عام (1255هـ- 1839م)، وتم التصديقُ عليها عام (1333هـ- 1914م) وبهذه المعاهدة تعرَّضت اليمَنُ لأوَّلِ انشطار إلى جنوبٍ وشمال في التاريخ."},{"id":4847,"title":"فرنسا تصدر مرسومًا في المغرب خاصا بالبربر عرف بالظهير البربري .","date":["العام الهجري :1333","العام الميلادي :1914"],"text":"وضعت فرنسا نُصبَ عينيها لَمَّا دخلت المغرب أن تفَرِّقَ بين العرب وبين البربر؛ لتضرب جماعةً بأخرى، وذلك من باب فَرِّق تسُدْ، وخاصة أن البربر يشكِّلون أكثَرَ من أربعين بالمئة، وفكَّرت بتنصيرهم، ثم استصدرت السلطاتُ الفرنسية مرسومًا (ظهيرًا) عرف بالظهير البربري أعفت فيه البربرَ من تطبيق الشريعة الإسلامية، ومن دراسة اللغة العربية، وسمحت لهم بالتقاضي حسب الأعراف والتقاليد البربرية، وبدراسة اللغة البربرية، ثم استصدرت مرسومًا آخرَ نظَّمَت فيه انتقال الأراضي وملكيَّتها في المناطق البربرية بصورة تتعارضُ مع الشريعة الإسلامية في الإرثِ، ثم استصدرت مرسومًا ثالثًا فيه حكم شيوخ القبائل في مناطقهم حسَبَ العُرف والعادة المتَّبَعة، وأن تُشكَّل محاكِمُ تحكُمُ حسب عادات القبائل البربرية!"},{"id":4848,"title":"احتلال مدينة البصرة بقوة بريطانية .","date":["العام الهجري :1333","الشهر القمري : محرم","العام الميلادي :1914"],"text":"قامت قوةٌ بريطانية قادمة من الهند باحتلالِ مدينة البصرة أثناء اشتعال الحربِ العالمية الأولى، وكان الهدفُ من ذلك حماية أنابيب البترول وتأمين وصولِ الإمدادات."},{"id":4849,"title":"الاحتلال الإنجليزي للعراق وقتالهم مع الجيوش العثمانية .","date":["العام الهجري :1333","الشهر القمري : محرم","العام الميلادي :1914"],"text":"وصلت الحملةُ الإنجليزية من الهند إلى شطِّ العرب في آخر سنة 1332هـ ثم في اليوم التالي احتَلَّت الفاو، جنوب البصرة ثم البصرة في الخامس من محرم، واستمرت النجداتُ تصل إلى الحملة الإنجليزية حتى احتلت العمارة في 21 رجب، كما سيطرت على القرنة والشعبية وبَقِيَت حكومةُ الهند والحكومة الإنجليزية لا يتقدَّمان إلى بغداد حتى شجَّعهم فشل القوات العثمانية في السويس ونجاح مراسلات حسين ومكماهون فتقَدَّموا واحتلوا الكوت بالعراق في 22 ذي القعدة  غيرَ أنَّهم توقَّفوا جنوب بغداد بثلاثين كيلًا، ثم تراجعوا إلى الكوت أمام القوات العثمانية التي حاصرتهم مدة ستة أشهر اضطروا بعدها للاستسلامِ، وتسلَّم العثمانيون 13309 أسيرًا بين ضابط وجندي."},{"id":4850,"title":"معركة جراب بين الملك عبدالعزيز وقوات ابن رشيد .","date":["العام الهجري :1333","الشهر القمري : ربيع الأول","العام الميلادي :1915"],"text":"اشتبكت قوات الملك عبدالعزيز مع قوات ابن رشيد قرب بئر جراب شمالي الزلفي وكانت قوات الملك عبدالعزيز تتكون في معظمها من أهل العارض وثلاثمائة خيال من العجمان ومدفع واحد فقط وبعض البادية المتأثرين بفكر الإخوان (إخوان من أطاع الله) الحركة الناشئة داخل الجزيرة العربية  واستمرت المعركة عدة إيام وقتل أثناءها شكسبير مبعوث كوكس إلى الملك عبدالعزيز وقيل انه حضر المعركة كمراقب على الرغم أن الملك عبدالعزيز كان لا يرغب في تواجده معه في ميدان المعركة ونصحه في البقاء بالزلفي لكن شكسبير أصر على الحضور معهم إلى ميدان المعركة، احتدم القتال وأصيب شكسبير برصاصة أودت بحياته. كان فرسان العجمان قد تراجعوا خيانة وهم يصيحون صيحة الانهزام فأغارت إذ ذاك بادية ابن رشيد على الجناح الإيسر من قوات ابن سعود فدحرته وغنمت أمواله، وأما بدو الملك عبدالعزيز وأكثرهم من مطير فقد أغاروا اثناء ذلك على جيش ابن رشيد ومخيمه فغنموا ما فيه، فيوم جراب كان على قوات الملك عبدالعزيز وقوات ابن رشيد على السواء ولم يكن فيه ظافرا غير البدو من الفريقين."},{"id":4851,"title":"مطالبة روسيا بالقسطنطينية في حالة فوز الحلفاء بالحرب .","date":["العام الهجري :1333","الشهر القمري : ربيع الآخر","العام الميلادي :1915"],"text":"قام سازونوف وزير الخارجية الروسي بتسليم مذكرة إلى ممثلي إنجلترا وفرنسا، يطالب فيها لروسيا بالقسطنطينية، وبشريط على طول الساحل الشمالي للبسفور وبحر مرمرة والدردنيل، وكذلك تراقيا، وبالجانب الأسيوي للبسفور، وذلك في حالة فوز الحلفاءِ بالحرب."},{"id":4852,"title":"مذابح الأرمن ضد المسلمين في مدينة \"وان\" .","date":["العام الهجري :1333","الشهر القمري : جمادى الآخرة","العام الميلادي :1915"],"text":"قامت العصاباتُ الأرمينية بارتكابِ مذابِحَ وحشية ضِدَّ المسلمين في مدينة \"وان\" الواقعة في الأناضول الشرقية؛ حيث قامت بقتل جميعِ من فيها من المسلمين بعد تعذيبٍ وحشيٍّ."},{"id":4853,"title":"معركة القرضابية  .","date":["العام الهجري :1333","الشهر القمري : جمادى الآخرة","العام الميلادي :1915"],"text":"معركةُ القرضابية من المعارك الفاصلة في جهاد الليبيين ضِدَّ إيطاليا؛ إذ شارك فيها جميعُ الليبيين، كما أنها شكَّلت البداية لاندحار الإيطاليين، وبعد المعركةِ لم يبقَ بيد الإيطاليين إلا مدينتا طرابلس والخمس."},{"id":4854,"title":"معركة كنزان بين الملك عبد العزيز وبني هاجر والعجمان .","date":["العام الهجري :1333","الشهر القمري : شعبان","العام الميلادي :1915"],"text":"حدثت هذه المعركة بين الملك عبد العزيز وبني هاجر والقبائل التابعة له وبين قبيلة العجمان بالقرب من جبل كنزان في الأحساء عندما اعتدى العجمان  على عشائر مبارك بن الصباح فنهبوا مواشيه فكتب ابن الصباح إلى عبدالعزيز يطلب منه تأديبهم ورد المنهوبات فأجابه عبدالعزيز أن العجمان لا يرجعون ما ينهبون إلا بحرب، وإذا عزمت عليّ حربهم تعطيني عهد الله وميثاقه ان تعيني بالمال والرجال وأن لا تسلك معهم مسلكا غير مسلكي ولا تستقبلهم إذا لجأوا إليك ولا تتوسط بالصلح بيني وبينهم فعاهده مبارك على ذلك وأعطاه عهد الله فسار عبدالعزيز بقواته إلى الأحساء والتقى بالعجمان عند كنزان فجُرح عبدالعزيز وقتل شقيقه سعد وانهزمت قواته إلى الأحساء فلحق بهم العجمان وحاصروهم في الأحساء ثلاثة أشهر فأرسل إلى أبيه في الرياض يطلب المدد وإلى الشيخ مبارك يستنجده. فوصلت نجدة من أهل نجد بقيادة أخيه محمد بن عبدالرحمن ومعه ابن عمه سعود الكبير أما ابن الصباح فقد تأخر في إرسال النجدة فأرسل له الملك عبدالعزيز يذكره بالعهد، فجهز له ابنه سالم بقوة صغيرة 150 رجل من الحضر و200 من البدو فجاءوا الأحساء وانضموا إلى جيش الملك عبدالعزيز."},{"id":4855,"title":"انقلاب مبارك بن الصباح على الملك عبدالعزيز .","date":["العام الهجري :1333","الشهر القمري : ذي القعدة","العام الميلادي :1915"],"text":"قدم سالم بن مبارك ابن الصباح مع قوة صغيرة لنجدة الملك عبدالعزيز بعد هزيمته من العجمان إلا أنه انقلب على الملك عبدالعزيز واتفق مع العجمان وصالحهم وأعلن حمايتهم وهجر حليفه الملك عبدالعزيز، فكتب محمد بن عبدالرحمن إلى أخيه عبدالعزيز يستأذنه في الهجوم على العجمان وابن الصباح فأجابه: \" لا تفعل كيف نكون حلفاء أول النهار وأعداء في آخره والناس لا يعرفون حقيقة الحال\" ثم كتب إلى مبارك يشكو إليه خيانة ابنه سالم ويقول: \" لم أقدم إكراما لك على تأديبه\" فكتب له الشيخ يذكره بأنه بينه وبين العجمان صداقة قديمة فغضب الملك عبدالعزيز وزحف مسرعا يريد مهاجمة العجمان وابن الصباح ولكنه حين وصل إلى معسكر أخيه محمد جاءه خبر وفاة الشيخ مبارك فوقف مدهوشا محزونا وقال: إنا لله وإنا إليه راجعون مات الشيخ مبارك."},{"id":4856,"title":"محاولة السنوسيين بليبيا غزو غرب مصر .","date":["العام الهجري :1334","العام الميلادي :1915"],"text":"رأى السنوسيون في برقةَ مؤازرةَ الدولة العثمانية استجابةً لدواعي الجهاد الديني والتضامن الإسلامي، وذلك بالهجوم على القوات البريطانية في مصر، وكان كلٌّ من العثمانيين والإنجليز يحاولون كسبَ السيد أحمد الشريف السنوسي لصَفِّه، ولكن رغم ما قدَّمه هنري مكماهون للسنوسي من أجل كسبِه إلى طرفه إلَّا أنه آثر البقاءَ مع العثمانيين، فقام بمهاجمة الحدود المصرية الغربية، وتوغَّل داخِلَ الأراضي المصرية، ونازل القوات البريطانية المنتشِرة في المنطقة وبنفس الوقت كان العثمانيون يحاولونَ التوغل على الحدود الشرقية، واستطاع السنوسي مع عددٍ مِن المقاتلين قرابة الخمسة آلاف من القوات النظامية وبعض القوَّات التركية أن يستولوا على مدينة السلُّوم وسيدي براني بمصر، وتوغلوا حتى وصلوا زاوية أم الوخم غربي مرسى مطروح، واعتصم البريطانيون في المرسى واتخذوه مقرًّا لقيادتهم، وانضمَّ بعضُ الضباط المصريين إلى السنوسيين في هذا القتال، وانتشرت الثورة من قِبَل هؤلاء الضباط؛ مما فاجأ البريطانيين، ودارت المعارك العنيفة بين السنوسيين والبريطانيين من طرَفٍ، وبين المصريين ومعهم السودانيين من جهة أخرى على البريطانيين، حتى لقي البريطانيون الهزيمةَ في وقعة وادي ماجد، وكانت الحرب سِجالًا؛ فقد هُزم السنوسيون في وقعة بير تونس، ومما حقَّقته الحملة السنوسية أنها احتجزت قوات بريطانية كبيرة على الحدود الغربية لمصر وفي صحراء مصر في وقت كانت تحتاجُهم فيه بريطانيا في أماكن أخرى، ولكِنَّ المجاهدين لم يكن لهم من الإمدادات ما يؤهِّلُهم للبقاء طويلًا في القتال فبدأ انسحابهم تدريجيًّا، وانسحب السنوسيون إلى الجفرة، ثم تحولوا إلى مقاتلة الإيطاليين."},{"id":4857,"title":"أوروبا تُرغم ملك الحبشة على التنازل عن عرشه بعد إعلان إسلامه .","date":["العام الهجري :1334","العام الميلادي :1915"],"text":"بعد أن هلك منليك الثاني ملك الحبشة عام 1331هـ/ 1913م خلَفَه حفيده ليج أياسو الذي كان بالأصل مسلما؛ وإن تسمَّى ليج باسم نصراني ونشأ في رعايةِ جَدِّه النصراني منليك الثاني والد أمه أرجاس، إلا أنه كان يتردَّد على مساجد هرر، وشيَّد المساجد فيها، واتخذ عَلَمًا جديدا للدولة، فوضع الهلال بدل الصليب، وأرسل هذا العلم إلى القنصل العثماني في أديس أبابا واتَّصل مع محمد عبد الله حسن مهدي الصومال، وحاول ليج توحيدَ كلمة المسلمين وإقامةَ حِلفٍ إسلامي ضِدَّ الحلفاء، وادعى الانتساب إلى آل البيت، وكلُّ هذه الأعمال لم ترضِ عنها صليبية أوربا، فأصدرت الكنيسة قرارًا بحرمان ليج أياسو من التاجِ الحبشي، وحرَّضت النصارى ضِدَّه، ففر إلى بلاد الدناقل وبقي هناك حتى قُبِض عليه عام 1339هـ/ 1921م، فلما انتصر هيلا سيلاسي أعدمه عام 1353هـ/ 1934م وأعطت المُلك لزاويتو ابنة منليك الثاني وعيَّنت رأس تفاري (هيلا سيلاسي) وصيًّا ووريثًا."},{"id":4858,"title":"إنهاء حركة علي دينار وضم دارفور للسودان .","date":["العام الهجري :1334","العام الميلادي :1915"],"text":"كانت أسرة سولونغ تحكم منطقة دارفور غرب السودان حتى عام 1293هـ، ثمَّ بعد أن أعيد الحُكمُ الإنجليزي على السودان وبعد معركةِ كرري 1316هـ غادر أم درمان علي دينار بن زكريا السولونغي ومعه عشرة أفراد، وانضم لهم في طريقِهم قرابةُ الألفي رجلٍ، واتجه نحو دارفور، ولما وصل الفاشر سلمت له وبدأت المنافسة بينه وبين إبراهيم علي الذي وضعته القواتُ الإنجليزية في دارفور، فتنازل إبراهيم لعلي دينار الذي استطاع أن يضبِطَ أمور دارفور وينشر الأمنَ، ثم بدأت شهرتُه تزداد حتى أصبحت الحكومةُ السودانيةُ الخاضعةُ للإنجليز تخافه؛ فقد وصل أمرُه إلى أن أصبح يرسِلُ محملًا للحجاز كأيِّ حاكمٍ مُسلمٍ، وبالمقابل رأى هو أنه لا يحصُلُ على حقِّه من الحكومة، بل إن كلَّ تعدٍّ عليه تسكت عنه الحكومة، وكلَّ متمرد عليه تؤويه الحكومة، وكان علي دينار قد أيَّد العثمانيين في الحرب العالمية الأولى، فسيَّرت الحكومة جيشًا من ثلاثة آلاف مقاتل أغلبُهم مصريون إلى دارفور، وجرت موقعةُ برنجية بين الطرفين، فهُزم علي دينار أمام هذا الجيش المجهَّز، وهرب إلى جبل مرة، ثم تبعوه وقُتِلَ في محرم 1335هـ / 6 تشرين الثاني 1916م وضُمَّت دارفور إلى السودان."},{"id":4859,"title":"اتفاقية (سايكس بيكو) وفرض الاحتلال الأوروبي على الشرق الأوسط .","date":["العام الهجري :1334","العام الميلادي :1915"],"text":"في الوقت الذي كان الشريف حسين بن علي أميرُ مكة ما زال يتفاوضُ مع السير هنري مكماهون لإعلان الثورة العربية، كانت إنجلترا تعقِدُ صفقةً جديدة مع فرنسا لتحديدِ مناطق النفوذ بينهما في البلاد العربية، منعًا لأي خلاف قد يحدثُ في المستقبل، وهذه الاتفاقية -التي عُرِفَت باسم واضعيها السير مارك سايكس الإنجليزي، والدبلوماسي جورج بيكو الفرنسي- هي جزء من اتفاقية واسعة عقدتها دول روسيا وبريطانيا وفرنسا بين بعضها لاقتسام أجزاءٍ كبيرة من أراضي الدولة العثمانية، وقد تمَّ التصديقُ عليها في شهر نيسان سنة 1916م والحرب دائرةٌ تراقُ فيها دماء العرب والمسلمين لتحقيقِ مطامِعِ الحلفاء؛ فقد عيَّنت الحكومة البريطانية مارك سايكس، وعَيَّنت فرنسا جورج بيكو قُنصُلَها في بيروت مندوبَينِ عن الدولتين ليقوما بمباحثات غايتُها الاتفاق على نصيبِ كلٍّ منهما ضِمنَ نطاق الاتفاقية الثلاثية الكبرى، وتوصَّل المندوبان إلى اتفاقٍ صادقت عليه حكومتهما في أيار 1916م واحتفظت فرنسا في هذه الاتفاقية بمساحة كبيرة من أراضي الأناضول الجنوبية وشمالي سوريا والموصل، وأما بريطانيا فاحتفظت بولايتي البصرة وبغداد ولواء كركوك إضافةً إلى القسم الجنوبي من سوريا الطبيعية (أي: فلسطين) واتفقت الدولتان على جعل فلسطين باستثناءِ منطقة النقب منطقةً تخضع لحكمٍ دولي خاص، وقضت الاتفاقيةُ كذلك على إنشاء حُكمٍ مباشر لفرنسا في الساحل السوري، وعُرِفَت بالمنطقة الزرقاء، ويصارُ إلى الاعتراف بدولة عربية مستقلَّة تحت الانتداب الفرنسي، أي: سوريا الداخلية، ومثلها في منطقة النفوذ البريطاني، أي: شرق الأردن، فحَدَّدت الدولتان مصيرَ العرب وحدهما، وحتى الشريف حسين لم تطلعه بريطانيا على اتفاقها مع فرنسا ولم تكشف هذه الاتفاقية إلا بعد الثورة الشيوعية سنة 1917م، وكانت هذه الاتفاقيةُ مقدِّمةً لإعطاء فلسطين إلى اليهود، ومن ثم تحقيق حلمِهم الصهيوني!!!"},{"id":4860,"title":"وفاة الشيخ مبارك بن صباح أمير الكويت .","date":["العام الهجري :1334","الشهر القمري : محرم","العام الميلادي :1915"],"text":"هو مبارك بن صباح بن جابر بن عبد الله بن صباح، من عنزة، أمير الكويت، مِن الشُّجعان الدُّهاة، ولِدَ سنة 1252هـ في الكويت ونشأ فيها. كان نفوذ الكلمة فيها لأخويه (محمد، وجراح) فقتلهما سنة 1313هـ واستقام له أمر الكويت، وصار حاكِمَها المُطلَق. وهو سابع من وَلِيَها من آل الصباح. وكان للعثمانيين (الترك) شيءٌ من السلطان في الكويت، فحرَّضوا ابن الرشيد على مبارك، فظَفِرَ مبارك. فحاولوا نفيَه سنة 1315هـ بحيلة، فأرسلوا إحدى السفن لنقله، ليكونَ من أعضاء مجلس الشورى بالأستانة، فلجأ إلى الإنجليز، فأنقذوه من الأتراك، وأعلنوا حمايتَهم للكويت. وظَلَّ حاكِمًا للكويت تحت حماية الإنجليز إلى أن مات فيها بقَصرِه. كان مبارك عاليَ الهمة، طموحًا جبَّارًا مَهِيبًا، فيه حِلمٌ وكرم. لجأ آلُ سعود إليه بعد سقوطِ دولتهم الثانية، وعاش عبد العزيز بدايةَ شبابه في الكويت وتحت رعاية ابن الصباح، ساد الأمن في عهده فازدهرت الكويت تجاريًّا، وشيَّد فيها أوَّلَ مدرسة نظاميَّة، هي المدرسة المباركية، كما شُيِّد في عهده أوَّلُ المستشفيات الطبية. عانى مبارك في آخر أيامه من مرض الملاريا وتصَلُّب الشرايين، خرج من بيته إلى مجلسه في يوم وفاته بعد أن غاب عنه لعدة أيام، وقد كان يريد سماع آخر الأخبار بشأن المعارِكِ التي تحدث في العراق زمَنَ الحرب العالمية الأولى، وبعد سماعه الأخبار تناول العشاءَ وأسند رأسَه على الأريكة وغَطَّ في نوم عميق، ثم أراد حارِسُه أن يوقِظَه كي يذهب إلى البيت، فوجده قد توفِّيَ، وتولى حكمَ الكويت بعده ابنُه جابر."},{"id":4861,"title":"معاهدة دارين (القطيف) .","date":["العام الهجري :1334","الشهر القمري : صفر","العام الميلادي :1915"],"text":"وقّعت هذه المعاهدة عند بلدة دارين في جزيرة تاروت المقابلة لميناء القطيف، ونصت المعاهدة على اعتراف بريطانيا بأن عبدالعزيز حاكما مستقلا في نجد والأحساء والقطيف والجبيل ولأبنائه من بعده."},{"id":4862,"title":"فشل بريطانيا وحلفائها في الاستيلاء على مضيق البوسفور والدردنيل .","date":["العام الهجري :1334","الشهر القمري : صفر","العام الميلادي :1915"],"text":"مارست الدولةُ العثمانية سيادتَها على مضيقي البوسفور والدردنيل، وبحر مرمرة، وكانت هذه المضايقُ تصِلُ بين البحر الأسود وبحر إيجة الذي هو جزءٌ من البحر المتوسط، ولم يكن للبحر الأسود مخرجٌ يتَّصِلُ عن طريقه بالبحار العامة إلا عبر هذه المضايق. وقد نجحت الدولةُ العثمانية في فرض سيادتها على هذه المضايق. وبلغ من هيبة الدولةِ العثمانية في فترة قوَّتِها أنَّ الرعايا الروس إذا أرادوا ممارسةَ التجارة بين موانئ البحر الأسود كان عليهم أن ينقلوا بضائِعَهم على سفُنٍ عثمانية تحمِلُ العلم العثماني. ولم يكن لروسيا طريقٌ إلى المياه الدافئة إلا عبر المضايق التي تسيطر الدولةُ العثمانية عليها، وظَلَّ حُلمُ السيطرة على هذه المضايق يراوِدُ روسيا زمنًا طويلًا. وقبل اشتعال الحرب العالمية الأولى ببضعة أشهر حاولت روسيا أن تحتلَّ البوسفور والدردنيل، ولم يكن أمامها سوى افتعالِ أزمة سياسيةٍ مع الدولة العثمانية، ثم تصعيدِها حتى تنقَلِبَ إلى حرب أوروبية تتَّخِذُها روسيا ذريعةً لإرسال قوَّاتِها المسلحة لاحتلال البوسفور والدردنيل في وقتٍ مبكر، ولوضع العثمانيين والأوربيين أمام الأمرِ الواقع، لكِنَّ هذا المخطَّط لم يُكتبْ له التنفيذ؛ لمعارضة بريطانيا له ورغبتِها آنذاك في حلِّ المشكلات الأوربية بالدبلوماسية لا بالحروب. ولَمَّا نشبت الحرب العالمية الأولى انضمَّت الدولة العثمانية إلى جانب ألمانيا والنمسا والمجر في مواجهة إنجلترا وفرنسا وروسيا وإيطاليا. وترتَّب على دخول الدولة العثمانية إلى جانب ألمانيا أن قامت بريطانيا وحلفاؤها بهجومٍ على الدردنيل والبوسفور. وكان موقِفُ روسيا في بدايات الحرب حرجًا للغاية بعد الهزائم المنكَرة التي أنزلتها بها القواتُ الألمانية، وأرادت بريطانيا أن تفتحَ الطريق أمام الأساطيل البريطانية والفرنسية إلى البحر الأسود، وكانت منطقةُ المضايق هي التي تفصل بريطانيا وفرنسا عن روسيا وتحولُ دون إمدادِها بالذخائر والأسلحة التي كانت روسيا في أشَدِّ الحاجة إليها بعد أن استنفدت احتياطيَّها من الذخائر، وانعدمت قدرةُ مصانِعِها على تلبية أكثر من ثُلثِ حاجتها من الذخائر. وكانت بريطانيا غيرَ راغبة في خروجِ روسيا من الحرب وتخشى ذلك، ولم يكن أمامها هي وحلفائها سوى بسط السيطرة العسكرية على منطقة المضايق؛ ضمانًا لإرسال الذخائر والأسلحة إلى روسيا وحثِّها على مواصلة الحرب. وفي الوقت نفسِه كان الاستيلاء على المضايق يشدُّ من أزر الروس ويرفَعُ من معنوياتهم التي انهارت أمام القوَّاتِ الألمانية. وفوق ذلك وعدت بريطانيا روسيا في حالة سيطرتها على منطقة المضايق بأنها ستهدي إليها مدينة استانبول؛ لحثِّها على الثبات والصمود، ولم تكن هناك هديةٌ أعظم من أن تكون المدينة التاريخية بين أنياب الروس. وفي (نوفمبر 1914م) اقترب الأسطول البريطاني من مياه الدردنيل، وهو يمنِّي نفسَه بانتصار حاسم وسريع، وقبل أن تتوغَّل بعضُ السفن البريطانية في مياه مضيق الدردنيل، ألقت بعضُ المدمِّرات قنابِلَها على الاستحكامات العسكرية العثمانية، ولم تتحرَّك هذه القوات للردِّ على هذا الهجوم ووقفت دون مقاومةٍ، الأمرُ الذي بثَّ الثقةَ في رجال الأسطول البريطاني، وأيقنوا بضَعفِ القواتِ العثمانية وعَجزِها عن التصدي لهم، وتهيَّؤوا لاستكمال حملتهم البحرية. وبعد مضي شهرين أو أكثر من هذه العملية توجَّهت قِطَعٌ عظيمة من الأسطول البريطاني إلى الدردنيل، وهي لا تشك لحظةً في سهولة مهمَّتِها، واستأنفت ضربَ الاستحكامات العسكرية الأمامية مرةً أخرى، ثم اقتحم الأسطولُ البريطاني المضيقَ لكنه اصطدم بحقلٍ خفيٍّ من الألغام في مياه الدردنيل، وأصيب الأسطول البريطاني بأضرارٍ بالغة بسبب ذلك، وكان لهذا الإخفاق دويٌّ هائل وصدًى واسع في جميع أنحاء العالم، ولم تحاوِلْ بريطانيا اقتحام الدردنيل بحريًّا مرةً ثانية. فعزَّزت بريطانيا الهجومَ البحري على الدردنيل بهجومٍ بري، على أن يكون دورُ القوات البرية هو الدورَ الأساسي، في حين يقتصر دورُ القوات البحرية على إمداد القوات البرية بما تحتاج إليه من أسلحةٍ وذخائرَ وموادَّ تموينية، ومساعدتها على النزول إلى البر، وحماية المواقع البرية التي تنزل بها. لكنَّ القوات العثمانية نجحت في صَدِّ المهاجمين، واسترداد ما تحت أيدي الإنجليز وتكبيدِهم خسائِرَ فادحة. وانتهت الحرب العالمية الأولى دون أن تنجَحَ القوات البريطانية والفرنسية أو غيرهما في اقتحام المضايق."},{"id":4863,"title":"انتصار العثمانيين على الإنجليز في معركة \"كوت العمارة\" في العراق .","date":["العام الهجري :1334","الشهر القمري : جمادى الآخرة","العام الميلادي :1916"],"text":"كان للإنجليزِ في العراق نفوذٌ واسعٌ لا سيما في مناطق حقول النفط هناك، وفي المناطق الجنوبية الشرقية من إيران؛ لذا فقد أنزلوا سنة 1914 قوةً من الجيش البريطاني الذي رابط في الهند، فاحتلت البصرة وتوجَّهت صوب بغداد لاحتلالها، ولكنها اصطدمت بالجيش التركي بقيادة الجنرال الألماني فون دير غلوتز، فأوقع بالجيشِ البريطاني خسائِرَ فادحة وكارثة عظيمة؛ إذ استسلم له عند \"كوت العمارة\" جيشٌ قوامه 13 ألف جندي وضابط بكامل معدَّاتهم، وبعد حصار دام خمسةَ أشهر."},{"id":4864,"title":"ثورة ضد الأتراك وإعلان الشريف حسين نفسه ملكا على الحجاز .","date":["العام الهجري :1334","الشهر القمري : شعبان","العام الميلادي :1916"],"text":"كانت مُراسلاتُ \"حسين - مكماهون\" التي دارت بين شَريف مكةَ الشَّريفِ حسين، ونائبِ الملِكِ البريطاني في القاهرة هنري مكماهون، تمثِّلُ مقدِّماتِ الثورةِ العربية، ومن أبرزِ أسبابِها، والتي وعدت فيها بريطانيا الشريفَ حسينًا بالمساعدة وتنصيبِه ملكًا على العربِ، وإقامةِ خلافةٍ عربيةٍ إسلاميةٍ، كما أنَّ هناك أسبابًا أخرى، منها: الضَّعفُ الذي دَبَّ في أطرافِ الدولةِ العثمانية التي كانت تحكمُ المناطِقَ العربيةَ في  الشامِ والحجازِ ومصر والمغرب، ومنها النعراتُ العُنصرية التي ظهرت على يدِ الاتحاديِّين القوميِّين بشكلٍ واضح، وانتشر الظلمُ في الدولةِ على نطاقٍ واسع؛ فسياسةُ الاتحاديِّينَ هي التي أيقظت الفكرةَ القوميَّةَ العثمانيةَ، بدأ بسوء الظنِّ بالعربِ، وأسهم في ذلك بعضُ الذين يريدون تخويفَ السلطانِ العثماني من العربِ، يُشيعُ أن العربَ يريدون أن يقيموا مملكةً عربية وحدهم، وكانت شكاوى العرب تنحصِرُ في إقصاء عدد كبير منهم عن وظائفهم بالأستانة، وعدمِ دعوة العربِ لأيِّ اجتماع للتأليف بين العناصِرِ العثمانية، ولا إدخالهم في الجمعياتِ الاتحادية ولا اللِّجان المركزية، ولا حتى تعيينهم على الولاياتِ والقضاءِ في البلاد العربية، ومعارضة الاتحاديين لكلِّ مشروعٍ علمي أو أدبي في البلاد العربية، ثم بدأت بعضُ الأحزاب العربية بالظهورِ كردَّةِ فِعلٍ للقومية العثمانية؛ فعُقِدَ في باريس أول مؤتمر عربي عام 1913م، ثم تفاقم أمرُ الاتحاديين وعَظُم تشدُّدهم إلى القومية التركية، وزاد الأمرُ عندما قام جمال باشا -الذي لقِّبَ بالسفاح- بقتل عددٍ مِن الذين كَشَف أنهم يتآمرون من خلال جمعياتٍ سرية على الاستقلال عن الدولة العثمانية، وكان القوميُّون العربُ قد رأوا أن يتجمَّعوا حولَ زعيم واحد ويشكِّلوا قوةً كبيرة عربية، فرأوا في الشريفِ حُسين بن علي -شريفِ مكة وأميرِها- الشخصَ المناسب لهذه الزعامة، فأجابهم، وكان التفاهمُ معه سرًّا بواسطةِ من تمكَّن مِن بعض أعضاء الجمعيات العربية الذين هربوا من جمال باشا ووصلوا للحجاز وغيرها، فتمَّ بين زعماء العرب وجمعيَّاتهم وبعضِ المقامات العالية، ومنهم الشريف حسين، أن قرَّروا إعلان الثورة في الحجاز، وكان الشريف حسين قد تعاقد مع مكماهون على أن يكون العرب حلفاءَ للإنجليز والفرنسيين خلال الحرب العالمية الأولى، وطبعا ضد الأتراك؛ لأنها كانت ضِدَّ الحلفاء، ووعدوا الشريف حسين أن يُبقوه مَلِكًا على العرب وأن يعطوا العربَ استقلالهم، وإن كان القوميون العربُ بعد اطِّلاعهم على مراسلات حسين مكماهون أغضبهم كثيرًا تنازل الشريف حسين عن بعض البلاد العربية للإنجليز أو للفرنسيين. أعلن الشريفُ حسين الثورةَ على الدولة العثمانية، وأطلق بنفسِه في ذلك اليوم أولَ رصاصةٍ على قلعةِ الأتراك في مكة؛ إيذانًا بإعلانِ الثورة، وعزَّز حركتَه بإذاعة منشورٍ اتَّهم فيه الاتحاديِّين في تركيا بالخروج على الشريعةِ الإسلامية، وجاء فيه: \"وانفصلت بلادُنا عن المملكةِ العثمانية انفصالًا تامًّا، وأعلنَّا استقلالًا لا تشوبُه شائبةُ مُداخَلة أجنبية ولا تحكُّم خارجي\"، واستطاعت القواتُ الثائرة أن تستوليَ في أقلَّ من ثلاثة أشهرٍ على جميعِ مدن الحجاز الكبرى، باستثناء المدينة النبوية التي بقيت محاصَرةً إلى نهاية الحرب العالمية الأولى، ولم يلبَثْ أن بويع الشريفُ حسين ملكًا على العرب. وقد نسفت القواتُ العربية بقيادةِ الأمير الشريف فيصل سكةَ حديد الحجاز، واحتلَّت ينبع والعَقَبة، واتخذوا من العَقَبة نُقطةَ ارتكازٍ لهم، ثم أخذ فيصل يتقدَّمُ لِيُحارِبَ الأتراكَ في منطقة شرقي الأردن، وبذلك قَدَّم للحُلفاء أكبرَ مساعدة؛ حيث استطاع اللورد اللنبي قائِدُ القوات الإنجليزية أن يدخُلَ القدسَ بمعاونة العرب، كما أنَّ احتلالَ القوات العربية لمنطقة شرقي معان قد حمى ميمنة القواتِ البريطانية في فلسطين من هَجَمات الأتراك عليها في منطقة بئر سبع والخليل، وحمى خطوطَ مواصلاتها، ولم تلبَث القواتُ العربيةُ أن تقدَّمت في (ذي الحجة 1336هـ/ سبتمبر 1918م) فاحتَلَّت دمشق واصطدمت بالأتراكِ قبل أن يدخُلَها اللنبي، ولم يمضِ أكثرُ من شهر حتى زال النفوذُ العثماني من سوريا بعد أن أمضى بها أربعة قرون. والواقع أن الكثيرين قد أُصيبوا بخيبةِ أمل كبيرة، وعلى رأسِهم الشيخ محمد رشيد رضا، وذلك عندما عَلِموا بتنازل حسين عن ولايتي إسكندرون ومرسين والمناطق الشمالية السورية، ووافق على مصالح فرنسا في ولاية بيروت لِما بعد الحرب، وعلى مصالح بريطانيا في البصرة وبغداد، وأنَّ الأسطول الإنجليزي هو الذي أسقط ثغورَ جدة ورابغ وينبع وغيرها من موانئ الحجاز، وأن ثغرَ بورسودان كان القاعدةَ التي انطلق منها الأسطول الإنجليزي لدعم ثورة الشريف حسين، وازداد شعورُهم بالخيبة عندما وجدوا ضباط إنجلترا وفرنسا مثل اللنبي وكوكس وكاترو وغورو والضابط الشهير لورانس هم الذين يقودون القبائِلَ العربية، ووصل الأمرُ ببعض هؤلاء الضبَّاط في النَّيلِ من المسلمين أنه لَمَّا دخل الجنرال اللنبي القدسَ يوم 9/12/1917م قال قولَته المشهورة: الآن انتهت الحروبُ الصَّليبية! ولَمَّا دخل الجنرال غورو دمشق يوم 21/7/1920م توجَّه إلى قبر صلاح الدين الأيوبي ووقف أمامَه قائلًا: ها قد عُدنا يا صلاحَ الدين! ثم تكرَّست المرارةُ والحسرة عندما ارتفعت أعلامُ بريطانيا وفرنسا على المناطق التي قاتَلَ فيها العرب، ولم يكن بينها عَلَمُ الدولة العربية المنتظَرة! وحاول الشيخ رشيد رضا أن يلفِتَ نظرَ الشريف حسين إلى خطورة ما أقدم عليه؛ لأن العدوَّ الحقيقيَّ هو الاستعمار الغربي لا الدولةُ العثمانية، إلا أنَّ بريقَ المصلحة وأحلامَ المُلك والعَرش كانا قد سيطرا على خيال الشريف حسين، فلم يستمِعْ إلى صوتِ ناصحٍ أو حكيمٍ! وإنما أمر بمنع دخول مجلة \"المنار\" التي يُصدِرُها الشيخ رشيد رضا من دخول مكة. ولم يعلم العربُ باتفاقِ (سايكس – بيكو) إلا عندما أعلنه البلاشفة بعد قيام ثورتهم في روسيا 1917م، وتأكَّد العربُ أنَّ الاتفاق أهمل تأسيسَ خلافة عربية، وأعطى بعضَ أجزاء من الدولة العربية المنتَظَرة لفرنسا، وأثار هذا الاتفاقُ حفيظةَ العرب، إلا أنَّهم مضوا في ثورتهم بعد طمأنةِ البريطانيين لهم، ونجح العثمانيُّون في تصوير الشريف حسين على أنَّه خائِنٌ للإسلام متحالِفٌ مع الدُّوَل النصرانية ضِدَّ دولة إسلامية، إلَّا أن الخلافاتِ الحقيقيةَ بين العرب والإنجليز تعمَّقت وظهرت مع إطلاقِ بريطانيا لوعدِ بلفور في (المحرم 1336هـ/نوفمبر 1917م) كانت غاية الإنجليز من ثورة العرب هو ضربَ الأتراك بالعرب، بدلًا أن يخوضوا هم غمار هذه الحرب، ويدلُّ على ذلك أن الإنجليز كانوا يضغطون على الشريف حسين لبدء الثورة عندما كانت جيوش الحلفاء تستسلم للأتراك عند كوت العمارة في نيسان 1916م، وكان الحلفاءُ غير قادرين على مواجهة القوات العثمانية عند قناة السويس واليمن، فكان التعجيل بالثورة ضِدَّ العثمانيين فيه تخفيف العبء عن الإنجليز، وفعلًا أدى إعلان الثورة إلى رجحان كفة الحلفاء، وبدأت الحاميات التركية في الاستسلام بعد أن حوصِرَت واستعمل معها رجال الجيش حربَ العصابات، ثم بدأ القتال فعلًا بين العرب وجيوش العثمانيين في الحجاز في التاسع من شعبان 10 يونيو، وأعلنوا استقلالهم، وهاجموا الثكناتِ التركيةَ في مكة، وحمِيَ القتال خلال يومين، حتى تعطَّلت الصلاةُ والطواف في المسجد الحرام، وكذلك الأمرُ في جدَّة؛ دام القتال ستة أيام حتى سقطت بيدِ قوات الشريف، وفي التاسع من رمضان استسلم الأتراك في مكة، وفي ذي القعدة سقطت الطائفُ، ثم أعلن الحجازُ استقلاله عن الاتحاديين، فانتهز الإنجليز والفرنسيون الفرصة وبدؤوا في إرسال التهاني، وحتى الدول الأوربية الأخرى كروسيا وسائر الدول غير المنحازة، أما السوريون واللبنانيون فلم ينَلْهم من الثورة إلا الحصارُ والاضطهاد؛ حيث كانت كفاءتُهم الحربية ضعيفة مقارنة مع كفاءات العثمانيين في هذه المنطقة، وكانت جيوش الثورة عبارة عن ثلاثة جيوش كل واحد بقيادة ولد من أولاد الحسين، وهم فيصل، وعبد الله، وعلي، وكان مع جيش فيصل لورنس وكان يتلقى أوامِرَه من الجنرال اللنبي، ثم تألَّفت أول وزارة عربية في السابع من ذي الحجة 1334هـ/ 5 أكتوبر 1916م، ثم أمر بتأليف مجلس الشيوخ الأعلى، هذا ولم تعين الحكومة العربية، ثم تمت مبايعةُ العربِ للشريف حسين بن علي ملكًا على العرب يوم الخميس السادس من محرم 1335هـ/ 6 تشرين الأول 1916م، علما أن استنكارًا إسلاميًّا قد ورد إلى الشريف حسين عن طريق شكيب أرسلان الذي قال له: أتقاتل العربَ بالعربِ أيها الأمير حتى تكون ثمرةُ دماء قاتِلِهم ومقتولِهم استيلاء إنجلترا على جزيرة العرب، وفرنسا على سوريا، واليهود على فلسطين، وهذا ما حصل بالفعل!!"},{"id":4865,"title":"حصار المدينة أثناء الحرب العالمية الأولى (سِفِر بِرلِك) (النفير العام) .","date":["العام الهجري :1334","الشهر القمري : شعبان","العام الميلادي :1916"],"text":"وقفت الدولةُ العثمانية في الحرب إلى جانب دول المحور، بينما أعلن الشريف حسين الثورةَ على الدولة العثمانية ووقف إلى جانب دول الحلفاء، وتمكنت قواتُ الشريف حسين مدعومةً من قوات الحلفاء -وخاصة بريطانيا- من السيطرة على معظم بلاد الحجاز عدا المدينة، فحوصرت حصارًا يعدُّ واحدًا من أطول الحصارات في التاريخ؛ حيث استمَرَّ الحصار لمدة سنتين وسبعة أشهر حتى بعد انتهاء الحرب العالمية الأولى، وكان والي المدينة هو فخري باشا أحد قادة الاتحاديين نائب جمال باشا قائد الفيلق الرابع في الشام، كان يتبَعُ فخري باشا جيشٌ مجهَّز بالأسلحة الخفيفة والمدفعيَّة التقليدية، وأثناء حصار المدينة هجر  معظم أهالي المدينة المنورة، فلحق بعضُهم بالبدو حول المدينة، أو بمدن حجازية كمكة وجدة وينبع، ومنهم من ارتحل إلى حائل، بينما لحِقَ بمصر والشام والعراق وتركيا والهند واليمن، ولعب قطار الحجاز دورًا كبيرًا في نقل المدنيين إلى بلدان آمنة، وبعد هزيمة الدولة العثمانية واستسلامها للحلفاء صدرت الأوامِرُ لفخري باشا من استانبول بتسليمِ المدينة فرفض الاستسلامَ، واستمَرَّ في المقاومة نحو خمسة أشهر إلا أنه اضطر بعدها للاستسلام بعد أن سلم قيادةَ المدينة إلى قائد الفوج العثماني في المدينة، والذي استسلم بدوره لقوات الثوار العرب، ثم خرج فخري باشا بقواته البالغ عددهم 8000 جندي إلى معسكر القوات المحاصرة خارج المدينة في بير درويش بالفريش، وسلَّم نفسه لهم فاستقبله الشريف عبد الله بن الحسين فأكرمه، ثم أرسله إلى مصر حيث اعتُقِلَ فيها، وبعد استسلام الحامية العثمانية في المدينة لقوات الأشراف عاد بعضُ من تم تهجيرُهم من أهل المدينة إلى المدينة، في حين أن بعضَهم فُقد أو مات في دار هجرتِه، أو فضَّل البقاء هناك، أو عجز عن العودة إلى المدينة، وفقد كثيرٌ من الأهالي أموالهم وبيوتهم."},{"id":4866,"title":"الخلاف بين الملك عبدالعزيز وآل الصباح .","date":["العام الهجري :1335","العام الميلادي :1916"],"text":"أثار نموُّ عبد العزيز بن سعود في نجدٍ قلقَ آل صباح؛ لذلك ساعد آل الصباح العجمانَ عندما تمرَّدوا على الملك عبدالعزيز واستقبلوهم لَمَّا هربوا منه، كما ظهرت أزمةٌ بين الملك عبدالعزيز والعوازم، وهم من أتباع آل الصباح في الكويت، لَمَّا فرض عليهم الملك عبدالعزيز الزكاةَ، وحرَّضَهم على هجر الكويت والاستقرار في نجدٍ؛ لذلك زار الكولونيل هاملتون الرياضَ لينقل إلى الملك عبدالعزيز احتجاجَ سالم الصباح على تجاوز أتباع الملك عبدالعزيز، فأظهر الملك عبدالعزيز غضَبَه من دعم آل الصباح للعجمان وإيوائِهم في الكويت وتعاونِهم مع خصومِه ابن رشيد في حائل، وأبدى رغبته في إعادة العوازم إلى الكويت إذا أعاد سالم الصباح العجمانَ إلى نجدٍ، وقَطَع علاقته مع ابن رشيد، فوافق ابن الصباح وأرسل يعتذِرُ للملك عبدالعزيز ويؤكِّدُ حِرصَه على استمرار الصداقة بين الأسرتين، فعاد العوازم إلى الكويت، وظلَّت مشكلة العجمان قائمةً، بل وحصلوا على دعمٍ وحماية من بريطانيا، ومع ذلك تمكن الملك عبدالعزيز من إخضاعِهم لسلطانِه."},{"id":4867,"title":"مؤتمر الكويت برئاسة برسي كوكس المعتمد البريطاني لدعم الثورة العربية .","date":["العام الهجري :1335","الشهر القمري : محرم","العام الميلادي :1916"],"text":"دعا برسي كوكس المعتمد البريطاني إلى مؤتمرٍ عربيٍّ إعلامي لشَدِّ أزْر الشريف حسين، وإثبات تأييد العربِ له، فعقد اجتماعًا موسَّعًا في الكويت دعا إليه الشيخ جابر بن مبارك، والملك عبدالعزيز، وخزعل الكعبي أمير عربسات، ومئة شيخ من شيوخ عشائر قبيلة مطير، والظفير، والعجمان، وغيرهم من شيوخ القبائل، وأعلن في المؤتمَرِ عن نية بريطانيا الحَسَنة تجاه العرب!، وأنها ترغَبُ في استعادة مجدِهم، وتوحيدِهم وجمعِ كَلِمتِهم، ليكونوا كتلةً واحدةً!! وأكَّد على ضرورة عودة الخلافة للعرب!"},{"id":4868,"title":"وفاة علي دينار سلطان دارفور .","date":["العام الهجري :1335","الشهر القمري : محرم","العام الميلادي :1916"],"text":"هو السلطانُ علي دينار ابن السلطان زكريا بن محمد فضل الكيراوي. ولِدَ في قرية \"شوية\" بدارفور سنة 1856م، وهو آخر سلاطين الفور من السلالة الكيراوية في سلطنة دارفور بالسودان. أعلن توحيدَ جهود المسلمين ضِدَّ الغزو الصليبي الأوروبي في أفريقيا، ويعَدُّ السلطان علي دينار من أشهرِ السلاطين الذين حكَموا إقليم دارفور ووقفوا مع الثورة المهدية في دحر المستعمِر، كما قام السلطانُ بنشر الدعوة المهديَّة في عهد الخليفة عبد الله التعايشي خليفة مهدي السودان. أقام علي دينار في مدينة الفاشر عاصمة دارفور، وأقام مصنعًا لصناعة كسوة الكعبة، وظَلَّ طوال عشرين عامًا تقريبًا يرسِلُ كسوة الكعبة إلى مكة المكرمة، وينسب إليه حفرُ أبيار علي -ميقاتِ أهل المدينة للإحرام بالحج والعمرة- وتجديد مسجد ذي الحُليفة. اغتاله الإنجليز."},{"id":4869,"title":"زيارة الملك عبد العزيز للبصرة .","date":["العام الهجري :1335","الشهر القمري : صفر","العام الميلادي :1916"],"text":"بعد اختتام مؤتمر الكويت أعمالَه زار الملك عبد العزيز البصرةَ بدعوة من برسي كوكس، وقد حَظِيَ الملك باستقبالٍ حافل من جانب سلطاتِ الاحتلال البريطاني في البصرةِ؛ إذ أقيم أمامَه استعراضٌ عسكري اشتركت فيه صنوفُ الأسلحة العسكرية، ثم قام بجولةٍ على متن القطارات والعربات، ثم اطَّلَع على المستشفيات الحديثة والقطاعات العسكرية، وسعى كوكس لعقد اجتماعٍ بين الملك عبد العزيز وفهد الهذال شيخ عنزة؛ بغرضِ منع الأخير من السماحِ بتهريب الأسلحة عن طريق العراق لتركيا، وتمَّ له ذلك."},{"id":4870,"title":"استيلاء الجيش الإنجليزي على مدينة غزة .","date":["العام الهجري :1335","الشهر القمري : صفر","العام الميلادي :1916"],"text":"استولى الجيشُ الإنجليزي على مدينة غزَّة الفلسطينية وانتزعها من العثمانيين، بعدما قاموا بمدِّ خَطِّ سكة حديد وخَطِّ أنابيب مياه في سيناء؛ للتغلب على صعوبة الطقس ووعورة التضاريس، وذلك بعد أن خَسِروا معركتين في غزةَ أمام العثمانيين."},{"id":4871,"title":"بعثة وفد إنكليزي للرياض برئاسة الكولونيل هاملتون  .","date":["العام الهجري :1335","الشهر القمري : صفر","العام الميلادي :1916"],"text":"أوفد برسي كوكس المعتمد البريطاني وفدا مكونا من الكولونيل هاملتون رئيسا للوفد وبرفقته جون فيلبي سكرتير كوكس والكولونيل أوين الوكيل السياسي في الكويت بغرض استنهاض الملك عبدالعزيز لحرب ابن رشيد في حائل والتوفيق بينه وبين الشريف حسين، وقد قضى هاملتون 21 يوما ثم غادر الرياض وترك فلبي يحل محله لإكمال التفاوض مع الملك عبدالعزيز، رفض الملك عبدالعزيز إعلان الحرب صراحة على تركيا لكنه طمأن الوفد عن استعداده لحرب خصمه ابن رشيد إذا تعهدت بريطانيا بتقديم التأييد له. فكتب فلبي لرؤسائه في بغداد يؤكد ضرورة تحقيق ذلك ليتمكن من التصدي لمخططات الأتراك في المنطقة من خلال قوة ابن رشيد. ثم تغيرت سياسة بريطانيا في شن حملة ضد ابن رشيد بعد تدهور الموقف العثماني في الجبهة الشرقية مع توقع انهيار الدولة العثمانية."},{"id":4872,"title":"القوات البريطانية تحتل بغداد .","date":["العام الهجري :1335","الشهر القمري : جمادى الأولى","العام الميلادي :1917"],"text":"ما كادت الحربُ العالمية تُعلَن حتى أنزلت الجيوش البريطانية قواتِها في المحمرة -مدينة عربية في خوزستان جنوب غرب إيران- بحجة حماية امتيازات البترول في إيران، ثم نزلت في البصرة ومشت بسرعة إلى القرنة، ثم العمارة، وحسبت أن الطريق إلى بغداد بات مفتوحًا، ولكِنَّ الهجوم المعاكس الألماني التركي هزم الإنجليزَ في البداية في الكوت بعد حصار ستة أشهر، فاستنجدوا بنجداتٍ أتت من الهند ليواصِلوا الزحف إلى بغداد ودخلوها باستقبالِ اليهود والنصارى لهم بالترحيبِ والفرَحِ واضعين أنفُسَهم تحت تصرُّفِهم، وانسحب الأتراك من شمال العراق، ولم يكن احتلالُ الإنجليز للعراق إلا جزءًا من اتفاقية سايكس بيكو، مع أن الجنرال مود أعلن أنه جاء لتحرير العرب، وكان نبأُ الثورة العربية قد هدأ من نفوس العراقيين. وبقيت الحرب سجالًا بين الطرفين حتى توقيع هدنة رودس؛ لوقف الحرب عام 1337هـ / 1918م."},{"id":4873,"title":"نشوء جمهورية شمال القوقاز الجبلية الفيدرالية .","date":["العام الهجري :1335","الشهر القمري : رجب","العام الميلادي :1917"],"text":"نشأت جمهوريةُ شمال القوقاز الجبلية الفيدرالية، وتتكوَّنُ مِن داغستان، والشيشان، وأنغوشيا، وأوسيتيا، وألانيا، وقبردينو، وأبخازيا، وبلقاريا، وأديغيا، وكانت عاصمتُها باطوم (جورجيا) واختير عبد المجيد تشيرموف أولَ رئيس لها، واعترف بهذه الدولة عددٌ من الدول الأوربية، والدولةُ العثمانية أيضًا."},{"id":4874,"title":"مؤتمر موسكو للتوفيق بين الإسلام والاشتراكية .","date":["العام الهجري :1335","الشهر القمري : رجب","العام الميلادي :1917"],"text":"اتحد الزُّعماءُ المسلمون الذين يؤيدون الاشتراكيين الثوريين والديمقراطيين الدستوريين، وشكَّلوا لجنة إسلامية نشأت عنها الجبهةُ الوطنية التتارية، ونظمت لجان العمال التي انضمَّ بعضُها إلى بعض تحت اسمِ اللجان الاشتراكية الإسلامية، فلم تلبث أن أصبحت تسيرُ في خطِّ البلاشفة، وأصدرت صحيفة \"قيزل بيرق\" (العلم الأحمر)، ورغم بُعدِها عن الشيوعية وكرههم للاشتراكيين ومبادئهم الإلحادية، إلا أنهم اتفقوا معهم على إنهاء الحرب وتقسيم الأرض وتحويل السلطة إلى السوفيت (مجلس العمال).عقد الأعضاء المسلمون في المجلس النيابي (الدوما) الرابع مؤتمرًا في بيتروغراد، ودعوا أناسًا من غير النواب، وقرروا إنشاء مكتب مؤقت للمسلمين في الإمبراطورية الروسية، وتولى أحمد تساليكوف القفقاسي المنشفيكي إدارته، وقرَّروا عدم التعاون مع الأحزاب الروسية، وفي طليعتها الحزب الديمقراطي الدستوري؛ لخيانته المسلمين، وبجهودِ هذا المؤتمر عُقِدَ مؤتمرُ موسكو في الثامن من رجب من هذا العام، وعمل على التوفيق بين الإسلام والاشتراكية، ولم يقاطع المؤتمرَ من المسلمين سوى بعض البلاشفة، وطالب المؤتمرُ الحكومةَ المؤقتة بالمساواة في الحقوق المدنية مع الروس، والاستقلالَ بالأمور الدينية، وأن يكون المفتي منتخَبًا من قِبَل المسلمين وليس مُعَيَّنًا من قِبَل الحكومة، وإنهاء الاستعمار الريفي، وحصْر الأراضي بالسكَّان الأصليين، وكان أيضًا من جملة المطالبات إلغاءُ الملكية الشخصية، ومساواة الرجل بالمرأة، ومنع تعدد الزوجات، وإنشاء مديرية للشؤون الإسلامية في أوفا عاصمة الكيان الفدرالي الروسي، والمحافظة على الوحدة الإسلامية. يقول محمود شاكر: \"كان المسلمون في آخرِ أيام روسيا القيصرية على درجةٍ من السذاجة والغباء لا تُوصَفُ؛ فقد استُغِلُّوا بأبسط الشعارات، وخُدِعوا بأقَلِّ الكلمات، ومع تمسُّكِهم بدينهم وكُرهِهم للروس، فقد انجرفوا معهم وساروا مع هذه المجموعة من الأحرار، ومع تلك من الاشتراكيين، ومع أخرى من البيض، ومع رابعة من الثوريين، ومع البرجوازيين!!\"."},{"id":4875,"title":"استقلال ألبانيا ودخولها تحت الحماية الإيطالية .","date":["العام الهجري :1335","الشهر القمري : شعبان","العام الميلادي :1917"],"text":"استقلت دولة ألبانيا وأصبحت تحت الحماية الإيطالية، وذلك إبَّان الحرب العالمية الأولى. وألبانيا هي إحدى دول البلقان التي كانت خاضعةً للحكم العثماني، وتحوَّلت من النظام الرئاسي بعد استقلالها إلى النظام الملكي عام 1928م تحت حكم \"أحمد زوغو\"، ثم حكَمَها الشيوعيون بقيادة \"أنور خوجا\" أربعين عامًا من الحكم المطلق حتى وفاته عام 1985م."},{"id":4876,"title":"وفاة السلطان حسين كامل سلطان مصر .","date":["العام الهجري :1335","الشهر القمري : ذي الحجة","العام الميلادي :1917"],"text":"هو السلطانُ حسين كامل سلطان ابن الخديوي إسماعيل، حَكَمَ مصر تحت الاحتلال البريطاني، ولِدَ في القاهرة، ولما بلغ الثامنة التحق بمدرسة قصر النيل التي أنشأها والده ليتعلَّم فيها، بخاصة أولاده وأولاد الأعيان. ولي حسين كامل سلسلةً من المناصب الإدارية. وأقام في طنطا فترةً بوصفه مفتشًا للدلتا، وأشرف على النهوض بقنوات الري في هذه المنطقة. وكذلك خدم مراتٍ عدةً في وزارات المعارف والأوقاف والأشغال العمومية، والداخلية والمالية. وعمل في مجالس إدارة كثيرٍ مِن الشركات الأجنبية، مثل سكة حديد الدلتا. على أنَّ خير ما أسداه من فضلٍ هو نهوضه بالزراعة في مصر، وأنشأ في دمنهور مدرسةً تجارية صناعية، ورأس مدة قصيرة مجلس شورى القوانين والمجلس التشريعي، ولكنه استقال من المجلسين سنة 1909 إثرَ الأزمة التي نشأت حول تمديدِ امتياز قناة السويس. ولما أعلنت تركيا الحربَ على بريطانيا سنة 1914. وشكَّت بريطانيا في أن الخديوي عباس حلمي الثاني يتعاطفُ مع تركيا فضلًا على تأييده للوطنيين في مصر، فعزلته وأقامت الأميرَ حسين كامل حاكمًا على مصر، وأطلقت عليه لقب سلطان؛ نكاية بالسلطان العثماني، وكان قبولُ حسين كامل للسلطنة قد قوبِلَ بمعارضة العناصر الوطنية؛ إذ رأوا أنَّ قبولَه لها في ظِلِّ الاحتلال البريطاني والحكومة العسكرية مَهانةٌ قومية. بل إن كثيرًا من هذه العناصر رأت أنها خيانةٌ عظمى ارتكبها في حَقِّ الدولة العثمانية المُسلِمة في حربها مع بريطانيا. بل نظر بعضُ الوطنيين إلى السلطان وحكومةِ الحرب التي يرأسُها حسين رشدي باشا إلى أنها أدواتٌ في يد سلطات الاحتلال البريطاني، فاستفحلت الوحشةُ بين الجمهور وبين الحكومة والسلطان؛ ولذلك ما إن تربَّع السلطان حسين على دست الحكمِ حتى باشر واجباتِه فمضى يمحو البقيةَ الباقية من آثار السلطان التركي على مصر ومظاهره الإدارية والقضائية، وعلى الرغم من كل هذا إلا أن علاقة السلطان حسين كامل بالسلطات البريطانية في مصر لم تكن في جميع ِالأحوال علاقاتٍ وديةً أو وثيقة؛ فقد كانت بريطانيا في مصر تنظر بعين السخط إلى أنه يعمَلُ على تقوية الروابط بينه وبين الحركة الوطنية؛ ومن ثم فإن البريطانيين كانوا لا يقرُّون محاولات السلطان بالظهور في صورة الزعيم الشعبي، في حين أن الشعب المصري كان ينكِرُ منه أنه أداةٌ في يد البريطانيين. بدأت صِحَّةُ السلطان حسين تضمحِلُّ إلى أن توفي في هذا العام، وكان ابنه الأمير كمال الدين حسين قد أعلن من قَبلُ نزوله عن حقه في وراثة عرش مصر، فخَلَف السلطانَ حسين أخوه الأميرُ فؤاد الذي أصبح ملكًا بعد ذلك."},{"id":4877,"title":"قيام الاتحاد السوفيتي .","date":["العام الهجري :1335","الشهر القمري : ذي الحجة","العام الميلادي :1917"],"text":"نشأ الاتحادُ السوفيتي بعد ثورة أكتوبر في العام 1917م بقيادة لينين الذي أزاح منافِسيه ووصل إلى الحُكمِ على يد البلاشفة اليساريين الاشتراكيين الذين تسَمَّوا باسم الحزب الشيوعي فيما بعد. ومن الأسباب الرئيسة في قيامِ الاتحاد السوفيتي: ضَعفُ النظام القيصري في روسيا، وتردِّي الأوضاع الاقتصادية، وبسبب دخول روسيا في الحرب العالمية الأولى ضد ألمانيا، وكانت قد نشطت في روسيا العديدُ من الأحزاب اليسارية المبشِّرة بالنظام الاشتراكي الذي كان بمثابة الأمل الوحيد للتخلُّص من الإقطاعيين والرأسماليين المدعومين من قِبَل الحكومة القيصرية. وبعد عدةِ نزاعاتٍ وملاحقات وتحالفاتٍ استطاع الشيوعيون بالتعاونِ مع قوًى برجوازية -وهي الطبقة الوسطى في المجتمع- وأنواعٍ أخرى من الأحزاب الشيوعية إزاحةَ النظام القيصري، لحقت بعد ذلك فترة من الحرب الأهلية والانقسامات داخِلَ الفكر الشيوعي؛ ليقودَ الحزب الشيوعي البلشفي بقيادة فلاديمير لينين روسيا نحو حقبة سوفيتية طويلة الأمد. ولفظُ سوفييت مأخوذٌ من الكلمة الروسية التي تعني لجنة، وكان النظامُ يتكوَّن من لجان ذات عدد محدود تغطِّي جميع المناطق في الاتحاد، ثم تترتب اللجانُ بشكلٍ هرمي وصولًا للَّجنةِ المركزية للحزب الشيوعي، ويرأس الاتحادَ السوفيتي السكرتيرُ العام للحزب الشيوعي. وجمهورياته: أرمينيا، أذربيجان، روسيا البيضاء، أستونيا، جورجيا، قزخستان، قرغيزستان، لاتفيا، لتوانيا، مولدافيا، روسيا، طاجيكستان، تركمانستان، أوكرانيا، أوزبكستان، وفي هذه الجمهوريات نسبة كبيرة جدا من المسلمين."},{"id":4878,"title":"أوضاع المسلمين في روسيا بعد الثورة البلشفية .","date":["العام الهجري :1336","العام الميلادي :1917"],"text":"قامت الثورة البلشفية في روسيا عام 1335هـ / 1917م، حيث تظاهر العمَّالُ نتيجة المفاسد وانهيار الأوضاع الاقتصادية وكثرة البطالة، فتشكَّلت حكومةٌ مؤقتة اشترك فيها الاشتراكيون والحزب الديمقراطي الدستوري، كان من نتيجتها تنازُلُ القيصر نقولا الثاني عن العرش لأخيه الأكبر ميخائيل، الذي سرعان ما تنازل هو أيضًا، وخوَّل الحكومةَ المؤقَّتة تسييرَ شؤون البلاد، ولم يجِدِ المسلمون لهم ناصرًا بين الروس، وقد حضروا المؤتمرات وأسَّسوا الجمعيات، لكن دون جدوى، ثم عاد لينين إلى روسيا في جمادى الأولى من العام نفسه / آذار 1917م بعد أن كان في سويسرا، وأخذ ينادي بمبدأ تقرير المصير للأقليَّات؛ ممَّا حدا ببعض المسلمين الانضمام لهذه الثورة البلشفية، بدافِعِ كرههم للروس وما فعلوه بهم، واتحد الزعماءُ المسلِمون المؤيِّدون وقرروا في مؤتمر موسكو التوفيقَ بين الإسلام والاشتراكية!، ثم أعطى لينين عام 1336هـ / 1917م أوامِرَه بصراحة لجماعته البلاشفة، فتسلَّموا السلطة دون مقاومة، ودعمها الطلاب الضبَّاط في الكلية الحربية ثم تشكَّلت الحكومة الجديدة برئاسة لينين، وهرب رئيس الحكومة المؤقتة، ثم تمَّ تأميمُ الأراضي وطلب الصلح فورًا مع الألمان، وتمَّ إلغاء المِلْكية الشخصية، ووقف المسلمون بجانب البلاشفة، أما تركستان فقد أعلنت استقلالَها بعد الانقلاب البلشفي حيث أعلن مجلِسُ الشعب الإسلامي في مدينة خوقند استقلالَ تركستان الذاتي، فسار إليها سوفييت طاشقند فاقتحموا المدينةَ ونهبوها وحرَّقوها وقَتَلوا أكثَرَ من مئة ألف من سكانها، وأما شمال القفقاس أو القوقاز فأعلن اتحادُ الجبلين أن بلادَ القفقاس جزءٌ من روسيا البيضاء، أما الداغستان والشيشان فأعلنوا قيامَ حكومة مستقلة، وأما أذربيجان فتأخَّر صدامُهم مع البلاشفة لِبُعدِ الشُّقَّة، ولكن بعد أن وقع جرت المذابِحُ التي ذهب ضحيَّتها ثلاثة آلاف مسلم، وهكذا لم يبق للمسلمين نفوذٌ ولا سلطةٌ إلا في أربعة مراكز، هي: داغستان، وشيشان، وحكومة غاندكا في أذربيجان، وإمارة بخارى، وإمارة خوارزم."},{"id":4879,"title":"قيام المملكة اليوغسلافية  .","date":["العام الهجري :1336","العام الميلادي :1917"],"text":"بعد انتهاء الحرب العالمية الأولى وتقسيم الإمبراطورية، اتحدت عام 1918م كلٌّ مِن صربيا، كرواتيا، وسلوفينيا، تحت قيادة ملك الصرب بطرس الأول، وباسم مملكة صربيا وكرواتيا وسلوفينيا، وهي مملكة أوروبية امتدَّت من غرب البلقان حتى وسط أوروبا. اتبع خليفة بطرس الأول الملك الكسندر الأول حكمًا عسكريًّا منذ عام 1929م إلى حين اغتياله عام 1934م. أُعيد تسمية البلاد إلى مملكة يوغوسلافيا. ثم ناصَرَ الملكُ بطرس الثاني عام 1941م دولَ المحور في الحرب العالمية الثانية؛ مما أدى إلى إسقاطه في الحال على يد الجيش. انتهز هتلر هذه الفرصة وأمر القواتِ الألمانيةَ والإيطالية باحتلال البلاد. أصبح عام 1943م جوزيف بروز الملقب بتيتو زعيمَ المقاومة اليوغوسلافية، التي تمكَّنت مع القوات السوفيتية من تحرير البلاد عام 1945م. أُعلِنَ في نفس السنة قيامُ اتحاد الجمهوريات اليوغوسلافية الشعبية وتيتو رئيسًا لها. كان هذا الاتحادُ يضُمٌّ كلًّا من صربيا، كرواتيا، سلوفاكيا، البوسنة والهرسك، والجبل الأسود، ومقدونيا. بقي رئيسًا للاتحاد حتى مماته عام 1980م، الذي كان بداية النهاية للاتحاد اليوغوسلافي. كانت يوغوسلافيا في الفترة 1945 - 1948م تتبع الاتحاد السوفيتي، إلى حين ظهور خلافات على السطح وإعلان يوغوسلافيا اتباع سياسة محايدة إيجابية دوليًّا. لعبت بعد ذلك تحت قيادة تيتو دورًا مهمًّا في السياسة الدولية وتشكيل منظَّمة عدمِ الانحياز."},{"id":4880,"title":"وعد بلفور وخيانة بريطانيا للعرب .","date":["العام الهجري :1336","الشهر القمري : محرم","العام الميلادي :1917"],"text":"وعدُ بلفور أو تصريحُ بلفور، هو وعدٌ لليهود يمنَحُهم حقَّ إقامة وطني قومي في فلسطين، وهو وعدٌ مشؤوم بالنسبة للمسلمين يناقِضُ ما أبرمه الإنجليزُ مع الشريف حسين في مراسلات \"حسين، مكماهون\" والوعودَ بإقامة خلافةٍ عربية إسلامية في البلاد العربية مقابِلَ إعلان العرب الثورةَ على الدولة العثمانية!! ولقد أثار اشتراكُ الإمبراطورية العثمانية في الحربِ ضِدَّ الحلفاء الأطماعَ الصهيونية، وكان على رأس زعمائهم في إنجلترا حاييم وايزمان الذي كتب إلى زعماء الصهيونية في أمريكا طالبًا دعم الرئيس الأمريكي وودرو ويلسون الذي وصل للرئاسة بفضلِ تمويل اليهودِ فهو تابعٌ لهم، وأما في بريطانيا فكان اليهودُ قد أطاحوا بحكومةِ رئيس الوزراء هربرت هنري سكويت المعروفِ بعدائه لليهود، وموَّلوا حكومةً ائتلافية فيها ديفيد لويد جورج المحامي عن الحركة الصهيونية ووينستون تشرشل الماسوني والمؤازر للصهيونية، ثم أعلنت بريطانيا إرسالَ وزير خارجيتها بلفور إلى الولايات المتحدة للاتصالِ بممثلي المصارف الأمريكية (غالبهم إن لم يكن كلهم من اليهود) وإبلاغهم رسميًّا بأنَّ الحكومة البريطانية ستتبنى رسميًّا مشاريعهم المتعلِّقة بالصهيونية مقابِلَ تعهُّدهم بإدخال أمريكا إلى جانب الحلفاء في الحرب العالمية، ثم دخلت أمريكا الحربَ، وكانت أول كتائبها وصلت إلى فرنسا في حزيران 1917م وتكفَّلت بريطانيا بإعادة تأسيس فلسطين كوطنٍ قومي لليهود، وكأن أرض فلسطين ملكُ آبائهم! وكان وعد بلفور صدر في الثاني من نوفمبر (تشرين الثاني) وهو عبارةٌ عن خطاب من آرثر جيمس بلفور وزيرِ خارجية بريطانيا إلى المصرفيِّ اليهودي اللورد ليونيل وولتر دي روتشلد، وجاء فيه: \"أن حكومة جلالة الملك تنظرُ بعين العطفِ إلى تأسيس وطنٍ قوميٍّ للشعب اليهودي في فلسطين، وستبذل جهدَها لتسهيل تحقيق هذه الغاية، على أن يفهم جليًّا أنه لن يؤتى بعمَلٍ من شأنه أن يجحَفَ بالحقوق المدنية والدينية التي تتمتَّعُ بها الطوائف غير اليهودية الآن في فلسطين، ولا الحقوق أو الوضع السياسي الذي يتمتَّعُ به اليهود في البلدان الأخرى\" وقد تمسَّكت الحكومات البريطانية المتعاقبة بهذا التصريح الذي أصبح عن طريق الانتداب إلزامًا دوليًّا، وكان من غايات بريطانيا لهذا هو حماية مصالحها في السويس، فكان هذا أولَ الغدر الظاهِرِ، وليس أوَّله بالكلية، وأبدى العربُ والقوميون الذين كانوا مخدوعين بالوعود الإنجليزية استياءَهم، ولكن لاتَ حينَ مناصٍ!!!"},{"id":4881,"title":"موقف الإنجليز من حركة إخوان نجد  (إخوان من أطاع الله) .","date":["العام الهجري :1336","الشهر القمري : ربيع الأول","العام الميلادي :1918"],"text":"تأسَّست حركة الإخوان -وكان مقرها الرئيسي الأرطاوية- على يد الملك عبدالعزيز لخوض المعارك ضد خصومه، وكانوا تستعِرُ داخِلَهم جذوةُ الدين وأصبحوا لا يُقهَرون، وكان شعارهم في الحرب: (هَبَّت هبوبُ الجنة، أين أنت يا باغيها؟ وكلٌّ يبغيها)؛ لذلك فكانوا يحاربون، وقلَّما ينهزمون، يرون أنَّ الجنَّةَ أمامهم والنارَ خلفهم، فلا يتقهقرون ولا يولون الدبر، فانتشر خبرهم وذاع صيتهم حتى بلغ الدوائر الإنجليزية والشريف حسين الذي هابهم وأبلغ الانجليز عن قلقه منهم وتحريضه لهم للقضاء عليهم والضغط على الملك عبدالعزيز للإلغائهم والتخلص منهم.تمكن الكولونيل هاملتون خلال رحلة له في الرياض أن يقضيَ يوما في الأرطاوية في أكتوبر 1917 أحدِ أهمِّ مراكز الإخوان، ليتعرف عليهم عن كثب فقدَّر عدد سكان الأرطاوية ب 35 ألف نسمة، وأرسل تقريره إلى جُدة ثم القاهرة فانتشر وأثار لديهم فزعًا ليس بقليل."},{"id":4882,"title":"وفاة السلطان عبد الحميد الثاني آخر سلاطين الدولة العثمانية .","date":["العام الهجري :1336","الشهر القمري : ربيع الآخر","العام الميلادي :1918"],"text":"هو السلطانُ عبد الحميد الثاني بن عبد المجيد الثاني، السلطان الرابع والثلاثون من سلاطين الدولة العثمانية، وآخِرُ من امتلك سلطةً فعليةً منهم. ولد في 16 شعبان 1258هـ الموافق 21 سبتمبر 1842م، وتولَّى الحكم عام 1293هـ 1876م. أبعِدَ عن العرش عام 1327هـ / 1909م بتهمة الرجعية، وأقام تحت الإقامة الجبرية حتى وفاته في 15 جمادى الأولى 1337هـ الموافق 10 فبراير 1918م. تلقى السلطان عبد الحميد بن عبد المجيد تعليمَه بالقصر السلطاني، وأتقن من اللغات: الفارسية والعربية، وكذلك درس التاريخ والأدب. يعرِّفُه البعض، \"باولو خاقان\" أي \"الملك العظيم\" وعُرِفَ في الغرب باسم \"السلطان الأحمر\"، أو \"القاتل الكبير\" بسبب مذابح الأرمن المزعوم وقوعُها في فترة تولِّيه منصِبَه. رحَّب جزء من الشعب العثماني بالعودة إلى الحكم الدستوري بعد إبعاد السلطان عبد الحميد عن العرش في أعقاب ثورة الشباب التركي \"الاتحاديين\". غيرَ أن الكثير من المسلمين ما زالوا يقدِّرون قيمة هذا السلطان الذي خَسِرَ عرشه في سبيل أرض فلسطين التي رفض بيعَها لزعماء الحركة الصهيونية. تولى السلطانُ عبد الحميد الثاني الخلافة في 11 شعبان 1293هـ، الموافق 31 آب (أغسطس) 1876م، وتبوَّأ عرشَ السلطنة يومئذٍ على أسوأ حال؛ حيث كانت الدولة في منتهى السوء والاضطراب، سواء الأوضاع الداخلية أو الخارجية. دبَّرت جمعية \"الاتحاد والترقي\" عام 1908م انقلابًا على السلطان عبد الحميد تحت شعارات الماسونيةِ \"حرية، عدالة، مساواة\". كان اليهودُ لَمَّا عُقِدَ مؤتمرُهم الصهيوني الأول في (بازل) بسويسرا عام 1315هـ، 1897م، برئاسة ثيودور هرتزل 1860م-1904م رئيس الجمعية الصهيونية، اتَّفقوا على تأسيس وطنٍ قوميٍّ لهم يكون مقرًّا لأبناء عقيدتهم، وأصَرَّ هرتزل على أن تكون فلسطينُ هي الوطنَ القوميَّ لهم، فنشأت فكرةُ الصهيونية، وقد اتَّصل هرتزل بالسلطان عبد الحميد مرارًا ليسمح لليهودِ بالانتقال إلى فلسطين، ولكِنَّ السلطان كان يرفض، ثم قام هرتزل بتوسيطِ كثير من أصدقائه الأجانب الذين كانت لهم صلةٌ بالسلطان أو ببعض أصحابِ النفوذ في الدولة، كما قام بتوسيطِ بعض الزعماء العثمانيين، لكنه لم يُفلح، وأخيرًا زار السلطانَ عبد الحميد بصحبة الحاخام (موسى ليفي) و(عمانيول قره صو)، رئيس الجالية اليهودية في سلانيك، وبعد مقَدِّمات مُفعَمة بالرياء والخداع، أفصحوا عن مطالبهم، وقدَّموا له الإغراءاتِ المتمثلة في إقراض الخزينة العثمانية أموالًا طائلةً مع تقديم هدية خاصة للسلطان مقدارها خمسة ملايين ليرة ذهبية، وتحالُف سياسي يُوقفون بموجِبِه حملات الدعاية السيئة التي ذاعت ضِدَّه في صحف أوروبا وأمريكا. لكِنَّ السلطان رفض بشدةٍ وطردهم من مجلسِه، وقال: \" إنكم لو دفعتم ملءَ الدنيا ذهبًا، فلن أقبل؛ إنَّ أرضَ فلسطين ليست ملكي، إنما هي ملك الأمة الإسلامية، وما حصل عليه المسلِمون بدمائهم لا يمكن أن يباعَ، وربما إذا تفَتَّت إمبراطوريتي يومًا يمكِنُكم أن تحصلوا على فلسطين دون مقابل\"، ثم أصدر أمرًا بمنعِ هجرة اليهود إلى فلسطين. عندئذ أدرك خصومُه الصهاينة أنهم أمام رجلٍ قوي وعنيد، وأنَّه ليس من السهولة بمكانٍ استمالتُه إلى صفِّها، ولا إغراؤه بالمال، وأنه ما دام على عرش الخلافة فإنَّه لا يمكِنُ للصهيونية العالمية أن تحقِّقَ أطماعها في فلسطين، ولن يمكِنَ للدول الأوروبية أن تحقِّقَ أطماعها أيضًا في تقسيمِ الدولة العثمانية والسيطرة على أملاكها، وإقامة دويلات لليهود والأرمن واليونان؛ لذا قرَّروا الإطاحةَ به وإبعاده عن الحكم، فاستعانوا بالقوى المختلفة التي نذرت نفسَها لتمزيق ديار الإسلام؛ أهمها الماسونية، والدونمة، والجمعيات السرية (الاتحاد والترقي)، وحركة القومية العربية، والدعوة للقومية التركية (الطورانية)، ولَعِبَ يهود الدونمة دورًا رئيسًا في إشعال نار الفتن ضد السلطان إلى أن تمَّ عزلُه وخَلعُه من منصبه عام 1909، وتم تنصيب شقيقِه محمد رشاد خلفًا له. وتوفِّيَ السلطان عبد الحميد الثاني في المنفى في 15 جمادى الأولى 1337هـ 10 فبراير 1919م."},{"id":4883,"title":"مؤتمر سان ريمو أو سان جان دي موريين في إيطاليا  .","date":["العام الهجري :1336","الشهر القمري : شعبان","العام الميلادي :1918"],"text":"عقد المجلسُ الأعلى للحلفاء اجتماعًا في سان ريمو في إيطاليا في نيسان 1920م وغايتُه وضع اتفاقية خاصة بتركيا غايتُها تصفية الخلافات الفرنسية الإيطالية؛ لهذا قرَّرت منح فرنسا منطقةَ أضنة على أن تضعَ إيطاليا يدَها على ما تبقَّى من أراضي جنوبي الأناضول، بما في ذلك أزمير، وولاية قونيا، ومتصرفيات أضاليا، وبقية أراضي الأناضول غربًا."},{"id":4884,"title":"وفاة السلطان العثماني محمد رشاد وتولي محمد السادس وحيد الدين .","date":["العام الهجري :1336","الشهر القمري : رمضان","العام الميلادي :1918"],"text":"هو السلطانُ محمد الخامس رشاد بن عبد المجيد الأول بن محمود الثاني عبد الحميد الأول بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني. ولِدَ سنة 1844 باستانبول، وهو السلطان الخامس والثلاثون للدولة العثمانية، تولى الحكمَ بعد خلع أخيه عبد الحميد الثاني 1909م، وكان عمره 65 عامًا. أعيد تفعيلُ الدستور بعد تنصيبِه، وسيطر الاتحاديون على جميعِ مقاليد الحكمِ، ولم يبق للخليفة من الحكمِ إلا اسمُه، وأعلن السلطان محمد رشاد الجهادَ الإسلاميَّ على الحُلَفاء رغمًا عنه بأمر من الاتحاديين، وهُزِمت الدولة العثمانية في الحرب بجانب ألمانيا، وتوفِّيَ قبل أن تستسلم الدولة في الحرب العالمية الأولى بعدة أشهرٍ مِن هذا العام، بعد أن أمضى في الخلافة الصوريةِ قرابةَ الثماني سنوات، ثم تولى بعده أخوه محمد السادس وحيد الدين."},{"id":4885,"title":"احتلال الجيش العثماني التاسع مدينة باكو في أذربيجان .","date":["العام الهجري :1336","الشهر القمري : ذي الحجة","العام الميلادي :1918"],"text":"احتلَّ الجيش العثماني التاسع، الذي يقوده نوري باشا، مدينةَ باكو في أذربيجان أثناء الحربِ العالمية الأولى، وأعلن نوري باشا أن تَدخُّل قواتِه حدث بطلبٍ مِن الحكومة الأذربيجانية، وتمكَّن الجيشُ من الوصول إلى حدودِ بحر الخزر -بحر قزوين-، لكِنَّ هذا الوضع لم يستمرَّ طويلًا؛ فقد اضطرت القواتُ العثمانية إلى الانسحاب بموجِبِ معاهدةِ موندروس."},{"id":4886,"title":"سيطرة القوات الفرنسية والإنجليزية على الشام .","date":["العام الهجري :1336","الشهر القمري : ذي الحجة","العام الميلادي :1918"],"text":"استطاعت كلٌّ من القوات الفرنسية والإنجليزية التمكُّنَ مِن السيطرة على بلاد الشام مِن الدولة العثمانية بما يتَّفِقُ مع اتفاقية سايكس بيكو، وقامتا بتحريضِ الأمير فيصل بن الحسين على ارتكابِ مذبحةٍ ضِدَّ الجنود العثمانيين المنسحِبين نحو الشمال."},{"id":4887,"title":"مؤتمر الرياض الأول .","date":["العام الهجري :1337","العام الميلادي :1918"],"text":"مع ما تمتَّع به الإخوانُ (إخوان من أطاع الله) من بسالةٍ وبطشٍ بالأعداء ورغبةٍ في الجهادِ، لكن بدا منهم جفاءٌ وغلظة مع من يخالِفُهم في طريقتِهم من الحضَرِ عُمومًا، والبدو خصوصًا، ممَّن لم يلحَقْ بهم في الهِجَر، وصاروا يتهمونَهم بالضلالِ، وربما رموهم بالكُفرِ، فانتشر من جرَّاءِ هذا الأمر الفوضى في البلادِ، وكاد ينقَطِعُ حبل الأمن والسلام، فعقد السلطان عبد العزيز ابن سعود مؤتمرًا في الرياض في هذا العام للنظرِ فيما استحدث الإخوانُ مِن تُهَمٍ وأحكامٍ حَضَره كبارُ الرؤساء والعلماء وقرَّروا بعد البحث ستة أمور: 1- الكُفرُ لا يُطلَقُ على بادية المسلمين الثابتين على دينهم. 2- لا تفاوُتَ بين لابسِ العقال ولابسِ العمامة إذا كان معتقَدُهم واحدًا. 3- لا فرقَ بين الحضر الأولينَ والمهاجرين الآخرين. 4- لا فرقَ بين ذبيحةِ البدوي الذي في ولايةِ المسلمين، ودَربُه دَربُهم، ومُعتقدُه مُعتقدُهم، وبين ذبيحةِ الحضر الأولين والمهاجرين. 5- لا حَقَّ للمهاجرين أن يعتدُوا على النَّاسِ الذين لم يُهاجِروا؛ كأن يضربوهم، أو يتهدَّدوهم، أو يُلزِموهم بالهِجرةِ.6- لا يحِقُّ لأحدٍ أن يهجُرَ أحدًا بدويًّا كان أو حضريًّا بغيرِ أمرٍ واضحٍ، وكُفرٍ صَريحٍ، وبدون إذنٍ مِن وليِّ الأمرِ أو الحاكِمِ الشرعيِّ."},{"id":4888,"title":"استقلال اليمن عن الدولة العثمانية .","date":["العام الهجري :1337","العام الميلادي :1918"],"text":"أخذت اليمنُ استقلالها عن الدولة العثمانية مبكرًا، وذلك منذ قيام الإمام محمد بن يحيى سنة 1307هـ ثم ابنِه يحيى؛ حيث حاربوا الجيوشَ العثمانية وأخرجوها من اليمن بعد حروبٍ مريرة حتى سمِّيَت البلاد مقبرة الأناضول، ولَمَّا ضاق العثمانيون ذَرعًا من الحرب في اليمن عَقَدوا صُلحًا مع الإمام يحيى سنة 1329هـ نال فيه اليمنُ الاستقلال الذاتي، ثم لما خسر العثمانيون في الحرب العالمية الأولى سنة 1336هـ جلت بقايا الحاميات العثمانية عن البلاد، فوجدت اليمنُ نَفسَها مستقلةً، واعترفت تركيا بهذا الاستقلال في معاهدة لوزان."},{"id":4889,"title":"هدنة مدروز واستسلام الدولة العثمانية في الحرب العالمية الأولى .","date":["العام الهجري :1337","الشهر القمري : محرم","العام الميلادي :1918"],"text":"تدهورت الأوضاعُ العسكرية للدولة العثمانية أثناءَ الحرب العالمية الأولى، وسيطر البريطانيون على العراقِ والشام، واحتلَّ الفرنسيون شماليَّ بلاد الشام، وسيطر الحلفاءُ على استانبول والمضايق التركية، ولَمَّا رأى قادة الاتحاد والترقي هذه الهزائم قدَّم طلعت باشا رئيس الوزراء استقالةَ وزارته، فتألفت وزارة جديدة برئاسة أحمد عزت باشا، وهرب كلٌّ من طلعت باشا وأنور باشا وغيرهما إلى ألمانيا. وأرسلت الحكومة الجديدة وفدًا وزاريًّا إلى مدينة مدروز في بحر إيجة بين اليونان وتركيا لمفاوضة الإنجليز على شروطِ الهدنة، وأرجأ الإنجليزُ الاجتماعَ النهائي لمدة أسبوعين حتى تتمكَّن قواتهم من احتلالِ الموصل وحلب. وعُقِدَت هدنة مدروز في 25 من محرم 31 من أكتوبر، ونصَّت على استسلام الدولة العثمانية دون قيدٍ أو شرطٍ، وهو ما لم يحدث بالنسبة لألمانيا، وبدأت القواتُ العثمانية في إلقاء سلاحها، وبدأت عملياتُ الاحتلال طبقًا للاتفاقيات، ووقَعت الأستانة تحت الاحتلال المشترك للحلفاء تحت قيادة الأميرال البريطاني \"كالثورب\". واستيقظ المسلمون على هذا الفاجعة المدوِّية، وزاد من كآبةِ هذه الفاجعة سعيُ الأقليات الدينية لخدمة مصالحها، خاصةً الأرمن واليونانيين، وجرت مذابِحُ ضِدَّ المسلمين، وظهرت روحٌ بغيضة من التشفِّي ضِدَّ المسلمين؛ فالجنرال اللنبي قال حين دخل القدس: \"الآن انتهت الحروب الصليبية\"، وبعد هدنة مدروز وصل الجنرال اللنبي القائد الإنجليزي إلى استانبول، وطلب من الحكومة التركية تعيين مصطفى كمال قائدًا للجيش السادس بالقربِ مِن الموصل."},{"id":4890,"title":"انتصار مصطفى كمال أتاتورك وإلغاء الخلافة الإسلامية وعلمنة تركيا .","date":["العام الهجري :1337","الشهر القمري : صفر","العام الميلادي :1918"],"text":"بعد هزيمة الدولة العثمانية في الحربِ العالمية الأولى، وإعلان هُدنةِ مودروس؛ وصل الجنرال اللنبي قائِدُ الإنجليز استانبولَ وطلب من الحكومةِ التركية تعيينَ مصطفى كمال قائدًا للجيش السادس بالقُربِ مِن الموصل حيث تهمُّ هذه المنطقة إنجلترا، وأثناء انسحاب مصطفى كمال من حلبٍ اقترح تشكيلَ وزارة جديدة برئاسةِ عزة باشا الأرناؤوط؛ لتخلُف وزارة الاتحاديين برئاسة طلعت باشا، وعلى أن يتولى هو في هذه الوَزارةِ الجديدة وزارةَ الحربية. تشَكَّلَت وزارةٌ جديدة برئاسة الأرناؤوط وضَمَّت عددًا ممن رشَّحهم مصطفى كمال لمناصِبَ وزارية، أما هو فلم يوافِقْ عليه الخليفةُ العثماني. فأخذ مصطفى يتقَرَّب من حزب أنصار الحرية والائتلاف الذي كان يتعاونُ مع سلطات الاحتلال، لكِنَّ الحزب لم يهتَمَّ به، ثم خطب مصطفى صبيحةَ بنت الخليفة العثماني وحيد الدين، فرفض طلَبه مباشرةً، كانت سلطاتُ الاحتلال تقبِضُ على كلِّ من يعود من القادة الأتراك من الجبهاتِ، ثم يُنفى إلى مالطة إلا مصطفى كمال فقد تركوه وشأنَه. كان الخليفةُ وحيد الدين ورئيسُ وزرائه فريد باشا يحسِنانِ الظَّنَّ بمصطفى كمال، فكَلَّفاه سرًّا بالقيام بثورة في شرق الأناضول، لعَلَّ هذه الثورة تُسهِمُ في الحدِّ من شروط الصلح القاسية التي فُرِضَت على الدولة. قَبِلَ مصطفى بالمهمَّة وزوَّده الخليفةُ بالمال ومَنَحَه منصِبَ مفتشٍ عامٍّ على الجيوش، ولَمَّا بُلِّغت الحكومةُ العثمانيةُ مِن الحلفاء بأنَّ الجيشَ اليونانيَّ سينزل أزمير، وعلى الحكومةِ عدَمُ مقاومتِه، فبعد نزولِ اليونانيين بيومين نزل مصطفى في ميناء أزمير من سفينة إنجليزية بشكلٍ مفاجئٍ للجميع، ثم أعلن الثورةَ على الدولة العثمانية، وتمرَّد على السلطان العثماني، وانزعجت الحكومةُ من تصرفاته، واحتجَّ الحُلَفاءُ في استانبول على الأعمالِ التي يقومُ بها مصطفى كمال في الأناضول؛ لإعطائه صفةَ الوطنية والإخلاصِ لأمَّتِه، فظهر كمال كمُنقذٍ للأمة، وتبعه وأيَّده كثيرٌ من الأتراك، ثم طلب الحلفاءُ مِن الحكومة استقدامَه إلى استانبول ووضْعَه تحت الرقابة، فدُعِيَ مِن قِبَل الوزارة، لكِنَّه لم يستجِبْ، فهدَّد الحلفاءُ بإعادة الحرب، فاضطرَّت الحكومةُ إلى إقالة مصطفى من منصِبِ المفتِّش العام، فقابل الإقالةَ بالاستقالة من الجيشِ، واتصل سرًّا بالإنجليز، ثم دعا إلى عقد مؤتمر في أرضروم، فانتُخب مصطفى رئيسًا له، ثم دعا مصطفى إلى مؤتمر أوسَعَ يشمَلُ تركيا كلَّها، فعُقِدَ مؤتمرُ سيواس في 13 ذي الحجة 1337هـ، وكانت الحكومةُ في استانبول ترى إلغاءَ المؤتمر واعتقالَ أعضائه، والحلفاءُ يؤيِّدون الحكومةَ في رأيهم لإعطاء مصطفى كمال مزيدًا من القوة، وجَعْله زعيمًا وطنيًّا يقاوم المحتَلَّ. عُقِد المؤتمَرُ وانتُخِبَ مصطفى رئيسًا له وشُكِّلَت فيه جمعيةٌ تُعنى بالدفاع عن كامل الوطنِ، وانتُخِبَت هيئةٌ تمثيليةٌ بقي أعضاؤها في سيواس. غادر مصطفى كمال سيواس إلى أنقرة التي اتخذَها مقرًّا له. احتلَّ الإنجليز باسم الحلفاء استانبول بشكلٍ كاملٍ في جمادى الآخرة 1338هـ / آذار 1920م، وبدأت الاعتقالاتُ في صفوف المؤيِّدين لمصطفى كمال، ثم نُفُوا إلى مالطة؛ لإظهارِ خلافهم مع مصطفى، وفَرَضت الحكومةُ الرقابةَ على الصحُفِ ووسائِلِ الإعلام، وراقب الإنجليزُ الوزارةَ وطلبوا بطاعةِ أوامر الخليفة؛ لينفِرَ منه الشعبُ ويتعلَّقَ أكثَرَ بمصطفى كمال الذي يعمَلُ فيما يبدو للناس ضِدَّ الإنجليز المحتلين، وأنَّه لم يتحرَّكْ ضِدَّ الخليفة إلا لأنَّه مؤيَّدٌ مِن قِبَل المحتلين، وهذا ما جعل الأتراك يرتبطون بكمال ويؤيدونه ويسيرون وراءه. في رجب 1338هـ حُلَّ المجلسُ النيابي وشُكِّل مجلِسٌ جديدٌ برئاسة فريد باشا صِهرِ الخليفة بطلبٍ مِن الإنجليز وضَغطٍ منهم؛ ليظهَرَ للنَّاسِ أن الخليفةَ وحكومتَه يسيرانِ برأي الأعداء، فيتَّجِهَ الناسُ أكثر إلى مصطفى كمال الذي يبدو أنَّه على خلاف مع المحتلين، وأنَّه عدوُّهم الأول، فلما استبَدَّ فريد باشا بحُكمِه تضايقَ السكانُ وأحبُّوا الخلاص منه، وليس لهم من طريقٍ سوى مصطفى كمال. جرت انتخاباتٌ ونجح مصطفى غيابيًّا عن أنقرة، فعُقِد مؤتمرٌ ونصب نفسه رئيسًا للمجلس وللهيئة التنفيذية، ثم أظهر التدينَ ولَبِسَ شعاره، وأعلن أن أولَ جلسة ستُفتتح بعد صلاة الجمعة في هذا اليوم المبارك في أنقرة، وعندما ألقى الخطبةَ الافتتاحية أكثَرَ من مدح الخلافةِ، وأنَّ كُلَّ ما فعله في الأناضول وانتقاله إليها كان بمعرفة الخليفة وأمرِه. أصدر شيخ الإسلام في استانبول فتوى ضدَّ مصطفى كمال فضَعُف مركزُه، وسيَّرَ الخليفةُ حملةً إلى كردستان فانضَمَّت لها كلُّ أجزاء الأناضول باستثناء أنقرة التي أرسل إليها الخليفةُ حملةً لإخضاعها لسلطانه، وكادت أوراقُ مصطفى كمال تتساقط وينتهي أمرُه، لولا تدارُكُ أسيادِه الإنجليز بإعلانِ معاهدة سيفر المجحفة بأسلوبٍ إعلامي مثيرٍ، فهاج الشعبُ ضِدَّ الخليفة الذي وقَّع عليها هو وحكومته برئاسة فريد باشا، وإن كانا مُكرَهينِ، فعاد الناسُ إلى تأييد مصطفى كمال ورجال الحملة التي وجهها الخليفةُ إلى أنقرة انقلبت من ضد كمال لتصبِحَ معه، حتى أصبح مصطفى يفكِّرُ في الهجوم على العاصمة استانبول، فالأمرُ في غاية الوضوح أنَّ الخليفةَ والحكومة مع الإنجليز في الظاهر، وهما أعداء لها واقعًا, ومصطفى كمال يهاجِمُ الإنجليز في الظاهر ويتَّفِقُ معهم في الحقيقة. جاء إعلان معاهدة سيفر في الوقت المناسِب، فانتصر مصطفى كمال على حملةِ الخليفة في أنقرة، وعلت مكانتُه وأرادت إنجلترا أن تقطِفَ ثمار تخطيطها؛ فقد غدا صنيعتُها في موقفٍ يؤهِّلُه لتسلُّم المنصِبِ الأول، فدعت بريطانيا إلى عقدِ مؤتمر في لندن لحلِّ المسألة الشرقية مع تركيا، فوجَّهت دعوةً لحكومة استانبول الحكومةِ الشرعيةِ، وهي المعنيةُ بالتفاوض بشأن الصلحِ، كما أن الإنجليزَ وجَّهوا دعوةً كذلك لحكومة مصطفي كمال في أنقرة، وهذا اعترافٌ منهم ضمنيًّا بحكومة أنقرة، وبلغ من جرأةِ حكومة أنقرة أنَّها رفضت دعوةَ حكومة استانبول؛ لأنَّها هي الممثِّل الوحيد للشعب التركي والمدافِع عن حقوقه. حضر في لندن ممثِّلون عن الحكومتين، وحرصًا على وحدة الصَّفِّ ترك وفدُ استانبول الحديثَ لوفد أنقرة، وفَشِلَ المؤتمر لكِنْ ظَهَرت حكومةُ أنقرة كممَثِّل رئيس للشعب التركي. اتصل مصطفى كمال بالفرنسيين واعترف لهم بحقِّهم في سوريا ولبنان، فكسب رضاهم واعترفوا به كممثِّل لدولة تركيا الحديثة، ثم اتصل بروسيا الشيوعية وعقدَ معهم معاهدةً في رجب 1339هـ / 16 آذار 1921م تنازل لها عن منطقة آجاريا (جورجيا) فرَضِيَت عنه واعترفت بحكومته في أنقرة، على أنها تمثِّل الدولة الحديثة للأتراك، واتصل بإيطاليا التي اعترفت بحكومتِه وتنازل لها عن منطقة أضاليا -جنوب غرب تركيا- التي دخلتها أثناء الحرب، فاتجهت الأنظارُ إلى مصطفى كمال كمنقذٍ لتركيا وممثِّل لدولة تركيا الحديثة، وأُغلِقَت كلُّ القنوات أمام  الخليفة وبهذا نجحت اللعبةُ الدولية التي حبكتها إنجلترا مع دول الحُلفاء؛ وفي 17 ربيع الأول أُقيلَت حكومةُ السلطان في استانبول بضغطٍ مِن إنجلترا، وتنازل السلطانُ وأُبعِدَ عن البلاد، ثم بحثت إنجلترا مع حكومةِ أنقرة موضوع إلغاء السلطنة وإعلان تركيا دولة علمانيةً، وهو شرطُ اعتراف الحلفاء بدولة تركيا الحديثة، فأعلنت حكومةُ أنقرة إلغاءَ السلطنة، وفَصْل الدين عن الدولة، فسُرَّ الحلفاءُ بهذا الإعلان، ودَعَوا حكومةَ أنقرة إلى لوزان؛ لإعادة النظر في بنود معاهدة سيفر، وكان مصطفى كمال يشكِّل حكوماتٍ بدون برامج، ويعَيِّنُ من يشاء ويعزل من يشاء حسَبَ مزاجِه الخاص، أو ما يقَدَّمُ له من خِدماتٍ. تشكَّلَ الوفدُ إلى مؤتمر الصلح في لوزان من وزير الخارجية عصمت إينونو، ووزير الصحة، وخبير مالي، وجاء الحلفاءُ، وهم: إنجلترا، وفرنسا، وإيطاليا، واليابان، واليونان، والولايات المتحدة الأمريكية، وكان الأمرُ كُلُّه بيد إنجلترا، وتم تعديل بنودِ معاهدة سيفر بعد جولتينِ تمَّت بين الأطراف بعد أن أعدَّ البنودَ الجديدة كبيرُ حاخام اليهود في الدولة العثمانية حاييم ناعوم، ومستشار إيطاليا ماتر سالم -يحمل جنسية عثمانية- مع الوفد التركي إلى لوزان، وكان إلغاءُ الخلافة وتَرْك الموصِل شرطين أساسيين لاستقلال تركيا. اجتمع المجلسُ النيابي في أنقرة بن20 ربيع الأول 1342هـ/ 30 أكتوبر 1923م وقرَّر إلغاءَ السلطنة وإعلان الجمهورية، وانتُخِبَ مصطفى كمال رئيسًا للجمهورية، وبعد يومين وُقِّع الصلحُ في لوزان، وأُطلِقَت المدافعُ في تركيا؛ ابتهاجًا بهذا التوقيع."},{"id":4891,"title":"تأسيس حزب الوفد المصري المطالب بالاستقلال .","date":["العام الهجري :1337","الشهر القمري : صفر","العام الميلادي :1918"],"text":"انتهت الحربُ العالمية الأولى وخرجت إنجلترا ومن معها منتَشِين بالنصر، وكانت تُمنِّي المصريين بمنحِهم الاستقلالَ فورَ انتصارهم في الحرب، ولما كان الاحتلالُ مكَلِّفًا أكثر من إبقاء الدولة تابعةً لها بوضع أناسٍ يُخضِعون إدارتها، فتحصُلُ على ما تريد دون خسائرَ بشرية ولا خسائِرَ اقتصادية، فأظهرت اللِّينَ وأبدت الاستعدادَ لفكرة الاستقلالِ، وهيَّأت أشخاصًا مناسبين لها لهذا العمل الجديد، فأوحت لسعد زغلول بالتحرُّكِ، فدعا لاجتماع في صفر تمخَّض عن المطالبة بالاستقلال وتشكيلِ وفدٍ للسَّفَر إلى باريس لعرض القضية على مؤتمر الصُّلحِ، وتشكَّل الوفدُ مِن سعد زغلول، وعلي الشعراوي، وعبد العزيز فهمي، ولكِنَّ الأمر لا بدَّ له من ضجةٍ وضوءٍ ليبدوَ طبيعيًّا، فقامت إنجلترا بمنع الوفدِ مِن السفر وقبضت على سعد زغلول وغيره، ونُفيَ إلى مالطة فأصبح بطلًا وطنيًّا!! وقامت المظاهرات، ومنها المظاهرة النسائية المشهورة في ميدان التحرير، التي قادتها هدى شعراوي، وخلعت فيها الحجابَ وأحرقت صفية فهمي -زوجة سعد زغلول- حجابَها، وفعل بعضُ الساذجات المغفَّلات مثلَهنَّ، وكأن الحجابَ فرضته إنجلترا حتى يكون هذا مظهرًا من التنديد بالاستعمارِ!!! وقامت المظاهراتُ بالتخريب والتدمير بلا هدفٍ ولا مبرِّرٍ، ليس إلا التقليد الأعمى، فهم يدمرون بلادَهم هم لا بلادَ العدو، بل وسمِّيَ هذا الميدان فيما بعد \"ميدان التحرير\"!! واستقالت الوزارةُ واندلعت الثورةُ في أرجاء مصر، واعترفت أمريكا بالحماية الإنجليزية على مصر، ثم رُفِع الحظر على السفر، وأطلق سراح المنفيين في مالطة، فتألَّف وفدٌ جديد ضمَّ سعد زغلول، وعلي الشعراوي، وسينوت حنا، وجورج خياط، وغيرهم، وفي 11 رجب 1337هـ / 11 نيسان 1919م غادر الوفد البلادَ ووصل باريس، وبدأ الاتصال بالمسؤولين في مؤتمر الصلح، غير أن الأمور كانت مرتبةً وجاهزة كما يريد الصليبيون، وحدثت اضطراباتٌ بمصر، واتفقت كلمة شعب مصر أن الرأي للمفاوِضين في باريس ولهم القرار، ورفَضَ أيٌّ منهم المفاوضةَ داخل مصر َبغياب الوفد المصري، فسافرت لجنةُ ملنر التي جاءت إلى مصر للمفاوضة إلى لندن، ودعت المفاوضين للسفر من باريس إلى لندن للمفاوضة معهم، وتبيَّن أن أعضاء الوفد متفاوتون في درجة رضوخِهم للمفاوضات وشروطها، فرجع البعض لمصر وبقي البعض، منهم سعد زغلول، وبقيت الأمورُ بين أخذٍ وردٍّ، وكل ذلك إنجلترا تصِرُّ على إبقاء حامية إنجليزية في مصر، وفشلت المباحثات. ثم جرى اتفاقٌ بين المعتمد البريطاني في القاهرة وبين عبد الخالق ثروت، وعدلي يكن، وإسماعيل صدقي، وذلك في 14 جمادى الأولى 1340هـ / 12 كانون الثاني 1922م، نص الاتفاق على تأليف وزارة برئاسة عبد الخالق ثروت؛ شريطة موافقة الحكومة البريطانية على نقاطٍ، منها إلغاء الحماية والاعتراف بمصر مستقلةً، وإلغاء الأحكام العسكرية، وحماية المصالح الأجنبية وغيرها."},{"id":4892,"title":"المظاهرة النسائية وخلع الحجاب في مصر .","date":["العام الهجري :1337","الشهر القمري : جمادى الأولى","العام الميلادي :1919"],"text":"قامت مجموعةٌ من النساء المصريات بمظاهرةٍ نسائية في ميدان الإسماعيلية منَدِّدةً بالاحتلال الإنجليزي، كان على رأسهن صفية زغلول، وهدى شعراوي؛ حيث إن زوجيهما كانا أبرزَ قادة الوفد المقتَرَح لمفاوضة الحلفاء لتقريرِ مصير مصر بعد الحرب العالمية الأولى، وتجمَّع النسوة أمام ثكنات الجيش الإنجليزي، وهتَفْنَ ضِدَّ الاحتلال. ثم بتدبيرٍ سابقٍ ودون مقدماتٍ ظاهرةٍ خَلَعْنَ الحجابَ، وألقين به في الأرضِ، وسكَبْنَ عليه البترولَ، وأشعَلْنَ فيه النار، وتحرَّرت المرأة -على زعمهم- وكأنَّ خَلْعَ الحجابِ سيُخرج الاستعمارَ، ويُنهي وجودَ الإنجليز بمصر!!! وسمِّي ميدان الإسماعيلية فيما بعد بميدان التحرير!!"},{"id":4893,"title":"اغتيال أمير الأفغان حبيب الله خان وتولي ابنه أمان الله خان .","date":["العام الهجري :1337","الشهر القمري : جمادى الأولى","العام الميلادي :1919"],"text":"هو حبيب الله خان عبد الرحمن خان بن محمد أفضل خان بن دوست محمد خان، ولِدَ سنة 1872م، تولى إمارة أفغانستان عام 1901م، وفي عهدِه اعترفت كلٌّ من إنجلترا وروسيا باستقلال بلاد الأفغان، عندما احتلت إيطاليا ليبيا دعا حبيب الله شعبَه لدعم جهاد الليبيين ضِدَّ الاحتلال الإيطالي، وافتتح التبرعاتِ بعشرين ألف روبية، ولَمَّا اندلعت الحرب العالمية الأولى التزم الحيادَ في أفغانستان في الحرب العالمية الأولى، على الرغم من الجهود المضنية التي بذلها السلطان العثماني والألمان لحشد أفغانستان على جانبها. وهذا ما أزعج الأفغانيين الذين قاموا باغتيالِه في 1338هـ، ثم تسلَّم السلطةَ بعده ابنه الثالث أمان الله خان، وتسمى باسم ملك، وحاول التخلصَ من النفوذ الإنجليزي."},{"id":4894,"title":"ثورة المصريين ضد الاحتلال البريطاني .","date":["العام الهجري :1337","الشهر القمري : جمادى الآخرة","العام الميلادي :1919"],"text":"بعد انتهاء الحرب العالمية الأولى توقَّعت إنجلترا بدءَ مستعمراتها في طلب الاستقلال، فأخذت تظهِرُ اللينَ، وأبدت استعدادَها للموافقة، وأوحت إلى سعد زغلول ورفاقه بالتحرك، فبدأ في عقد اجتماعات ولقاءات أسفرت عن طلب الاستقلالِ، وتم تشكيلُ وفد للسفر إلى الخارج لعرض القضية على العالم، وتشكَّل هذا الوفد من سعد زغلول، وعلي شعراوي، وعبد العزيز فهمي، وطلبوا مقابلةَ المندوب السامي البريطاني «وينجت» وطلبوا منه السماح لهم بالسفر إلى إنجلترا؛ لعرض طلباتهم باستقلال مصر، فرفض المندوبُ ذلك الطلب، فاستعدَّ سعد زغلول ورفاقُه إلى السفر إلى جهة أخرى، وهي باريس؛ وذلك لعرض قضية مصر على مؤتمر الصلح، فاعتبرت إنجلترا هذا تمردًا منهم، فألقت القبضَ عليهم، ومعهم آخرون، منهم: محمد محمود، وحمد الباسل، وإسماعيل صدقي، ثم ما لبثت أن أفرجت عنهم، فلما لم يحقِّقْ هذا القبضُ الهدفَ منه -ألا وهو أن يُتوَّجَ هؤلاء زعماءَ جُددًا لمصر- وكان مصطفى كامل وخليفته محمد فريد ما زالا يمثِّلان الزعامة الوطنية للمصريين، قامت إنجلترا بالقبضِ عليهم مرة أخرى ونفيِهم إلى مالطة. وعندما وصلت أخبار النفي للشعب المصري ثار ثورةً عارمة يملؤها الإحساسُ بالعدوان والطغيان الصليبي الذي أرهق المصريين لسنوات طويلة، وبدأت الثورةُ يوم 7 جمادى الآخرة 9 مارس بتظاهُرِ طلبة كلية الحقوق والهندسة والزراعة والطب والتجارة، وتصدى الجنودُ الإنجليز للمظاهرات، وأوقعوا عددًا كبيرًا من القتلى والجرحى. امتدت الثورةُ بعد ذلك لتشمل جميعَ شرائح وقطاعات الشعب المصري من محامين وعمال وموظفين وصحفيين ونساء، وتحوَّلت من ثورة سِلمية إلى ثورة عنيفة وقعت خلالها أعمالُ تخريب وسلب ونهب، ونجحت الثورةُ في تحقيق أهدافها الخفيَّة، وأصبح سعد زغلول هو زعيمَ الأمة المتحَدِّث باسمها؛ ليبدأ فصلًا جديدًا في مصرَ تختفي فيه الشعاراتُ والهُوية الإسلامية، وتحلَّ محلَّها الوطنيةُ والقوميَّةُ!!"},{"id":4895,"title":"اندلاع الحرب الأفغانية البريطانية الثالثة واستقلال أفغانستان .","date":["العام الهجري :1337","الشهر القمري : شعبان","العام الميلادي :1919"],"text":"اندلعت الحربُ الثالثة بين بريطانيا وأفغانستان في هذا العام، بينما كانت الحربُ الأولى عام 1254ه حيث هُزمت فيها بريطانيا هزيمةً نكراء، والحرب الثانية في عام 1295ه التي انتصرت فيها بريطانيا ورضيت من نتائج نصرِها بالسيطرة على المناطق الحدودية لبلاد الأفغان، وبقية السيادة كاملة للأفغان داخِلَ بلادهم. أما الحربُ الثالثة هذه، فكان سببُها هو عدم اعتراف الحكومة الهندية البريطانية (الراج البريطاني) باستقلال أفغانستان، وانتهت الحربُ بتوقيع بريطانيا معاهدة روالبندي في 19 أغسطس 1919م التي تعترفُ فيها باستقلال أفغانستان داخليًّا وخارجيًّا، ومن ثَمَّ أصبح هذا التاريخُ ذكرى للاستقلال."},{"id":4896,"title":"معركة تربة وهزيمة الإخوان (إخوان من أطاع الله) لجيش الشريف حسين .","date":["العام الهجري :1337","الشهر القمري : شعبان","العام الميلادي :1919"],"text":"عندما استردَّ الأمير عبد الله بن الشريف حسين واحةَ تربة (جنوب غربي نجد) التي خضعت مؤخرًا لسلطان الملك عبدالعزيز، فهجم جيشُ الإخوان بقيادة سلطان بن بجاد ومعه قبائل سبيع وعتيبة وخالد بن لؤي أمير الخرمة (من محافظات منطقة مكة المكرمة) على جيش الأمير عبد الله بن الحسين، بعد منتصف الليل من مختلف الجهات، الأمرُ الذي أصاب الأمير عبد الله بالارتباك، فلم يستطع أن يفعل شيئًا، فمزَّق الإخوان جيشَه على الرغم من كثرة عددِ جُندِه المدرَّب تدريبًا حديثًا على يد الإنجليز، وكثرة عتاده من الأسلحة الحديثة التي كانت بريطانيا قد زوَّدت الشريف حسين بها، وتجاوز عددُ القتلى خمسة آلاف قتيل، ولم ينجُ منهم إلا عدد قليل، منهم الأمير عبد الله بن الحسين، واستولى الإخوان على أسلحة ومؤن وأموال وعتادٍ كثير، ثم وصل عبد العزيز بجيشه إلى تُربة، فأقام بها خمسة عشر يومًا يديرُ شؤونها. أما الملك حسين بن علي فقد أفزعه ما حلَّ بجيشه في تُربة. وخاف من مواصلة الإخوان تقدُّمَهم نحو الطائف. فاتصلَ بالحكومة البريطانية يطلُبُ مساعدتَها، فحذَّرَتْه من التوغُّل في الحجاز، وقد برزت قوةُ الإخوان الضاربة لأول مرة في هذه المعركة."},{"id":4897,"title":"تأسيس الحزب الحر الدستوري في تونس .","date":["العام الهجري :1337","الشهر القمري : شعبان","العام الميلادي :1919"],"text":"أسَّس الحزبَ الحُرَّ الدستوريَّ في تونس أنصارُ عبد العزيز الثعالبي أثناء اعتقال الفرنسيين له، وقد ساهم في نشأةِ الحزب جملةٌ من العوامل الداخلية والخارجية أدت إلى ظهوره، كان من بينها على مستوى عالميٍّ الإعلانُ عن مبادئ الرئيس الأمريكي وِلْسن، الداعية إلى تحرير الشعوب، وحَقِّها في تحرير مصيرها، بالإضافة إلى تنامي حركات التحرُّر في العالم، فلما أُطلِقَ سراح الثعالبي تولى رئاسةَ الحزب، وقد آزر الحزبَ مجموعةٌ من الوطنيين التونسيين، وكانوا من الطبقة المتمسِّكة بالثقافة العربية، والتي خشيت على تونس من نفوذ الثقافةِ الغربية، وعقد الحزب مؤتمرًا له في منزل الشيخ حمودة المنستيري بالمرسى برئاسة الشيخ عبد العزيز الثعالبي. وتقرر انتخابُ أحمد الصافي أمينًا عامًّا للحزب، وأحمد توفيق المدني أمينًا عامًّا مساعدًا للقلم العربي. وأعيد تنظيمُ الحزب، فكان أعضاء اللجنة التنفيذية يضمون 27 رجلًا. غير أنَّ حزب الدستور لم يلبث أن انهار تحت ضرباتِ الاستعمار الفرنسي ومؤامراتِه."},{"id":4898,"title":"إعلان مصطفى كمال أتاتورك استقلاله عن الخليفة العثماني .","date":["العام الهجري :1337","الشهر القمري : شعبان","العام الميلادي :1919"],"text":"أبلغت لجنةُ الحلفاء العليا المقيمة في باريس الحكومةَ العثمانيةَ قرارًا يقضي بنزول الجيوشِ اليونانية في أزمير ويحذِّرونها من المقاومة، فأبلغت الحكومةُ التركية والي أزمير الالتزامَ بالهدوء وعدمِ المقاومة؛ لأن الحلفاءَ سيحتلون أزمير، ثم ظهر الأسطولُ الإنجليزي في مياه المدينة في 14 أيار، وأبلغ القائدُ الإنجليزي كالثورب واليَ أزمير بأنَّ الاحتلال سيكون من قِبَل اليونان وليس من قِبَل الحُلَفاء، فصُعِقَ الوالي لذلك الخبر، وبدأ الإنزال اليوناني في 15 أيار، وطاف الجنود اليونانيون الشوارعَ في تحدٍّ سافرٍ مثيرٍ للمشاعِرِ، وأطلقوا النارَ على الأتراك وأجبروهم على خلعِ طرابيشهم وداسوها بأقدامِهم، واستفزُّوا الضباطَ بالبصاق في وجوههم، وأخذوا بانتزاعِ الحجاب عن وجوه النساء المسلِمات، وفي زحمة هذه الأحداث رست الباخرة أينبولي في مياه أزمير بين الأسطول الإنجليزي والبواخر اليونانية، ونزل منها مصطفى كمال (أتاتورك) بصورةٍ مفاجئة، وهو الذي من المفروض أن يكون قد سافر إلى الأناضول، وبالذات إلى مدينة سامسون عن طريق البحر الأسود؛ لذلك في اليوم التالي لسفره طلبته الحكومة لتأكُّدِها من إثارته للاضطرابات، فانفجرت روحُ المقاومة، وتشكَّلت جمعياتٌ سرِّية، مثل جمعية القرقول، وامتدَّت المقاومة والأعمال الفدائية إلى مناطِقَ متعددة في البلاد، واستغل مصطفى كمال هذه الفوضى، وأعلن استقلالَ نَفسِه وعدمَ ارتباطه بالخليفة أو الحكومة، وأخذ يحرِّضُ الناس على الثورة ضِدَّ الحكومة العثمانية."},{"id":4899,"title":"حركة محمود المعروف الكردي ضد الاحتلال الإنجليزي .","date":["العام الهجري :1337","الشهر القمري : شعبان","العام الميلادي :1919"],"text":"كان محمود المعروف أحدَ زعماء الأكراد الذين برَزوا في السليمانية، وكانت له شعبيةٌ واسعة، وعندما انسحب العثمانيون من العراق لصالح الإنجليز أراد القائدُ العثماني أن يستفيدَ من محمود ونفوذه، فأمَدَّه بالمال وترك له فوجًا يتصرَّفُ بإمرته، والإنجليز لم يكونوا وصلوا للسليمانية، ولما رأى محمود أن القوةَ أصبحت للإنجليز لا للعثمانيين أراد الاتصالَ بهم، فكتب إلى وِلْسن القائد الإنجليزي في كركوك، وطلب منه أن يشكِّلَ حكومةً في السليمانية برئاسته وتكون تابعةً لتوجيه الإنجليز، فوافق على ذلك الإنجليز وعُيِّن محمود حاكمًا على السليمانية براتبٍ معيَّن، ومعه مستشار عسكري هو النقيب دانليس، ولكِنَّ الحكومة الإنجليزية تعرِفُ أنَّه مجرَّد تابع، فتصرفت كما شاءت لا كما شاء هو، ونظرت لمصالحها لا لمصالحه، فأعلن محمود سيطرتَه على السليمانية واحتلَّها وأخذ الضباط الإنجليز أسرى، وجعل لنفسه علمًا خاصًّا هو الهلالُ الأحمر على الأرضية الخضراء، وعمل طوابِعَ بريدية خاصة، وهاجم الجيشَ المرابط في مضيق طاسلوجه وسيطر على المنطقة، لكِنَّ الإنجليز سيَّروا له فرقةً فحاصرته في مضيق دربند بمعاونة بعضِ الزعماء الأكراد، فاستطاعت القبض عليه وقُدِّمَ للمحكمة التي حكَمَت عليه بالقتل، ثم خفِّفَ للمؤبَّدِ، ونفِيَ إلى الهند."},{"id":4900,"title":"إقالة الحكومة العثمانية مصطفى كمال كمفتش عام الجيوش .","date":["العام الهجري :1337","الشهر القمري : شوال","العام الميلادي :1919"],"text":"كان السلطانُ وحيد الدين يدرِكُ أنَّ ما فقدته الدولة العثمانية لا يمكِنُ أن يعود إلا بالقتال، فكلَّف سرًّا مصطفى كمال بمهمة إثارة القلاقل في الأناضول، وعيَّنه مفتشًا عامًّا لجيوش الأناضول ليعمِّيَ على الحلفاء -وخاصة الإنجليز- الدور الذي سيلعبه مصطفى كمال في إثارة الفوضى فيها، لكِنَّ مصطفى كمال لم يذهب للأناضول، وإنما اتَّجه إلى أزمير بتدبير مع الإنجليز ودخَلَها مع دخول القوات اليونانية، واستغل الفوضى التي ترتَّبت على مذابح اليونانيين في الأتراك، واستثمر حماس الأتراك لجهادِ المحتَلِّ، وأعلن استقلالَه عن السلطان في استانبول وأظهر أنه المنقِذُ لتركيا. أزعجت تصرفاتُ مصطفى كمال الحكومةَ العثمانية، وانتهى الأمر بإقالته، لكنَّ مصطفى كمال عقد مؤتمرًا في أرضروم دعا فيه إلى وحدة البلاد ضِمنَ الحدود القوميَّةِ."},{"id":4901,"title":"اتفاقية المساعدة البريطانية من أجل تقدم فارس ورفاهيتها .","date":["العام الهجري :1337","الشهر القمري : ذي القعدة","العام الميلادي :1919"],"text":"كانت فارس مقسَّمةً إلى ثلاثة أقسام: قسم تحت النفوذ الروسي، وقسم تحت النفوذ البريطاني، وقسم محايد، ولما انتهى النفوذ الروسي في فارس بعد قيام الثورة الشيوعية، وتسلمها مقاليد الحكم في محرم 1336هـ / تشرين الأول 1917م وتنازلوا عن ديونهم على فارس، وأرادت إنجلترا أن تحُلَّ محلَّ روسيا فلم تتمكَّنْ، ولكنها رأت أن تجعل على الأقل سدًّا في وجه التوسع الشيوعي، فأسرعت في توقيع اتفاقية مع فارس بعد مباحثات لمدة سنة، فكان التوقيعُ على الاتفاقية المسمَّاة بـالمساعدة البريطانية من أجل تقدُّم فارس ورفاهيتها، واعترفت ظاهرًا باستقلال فارس، لكنها قيَّدتْها بقيود جعلتها تحت حمايتها؛ حيث جاء في الاتفاقية أن تستخدم فارس المستشارين البريطانيين في كلِّ مؤسَّساتها حتى الجيش، وألَّا تتسلَّح إلا من بريطانيا، وأن تكون بريطانيا هي من ينشئ فيها المواصلاتِ وكذلك تحديد الحدود، ثم أقرضَتْها دينًا قدره مليونا جنيه بفائدة سبعة بالمائة، ووقَّع الاتفاقية رئيس وزراء فارس \"وثوق الدولة\" والسفير البريطاني برسي كوكس، ورضي الشاه أحمد بالاتفاقية، ولكن الشعب ثار وحدثت انتفاضاتٌ في عدد من المناطق وأسست المعارضة حكوماتٍ مُستقلةً في تلك المناطق."},{"id":4902,"title":"مؤتمر الشرق الأوسط لمناقشة توسع الملك عبدالعزيز في الحجاز .","date":["العام الهجري :1337","الشهر القمري : ذي الحجة","العام الميلادي :1919"],"text":"أثار انتصار قوات الإخوان (إخوان من أطاع الله) في تربة وتفوقهم العسكري مخاوف الإنجليز من توسع الملك عبدالعزيز تجاه الحجاز على حساب حليفهم الشريف حسين لذلك حاولت بريطانيا تخفيف حدة الصراع والتوتر بين الحجاز ونجد والحيلولة دون تقدم آل سعود إلى الحجاز بأن طلبت منه أن يسحب قواته من الحجاز، ثم دعا اللورد كيرزون وزير الخارجية البريطانية لعقد مؤتمر في مبنى وزارة الخارجية في لندن دعا إليه مسؤولون بريطانيون مختصون بالشرق الأوسط فأشار في المؤتمر جون فيلبي سكرتير برسي كوكس المعتمد البريطاني في الخليج إلى أن الملك عبدالعزيز لن يتقدم نحو الأراضي الحجازية لأنه أكثر حكمة من أن يلحق الإساءة بعلاقته مع بريطانيا من خلال توسعه في الحجاز إلا أن كيرزون أوضح أن الموقف لا يسمح بالتكهنات والاحتمالات حول تقدم الملك عبدالعزيز نحو الحجاز واقترح إرسال مبعوث للرياض لإبلاغ الملك عبدالعزيز انزعاج بريطانيا من سوء علاقته بالهاشميين وكُلف فيلبي بتبليغ رسالة الإنجليز للملك عبدالعزيز وأمرت الخارجية البريطانية الجنرال اللنبي المندوب السامي في القاهرة أن يرسل ست طائرات حربية إلى جدة لمساعدة الحسين إذا ما حاول الملك عبدالعزيز التقدم نحو الحجاز، وعند ما أظهر الشريف حسين انزعاجه من حسن تعامل بريطانيا مع الملك عبدالعزيز أرسل اللنبي إليه يطمئنه بأن الحكومة البريطانية لن تتخذ موقفا يضر بمصالحه ويؤُخذ بعين الاعتبار شروط المعاهدة بين حكومة بريطانيا والملك عبدالعزيز التي تتعهد بموجبها حمايته والاعتراف باستقلاله ورجاء الامتناع عن إثارة أية مشكلة قد تؤدي إلى توتر العلاقات مع الملك عبدالعزيز."},{"id":4903,"title":"عقد اتفاق بين فرنسا وإيطاليا حول بعض الواحات التونسية .","date":["العام الهجري :1337","الشهر القمري : ذي الحجة","العام الميلادي :1919"],"text":"تمَّ عقدُ اتفاق بين فرنسا وإيطاليا، تمَّ بمقتضاه النزولُ لإيطاليا عن عددٍ من الواحات الهامة في الجنوب الشرقي لتونس، وأصبح وضعُ الإيطاليين معادِلًا لوضع الفرنسيين في تونس."},{"id":4904,"title":"قيام مصطفى كمال بعقد مؤتمر سيواس .","date":["العام الهجري :1337","الشهر القمري : ذي الحجة","العام الميلادي :1919"],"text":"عقد مصطفى كمال مؤتمر سيواس، وقد تشكَّلت فيه هيئةٌ تمثيلية، وطالب الدوائرَ العسكرية والمدنية بالارتباط بها، وقَطْعِ علاقتهم باستانبول، ثم انتقل مقرُّ هذه الهيئة إلى أنقرة."},{"id":4905,"title":"تشكيل حكومة الاحتلال البريطاني لجنة ملنر .","date":["العام الهجري :1337","الشهر القمري : ذي الحجة","العام الميلادي :1919"],"text":"قامت حكومةُ الاحتلال البريطاني بتشكيل لجنة عُرِفَت باسم \"لجنة ملنر\"؛ وذلك من أجل التحقيق في أسباب اشتعال الثورة المصرية المعروفة بثورة 1919م، على الرغم من أن الإنجليز هم من خطَّط لقيام ثورة احتجاجٍ على اعتقال أعضاء الوفد المزمَع سفرُهم للتفاوض في باريس؛ وذلك لمزيد من صناعة أعضاء الوفدِ سعد زغلول ورفاقه كزعماء وطنيين بدلًا من الزعامة الوطنية الموجودة في البلاد، كمصطفى كامل، فقدَّمت لجنة ملنر مقترحاتٍ لتنظيم الأحوال في مصر، ومن هذه المقترحات:1- لكي يبنى استقلال مصر على أساس متين دائم يلزم تحديدُ العلاقات بين بريطانيا العظمى ومصر تحديدًا دقيقًا، ويجب تعديلُ ما تتمتع به الدول ذوات الامتيازات في مصر من المزايا، وجعلها أقلَّ ضررًا بمصالح البلاد. 2- ولا يمكن تحقيقُ هذين الغرضين بغير مفاوضات جديدة تحصل للغرض الأول بين ممثِّلين معتَمَدين من الحكومة البريطانية وآخرين معتَمَدين من الحكومة المصرية، ومفاوضات تحصل للغرض الثاني بين الحكومة البريطانية وحكومات الدول ذوات الامتيازات، وهذه المفاوضات ترمي إلى الوصولِ إلى اتفاقات معيَّنة ومبنية على قواعِدَ مُعينةٍ."},{"id":4906,"title":"زيارة الأمير فيصل بن عبدالعزيز الأولى لأوروبا .","date":["العام الهجري :1337","الشهر القمري : ذي الحجة","العام الميلادي :1919"],"text":"دفعت أحداث تربة والخرمة (من محافظات منطقة مكة المكرمة) والصراع الحجازي النجدي الحكومة البريطانية إلى الطلب من الملك عبدالعزيز إرسال وفد إلى لندن فكلف ابنه فيصل البالغ من العمر 14 سنة للقيام بهذه الزيارة نيابة عنه وأرسل معه وفدا ضم مستشاره للشؤون الخارجية أحمد بن ثنيان ولحق بهم فيلبي سكرتير برسي كوكس المعتمد البريطاني في الخليج ليكون وسيطا بين حكومته والوفد، وقد حضر فيصل والوفد المرافق له احتفالات انتصارات بريطانيا في الحرب العظمى ثم قام بجولة على مشاهد آثار المعارك والخراب من جراء الحرب العالمية ووقف على معالم الحضارة الغربية والتطور العسكري ثم زار فرنسا وإيرلندا وويلز، وعاد من رحلته بعد ستة أشهر."},{"id":4907,"title":"معاهدة سيفر  .","date":["العام الهجري :1338","العام الميلادي :1919"],"text":"بعد أن سيطر الحلفاء على استانبول وألقِيَ القبضُ على رئيس الوزراء، وحُلَّت جمعيةُ الاتحاد والترقي، واغتيلَ أكثَرُ أعضائها، وأُقيل مصطفى كمال من منصبِه، وأعلنت الحكومة تمرُّدَ مصطفى كمال الذي ظهر بمظهرِ البطل الثائر حتى لقَّب نفسه بالغازي، فتقدَّم إلى الغرب من الأناضول، وحاصر أسكي شهر فانسحب الإنجليزُ منها دون مقاومة، فدخلها بصورة الفاتح ودخل قونية، وأعلن إجراءَ انتخابات جديدة بحيث تكون أنقرة مقرًّا للمجلس الجديد، فنجح أنصاره، واجتمع المجلس وبدأ يعمل على تشكيل جيشٍ خاصٍّ، أما الحكومة فسيطرت على كافةِ المناطق وبَقِيَت أنقرة وحدها، وكادت تسقط، فأذاع الحلفاء في هذا الوقت شروطَ معاهدة سيفر التي وافق عليها الخليفةُ ورئيس الوزراء الداماد فريد باشا مرغَمَينِ، ولما فيها من إجحافٍ بحقِّ الدولة المهزومة فقد ثار الأهالي؛ إذ تنص المعاهدة على: إقامة دولة في استانبول، آخر الولايات العربية من الدولة، إعطاءُ الاستقلال لأرمينيا، إعطاء كردستان استقلالًا ذاتيًّا، تُعطى تراقيا وجزر بحر إيجة لليونان، توضع المضائق تحت إشراف دولي، يوجِّهُ الحلفاءُ الجيشَ ويحدَّدُ عدد أفراده، يحِقُّ للحلفاء السيطرة على المالية، فبدأت ثورة الأهالي على الحكومة لتوقيعها المعاهدة، وبدأ مصطفى كمال الهجومَ على الحكومة الذي أعلن أنها عميلة، وبدأت كِفَّتُه ترجح، ودعت إنجلترا لعقد مؤتمر في لندن لإعادة النظر في معاهدة سيفر، ثم قوِيَ أمر مصطفى كمال، واتفق مع الدول الأخرى؛ إذ اتفق مع اليونان على إعطاء أزمير استقلالًا ذاتيًّا تحت حكم نصراني، وتنازل لروسيا عن باطوم في جورجيا، وانسحبت فرنسا من كيليكيا جنوب الأناضول بتركيا، وانسحبت إيطاليا من أنطاكية، واستطاع أن يهزم اليونانَ واضطرَّهم للانسحاب من تركيا، فظهر مصطفى كمال بصورة البطل المغوار!!!"},{"id":4908,"title":"مؤتمر مدينة غريان لتوحيد الجهاد الليبي ضد الطليان .","date":["العام الهجري :1338","العام الميلادي :1919"],"text":"عندما بدأ الاحتلالُ الإيطالي لليبيا وتخلَّت عنهم الدولة العثمانية، بقي المجاهدون وحدهم في ميدان القتال، فالتقَوا في عدة معارك مع الطليان، وكان الليبيون قد دحروا القواتِ الإيطاليةَ حتى حاولوا الهجومَ على الإنجليز بمصرَ، لكنهم فشلوا، وتنازل أحمد شريف عن زعامة الحركة السنوسية لابن عمه محمد إدريس، الذي هزم الطليان في عدة معارك، واضطروا إلى إبرام اتفاقيةٍ معه اعترفوا له فيها بنفوذه على المناطق، وتعهَّدوا بإبقاء المحاكم الشرعية والعناية بالقرآنِ، وعدم التعرض للزوايا السنوسية، والسماح بالمبادلات التجارية، ثم عُقِد مؤتمر في مدينة غريان ضمَّ ممثِّلين عن جميع أبناء البلاد عدا البربر، واتفقوا على توحيد الجهاد، فخاف الطليان من نتائج هذا المؤتمر، فاضطروا للاعتراف بمحمد إدريس السنوسي أميرًا على المناطق الداخلية؛ حرصًا منهم على كسب الوقت للاستعداد وحشد القوات، فعقد الليبيون مؤتمرًا آخر في العام التالي في سِرْت حضره ممثِّلون عن السنوسيين وعن طرابلس، وتمت البيعة فيه لمحمد إدريس السنوسي، وعاد القتال ولم يستطع المجاهدون مقاومةَ الحشود الجرَّارة، فاحتل الطليان طرابلس وقضوا على جمهورية ليبيا الأولى عام 1342هـ / 1923م أما برقة فكانت قيادتها تحت عمر المختار الذي أحرز كثيرًا من الانتصاراتِ في الجبل الأخضر الذي احتله الطليان أخيرًا."},{"id":4909,"title":"ضم الملك عبدالعزيز مدينة عسير لحكمه .","date":["العام الهجري :1338","العام الميلادي :1919"],"text":"عندما اندلعت الحرب العظمى انسحب الأتراك من عسيرٍ، أصبح الأمير حسن آل عائض حاكمًا لعسير، لكِنَّ قبائل قحطان وزهران نفرت منه بسبب استبداده، فأرسلوا إلى الملك عبدالعزيز يستعينون به عليه، فأرسل لهم علماء يعلِّمون الناس العلم وينشرون التوحيد، لكنَّ ابن عائض لم يحسِنْ استقبالهم واستمَرَّ في سياسته، فأرسل الملك عبدالعزيز حملةً بقيادة ابن عمه عبد العزيز بن مساعد بن جلوي أمير حائل ومعه قحطان وزهران، فهزموا ابن عائض وابن عمه محمد آل عائض في معركة حجلا؛ فأُسِرَا وأرسلا إلى الرياض، ثم أفرج عنهما وعادا إلى عسير كعمَّال للملك عبدالعزيز."},{"id":4910,"title":"دخول فرنسا موريتانيا .","date":["العام الهجري :1338","العام الميلادي :1919"],"text":"كانت موريتانيا محلَّ أطماع الأوروبيين منذ القرن الخامس عشر الميلادي؛ حيث وصلها البرتغال والهولنديون، وأقاموا مراكز تجارية علي سواحلها بغيةَ الحصول علي الصمغ العربي الذي اشتهرت موريتانيا بإنتاجه، وفي القرن (17م) دخل الفرنسيون والإسبان والإنجليز هذا الصراع، فكانت معاركُ وصدامات بين الأوروبيين من أجل السيطرة علي تجارة الصمغ العربي، وقد أطلق على تلك الحروب اسم حروب الصمغ العربي، التي انتهت بسيطرة الفرنسيين على موريتانيا. بعد الحرب العالمية الأولى شعر الفرنسيون أن الوضعَ قد استقَرَّ لهم فعدُّوا موريتانيا جزءًا من إفريقيا الغربية الفرنسية وأصبحت تحت حمايتها."},{"id":4911,"title":"ثورة إبراهيم هنانو ضد الاحتلال الفرنسي في سوريا .","date":["العام الهجري :1338","الشهر القمري : محرم","العام الميلادي :1919"],"text":"في عام 1919م اتَّفق عددٌ من الوطنيين السوريين على اختيار إبراهيم هنانو لتأليف قواتٍ من المجاهدين، تمكَّنَت من احتلال مدينة أنطاكية، وكان أولُ صدام مسلح بين قوات هنانو والفرنسيين في أكتوبر، ثم قامت بعضُ القوات التابعة لهنانو بالهجومِ على الفرنسين والانتصار عليه، فذاع صيتُه وكثُر مؤيدوه، وبعد توقيع الأمير فيصل بن الحسين على معاهدة الانتداب عام 1920م أصبح وضعُ هنانو صعبًا؛ لحاجته للسلاح، فحصل عليه من تركيا، فواصل في هجومه على الفرنسيين حتى كبَّدهم خسائِرَ فادحةً، واستطاع أسْرَ جنود فرنسيين, واستردادَ مناطِقَ واسعة من الفرنسيين. ولَمَّا دخل الفرنسيون دمشقَ ثمَّ حلب؛ لقَمعِ ثورته، أعلن هنانو دولةَ حلب بإدارته، فبدأت مفاوضاتٌ بينه وبين الفرنسيين. تعرَّض هنانو لكمين قُربَ جبل الشعر بالقرب من حماة يوليو 1921م حيث فقَدَ مُعظَمَ قوَّاته. ونجا هو بنفسه، ثم تمكَّن الفرنسيون من القبضِ عليه وتقديمه إلى محكمةٍ عسكريةٍ فرنسيةٍ بتهمةِ الإخلالِ بالأمنِ والقيام بأعمالٍ إجرامية، فحُكِمَ عليه بالقتل، لكِنَّ القاضيَ الفرنسيَّ أطلق سراحَ هنانو مُعتبرًا ثورتَه ثورةً سياسيةً مشروعة، معلنًا استقلاليَّةَ السلطة القضائية الفرنسية عن السُّلطةِ العسكرية!!"},{"id":4912,"title":"اعتراف بلجيكا بالإسلام كدين رسمي .","date":["العام الهجري :1338","الشهر القمري : ربيع الأول","العام الميلادي :1919"],"text":"اعترفت دولة بلجيكا بالإسلام كدينٍ رسمي، وفي عام 1998م بعد ربع قرن على هذا الاعتراف حقَّق المسلمون نجاحًا آخر عندما خاضوا انتخاباتٍ على مستوى الأقلية لاختيار هيئة موحَّدة تمثِّلُهم لدى الحكومة، وتكون بمثابة المُحاوِرِ الرسمي للسلطات البلجيكية في شؤون المسلمين."},{"id":4913,"title":"قيام منظمة عصبة الأمم رسميًّا .","date":["العام الهجري :1338","الشهر القمري : ربيع الآخر","العام الميلادي :1920"],"text":"عُصبةُ الأمم منظَّمةٌ دولية تمَّ تأسيسُها بعد الحرب العظمى (العالمية الأولى) والهدف من إنشائها -كما يزعمون- هو التقليل من عملية التسلح العالميَّة، وفكُّ النزاعات قبل أن تتطور لتصبِحَ نزاعًا مسلَّحًا، كما حدث في الحرب العالمية الأولى. وأثبتت المؤسَّسةُ فشلها في مواجهة القوى الفاشية في العالم، وفشَلَها في منع وقوع الحرب العالمية الثانية؛ مما تطلَّب أن يُستبدَلَ بها هيئةُ الأمم المتحدة بعد الحرب العالمية الثانية. نشأت فكرةُ عصبة الأمم أساسًا على يد وزير الخارجية البريطاني \"إدوارد جراي\" وتبنَّاها بشكل كبير الرئيس الأمريكي \"وودرو وِيلْسون\" الذي أراد أن يرى معاهدة فرساي تتضمَّن نصًّا يدعو لإنشاء هذه المؤسسة الأممية، وقد تم بالفعل إدراجُ نص التأسيس في 25 يناير 1919 من الجزء الأول من المعاهدة. وكان \"إنشاء منظمة عامة للأمم ذات مواثيق توفِّر ضماناتٍ متبادلة للاستقلال السياسي واحترام وحدة تراب الأمم الكبيرة والصغيرة على حدٍّ سواء\"، وهي إحدى النقاط الأربعة عشرة للسلام لوودرو ويلسون. عقدت عصبة الأمم أولَ اجتماعاتها في 10 يناير 1920 وغيَّرت من معاهدة فرساي لتصبح النهايةَ الرسمية للحرب العالمية الأولى. وبالرغم من تأييد الرئيس ويلسون لفكرة عصبة الأمم إلا أن الولايات المتحدة، بقيادة الكونجرس الجمهوري، رفضت التصديقَ على ميثاق العصبة أو الانضمام لها؛ فقد رأت الولايات المتحدة أنَّ في النظام التأسيسي لعصبة الأمم محاولةً من الدول الأوروبية الاستعمارية الكبرى للاستئثارِ بغنائم الحرب العالمية الأولى. وتجدرُ الإشارة إلى أنَّ العُصبةَ كانت قد تمكَّنت من حلِّ النزاعات الثانوية العالمية في عشرينيات القرن العشرين، ولكنَّها وقفت عاجزةً عن كوارث ثلاثينيات القرن أو الحرب العالمية الثانية؛ مما استدعى تفكيك المؤسسة من تلقاء نفسها عشيَّةَ الحرب العالمية الثانية في 18 إبريل 1946م والاستعاضة عنها لاحقًا بمنظمة الأمم المتحدة. وكان للعصبة مجلس يتكوَّنُ من 4 مقاعد دائمة لبريطانيا، إيطاليا، فرنسا، واليابان، بالإضافة إلى مقاعد أخرى غير دائمة، وكانت الاجتماعات تُمثَّل بمندوبين عن دول العصبة. وتمثَّل الإشكال في التصويت على القرارات بشكل جماعي، الأمر الذي لم يكن واردًا على أرض الواقع، ناهيك عن عدم اكتمال النصاب من قِبَل الدول الأعضاء بعدم التمثيل الدائمِ في جنيف مقَرِّ العصبة، بالإضافة إلى انشغال العصبة في أمور دولية أخرى، كالمحكمة الدولية."},{"id":4914,"title":"وفاة الأمير سعود بن عبد العزيز بن متعب الرشيد أمير حائل .","date":["العام الهجري :1338","الشهر القمري : جمادى الآخرة","العام الميلادي :1920"],"text":"هو الأمير سعود بن عبد العزيز بن متعب بن عبد الله بن علي بن رشيد من فخذ آل جعفر من عبده من قبيلة شمر، عاشر حكام إمارة جبل شمر في حائل، خلال الفترة من 1908 إلى 1920م. ولِدَ بحائل عام 1898م تولى سعود حكم حائل وعمُرُه 11 سنة تحت وصاية خاله الأمير حمود بن سبهان السبهان الذي مارس دور الحاكم الفعلي للإمارة إلى أن تولَّى الأمير سعود آل عبد العزيز الحكم رسميًّا في حائل 1914م وفي عام 1915 خاض معركة جراب ضِدَّ الملك عبدالعزيز وانتصر فيها. لقي سعود مصرعه على يد ابن عمه عبد الله بن طلال، ثم تولى بعده حكم حائل عبد الله بن متعب بن عبد العزيز."},{"id":4915,"title":"دخول قوات التحالف عاصمة الخلافة العثمانية بعد الحرب العالمية الأولى .","date":["العام الهجري :1338","الشهر القمري : جمادى الآخرة","العام الميلادي :1920"],"text":"احتَلَّ الحلفاءُ استانبول بالكامل، وكانت القواتُ الإنجليزية فقط هي التي احتلَّتْها، وأظهر الإنجليزُ عداءً ظاهريًّا لمصطفى كمال حتى يصنعوا منه بطلًا؛ فبعد سقوط الحكومة التي شُكِّلَت في ظل الاحتلال جرت انتخاباتٌ ونجح مصطفى (أتاتورك) عن أنقرة، فجمع النواب فيها، وشكَّل حكومةً برئاسته، وأظهر التدينَ والتمسُّكَ بالإسلام!!"},{"id":4916,"title":"قيام ثورة العشرين في فلسطين .","date":["العام الهجري :1338","الشهر القمري : رجب","العام الميلادي :1920"],"text":"اندلعت ثورة 1920 في فلسطين احتجاجًا على وعد بلفور، وبدأت أحداثها في القدس، ثم امتدت إلى مختلف المدن الفلسطينية؛ فقد سارت جموعٌ حاشدة في مظاهرات صاخبة طافت شوارعَ القدس، وهي رافعة صورة فيصل بن الحسين بصفته ملكًا لسوريا وفلسطين. وحينما وصلت المظاهرة باب يافا في القدس وقع انفجارٌ قوي تبعه قذفُ الحوانيت اليهودية بالحجارة، واشتبك المتظاهرون مع اليهود، ثم مع الإنجليز الذين هُرعوا لحمايتهم. وكانت تلك الأحداثُ بداية الهبَّة الشعبية التي استمرت أسبوعًا لم تستطع السلطاتُ البريطانية إخمادَها رغم إعلان الأحكام العُرفية، وبلغت حصيلةُ القتلى والجرحى من الفلسطينيين تسعة قتلى و251 جريحًا. وتعتبر ثورة 1920 بدايةَ الانتفاضات الشعبية الكبرى على الوجود البريطاني والتغلغل الصهيوني منذ العشرينات من القرن العشرين، وللتعبير عن شعورهم بخيبة آمالهم وإحباط مطالبِهم التي وعدهم بها الحُلَفاءُ مقابِلَ الثورة ضد الدولة العثمانية!!"},{"id":4917,"title":"ضعف دعم الإنجليز للشريف حسين وأثره على استقرار الأوضاع في الحجاز .","date":["العام الهجري :1338","الشهر القمري : رجب","العام الميلادي :1920"],"text":"تغيَّرت سياسةُ الحكومة البريطانية في حَجمِ دَعمِها للشريف حسين بعد نهاية الحرب العظمى، فأصبح الدعمُ مرهونًا بالمحافظة على ميزان القوى داخل الجزيرة العربية، والتي يمثِّلُ الشريف حسين أحد أطرافها في الحجاز، مع أطراف أخرى منهم الملك عبدالعزيز في نجد، وابن رشيد في حائل، وغيرهم. ففي هذا العام حدثت أزمةٌ مالية للشريف حسين عندما قلَّصت بريطانيا دعْمَها الماديَّ الذي كان قد بلغ وقت الحرب ما يزيد على 200 ألف جنيه استرليني إلى 27 ألف جنية هذا العام، فأدَّى هذا إلى تدهور الوضع الاقتصادي في الحجاز؛ لذلك أخذ الشريف يبحث عن مواردَ مالية، مثل: فرض الضرائب على التجار والأهالي، وقطع المعونة التي كان يقدِّمُها للقبائل البدوية الخاضعة لسلطانه، فأثار هذا حالةً من عدم الاستقرار والفوضى في الحجاز، وأخذت القبائل تقطع الطرقَ على قوافل الحجِّ والتجَّار وتقوم بالسلب والنهب؛ مما أدى إلى ضعف سلطان الشريف حسين على الحجاز!"},{"id":4918,"title":"انعقاد المؤتمر السوري .","date":["العام الهجري :1338","الشهر القمري : رجب","العام الميلادي :1920"],"text":"انعقد المؤتمر السوري واتخذ عدةَ قراراتٍ تاريخية تنصُّ على إعلان استقلال سوريا بحدودها الطبيعية استقلالًا تامًّا بما فيها فلسطين، ورفْض ادِّعاء الصهاينة في إنشاء وطن قومي لليهود في فلسطين، وإنشاء حكومةٍ مسؤولة أمام المؤتمر السوري الذي هو مجلس نيابي، وكان يضم ممثِّلين انتخبهم الشعب في سوريا ولبنان وفلسطين. وتنصيب الأمير فيصل حسين ملكًا على سوريا الكبرى، فاستقبلت الجماهيرُ المحتشدة في ساحة الشهداء هذه القراراتِ بكل حماس بالغ وفرحةٍ طاغية باعتبارها محقِّقةً لآمالهم ونضالِهم من أجل التحرر والاستقلال. وتمَّ تشكيلُ الحكومة برئاسة رضا باشا الركابي، وضَمَّت سبعةً من الوزراء، من بينهم فارس الخوري، وساطع الحصري -فيلسوف القومية العربية ومنظِّرها- ولم يَعُد فيصل في هذا العهد الجديد المسؤولَ الأول عن السياسة، بل أصبح ذلك منوطًا بوزارة مسؤولة أمام المؤتمر السوري، وتشكَّلت لجنة لوضع الدستور برئاسة هاشم الأتاسي، فوضعت مشروعَ دستور من 148 مادة على غرار الدساتير العربية. لم يلقَ هذا استحسانَ وقبول الحلفاء، ورفضت الحكومتان: البريطانية والفرنسية قراراتِ المؤتمر في دمشق، واعتبرت فيصل أميرًا هاشميًّا لا يزال يدير البلاد بصفته قائدًا لجيوش الحلفاء في الشام، لا ملكًا على دولة. ودعته إلى السفر إلى أوروبا لعرض قضية بلاده؛ لأن تقريرَ مصير الأجزاء العربية لا يزال بيد مؤتمر السلم المنعقد في \"سان ريمو\" الإيطالية، والذي جاءت قراراته مخيِّبةً لآمال العرب."},{"id":4919,"title":"إعلان بريطانيا الانتداب على العراق وتهنيد العراق .","date":["العام الهجري :1338","الشهر القمري : شعبان","العام الميلادي :1920"],"text":"بعد اندلاع الحرب العالمية الأولى عام 1914 ودخول الدولة العثمانية في تحالفٍ إلى جانب ألمانيا ضِدَّ دول الحلفاء بزعامة بريطانيا وفرنسا وروسيا القيصرية، أدى ذلك إلى قطع خطوط المواصلات الاستراتيجية لبريطانيا مع مستعمراتها؛ مما أدى بالتالي إلى انقطاع شريانِ الإمدادات الحيوي للحرب والحياة العامة البريطانية. فقامت بريطانيا باعتمادِ خطةٍ سريعة، كان من بين أهدافها احتلالُ العراق، في الوقت الذي كان الجهدُ العسكري في المواجهات مع ألمانيا وحلفائها منصَبًّا على الجبهات الرئيسية في قلب أوروبا، وبعد تمكن القطاعات البريطانية التابعة لحكومة الهند الشرقية البريطانية من احتلال العراق بصعوبةٍ بسبب الهجمات العثمانية المضادَّة مع المتطوعين، وبعد إتمام احتلال العراق وُضِع تحت انتداب عصبة الأمم،وتحت الإدارة البريطانية، وذلك عام 1918. وبعد بسط النفوذ البريطاني على مجمَل الأراضي العراقية عزمت بريطانيا على تأسيسِ بعض الدوائر والمؤسَّسات المدنية لتسهيل هيمنَتِها على العراق. وبعد انتهاء الأعمال الحربية ناقشت عصبةُ الأمم موضوعَ انتدابها للعراق؛ حيث قررت أن يكون منتدبًا من قِبَل عصبة الأمم وأن تديره المملكة المتحدة مباشرةً، وليست حكومة الهند الشرقية، إلا أن بريطانيا أوكلت لقادتها الميدانيين من جيشِ حكومة الهند البريطانية بتشكيل الإدارة المدنية تحت الإدارة الظاهرية للمملكة المتحدة. وقد ترأَّسها السير برسي كوكس حتى مايو/ أيار عام 1918 فتبعه السير أرنولد وِلْسون، الذي ألغى العديدَ من المؤسسات الإدارية العثمانية، وأنشأ محَلَّها مؤسسات عسكرية خُصِّصَت لإدارة الشؤون المدنية، ووضع على رأسها ضباطًا من رتب عالية لإدارتها بشكلٍ إداري صارم. وقد جلبت الإدارة المدنية عددًا كبيرًا من الكَتَبة والإداريين وأرباب الأعمال الصغيرة من الهنودِ مع عوائلهم إضافةً إلى الأعداد الغفيرة للجنود في جيش الليفي، الذين جلب قسم منهم عوائلهم معه. حيث مارست الحكومةُ المؤقتة البريطانية – الهندية سياسةَ التهنيد من خلال فرض القانون الهندي لحين صياغةِ الدستور العراقي عام 1925؛ بغيةَ إلحاق العراق وضمِّه بالتاج البريطاني. وبعد خسارة بريطانيا حربَها في العراق على أعقاب ثورة العشرين انسحبت تلك القوات تاركةً خلفها تلك الأعداد من الهنود التي بقيت في العراق وذابت مع المجتمع العراقي على مرِّ الزمن. واجه العراقيون العربُ في الوسط والجنوب، والأكرادُ في الشمال بضراوةٍ الاحتلالَ البريطانيَّ وسياساتِ التهنيد وغير ذلك."},{"id":4920,"title":"انعقاد مؤتمر سان ريمو بعد انتهاء الحرب العالمية الأولى .","date":["العام الهجري :1338","الشهر القمري : شعبان","العام الميلادي :1920"],"text":"نتيجةً لموقف إنجلترا وفرنسا من مقرَّرات المؤتمر السوري الذي انعقد في مارس تمَّ عقدُ مؤتمر سان ريمو الذي حُدِّدت فيه مناطق النفوذ البريطانية والفرنسية في المشرق العربي، فانعقد المجلس الأعلى للحلفاء، الذي يعتبَرُ امتدادًا لمؤتمر لندن المنعقد في (فبراير) 1920 في مدينة سان ريمو الإيطالية، في المدة ما بين التاسع عشر والخامس والعشرين من نيسان (أبريل) 1920؛ للبحث في شروط الحلفاء للصلحِ مع تركيا طبقًا لمعاهدة سيفر والمصادقة عليها، وذلك بعد إعلان المجتَمِعين في المؤتمر السوري -الذي عُقِدَ في مارس- استقلال سوريا ومناداتهم بفيصل ملكًا عليها. وقد قرر الحلفاء: استقلال سوريا تحت الانتدابِ الفرنسي. واستقلال العراق تحت الانتداب البريطاني. ووضع فلسطين تحت الانتداب البريطاني، وكان ذلك سعيًا لتحقيق وعد بلفور لليهود فيها. ولم يكن قرارُ الانتداب في سان ريمو إلَّا تطبيقًا لاتفاقية سايكس بيكو المشهورة، وإصرارًا قويًّا من فرنسا على احتلال سوريا. وكان قرار المؤتمر ضربةً شديدة لآمال الشعب في استقلال سوريا ووحدتها، فقامت المظاهراتُ والاحتجاجات، واشتعلت النفوسُ بالثورة، وأجمع الناسُ على رفض ما جاء بالمؤتمر من قرارات، وكثرت الاجتماعاتُ بين زعماء الأمة والملك فيصل، وأبلغوه تصميمَ الشعب على مقاومةِ كُلِّ اعتداء على حدود البلاد واستقلالها."},{"id":4921,"title":"صدور قرار بإنشاء المجمع العلمي العربي بدمشق .","date":["العام الهجري :1338","الشهر القمري : شوال","العام الميلادي :1920"],"text":"صدر قرارٌ بإنشاء المجمَع العِلميِّ العربي بدمشق، والذي عُرِفَ فيما بعد بـ \"مجمع اللغة العربية\". وقد نهض المجمَعُ بأمور اللغة في سوريا، وأحياها في دواوين الحكومة، وقام بجَمعِ الكتب والمخطوطات، وقد ضَمَّ المجمَعُ بين صفوفه عددًا من أعيان اللغة في العالم العربي. كانت الدولُ الاستعمارية منذ الوهلة التي يضعُ المستعمِرُ قدمَه في أي بلدٍ يستعمِرُه يبدأ بالتنقيب عن آثار البلد لربطِ سكانه بتاريخهم القومي بدَلَ دينِهم وعقيدتِهم التي يمكِنُ أن يكونَ لها أعظَمُ الأثر في مواجهة مخطَّطاته الاستعمارية؛ لذلك عمل الفرنسيون على تشجيع السوريين من خلال هذا المجمَعِ العلمي على الاهتمام باللغة العربية والآثار التاريخية؛ ففي مجال اللغة أخذ المجمَعُ على نفسه في إصلاحِ اللغة العربية، ووضْعِ ألفاظ للمستحدثات العصرية، وتنقيحِ الكتب، وإحياء المهمِّ مما خلَّفه الأسلاف منها، والتنشيط على التأليف والترجمة، وشراء الكتب، وجلْب كتب بلغة المستعمِر سواء كانت فرنسية أو إنجليزية أو ألمانية، وأما في مجال الآثار فلم تكن عنايةُ المجمع بجمع الآثار للمتحف بأقَلَّ من اهتمامه باللغة. فجمع أُلوفًا ما بين تماثيل حجرية وأوانٍ معدنية وزجاجية وخزفية، ومجاميع نقود ذهبية وفضية ونحاسية، وأسلحة وصفائح حجارة عليها كتابات، وأدواتٌ أخرى مختَلِفة. ومن هذه الآثار ما هو ذو شأنٍ عظيم قد لا يوجَدُ نظيره في كثيرٍ مِن المتاحف، وقد ألَّفَ المجمَعُ من أعضائه لجنتين: لجنة لُغَوية أدبية تبحَثُ في لغة العرب وآدابها وطرُقِ ترقيتها، ولجنة علمية فنية تبحث في توسيعِ دائرة العلوم والفنون في البلاد السورية. وألَّف أيضًا لجنة من المختصِّين في معرفة الآثار، ولجنتين أخيرتين، إحداهما لتتَبُّع الآثار القديمة والبحث عنها خارج دمشق من جهات سورية، وجلْب ما يمكِنُ جلبه منها، فذهبت إلى تدمر وجلبت منها ومن حمص بعضَ القِطَع الحجرية القديمة. وكتبت تقريرًا بشأن الآثار والملاحظات التي رأتها في رحلتها. أما اللجنة الأخرى فلتتبُّعِ الآثار القديمة في دمشق، وكتَبَ المجمَعُ منشورًا باللغتين العربية والفرنسية ضمَّنه ملخَّصًا من أخباره وأعماله في هذه المدة، ووزَّعه على المجامِعِ العلمية ودُورِ الكتب والجامعات وأمَّهات المجلات في أوروبا وأمريكا وغيرهما."},{"id":4922,"title":"ثورة العشرين في العراق ضد الاحتلال البريطاني .","date":["العام الهجري :1338","الشهر القمري : شوال","العام الميلادي :1920"],"text":"انتهت الحربُ العالمية الأولى ووُضِعَت العراق تحت الانتداب البريطاني، فأظهر الإنجليزُ الفساد من مجاهرة لشرب الخمور، وممارسة الزنا والاختلاط والسير في الطرقات بدون حشمة، بالإضافة لنظرة الاستعلاء بزعمهم أنَّهم جاؤوا ليرفعوا مستوى السكَّان والأخذ بأيديهم نحو الاستقلالِ، ولكن العراقيين (غير اليهود والنصارى الذين صاروا يصِرُّون على أن يبقوا تحت رعاية بريطانيا) كانوا ينظرون إلى الإنجليز نظرةَ ازدراء وكراهية ورغبة في الانتقام والثورة، فحدثت في بعض المناطق هنا وهناك عملياتٌ مثل ما حدث في النجف؛ حيث قُتِلَ مارشال قائد القوات الإنجليزية، وقُتِلَ في إقليم زاخو في الشمال النقيب بعسن الذي أراد رفع النصارى فوق المسلمين، وقُتِلَ الحاكم الإنجليزي في العمادية وتكَرَّرت مثل هذه العمليات، وخاصة بين العشائر، سواء في الشمال في منطقة الأكراد، أو في الجنوب في لواء المنتفق، حتى كانت بعضُ الاحتفالات يُلقى فيها الخطب الحماسية أو بعض الأشعار الحماسية التي تُشعِلُ نار الثورة فتتحَرَّك، وبقيت هكذا تغلي نفوس العراقيين حتى اندلعت ثورةُ العشرين حين اعتُقِل الشيخ شعلان أبو الجون شيخ قبائل بني حجيم، فهاجمت القبيلة مقرَّ الحاكم وخلَّصت الشيخ شعلان منهم، وكانت هذه الحادثة الشرارةَ لاندلاع الثورة العراقية. مرت الثورة في مراحل ثلاث: أولاها: تتمثل في الأحداث التي مهَّدت للثورة، وهي الأحداث التي جرت في بغداد وكربلاء ودير الزور وتلعفر والموصل، والثانية: تتمثل في الثورة المسلَّحة التي انطلقت في الرميثة في الثلاثين من حزيران 1920 ثم عمَّت منطقة الفرات الأوسط. أما الثالثة: فتتمثل في انتشار الثورة في مناطِقِ العراق الأخرى كديالي والغراف وغيرهما. وتعَدُّ الثورة في منطقة الفرات الأوسط بمثابة العمود الفقري لثورة العشرين كلها؛ ففي هذه المنطقة حصلت الانتصاراتُ الكبرى للثورة، كما أنَّ هذه المنطقة هي التي تحمَّلت العبءَ الأكبر من التضحيات في الأنفس والأموال، وصمدت للقتال فترة طويلة نسبيًّا نحو ثلاثة أشهر، وبعد أن عمَّت الثورة منطقةَ الفرات الأوسط أقام العراقيون سلطاتٍ محلية، ثم انتقلت إلى بعقوبة وديالي وأربيل وكركوك وخانقين، وقد تمكن الإنجليز من القضاء عليها بسهولة وفي خلال وقت قصير. هاجم رجال القبائل الكوفةَ واستولوا على قرية الكفل، وقتل الثوارُ مئةً وثمانين مستعمرًا وأسَروا مئة وستين، كما استولوا على عتادٍ حربيٍّ وذخيرة، وأغرقوا الباخرةَ فلاي في شطِّ الكوفة، كما سيطر رجالُ القبائل على المسيب وكربلاء والنجف وسدة الهندية، والجديرُ بالذِّكرِ أنَّ هذه الثورة التي عمَّت أرجاء القطر العراقي شارك فيها على السواء السُّنَّة والشيعة. أخذت النجدات الإنجليزية تصِلُ إلى العراق حتى وصل من القوات الغازية 133 ألف مقاتل، وبدأت تستعيد المدن شيئًا فشيئًا حتى أنهوا تلك الثورةَ، وبعد ثلاثة أشهر أعلِنَ العفوُ العامُّ."},{"id":4923,"title":"توقيع الدولة العثمانية معاهدة سيفر مع الحلفاء .","date":["العام الهجري :1338","الشهر القمري : ذي القعدة","العام الميلادي :1920"],"text":"وقَّعت الدولةُ العثمانية معاهدةَ سيفر مع الحلفاء بعد هزيمتها في الحربِ العالمية الأولى واحتلالِ معظَمِ أراضيها، في مدينة سيفر الفرنسية، وكانت هذه المعاهدةُ بمثابة المسمار الأخير في نعش الدولة العثمانية وتفكُّكِها ثم انهيارها؛ بسبب شروطها القاسية والمُجحِفة، والتي كانت بدافع النِّقمةِ مِن هزيمة الحُلَفاء في معركة غاليبولي، وضخامة الخسائر التي تكبَّدها الحلفاء على يد القوات العثمانية؛ فقد نصَّت المعاهدة على التالي: أن تكون سوريا وفلسطين وبلاد ما بين النهرين (العراق حاليًّا) دُولًا مستقلَّةً، تتولى الوصايةَ عليها القواتُ المنتدَبة من عُصبةِ الأمم. تَخلِّي الدولةِ العثمانية عن كلِّ سلطاتها الإقليمية في شمال إفريقيا. تخلِّي الدولة العثمانية عن تراقيا الشرقية لليونان، على أن تكون سميرنا (أزمير حاليًّا) والإقليم الأيوني تحت حكمِ اليونان لمدة خمس سنوات. الاعترافُ باستقلال أرمينيا، ويُضمُّ إليها جزءٌ كبير من شرق تركيا. منحُ حريةِ الملاحة في كلِّ المياه التي حول الدولة العثمانية لسفن جميع الدول. تقلُّصُ القوات التركية المسلَّحة إلى قوة شرطة فقط. هيَّأت معاهدةُ سيفر أن يكون الاقتصادُ التركي محكومًا من قِبَل لجنةٍ للحلفاء. وكان من النتائج المباشِرة لتلك الاتفاقية سقوطُ هيبة الدولة العثمانية، وكانت الضربةُ قبل الأخيرة في إلغائِها؛ حيث وقَّعت الحكومة العثمانية هذه المعاهدةَ، فكانت خسارة فادحة للاتحاديين الأتراك لذلك لم يُقِرُّوها، بينما كانت نصرًا لمصطفى كمال الذي أطاح بالحكومة العثمانية الضعيفة، وأقام كيانًا تركيًّا علمانيًّا مستقلًّا، عاصمته أنقرة."},{"id":4924,"title":"مفاوضات بين ملنر والوفد المصري بزعامة سعد زغلول .","date":["العام الهجري :1338","الشهر القمري : ذي القعدة","العام الميلادي :1920"],"text":"تقدَّم اللورد ملنر وزير المستعمرات الألماني إلى الوفدِ المصري بنصِّ مشروع معاهدة تتكوَّن من عدة مواد، ومنها: (المادة الأولى) تتعهد بريطانيا بضمان سلامة أرضِ مِصرَ واستقلالها كمملكةٍ ذات أنظمة دستورية. (المادة الثانية) تتعهَّدُ مصر من جانبها ألَّا تَعقِدَ أيَّ معاهدة سياسية مع أي دولة أخرى بدون رضا بريطانيا. (المادة الثالثة) نظرًا للمسؤولية الملقاة على عاتق بريطانيا بمقتضى الفقرة المتقدمة، ونظرًا لِما لها من المصلحة الخاصة في حفظ مواصلاتها مع ممتلكاتها في الشرق والشرق الأقصى، فمِصرُ تعطيها حقَّ إبقاء قوة عسكرية بالأراضي المصرية، وحقَّ استعمال الموانئ والمطارات المصرية لغَرَضِ التمكن من الدفاع عن القُطرِ المصري، ومن المحافظة على مواصلاتها مع أملاكها المذكورة، أما المكان أو الأمكنة التي تعسكِرُ فيها تلك الجنود البريطانية فإنها تعَيَّن بعد اتفاق الطرفين، إلى غير ذلك من المواد. كما أن الوفد المصري قدَّم مشروعَ معاهدة إلى لجنة اللورد ملنر، والتي تتكوَّنُ مواده من: (المادة الأولى) تعترف بريطانيا باستقلال مصر. وتنتهي الحماية التي أعلنتها بريطانيا على مصر في 18 ديسمبر سنة 1914 هي والاحتلال العسكري الإنجليزي، وبذلك تستردُّ مصرُ كامِلَ سيادتها الداخلية والخارجية، وتكونُ دولةً مَلَكيةً ذات نظام دستوري. (المادة الثانية) تُجلي بريطانيا جنودَها عن القطر المصري بدءًا من تاريخ العمل بهذه المعاهدة. (المادة الخامسة) في حالة إلغاء المحاكم القُنصلية وإحالة محاكمة الأجانب على ما يقع منهم من الجنايات والجُنَح إلى المحاكم المختلطة تَقبَل مصر أن تعَيِّن أحدَ رجال القانون من التبعية الإنجليزية في وظيفة النائبِ العمومي لدى المحاكمِ المختلطة."},{"id":4925,"title":"تعيين الحكومة البريطانية هربرت صموئيل الصهيوني مندوبًا ساميًا في فلسطين .","date":["العام الهجري :1338","الشهر القمري : ذي القعدة","العام الميلادي :1920"],"text":"قامت الحكومةُ البريطانية بتعيين هربرت صموئيل الصهيوني مندوبًا ساميًا لحكومة الانتداب البريطاني في فلسطين، وقد وضع الانتداب موضِعَ التنفيذ رسميًّا في 29 سبتمبر 1923م بعد أن وقَّعت تركيا على معاهدة لوزان."},{"id":4926,"title":"إعلان المؤتمر الوطني في تركيا \"الميثاق الوطني\" .","date":["العام الهجري :1338","الشهر القمري : ذي الحجة","العام الميلادي :1920"],"text":"أعلن المؤتمرُ الوطني في تركيا بعد الهزيمة في الحرب العالمية الأولى\"الميثاق الوطني\" الذي تضمَّن عِدَّةَ مبادئ تشمل: حقَّ تقرير المصير. تأمينَ القسطنطينية، فتحَ المضايق، حقوقَ الأقليَّات. إلغاءَ الامتيازات الأجنبية. وقد يلاحَظُ أنَّه يحتوي على الحد الأدنى من شروط السلام التي وافقت عليها تركيا في معاهدة السلام التي ستنتهي بها الحربُ العالمية الأولى. ومن بين القراراتِ التي خرجت من الاجتماع وخاصة اعتماد الميثاق الوطني \"التذكار الوطني\" الذي أعِدَّ مِن قِبَل مصطفي كمال أتاتورك مسبقًا في جلسة سرية بجهود مكثَّفة لنواب أعضاء جمعية قانون الدفاع في يناير 1920م، ثم أُعلِنَت الجمهورية في فبراير، وقد شكَّلت حدود تركيا وفقًا لمبادئ الميثاق الوطني إلى حدٍّ كبير."},{"id":4927,"title":"معاهدة الصداقة \"الأفغانية- السوفيتية الأولى\" .","date":["العام الهجري :1339","العام الميلادي :1920"],"text":"تم توقيعُ معاهدة الصداقة \"الأفغانية - السوفيتية الأولى\" وهي أول معاهدة تعقِدُها أفغانستان بعد إعلان استقلالها في عام 1919؛ حيث نصَّت المعاهدة على إعادة منطقة \"بنجده\" -وهي التي كان الروس قد استولوا عليها في عام 1885م- والاعتراف باستقلال الولايات الإسلامية (بخارى وكييف) وعدم الاعتداء بين الطرفين 25 سنة، الأمر الذي لم يفعَلْه الاتحاد السوفيتي حتى سقوطِه في عام 1991. وقد عقَدَ هذه المعاهدةَ الملكُ أمان الله الذي ضاعف حجمَ التبادُلِ التجاري السوفيتي الأفغاني 9 مرات."},{"id":4928,"title":"نشأة المجلس الإسلامي الأعلى الفلسطيني  .","date":["العام الهجري :1339","العام الميلادي :1920"],"text":"تأسَّس مجلس إسلامي فلسطيني عام 1922 لإدارة المحاكم الشرعية والأوقاف والشؤون الإسلامية، وقد تألَّف المجلس من مجموعة العلماء الذين رشَّحوا الحاج أمين الحسيني مفتي القدس رئيسًا لهذا المجلس الذي سُمِّي (المجلس الإسلامي الأعلى) الذي أصبح على مرِّ الأيام أقوى قوة وطنية فلسطينية إسلامية في البلاد، وقام بعددٍ من الأعمال والإنجازات الهامة؛ منها: إنشاء دار الأيتام الإسلامية الصناعية في القدس، وفَتْح عشرات المدارس في البلاد، وقام باسترجاع أراضي الوقف الإسلامي التي كانت حكومةُ الانتداب تسيطر عليها، وتولى إدارتَها، وأنشأ العشراتِ مِن المحاكم الشرعية، وعيَّن المئاتِ من الوعَّاظ والمرشدين، فضلًا عن إنشاء فِرَق الجوَّالة والكشَّافة الإسلامية والجمعيات الخيرية والنوادي الأدبية والرياضية، وإصلاح المسجد الأقصى المبارك ومسجد الصخرة، وإنقاذهما من الأخطار التي كانت تهدِّدُهما بالانهيار، وقد تمَّ ذلك بأموال الأوقاف وتبرُّعات المسلمين في شتى أنحاء العالم، وكان المجلِسُ يعقد مؤتمرًا سنويًّا من العلماء والدعاة؛ لتنظيم وسائل مقاومة بيع الأراضي لليهود، ويُصدِرُ فتاوى بتكفير من يبيع أرضه لهم، أو يقوم بعملية السمسرة لبيعِها. وقد ذكَرَت تقارير حكومة الانتداب السنوية إلى اللجنة الدائمة للانتدابات في عُصبة الأمم في جنيف أنَّ سبَبَ قلة انتقال الأراضي إلى اليهودِ هو المجلس الإسلامي الأعلى."},{"id":4929,"title":"تأسيس الجيش العراقي أثناء الانتداب البريطاني على العراق .","date":["العام الهجري :1339","العام الميلادي :1920"],"text":"تمَّ تأسيسُ الجيش العراقي تحت الانتدابِ البريطاني في العراق، وتكوَّن هذا الجيشُ من 1500 جندي، وكان الفريقُ جعفر العسكري أوَّلَ مَن تولى وزارة الدفاع العراقية، واستمرَّ هذا الجيشُ قائمًا حتى ألغاه الاحتلالُ الأمريكي في مايو 2003م."},{"id":4930,"title":"اتفاق الرجمة واعتراف الإيطاليين بحكم السنوسي في ليبيا .","date":["العام الهجري :1339","الشهر القمري : صفر","العام الميلادي :1920"],"text":"استمرَّت حركة المقاومة في ليبيا حتى نشوب الحرب العالمية الأولى سنة (1332هـ / 1914م)، ودخلت إيطاليا الحربَ إلى جانب الحلفاء، بينما كانت تركيا حليفًا لألمانيا، ومن ثمَّ فقد جاهرت تركيا بمساندتها وتأييدها للِّيبيين بقيادة أحمد السنوسي، ومناصرتهم في حربهم ضِدَّ عدوهم المشترك. ولكنْ ما لبثت العلاقاتُ أن تعقَّدت بين السنوسي والأتراك الذين نجحوا في الوقيعة بينه وبين الإنجليز فأغلقوا بدورهم طريق مصر في وجهه، وازداد الأمر حرجًا مع سوء الأحوال الاقتصادية وحدوث المجاعة التي أودت بحياة مئات الليبيين نتيجة انتشار الأمراض، وتفشِّي وباء الطاعون، الأمرُ الذي اضطر السنوسي إلى التفاوض مع القوتين المتحالفتين: إنجلترا وإيطاليا في (24 من جمادى الآخرة 1335هـ / 16 من إبريل 1917م). وقد أسفرت تلك المفاوضات عن اتفاق \"عكرمة\" الذي حدد مناطِقَ نفوذٍ لكلٍّ من السنوسيين والإيطاليين، كما نصَّ على إيقاف الحرب، وأتاح حريةَ التنقل بين كلتا المنطقتين. وتمَّ عقدُ اتفاق آخر بعد ذلك، عُرِفَ باتفاق \"الرجمة\"، تم بموجِبِه الاعتراف بالسنوسي حاكمًا مدنيًّا وزعيمًا للقسم الداخلي من برقة، ومُنِحَ لقب أمير، وأصبحت تلك المنطقة تخضع لنظامِ حُكمٍ وراثي ينحصر في السنوسي وأولاده من بعدِه."},{"id":4931,"title":"معركة الجهراء بين نجد والكويت  .","date":["العام الهجري :1339","الشهر القمري : صفر","العام الميلادي :1920"],"text":"حدثت أزمة حدودية بين نجد والكويت حول واحة البلبول جنوب الكويت والتي تبعد عن ميناء الجبيل عشرين ميلا عند ما بنى فيها سالم الصباح حاكم الكويت حصنا فاحتج الملك عبدالعزيز وكتب لابن الصباح يؤكد فيها أن البلبول ضمن أراضيه ويطلب منه وقف التوسع في بناء الحصون لكن ابن صباح رفض هذا التحذير فبنى الملك عبدالعزيز قرية بالقرب من البلبول وعلى الرغم من حدوث سلسلة من المراسلات والاتصالات التي توسطت بها بريطانيا بين الطرفين إلا أن المواجهة العسكرية قد حدثت بين الطرفين في الجهراء عندما هجم فيصل الدويش زعيم مطير وأحد قادة الإخوان (إخوان من أطاع الله) على الجهراء -قرية كبيرة في الكويت- ومعه أربعة آلاف مقاتل من الإخوان ووصل الدويش إلى الصبيحة شمالا وهجموا على قوات ابن الصباح الذين تقهقروا إلى القصر الأحمر، وقرر الإخوان الانسحاب والعودة إلى الصبيحة وعدم التوغل في الكويت، فطلب ابن الصباح نجدة السلطات البريطانية فوصلت طائرات بريطانية من العراق وحلقت فوق قوات الإخوان وألقت عليهم المنشورات تأمرهم بالتراجع عن الصبيحة فانسحب الدويش بقواته لما أدرك تصميم السلطات البريطانية على حماية الكويت، وأرسل برسي كوكس المعتمد البريطاني في الخليج إلى الملك عبدالعزيز يحتج على اعتداء الإخوان على الكويت وطلب منه أن يسحب قواته إلى أراضيه فوافق الملك عبدالعزيز وتعهد بعدم الهجوم على الكويت إذا ما كف سالم بابن الصباح عن التآمر على نجد والتعاون مع خصومه وخاصة ابن رشيد. ثم ارسل الملك عبدالعزيز إلى كوكس يؤكد له أنه لم يأمر الدويش بالهجوم على الجهراء وإنما تحشد سالم ابن الصباح قواته زاد من توتر الموقف ثم أغارت قوات ابن الصباح على أتباعه وسلبت الأموال والجمال وقتلت الرجال ثم عادت إلى الجهراء."},{"id":4932,"title":"المعارك بين الأتراك واليونان .","date":["العام الهجري :1339","الشهر القمري : ربيع الآخر","العام الميلادي :1921"],"text":"كانت لجنةُ الحلفاء العليا المجتَمِعة في باريس والمؤلَّفة من رؤساء وزارات كلٍّ من إنجلترا وفرنسا وإيطاليا واليونان والحكومة التركية أصدرت قرارًا يقضي بنزول الجيوشِ اليونانية في أزمير، وحذَّر القرارُ الدولةَ العثمانية من المقاومة، وأن أيَّ مقاومة تعني نقضَ الهدنة وعودة الحرب، وقد نزل اليونانيون فعلًا في اليوم الثاني من مطلع صيف 1338هـ، ثم دفعت إنجلترا باليونانيين فتقدَّموا من ناحية الغرب، وجرى القتال بين الأتراك واليونانيين؛ حيث شنَّ اليونانيون هجومَهم وأحرزوا نصرًا على الأتراك في معركة إينونو الأولى، ثم عاد اليونانيون في رجب / مارس، وكان مؤتمر لندن قائمًا، فسار اليونانيون نحو أسكي شهر وأفيون قره حصار لكنَّهم هُزِموا وارتدوا إلى بورصة، فصمموا على الهجوم على استانبول، لكن بريطانيا وقفت في وجههم، فانكفأ اليونانيون نحو الشرقِ فالتقوا بالقوات التركية، واستولوا على أفيون، ثم وصل مصطفى كمال إلى جبهة القتال الذي أمر القوات التركية بالانسحابِ، وفعلًا تم ذلك وتجمَّعت القوات في سقاريا، ورجع مصطفى إلى أسكي شهر على الجبهة الأولى، وكان اليونانيون قد وصلوا إلى غرب نهر سقاريا، وبدأ الهجوم اليوناني في شوال 1339هـ وتراجع الأتراكُ بفوضوية، وسدَّ الفدائيون الثغراتِ، ثم بدأ اليونانيون أيضًا بالانسحاب بعد أن رأوا عدمَ جدوى الهجوم الذي دام عشرةَ أيامٍ، وكانوا يحرقون القرى ويدمِّرون الآبار، ويسوقون المواشيَ، ويقتلون الأهاليَ، ثم عُقِدت الهدنة مع اليونان، وبرز مصطفى كمال يومَها بأنه استطاع إجبار اليونان من الانسحاب من تركيا عام 1340ه."},{"id":4933,"title":"محاولة الملك عبدالعزيز ضم حائل .","date":["العام الهجري :1339","الشهر القمري : ربيع الآخر","العام الميلادي :1921"],"text":"بعد مقتَلِ سعود بن عبد العزيز أمير حائل غزا الملك عبدالعزيز حائل، واستطاع أن يهزم شمر، ووصل إلى أسوارها، وقرر أميرُها الجديد عبد الله بن متعب أن يحتميَ بأسوار حائل المنيعة، ولما بدأت المؤَنُ تنفَدُ أرسل إلى الملك عبدالعزيز يعرِضُ عليه التفاوضَ، على أن تبقى إمارة جبل شمر على حائل، ولكنَّ الملك عبدالعزيز طلب منه الاستسلامَ بالكامِلِ، واستمرت المعركة عدة أشهر دون أن يتمكَّنَ من فتحِ حائل على الرغم من ظهور خلافٍ في حائل على حاكِمِهم، عندما خلعوا عبد الله بن متعب ونصَبوا محله محمد بن طلال، فاستجار عبد الله بن متعب بالملك عبدالعزيز."},{"id":4934,"title":"إفراج السلطات الفرنسية عن الزعيم التونسي عبد العزيز الثعالبي .","date":["العام الهجري :1339","الشهر القمري : شعبان","العام الميلادي :1921"],"text":"أفرجت السلطاتُ الفرنسيةُ عن الزعيم التونسي عبد العزيز الثعالبي بعد سجن استمرَّ 9 أشهر. وعبد العزيز الثعالبي زعيمٌ تونسي حاول التخلُّصَ من الاستعمار وظُلمِه، والرفعة بالمجتمع في الوقت ذاته. وقد تعرَّض الثعالبي للنفي والتَّرحال في سبيل دعوته ومبادئه. وقد تولى الثعالبي رئاسةَ الحزب الحر الدستوري التونسي الذي كان من أهدافِه: الفصلُ بين السلطات الثلاث. ضمانُ الحريات والمساواة. إجباريَّةُ التعليم."},{"id":4935,"title":"وضع فلسطين تحت الانتداب البريطاني بعد نهاية الحرب العالمية الأولى .","date":["العام الهجري :1339","الشهر القمري : شعبان","العام الميلادي :1921"],"text":"وُضِعَت فلسطين تحت الانتداب البريطاني بعد نهاية الحرب العالمية الأولى، وكلَّفَت بريطانيا الصهيونيَّ هربرت صموئيل كمندوب سامي لها في فلسطين، وقد مكَّن هذا الوضعُ من ازدياد الهجرة اليهودية إلى فلسطين في موجاتٍ متتابعة، والتمكين لهم، ثم انتهى الأمرُ بقرار الأمم المتحدة بتقسيم فلسطين سنة 1947م."},{"id":4936,"title":"معركة أنوال الشهيرة وانتصار الأمير المغربي محمد بن عبد الكريم الخطابي على الإسبان .","date":["العام الهجري :1339","الشهر القمري : شوال","العام الميلادي :1921"],"text":"كان الجنرالُ الإسباني سلفستر قائِدُ قطاع مليلة يزحَفُ نحو بلاد الريف؛ لِيُحكِمَ السيطرة عليها، ونجح في بادئ الأمر في الاستيلاء على بعض المناطق، وحاول الأميرُ محمد بن عبد الكريم الخطابي أن يُحَذِّرَ الجنرال سلفستر من مغبَّةِ الاستمرار في التقدُّمِ والدخول في مناطق لا تعترف بالحماية الإسبانية الأجنبية، لكنَّ الجنرال المغرور لم يأبهْ لكلام الأمير، واستمرَّ في التقدُّمِ ممنِّيًا نفسه باحتلال بلاد الريف، ولم تُصادِفْ هذه القواتُ في زحفها في بلاد الريف أيَّ مقاومة، واعتقد الجنرال أن الأمرَ سهلٌ، وأعماه غرورُه عن رجال الخطابي الذين يعملون على استدراجِ قوَّاتِه داخل المناطق الجبلية المرتفعة، واستمرَّت القوات الإسبانية في التقدُّمِ وتحقيق انتصارات صغيرة، حتى احتلَّت مدينة أنوال في رمضان، ثمَّ في شوال وقعت معركة أنوال الشهيرة التي سميت باسم المكان الذي جرت فيه، وهي قرية أنوال، وإن كانت أحداثُها قد شَمِلت عدةَ مواقع، بحيث عُدَّت من أكبر المعارك التاريخية التي جرت بين المغرب وإسبانيا، كمعركة الزلاقة أيام المرابطين، ومعركة الأرك في عهد الموحِّدين، وكان لها صدًى كبير في العالم الغربي؛ لأنَّها لقَّنت جنودَ الاحتلال الإسباني دروسًا لن تنسى. خاض المجاهِدون الريفيُّون المعركةَ بقيادة المجاهد الأمير المغربي محمد بن عبد الكريم الخطابي، وهم بضع مئات في كلِّ موقع، بحيث لم يكن يتعدَّى العددُ الإجمالي ثلاثة آلاف مقاتل، في حين كان عددُ جيش الاحتلال بقيادة الجنرال سلفستر ستين ألفَ جنديٍّ مدجَّجين بأحدث الأسلحة الفتَّاكة. واعتمد المجاهدون على الغنائِمِ التي ربحوها من المحتَلِّ، كالأسلحة المتنوِّعة والذخائر والمؤَن الكثيرة، إضافةً إلى نحو ألف أسير من مختلف الرُّتَب العسكرية، وتكبيدهم 15 ألف جندي ما بين قتيل وجريح و570 أسيرًا، وكان الجنرال سلفستر على رأس القتلى. ما إن انتشر خبَرُ انتصار الخطابي ورجاله في معركة أنوال، حتى هبَّت قبائِلُ الريف تُطارِدُ الإسبان أينما وُجدوا، ولم يمضِ أسبوعٌ إلَّا وقد انتصر الريفُ عليهم، وأصبح وجودُ الإسبان مقتصرًا على مدينة تطوان وبعض الحصون في منطقة الجبالة."},{"id":4937,"title":"معركة ميسلون واحتلال دمشق .","date":["العام الهجري :1339","الشهر القمري : ذي القعدة","العام الميلادي :1921"],"text":"كان غورو قد أرسل إلى المَلِك فيصل كتابًا يشيرُ فيه إلى استغرابه من بدءِ الفساد والتمرُّد منذ دخول جيوش فرنسا للمنطقة بعد رحيل إنجلترا، وذلك في تموز 1920م، ثم أرسل إليه إنذارًا أو بلاغًا يدور حولَ خمسِ نقاطٍ، أهمُّها: قَبولُ الانتداب الفرنسي، وإلغاءُ التجنيد الإجباري. رفَضَ وزيرُ الحربية يوسف العظمة قرارَ التسريحِ للجيشِ ولكنَّه اضطرَّ للتوقيع على القرار مُكرهًا بحضور الملك فيصل، وكتب الملك فيصل برقيةً لغورو بأنَّ مطالِبَه قُبِلَت، لكن غورو زعم أنَّ البرقية تأخَّرت وأنَّه أرسل جيشًا نحو دمشق واستطاع هذا الجيشُ أسْرَ فوجين من الجيشِ السوري بدون إطلاقِ رصاصة واحدة، وأراد الملِكُ أن يعود للدفاع لكِنَّ الجيش كان قد سُرِّح وخلت الكتائِبُ مِن معظم الجنود فذهب الوزير يوسف العظمة إلى ميسلون، وأخذ يُعِدُّ المعدَّاتِ مُنتظِرًا ما وعد به من النَّجدات، ولكن لم يَزِد عددُ الجنود مع المتطوِّعين على الأربعة آلاف، وكان القائم مقام \"جميل الألش\" -الذي كان على صلاتٍ جيِّدةٍ مع الفرنسيين- قد اطَّلع على الجيش في ميسلون، وقام بتعريف الجيش الفرنسي على مواضِعِ الضعف فيه، وكان الفَرقُ كبيرًا جدًّا في العَدَد والعُدَّة، وبدأت المعركة التي استُخدِمَت فيها الدَّبابات والطائرات، وقاتل العظمة ومَن معه ببسالةٍ، ولكن بوجود الخَوَنة حُسِمَت المعارك لصالحِ الفرنسيين؛ فقد قام رجلٌ درزي من المتطوِّعين مع بعضِ الفرسان بالوثوبِ على أحد المساير السورية من الخلف، وفتحوا النارَ عليها ونهبوا السلاحَ منهم، ورغم ذلك بقي العظمة يدير المعركةَ بإمكانيَّاتِه المتوفرة حتى قضى نحبَه بقذيفةِ إحدى الدبابات الفرنسية، وذلك في السابع من ذي القعدة 1339هـ / 24 يوليو. دامت المعركة ثماني ساعات انتهت بالقضاء على الجيش السوري المقاوِم، ودخولِ الجيش الفرنسي إلى دمشق بقيادة غوابييه، أما الملك فيصل وأعوانُه فقد كانوا خرجوا من دمشق إلى الكسوة (قريبًا من دمشق) ثم عادوا بعد دخول القوات الفرنسية إلى دمشق للتفاهمِ، إلَّا أن الفرنسيين رفضوا رفضًا باتًّا بقاء فيصل في البلاد، وأقلُّوه قطارًا خاصًّا هو وأعوانه، وتبعثر رجالُ الثورة العربية في مختَلِف الأقطار بعد أن عَرَفوا الفرق بين ما كانوا فيه وما أصبحوا فيه، أمَّا الفرنسيون فلم يُخفُوا أبدًا حِقدَهم الصليبي ولا أخفَوا أبدًا أنَّ حَربَهم هذه صليبيةٌ؛ فقد قال غورو أمام قبر صلاح الدين: ها قد عُدنا يا صلاحَ الدين! وقال: إنَّ حضوري هنا يقدِّسُ انتصارَ الصليبِ على الهلالِ."},{"id":4938,"title":"تتويج فيصل بن الحسين ملكًا على العراق مع توقيع صك الانتداب .","date":["العام الهجري :1339","الشهر القمري : ذي الحجة","العام الميلادي :1921"],"text":"كان فيصل بن الحسين ثالثُ الأبناء قد نُصبَ ملكًا على سوريا الجزءِ الأكبر من بلاد الشام، لكِنَّه لم يلبث أن طُرِدَ في العاشر من ذي القعدة 1338هـ / 25 تموز 1920م عندما دخل الفرنسيون إلى سوريا، وكانت إنجلترا بعد أن نكَثَت كلَّ العهود التي أعطتها للشريف حسين ظنَّت أنَّ فيصلًا أنسب أبنائه لحُكمِ العراق التي كانت تحت سيطرتها، فكتب وزيرُ الخارجية الإنجليزي كرزون إلى نائب الحاكِمِ الملكي في العراق يسألُه عن هذا الرأي، فرد النائب باقتراح أحدِ هؤلاء: هادي العمري، نقيب أشراف بغداد، عبد الرحمن الكيلاني، أحد أبناء الحسين بن علي، أحد أفراد الأسرة الخديوية في مصر. مع ترشيحِه هو لهادي العمري، كان تفضيل بريطانيا لفيصل ابن الشريف حسين ليكونَ ملكًا على العراق لعدَّةِ أسباب: منها تهدئة خواطر العرب الذين أُصيبوا بخيبةِ أملٍ بعد عزم دول الحُلَفاء بفرضِ سياسة الانتداب على البلاد العربية التي كانت تحت حُكمِ الدولة العثمانية، ووعد بلفور الذي يهدِّدُ مستقبل فلسطين، وكذلك اطمئنان الإنجليز من شِدَّةِ ولاء الشريف حسين وأبنائه للإنجليز واستعدادهم لتنفيذ سياساتها في المنطقة بكلِّ إخلاص. لذلك دعت الحكومةُ البريطانية فيصلًا لزيارة لندن، وقابل الملك جورج الخامس الذي عَرَض عليه مُلكَ العراق، لكن فيصل أبدى اعتراضًا، وهو أن أخاه عبد الله رشَّحه الشاميون لمُلك العراق، فقام لورنس بالتفاوض مع عبد الله على أن يكون هو ملكًا على شرق الأردن، ويترك مُلْك العراق لأخيه فيصل، فوافق، ثم قام برسي كوكس ممثِّل الحكومة البريطانية في العراق بتشكيل حكومةٍ وطنية، فكُوِّنت بمساعدة عبد الرحمن الكيلاني، وكُوِّن مجلس شورى، ثم قَبْلَ تنصيبِ الملك فيصل على العراق ساومه ونستون تشرشل على أن يكونَ بينهما معاهدة -يعني بين العراق وإنجلترا- تقوم مقامَ الانتداب وتؤدِّي غرضَه، يعني: في تحقيق مصالح إنجلترا في العراق، ثم ليبدوَ الأمر ليس مفروضًا على العراق؛ لأن المرشَّحين لمنصب الملك على العراق كُثُر، ومع أنه اقترح غير النظام المَلَكي، لكنَّ إنجلترا رأت أنَّ النظام الملكي حاليًّا أنسب لوضع العراق، ثم أخذت بإشاعةِ الخبر والدعاية لفيصل في العراق، ثم صرحت الحكومةُ البريطانية بموافقتها على ترشيحه، وبعد أن انتهت التمهيداتُ سافر فيصل إلى العراق على متنِ الباخرة البريطانية نورث بروك في ميناء البصرة في السابع عشر من شوال 1339هـ / 23 حزيران 1921م فاستُقبِلَ استقبالًا حارًّا، ثم سافر إلى بغداد، وكلما مرَّ على قرية عُمِلت له الاحتفالات، ووصل إلى بغداد في 23 شوال 1339هـ / 29 حزيران 1921م وبايعه مجلس الوزراء في الخامس من ذي القعدة من العام نفسه / 5 تموز، وأعدت وزارة الداخلية صورةً لمضبطه يُعلِنُ فيها الأهالي تأييدَهم، وتُوِّجَ مَلِكًا على العراق في يوم 18 ذي الحجة 1339هـ / 23 آب 1921م."},{"id":4939,"title":"مؤتمر الرياض الأول واتخاذ ابن سعود لقب سلطان نجد وملحقاتها  .","date":["العام الهجري :1339","الشهر القمري : ذي الحجة","العام الميلادي :1921"],"text":"عندما أنشأت بريطانيا عرشينِ ملكيَّينِ للهاشميين خصومِ الملك عبد العزيز، في العراق وشرق الأردن عام 1921م، غَضِبَ الملك من سياسة بريطانيا تجاهَه بعد أن أحاطوه بالأعداءِ، وأقاموا دويلاتٍ من حولِه ونَصَبوا من أعدائِه ملوكًا وقدَّموا لهم المساعداتِ المالية والسياسية، فدعا إلى عقد مؤتمر في الرياض حضره القادةُ العسكريون والشيوخُ والعلماء من نجدٍ وما حولها، وأُعلِنَ في هذا المؤتمر عن مبايعة الملك عبد العزيز ومَنحِه لقبَ سلطان نجد وملحقاتها، ثم أعلنت الحكومةُ البريطانية اعترافَها الرسميَّ بلقب ابن سعود الجديدِ سُلطانًا على نجد وملحقاتها هو وخلفائه من بعده."},{"id":4940,"title":"تتويج عبد الله بن الحسين ملكًا على شرق الأردن .","date":["العام الهجري :1340","العام الميلادي :1921"],"text":"ارتبط تأسيسُ إمارة شرقي الأردن بوصول الأمير عبد الله بن الحسين (الذي كان يشغَلُ منصب وزير خارجية الدولة العربية في الحجاز) إليها بناءً على الدعواتِ التي وُجِّهَت للشريف علي بن الحسين من قِبَل أعيان ووُجهاءِ مناطِقِ شرقي الأردن، وكذلك أعضاء حزب الاستقلال الذين جاؤوا للأردن من سوريا بعد معركة ميسلون 1920، وبعد طَردِ الملك فيصل من سوريا على يد الفرنسيين جاء أخوه عبد الله طالبًا للثأر، فلما وصل إلى مدينة معان في 21/11/1920 بعد رحلةٍ شاقة لمدة 27 يومًا مع حاشيته، و 500 من الحرس بالقطار، بدأ بدعوةِ أهالي شرق الأردن وحكوماتها المحليَّةِ للالتفافِ حولَه؛ مما حدا بالفرنسيين إلى اعتبار وصول الأمير عبد الله إلى شرق الأردن أمرًا خطيرًا يهدِّدُ وجودَها في سوريا؛ وذلك بسبب تصريح الأمير عبد الله أنه جاء لإحياء الثورة التي أُخمدت في حوران، وأنَّ قُدومَه للمشاركة في الدفاعِ عن أوطانهم، وأعلن نفسه وكيلًا للأمير فيصل. وخاطبت الحكومةُ الفرنسيةُ الحكومةَ البريطانية لممارسة ضغوطها على الملك حسين؛ لاتخاذ الخطوات الكفيلة بإيقافِ ابنه الأمير عبد الله واستعدادها للدخول إلى الأردن إذا اقتضى الأمرُ ذلك، وفعلًا قامت بريطانيا بالتوسُّط لدى الملك حسين لمنع الأمير عبد الله من القيام بأي شيء، مقابِلَ أن تحقِّقَ بريطانيا لأهالي شرقي الأردن حكمًا لأنفُسِهم تحت حكم الأمير عبد الله، وكانت بريطانيا لَمَّا عرضت على فيصل عرشَ العراق أبدى اعتراضًا أن أخاه عبد الله قد رشَّحه الشاميون لمُلْك العراق، فقام لورنس بالتفاوضِ مع عبد الله على أن يكونَ هو مَلِكًا على شرق الأردن ويترُكَ مُلك العراق لأخيه فيصل، فوافق؛ لذلك اجتمع عبد الله مع تشرشل في القدس في نيسان 1921م وعقد معه اتفاقًا لم يغِبْ عن الفرنسيين بأن تقوم في شرقي الأردن إمارةٌ ذاتُ حكومة تتمتَّعُ بالاستقلال الإداري، وتسترشد برأي المفَوَّض السامي الإنجليزي في القدس وتتقاضى من إنجلترا معونةً سنوية، ولكِنَّهم لم يعيِّنوا حدود الإمارة في صك الانتداب الذي وقَّع عليه عبد الله بن الحسين في هذه السنة، ولم يعترفوا بحدودِ إمارة شرق الأردن إلا في تصريحِ سنة 1923م."},{"id":4941,"title":"فرنسا تقسم سوريا الكبرى إلى عدة دويلات بعد أن فرضت عليها الانتداب  .","date":["العام الهجري :1340","العام الميلادي :1921"],"text":"استطاعت فرنسا أن تدخُلَ دِمشقَ بعد معركةٍ ميسلون، فقامت بتمزيق سوريا الكبرى واصطنعت بينها الحواجِزَ الجمركية والحدودَ المصطنعةَ، فأول ما قاموا به هو فصلُ لبنان عن سوريا باسم لبنان الكبير، وضمُّوا فيه جبل لبنان ومدن طرابلس وصيدا وصور بأقاليمها وأغلبيتها المسلمة، إضافة إلى بيروت وسهل البقاع وأغلَبُه أيضًا من المسلمين، وهذه أوَّلُ خطوة في محاباة فرنسا؛ حيث إن غورو كاثوليكي متعصِّبٌ، ثم قُسِّمت سوريا الباقية إلى دُوَل حلب ودمشق، ودولتي الدروز والعلويين، أمَّا فلسطين وشرق الأردن فلم يدخلا في تقسيم فرنسا؛ لأنَّهما كانا من نصيب الإنجليز حسب اتفاقية سايكس بيكو، وكان الفرنسيون قد ركَّزوا في سوريا على الأقليَّاتِ، مثل الدروز والعلويين؛ لعِلمِهم بجدوى مثل هؤلاء في تمزيق شَملِ المسلمين، وجعلت على كلٍّ مِن حلب ودمشق حاكمًا محليًّا يساعده عددٌ مِن المستشارين الفرنسيين، ثمَّ في عام 1922م أُعلِنَ جبلُ الدروز وحدةً مُستقلةً إداريًّا تحت الحماية الفرنسية، وعُيِّن سليم الأطرش الدرزي أوَّلَ حاكمٍ له، ثم أعلنت الدولة العلوية وجعلوا لها نظامًا إداريًّا خاصًّا أيضًا، وعُيِّن لها حاكمٌ فرنسي، وفي عام 1922م أيضًا أعلن غورو قيامَ اتحاد فيدرالي سوري يتضمَّنُ دويلات حلب ودمشق والعلويين، ثم حلُّوا هذا الاتحادَ في عام 1924م أيامَ المندوب فيجان، وحَلَّت محلَّه دولة سوريا التي تشمَلُ حلب ودمشق وسنجق الإسكندرون، واستبعدوا منها دولةَ العلويين، وأصبح التنظيمُ الجديد يطلَقُ عليه دولةُ سوريا."},{"id":4942,"title":"خلع السلطان محمد السادس نفسه وتنازله عن الخلافة وتولي عبد المجيد الثاني .","date":["العام الهجري :1340","العام الميلادي :1921"],"text":"بعد أن تسلم محمد السادس الخلافةَ بأشهر استسلمت الدولةُ في الحرب العالمية الأولى واحتَلَّ الحلفاء أكثَرَ أجزاء الدولة وسيطروا على استانبول والمضائق، واحتلت اليونانُ الأقسامَ الغربية وضاعت البلدانُ العربية، فوضع السلطانُ ثِقتَه بمصطفى كمال فخاب ظنُّه؛ لأنه أصبح يعمل لنفسِه، فلما وجد السلطانُ محمد ذلك اعتزل السلطةَ وتنازل عن الخلافة في هذا العامِ، وبعد أقل من أربع سنوات من توليه للحكمِ؛ حيث رفض أن يكونَ مَلِكًا رمزيًّا لا علاقةَ له بالحكم، فاعتزل ورحل إلى جزيرة مالطة ونودِيَ بابن عمه عبد المجيد الثاني بن عبد العزيز الذي أصبح الخليفةَ، والذي جُرِّد من السلطاتِ السياسية كافةً."},{"id":4943,"title":"مؤتمر لوزان يطالب بإلغاء الخلافة الإسلامية مقابل منح تركيا الاستقلال .","date":["العام الهجري :1340","العام الميلادي :1921"],"text":"بعد ثلاثةِ أيام من تسلُّم عبد المجيد الثاني الخلافةَ افتُتِحَ مؤتمر لوزان الذي حضره وفدُ أنقرة فقط، ووضَعَ رئيسُ الوفد الإنجليزي كرزون أربعةَ شُروطٍ للاعتراف باستقلال تركيا، وهي إلغاء الخلافة الإسلامية، وطردُ الخليفة من بني عثمان خارِجَ حدود تركيا، وإعلانُ علمانيةِ الدولة، ومصادرةُ أملاك وأموال بني عثمان، وربطُ نجاحِ المؤتمر على ذلك، فأخفق المؤتمَرُ، ورجع إلى البلاد الوفدُ التركي برئاسة عصمت إينونو"},{"id":4944,"title":"تأسيس جمهورية الريف وتدخل فرنسا وإسبانيا لحلها .","date":["العام الهجري :1340","الشهر القمري : محرم","العام الميلادي :1921"],"text":"تأسَّست في 18 سبتمبر 1921 عندما ثار سكان منطقة الريف (شمال المغرب) على إسبانيا، وأعلنوا استقلالَهم عن الحماية الإسبانية للمغرب. عاصمة الجمهورية كانت أجدير، وعملتها كانت الريفان، وقدر عدد سكانها بـ 18، 350 نسمة. وقد أُعلِنَ محمد بن عبد الكريم الخطابي أميرًا للريف. وتم تشكيلُ الجمهورية رسميًّا في 1 فبراير 1923. وكان الخطابي رئيسَ الدولة ورئيس الوزراء في البداية، ثم تمَّ تعيينُ الحاج الحاتمي كرئيس للوزراء من يوليو 1923 حتى 27 مايو 1926، ثم حُلَّت الجمهورية في 27 مايو 1926 بقوة فرنسيةٍ إسبانية تَعدادها 500.000 مقاتل، وباستخدام مكثف للأسلحة الكيماوية."},{"id":4945,"title":"قواعد فرنسية جديدة للجنسية التونسية .","date":["العام الهجري :1340","الشهر القمري : ربيع الأول","العام الميلادي :1921"],"text":"قامت فرنسا بتطبيقِ قواعِدَ جديدة للجنسية بتونس تجيزُ فيها سحْبَ الجنسية التونسية من بعضِ المواطنينَ."},{"id":4946,"title":"ضم الملك عبدالعزيز حائل إلى حكمه .","date":["العام الهجري :1340","الشهر القمري : ربيع الأول","العام الميلادي :1921"],"text":"بعد أن أعلنت بريطانيا تنصيبَ فيصل بن الحسين في العراقِ، وعبد الله بن الحسين في شرق الأردن، زادت مخاوفُ الملك عبدالعزيز من تحالفهما مع ابن رشيد؛ فقرَّر المسارعةَ لضَمِّ حائل، فعاد لغزوها بقواتٍ كبيرة من ضِمنِها قواتُ الإخوان  (إخوان من أطاع الله) بزعامة فيصل الدويش، وبعد شهرين من الحصار استسلمت المدينةُ للملك عبدالعزيز، وأسَرَ معه محمد بن طلال إلى الرياض، وتزوج الملك عبدالعزيز من ابنةِ محمد بن طلال."},{"id":4947,"title":"أزمة الحج بين الملك عبدالعزيز والشريف حسين .","date":["العام الهجري :1340","الشهر القمري : جمادى الأولى","العام الميلادي :1922"],"text":"على الرغمِ من انتهاء الأزمة بين الملك عبدالعزيز والشريف حسين، وتبادل الطرفين المبعوثين، والتأكيد على إحلال السلامِ بينهما، إلا أن الشريف حسين في هذا العام حدَّد عددَ حُجَّاج نجد، فاعترض الملك عبدالعزيز على هذا التحديدِ، ووجَّه خِطابًا إلى المعتَمد البريطاني في بغداد، فوجَّه الإنجليز خطابًا للشريف للدخولِ مع الملك عبدالعزيز في مباحثاتٍ لحَلِّ هذه المشكلة، فرفض الشريف وكتب للإنجليزِ بعدم استقباله لحجَّاج نجدٍ هذا العام إلَّا إذا تخلى الملك عبدالعزيز عن مناطِقِ الجوف، وبيشة، ورانية، وتربة، وخيبر، والمناطق الأخرى التي احتلَّها في السنوات الأخيرة، وأنَّه سيدخل معه في معاهدةٍ إذا وافق على الانسحابِ مِن هذه المناطق والعودة إلى حدود والِدِه السابقة في إمارة نجد، ورغمَ الضغوطِ البريطانية على الشريف من أجلِ تغيير موقِفِه والسماحِ للحُجَّاج النجديِّين بدخول مكة لأداء مَنسَكِ الحجِّ إلَّا أنه كان مصَمِّمًا على رأيِه، وفشلت بريطانيا في التوفيق بينهما، ولما أدرك ابنُ سعود عدَمَ جدوى الحلول السلمية والدبلوماسية مع الشريف حسين، قرَّر أن يصفي حساباتِه معه في ميادينِ القتالِ، وهذا ما أوضحه في رسالة إلى برسي كوكس المعتمد البريطاني في الخليجِ في نهاية عام 1923م بقوله: \"حَقَّ لي فيما أظنُّ أن اتَّبِع السياسة التي أريدُها، وأن أعملَ على تقرير مصيري بالطريقةِ التي أراها، وهذا ما أفعَلُه الآن\"."},{"id":4948,"title":"إلغاء الحماية البريطانية على مصر مع بقاء قوات الاحتلال  .","date":["العام الهجري :1340","الشهر القمري : جمادى الآخرة","العام الميلادي :1922"],"text":"دخلت مصر إلى القرن العشرين وهى مُثقلَةٌ بأعباء الاستعمار البريطاني بضغوطِه لنَهبِ ثرواتها، وتصاعدت المقاومةُ الشعبية والحركةُ الوطنية ضِدَّ الاحتلال بقيادة مصطفى كامل، ومحمد فريد، وظهر الشعورُ الوطني بقوة مع ثورة 1919 للمطالبة بالاستقلال، وكان لسعد زغلول ورفاقِه دورٌ بارز فيها بدعمٍ مِن الإنجليز للعمل من أجلِ إلغاء الحماية البريطانية على مصر في عام 1922 والاعتراف باستقلالِها على أيدي وطنيِّين تمَّ تهيئتُهم مِن قِبَل الإنجليز لضمان ولاء مصرَ لها. انتهت الحمايةُ البريطانية على مصر بإعلان الثامن والعشرين من شباط في العام 1922م، الذي اعترف بمصر كدولةٍ مستقلةٍ ذاتِ سيادةٍ بقيود محددة، وصدر أوَّلُ دستورٍ مصري في هذا العام، وفي الأول من آذار أصدر السلطان فؤاد مرسومًا بتشكيلِ حكومة جديدة، التي ضمَّت أوَّلَ وزارة خارجية مصرية بعد إعلانِ زوال الحماية البريطانية. وهناك يومٌ آخر يعَدُّ أحد المعالم الرئيسة في تاريخِ وزارة الخارجية المصرية، وهو الخامس عشر من آذار في العام 1923م؛ فهذا اليوم يرمُزُ إلى تغيير اللقب الرسمي لمصر لتصبِحَ مملكةَ مصر، كما تلقَّب السلطان فؤاد بلقَب الملك فؤاد، ويشيرُ أيضًا هذا اليوم إلى تطوُّر الدبلوماسية المصرية؛ فقد تمَّ تعيين وزير خارجية جديد، في حين أخذت الوزارةُ شَكلَها البنيويَّ، مع إعادة إرسال المبعوثين المصريين إلى الخارج. ومنذ ذلك الوقتِ قام العديدُ من الشخصيات المصرية بقيادةِ الدبلوماسية المصرية كوزراء للخارجية."},{"id":4949,"title":"إعادة النظر في بعض مواد معاهدة سيفر الظالمة .","date":["العام الهجري :1340","الشهر القمري : رجب","العام الميلادي :1922"],"text":"وافق الحُلفاءُ على إعادةِ النظر في بعضِ موادِّ معاهدةِ سيفر الظالِمة التي أُجبِرَت الدولةُ العثمانيةُ على قبولِها بعد هزيمتِها في الحرب العالمية الأولى، وحاول الحُلفاءُ الوصولَ إلى تسويةٍ للنزاع بين الأتراك واليونانيين، وقد رفض الأتراكُ الهدنةَ حتى يجلوَ اليونانيون عن الأناضول."},{"id":4950,"title":"غزو الإخوان  (إخوان من أطاع الله) حدود العراق .","date":["العام الهجري :1340","الشهر القمري : رجب","العام الميلادي :1922"],"text":"بعد أن استولى الملك عبدالعزيز على حائل واجه ثلاثَ قوًى محيطةٍ به ومعاديةٍ له في الشمال والغرب، ولم يتِمَّ ترسيمُ الحدود بين العراق وشرق الأردن وحائل ونجد، ولم تُحَلَّ الخلافات القبلية بين العراق ونجد، وفي عام 1921م تم تعيينُ يوسف بن سعدون قائدًا لقوات عراقية من الفرسان، وكان على عَداءٍ مع شيخ الظفير حمود بن سويط الذي هرب إلى الرياض، وطلب نجدةَ الملك عبدالعزيز، والتحقت بحمود مجموعةٌ من الإخوان من مطير برئاسة فيصل الدويش، وهاجموا معسكرَ يوسف وقتلوا غالبيةَ جنوده، فأرسلت بريطانيا طائراتٍ لنجدة العراقيين، وتم إقالةُ يوسف بن سعدون، فهرب يوسف إلى الرياض للعمَلِ تحت إمرة الملك عبدالعزيز."},{"id":4951,"title":"اتفاقية استقلال مصر المقيد بتحفظات بريطانية .","date":["العام الهجري :1340","الشهر القمري : رجب","العام الميلادي :1922"],"text":"بعد أن تألَّف الوفد المصري وسافر إلى باريس ولندن، ولم يُجدِ ذلك شيئًا حتى جرى اتِّفاقٌ بين المعتمد البريطاني في القاهرة وبين عبد الخالق ثروت، وعدلي يكن، وإسماعيل صدقي، في الرابع عشر من جمادى الأولى 1340هـ / 13 كانون الثاني 1922م، ونص الاتفاق على نقاطٍ، منها: أن تصبِحَ مِصرُ دولةً مستقلة لها سيادتها، ووافقت الحكومةُ البريطانية على اعتمادِ هذا الاتفاق، ولكن أدخَلت عليه بعضَ التعديلاتِ، ومنها: جَعلُ الهيئة التشريعية بيد مجلسينِ: مجلس للنواب ينتخبه الشعبُ، ومجلس للشيوخ يعيِّنُه المَلِك، وضَمَّ المشروع تصريحين أحدهما تصريح 2 رجب 1340هـ / 28 شباط 1922م، وينصُّ على إنهاء الحماية عن مصرَ مقيَّدةً بأربعةِ تحفُّظات، وجاء في التحفظ الثالث: 1/ تأمين مواصلات الإمبراطورية البريطانية في مصر. 2/ الدفاع عن مصر من كل اعتداء أو تدخُّل أجنبي بالذات أو بالواسطة. 3/ حماية المصالح الأجنبية في مصر وحماية الأقليات. 4/ يبقى وضع السودان على حاله خاضعًا للحكم الثنائي البريطاني المصري. والتصريح الثاني كتابٌ مُفصَّل عن السلطان، وأعلنت إنجلترا إنهاءَ الحماية عن مصر، وتصبِحُ مِصرُ دولةً مستقلة ذاتَ سيادة، وأصبح مَلِكُ مصر هو أحمد فؤاد الذي أعلن في 17 رجب 1340هـ استقلالَ البلاد واتَّخذ لقبَ ملك مصر."},{"id":4952,"title":"معاهدة المحمرة لرسم حدود بين العراق ونجد .","date":["العام الهجري :1340","الشهر القمري : رمضان","العام الميلادي :1922"],"text":"التقى الإنجليزي برسي كوكس مع الملك عبدالعزيز في المحمرة، وأكَّد الإنجليزُ على ضرورة إقامةِ حدودٍ بين نجد والعراق، وطالب الوفدُ النجديُّ رسمَ الحدود اعتمادًا على التقسيم القَبَلي المعروف للبدوِ، وتمَّ توقيعُ المعاهدة التي جَعَلت قبائِلَ المنتفق والظفير والعمادات من عنيزة تبعَ العراق، وجعلت شمر تابعةً لنجد، إلا أنَّ الملك عبدالعزيز رفض إبرامَ الوثيقة لأنَّ الظفير بزعامة حمود بن سويط قد احتَمَوا به ورفضوا الانصياعَ للعراق. وتم اعتمادُ ترسيم الحدود بين الطرفين في اتفاقية العقير كمُلحَق لمعاهدة المحمرة."},{"id":4953,"title":"غزو الإخوان (إخوان من أطاع الله) شرق الأردن وترسيم الحدود .","date":["العام الهجري :1340","الشهر القمري : شوال","العام الميلادي :1922"],"text":"شرع الإخوانُ يتحرَّكون شمالًا نحو شرق الأردن واحتلُّوا واحةَ الجوف بعد أشهرٍ واشتبكوا مع رجال شرقِ الأردن، واستولَوا على تيماء وتبوك وأخذوا الزكاة منهما إلى الرياضِ، ووصلوا إلى وادي السرحان وواحة بن شاكر، كما وصلوا إلى قلب شرق الأردن، وحدود سوريا وحدود العراق المباشر بين الممتلكات البريطانية؛ لذلك رأى كوكس المعتمد البريطاني في الخليج ضرورةَ تثبيت الحدود مع الملك عبدالعزيز؛ حيث تم اعتمادُ الحدود والتوقيعُ عليها في برتوكول العقير."},{"id":4954,"title":"إخضاع آل عائض في عسير وتأديب إمام اليمن .","date":["العام الهجري :1340","الشهر القمري : شوال","العام الميلادي :1922"],"text":"في هذا العام تمرَّد الأميرُ حسن آل عائض على ابنِ سعودٍ ونقَضَ العهدَ بتحريضٍ مِن إمام اليمن يحيى حميد الدين، فأرسل الملك عبدالعزيز قواتٍ نجديةً بقيادةِ ابنه فيصل، وجعل القيادةَ العسكريةَ إلى خالد بن لؤي أميرِ الخرمة (من محافظات منطقة مكة المكرمة) وأحدِ قادة الإخوان، والتحق بهم أثناء الطريق بدوٌ مِن قحطان وزهران وشهران، فاستولى فيصل على واحة بيشة ووصل إلى مشارفِ أبها، فهرب منها ابنُ عائضٍ ولم يستَطِع الشريفُ حسين أن يُنجِدَه بقواتٍ كما كان يفعَلُ في السابق، فدخل فيصل أبها، وولى عليها سعدَ بنَ عفيصان وعاد فيصل إلى الرياض، ثم استسلم حسَن آل عائض ونُقِلَ إلى الرياض."},{"id":4955,"title":"صدور قانون الظهير البربري .","date":["العام الهجري :1340","الشهر القمري : ذي الحجة","العام الميلادي :1922"],"text":"صدر قانون الظهير البربري -والظهيرُ يعني المرسوم- أصدره المستعمِرُ الفرنسي، ونصَّ هذا الظهيرُ على جعْلِ إدارة المنطقة البربرية تحت سلطةِ الإدارة الاستعمارية، فيما تبقى المناطِقُ العربية تحت سلطة \"حكومة المخزن\" والسلطان المغربي، وتمَّ إنشاءُ محاكم على أساسِ العُرفِ والعادة المحلية للبربر، وإحلالُ قانون العقوبات الفرنسي محلَّ قانون العقوبات \"الشريفي\" المستَنِد إلى الشريعة الإسلامية؛ ومِن ثمَّ قام هذا القانونُ بنوعينِ مِن العزل تجاهَ المناطِقِ البربرية؛ أولهما: عزلُ الإدارة السلطانية عنهم، وعزلُ الشريعة الإسلامية عن التقاضي بينهم، على اعتبار أن العاداتِ والأعراف البربرية كانت سابقةً على الإسلام!! وكان البربر يشكِّلون حوالي 45% من سكان المغرب في تلك الفترة، وينتشرون في بلاد الريف وجبال أطلس."},{"id":4956,"title":"ثورة محمد بن عبد الكريم الخطابي على الإسبان والفرنسيين معًا في المغرب .","date":["العام الهجري :1341","العام الميلادي :1922"],"text":"كان الشعبُ المغربي قد ثار على السلطان عبد العزيز بن الحسن العلوي وخلَعَه عام 1908م بعد أن أطلق يدَ فرنسا وإسبانيا في المغرب، وبايع الشعبُ أخاه عبد الحفيظ بشَرطِ العمل على استرداد الجهاتِ المقتطعة على الحدودِ، ولكِنَّ عبد الحفيظ صانَعَ فرنسا التي اتَّفَقت سنة 1911 مع إسبانيا على إعطائِها الريفَ مقابِلَ السكوت على الاحتلال الفرنسي، وثار الشعبُ مرة أخرى، ففُرِضَت الحماية الفرنسية، وعَمَّت الثورةُ أرجاء المغرب وقامت الحربُ العالمية الأولى، والشعبُ المغربي يقاوِمُ الفرنسيين في الأطلس الأوسط والأطلس الكبير، وفي تافيلالت وآية عطا، وتسلَّم تطبيقَ المخطَّطات الاستعمارية في مراكش قائِدٌ فرنسيٌّ مِن زبانية الاستعماريين، هو المارشال ليوتي، الذي عقَدَ معاهدةَ الحماية، وحكَمَ المغربَ كمُقيمٍ عام، وأخمد ثوراته، ووجه الاستثماراتِ الفرنسيةَ لنَهبِ ثروات المغرب، وقد ثار الريفُ الذي احتلَّته إسبانيا سنة 1922م، وتزعم الثورةَ الأمير عبد الكريم الخطابي واستطاع النجاحَ في حصار طنجة، وامتدت الثورةُ إلى المناطق التي تحتلُّها فرنسا، فاتفق ليوتي مع الإسبان على قتال الثائرين، وخُنِقَت الثورة سنة 1925م، واستسلم الأمير عبد الكريم للفرنسيين الذين نفوه إلى مدغشقر في جُزُر ريئونيون."},{"id":4957,"title":"معاهدة 1922م وتوقيع صك الانتداب بين ملك العراق وبريطانيا .","date":["العام الهجري :1341","الشهر القمري : محرم","العام الميلادي :1922"],"text":"كان وزيرُ المستعمرات البريطانية ونستون تشرشل قد اتَّفق مع الملك فيصل ابن الشريف حسين قبل تسَلُّمِه المُلْك أن تكون معاهدةٌ بين الطرفين تحُلُّ مكانَ الانتداب، غيرَ أن الإنجليز قد فهموا من هذه العبارة أنَّ الاستقلالَ صورةٌ، والواقِعَ انتدابٌ؛ فالمَلِك ليس أكثَرَ مِن اسمٍ؛ فالمتصَرِّفُ الفعلي والحقيقي هو المعتمد السامي البريطاني، والوزراء ليس لهم سوى التوقيع على قراراته، وصاحِبُ الكلمة هو المستشار البريطاني، وأما الملِكُ فيصل والعراقيون ففَهِموا أنَّ المعاهدةَ ستُلغي الانتداب وتبيِّن العلاقات المتبادلة بين الحكومة العراقية والحكومة البريطانية! ونتيجةً لهذا التباين تأخَّر توقيعُ المعاهدة حتى قُدِّمت للدراسة والتوقيعِ عليها، وكانت تضمُّ بنودًا عديدةً، منها: أن يوافق مَلِك العراق على أن يستدِلَّ بما يقدِّمُه ملك بريطانيا من المشورة بوساطةِ المعتمد السامي جميع الشؤون المهمة التي تمسُّ بتعهدات ومصالح مَلِك بريطانيا، ويستشير ملك العراق المعتمدَ السامي الاستشارةَ التامة فيما يؤدي إلى سياسة مالية ونقدية سليمة، ومنها: أنَّ مَلِكَ العراق لا يعيِّنُ مدة المعاهدة موظفًا دون موافقة ملك بريطانيا، ومنها: أن يتعهَّد مَلِكُ العراق بقَبول الخطة الملائمة التي يشير بها مَلِك بريطانيا، ومنها: لا تُتَّخَذ وسيلةٌ ما في العراق لمنع أعمال التنصير أو للمُداخلة فيها أو لتمييز منَصِّر ما على غيره بسبب اعتقاده الديني أو جنسيته! ولم يكن في نصوص المعاهدة أيُّ ذكرٍ لانتهاء الانتداب، وأكثَرُ بنودها هو ترسيخ للوجود البريطاني والوصاية الواضحة على الملِك، ولم يوافِقِ الوزراء على المعاهدة، فاستقال الوزراءُ كُلُّهم واحدًا تلوَ الآخر، ولم توقَّعْ هده المعاهدة المعروفة بمعاهدة 1922م إلا في الحكومة الثالثة في ليلة 9 ذي القعدة 1342ه بعد منتصف الليل في جلسةٍ غيرِ اعتياديةٍ، وبعد أن بطش المعتمد السامي بالحركة الوطنية، فوُقِّعت المعاهدة، ثم ألحِقَ بند بالمعاهدة بأنَّ المعاهدة ينتهي مفعولها حين دخول العراق عُصبةَ الأمم المتَّحِدة، وألَّا يتجاوَزَ ذلك مدة أربع سنوات، ويُذكَرُ أنَّ بريطانيا أصلًا بعد أن دخلت العراقُ عُصبةَ الأمم كانت قد أفرغت كلَّ الخزائن في الولايات التي كانت تابعةً للعثمانيين، ونهبت كلَّ ما تستطيع نهْبَه حتى الأوقاف، ووضعت يدَها عليها، فلم يعُدْ لها أي مصلحةٍ كبيرة في البقاء بالعراق من الناحية الاقتصادية!!! حتى إن بعض المسؤولين فكَّر بالانسحاب نهائيًّا فور تنصيب المَلِك، ولكِنْ هناك من يرى أن المصالح البريطانية أبعَدُ من مجرد المال الذي انتهى من العراقِ، وإنما محاولة إبقاء التبعيَّة والوصاية من أجل أن تبقى العراقُ تحت السيطرةِ."},{"id":4958,"title":"وصول موسوليني للسلطة في إيطاليا .","date":["العام الهجري :1341","الشهر القمري : ربيع الأول","العام الميلادي :1922"],"text":"في هذا العام تولَّى الدوتشي بينيتو أندريا موسوليني رئاسةَ إيطاليا وشغَلَ منصِبَ رئيس الوزراء وأحيانًا وزارة الخارجية والداخلية، ويعتبَرُ موسوليني من الشخصيات الرئيسة والمهِمَّة بين المؤسِّسين الحقيقيِّين للفاشية، وفي عهده مارست إيطاليا أبشَعَ صُوَر الوحشية من أجل إخضاعِ الشعب الليبي للاستعمار الإيطالي، وأدخل إيطاليا الحربَ العالميَّةَ الثانية إلى جانبِ دُوَل المحور ضِدَّ دول الحلفاء."},{"id":4959,"title":"علماء العراق يقاطعون الانتخابات  .","date":["العام الهجري :1341","الشهر القمري : ربيع الأول","العام الميلادي :1922"],"text":"بعد إعلان الحكومة العراقية معاهدة 1922م التي تُرسِّخ الانتداب البريطاني في العراق، قاطع العلماءُ المشاركةَ في الانتخابات مالم يتِمَّ: 1/ إلغاء سياسة الضغط التي يمارسها المعتمد البريطاني. 2/ إطلاقُ حرية الاجتماعات والمطبوعات. 3/ سحبُ المستشارين الإنجليز من الألوية إلى بغداد. 4/ السماح بتأليف الجمعيات. 5/ السماح بإعادة المنفيِّين السياسيين إلى وطنهم."},{"id":4960,"title":"إلغاء مصطفى كمال أتاتورك السلطنة العثمانية .","date":["العام الهجري :1341","الشهر القمري : ربيع الأول","العام الميلادي :1922"],"text":"قام مصطفى كمال أتاتورك -الذي كانت بيده مقاليدُ الأمور في تركيا- بإلغاء السَّلْطَنة العثمانية، ونفيِ السلطان عبد المجيد الثاني، وكان ذلك تمهيدًا لإلغاءِ الخلافة الإسلامية التي أصدر قرارًا بإلغائها سنة 1924م!! ونفى جميعَ أسرة آل عثمان التي حكمت العالم الإسلاميَّ خمسة قرون. وبذلك نجحت الجهودُ الغربية الاستعمارية في تدمير الرباطِ الرُّوحيِّ بين المسلمين بعد عشراتِ السنواتِ مِن التآمُرِ والمكائد لإسقاط الخلافة!!!"},{"id":4961,"title":"معاهدة العقير وترسيم الحدود بين نجد والعراق والكويت .","date":["العام الهجري :1341","الشهر القمري : ربيع الآخر","العام الميلادي :1922"],"text":"معاهدةٌ حدوديةٌ وُقِّعَت في العقير (ميناء قرب الأحساء)، كان الهدفُ منها إيجادَ حَلٍّ للخلاف بين الملك عبد العزيز والشريف حسين وأولاده في شرق الأردن والعراق، وأطماع الأتراك في الموصل، وقد مثَّلَ نجْدًا سلطانُ نجد عبد العزيز بن عبد الرحمن آل سعود، وكان صبيح بك نشأت وزيرَ المواصلات والأشغال عن الملك فيصل ملك العراق، أمَّا الكويت فقد مثَّلَها الميجور مور الوكيل السياسي البريطاني في الكويت طبقًا لاتفاقية الحماية البريطانية الكويتية الموقَّعة عام 1899م، والتي تمنَحُ بريطانيا حَقَّ إدارة شؤون الكويت الخارجية، وكان السير برسي كوكس المعتمد السياسي في الخليج يلعَبُ دور الوسيط في تلك الاجتماعات. بدأت الاجتماعات بين ممثِّل العراق صبيح بك، والملك عبدالعزيز، بدأ الطرفان بالتشَدُّد في مواقفهم، حيث طلب العراق أن تكون حدودُه على بعد 12 ميلًا من الرياض، بالمقابِلِ طلب ابن سعود كلَّ مناطق البدو الشمالية من حلب حتى نهر العاصي، وعلى جانب الشطِّ الأيمن للفرات وحتى البصرة، وطالب أيضًا بحدود قَبَلية بدلًا من حدود ثابتة، استمرت النقاشاتُ طوال خمسة أيام، أراد الجانب العراقي حدودًا لا تقل عن 200 ميل جنوب الفرات، بينما أراد الملك عبدالعزيز أن يتِمَّ تحديدُ الحدود باعتبار منازل القبائل الموالية لكُلِّ طَرفٍ بدلًا من الترسيم عن طريق الخرائط. في اليوم السادس من اللقاءات تمَّ رسمُ الحدود التي اعتُمِدَت من قِبَل الأطراف الثلاثة، وتقرر بناءً عليها إنشاءُ منطقتين محايدتين: الأولى بين الكويت والسعودية، والثانية بين العراق والسعودية."},{"id":4962,"title":"إصدار فرنسا قانونًا جديدًا يتعلق بالجنسية الفرنسية في تونس .","date":["العام الهجري :1341","الشهر القمري : شعبان","العام الميلادي :1923"],"text":"أصدرت فرنسا قانونًا جديدًا في تونس يمنَحُ الجنسية الفرنسية لكُلِّ من يطلُبُها، أو يُظهِرُ عواطِفَ نحو فرنسا، وبالتالي يصبحُ حامِلُها من رعايا فرنسا، ويستحق حمايتَها ودَعْمَها، فردَّ المسلمون على هذا القانون اجتماعيًّا وعَقَديًّا، فقاطعوا كلَّ مُسلِمٍ طلَبَ الجنسية الفرنسية، وعدُّوه خارجًا عن الإسلامِ، لا يصِحُّ دَفنُه في مقابر المسلمين! وهذه القوَّةُ في مواجهة القانون جعلت كثيرًا ممن أقدم على التجنُّسِ يتخلَّى عن الجنسية الفرنسية ويعودُ لأصله، واغتاظ الفرنسيون بشدَّةٍ مِن ذلك، وقام المستوطِنون الفرنسيون بأعمالٍ استفزازية ضِدَّ مسلِمي تونس."},{"id":4963,"title":"صدور أول دستور مصري في ظل الاستقلال المقيد .","date":["العام الهجري :1341","الشهر القمري : رمضان","العام الميلادي :1923"],"text":"عَقِبَ انتهاء الحرب العالمية الأولى قامت الثورةُ المصرية في عام 1919 مطالِبةً بالحرية والاستقلال لمصر، وإقامة حياة نيابية وديمقراطية كاملة. وأدَّت هذه الثورة إلى صدور تصريح في 28 فبراير 1922، والذي اعترف بمصرَ دولةً مستقلةً ذات سيادة (مع وجود تحفُّظات أربعة)، كما تضمَّن إنهاءَ الحماية البريطانية على مصر. واستنادًا إلى هذا الواقِعِ الجديد تمَّ وَضعُ دستور جديد للبلاد صدر في إبريل عام 1923، ووضعَته لجنةٌ مكوَّنةٌ من ثلاثين عضوًا، ضمَّت ممثِّلين للأحزاب السياسية، والزعامات الشعبية، وقادة الحركة الوطنية. وقد أخذ هذا الدستورُ بالنظامِ النيابي البرلماني القائِمِ على أساس الفصل والتعاون بين السُّلطاتِ. ونُظِّمَت العلاقةُ بين السلطتين: التشريعية والتنفيذية على أساسِ مبدأ الرَّقابة والتوازن. كما أخذ الدستورُ الجديد بنظام المجلِسَين، وهما: مجلس الشيوخ، ومجلس النواب. وبالنسبة لمجلس النوَّاب نَصَّ الدستور على أنَّ جميعَ أعضائه مُنتَخَبون، ومدةُ عضوية المجلس خمس سنوات. أمَّا مجلسُ الشيوخ فكان ثلاثةُ أخماس أعضائِه مُنتخَبين، والبقيَّةُ مُعيَّنين. وأخذ الدستورُ بمبدأ المساواة في الاختصاص بين المجلسين كأصلٍ عامٍّ، مع بعض الاستثناءاتِ. وقد تزايد عددُ أعضاء المجلِسَين من فترة لأخرى؛ حيث كان الدستور يأخذ بمبدأ تحديد عدد أعضاء المجلِسَين بنسبةٍ معينة من عدد السكَّان."},{"id":4964,"title":"إقامة حفلة بمناسبة اعتراف إنجلترا باستقلال شرق الأردن  .","date":["العام الهجري :1341","الشهر القمري : رمضان","العام الميلادي :1923"],"text":"اعترفت إنجلترا باستقلال شرق الأردن، واحتفظت لنفسِها بالإشراف العسكريِّ، وبعضِ الإشرافِ الماليِّ عليه، والمعروف أنَّ هذا القسم كان تحت حكم ِالأمير عبد الله بن حسين بن شريف مكةَ، وفي 15 أيار أقيمَ حَفلٌ رَسميٌّ بمناسبة اعتراف بريطانيا باستقلالِ شرق الأردن، شارك فيه رجالاتُ الأردن وفلسطين، وأيضًا المندوب السامي البريطاني في فلسطين الصهيوني هربرت صموئيل، ومعه الجنرال كلايتون الذي يعمل في المكتب العربي في القاهرة، وكان له دورٌ كبير في عمليات الثورة العربية، وقد ألقى الأميرُ عبد الله خطبةً طويلة استهلَّها بمقدِّمة تاريخية عن مجد الأمة العربية، وما أصاب هذه الأمَّةَ بعد الدولة العباسية، ثم تحدَّث عن مفاوضاته مع جلالةِ ملك بريطانيا مُثمِّنًا اعتراف جلالته باستقلال هذا القِسمِ مِن المملكة العربية، وأن الحكومةَ ستشرع بتعديل قانون الانتخابات، ووضْعِ القانون الأساسيِّ لشرق الأردن، ثم شكر الأميرُ عبد الله كلَّ الذين ساهموا في إنجاز المعاهدة أو في خطوات الاستقلال، وإرساء قواعد الدولة، وخَصَّ بالشكر المندوبَ السامي في فلسطين الصهيوني هربرت صموئيل، وتناول فرنسا في حديثِه؛ حيث قال: \"إني لآمُلُ أن يكونَ موقِفُ الدولة الفرنسية تجاهَ قضيتنا العربية المقدَّسة وتجاه القسم الشمالي الباقي من وطننا المحبوب آخِذًا بها إلى عهدٍ جديدٍ كافٍ للدَّلالةِ على احترامِ أبناء الثورة الفرنسية لحريةِ الأقوامِ واستقلالِها\""},{"id":4965,"title":"اعتراف بريطانيا بحكومة شرق الأردن تحت الإشراف البريطاني .","date":["العام الهجري :1341","الشهر القمري : شوال","العام الميلادي :1923"],"text":"قرَّرت بريطانيا أن يكونَ شرق الأردن دولةً مُتمتِّعةً بالحكم الذاتي، يحكُمُها الأمير عبد الله بن حسين بن شريف مكةَ، بعد مقابلته لوزير المستعمرات البريطاني وينستون تشرشل، تمَّ الاتفاق بأن تقومَ في شرقي الأردن إمارةٌ ذاتُ حكومة تتمتَّعُ بالاستقلال الإداري وتسترشِدُ برأي المفوض السامي الإنجليزي في القدس، وتتقاضى من إنجلترا معونةً سنوية، فوقَّع الأميرُ عبد الله بن الحسين على صكِّ الانتداب البريطاني على شرق الأردن، فأعلَنَ عن تأسيس إمارة شرق الأردن تحت حُكمِ الأمير عبد الله بن الحسين، ثم تمَّ إنشاء حكومة دستورية في 11/4/1921م، وكان أوَّلُ رئيس لها رشيد طليع، وبذلك اختفت الحكوماتُ المحلية واندمجت في حكومةٍ واحدة هي حكومةُ إمارة شرقي الأردن، وماطلت بريطانيا في الاعترافِ بحكومة شرق الأردن حتى 25 أيار 1923 بعد الاعترافِ الرسميِّ مِن قِبَل المندوب السامي البريطاني بالحكومة الأردنية، وتمَّ تحديدُ حدود إمارة شرق الأردن التي كانت مُبهمةً وقت إعلان قيام الإمارة سنة 1921م."},{"id":4966,"title":"بداية القضية الكردية في العراق  .","date":["العام الهجري :1341","الشهر القمري : ذي القعدة","العام الميلادي :1923"],"text":"بعد زيارة رئيس مجلس الوزراء العراقي عبد المحسن السعدون منطقةَ السليمانية قرَّر مجلِسُ الوزراء في جلسة المجلس يوم 28 ذي القعدة 1431ه الموافق 11يوليو 1923م: 1/ أنَّ الحكومة لا تنوي تعيينَ أيِّ موظَّف في الأقضية الكردية عدا الموظَّفين الفنيين. 2/ أن الحكومةَ لا تجبِرُ سكان المناطق الكردية على استعمال اللغة العربية في مراجعاتهم. فكان هذا القرارُ خاطئًا؛ فإن المناطق الكردية جزء من أرض العراق يعيَّنُ فيها الموظف الكفء سواء أكان كرديًّا أم عربيًّا، وكذلك يعَيَّنُ الكردي في أي منطقة من العراق حسَبَ ما تقتضيه المصلحة، كان أكثَرُ سكان العراق من العرب، ولغتُهم الرسميَّةُ العربية، والأكراد مسلمون والعربية أساسية في عباداتهم وتلاوتهم للقرآن، فعليهم أن يحافظوا عليها. إنَّ اتخاذ هذا القرار وأمثاله هو الذي أوجد الفكرةَ الانفصالية ورسَّخَها مع الزمن وجعل العصبيَّةَ القوميَّةَ تحُلُّ محلَّ العقيدة الإسلامية، فعانت البلادُ الويلاتِ منها خاصةً عندما نشأت العصبية القومية عند العرب، والذي كان المستعمِرُ ينفُخُ فيها ويؤجِّجُها في نفوسِ المسلمين."},{"id":4967,"title":"أعمال مصطفى كمال أتاتورك بعد أن تسلم الرئاسة .","date":["العام الهجري :1342","العام الميلادي :1923"],"text":"مصطفى كمال من سلانيك أو سالونيك مدينة يونانية، وهي مهبِطُ اليهود ومقَرُّهم، ومنها خرج وفيها نشأ، لذلك عدَّه كثيرٌ من الكُتَّاب من يهود الدونمة؛  ثمَّ إن أدواره التي لَعِبَها توحي بالعمالة الغربية؛ فقد صنعه الغَربُ ليظهَرَ في صورة البطل؛ وليكونَ مقبولًا عند الأتراك، ويكفي أنَّ أعمالَه تدُلُّ على باطنه؛ فقد منع الخليفةَ مِن الخروج للصلاة، ثم خفض مخصَّصاته للنصف، وحكم مصطفى كمال البلادَ بالحديدِ والنار، وضَمِنَ تأييدَ الدول العظمى لسياستِه التعسفية، وقد نفَّذ مصطفى كمال المخطَّط كاملًا، وابتعد عن الخطوط الإسلامية، ودخلت تركيا لعمليَّات التغريب البَشِعة؛ فألغى الخلافةَ الإسلامية سنة 1342ه، ثم ألغى وزارة الأوقاف سنة 1343هـ/1924م، وعَهِدَ بشؤونها إلى وزارة المعارف. وفي عام 1344هـ أغلق المساجِدَ، وقضت حكومتُه في قسوةٍ بالغة على كلِّ تيَّار ديني، وواجهت كلَّ نقدٍ ديني لتدبيرها بالعُنفِ. أما الشريعة الإسلامية فقد استُبدِلَت وحلَّ محلها قانونٌ مدني أخذته حكومةُ تركيا من القانون السويسري عام 1345هـ/1926م، وغيَّرَ التقويمَ الهجريَّ واستخدم التقويم الجريغوري الغربي، فأصبح عام 1342هـ مُلغًى في كلِّ أنحاء تركيا وحلَّ محله عام 1926م! وفي دستور عام 1347هـ أغفل النصَّ على أن تركيا دولةٌ إسلامية، وغيَّرَ نَصَّ القسم الذي يقسِمُه رجال الدولة عند تولِّيهم لمناصبهم، فأصبحوا يُقسِمون بشَرَفِهم على تأدية الواجبِ بدلًا من أن يحلِفوا بالله كما كان عليه الأمر من قبل!! وفي عام 1348ه بدأت الحكومة تَفرِضُ إجباريًّا استخدامَ الأحرف اللاتينية في كتابة اللغة التركية بدلًا من الأحرُفِ العربية. وبدأت الصُّحُفُ والكتُبُ تَصدُرُ بالأحرف اللاتينية، وحُذِفَ من الكليات التعليمُ باللغة العربية واللغة الفارسية، وحُرِّم استعمال الحرف العربي لطبع المؤلفات التركية، وأما الكتُبُ التي سبق لمطابِعِ استانبول أن طبعتها في العهود السالفة فقد صُدِّرَت إلى مصر، وفارس، والهند، وهكذا قطعت حكومة تركيا ما بين تركيا وماضيها الإسلاميِّ من ناحية، وما بينها وبين المسلمين في سائر البلدان العربية والإسلامية من ناحية أخرى!! وفي عام (1350-1351هـ/1931-1932م) حدَّدَت عددَ المساجِدِ، ولم تسمَحْ بغير مسجد واحدٍ في كل دائرة من الأرض يبلغ محيطُها 500 متر مربع، وأعلن أنَّ الروح الإسلامية تعوقُ التقدُّمَ. وتمادى مصطفى كمال في تهجُّمه على المساجد، فخفض عددَ الواعظين الذين تدفَعُ لهم الدولة أجورَهم إلى ثلاثمائة واعظ، وأمَرَهم أن يفسحوا في خطبة الجمعة مجالًا واسعًا للتحدُّثِ على الشؤون الزراعية والصناعية وسياسة الدَّولة، وكَيْلِ المديحِ له. وأغلق أشهَرَ جامعين في استانبول، وحَوَّلَ أولهما وهو مسجد آيا صوفيا إلى متحف، وحول ثانيهما وهو مسجد الفاتح إلى مستودع، وأهملت الحكومةُ التعليم الديني كليَّةً في المدارس الخاصة، ثم تمَّ إلغاؤه. بل إنَّ كلية الشريعة في جامعة استانبول بدأت تقَلِّلُ من أعداد طلابها حتى أغلقت عام 1352هـ/1933م. وأمعنت حكومة مصطفى كمال في حركة التغريب، فأصدرت قرارًا بإلغاء لبس الطربوش، وأمَرَت بلُبس القبعة تشبهًا بالدول الأوروبية، وفي عام 1935م غيَّرَت الحكومة العطلة الرسمية فلم يعد الجمعة، بل أصبحت العطلة الرسمية للدولة يومَ الأحد، وأصبحت عطلةُ نهاية الأسبوعِ تبدأ منذ ظُهر يوم السبت وتستمر حتى صباح يوم الاثنين، وأخذ أتاتورك ينفُخُ في الشعب التركي روحَ القومية، واستغَلَّ ما نادى به بعضُ المؤرخين من أن لغة السومريين أصحاب الحضارة القديمة في بلاد ما بين النهرين كانت ذات صلةٍ باللغة التركية، فقال: إن الأتراك هم أصحاب أقدم حضارة في العالم؛ ليعَوِّضَهم عما أفقَدَهم إياه من قِيَمٍ، بعد أن حارب كلَّ نشاط إسلامي، وخلع مصطفى كمال على نفسه لقب (أتاتورك) ومعناه أبو الأتراك، وعملت حكومته على إلغاء حجاب المرأةِ وأمرت بالسفور، وأُلغيت قوامةُ الرجل على المرأة، وأُطلِقَ لها العِنان باسم الحرية والمساواة، وشجع الحفلاتِ الراقصة والمسارح المختلطة والرقص. وأمر بترجمة القرآن إلى اللغةِ التركية، ففقد كُلَّ معانيه ومدلولاته، وأمر أن يكونَ الأذان باللغة التركية، ثمَّ عَمِلَ على تغيير المناهج الدراسية، وأعيد كتابةُ التاريخ من أجل إبراز الماضي التركي القومي، وجرى تنقيةُ اللغة التركية من الكلمات العربية والفارسية، واستُبدِل بها كلمات أوروبية أو حثية قديمة."},{"id":4968,"title":"احتلال الإيطاليين مدينة طرابلس وقضاؤهم على جمهورية ليبيا الأولى .","date":["العام الهجري :1342","الشهر القمري : صفر","العام الميلادي :1923"],"text":"في أعقاب الحرب العالمية الأولى التي انتهت سنة 1337هـ/ 1918م والتي خرجت إيطاليا منها مُنهَكةً، رأت إيطاليا مهادنةَ الليبيين، وتمَّ عقد اتفاق \"سوني\" بين الطرفين، اعترفت إيطاليا بموجِبِه بقيام الجمهورية، ونصَّ على إنهاء حالة القتال بينهما، مع الاعترافِ بالاستقلال الداخلي لطرابلس تحت سيادةِ ملك إيطاليا، وإنشاء مجلسِ نوابٍ محليٍّ، ومجلس آخر حكومي يشتركان في حكمِ البلاد. إلا أنَّه لم يقَدَّر لتلك الجمهورية الوليدة أن تدوم طويلًا؛ إذ لم تكن إيطاليا جادَّةً في اعترافها بها، وإنما كانت تسعى من وراء ذلك إلى مُهادنة الليبيين وكَسبِ مزيد من الوقت؛ نتيجةَ الضعف الذي ألمَّ بها."},{"id":4969,"title":"مؤتمر الكويت لحل النزاعات الحدودية بين نجد والعراق والحجاز و الأردن .","date":["العام الهجري :1342","الشهر القمري : جمادى الأولى","العام الميلادي :1923"],"text":"دعت الحكومةُ البريطانية كُلًّا من نجد والعراق وشرق الأردن والحجاز إلى تسويةِ القضايا الحدوديَّةِ في مؤتمر عُقدَ في الكويت برئاسة الكولونيل نوكس وزير البحرية الأميركية، اشترط الملك عبدالعزيز على نوكس أن يتِمَّ تعيينُ الحدود بين نجدٍ والحجاز وشرق الأردن من جهة، وعدم اشتراك مندوبِ العراق مع حكومتي الحجاز وشرق الأردن في المباحثات المشتركة، وأن يتِمَّ تناول المشكلات بين نجدٍ وتلك الحكومات بصورة منفردة، فأبلغ نوكس الملك عبدالعزيز موافَقةَ الحكومة البريطانية على الشروطِ التي عرضها. مثَّلَ جانِبَ نجد في المؤتمر حمزة غوت وأحمد الثنيان وعبد الله الدملوجي، وشرق الأردن مثَّلَه علي خلقي، والعراق مثَّلَه صبيح نشأت، وبدأت جلساتُ المؤتمر دون حضورِ مَن يمثِّلُ الحجاز، ولم يتوصَّل الأطراف الثلاثة إلى اتفاقٍ محدَّد بينهم."},{"id":4970,"title":"سعد زغلول يشكل أول وزارة وفديَّة .","date":["العام الهجري :1342","الشهر القمري : جمادى الآخرة","العام الميلادي :1924"],"text":"قام سعد زغلول بتشكيل أول وزارة وفدية، وذلك عَقِبَ الفوز الذي حقَّقه حزبُ الوفد في الانتخابات التي أُجرِيَت في 27 من سبتمبر 1923، وفاز بأغلبية مقاعد البرلمان المصري."},{"id":4971,"title":"إلغاء الخلافة العثمانية الإسلامية والإعلان عن قيام جمهورية تركيا .","date":["العام الهجري :1342","الشهر القمري : رجب","العام الميلادي :1924"],"text":"بعد أن أخفق مؤتمر لوزان، وعاد رئيسُ الوفد التركي عصمت إينونو واختلف هو ومصطفى كمال مع رئيسِ الوزارة وبجانبه الجمعية الوطنية، فاستقال رئيس الوزارة، وبدأت الدسائِسُ، فحَلَّ مصطفى كمال الجمعيةَ الوطنية، وكثرت الفوضى وقرَّر مصطفى كمال إعلان الجمهورية، واجتمعت الجمعيةُ الوطنية، ودُعِيَ مصطفى كمال لتشكيل الوزارة فوافق، على ألا يُناقَشَ في تصرُّفاته، وشكَّل الوزارة، وأعلن الجمهورية بعد اجتماع المجلس النيابي في أنقرة بتاريخ 20 ربيع الأول 1342هـ / 30 تشرين الأول 1923م، فقَرَّر إلغاء السلطنة والخلافة، وإعلان الجمهورية التركية، وانتُخِبَ مصطفى كمال رئيسًا لها، فعَمَّت الفوضى وغادر أنقرة عددٌ مِن الزعماء، واتجهوا إلى استانبول عند الخليفة، وقامت الاحتجاجات، ولكِنْ بدأت الاغتيالاتُ ودعا المجلِسَ الوطني لعقد جلسةٍ، وقدَّم مرسومًا بإلغاء الخلافةِ، وطرَد الخليفةَ، وأعلن فَصْلَ الدين عن الدولة، وأمر عبد المجيد بالسَّفرِ إلى سويسرا، ثم أصدر مرسومًا بإلغاء الوظائف الدينية، وامتلاك الدولة للأوقاف، وأرسل وزيرَ الخارجية عصمت إينونو إلى لوزان، وأعيد المؤتمر واعترفت إنجلترا باستقلالِ تركيا، وانسحبت من المضائق واستانبول، وطُوِيَت صفحةُ الخلافة الإسلامية العثمانية التي حكمت العالم الإسلامي عدة قرون."},{"id":4972,"title":"تغير ميزان القوى في الحجاز لصالح الملك عبدالعزيز ضد الشريف حسين .","date":["العام الهجري :1342","الشهر القمري : شعبان","العام الميلادي :1924"],"text":"دخلت العلاقاتُ الحِجازية النجدية في مراحِلَ حاسمة في أواخر هذا العام، وزادت طموحات الملك عبدالعزيز في ضم الأراضي الحجازية مع تغيُّر الأوضاع في ظِلِّ تفوُّقِه بعد ضم الأحساء ثم حائل، ثم عسير، وضَعْف الدعم البريطاني للشريف حسين، وفشل مؤتمر الكويت، وتحميل الإنجليز الشريف المسؤوليةَ في ذلك، وإعلان الشريف حسين الخلافةَ على المسلمين بعد إعلانِ سُقوطِ الخلافة العثمانية، ورَفْض الدول الإسلامية وعموم المسلمين هذا الإعلانَ وظهور حركة مضادَّة في مصر والهند ضِدَّ الشريف حسين وطموحاته، ويضاف إلى هذا فقْدُ الحسين مكانتَه في أوساط أهل الحجاز بعد تدهورِ الأوضاعِ الاقتصادية والأمنية في الحجاز وتناقُص أعداد الحُجَّاج، وتخلِّي زعماء القبائل عن دعم ومساندة الشريف حسين أمام هَجَمات النجديين، حتى أصبح الوضعُ مهيَّأً أمام الملك عبدالعزيز لتحقيقِ طموحاته في الحجازِ، وكلُّ هذه الأوضاع شجَّعته على ضم الحجاز إلى حكمه."},{"id":4973,"title":"مؤتمر الرياض لإقرار غزو الحجاز .","date":["العام الهجري :1342","الشهر القمري : ذي القعدة","العام الميلادي :1924"],"text":"دعا الملك عبدالعزيز إلى عقد مؤتمر في الرياض للأعيان والعلماء والشيوخ وزعماء القبائل؛ للتداول في شُؤونِ الحُجَّاج، وتمَّ اتخاذُ القرارات الخاصة بعدم صلاحية الشريف حسين في الإشراف على الأماكن المقدَّسة في الحجاز، بعد أن منع الحُجَّاج من نجد بأداء مناسِكِ الحج، وأيَّدَ المجتَمِعون استخدام القوة ضِدَّ الشريف في الحجاز."},{"id":4974,"title":"المصادقة على المعاهدة العراقية البريطانية 1922م .","date":["العام الهجري :1342","الشهر القمري : ذي القعدة","العام الميلادي :1924"],"text":"أحالت الحكومةُ العراقيَّةُ برئاسة جعفر العسكر المعاهدةَ العراقية البريطانية إلى لجنةِ للتدقيق فيها، وكانت بنودُ هذه المعاهدة قد وُضِعَت عام 1922م وهي تتضمَّنُ ترسيخ الانتداب البريطاني وانضمام العراق إلى عُصبة الأمم، وعندما أحيلت المعاهدةُ إلى لجنة مكونة من 15 عضوًا جرت مناقشاتٌ كثيرة حولها؛ فالمعارِضون يريدون تعديلَها والمؤيِّدون للحكومة يرون أنَّهم مضطرون للتصديقِ عليها خوفًا من التهديدات البريطانية، ثمَّ في 29 شوال انعقد المجلسُ التأسيسي وطُرِحَت المعاهدة للنقاش، فلما تكلَّم المعارضون قسَوا على المؤيِّدين واستمَرَّت المناقشات 4 جلسات طويلة، وفي يوم 8 ذي القعدة طالت الجلسةُ فاقتُرِحَ تأجيل الجلسة مع تأجيل المصادقة حتى ينتهي أمرُ الموصل، والبعض يرى فقط تأجيل الجلسة والمصادقة إلى الغد، فتأجَّلت، وتضايق المعتمد السامي فأعدَّ مذكِّرة لحلِّ المجلس واحتلال بناء المجلس، ونتيجةً لضغط المعتمد عُقِدَت جلسة فوق العادة قبل منتصف الليل، وأكرِهَ الأعضاء على الحضور، فاجتمع 69 من أصل 100 عضو، وأحاطت القوات المسلحة بالمبنى، وفُتِحَت الجلسة وبدأ التصويت، فأيَّد المعاهدة 37 وعارضها 24، واستنكف عن التصويت 8 أعضاء، وبذا تم التصديقُ على المعاهدة في يوم 9 ذي القعدة 11 يونيو 1924م. سَخِطَ الشعب العراقي على المعاهدة وعلى الذين أيَّدوها، لكِنَّ الحكومة البريطانية رفعت المعاهدة والاتفاقيات الملحقة بها إلى عُصبة الأمم، فوافقت عليها وصادق عليها المَلِك جورج الخامس ملك بريطانيا والملك فيصل بن الشريف حسين مَلِك العراق."},{"id":4975,"title":"وفاة الأديب مصطفى لطفي المنفلوطي .","date":["العام الهجري :1342","الشهر القمري : ذي الحجة","العام الميلادي :1924"],"text":"هو الأديبُ مصطفى لطفي بن محمد لطفي المنفلوطي، ولِدَ سنة 1292هـ بمنفلوط من مدن الوجه القبلي بمصر، من أبٍ مصري وأم تركية، من أسرة حُسينية النَّسَب، في بيت علمٍ وقضاء، حيث كان والده قاضيًا مشهورًا ونقيبًا للأشراف، وهو نابغةٌ في الإنشاء والأدب، انفرد بأسلوب نقيٍّ في مقالاته وكتبه. له شعرٌ جيد فيه رقَّة وعذوبة. تعلَّم في الأزهر، واتَّصَل بالشيخ محمد عبده اتصالًا وثيقًا، حتى إنه سُجِنَ بسببِه ستة أشهر، بدأ يكتب الشعر صغيرًا على سجيَّتِه، ثم التحق بالأزهر ولكنَّه لم يُطِقِ المتابعة وآثَرَ البقاء على قراءة كتب الأدب، فتفرغ للأدب وكتابته، وكان قد سُجِنَ بسبب هجائه للخديوي عباس الذي كان على خلافٍ مع شيخه محمد عبده، ثم رجع بعد ذلك إلى قريتِه وكتب فيها، وكانت تُنشَرُ كتاباته في الصحف والمجلات، وكان صاحِبَ أسلوب مميَّز جدًّا فيما يكتبه، وله مجموعة من القَصَص المشهورة، مثل العبرات والنظرات، وماجدولين، والفضيلة، وكان له آراءٌ إصلاحية واجتماعية وتكافلية، وله شِعرٌ عذب، ابتدأت شهرته تعلو منذ سنة 1324هـ بما كان ينشرُه في جريدة (المؤيد) من المقالات الأسبوعية تحت عنوان (النظرات)، وولي أعمالًا كتابية في وزارة المعارف، ووزارة الحقانية، وسكرتارية الجمعية التشريعية، وأخيرًا في سكرتارية مجلس النواب، واستمَرَّ فيها إلى أن توفِّيَ."},{"id":4976,"title":"قوات الملك عبدالعزيز على حدود العراق وشرق الأردن .","date":["العام الهجري :1343","العام الميلادي :1924"],"text":"عندما قرَّر الملك عبدالعزيز التقدُّمَ نحو الحجاز أرسل قوةً عسكرية إلى حدودِ نجد مع العراق، وأخرى على حدود نجد مع شرق الأردن؛ خوفًا من تدخُّل فيصل وعبد الله -نجلَي الشريف حسين- في حَسمِ الصراعِ على الحجاز."},{"id":4977,"title":"احتلال إيران لعربستان (الأحواز) .","date":["العام الهجري :1343","العام الميلادي :1924"],"text":"كانت منطقةُ الأحواز تسمَّى عربستان، وهي إمارةٌ عربيةٌ تقعُ في محيطٍ فارسي، وكانت مشمولةً برعايةٍ بريطانيةٍ يحكُمُها أميرُ الشيخ حسين خزعل، وهي إمارة مستقلَّة، إلى أن جاء الجنرال رضا بهلوي، ونظرًا لتأثير الحرب العالمية الثانية على بريطانيا وسَعْيِها لكسبِ إيران وضمانِ مساندتها لبريطانيا قامت بريطانيا بإعطاءِ إمارة عربستان لإيران في هذا العام، وَعَمِلَ الجنرالُ بهلوي على إنهاءِ حُكمِ آخِرِ حکَّامِ الکعبيين -وهو خزعل جابر الکعبي- على الأحواز، ثم قام بضمِّها كجزءٍ من الدولة الفارسية، ويعَدُّ السببُ الأقوى لاحتلال إيران لهذه المنطقة كونَها غنيَّةً بالموارد الطبيعية من النفطِ والغاز، ويوجَدُ فيها أراضٍ زراعية خصبة؛ حيث يصبُّ فيها أكبر أنهار المنطقة، وهو نهر كارون؛ لذلك تعتبرُ منطقة الأحواز هي المنتِجَ الرئيسيَّ لمحاصيل السكر والذرة في إيران، وتساهم مواردُها بحوالي نصف الناتج القومي لإيران، وأكثر من 80% من قيمة الصادرات في إيران. ويعَدُّ إقليم الأحواز أقربَ المناطق العربية التي استولت عليها إيرانُ إلى العراق، بل إنَّ إيران استفادت استفادةً كبيرة منها في صراعِها مع العراقِ حول منطقةِ شَطِّ العرب."},{"id":4978,"title":"تدويل طنجة لمصلحة المستعمر .","date":["العام الهجري :1343","العام الميلادي :1924"],"text":"كان لمدينة طنجة وضعٌ خاصٌّ بسبب موقعها المهم؛ لذا حرصت الدول المستعمِرة للمغرب أن يكونَ لها وضعٌ خاصٌّ، وقد شُغِلت الدول بأحداث الحرب العالمية الأولى؛ لذا لم تستطع وضعَ نظام لها، فلما وضَعَت الحربُ أوزارَها وضعت الدولُ الكبرى لطنجة نظامًا دوليًّا محايِدًا يقضي بأن يكون للميناء حاكِمٌ فرنسي إداري وله مساعدان إنجليزي وإسباني، والسلطة التنفيذية بيد هيئة المراقبة المؤلَّفة من فرنسا وإسبانيا وإنجلترا، ومندوب عن سلطان مراكش، وبهذا انتزعت طنجة من مراكش وتمَّ تدويلُها، ثم استولى عليها الإسبان في الحرب العالمية الثانية، ولم تعُدْ طنجة إلى المغرب إلا بعد الاستقلال في عام 1375هـ / 1955م."},{"id":4979,"title":"عصبة الأمم تقرِّر ضم الموصل للعراق  .","date":["العام الهجري :1343","العام الميلادي :1924"],"text":"كانت الموصِل جزءًا من الدولة العثمانية حتى نهاية الحرب العالمية الأولى، عندما احتلَّتْها بريطانيا، وبعد حرب الاستقلال التركية، اعتبرت تركيا الموصل من القضايا الحاسمة المحدَّدة في الميثاق الوطني التركي. وعلى الرغم من المقاومة المستمرة تمكَّنت بريطانيا من طرح هذه القضية في الساحة الدولية، كمشكلة حدود بين تركيا والعراق. فقرَّر مجلسُ عصبة الأمم في جلسته المنعقدة في الثالث من ربيع الأول عام 1343هـ / الأول من تشرين الأول 1924م أن يتولى بنفسِه تعيينَ الحدود بين تركيا والعراق، وإنهاء الخلاف بين الحكومتين على ولاية الموصل، وأرسل مجلِسُ عصبة الأمم لجنةً مؤلفة من ثلاثة أعضاء وصلت إلى بغداد في العشرين من جمادى الآخرة 1343هـ / 15 كانون الثاني 1925م، وكانت إنجلترا ترى أن المنطقةَ المتنازَعَ عليها تضُمُّ مجموعاتٍ نصرانيةً وأخرى يهودية، وكذلك مجموعة يزيدية، وبما أنهم سيوطَّنون تحت دولة مسلمة فلا بد من اتخاذ الإجراءات الكفيلة بحمايتهم تمامًا، وخاصة أنهم رغم بقائهم بكلِّ أمن وسلام فترة عيشهم في ظل الدولة العثمانية إلا أنهم عند اندلاع الحرب العالمية الأولى أظهروا ما تُخفي صدورهم من الحقد الصليبي، فكانوا شرًّا وبيلًا على المسلمين من قَتلٍ وترويع ونهب؛ فلذا رفض الأتراك أن يكون الآشوريون على الحدود، فقامت إنجلترا ومن خلال جمع التبرعات لهم بإسكانِهم في مناطق أخرى في الوسَط، وطُلِب من الحكومة العراقية منحُهم أراضيَ مقابل التي تركوها في الموصل، وإعفاؤهم من الضرائب، واعترفت الحكومةُ بالبطريك مار شمعون بطريقًا لهم، أمَّا الأكراد الذين كانوا جيرانًا للآشوريين فلم يَسلَموا أيضا من أذاهم أيامَ اندلاع الحرب بحكم أن الأكراد يخالفونهم في العقيدة، فهو مسلمون، وزاد أذاهم لهم لَمَّا احتل الإنجليز العراق، وبعد رفع الأمر لمحكمة لاهاي وإرسال اللجان التي درست المنطقة قرَّر مجلس عصبة الأمم أن تكون الحدودُ بين العراق وتركيا كما في قرار الأول من ربيع الثاني 1343هـ ولم توافق تركيا طبعًا فعرض الإنجليز على تركيا اتفاقًا تتعهَّدُ فيه المحافظة على سلامة أملاكها مقابِلَ بقاء الموصل للعراق وأن تُجرَّدَ الموصِلُ من وسائل الدفاع وتُعَدُّ حيادية، وتعطى تركيا قرضًا بقيمة عشرة ملايين جنيه وتتنازل عن جزء من السليمانية، ورفضت أيضًا تركيا ذلك، ثمَّ عُقِدَ مؤتمر ثلاثي عراقي تركي إنجليزي وُقِّعَت فيه معاهدة شَمِلَت رسم الحدود وجنسية سكان المناطق التي كانت موضِعَ خلافٍ، وموضوعَ استثمارِ النِّفطِ، وتعهدت إنجلترا بدفع عشرة بالمائة من عائدات النفط لمدة خمسة وعشرين سنة."},{"id":4980,"title":"دخول قوات الإخوان  (إخوان من أطاع الله) الطائف .","date":["العام الهجري :1343","الشهر القمري : صفر","العام الميلادي :1924"],"text":"بلَغَت قراراتُ مؤتمر الرياض قواتِ الإخوان المتمركِزة في تربة والخرمة (من محافظات منطقة مكة المكرمة)، ووصلهم الأمرُ بالاستعداد لفتح الطائف، فتقدموا إلى الحوية قرب الطائف، وهزموا القواتِ الحجازية ودخلوا الطائفَ بعد انهيار قوات الشريف حسين في معركة الهدا، فأرسل الشريف إلى بريطانيا يطالبها بالتدخُّل وعدمِ السماح للملك عبدالعزيز بتكرارِ ما فعله الإخوان في الطائف في أماكن أخرى، ولكِنَّ بريطانيا أجابت بأنها تتمسَّكُ بالحياد وعدم التدخُّل في قضايا دينية بينهما، وأكَّدت لمندوب الحجاز أنها ستعملُ على حماية الرعايا الأجانب في الحجاز، وقد ذكَرَت عددٌ من المصادر الإعلامية في حينها بهتانًا وزورًا مشاهِدَ مُرعبة صُوِّرَت فيها وحشية الإخوان حال دخولِهم الطائِفَ، يقول جلال كشك المصري: (زحف الإخوان على الحجاز وذاب الجيش الهاشمي الذي التهمه الإخوان، وكانت معركة الطائف التي لعبت رويتر والمقطم وتايمس أوف أنديا وأجهزة الإعلام البريطانية والهاشمية دورًا كبيرًا فيما أُثير حولَ المعركة ونقَلَتْه كتابات المؤرخين دون تمحيصٍ، حتى بدت وكأنها غزوةٌ تَتَرية، وقد أجمعت المصادِرُ على أن جميعَ قتلى غزوة الطائف لا يتجاوزون 300 رجل داخِلَ وخارج المدينة، وهو أقل بكثير من ضحايا موقعة البكيرية مثلًا) وما أن بلغ الملك عبدالعزيز خبر دخول الإخوان الطائف حتى أمرهم بالتوقُّف وعدم دخول مكَّة."},{"id":4981,"title":"تنازل الشريف حسين عن الحكم لابنه علي .","date":["العام الهجري :1343","الشهر القمري : ربيع الأول","العام الميلادي :1924"],"text":"بعد دخول قوات الملك عبدالعزيز الطائفَ كتب أعضاءُ الحزب الوطني الحجازي من أشراف مكَّة وجُدَّة إلى الحسين يطلبون منه التنازُلَ عن الحُكمِ لولده علي، وبالفعل قرَّر الحسين التنازل ومغادرة الحجاز إلى العقبة مع أفراد أسرته، وأصبح علي بن الحسين ملكًا على الحجاز، وبويعَ بذلك، وهذا ما يشيرُ إلى انهيار الحكم الهاشمي في الحجاز عندما فقد الحسين حُلفاءَ الخارج (بريطانيا) وحُلَفاء الداخل (الأعيان والجيش)"},{"id":4982,"title":"دخول الإخوان (إخوان من أطاع الله) مكة بدون قتال ووصول الملك عبدالعزيز إليها .","date":["العام الهجري :1343","الشهر القمري : ربيع الأول","العام الميلادي :1924"],"text":"على الرغم من تنازُلِ الحسين لابنه علي فإنَّ الوضع في مكة لم يكن يسير لصالحِ الأشراف؛ لذلك غادر علي بن الحسين وحكومته مكةَ عندما تيقَّنوا عدم مقدرتهم منعَ قوات الإخوان عن دخول مكة بعد انهيار قوات الشريف في معركة الهدا. فتمكَّن الإخوان من دخول مكة بأسلحتِهم مُلَبِّين مُحرِمين بعُمرة بدون أي مقاومة تُذكَرُ، وأرسل قائدَا الإخوان سلطانُ بن بجاد وخالد بن لؤي رسائِلَ إلى معتمدِيِ الدول وقناصِلِها في جدة يخبرونَهم بدخولهم مكة، ويستفسرون عن موقِفِهم تجاه الحرب. فتلقَّوا ردًّا من معظم القناصل الأوروبية يُعلِمون سلطان بن بجاد بوقوفهم على الحياد التام إزاء الحرب القائمة في الحجاز، وفي 8 جمادى الأولى وصل الملك عبدالعزيز إلى مكة قادمًا من الرياض، فدخلها محرِمًا وأتاه أهلُ مكة مبايعين."},{"id":4983,"title":"تشكيل المجلس الأهلي بمكة .","date":["العام الهجري :1343","الشهر القمري : ربيع الأول","العام الميلادي :1924"],"text":"وجَّه الملك عبد العزيز بعد دخولِه مكَّةَ دعوةً لمجموعة من العلماء والأعيان فاجتمعوا، فقال يخاطبهم:\"إنَّ ديارًا كديارِكم تحتاجُ إلى اهتمامٍ زائدٍ في إدارة شؤونها، وعندنا مَثَلٌ يعرِفُه الناسُ جميعًا: أهلُ مكَّةَ أدرَى بشِعابِها. فأنتم أعلم ببلدِكم من البعيدين عنكم، وما أرى لكم أحسَنَ مِن أن تُلقى مسؤوليات الأعمال على عواتِقِكم، وأريد منكم أن تعَيِّنوا وقتًا تجتَمِعُ فيه نخبةٌ من العلماء والأعيان والتجَّار، وينتَخِبُ كُلُّ صِنفٍ مِن هؤلاء عددًا معيَّنًا كما ترتضون وتقرِّرون، وذلك بأوراق تمضونَها من المجتمعين بأنهم ارتضَوا أولئك النفر لإدارة مصالحهم العامة، والنظرِ في شؤونهم، ثم يستلمُ هؤلاء الأشخاص زمامَ الأمر، فيعيِّنون لأنفسهم أوقاتًا يجتمعون فيها، ويقرِّرون ما فيه المصلحة للبلد، وشكاياتُ الناسِ ومطالبُهم يجب أن يكونَ مرجِعُها هؤلاء النخبةَ من الناس. ويكونون أيضًا الواسطةَ بين الأهلين وبيني، فهم عيون لي وآذانٌ للناس يسمعون شكاويهم وينظرون فيها، ثم يراجعونني، وإني أريد ممن سيجتمعون لانتخاب الأشخاص المطلوبين أن يتحَرَّوا المصلحةَ العامة ويقدِّموها على كل شيء، فينتخبوا أهل الجدارة واللياقة الذين يغارون على المصالح العامة، ولا يقَدِّمون عليها مصالحهم الخاصة، ويكونون من أهل الغَيرة والحميَّة والتقوى، تجِدون بعض الحكومات تجعل لها مجالِسَ للاستشارة، ولكِنَّ كثيرًا من تلك المجالس وهمية أكثَرَ منها حقيقية، تشكَّلُ ليقال إنَّ هنالك مجالسَ وهيئات، ويكون العمل في يدٍ شخصٍ واحدٍ ويُنسَب العمل إلى العموم!! أمَّا أنا فلا أريد من هذا المجلس الذي أدعوكم لانتخابه أشكالًا وأوهامًا، وإنما أريد شكلًا حقيقيًّا يجتَمِعُ فيه رجال حقيقيون يعملون جهدَهم في تحرِّي المصلحة العامة. لا أريد أوهامًا، وإنما أريد حقائقَ. أريد رجالًا يعملون. فإذا اجتمع أولئك المنتَخَبون وأشكل عليَّ أمر من الأمور، رجعت إليهم في حَلِّه وعملتُ بمشورتهم. وتكون ذمتي سالمةً من المسؤوليات، وأريدُ منهم أن يعملوا بما يجِدون فيه المصلحة، وليس لأحدٍ مِن الذين هم أطرافي سلطةٌ عليهم ولا على غيرهم. أريد الصراحة في القول؛ لأن ثلاثةً أكرهُهم ولا أقبلُهم: رجلٌ كذابٌ يكذِبُ عليَّ عن عمدٍ، ورجلٌ ذو هوًى، ورجلٌ متمَلِّقٌ؛ فهؤلاء أبغضُ الناس عندي\" فعُقِد بعد ذلك اجتماع أسفر عن انتخاب 12 شخصًا تألف منهم مجلسٌ سمِّي المجلسَ الأهلي، وصدر بيان ملكي عُهِدَ فيه إلى المجلس بالنظر في نظام المحاكِمِ الشرعية، وتدقيق مسائل الأوقاف، ووضْع نظام للأمن الداخلي، وسَنِّ لوائح للبلدية والصحة العامة، ونشر التعليم الديني، وتعميم القراءة والكتابة، وتنظيم التجارة ووسائل البرق والبريد. واستمر العمَلُ في هذا المجلس إلى مطلع عام 1345هـ حيث حُلَّ المجلسُ الأهلي وشُكِّل بدلًا عنه مجلسُ للشورى."},{"id":4984,"title":"وفاة سيرلي ستاك سردار الجيش المصري وحاكم السودان العام .","date":["العام الهجري :1343","الشهر القمري : ربيع الآخر","العام الميلادي :1924"],"text":"هو سيرلي ستاك، سردار الجيش المصري وحاكم السودان العام، أحد موظَّفي الدفاع البريطانيين الكِبار، انتقل إلى قيادة الجيش المصري عام 1899، ثم عُيِّن قائدًا لقوة السودان عام 1902، ثم أصبح وكيلَ السودان ومديرَ المخابرات العسكرية. تقاعد عام 1910 وأصبح سكرتيرًا مدنيًّا لحكومة السودان، ثم عيِّنَ حاكِمًا عامًّا للسودان، وسردارًا للجيش المصري إلى أن قُتِلَ هذا العام، وكان قد قام باغتياله أحدُ الوطنيين المصريين، وعَقِبَ مقتله أعلنت حكومة سعد زغلول أسَفَها عن الحادث ووعدت بعقابِ المسؤولين عنه."},{"id":4985,"title":"عقد الملك عبدالعزيز البحث عن النفط شرق البلاد مع الشركة البريطانية .","date":["العام الهجري :1343","الشهر القمري : رمضان","العام الميلادي :1925"],"text":"مع اتساعِ رقعةِ ممتلكاتِ الملك عبدالعزيز وزيادةِ المصاريفِ على شؤون الدولة وقلَّةِ المواردِ، أخذ يبحَثُ عن مواردَ جديدةٍ؛ لتموين احتياجاتِ دولته الناشئة، فجاءت فكرةُ التنقيب عن النفط، فجَرَت مباحثاتٌ مع فرنك هولمز المغامر النيوزلندي الأصل، والضابط في الجيش البريطاني أثناء الحرب العالمية الأولى- مؤسِّس شركة الشرقية العامة في لندن، وقد حصل على عقد حَقِّ امتياز التنقيب عن النفطِ في الأحساءِ؛ لحساب شركته لمدة سنتين بقيمة 2000 جنيه استرليني، على مساحة 30 ألف ميل مربع، كإيجار سنوي قابلٍ للتجديد, ثم منحَ الملك عبدالعزيز حقَّ امتيازِ التنقيب في المنطقة المحايدة مع الكويتِ لهولمز في السنة التالية، واحتجَّت بريطانيا على العقدِ الأخير؛ بحُجَّة أنَّ حاكِمَ الكويت له حصة فيها، ولَمَّا أدركت بريطانيا عدمَ جدية شركة هولمز في التنقيب خَشِيَت أن يتاجر بترخيص التنقيب وبيعِه على شركاتِ نفط أمريكية، فأوعزت بريطانيا إلى شركة النفط أنكلو – فارسية؛ لتحتَجَّ على منح الامتياز لهولمز، فأرسلت الشركة أرنولد ويلسون ليتفاوضَ مع الملك عبدالعزيز في هذا الأمر، إلَّا أنه اعتذر بأنَّ أعيان نجد قد وافقوا على الامتيازِ لهولمز، ولا مجال لإلغائه، ثم طلب برسي كوكس المعتمد البريطاني في الخليج أن يرسِلَ الملك عبدالعزيز إلى هولمز كتابًا يؤكِّدُ فيه بأنه لا يستطيع البتَّ في طلب الامتياز قبل إجراءِ التحريات واستشارة الحكومة البريطانية في الأمر، إلا أن الملك عبدالعزيز رفض الطلب على الرغمِ مِن تَكرار كوكس الطلبَ ثلاثَ مرات وصمَّم بعد مشاورة معاونيه على منح هولمز الامتياز. كان الملك عبدالعزيز حريصًا على منح الامتياز لهولمز المستقل دون شركة إنكلو – فارسية الخاضعة لهيمنة الحكومة البريطانية؛ للبعد عن تحكُّم وسيطرة بريطانيا في الجانب الاقتصادي، خاصةً بعدما جرَّبَ وخبَرَ مراوغات بريطانيا معه في الجانب السياسي. إلا أنَّ هولمز لم يوفَّقْ إلى نتائج إيجابية طوال خمس سنوات، فاضطرَّ الملك عبدالعزيز لسحب الامتياز سنة، وأخذ في البحث عن الشركات الأمريكية، والتي بدأ تزايد اهتمامُها في المنطقة."},{"id":4986,"title":"رضا خان البهلوي ينصب نفسه شاهًا لإيران .","date":["العام الهجري :1343","الشهر القمري : ذي القعدة","العام الميلادي :1925"],"text":"كان رضا خان بهلوي من ضباط الجيش القاجاري، وسرعان ما أبدى كفاءةً عالية فأصبح قائدًا لفرقة القوزاق، وكان طموحًا جدًّا وفي غاية الذكاء. وكانت البلاد تترنَّح، فصمَّم على إنقاذها، فقام بانقلاب عسكري، وأسقط الوزارة سنة 1340 هـ/1921م وأسندها لسياسيٍّ إيراني شهير هو ضياء الدين طباطبائي، وذلك ليحكُمَ مِن ورائه، وتتوارى أهدافُه الديكتاتورية. فتولى وزارة الحربية ثمَّ رئاسة الوزراء، ثم خطا رضا خان خطوتَه الكبيرة في ربيع الأول عام 1344ه فأسقط الأسرةَ القاجارية، ونصَّب نفسه شاهًا لإيران، وهو أول ملوك الدولة البهلوية في إيران، وامتدت فترة حكمه من 1925 حتى 1941، وغيَّرَ اسم الدولة من فارس إلى إيران، وتنازل عن عرشه عام 1941؛ بسبب رفضه الانحيازَ للحلفاء في الحرب العالمية الثانية."},{"id":4987,"title":"نفي الشريف حسين إلى قبرص .","date":["العام الهجري :1343","الشهر القمري : ذي القعدة","العام الميلادي :1925"],"text":"بعد انتقالِ الشريف حسين إلى العَقَبة -جنوب الأردن- عَمِلَ على دعمِ ابنه علي في مواجهتِه للملك عبدالعزيز بإرسال الأموالِ والرجالِ، فغَضِبَ الملك عبدالعزيز وطلب من الإنجليز إخراجَ الحسين من العقبة، وإلا سيهاجمه هناك، فقررت بريطانيا نقْلَه إلى قبرص، فلما رفض الانتقالَ أقنعه ابنُه عبد الله بمغادرة العَقَبة وعدم إثارة المشكلاتِ مع بريطانيا، ومكث في قبرص 7 سنوات، ثم عاد منها بعد مرضه إلى عَمَّان سنة 1931م حيث توفِّيَ فيها في نفس السنة."},{"id":4988,"title":"الثورة السورية الكبرى (ثورة 1925م) ضد الاحتلال الفرنسي .","date":["العام الهجري :1343","الشهر القمري : ذي الحجة","العام الميلادي :1925"],"text":"في عام 1924 ألَّف الدكتور عبد الرحمن الشهبندر بدمشق حزبًا سياسيًّا سمَّاه حزب الشعب، وتولى رئاسته، وأطلق على نفسِه لقب الزعيم، وأخذ يعمَلُ في تنظيم العمل السياسي ويدعو إلى الوَحدة العربية، ويطالِبُ بإلغاء الانتداب، وإقامة جمهورية سورية في نطاق الاتحاد مع جميع البلدان العربية المستقِلَّة؛ ولتحقيق ذلك بدأ الدكتور عبد الرحمن الشهبندر الاتصالَ بزعماء ووجهاء المدن السورية يحثُّهم على الثورة ضِدَّ الاستعمار الفرنسي ويشحَذُ هِمَمهم ويعزِّز شعورهم الوطني، ويطلب منهم بدء الكفاح المسلَّح لنيل الاستقلال، وتحقيق الحلم الوطني العربي بإقامة الجمهورية السورية العربية، وقد جاءت الثورةُ السورية الكبرى كرَدِّ فعلٍ على السياسات الدكتاتورية العسكرية التي اتبعَتْها السلطات الفرنسية الاستعمارية، والمتمثِّلة في تمزيق سوريا إلى عدَّة دويلات، وإلغاء الحريات، وملاحقة الوطنيين، وإثارة النزعات الطائفية، ومحاربة الثقافة والطابع العربي للبلاد، ومحاولة إحلال الثقافة الفرنسية، بالإضافة إلى رفضِ سُلُطات الانتداب عَقْدَ اتفاق مع القوى الوطنية السورية لوضع برنامج زمني لاستقلال سوريا، انطلقت ثورة سوريا الكبرى في 29 ذي الحجة الموافق 21 تموز / يوليو، وانضَمَّ تحت لوائها عددٌ من المجاهدين من مختَلِف مناطق سوريا ولبنان والأردن، ومنهم دروز الجبل، وقد شَهِدت سوريا خمسًا وثلاثين ثورة قبل الثورة الكبرى، وقُتِلَ في تلك الثورات ما يقرُبُ من خمسة آلاف جندي فرنسي، وكان الدروز غائبين تمامًا عن كل تلك الثورات 35 ثورة، وبعد وفاة سليم الأطرش حاكِمِ جبل الدروز وتعيين حاكم فرنسي بدلًا عنه ناقضين اتفاقَهم مع زعماء الجبل الذين نفاهم الجنرال سراي بعد ذلك، فتمرد الدروز ووقعت معركةُ المزرعة؛ مما اضطر سراي أن يدخُلَ في مفاوضات مع الدروز لوقف القتال وإطلاق سراح الزعماء، ثم اتصل أعضاءُ حزب الشعب بزعماء الدروز في الجبل وقرَّروا التعاونَ للدفاع عن استقلال البلاد، وحثَّ الدكتور عبد الرحمن الشهبندر زعيمَ الدروز الجديدَ سلطانَ الأطرش على التقدُّم نحو دمشق ضِدَّ السلطات الفرنسية، فاشتعلت المعارِكُ حول دمشق وغوطتها والجبل وقراه، فأرسلت فرنسا الجنرالَ جاملان وعيَّنوه قائدًا عامًّا لجيش الشرق، فزحف نحو الجبل ولم يستطِع احتلال عاصمة الجبل السوداء، ثم نشبت ثورة حماة في تشرين الأول 1925م وانتشرت إلى دمشق وعمَّت أنحاء سوريا، وقُصفت قوات فرنسا في دمشق بعد أن اتَّسع نطاق حرب العصابات، فأطلق الفرنسيون نيرانَ مدافِعِهم وقنابل طائراتِهم على دمشق وأسواقها وأحيائها أيامًا وشهورًا خلال الثورة، واشتركت في هذه الثورة جميعُ الطوائف بما فيهم البدوُ، إلَّا أنَّ بعضَ الطوائف لم تشترك بالثورة، مثل النصيريين وسكان سنجق إسكندرون، وأغلبهم نصيرية، وكانت القواتُ الفرنسية تستعين في إخماد الثورات على الأقليات الذين جنَّدَتْهم للثورة، كالأرمن وبعض الشراكسة وبعض البدو الذين كان لهم ثأرٌ مع الدروز، ولكِنْ في أواخر أيام الثورة انضمَّ الدروز إلى السلطات الفرنسية تحت لواء قيادتهم عبد الغفار الأطرش ومتعب الأطرش، وتطوعوا في الجيش الفرنسي وأجهزة الأمن الفرنسية، وقد كانوا قبل ذلك في اللجنة العليا للثورة السورية التي أعلن المجاهِدونَ حَلَّها بعد هذه الخيانة، وأمَّا عموم النصارى فكان غالِبُهم وقف موقف المتفَرِّج، غير الذين كانوا يعملون في أجهزة الأمنِ الفرنسي، وكان النصارى في دمشق يضعون على منازلهم أقمشةً بيضاء عليها صليبٌ أحمر لِيَعرِفَ الطيارون أنها بيوت للنصارى فلا يقصِفونها، وأما الغوطة فقد كانت ملجأً للمجاهدين، فقام الفرنسيون بإحراق معظَمِ بساتينها، وفرضت السلطاتُ الفرنسية غراماتٍ مالية على الأهالي فوق القَصفِ العشوائي الذي استنكرته القناصِلُ، وهاجر كثيرٌ من أهل دمشق إلى بيروت ومصر وغيرها، واستمر مسلسل العنف والدمار إلى أيار 1926م، ثم حدثت مفاوضاتٌ مع بعض المسؤولين السوريين بَقِيَت قرابة التسعة أشهر، لكِنْ دون نتيجة، فعادت سياسةُ العنف والقصف والنهب للأحياء كما كانت."},{"id":4989,"title":"الاتحاد السوفيتي يعلن قيام جمهورية تركمانستان ويضمها إلى إمبراطوريته .","date":["العام الهجري :1344","العام الميلادي :1925"],"text":"كان الروسُ قد احتلُّوا جمهورية تركمانستان -من الشعوب التركية- في عام 1881م، ودخل الشيوعيون عاصمتَها عشق أباد في 1918م بعد مقاومة ضارية من السكان المسلمين، وفي عام 1918-1921م حارب التركمانُ البولشيفيين أثناء الثورة الروسية. وفي عام 1921م ضَمَّ البلاد إلى جمهورية تركستان الاشتراكية السوفيتية. وفي عام 1924م أصبحت تركمانستان جمهوريةً اشتراكية سوفيتية تابعةً إلى الاتحاد السوفيتي. وفي عام 1990م أصبحت التركمانية اللغةَ الرسمية بالبلاد، وأعلنت الدولةُ سيادتها ثم استقلالَها بموجِبِ استفتاء سنة 1991م فانضمَّت بذلك إلى اتحاد الدولِ المستقلة."},{"id":4990,"title":"أوضاع الحجاز بعد دخولها تحت حكم الملك عبدالعزيز .","date":["العام الهجري :1344","العام الميلادي :1925"],"text":"بعد أن ضَمَّ الملك عبدالعزيز الحجازَ حاول الإبقاء على النظام الإداري الذي وضعه المَلِكُ حسين في الحجاز، والتوفيق بين عُلماء الدين في نجد والحجاز، واستمَرَّت أعمال الشركات الأجنبية في الحجاز، وكان الوضعُ في الحجاز أكثَرَ تطورًا من نجد؛ حيث وجودُ الإدارة وَفقَ المعايير العثمانية والميزانية المالية، والجيش النظامي والمدارس على النظام الحديث حتى المرحلة الثانوية، كما كان يوجدُ في الحجاز صحيفة \"القبلة\" الناطقة باسم الحكومةِ، كما أدرك الملك عبدالعزيز أهميةَ إدخال الوسائل الحديثة للدولة من الهاتف والراديو والسيارة وغيرها، بعد أن اطَّلع على أثَرِها في الحياة العامة والخاصة، إلَّا أنَّ بعضَ هذه الوسائل الحديثة كانت مرفوضةً من بعض علماء نجد وإخوان من أطاع الله خاصة، كالهاتف والتلغراف والراديو، على أنها من أعمال \"الشيطان\". ومعظم شعوب العالم حتى في أوروبا استنكرتها في بدايتها ظنًّا منها أنَّها من أعمال السحر، ولكِنَّ الملك عبدالعزيز أصرَّ على استخدامها فانتشرت السيارة والتليفون  في البلاد، ثم قام الملكُ عبد العزيز بإجراء بعض التغييرات السياسية؛ فعيَّن ابنَه فيصلًا نائبًا للمَلِك في الحجاز في منتصف عام 1926م، وأصدر \"التعليمات الأساسية للمملكة الحجازية\" وهو كالدستور، حدَّد وضع نائب الملك، ومجلس الشورى، والإدارة العامة."},{"id":4991,"title":"ثورات الأكراد ضد سياسة التتريك في تركيا .","date":["العام الهجري :1344","العام الميلادي :1925"],"text":"في عام 1919م ساهم المثقَّفون والفئات الواعية من الأكراد في حركةِ التحرُّر الوطني التركية التي تزعَّمها مصطفى كمال (أتاتورك) ولا سيما من خلال جمعية الدفاع عن حقوقِ الأناضول الشرقي أي (كردستان تركيا)؛ اعتقادًا منهم بأن مساهمتَهم مع إخوانهم الأتراك في الكفاحِ ضِدَّ الاستعمار ستؤدِّي إلى نيل حقوقهم القومية، وحضر اجتماعَ المجلسِ الوطني التركيِّ الكبير في أنقرة عام 1920م اثنان وسبعون نائبًا كرديًّا تعاونوا مع مصطفى كمال كممثِّلين عن كردستان. ولم يتأخَّرْ مصطفى كمال والكماليون عمومًا في تقديم الوعود والعهود للأكراد لنَيلِ حقوقهم القومية، بل إن الكماليين كانوا يردِّدون بصوتٍ عالٍ بأن تركيا وطنُ الأتراك والأكراد: الأتراك والأكراد شركاءُ في هذا الوطن، ولكن ما إن استتَبَّ للكماليين الحكمُ في تركيا الجديدة حتى تنكَّروا لوعودهم وعهودهم للأكراد، وأعلنوا على لسان وزير العدل أنْ ليس لغير الأتراك في تركيا إلَّا أن يكونوا عبيدًا، ولم يعُدْ أمام الأكراد والحالة هذه إلا الثورةُ المسلَّحة دفاعًا عن وجودهم، فكانت ثورة 1925م بقيادة الشيخ سعيد بيران في ديار بكر، تلك الثورة التي لاقت صدًى قويًّا وعنيفًا ودمويًّا، وقد دلَّت الإحصائيات الأولية أن القواتِ التركية دمَّرت 8.757 بيتًا و206 قرية، وقتلوا حوالي نصف مليون كردي، وفي عام 1927م ثار الأكرادُ مرة أخرى بعد تشكيل حزب خويبون (الاستقلال) ثورة اندلعت أولًا في جبال آرارات بقيادة الجنرال إحسان نوري باشا، واستمرَّت هذه الثورة حتى عام 1930م حين استطاعت القواتُ التركية إجبار الثوار على اللجوء إلى إيران. وفي 1937م اندلعت ثورةٌ كردية في درسيم (شمال كردستان) قارعت الجيوش التركية نحو سنتين. وبعث أهالي درسيم إلى عُصبة الأمم في نوفمبر/ تشرين الثاني 1937م طلبًا يحتجُّون فيه على إجراءات الحكومة التركية بغَلقِ المدارس الكردية وتحريم استعمال اللُّغة الكردية، وحذف كلمتي كرد وكردستان من جميع المطبوعات والكتب، وتهجير الأكراد إلى مناطق تركيا. وأعلنت تركيا في عام 1946م بأنْ لا وجود في تركيا لأقليةٍ كردية."},{"id":4992,"title":"تطور التعليم في عهد الملك عبد العزيز  .","date":["العام الهجري :1344","العام الميلادي :1925"],"text":"في بدايةِ عَهدِ الملك عبد العزيز كان التعليمُ في معظم أنحاء الجزيرة العربية -عدا منطقتي الحجاز والأحساء اللَّتينِ كانتا تخضعان للحكم العثماني- يعتَمِدُ على النظام التقليدي (الكتاتيب)، ولم يكن في نجدٍ وما حولها أيُّ مدرسة نظامية، وإنما حلقات لدراسة العلوم الشرعية، والتاريخ واللغة في المساجد والجوامع والكتاتيب التي يُعلَّم فيها الأطفال في المنازل القراءة والكتابة وحفظ القرآن، وتمَّ فتحُ أول مدرسة في الرياض على يدِ الشيخ عبد الله آل الشيخ بعد أن عاد إلى نجدٍ من الحجاز، ثم ظهرت مدارسُ العلماء في منازلهم يهتمُّون فيها بحفظ القرآن الكريم، وتعلُّم أصول الفقه، والحديث، والعقيدة، والتاريخ، والسيرة، ويتخرج الطلبةُ من هذه المدارس على أساسِ العمَلِ في القضاء، وبعد ضَمِّ الحجاز أُعجِبَ الملك عبد العزيز بنظام التعليم الحجازي، فأسَّس في هذا العام إدارةَ المعارف العامة التي جَلَبت المعلمين من الدول العربية، وتأسَّس في نفس العام 12 مدرسة حكومية وأهلية في الرياض وما حولها، ثم انتشرت في المدنِ الكبيرة، وما إن حَلَّ عقدُ السبعينيات الهجري حتى أصبح عددُ المدارس الابتدائية 90 مدرسة، و10 مدارس ثانوية، و50 مدرسة في القرى يَدرُسُ فيها 16 ألف طالب، ثم توسَّع التعليمُ في المملكة بتوسُّع مناهجه وأساليبه، وفتح مدارس لتعليم البنات، وإرسال البعثات الطلابية للخارج، واستقدام الكفاءات العربية والأجنبية، وأُنشِئَت كلية الشريعة في مكة عام 1365هـ."},{"id":4993,"title":"التعليم في عهد الملك عبد العزيز .","date":["العام الهجري :1344","العام الميلادي :1925"],"text":"لَمَّا رأى المَلِكُ نمطَ التعليم المنتَشِر في الحجاز أُعجِبَ به، فأُنشِئَت في مكة إدارةُ المعارف العامة، وربَطَها بالنائب العام، ويديرُ أعمالَها مديرٌ عام، وكان من أبرز المشاكِلِ التي واجهت إدارةَ المعارف خلوُّ المدارس الابتدائية من المعلِّمين (المتعلِّمين) فأنشأت الإدارةُ في مكَّةَ المعهدَ العلميَّ السعوديَّ لإعداد معلِّمي المرحلة الابتدائية، بالإضافةِ إلى إرسال أوَّلِ بَعثةٍ مِن الطلاب إلى الخارج عام 1346هـ، وفي عام 1354هـ أُنشِئَت مدرسة تحضير البعثات، ووضِعَ لها منهجٌ خاصٌّ أُخِذَ مِن مصر، مدَّةُ الدراسة فيها 4 سنوات للقسم العام، و5 سنوات للقسم الخاص، بحيث يضمَنُ حامِلُ شهادة المدرسة التحضيرية للبعثات القبولَ في المعاهِدِ العالية وكليات الجامعة في مصر وغيرها، وأمَّا المطاوعة أو المرشِدون في الهجر والقبائل فهم غالبًا يُختارون من متعلِّمي الهجر والمدن القريبة من القبائل، وأوَّلُ ما عليهم تعلُّمُ القرآن، وأركان الإسلام، والعبادات، ومبادئ القراءة والكتابة، ولا يقتَصِرُ عملُ المطوع والمرشِد على التعليم، بل هو واعِظُ القبيلة وخطيبُ المسجد والإمامُ في الصلوات، وقد يكون المرجِعَ الديني في كل شيءٍ، وله رأيٌ مسموعٌ في شؤون القبيلة العامة والخاصة. كما أنَّ للتعليم الأهلي دورَه في نهضة البلاد الحديثة في ذلك العهدِ، بحيث إنَّ مُعظَمَ القائمين بالأعمال في الدوائر الحكومية من خرِّيجي المدارس الأهلية التي أُنشِئَت في الحجاز قبل عهد الملك عبد العزيز وفي عهده. كما أنشأ الملكُ عبد العزيز مدرسةَ الأمراء في قَصرِه لتعليم الأمراء من أبنائِه وأحفادِه وأبناء إخوانِه، ومن يليهم من الأُسَر السعودية، وأنشأ مثلها مدرسةَ للأيتام تابعة لإدارة القصر الملكي في بناية خاصة، ولَمَّا عاد الملِكُ من زيارته لمصر أراد أهلُ الرياض إقامةَ حفلة استقبال له، فأمرهم أن يصرفوا الأموالَ التي جمعوها على ما فيه مصلحةٌ للبلدِ، فاتفقوا على إنشاء مدرسةٍ في حي البطحاء في الرياض، سُمِّيَت المدرسة التذكارية، وأنشأ الأمير فيصل في الطائف المدرسةَ النموذجية لأولاد الأمراء وغيرهم، ثمَّ نُقِلَت إلى جُدَّة وسُمِّيَت مدارسَ الثغر النموذجية، أمَّا في نجد وشرق البلاد فلم تظهَرِ المدارس النظامية الحديثة فيها إلا بعد عام 1350هـ، وكان فتحُ المدارس في بعض المدن يتدرَّجُ نمو التعليم فيها ببطءٍ؛ لقلة المعلِّمين المتعلمين أولًا، ولِضَعفِ رغبة الأهالي في الإقبال على هذا النظام التعليميِّ الحديث، لكنْ ما إن دخلت سنة 1369هـ/ 1950م حتى كان عددُ مدارس نجد 84 مدرسة يَدرُسُ فيها أكثر من 8 آلاف طالب. وكان أعلى رقم لميزانية المعارِف في آخر ميزانية وُضِعَت في عهد الملك عبد العزيز سنة 1373هـ 20 مليون ريال سعودي يعادل 4.5 مليون دولار. كان التعليمُ في جميع المراحل مجانيًّا: تدريسًا وكتبًا ودفاترَ وأقلامًا، فضلًا عن أن الدولة كانت تنفق على نحو 30 % من التلاميذ على المأوى والطعام والملبس قياسًا على طلبة البعثات في الخارجِ، ويكثُرُ هذا النوع على الخصوص في المُدُن والقرى القريبة من البادية، حيث يؤتى بالطلابِ من خيامِ قبائِلِهم ومِن رعيِ إبلِهم، وربما دفعت الدولةُ لآبائهم مكافأةً عن عمل البنين في الرَّعيِ أو الزراعة، وكانت تُصرَفُ مثل هذه التعويضات لآباء بعض المبتَعَثين إلى الخارج، وقد تُصرَفُ مكافأة لبعض الطلاب الذين يظهر للحكومة أنَّ مقدرتهم المالية لا تساعِدُهم على الاستمرار في الدراسة، وقد تولى إدارةَ المعارف قبل أن تصبِحَ وزارةً: صالح شطا، ومحمد كامل قصاب، وماجد الكردي، وحافظ وهبة، ومحمد أمين فودة، وطاهر الدباغ، وآخِرُهم محمد بن عبد العزيز بن مانع."},{"id":4994,"title":"تشكيل الوزارات والإدارات الحكومية الحديثة في نجد والحجاز .","date":["العام الهجري :1344","العام الميلادي :1925"],"text":"بعد أن استقَرَّ الوضعُ في الحجاز للملك عبد العزيز بدأ بإدخال التنظيمات الحديثة في إدارة مملكة الحجاز ونجد وملحقاتها، مستفيدًا من بعض الشخصيات العربية الموجودة في الحجاز، كما استقطب شخصياتٍ أخرى من عدد من الدول العربية ذات خبرة إدارية وسياسية وإعلامية؛ فتأسَّست عام 1343هـ إدارة الأمن العام، ثم أصبحت مديرية الشرطة العامة لحماية الأخلاق والتفتيش والمحاسبة ومراقبة الأجانب، ولها إداراتٌ في كل مدينة وناحية،كما تمَّ في هذا العام إنشاء مصلحة الصحة العامة، ثم أصبح في كلِّ مدينة وإقليم إداراتٌ للصحة، وفي عام 1344هـ أنشئت مديرية الشؤون الخارجية، وبلدية مكة المكرمة، ثم إدارة لشؤون الخزانة في الرياض، ويتبع لها في كلِّ مدينة إدارةٌ لجباية الزكاة محاسَبةٌ أمام الملك، ثم في عام 1345هـ أنشئت المديرية المالية العامة، وفي عام 1347هـ أصبحت وكالة، وفي عام 1351هـ تحوَّلت إلى وزارة مالية لها صلاحيات واسعة، ورُبِطَت بالوزارة إداراتُ التموين والحج والزراعة والأشغال العامة والنفط والمعادن الأخرى، وكان فيها خبراءُ مِن عدة جنسيات عربية، وفي عام 1350هـ أنشئت مديرية خفر السواحل في جُدة، وأُوكِلَ لها شؤونُ الموانئ وخفر السواحل، ومكافحة التهريب وتنظيم الملاحة، وفي عامي 1344 و1345 صدرت أوامِرُ مَلَكية لإنشاء نظام قضائي موحَّد للدولة، وتأسَّست في الحجاز ثلاثةُ أنواع من المحاكم: المستعجلة، والكبرى، والاستئناف، وكان أول ظهور لدوائر كتاب العدل في الحجاز عام 1345هـ، وفي عام 1344 تأسَّس في جدة المجلِسُ التجاري الذي تحوَّل في عام 1349ه إلى محاكم تجارية تعمَلُ وَفقَ نظام التجارة الذي وُضِعَ على نمط الدولة العثمانية، واستُثنيَت منه القضايا التي تخضع لأحكام الشرع, وبعد توحيد المملكة عام 1351هـ أصبحت الإدارة في حالِ تشكُّل مؤقَّت إلى حين وضعِ تشكيلات جديدة للمملكة، وقد كُلِّف مجلس الوزراء في الحجاز بوضعِ النظام الأساسي (الدستور) ونظامِ الحُكم والإدارات. وكان يتِمُّ اختيار الأشخاص للمهامِّ السياسية والإدارية حسَبَ المعرفة الشخصية أو الكفاءة والثقة؛ بحيث يظلُّ المسؤولون والوزراء عدَّةَ سنوات، مثل عبد الله السليمان نجدي، ويوسف ياسين:سوري، وحافظ وهبة: مصري، مستشارونَ للملك في الشؤون الخارجية، والأول: سكرتير للملك، ثم وزير للدولة، والثاني: مديرٌ للمعارف، وممثِّلٌ للسعودية في إيطاليا، ثم سفيرٌ في لندن، وعبد الله الدملوجي: عراقي، يجيد التحدث بالإنجليزية والفرنسية، مستشارٌ للملك، ويقوم باستقبال الضيوف في البلاط الملكي، ثم أصبح ممثلًا للملك في جدة، ونائبًا لوزير الخارجية، وفؤاد حمزة: فلسطيني، عمل في وزارة الخارجية كمستشار للملك."},{"id":4995,"title":"تطور القطاع العسكري بعد ضم الملك عبدالعزيز الحجاز إليه .","date":["العام الهجري :1344","العام الميلادي :1925"],"text":"كانت قواتُ الملك عبد العزيز في نجد تتشكَّلُ مِن كلِّ فردٍ محاربٍ يحمِلُ السِّلاحَ من سنِّ 13 إلى سن 70، وتنقسِمُ إلى عدة أقسام: أهل العارض، والحضر، والإخوان (إخوان من أطاع الله)، والبدو، وكان الحرسُ الملكي (جيش الجهاد) من أهل العارض يتولى حمايةَ الملك والأمراء والأسرة المالكة، وكان مع جيشِ الجهاد جيشُ الإخوان من قبائل البادية الرحُّل، والتي تحولت الهجر فيه إلى ثكناتٍ عسكرية، وظلَّ هذا النظام قائمًا حتى عام 1349؛ حيث سعى الملك عبد العزيز إلى تطويرِ الجيشِ بإقامةِ إدارةٍ عسكريةٍ حديثةٍ، كنواةٍ للجيش النظامي، وبعد دخولِ الحجاز تحت حكم عبد العزيز ضمَّ إليه ضباطَ الجيش الهاشمي، وشكَّل منهم نواةَ الجيش النظامي، واستقدم ضباطًا من سوريا والعراق للعمل في الدائرة العسكرية، وشَهِدت جدة عام 1349هـ أوَّلَ استعراض عسكري شاركت فيه أفواجٌ مِن المدفعية والرشاشات والمشاة إلى جانب جيش الجهاد والإخوان، ثم أُلغِيَت تشكيلاتُ الهجَّانة التي تعتمد على الجمال والتشكيلات غير النظامية، وجُعِلت القوات على ثلاثة صنوف: سلاح المشاة، وسلاح المدفعية، وسلاح الفرسان, وتم تنظيمُ الجيش على شكل كتائب وألوية تمَّ توزيعها على خمس مناطِقَ عسكرية، كما تمَّ توحيدُ الزيِّ العسكري وإشارات الرُّتَب العسكرية، وافتُتِحَت في الطائف أول مدرسة عسكرية، وفي عام 1350هـ تم إرسال عددٍ من الطلاب لدراسة الطيران في الخارج، وتمَّ شراء أربع طائرات ذات المحرِّك الواحد، ثم أُنشِئَت إدارة طائرات الخطوط السعودية التي ألحِقَت لاحقًا بوزارة الدفاع، وبعد الحرب العالمية الثانية تم شراءُ خمس طائرات أمريكية من طراز داكوتا، ثم شراء تسع أخرى، وبدأت حركةُ الطيران المدني على الصعيد الخارجي، وفي عام 1353هـ أُسِّسَت مديرية الأمور العسكرية، ووكالة الدفاع، ومقَرُّها في الطائف، وفي عام 1359هـ ألغيت المديرية العسكرية، وشُكِّلَت في العام التالي رئاسةُ الأركان الحربية، وفي عام 1363ه أنشئت وزارة الدفاع وتولَّاها الأمير منصور بن عبد العزيز، وهو أول وزير لها، ولما توفي سنة 1370 تولَّى منصب الوزارة فيها الأميرُ مشعل بن عبد العزيز, وأنشِئَت في الطائف مدرسةُ الطيران، وصعِدَ الملك عبد العزيز الطائرةَ أول مرة في 8 ذي القعدة 1364هـ. كما تمَّ إنشاء مدارس لتعليم اللاسلكي في مكة وجدة والمدينة والرياض؛ لأهميته في العمليات العسكرية، وأُرسِلَ الخريجون الأوائل إلى بريطانيا ودول أوروبية أخرى؛ لمواصلة الدراسة حتى فتح 60 مركزًا لاسلكيًّا، وبهذا فإنَّ المؤسسة العسكرية النظامية تطوَّرت بمرور الزمن خاصةً بعد الحرب العالمية الثانية مع تطور العسكرية الغربية، والاتصال بالأوربيين، وظهور الحاجة لتطوير الجيشِ وتحديثِه وتنوُّع أصنافه وأساليبه ومهامه من حرس ملكي، إلى جيش الجهاد، ثم جيش الهجانة من البدو المخلصين للملك، إلى سلاحِ الطيران."},{"id":4996,"title":"نهاية دولة القاجاريين وبدء الأسرة البهلوية وأولهم رضا بهلوي ملكًا لإيران .","date":["العام الهجري :1344","الشهر القمري : ربيع الأول","العام الميلادي :1925"],"text":"كان أحمد شاه من الأسرة القاجارية ملك بلاد فارس (إيران) عندما أُلغيت الخلافة الإسلامية سنة 1342ه. وكان أحمد شاه منصرفًا إلى اللهو، وأما المتصَرِّف الفعلي في البلاد فهو رئيس الوزراء رضا بهلوي، وهو يتلاعَبُ بالكُتَل النيابية كيف يشاء، والمهيمِن على الوضع، واستمر الأمرُ على ذلك حتى قدَّم في 12 ربيع الأول نائبُ رئيس المجلس النيابي محمد تدين زعيمُ حزب التجديد نداء موقعًا من ستة وسبعين نائبًا جاء فيه: نظرًا لاستياء الشعب من الأسرة القاجارية، فإنَّه يعلِنُ باسم الشعب خلْعَ تلك الأسرة ويعهَدُ بإدارة البلاد إلى رضا خان بهلوي في إطار الدستور والقوانين المرعية، وبعد يومين جرى التصويتُ على الاقتراح فحصل على ثمانين صوتًا مقابل خمسة، وقرَّر المجلس إجراءَ انتخابات جديدة كردٍّ على الاقتراح، واستفتاء لرأي الشعب، وأُلزمَ ولي العهد مع عددٍ من أفراد أسرته القاجارية على السفر، ونُقِلوا إلى الحدود العراقية، وانتُخِبَ رضا بهلوي شاهًا من قبل مجلِسِه النيابي في 27 جمادى الأولى، وبعد ثلاثة أيام أقسم اليمينَ الدستورية ولبس التاج في 13 شوال، وبذلك زال ملكُ القاجاريين وزالت دولتُهم بعد أن بقيت مائة وأربعة وثلاثين عامًا وأربعة أشهر وأيامًا، وجاءت الأسرة البهلوية بدلًا منها لحكم بلاد فارس."},{"id":4997,"title":"تنازل مصر لليبيا عن واحة جغبوب .","date":["العام الهجري :1344","الشهر القمري : جمادى الأولى","العام الميلادي :1925"],"text":"تنازلت مصر لليبيا عن واحة جغبوب التي كانت من معاقِلِ الدعوة السنوسية، وذلك بإيعازٍ مِن بريطانيا، وتمَّ بعدها بأيامٍ عَقدُ اتفاق بين كلٍّ من إنجلترا وإيطاليا في 20 جمادى الأولى 1344هـ والذي تمَّ بمقتضاه النزولُ عن واحة جغبوب وضَمُّها مع أجزاء أخرى من غربِ مِصرَ إلى ليبيا التي كانت تحت الاحتلالِ الإيطالي."},{"id":4998,"title":"مبايعة الملك عبدالعزيز ملكًا على الحجاز وسلطان نجد وملحقاتهما .","date":["العام الهجري :1344","الشهر القمري : جمادى الآخرة","العام الميلادي :1926"],"text":"عُقِدَ اجتماعٌ بين أعيان الحجاز وخاصةً جدة، وتقرر فيه مبايعة الحجازيين عبدَ العزيز بن سعود الذي أعلن نفسه ملكًا على الحجاز وسلطان نجد وملحقاتهما، وكان قد انتزع مكَّةَ من الشريف حسين بن علي."},{"id":4999,"title":"استسلام جدة للملك عبدالعزيز بن سعود سلطان نجد وملحقاتها .","date":["العام الهجري :1344","الشهر القمري : جمادى الآخرة","العام الميلادي :1926"],"text":"انتقل المَلِكُ علي بن الحسين إلى جُدَّة قبل دخول قوات الإخوان  (إخوان من أطاع الله) مكة، واتخذها عاصمة لمملكته، ولَمَّا استقر الملك عبدالعزيز في مكة حاول أن ينهيَ قضية جُدَّة مع علي بن الحسين بالسِّلمِ، لكِنَّه رفض، ففرض السلطانُ الحصارَ عليه في الوقت الذي كان قادة الإخوان (إخوان من أطاع الله) يطالبون وبشدةٍ اقتحام جدة مع تقديم الضمانات بالمحافظة على سلامة الرعايا الأجانب وقناصِلِهم، لكِنَّه رُفِض طلبُهم، واستمر الحصار سنةً إلى أن قبِلَ علي بن الحسين الاستسلامَ بوساطة بريطانية، وتم التوقيعُ على شروط الاستسلام والذي يتضمَّنُ تسليمَ علي بن الحسين جدَّة للسلطان عبد العزيز، والاعتراف به سلطانًا على نجد ومكة مقابِلَ أن يخرج منها مع أسرته وأمواله ورجالِه وحاشيته سالِمين، وضمان سلامة الرعية، وإصدار عفوٍ عام لهم، ويمثِّلُ هذا الاستسلام نهايةَ حكم الهاشميين في الحجاز."},{"id":5000,"title":"إصدار الحكومة التركية قرارًا بقراءة القرآن الكريم باللغة التركية .","date":["العام الهجري :1344","الشهر القمري : رجب","العام الميلادي :1926"],"text":"قرَّرت الحكومة التركية بقيادة مصطفى كمال أتاتورك قراءةَ القرآن الكريم باللغة التركية بدلًا من العربية!! وكان حجَّتُها في ذلك أنَّ الأتراك لا يستطيعون تلفُّظَ وكتابة بعضِ الحروف العربية!!"},{"id":5001,"title":"الاتحاد السوفيتي أول بلد يعترف بمملكة الحجاز الجديدة .","date":["العام الهجري :1344","الشهر القمري : شعبان","العام الميلادي :1926"],"text":"كان الاتحادُ السوفيتي أوَّلَ بلدٍ اعترف بالمملكة الجديدة، وسُلِّمَت مذكِّرةٌ إلى الملك عبدالعزيز بهذا الخصوص"},{"id":5002,"title":"عقد المؤتمر الإسلامي بمكة  .","date":["العام الهجري :1344","الشهر القمري : ذي الحجة","العام الميلادي :1926"],"text":"دعا المَلِك عبد العزيز بن سعود مَلِكُ الحجاز وسلطان نجد وملحقاتهما إلى عقدِ مؤتمر إسلامي عالميٍّ في مكة بعد أداء فريضة الحج؛ للبحث في شؤون المسلمين، واقتراح سُبُل توحيد كلمتهم، والنَّظَر في مختلف المشكلات والقضايا الإسلامية، ولم تكُن الخلافةُ مدرجةً في جدول أعمالِه، ولَبَّت الدعوةَ أقطارٌ إسلامية كثيرة، وبدأ المؤتمَرُ جلساته، وألقى الملك كَلِمتَه التي تعهَّد فيها بأنه سيرعى الأماكِنَ المقدَّسة، وسوف يهيئ الظروفَ الأفضل للحجاج، كما أكَّد أنَّه سَيِّد الحجاز ونجد، ولن يسمَحَ بتدخُّل أي جهة في شؤون الحجاز، ووافق أغلبية المشاركين على ما نادى به، وأكدت بريطانيا اعترافها به مَلِكًا على الحجاز وسلطانًا على نجد وملحقاتها."},{"id":5003,"title":"المحمل المصري وموقف  إخوان من أطاع الله  منه .","date":["العام الهجري :1344","الشهر القمري : ذي الحجة","العام الميلادي :1926"],"text":"في موسِمِ حَجِّ تلك السَّنةِ، في اليومِ الأوَّلِ مِن عيدِ الأضحى،رأى الإخوان  (إخوان من أطاع الله) المحمَلَ القادِمَ مع الحجِّ المصري على جملٍ يتهادى بين الجموع، تحيطُ به موسيقاه وعساكِرُه، فقاموا يرشقونَه بالحجارة وهم بملابسِ الإحرام، ولم يكنْ مِن أمير الحج المصريِّ إلَّا أنْ أمَرَ بنَصبِ المدافع والرشَّاشات وإطلاق نيرانها على جموعِ الإخوانِ (إخوان من أطاع الله)، فقتل منهم خمسةً، وجرح آخَرون، ولَمَّا علم عبد العزيز بالخبر نهض من سرادِقِه، وأسرع يعدو إلى أن توسَّطَ بين الإخوان ونار الجند، وبَسَط ذراعيه يصيح: أنا عبد العزيز، أنا عبد العزيز، فهدأ إطلاقُ النار، وتدخَّل الجندُ السعودي، وانكَفَّ النَّاسُ، وأمَرَ بحجزِ المحمَلِ عن الأنظار، وترتَّبَ على هذا الحَدَث قَطعُ العلاقةِ مع مصرَ، وغضب الإخوان لأنَّه لم يقدِّمْ أميرَ الحجِّ المصري للشَّرعِ لِيُحاكمَ على قتله خمسةِ رجالٍ منهم وجَرْح آخرين."},{"id":5004,"title":"عقد مؤتمرات إسلامية لإحياء مؤسسة الخلافة الإسلامية .","date":["العام الهجري :1345","العام الميلادي :1926"],"text":"أدَّى سقوط الخلافة الإسلامية عام 1342هـ/ 1924م لانعقاد عدَّة مؤتمرات، وهي على وجه التحديد: مؤتمر مكة المكرمة عام 1342هـ/ 1924م، ومؤتمر الخلافة بمصر عام 1344هـ / 1926م، ثم مؤتمَر العالم الإسلامي بمكة المكرمة عام 1926م، ومؤتمر القدس عام 1349هـ / 1931م. وكان الهدفُ من هذه المؤتمرات إحياءَ مؤسسة الخلافة، ثم تعدَّدت أهدافها إلى إيجادِ شَكلٍ من أشكال الانعقاد المنتَظِم، وصولًا إلى منظمة إسلامية دائمة، إلَّا أن هذه الغاية لم يُكتَب لها النجاحُ؛ لأسباب عدة، منها: تفاقم الخلافات بين كثير من الأقطار الإسلامية، وخضوعُ مُعظَمِها للاستعمار في ذلك الحين؛ حيث لم يكن مسموحًا لها التعَرُّض للمصالح الاستعمارية على أيِّ نحو كان."},{"id":5005,"title":"معاهدة مكة بين الإدريسي والملك عبدالعزيز لحماية جازان .","date":["العام الهجري :1345","العام الميلادي :1926"],"text":"كان السيد محمد بن علي بن أحمد الإدريسي قد أوصى المَلِكَ عبد العزيز بأولاده من بعده، فلما دَبَّ الخلاف بينهم بعد وفاته أرسل الملك عبد العزيز الأميرَ عبد العزيز بن مساعد بن جلوي فأنهى الصراع الذي نشب بينهم، وعَيَّن حسن الإدريسي بدلًا من أخيه علي، وعندما غزت قواتُ إمام اليمن يحيى حميد الدين تهامةَ عسير بقيادة عبد الله الوزير واحتَلَّ موانئ تهامة ومدنها، عين الإمامُ ولاتَه عليها، ثم واصل جيشُ الإمام يحيى تقدُّمَه صَوبَ عسير، وحاصر مدينتي صبيا وجازان، فعرض عليه حسن الإدريسي صُلحًا يقضي بكفِّ قواته عن محاولة الاستيلاء على مدينتي صبيا وجازان، مقابِلَ اعتراف الأدارسة بولائهم للإمام، على أن يمنح الإمامُ الأدارسة نفوذًا محليًّا على تهامة، ولكِنَّ الإمام يحيى رفض العرض، وأصر على مواصلة محاولة الاستيلاء على منطقة عسير؛ مما حمل حسن الإدريسي على توقيع معاهدة حماية مع الملك عبد العزيز، عُرِفَت بمعاهدة مكة التي أصبحت بموجِبِها تهامة عسير تحت الإشراف السعودي أو الحماية السعودية."},{"id":5006,"title":"إنشاء أول مجلس شورى في الحجاز .","date":["العام الهجري :1345","العام الميلادي :1926"],"text":"لَمَّا صَدَرت التعليماتُ الأساسيَّةُ للمملكة الحجازية تألَّفَ بمقتضاه أوَّلُ مجلِسٍ للشورى مؤلَّف من النائب العام ومستشاريه، ومن ستة ذوات يعيَّنون من قِبَل صاحب الجلالة المَلِك ممَّن فيهم اللياقة والاقتدار، ويرأسُه النائب العام الأمير فيصل، أو معاوِنُه، أو أحد مستشاريه، وبيَّن الأميرُ فيصل في كلمته الافتتاحية للمجلس مهامَّ واختصاصات هذا المجلسِ."},{"id":5007,"title":"قطع العلاقة بين مصر ومملكة الحجاز  .","date":["العام الهجري :1345","الشهر القمري : محرم","العام الميلادي :1926"],"text":"بعد حادثةِ المحمَلِ في حَجِّ العام الماضي بمَنْعِ دخولِه مكَّةَ، أمر المَلِكُ فؤاد بقطع إرسالِ كِسوةِ الكعبة وريعِ أوقافِ الحرمين في الديار المصرية، وقَطْع العلاقة مع مملكةِ ابن سعود، وعلى الرَّغمِ أنَّ المَلِكَ عبد العزيز أرسل ابنَه سعودًا لمعالجة المشكلة وتصفية الجوِّ مع القصر الملكي إلَّا أنَّ الجفوةَ استمَرَّت بين مصر والسعودية، فدعا الملك عبد العزيز عام 1354 في حديثٍ له مع صحفيٍّ مصريٍّ إلى تحكيمِ الشَّرعِ في قضيةِ المحمَل، فقال: ولا خلافَ بيني وبين مصرَ، وأمرُ المحمَلِ متروكٌ إلى الدينِ وإلى حُكَّامِ الشَّرع.. وفي مِصرَ عُلَماءُ علينا أن نستفتيَهم، وأنا معهم فيما يأتونَ به من الكتابِ والسُّنَّة، وأبلِغْ مِصرَ عني أن حكومتي على استعدادٍ لكلِّ تساهل تطلبُه الحكومة المصرية يتَّفِقُ مع الشَّرعِ\" وظل البلدان متقاطعين رسميًّا إلى آخر أيام فؤاد، ودخل عليه رئيسُ ديوانه علي ماهر وهو يُحتَضَر، فقال: ألا تجعَلُ في صحيفتك عمَلَ الدخولِ في مفاوضة مع بلاد الحرمين الشريفين؟ فأشار: لا بأس، وبعد وفاة فؤاد سنة 1355هـ عُقِدَت معاهدةُ صداقة بين البلدين، وانقَشَعت غمامةُ الجفاء، وتبادل المَلِكُ عبد العزيز مع الملك فاروق بن فؤاد الزيارةَ بينهما."},{"id":5008,"title":"قيام مصطفى كمال أتاتورك بإلغاء الطرق الصوفية في تركيا .","date":["العام الهجري :1345","الشهر القمري : صفر","العام الميلادي :1926"],"text":"قام مصطفى كمال أتاتورك بإلغاء الطرُقِ الصوفية في تركيا، وذلك في محاولاته التي بدأها بإبعادِ تركيا عن الإسلامِ، وأيِّ مظهر من مظاهر التدين، وقَطْع كل السبل التي تربط تركيا بالإسلامِ أو بالمسلمين، وحتى الفِرَق المنحرفة، كالطُّرُقيَّة الصوفية لم تسلَمْ من بطشِ أتاتورك."},{"id":5009,"title":"صدور وثيقة التعليمات الأساسية للمملكة الحجازية  .","date":["العام الهجري :1345","الشهر القمري : صفر","العام الميلادي :1926"],"text":"أقام المَلِكُ عبد العزيز نظامًا للسُّلطةِ الإدارية، وأصدر وثيقةً باسم التعليمات الأساسية للمملكة الحجازية، وتُسَمَّى الدستور، ونصَّت على الارتباط الوثيق بين أجزاء المملكة الحجازية ومناطِقِها، وأنَّها دولةٌ مَلَكيةٌ شُوريةٌ إسلاميَّةٌ مُستَقِلةٌ، عاصِمتُها مكَّةُ، وإدارتها بيَدِ الملِكِ، وهو مقَيَّدٌ بأحكام الشَّرعِ، ونَصَّت الوثيقةُ على تعيين نائبٍ للملك في الحجاز، ورؤساء الشُّعَب التابعين له، وسِت شُعَب، هي: الشرعية، والداخلية، والخارجية، والمالية، والمعارف، والجيش؛ وتأسيس مجلس شورى، ومجالس إدارية في المدن."},{"id":5010,"title":"زيارة الأمير فيصل بن عبد العزيز الثانية لأوروبا .","date":["العام الهجري :1345","الشهر القمري : ربيع الأول","العام الميلادي :1926"],"text":"ما إن تم الاعتراف بالملك عبد العزيز مَلِكًا للحجاز وسلطانًا على نجد وملحقاتها حتى دعت بريطانيا نظيرتَها السعودية لإجراء مباحثات في لندن، كخطوة لتعزيز العلاقة بين البلدين، فأرسل الملك عبد العزيز ابنه فيصلًا ونائبه في الحجاز مرة أخرى إلى بريطانيا نيابةً عنه وكان عمره 22 سنة، وكان معه في الزيارة عبد الله الدملوجي مدير الشؤون الخارجية في مملكة الحجاز. وقد حَظِيَ الأمير فيصل باستقبال ضَخمٍ من قِبَل كبار المسؤولين البريطانيين، وظَلَّ هناك ثلاثة أسابيع، استقبل فيها الملك جورج الخامس وجميعَ وزرائه في القصر الملكي \"قصر بكنغهام\"، وأكد الملك جورج على قوة الروابط بين البلدين، وأثار الأمير فيصل قضية إعادة النظر في العلاقات بين البلدين، وأن معاهدة العقير 1915م لم تَعُد مناسبة للوضعِ الجديد للملك عبدالعزيز، ووجد فيصل موافقةً من الملك جورج لهذا الأمر، وأثناء الزيارة قام فيصل بجولاتٍ في المدن البريطانية، فزار المدارس والجامعات والمستشفيات والمصانع، ورأى مقدارَ التطوُّر العلمي والصناعي في أوروبا، وعَقَد اتفاقيات لتوريد الأسلحة والمعدَّات العسكرية للجيش السعودي، واتفاقيات لاستيراد المكائن الصناعية، ثم التقى فيصل بكبار المسؤولين الإنجليز، أمثال لويد جورج، وبرسي كوكس، ورينجينالد وينعيت، وهنري مكماهون، ثم غادر فيصل بريطانيا إلى باريس ثم هولندا."},{"id":5011,"title":"الامتيازات الأجنبية في الحجاز بعد دخولها تحت حكم الملك عبدالعزيز .","date":["العام الهجري :1345","الشهر القمري : شعبان","العام الميلادي :1927"],"text":"بعد أن ضمَّ  الملك عبدالعزيز الحجازَ عام 1344هـ رأى أنَّ من أولى الواجبات أن يعمَلَ على تأمين سلامة الحجاج، ويعيدَ ريعَ أوقاف الحرمين الموجودة في العالم الإسلامي، ويعمَلَ على تشغيل سكَّة حديد الحجاز، لكنه اصطدم بالامتيازاتِ التي يتمتَّعُ بها رعايا الدول الأوروبية، والتي حصلت عليه تلك الدولُ مِن خلال المعاهدات التي تمَّت بينها وبين الدولة العثمانية في جميعِ أراضي الدول العثمانية الواسعة، بحيث تُطَبِّقُ هذه الدول قوانينَها على مواطنيها في أراضي الدولة العثمانية، ولم يُستثْنَ الحجازُ في تلك المعاهدات على الرَّغمِ مِن خصوصيته؛ لوجود الحرمين والأماكن المقدسة، فكانت هذه المعاهداتُ تَكفُلُ للمواطن الأوروبي العادي من تلك الدولِ التمتُّعَ بامتيازاتٍ هي في الأساس تُمنَحُ للدبلوماسيين فحَسْبُ، في حين أنَّ السيادة الوطنية تتطلَّبُ خضوع الأجانب للقوانين والأنظمة السائدة في البلاد التي يقيم فيها؛ ولذلك وجدت قضيةُ الامتيازات الأجنبية في الحجاز طريقَها للعديد من القضايا المطروحة للتباحُثِ بين الطرفين الملك عبد العزيز وممثِّلي الحكومة البريطانية، وكان ممثِّلو بريطانيا قد عقدوا جلسةً في مارس 1926م أكَّدوا فيها ضرورة توطيد السلام في المنطقة، وحماية النفوذ البريطاني في سواحلها، وانتزاع اعتراف رسمي من عبد العزيز بمركز بريطانيا المتميِّز في فلسطين ومناطق الانتداب في العراق، وتأكيد التزام ابن سعود بعدمِ التدخُّل في شؤون مشيخات الخليج العربي، وأن يقَدِّمَ ضماناتٍ أكيدةً على حماية وحرية طرق الحج، وسلامة الرعايا المسلمين في أراضي الإمبراطورية البريطانية، والتعاون مع بريطانيا في محاربةِ تجارةِ الرقيق، والاعتراف من جانبه بنظام الامتيازات الأجنبية التي حصلت عليها بريطانيا من الدولة العثمانية، إلَّا أنَّ نقطة الامتيازات أثارت نقاشًا بين المسؤولين البريطانيين قبل أن يثيرها الملك عبدالعزيز معهم، فكان نائب الملك في الهند يحذِّرُ من التدخل في شؤون الأماكن المقدسة، وأن تتِمَّ المعاهدة مع ابن سعود من دونِ حاجةٍ لشروط تتعلَّقُ بالحجاز. ولَمَّا اتفقوا على التعَرُّف على موقف ابن سعود من هذه المسألة بإرسال جوردون وكيل القنصل البريطاني في جدة، ولَمَّا التقى به في وادي العقيق في خريف 1926م وعرض عليه مقترحاتِ الحكومة البريطانية الخاصة بالامتيازات الأجنبية في الحجاز رفَضَها ابنُ سعود وبشدَّةٍ، وأكَّدَ عليه أنَّ إدخال هذه القضية في المعاهدة المزمَع عَقدُها سوف يؤدِّي إلى إلحاق الضرر بالعلاقة بين البلدين، كما رفض ابنُ سعود فكرةَ تفضيل البريطانيين في الحجاز يقابِلُه تفضيل الرعايا السعوديين في بريطانيا، وأكد ابن سعود أنَّ المساواة أساسٌ بين المسلمين أثناء وجودِهم في أراضي الحجاز ونجد وما حولها, وبعد أن رفع جوردن تقريرَه عن المباحثات قرَّرت حكومته حذفَ الامتيازات من المعاهدة تمامًا، وفي فبراير 1927م تقرَّر استئنافُ المفاوضات مع الملك عبدالعزيز على أساس أنَّ بريطانيا حريصةٌ على إنجاحها والتوصُّل إلى إقامةِ علاقةٍ متينةٍ معه، وقدَّمت بعض التنازلات ضمانًا لنجاحها؛ إذ كانت قلقةً من الوجود السوفيتي في شبه الجزيرة العربية، ومِن القضايا التي تمَّ التباحثُ حولها رغبةُ بريطانيا في تسيير وإدامة المواصلات الجوية بينها وبين مملكة الحجاز ونجد؛ لأهمية ذلك في ترابُط أطراف الإمبراطورية البريطانية، وإقامة مركز وقود لتموين الطائرات في رأس السفانية، وتشييد محطتين للهبوط الاضطراري في الأحساءِ، إلا أن عبد العزيز اعترض على تشييد مطارات في تلك المنطقة تخصُّ الطيران البريطاني، كما هو الحال في صحراء العراق الجنوبية. وكان لهذه المباحثات بين الملك عبدالعزيز والبريطانيين أثرُها في صياغة معاهدة جُدة التي تم توقيعها بين الطرفين في ذي القعدة من هذا العام."},{"id":5012,"title":"وفاة الشيخ محمد الخضري صاحب الدراسات التاريخية الإسلامية .","date":["العام الهجري :1345","الشهر القمري : شوال","العام الميلادي :1927"],"text":"هو الشيخُ محمد بن عفيفي الباجوري، المعروف بالشيخ الخضري. باحث وخطيب من علماء الشريعة والأدب وتاريخ الإسلام، وهو صاحب الدراسات التاريخية الإسلامية. ولد بمصرَ سنة1289ه، وكانت إقامتُه في (الزيتون) من ضواحي القاهرة، تخرج بمدرسة دار العلوم، وعُيِّن قاضيًا شرعيًّا في الخرطوم، ثمَّ مدرسًا في مدرسة القضاء الشرعي بالقاهرة، مدة 12 سنة، وأستاذًا للتاريخ الإسلامي في الجامعة المصرية، فوكيلًا لمدرسة القضاء الشرعي، فمفتشًا بوزارة المعارف. ترك الخضري عدةَ مؤلفات تاريخية، منها: الدولة الأيوبية، الدولة العباسية، نور اليقين، تاريخ التشريع الإسلامي وأصول الفقه، وإتمام الوفاء في سيرة الخلفاء، ومحاضرات في تاريخ الأمم. توفي ودُفِن بالقاهرة."},{"id":5013,"title":"معاهدةُ جُدة بين حكومة بريطانيا وحكومة ملك الحجاز وملحقاتِها .","date":["العام الهجري :1345","الشهر القمري : ذي القعدة","العام الميلادي :1927"],"text":"تمَّت معاهدةُ جُدة بين حكومة بريطانيا وحكومة ملك الحجاز وملحقاتِها؛ لتوطيد العلاقة بينهما، وتأمين مصالحهما، وقد مثَّل بريطانيا جلبرت فلكنجهام كلايتن، بينما مثَّل حكومة ملك الحجاز وملحقاتها الأميرُ فيصل بن عبد العزيز نائب الملك في الحجاز، وأهم ما جاء في هذه المعاهدة: اعترافُ الحكومة البريطانية بالاستقلال التام لعبد العزيز آل سعود ملكًا على الحجاز ونجد، وتعهَّد الجانبان بالحفاظ على السلام والصداقة بينهما، وتعهَّد الملك عبد العزيز بتسهيل مهمَّة الحجاج من الرعايا البريطانيين إلى الديار المقدسة أسوةً بباقي الحجاج، واعترفت بريطانيا بالجنسية الحجازية النجدية لجميعِ رعايا هذه البلاد وملحقاتها خلالَ وجودِهم في بريطانيا أو في محميَّاتها، وتعهَّد الملك عبد العزيز بالحفاظ على العلاقات السِّلمية مع الكويت والبحرين ومشيخات ساحل عمان ومسقط وعُمان، الذين يرتبطون بمعاهدات مع بريطانيا، وأن يتعاونَ الطرفان للقضاء على تجارة الرقيق في الحجاز، وتم إلحاقُ الكتب التي تبودِلَت بين الملك عبد العزيز وكلايتون بالمعاهدة، خاصةً فيما يتعلَّقُ برغبة عبد العزيز في شراء وتوريد جميع الأسلحة والأدوات العسكرية والذخيرة من الأمور والحاجيات العسكرية التي يحتاجها؛ فقد أكد كلايتون أنَّ الحكومة البريطانية لا ترى ضرورةَ إيرادها في نص المعاهدة بعد أن تمَّ إلغاء قرار تحريم تصدير الأسلحة إلى المنطقة؛ وعليه فإن الملك عبد العزيز يمكن أن يستورد من السلاح ما يشاء على أنَّ بريطانيا تفَضِّل أن يتم الاتفاق مباشرة مع المنتجين البريطانيين للأسلحة. وبعد أن أصدر الملك عبد العزيز قرارَ تصديق المعاهدة وكذلك ملك بريطانيا جورج الخامس تبادل مديرُ الشؤون الخارجية الدكتور عبد الله الدملوجي مع القنصل البريطاني في جدة قراراتِ التصديق في 17 سبتمبر، وأصبحت المعاهدةُ نافذةَ المفعول من تاريخ التصديق لمدة سبع سنوات قابلة للتجديد على أساس الموافقة المتبادلة بينهما. وقد رحَّب العديد من الأوساط السياسية والصحفية العربية والبريطانية بعقد معاهدة جدة، وتم في المعاهدة إلغاءُ نظام الحماية والتبعية والقيود التي فرضتها معاهدةُ العقير عام 1915م. كان هَمُّ الملك عبد العزيز في هذه المعاهدة انتزاعَ اعتراف بريطانيا بسيادتِه على جميع المناطق التي ضمَّها تحت حُكمِه، وقد تحقَّق له ذلك كما تمَّ إلغاءُ الامتيازات الأجنبية في الحجاز والتي كان يتمتع بها الرعايا الأجانب دونَ غيرهم في القضاء والقانون الجنائي والمدني، ووضعت المعاهدة أساسًا جديدًا للمساواة في تطبيق القانون بين الأقليات في الحجاز. كما حصلت بريطانيا على استقرارِ الأمن والاستقلال في الساحل الشرقي بالحفاظ على علاقات سلام مع الكويت والبحرين وقطر وعمان التي تربطها ببريطانيا معاهدات حماية، كما ضَمِنَت بريطانيا بموجِبِ هذه المعاهدة سلامةَ حجِّ رعاياها في جميع مستعمراتها."},{"id":5014,"title":"وفاة سعد زغلول الملقب بزعيم نهضة مصر السياسية .","date":["العام الهجري :1346","الشهر القمري : صفر","العام الميلادي :1927"],"text":"هو سعدُ بنُ إبراهيم زغلول، لُقب بزعيم نهضة مصر السياسية، وكان من أبرز خطبائِها في عصره. ولِدَ في إبيانة من قرى الغربية في يوليو عام 1858م وتوفِّيَ والده وهو في الخامسة، التحق سعد زغلول في السابعة من عمره بكُتَّاب القرية، حيث مكث فيه خمس سنوات، تعلَّم فيه القراءة والكتابة، وحَفِظ القرآن الكريم في سنة 1873م. ثم انتقل سعد زغلول إلى القاهرة للالتحاق بالأزهر، وتتلمذ على يد الشيخ محمد عبده، ولازم جمالَ الدين الأفغاني مدة، واشتغل بالتحرير في جريدة الوقائع المصرية مع الشيخ محمد عبده، واشترك بالثورة العُرابية، وقُبِض عليه سنة 1299هـ بتهمة الاشتراك في جمعية سرية، قيل إنها تسعى لقلب نظام الحكومة، فسُجِن شهورًا، ثم أُفرِجَ عنه، وحصل على إجازة الحقوق، واشتغل بالمحاماةِ حتى اختيرَ قاضيًا ثم مستشارًا، ثم تولى وزارة المعارف، فالعدل، فوكالة رئاسة الجمعية التشريعية، وقاد مصر بعد الحرب العالمية الأولى فتسَلَّم رئاسة الوزراء، ورئاسة مجلس النواب، وقام بالثورات ضِدَّ الإنجليز وظهر في صورة البطل الذي عَمِلَ على استقلال البلاد، مع أنَّ كل ما كان يفعَلُه تحت مرأى ومسمع إنجلترا!! وكان منعه من العمل السياسي واعتقالُه ونفيُه أكثَرَ من مرة قد ساهم في جعله زعيمًا وطنيًّا نافس زعماء وطنيين مصريين، مثل: مصطفى كامل، وخليفته محمد فريد، بل قيل إن بريطانيا هي من كلَّفته بالعمل للسفر إلى باريس لعَرضِ قضية استقلال البلاد، ومع ذلك منعته من السفر، ثم نفته إلى مالطا؛ ليصبح بذلك بطلًا وزعيمًا وطنيًّا يُصَفِّق لكل قراراته الجمهورُ المصري!! وكانت زوجته صفية فهمي التي تُعرَف بصفية زغلول على مبدأ الغربِ، هي من قامت بحرق حجابها بعد أن خلعَتْه هي وهدى شعراوي في ميدان الإسماعيلية في إحدى المظاهرات المنَدِّدة بالاحتلال الإنجليزي لمصر خلال ثورة 1919م!! لَمَّا عاد سعد زغلول من بريطانيا سنة 1920م كبطل وزعيم قومي أُعِدَّ لاستقباله خيمتان كبيرتان: خيمة للرجال، وخيمة للنساء، ولَمَّا نزل من الطائرة بدلًا من أن يتجه إلى خيمة الرجال توجَّه إلى خيمة النساء، وكانت مليئة بالنساء المحجَّبات، فلما وصل الخيمة استقبلته هدى شعراوي أمام الناس جميعًا، وعليها حجابُها، فنزع حجابَها عن وجهها فصَفَّقَت هي وصَفَّق جميعُ النساء الحاضرات ونزَعْن حجابهن!!"},{"id":5015,"title":"هجوم الإخوان  (إخوان من أطاع الله) على مخفر بُصية في الحدود العراقية .","date":["العام الهجري :1346","الشهر القمري : ربيع الآخر","العام الميلادي :1927"],"text":"أقامت حكومةُ العراق بدعمٍ من الإنجليز مخفرًا على ماء بُصية في الحدود النجدية العراقية، وأعلنت رسميًّا عَزْمَها بناء حصون أخرى، ورأى الملك عبد العزيز في ذلك مخالفةً للمادة الثالثة من معاهدة العقير عام 1915م التي تنصُّ على عدم استخدام أيٍّ من الطرفين الآبار الموجودة على أطراف الحدود لأيِّ غرض حربي، كوضع قلاع عليها، أو تعبئتها بالجند، فاحتجَّ الملك عبد العزيز على هذا الخَرقِ الصريح للاتفاقيات المبرمة، ولكنَّه لم يتلقَّ بعد شهرٍ إلا إجابة فيها مراوغةٌ من المندوب البريطاني في العراق؛ لذلك بدأ فيصل الدويش بالهجومِ على المخفر فقد رأى أنَّ بناءَ حكومة العراق مخفر بُصَية ووعْدَها ببناء غيره على الحدود العراقية النجدية أمرًا يهَدِّدُ حياتَهم وأمْنَهم، ويحرِمُهم من آبار المياه التي لا غنى لهم عنها والتي يعتمدون عليها اعتمادًا كليًّا، فاتخذ قرارًا دون الرجوع إلى الإمام؛ لقناعته أن المفاوضات السلمية مع الإنجليز لن تأتيَ بنتيجة، فأرسل قوةً صغيرة هاجمت المخفر وقتَلَت من فيه من العمَّال والجنود الذين كانوا مكَلَّفين بحمايتهم، وبعد ثلاثة أشهر من حادثة البصية قام سِربُ طيران إنجليزي بقصف شمال نجد فألقت طائراتٌ إنجليزية قنابِلَ على هجرة اللصافة التابعة لقبيلة مطير، فدمرت مسجِدَها وبعض بيوتها، وأثار حالةً من الفزع بين بدوِ قبائل مطير، ولقي رجال وأطفال ونساء وحيوانات مصرعَهم من دون تمييزٍ."},{"id":5016,"title":"اكتشاف النفط في العراق  .","date":["العام الهجري :1346","الشهر القمري : ربيع الآخر","العام الميلادي :1927"],"text":"تم اكتشافُ النفط العراقي في عهد وزارة جعفر العسكري في كركوك يوم 18 ربيع الثاني من هذا العام، وبينما كان المهندسون والعمال يمارسون أعمالهم تدفَّق النفط وأدى إلى مقتَلِ عددٍ منهم."},{"id":5017,"title":"توقيع العراق مع إنجلترا معاهدة 1927م .","date":["العام الهجري :1346","الشهر القمري : جمادى الآخرة","العام الميلادي :1927"],"text":"كانت معاهدة 1922م والتي تمت المصادقة عليها في 12 يونيو 1924م قد لَقِيت معارضةً شديدة من العراقيين، وما زالت المعارضة لأنَّها تتضمن تكريسَ الانتداب والاحتلال البريطاني للعراق؛ فبدأ الجانبان مفاوضاتِهما لتعديل هذه المعاهدة في بغداد، ثم انتقلت المفاوضاتُ إلى لندن بإشراف الملك فيصل وإدارة جعفر العسكر، وتعَذَّرت المفاوضات بسبب عدم جِدِّية البريطانيين في تطوير الجيش العراقي، وأن المعاهدة دون معاهدة 1922م؛ ولذلك قاطع العسكر المفاوضاتِ وعاد من لندن، وتم التواصلُ بين فيصل وتشرشل لتسهيل عملية المفاوضات، ثم عاد العسكر إلى لندن وتمَّ التوقيعُ على معاهدة التي تضمَّنت الاعتراف باستقلال العراق، والوعد بتأييد انضمامِ العراق إلى عُصبة الأمم المتحدة في سنة 1932م، وفي مقابل ذلك تمنح العراق إنجلترا ثلاث قواعِدَ جوية جديدة، وأن يقومَ الضباط الإنجليز بتدريبِ الجيش العراقي."},{"id":5018,"title":"المعاهدة الأردنية البريطانية بدل صك الانتداب .","date":["العام الهجري :1346","الشهر القمري : شعبان","العام الميلادي :1928"],"text":"كانت حكومة بريطانيا قد وعدت بالاعترافِ باستقلال الأردن ومضت خمسُ سنوات قبل أن تنَفِّذَ بريطانيا هذا الوعدَ استجابة لمساعي الأمير عبد الله وضغوط لجنة الانتداب التابعة لعُصبة الأمم، وفي 20 شباط 1928م تمَّ في القدس التوقيعُ على المعاهدة ومن بنودها وضع قانون أساسي للبلاد (الدستور) وتنازُل حكومة الانتداب للأمير عبد الله عن السُّلطتين التشريعية والتنفيذية، ويبقى لحكومة بريطانيا حقُّ الاحتفاظ بقوات مسلَّحة في شرق الأردن، وتقَدِّم بريطانيا معونة مالية للأردن سنويًّا، ثم صدر الدستور في نيسان من نفس العام، ثم في عام 1934م أُدخِلَ تعديل على المعاهدة يقضي بأحقية الأمير تعيينَ الممثِّلين القُنصليِّين في الخارج."},{"id":5019,"title":"وفاة الإمام عبد الرحمن بن فيصل والد الملك عبد العزيز  .","date":["العام الهجري :1346","الشهر القمري : ذي الحجة","العام الميلادي :1928"],"text":"هو الإمامُ عبد الرحمن بن فيصل بن تركي بن عبد الله، من آل سعود كان رابع أبناءِ فيصل بن تركي، حصل بينه وبين ابن رشيد قتال على الرياض وتمكَّن ابن رشيد من هزيمة رجال عبد الرحمن في (المليدة) سنة 1308هـ فرحل عبد الرحمن إلى الجنوب، ونزل في قبائل (مرة) فأقام سبعةَ أشهر، وأرسل أهلَه إلى الأحساء -وكانت لا تزال في يد الترك- وجمَعَ من توسَّم فيهم النَّجدةَ وأعاد الكَرَّةَ على الرياض، فأخرج منها رجالَ ابنِ رشيد، واستولى عليها وعلى سائر العارض. فزحف عليه ابنُ رشيد، واقتتلا في (حريملاء) وظفر ابن رشيد، فرحل عبد الرحمن إلى بادية الأحساء، وأرسل أهلَه إلى (قطر) ثم إلى (البحرين) سنة 1309ه واستقَرَّ بعد ذلك في (الكويت) إلى أن استعاد ابنه عبد العزيز الرياضَ سنة 1319هـ، وعاد إليها عبدُ الرحمن وطالت حياته إلى أن شَهِدَ مُلكَ ابنه عبد العزيز يمتدُّ إلى أطراف الجزيرة العربية. كان الملك عبد العزيز يرجِعُ إلى والده في كثيرٍ من الأمور إلى أن توفي رحمه الله. وكان عبد الرحمن فيه زهدٌ وبُعدٌ عن مظاهر التَّرَف، وفي طبعه ميلٌ إلى الهوادة، وهو على جانبٍ مِن العلم؛ فقد صنَّف مناسِكَ الحج على المذاهب الأربعة بطلب من ابنِه عبد العزيز."},{"id":5020,"title":"معركـة قــارة عافية في ليبيا .","date":["العام الهجري :1347","الشهر القمري : جمادى الأولى","العام الميلادي :1928"],"text":"معركـةٌ شهيـرة وقَعَت بين الليبيِّين والإيطاليِّين بليبيا في الجفرة وتحديدًا قرب هون، وكان قائدُ المجاهدين في تلك المعركة المجاهِدَ قضوار السهولي الورفلي من قبيلة السهول الليبية، وانتصر فيها انتصارًا باهرًا على قوات الاحتلال الإيطالي، وقَتَل فيها معظم الضباط الإيطاليين، وقَتَل فيها القائِدَ قضوار السهولي وعددًا من قادةِ الجهاد الليبي، وكانتقام من المجاهدين تمَّ التنكيلُ بأهالي هون وشَنْقُ مَن قُبِضَ عليهم من الرجال بعد احتلال المدينة بعد المعركة بأسابيع قليلة."},{"id":5021,"title":"اجتماع الجمعية العمومية في الرياض  .","date":["العام الهجري :1347","الشهر القمري : جمادى الأولى","العام الميلادي :1928"],"text":"عُقِدَ اجتماع الجمعية العمومية في أحد أروقة القصر، وحضره نحو 800 من علماء ورؤساء حضر وبدو، بينما قاطَعَ زُعماءُ الإخوان  (إخوان من أطاع الله) اجتماعَ الجمعية العمومية استنادًا إلى أن مؤتمر الرياض فيه الكفاية، بعد أن ثبت لهم رفضُ الإنجليز هدمَ المخافر، وبالتالي أصبح على الإمام أن يشُنَّ الجهاد أو ينتدب المسلمون أنفسهم للجهاد. فلم يحضُرْ فيصل الدويش ولا سلطان بن بجاد، وأناب فيصل الدويش ابنه عزيز. افتتح الملِكُ المؤتمر بخطبةٍ شرح فيها جهودَه من استرداد الرياض إلى الوقت الحاضر، وبعد أن انتهى من خطبته عرض على الحاضرين تنازُلَه عن العرش ووجوب اختيار غيرِه مِن آل سعود، وأنَّه يعاهِدُهم أنه سيساعِدُ من يختارونَه، فلم يقبل الحضور بتنازُلِه، وأجمعوا على ضرورة بقائه في السلطة، وجدَّدوا له البيعةَ والسمع والطاعة، ثمَّ بيَّن نتائجَ مفاوضاته مع الإنجليز وتمسُّكَهم بالمخافر، وحَمَّل الدويش مسؤولية بنائِها بسبَبِ تعَدِّيه على الحدود العراقية النجدية."},{"id":5022,"title":"معركة السبلة .","date":["العام الهجري :1347","الشهر القمري : شوال","العام الميلادي :1929"],"text":"لَمَّا بلغ عبد العزيز أنَّ ابن بجاد زعيم عتيبة وأمير الغطغط -أول هجرة لقبيلة عتيبة- التقى بجماعةٍ مِن تجار القصيم فقتَلَهم واستباح أموالَهم، أذن بالزَّحفِ على الإخوان العصاةِ، فاجتمع مع عبد العزيز على حَربِ المتمرِّدين من الإخوان (إخوان من أطاع الله) حَضَرُ نجدٍ وبوادي حرب وقحطان وسبيع من الإخوان، وقِسْم من عتيبة المعارضين للدويش وابن بجاد، وخرج بهم عبد العزيز في 22 رمضان من هذا العام، وقد تجمَّعت قواتُ فيصل الدويش وابن بجاد في مكانٍ يقال له روضة السبلة -بين الزلفي والأرطاوية- وفي يوم 18 شوال 30 مارس هاجم الإخوانُ بقيادة فيصل الدويش زعيم مطير جيوشَ الملك عبد العزيز، وحملت عليهم قواتُ الملك عبد العزيز حملةً عنيفة لم يقدِروا على رَدِّها، ولم ينتصف النهار حتى ولَّى الإخوانُ الأدبارَ، ففَرَّ ابنُ بجاد من المعركة، وجُرِحَ الدويش فتمكَّنَ أحدُ أتباعه أن ينجوَ به إلى الأرطاوية، ثم حُمل جريحًا إلى الملك يحوطُ به بناتُه وزوجته وهنَّ يبكين يستشفِعْنَ فيه، وأُنزِلَ بين يديه فالتفت إليه الملك قائلًا: هذا فِعلُك بيدك، فأجاب الدويش: يا الإمامُ إن عاقَبْتَ فبذنوبنا، وإن عفَوْتَ فأنت أهلُ العفو، فعفا عنه، وبعد ثلاثة أيام استسلم ابن بجاد في مدينة شقراء، فأمر بسَجنِه في الأحساء؛ لأنَّه كان أكثر قادة الإخوان قناعةً بمبادئه وإيمانه بها؛ ولذلك لم يأمن الملك عبدالعزيز أن يعاوِدَ ابن بجاد انتفاضته لاحقًا ضد الدولة، كما أمر بتدمير بيوتِ الغطغط وأخْذ أسلحتهم؛ لإنهاء مقاومة ابن بجاد تمامًا، ثم أمر الملك ولده وأخاه بتأديبِ العصاة من الإخوان حَسَبَ درجاتِهم، كما أمر ابن جلوي بتأديبِ العجمان في شرق البلاد."},{"id":5023,"title":"وفاة ضيدان بن حثلين شيخ العجمان .","date":["العام الهجري :1347","الشهر القمري : ذي القعدة","العام الميلادي :1929"],"text":"هو ضيدان بن خالد بن فيصل بن حزام بن مانع آل حثلين، شيخ قبيلة العجمان، ومن قادة الإخوان (إخوان من طاع الله) الذين شاركوا مع الملك عبد العزيز في نشرِ الدعوة وتوحيد البلاد. إلا أنه اختلف معه حولَ استخدام المخترعات الحديثة، كالهاتف والبرقيات، ومرونتِه في التعامُل مع دول وفئات يرى ابن حثلين أنَّه من الخطأ التعامُلُ معهم؛ لانحرافهم عن الدينِ الصَّحيحِ، وقد انضَمَّ ابن حثلين مع زعماء الإخوان فيصل الدويش، وسلطان بن بجاد، وأعلنوا انشقاقَهم على الملك، وزاد من حِدَّة خلاف ضيدان مع الملك عبد العزيز منعُه من شَنِّ غارات على بادية العراق. إلَّا أن ضيدان مع ذلك لم يشارِكْ زعماء الإخوان في معركة السبلة، وكان في هجرة الصرار على مقربة من الأحساء، فلما دعاه عبد الله بن جلوي أمير الأحساء لمقابلته امتنع، فوجه إليه ابنَه فهدًا، فتقابلا في العوينة وقُتِلَ ضيدان في خيمة فهد ابن جلوي الذي قَتَل أحد العجمان بعد قَتْلِه لضيدان، وتولى زعامة العجمان بعد ضيدان ابنُ عمه نايف بن حثلين."},{"id":5024,"title":"الاتحاد السوفيتي يعلن عن قيام جمهورية طاجيكستان ويضمها إلى إمبراطوريته  .","date":["العام الهجري :1348","العام الميلادي :1929"],"text":"لَمَّا ضَعُفَت دولةُ المغول في طاجيكستان سيطر الروسُ عليها وكانت أكثَرُ المحاولات الروسية للسيطرةِ عليها في سنة1869م، تمكَّن البلاشفة الشيوعيون من الاستيلاء على طاجيكستان في سنة 1917م وأصبحت جمهورية اتحادية في سنة 1922م. وفي أوائل 1990م شهدت جمهورية طاجيكستان انتفاضةً ضِدَّ السلطة السوفيتية؛ مما أدى إلى العديد من المظاهرات والعصيان المدني، وقد استخدمت السلطاتُ القواتِ المسلحةَ ضِدَّ العصيان. وقبل أن ينتهي عام 1991م تفكَّك الاتحاد السوفيتي، وأعلنت طاجيكستان استقلالَها."},{"id":5025,"title":"انقلاب ابن السقا في أفغانستان ثم سيطرة محمد نادر على الحكم .","date":["العام الهجري :1348","العام الميلادي :1929"],"text":"ساءت سيرةُ المَلِكِ أمان الله خان كثيرًا، وسار سيرةَ الأوربيين في زِيِّه وغَيِّه، وترفَّع على شعبِه، بل بدأ يُلزِمُه بما هوَتْه نفسُه من الملابس الأوروبية وسفورِ النساء واختلاطهم، وزاد على ذلك أن أثقَلَهم بالضرائبِ التي هدَّت من كواهِلِهم، حتى نَقموا عليه، فاندلعت الفوضى ضِدَّه، فقام أحدُ قُطَّاع الطرق الطامعين، وهو باجي السقا (ابن السقا) باستغلالِ الأحداث، فاستولى على كابل وفَّرَ المَلِكُ إلى قندهار وتنازل لأخيه الأكبر عناية الله، وهرب هو إلى بريطانيا، ولم يستطِعْ عناية الله مواجهةَ ابنِ السقا الذي تمَلَّك باسم حبيب الله غازي، وأخذ يعيثُ فسادًا في أفغانستان هو وحاشيته، وبقي على هذا الحالة قرابةَ التسعة أشهر، حتى تمكَّن محمد نادر شاه القائِدُ الأفغاني الذي انتصَرَ على الإنجليز سابقًا، من إلقاءِ القَبضِ على ابن السقا وأعدَمَه وتسَلَّم أعباءَ الحُكمِ، وساعده على ذلك سيرتُه الحميدةُ أمام الناس وجِهادُه المعروفُ ضِدَّ الصليبيين من روس وإنجليز، فقضى على الفسادِ والرشوة، وقَدَّم خِدماتٍ واسعةً للبلادِ."},{"id":5026,"title":"تحول مديرية الشؤون الخارجية إلى وزارة خارجية .","date":["العام الهجري :1348","العام الميلادي :1929"],"text":"توسَّعت اتصالاتُ المَلِك عبد العزيز الخارجية بعد ضَمِّه للحجازِ؛ فقد كان في جُدَّة عددٌ من القناصل الأجنبيَّةِ، فأنشأ مديريةَ الشؤون الخارجية 1344هـ وأسهم فيها الدكتور عبد الله الدملوجي (عراقي) ويوسف ياسين (سوري) وحافظ وهبة (مصري)، ثم في هذا العام تحوَّلت إلى وزارةٍ للخارجية، وأُسنِدَت إلى الأمير فيصل بن عبد العزيز، فصار نائبًا للملك في الحجاز ووزيرًا للخارجية، وفي تلك الفترة أقامت الدولةُ علاقاتٍ دبلوماسيةً مع كلٍّ مِن الاتحاد السوفيتي في فبراير 1926م، وهي أوَّلُ دولةٍ اعترفت بدولةِ الحجاز وملحقاتِها، وفي مارس من نفسِ العام أقامت الدولةُ علاقةً مع بريطانيا وفرنسا وبولندا وتركيا وإيطاليا ومصر وإيران والولايات المتحدة."},{"id":5027,"title":"مفاوضات عمر المختار مع الإيطاليين .","date":["العام الهجري :1348","العام الميلادي :1929"],"text":"أرغَمَ عُمَرُ المختار -الذي لمعَ نجمُه في جهاد الإيطاليين في برقة- الإيطاليِّينَ على الدخولِ معه في مُفاوضاتٍ، فكان في جملةِ شروطه: عدمُ تدخُّلِ الحكومة الإيطالية في أمورِ الدين الإسلامي، والاعترافُ باللغة العربية لغةً رسمية في دوائِرِ ودواوين الإدارة الإيطالية، والسماحُ بفتح المدارسِ الدينية التي تُدرَّس فيها علومُ القرآن، والتفسير والحديث والفقه وسائر العلوم. وكذلك إلغاءُ القانون الذي وضعته إيطاليا، والذي ينصُّ على عدم المساواة في الحقوقِ بين الوطني الليبي والإيطالي، إلَّا إذا تجنَّس الليبي بالجنسية الإيطالية. غيرَ أنَّ إيطاليا لم تكن جادَّةً في المفاوضات، وكان هدفُها كسْبَ الوقت، تمامًا كما فعلت فرنسا مع الأمير عبد القادر الجزائري في معاهدة (تافنة) الشهيرة. فتَمَّ استئناف الحرب إلى أن تمَّ لإيطاليا القضاءُ على الثورة، وقتل البطل عمر المختار سنة 1350ه."},{"id":5028,"title":"جرائم الاحتلال الإيطالي بالليبيين .","date":["العام الهجري :1348","العام الميلادي :1929"],"text":"أرادت إيطاليا إقامةَ مملكةٍ لاتينية في ليبيا؛ لإعادتها كما كانت في عهدِ الرومان، ولتأمينِ استيطانِ ثلاثة ملايين إيطالي فيها؛ ومن أجل ذلك: (أقدَمَ الإيطاليون على ارتكابِ آلافِ المجازر الوحشيَّة بدون مُوجِبٍ سوى الانتقامِ مِن المسلمين واستئصالِ شأفتِهم من طرابلس وبرقة، ولَمَّا كانت أراضي الجبل الأخضر من برقة هي أجودَ قطعةٍ مِن برِّ طرابلس، وفيها المياه الجاريةُ، والعيونُ الصافية، والغاباتُ الملتَفَّة، والمروج الخصبة؛ فقد توجَّهت أنظار الإيطاليين إلى استعمارها قبل غيرها، وقاموا بإجلاء القبائِلِ العربية الساكنة في الجبل الأخضر وما جاوره عن أراضيهم، وجمعوا منهم ثمانين ألفَ نسمةٍ رجالًا ونساءً وأطفالًا، وساقوهم إلى صحراء سِرْت في الأراضي الواقعة بين برقة وطرابلس على مسافةِ عشرة أيام من أوطانهم الأصلية، وأنزلوهم في معاطِشَ ومجادِبَ لا يمكِنُ أن يعيش بها بشر، فمات عددٌ كبير منهم جوعًا وعطشًا، وماتت مواشيهم كلُّها مِن فَقدِ الكلأ والماء. وكان أهالي طرابلس وبرقة يزيدون على المليون ونصف المليون قبل الغزو الإيطالي. ولم تمضِ فترةٌ طويلة، حتى انخفض هذا العدد إلى سبعمائة ألفِ نسمة. وبلغ عددُ السكَّان الذين أعدمهم الإيطاليون شنقًا من أهالي طرابلس وبرقة خلال فترة الاحتلال عشرين ألفَ نسمةٍ، وكثيرًا ما شنقوا أناسًا بمجرَّد إرادة قائد، أو مجردِ رغبة ضابط صغير. وقد وقع لهم أنهم شنقوا نساءً بعد أن جرَّدوهن من ثيابِهن وأبقوهن عارياتٍ عِدَّةَ أيام! كما وقع أَّنهم كانوا يسلكون ستين أو سبعين شخصًا في سلسلة واحدة، ويحبسونهم على هذه الصورة مدةً إلى أن يموتوا. وجنَّد الإيطاليون من أهالي الجبل الأخضر برقة كلَّ الرجال من سنِّ البلوغ إلى الخامسة والأربعين لِيُحاربوا بهم إخوانهم. ثم عَمَدوا إلى الأحداث من فوق 4 سنوات حتى 12 سنة، فأخذوهم قهرًا من أحضان آبائهم وأمهاتهم، في يومٍ تشيبُ مِن هوله الأطفالُ، ودفعوهم إلى إيطاليا لأجل تربيتِهم وتنشئتِهم في النصرانية. واغتصبوا النساءَ وقتلوا منهن الكثيراتِ ممَّن دافعْنَ عن شرفِهنَّ حتى النهاية. وكان نحوًا من مِئَتي امرأة من نساء الأشراف، قد فرَرْن إلى الصحراء قبل وصول الجيش الإيطالي إلى الكفرة، فأرسلت القيادةُ الإيطالية قوةً في إثرِهنَّ لمطاردتهن حتى قبضوا عليهنَّ وسَحبوهن إلى الكفرة، حيث خلا بهنَّ ضباط الجيش الإيطالي واغتصبوهن. وقد هتكوا عِرضَ سبعين أسرة شريفة من أشراف الكفرة، الذين كانت الشمس تقريبًا لا ترى وجوه نسائهنَّ من الصونِ والعفاف. ولما احتجَّ بعض الشيوخ على هتك أعراضِ السيدات المذكورات، أمر القائدُ الإيطالي بقَتلِهم. ثم استباح الإيطاليون الزاويةَ السنوسية بالكفرة -المسماة بالتاج- وأراقوا الخمور فيها، وداسوا المصحفَ الشريف بالأقدام. وحملوا الشيخ سعد (شيخ قبيلة الفوائد)، وخمسة عشر رجلًا معه من الشيوخ، وقذفوا بهم من الطائراتِ على مشهد من أهلهم، حتى إذا وصل أحدُهم إلى الأرض وتقطع إربًا، صَفَّق الإيطاليون طرَبًا، ونادوا بالعربِ قائلين: (ليأتِ محمد هذا نبيُّكم البدوي الذي أمركم بالجهاد، وينقذُكم من أيدينا)!"},{"id":5029,"title":"تمرد الإخوان  (إخوان من أطاع الله) مرة أخرى بعد السبلة .","date":["العام الهجري :1348","الشهر القمري : ربيع الأول","العام الميلادي :1929"],"text":"ما إن اندملت جراحُ الدويش بعد موقعة السبلة وهو في الأرطاوية، وجاءته أخبار الإخوان في تجمُّعِهم بالوفرة جنوب الكويت، فتناسى عهده للملك عبد العزيز فخرج بمطير إلى الوفرة واشتَدَّ ساعده بنايف بن حثلين (الملقَّب بأبي الكلاب) فولوا فيصلَا رئاستهم، ولما تسامعت مطير وغيرها بانتفاضة الدويش وتزعُّمه الحركة أقبلوا إليه، فأخذ الدويشُ يشنُّ الغارات على نجد، ويقطع السبل، واستنفر القبائِلَ لنُصرتِه، وكانت لفيصل الدويش موقعةٌ في القاعية بالدهناء، وموقعة أخرى لابنه عزيز مع أمير حائل عبد العزيز بن مساعد في أم رضمة، وقُتِلَ فيها عزيز، فاتجه عبد العزيز إلى تقويةِ حامياته في الأحساء والقطيف وحائل، وأرسل الزحوف على عتيبة فقَضَت على عصاتها."},{"id":5030,"title":"تأسيس الوكالة اليهودية العالمية .","date":["العام الهجري :1348","الشهر القمري : ربيع الأول","العام الميلادي :1929"],"text":"في عام 1907 أنشأ الحزبُ اليهوديُّ مُنظَّمةً عَسكريَّةً من اليهود الأوروبيين تسمَّى (بارجيورا) ثم تأسَّست الوكالة اليهودية عام 1923 بقرارٍ من المؤتمر الصهيوني الثالث عشر، وهي الوكالةُ التي أخذت على عاتِقِها تنشيطَ هِجرةِ اليهود من جميع أنحاء العالم إلى فلسطين بشتى الوسائل. وهي منظَّمةٌ يهودية صهيونية أقيمَت بمبادرةٍ مِن بنيامين زئيف هرتزل في المؤتمر الصهيوني الأول، الذي انعقد في بازل عام 1897م بصفته برلمانًا عامًّا لليهود. انعقد المؤتمَرُ مِن أجل بحثِ سُبُل تحقيق أهداف الصهيونية، كما هو منصوصٌ عليها في خطة بازل: \"إقامة وطن للشعب اليهودي في أرض إسرائيل حَسَب الشريعة الدولية\". وعليه اتخذ المؤتمرُ إجراءاتٍ لإنجازِ هذه الخطة: توطينُ اليهود الفلَّاحين وأصحاب المهن وأرباب الصناعة، في أرض إسرائيل. تنظيم وتوحيد الشعب اليهودي بأسْرِه عن إنشاء المؤسَّسات الملائمة، والمحلية والعامة بموجِبِ القوانين الخاصَّة بكل بلاد. تقوية العواطِفِ اليهودية القومية والاعتراف القومي اليهودي. إجراءُ النشاطات التمهيدية بهدفِ الحصول على مُوافقة الحكوماتِ التي بوُسعِها المساعدة على تحقيق هدف الصهيونية. ولدى إقامة المنظَّمة الصهيونية انخرطت فيها حوالي 260 جمعيةً من \"حوففي تصيون\" (أعضاء محبي صهيون) من روسيا ومن شرق أوروبا. وفي بداية طريقها عملت المنظَّمةُ الصهيونية على توطيد الاستيطان في أرض فلسطين؛ حيث أقامت هيئاتٍ بهدفِ مساعدتها على نَيلِ أهدافها. على سبيل المثال تمَّ تأسيس بنك كنز الاستيطان اليهودي عام 1899 بهدف تمويلِ فكرة هرتزل في شِراءِ امتيازٍ لتوطين اليهود في أرض إسرائيل من أيدي المملكة العثمانية. ثمَّ تمَّ اعتبار ضائقة الشعب اليهودي مشكلةً سياسية عالمية يجِبُ التعامل معها على الصعيدِ الدولي، وعمل على إنجاز الهدفين الرئيسيين: الهدف الأول: إقامة وطن للشعب اليهودي في أرض إسرائيل بموافَقةٍ مِن الدول الكبرى، عن جراء \"شارتير\" (وثيقة حقوق سياسية يتم الحصولُ عليها بالمفاوضات الدبلوماسية) كما تقَرَّر في خطة مؤتمر بازل. والهدف الآخر: تقوية وتطوير المنظمة الصهيونية؛ من أجل أن تتحَوَّلَ إلى هيئةٍ ذات أهمية في المفاوضات السياسية؛ إذ في يوم من الأيام سيكون بمقدورها تولِّي قيادةِ المشروع الاستيطاني. هذا ومارست المنظَّمةُ الصهيونية العالمية نشاطاتِها بصورة دبلوماسية، وخاصةً في المملكة العثمانية، وفي ألمانيا، ولكِنْ لم تؤدِّ الجهود السياسية المباشِرة التي بذلها هرتزل إلى النتائجِ المنشودة."},{"id":5031,"title":"ثورة حائط البراق (حائط المبكى) في فلسطين .","date":["العام الهجري :1348","الشهر القمري : ربيع الأول","العام الميلادي :1929"],"text":"اندلعت في فلسطينَ ثورةٌ مَعروفةٌ باسم حائط البراق في 15 أغسطس من هذا العامِ، لكِنَّ إرهاصاتها تعودُ إلى نحو 12 شهرًا سابقة على هذا التاريخ مع وقوعِ عَدَدٍ من المواجهات بين الفلسطينيين واليهود في القدس؛ بسبب حائط البُراق -الحائط الغربي للمسجد الأقصى- الذي أطلق عليه اليهودُ اسمَ حائط المَبكى، وذلك بعد أن انعقد المؤتمرُ الصهيوني العالمي في السادس عشر في مدينة زيورخ السويسرية في صيف 1928م، وخرج \"الحزب الإصلاحي\" بزعامة الصهيوني المتطرف \"زئيف جابوتنسكي\" من المؤتمر بأجندة جديدة داعيًا اليهود في فلسطين إلى التسلُّحِ وسلوكِ طَريقِ العُنفِ واستخدام القوَّة لتحقيق أهدافهم. ثمَّ خرجت مُظاهراتٌ يهودية يوم 15 أغسطس 1928م حتى الحَرَم القدسي الشريف انتهت إلى \"حائط البراق\" وقام اليهود برفع العلم اليهودي على الحائط رافعينَ شِعارًا يقول: \"الحائط حائطنا\" مُنشِدين الأناشيد اليهودية. وكان القائِدُ العسكري البريطاني الميجور \"ساندرس\" قد بدأ بتوزيع السلاحِ على اليهود في فلسطين وتجنيدِ بَعضِهم في الفِرَق النظامية للجيش البريطاني باعتبارهم من الرعايا البريطانيين، أي: من حاملي الجنسية الإنجليزية. إلى أن كان يوم 15 أغسطس هذا العامَ؛ حيث كان اليهود يحتفلون بعيد الغُفران، فقامت منظمة \"بيتار\" الصهيونية المتطرِّفة بزعامة \"يوسف ترمبلدور\" بتنظيم مظاهرة للاستيلاء على الحائط الغربي للحرم القدسي الشريف بحُجَّة أنَّه من بقايا هيكل سليمان، فاندلعت الثورة في \"القدس\" أولًا، ثم في عموم فلسطين بعد ذلك؛ حيث اجتاحت الاشتباكاتُ مُدُنَ \"الخليل\" و\"عكا\" و\"حيفا\" و\"يافا\" و\"صفد\" و\"بيسان\" وغيرها من مدن فلسطين. وبعد عدَّةِ أيام من الاشتباكات المتفرِّقة بين العرب من جهة وبين اليهود وقوات الاحتلال البريطاني الموجودة في فلسطين من جهة أخرى بدأت ثورةُ البراق تتَّخِذُ طابعًا أكثر تنظيمًا؛ ففي يوم 20 أغسطس 1929م قامت معركةٌ عنيفة عند ممرِّ البراق في بيت المقدِسِ لم يتمكَّن البوليس البريطاني من إنهائِها إلا بعد مشقة بالغة. وجدد الفلسطينيون هجومَهم في القدس وفي أنحاءٍ مختلفة من فلسطين خاصةً على المجموعات المسلَّحة من اليهود، استمَرَّت طيلةَ يوم 23 أغسطس جُرِحَ خلالها 107 من الجانبين، وخَسِرَ اليهود 28 قتيلًا، وقُتِل 13 من العرب، وكانت هذه المعركة تدور في مدينة القدس من شارع إلى شارعٍ، ومن ركن إلى ركن. ومع سَرَيان أنباء الثورةِ في عموم فلسطين قامت معركةٌ أخرى في مدينة الخليل جنوبيَّ القدس؛ حيث أُعلِنَ رسميًّا عن مصرع ستين يهوديًّا وإصابة خمسين آخرين، وهوجِمَت مراكز البوليس البريطانية، ونَشَبت معركةٌ جديدة في ضواحي الخليل. وفي صفد نشبت معركةٌ أخرى في نفس يوم معركة مدينة الخليل استمَرَّت لساعات طويلة جُرِحَ خلالها 28 يهوديًّا وقُتِل تسعة آخرون. وفي توثيق الكاتب \"عيسى السفري\" لأحداث ثورة البراق في فلسطين -كما عاصرها- يقول: \"إن الثورة استمَرَّت 15 يومًا، قُتِلَ وجُرِحَ خلالها 472 يهوديًّا\"."},{"id":5032,"title":"اجتماع قرية الشعراء مع الملك عبد العزيز .","date":["العام الهجري :1348","الشهر القمري : جمادى الأولى","العام الميلادي :1929"],"text":"دعا الملِكُ عبد العزيز ذوي الرأيِ من شيوخ وقادة القبائل إلى اجتماعٍ في قرية الشعراء، وطلب منهم أن يأتوه بآرائِهم وآراءِ قبائلهم في شأنِ المتمَرِّدين من الإخوان (إخوان من طاع الله)، وفي اليوم التالي انعقد الاجتماعُ واتفقوا على عددٍ مِن المقررات، منها: 1/ كل من شارك في الفتنة وبقي حيًّا يؤخذ مالُه ورِكابُه وسلاحُه وتحكَّمُ الشريعة في رقبته. 2/ كل من كان متهمًا بممالأة أهل الفساد ولم يجاهِدْ مع المسلمين تؤخذ منه شوكة الحرب (ركابه وسلاحُه). 3/ كل ما يؤخذ من المفسدين يُمنَحُ للمجاهدين الصادقين. 4/ كل هجرة غلب على أهلها الفسادُ يُطرَدون من هجرتهم، ويفَرَّقون ولا يُسمَحُ لفريق منهم الاجتماعُ في مكان واحد."},{"id":5033,"title":"تسليم الإنجليز زعماء الإخوان (إخوان من أطاع الله) للملك عبد العزيز .","date":["العام الهجري :1348","الشهر القمري : شعبان","العام الميلادي :1930"],"text":"تمكن الملك عبد العزيز بعد اجتماع الشعراء أن يُلحِقَ بالإخوان هزائِمَ مُتلاحِقةً حتى فرَّ الدويش ونايف بن حثلين إلى الكويت، كما هرب أعدادٌ من الإخوان إلى داخل الحدود العراقية خوفًا وهربًا من ابن سعود الذي أرسل إلى ديكسون الوكيل السياسي في الكويت يحتَجُّ على السماح للإخوان باللجوء إلى العراق والكويت وشرق الأردن، فأجابه بأنَّه سيعيدهم إلى نجدٍ، وفي 9 شعبان نُقِلَ زعماء الإخوان الثلاثة: فيصل الدويش، وجاسر بن لامي، ونايف بن حثلين بالطائرة إلى البصرة، ثمَّ وُضِعوا في بارجة بريطانية، وطالب الملِكُ عبد العزيز بتسليمهم له، فوصل إلى مُعسكَرِه بالقرب من الكويت وفدٌ بريطاني تفاوض معه بشأنِ تسليم الزعماء الثلاثة، واستمرت المفاوضات أسبوعًا، وفي يوم 27 من شعبان تم تسليمُ الزعماء الثلاثة في معسكر ابن سعود القريب من الكويت، وأمر الملك عبدالعزيز بسَجنِهم في الرياض ثمَّ نُقِلوا إلى سجن الأحساء ليُسجَنوا فيه مع سلطان بن بجاد، وفي عام 1350هـ توفِّي فيصل الدويش، وأما الثلاثة البقية فقد ماتوا عام 1353هـ، وبنهاية هذا العام انتهت أعمالُ الإخوان على حدود العراق والكويت وشرق الأردن، وتلاشت حركتُهم تمامًا، ودخل البدو تحت خيمة الدولة الحديثة، وتوافقوا مع السكَّان الحَضَر."},{"id":5034,"title":"معاهدة صداقة وحسن جوار بين ملكي الحجاز والعراق .","date":["العام الهجري :1348","الشهر القمري : رمضان","العام الميلادي :1930"],"text":"بعد أن قضى الملك عبد العزيز على حركة الإخوان (إخوان من أطاع الله) وتسَلَّم زعماءَهم عَقَد معاهدةَ صداقة وحُسْن جوار مع الملك فيصل بن الحسين ملك العراق؛ حيث التقى الاثنان مع المندوب السامي البريطاني في العراق همفرز، ودام اللقاءُ ثلاثة أيام، واتفقا على معاهدة صداقة وحُسْن جوار، ووُقِّعَت بعد أسابيع، وتبادَلَ المَلِكان الاعترافَ بدولتيهما ونسيان ماضي الصراع الهاشمي السعودي في الحجاز، وتم تبادل المندوبين الدبلوماسيين."},{"id":5035,"title":"عودة البحث عن النفط بين السعودية والشركات الأمريكية .","date":["العام الهجري :1349","العام الميلادي :1930"],"text":"كان البريطانيون قد سبقوا الأمريكانَ إلى التنقيبِ عن النفطِ في غرب الخليج العربي. ولم تُسفِرْ بحوثُهم عن نتيجةٍ، فكتبوا إلى السلطان عبد العزيز يأسَفون على ما أضاعوا من جهدٍ ومالٍ، وانصرفوا عن البحثِ، ولَمَّا كان وزير الخارجية الأمير فيصل يزور لندن على رأس بَعثةٍ سياسية تحدَّثَ مع الجهاتِ البريطانية في احتمالِ وجودِ النِّفطِ على الشاطئ الغربي للخليج العربي، فلم يجِدْ في الشركات البريطانية استعدادًا لمجازفةٍ ثانية، وبينما كان الثريُّ الأمريكي كرين في زيارةٍ للسعودية بصُحبةِ المترجم جورج أنطونيوس، سأل كرين الملكَ عبد العزيز عمَّا يمكِنُ أن يقومَ به من مساعدة بلادِه، فطلب منه المَلِكُ أن يُحضِرَ إليه خبيرًا جيولوجيًّا يبحث له عن آبار ارتوازية في مناطق الصحراء لتسقيَ الحُجَّاجَ ويستخدِمَها البادية في الرعي والزراعة، فقال له كرين: سأبعث إليكم بخبير أعتقِدُ أنه سيفيدُ بلادَكم، ولا تكَلِّف حكومتَكم أن تنفِقَ عليه أكثر من تأمين إقامته وتنقُّلاته، فوصل إلى جدة المهندس الجيولوجي الأمريكي تويتشل، فأخذ يبحث عن الماءِ في مسافة 1500 ميل في الحجاز دون أيِّ فرصةِ أمَلٍ لِتَدفُّق المياه في أراضي الحجاز، ولَمَّا كان البحثُ عن النِّفطِ جاريًا في البحرين على يد الشركات الأمريكية، عرض المَلِكُ على تويتشل أن يتَّصِلَ بزملائِه في الشركات الأمريكية للتنقيبِ عن النفط في الأحساءِ بدلًا من البحث عن الماء، وبعد جهدٍ تمَّ الاتفاقُ مع شركة ستاندارد أويل كومباني أوف كليفورنيا على تبنِّي المشروع عام 1352هـ."},{"id":5036,"title":"تعيين إسماعيل صدقي باشا رئيسًا للوزراء في مصر .","date":["العام الهجري :1349","الشهر القمري : محرم","العام الميلادي :1930"],"text":"أصدر الملك فؤاد الأول قرارًا بتعيين إسماعيل صدقي باشا رئيسًا للوزراء خلفًا لمصطفى النحاس باشا، وكان الملك فؤاد يرى في صدقي رجلَ إدارة وحسم، قادرًا على حلِّ المشكلات التي تعصِفُ بالبلاد، فأُلغي دستور 1923 وأصدر دستور 1930."},{"id":5037,"title":"معاهدة التحالف الوثيق بين العراق وبريطانيا .","date":["العام الهجري :1349","الشهر القمري : صفر","العام الميلادي :1930"],"text":"كانت المعاهدةُ قد طُرِحَت سابقًا لكِنْ لم يتمَّ التوقيعُ عليها بسبب بُعدِ الشروط فيها، فكانت كلُّ وزارة تتغيَّرُ ولا يحدث أي توقيع للمعاهدة، حتى شُكِّلت لجنةٌ لمفاوضة الجهة البريطانية التي يمثِّلُها المعتمد السامي البريطاني، وقد وجدت ثلاث نقاط يجب بحثُها، وهي: تعديل الاتفاقية المالية والعسكرية؛ حيث كان هناك اعتراض على قوة الطيران البريطانية الموجودة بالعراق، وقضيةُ التجنيد الإلزامي، وامتلاك ميناء البصرة والسكك الحديدية. ثم عادت المفاوضاتُ بين الحكومة العراقية والبريطانيين في الرابع من ذي القعدة عام 1348هـ ودارت حول نقطتين أساسيتين: الاعتراف بحفظ وحماية المواصلات الجوية البريطانية في العراق بصورةٍ دائمة وفي جميع الأحوال، دخولُ العراق في عصبة الأمم عام 1932م. وكان الملك فيصل يُشرِفُ على المفاوضات بنفسِه، واضطر للسفر إلى لندن فأناب أخاه عليًّا حتى تم التوقيعُ على المعاهدة في الرابع من صفر من هذا العام، ونُشِرَت بنودُ المعاهدة في الثاني والعشرين من نفس الشهر فلَقِيَت معارضةً واسعة، والتي كان من بنودها: يسودُ سِلمٌ وصداقة دائِمَين بين ملك العراق وملك بريطانيا، ويؤسَّس بين الفريقين الساميين المتعاقدين تحالفٌ وثيق توطيدًا لصداقتهما... وتجري بينهما مشاوراتٌ تامة وصريحة في جميع شؤون السياسة الخارجية مما قد يكون له مِساسٌ بمصالحِهما المشتركة، ومنها معونةُ أي طرف للآخر في حال اشتبك أحدُ الفريقين بحربٍ، وغيرها من البنود الدالة على الربطِ الوثيقِ بين الحكومتين؛ لإبقاء العراق تحت بريطانيا كالتابِعِ."},{"id":5038,"title":"صدور دستور جديد للبلاد في مصر .","date":["العام الهجري :1349","الشهر القمري : جمادى الأولى","العام الميلادي :1930"],"text":"شهد عام 1930 إلغاءَ دستور 1923م ثم إصدارَ دستور جديد للبلاد في وزارة إسماعيل صدقي باشا رئيس الوزراء، واستمَرَّ العمل به لمدة خمس سنوات، ثم عادت البلادُ مرة أخرى إلى دستور عام 1923، وذلك في عام 1935."},{"id":5039,"title":"معارك واحة الكفرة الليبية آخر معاقل السنوسيين واحتلال القوات الإيطالية لها. .","date":["العام الهجري :1349","الشهر القمري : شعبان","العام الميلادي :1931"],"text":"وقعت هذه المعركة في يناير 1931م بعد ما أمضى الإيطاليون ستة أشهر وهم يعدُّون جيشًا قويًّا من أجل الزحف على مناطق الكفرة جنوب شرق ليبيا. وبعد إتمام تجهيز هذه القوة عَمَد قائدها إلى إطلاقها من عدةِ أماكن؛ فقد انطلقت القوة الرئيسية من أجدابيا شرق ليبيا في 20 ديسمبر 1930م عبر أوجلة جنوب بنغازي، والقوة الثانية انطلقت من زلة عبر تازربو، وانطلقت قوة ثالثة مسانِدة من الوادي الكبير، بلغ إجمالي هذه القوات الزاحفة صوب الكفرة أكثَرَ من أربعة آلاف جندي، وكانت قافلة الإبل وحدها تضم 5517 رأسًا من الجمال عدا السيارات والآليات. وكانت أولى المعارك في هذه الحملة معركةُ الهواري التي جرت يوم 19 يناير 1931م، حيث تصَدَّى فيها المجاهِدون لقوات تفوقهم عددًا وعُدة. وأمر غراتسياني باستخدام الطيران على أوسع نطاق ممكن، ورغم ذلك استطاع المجاهِدون أن يكبِّدوا الطليان خسائِرَ فادحة. ولَمَّا لم يكن في مقدورهم التصدي لمثل هذه القوة تحوَّلوا إلى واحة الهويويري وواصلوا قتالهم ضِدَّ القوات الإيطالية. وكان بمقدور المجاهدين التصدِّي للقوة الإيطالية لولا نيران الطائرات المعادية التي كانت تُغيرُ عليهم بمعدَّل تسع هجمات بطائرات من نوع \"رو\" في اليوم الواحد. وتعترف المصادر الإيطالية بأن المجاهدين لم يكونوا ليتزحزحوا لولا تدخُّل الطيران الإيطالي. وما إن سيطرت القوات الإيطالية على مناطِقِ الوسط والجنوب والغرب -إضافة للوجود الإيطالي في مناطق بنغازي وما حولها- حتى بدأت بالاستعداد العسكري لاحتلال منطقة الكفرة. وتمثِّلُ السيطرةُ على هذه الواحات أهميةً خاصة في الاستراتيجية الحربية الاستعمارية الإيطالية حينذاك، خاصةً بعد تحوُّل القسم الباقي من المجاهدين عَقِبَ احتلال منطقة الخليج والمناطق الصحراوية المجاورة، واتخاذهم واحة تازربو قاعدةً لبعض تحركاتهم، ومهاجمة المناطق الواقعة تحت سيطرة الاحتلال. كما تعتبر واحةُ الكفرة مركزًا اقتصاديًّا مهمًّا؛ حيث كانت تمرُّ بها القوافِلُ من زلة وتازربو، مرورًا بواحات الكفرة ثم إلى منطقة الجغبوب قبل احتلالها ثم إلى سيوه."},{"id":5040,"title":"تأسيس جمعية العلماء المسلمين في الجزائر .","date":["العام الهجري :1350","العام الميلادي :1931"],"text":"بقي الاستعمارُ الفرنسي في الجزائر قائمًا، وأخذ أشكالًا جديدة، فبدأ ينشر الجهلَ، ويحارب اللغة العربية، وينشر الرذيلة والفواحش بين المسلمين، ولكِنْ أبقى الله في الأمة بقيةً تأمر بالمعروف وتنهى عن المنكر، فكان من المصلحين الشيخ عبد الحميد بن باديس الذي كان يُلقي دروسًا في التفسير في مسجد سيدي الأخضر بقسنطينة، والتفَّ حوله الكثير واشتد ساعده، وقام بدعوة العلماء لتوحيد الكلمة، فحضر 190 من علماء الجزائر، واتَّفق الجميع على تأسيس جمعية العلماء المسلمين، وتولى هو رئاسَتَها، وفَتَحت هذه الجمعية المدارسَ للناشئة، وأصدرت جريدة المرصاد، وأخذ الشيخ عبد الحميد الحملَ على الفرنسيين، وبالمقابل جهدت فرنسا للإيقاع بالجمعية؛ حيث كانت تغتالُ سِرًّا بعض العلماء المعارضين لهذه الجمعية، وتتهم بهذا الفعل الجمعية، ثم انشَقَّ عن الجمعية بعضُ الذين استاؤوا من محاضرة الطيب العقبي التي تكَلَّم فيها على أصحاب الطرق، فانشقوا وألَّفوا جمعية علماء أهل السنة وجريدتهم البلاغ الجزائري، وارتفع أمرُ ابن باديس في الجزائر، وقد قام وفدٌ برئاسته بالذَّهاب إلى فرنسا وتقديم مطالب الشعب الجزائري للحكومة الفرنسية، ومنها: إلغاء كافة القوانين والقرارات الاستثنائية بالجزائر، وإلغاء الحكم العامِّ في الجزائر، واشتراك الجزائريين في الهيئة الانتخابية، ويكون لهم نوابٌ في المجلس النيابي الفرنسي، وعدمُ التمييز بين الفرنسيين والجزائريين، مع الاحتفاظ بالهُوية الإسلامية، واستقلال الدين الإسلامي عن الحكومة الفرنسية، وجَعْل اللغة العربية لغةَ الدراسة، ورُفِضَت مطالبهم جملة، وزادت فرنسا من توسيعِ الشِّقاق بمساعدة أصحاب الطُّرُق الصوفية، والاغتيالات السرية واتهام جمعية المسلمين بها، كما فعلت بالشيخ عمر بن دالي الذي جعلَتْه إمام الجامع الكبير في قسنطينة ثم طلَبَت منه الهجوم على الوفد الذي سافر لفرنسا، ثم دفعت من قَتَله حيث سَلَّم نفسه بعد فترةٍ واعترف بكُلِّ المخطَّط، ثم لَمَّا توفي ابن باديس 1359هـ تولى محمد بشير الإبراهيمي رئاسةَ الجمعية."},{"id":5041,"title":"وفاة فيصل الدويش زعيم قبيلة مطير .","date":["العام الهجري :1350","الشهر القمري : جمادى الأولى","العام الميلادي :1931"],"text":"هو فيصلُ بنُ سلطان بن فيصل بن نايف الدويش من أواخِر شيوخِ مطير، ومِن كبارِ أصحابِ الثورات في نجدٍ ضِدَّ الملك عبد العزيز. وهو من بني الدويش، ويقالُ لهم: الدُّوشان من بني علوة أصحابِ الرياسة في مطير، تمتَدُّ منازِلُ مطير من الصمَّان غربيَّ الأحساءِ إلى سهولِ الدبدبة فالقصيم فأطراف الحجاز، وكان فيصل بدويًّا قُحًّا، فيه شراسةٌ ودهاءٌ واعتزازٌ بعددِه الضخم. قام بزعامة مطير بعد أبيه. وكان لطبيعتِه البدوية متقلبًا يبدِّلُ مواقفه بسهولةٍ طِبقًا لِما يراه من رجحان كفَّةِ طرفٍ على آخرَ في أي لحظة، أو يوالي من يتوسَّمُ أنه سيهبه غنائِمَ أكثرَ، وكان لقوَّته وقوَّةِ جيشِه إذا انحاز إلى أحد الجانبين يرجِّحُ كِفَّتَه على الآخر، فكان يذهبُ إلى حائل ويمضي من عندِهم محمَّلًا بالهدايا والهبات، وفي أوقاتٍ أخرى يديرُ ظَهرَه لابنِ رشيدٍ، ويفِدُ على الرياض ويُقسِمُ يمين الولاء للملك عبد العزيز، لم يكُنْ مخلصًا لأحدٍ، قصد في شبابه أطرافَ العراق بجماعةٍ من عشيرته، فطاردته السلطاتُ العثمانية، فعاد إلى نجد بعد سنتين. وأنزله الملك عبدالعزيز في الأرطاوية، وهي دار هجرة كبيرة للإخوان، بين الزُّلفي والكويت. وانتدبه الملِكُ لإخضاع عشائِرَ مِن نجد خرجت عليه ولجأت إلى أطرافِ العراق، فمضى إليها ومزَّقَها، وظَفِرَ في معركة بينه وبين الشيخ سالم بن مبارك الصباح سنة 1920م فاحتل الجهرة من أراضي الكويت، وكاد يحتَلُّ الكويتَ، وتدخَّل البريطانيون فعُقِدَ اتفاق العقير سنة 1921م بتعيين الحدود بين الكويت ونجد. وحاصر المدينةَ المنورة في الحرب الحجازية سنة 1925م وطمع بإمارتها فخاف أهلُ المدينة بطْشَه، فكتبوا يلتمسون من الملك عبد العزيز إرسالَ أحد أبنائه ليتسَلَّمَها بدل الدويش، فأرسل ابنَه محمدًا فدخلها. تزوَّج فيصل ببنت سلطان بن بجاد شيخ عتيبة، فازدادت عصبيتُه قوَّةً. وعاد بعد حرب الحجاز إلى الأرطاوية غيرَ راضٍ عن سياسة الملك عبدالعزيز، فتآمر عليه مع جماعةٍ فقام الملك بزحف كبير سنة 1929م ضرَبَ به جموعَ الدويش على ماءٍ يقال له السبلة بقُربِ الزلفي، وجُرِحَ الدويشُ فحُمِل على نعشٍ تحفُّ به نساؤه وأولاده يندبون، وأُنزِلَ بين يديه، فلم يَرَ الإجهازَ عليه، وعفا عنه. وعولج في الأرطاوية، واندملت جراحه، فعاد يستنفِرُ القبائل للقيام على الملك عبد العزيز، وقام بمناوشات انفضَّت خلالها جماعاتُ الدويش. وضاقت في وجهِه السُّبُل، فلجأ إلى بادية العراق، ومنها إلى الكويت، واحتمى ببارجة بريطانية. وجيءَ بالدويش على طائرةٍ سنة 1930م فسُلِّمَ للملك عبد العزيز فأُرسِلَ إلى سجن الأحساء مكبَّلًا بالأغلال ومعه ابن حثلين وابن لامي، فمات في حبسِه بعد سبعة شهور."},{"id":5042,"title":"قتل عمر المختار قائد الكفاح الليبي ضد الاحتلال الإيطالي .","date":["العام الهجري :1350","الشهر القمري : جمادى الأولى","العام الميلادي :1931"],"text":"هو الشيخُ المجاهِدُ عُمَرُ بنُ مختار بن عمر المنفي، نسبةً إلى قبيلة منفة في بادية برقة بليبيا، تعلم في الزوايا السنوسية، وجعله محمد المهدي السنوسي شيخًا على زاوية القصور بالجبل الأخضر، خرج لجهادِ الطليان بعد أن احتلُّوا مدينة بنغازي عام 1329هـ وصَمَد للعدو صمودًا منقَطِعَ النظير جعَلَه في أوائل الأبطال في الجهاد الليبي ضِدَّ الطليان، كانت منطقة المختار برقة ثابتةً منيعةً. وتهادن الإيطاليون والطرابلسيون سنة 1340هـ، ودبَّ الخلافُ في زعماء طرابلس وبرقة، وتجدَّدت المعركة مع الإيطاليين، فتولى عمَرُ قيادة الجبل الأخضر وتلاحقت به القبائِلُ، واتفق الرؤساءُ على أن يكون هو القائِدَ العامَّ والرئيس الأعلى للمجاهدين. وهاجمتهم القوى الإيطالية، فردُّوا هجومها، وغَنِموا منها آلاتٍ حربية ومؤنًا غير قليلة. وأشهر ما نشب من المعارك معركة الرحيبة وعقيرة المطمورة وكرِسة، يقول غراتسياني القائد العام الإيطالي في بيان له عن الوقائع التي نشبت بين جنوده والسيد عمر المختار: إنها \"كانت 263 معركةً في خلال عشرين شهرًا\" هذا عدا ما خاضه المختار من المعارك في خلال عشرين سنة قبلَها. وبينما هو في سرية من رجالِه تُقدَّر بخمسين فارسًا بناحية سلطنة بالجبل الأخضر يستطلع مواقِعَ العدو فوجئ بقوةٍ مِن الأعداء أحاطت به فقاتَلَها، واستُشهِدَ أكثَرُ من كان معه، وأصيب هو بجراحٍ بعد أن عُقِرَ جَوادُه، فانقض عليه الطليان وحُمِل أسيرًا وهو لا يُعرَف، ثم حمل إلى سوسة فعرفوه، فنقل بطراد إلى بنغازي وسُجِنَ أربعة أيام ثم حقَّقوا معه، ثم أُعدِمَ شنقًا في مركز سلوق ببنغازي في 4 جمادى الأولى وعمره يومها خمسة وسبعون عامًا، ومع ذلك كان يجاهِدُ على جواده يقوم بنفسه بالاستطلاع، فرَحِمَه اللهُ وقَبِلَه عنده في الشهداءِ."},{"id":5043,"title":"انعقاد المؤتمر الإسلامي الأول .","date":["العام الهجري :1350","الشهر القمري : رجب","العام الميلادي :1931"],"text":"لما رأى الحاج أمين الحسيني انحياز الإنجليز مع اليهود، لجأَ إلى قوة العالم الإسلامي؛ حيث دعا إلى عقد مؤتمر إسلامي رسمي في القُدس؛ ليُشعِرَ سلطات الانتداب بأنَّ عَرَبَ فلسطين ليسوا وحدهم، فهناك الملايين من العرب والمسلمين يساندونَهم. وافتتح المؤتمر الإسلامي الأول رسميًّا يوم الإسراء 7/12/1931، حضره حشدٌ كبير من العلماء والشخصيات السياسية، من أمثال الشيخ رشيد رضا، وعبد العزيز الثعالبي، وضياء الدين الطباطبائي، والشاعر محمد إقبال، وقد استنكروا فيه جميعَ أنواع الاستعمار وفي أي قطر من الأقطار الإسلامية، وأصدر المؤتمرُ عِدَّةَ قراراتٍ، منها: تأليف دائرة معارف إسلامية، وإنشاء جامعة أُطلِقَ عليها جامعة المسجد الأقصى، وتكوين شركة زراعية لإنقاذ الأراضي الفلسطينية. وكانت قراراتُ هذا المؤتمر دون طموحات الجماهير التي خرجت في مظاهراتٍ عَفْوية كبيرة عامي 1931 و1933 عمَّت معظم المدن الفلسطينية، وواجهَتْها السلطات البريطانية بالقمع الشديد."},{"id":5044,"title":"استقلال العراق بموجب معاهدة مع بريطانيا 1927م .","date":["العام الهجري :1351","العام الميلادي :1932"],"text":"في الثالث من أكتوبر تمَّ إعلانُ استقلال العراق ودخولُه عصبة الأمم بموجِبِ المعاهدة البريطانية العراقية 1922م، التي تم تصديقها 1924م، ثم تعديلها عام 1927م، وتصديقُها من قِبَل مجلس الوزراء سنة 1930م إلا أنَّ الاستقلال لم يكن مكتَمِلًا؛ لأنَّ المعاهدة التي وُضِعَت له كان الغرضُ منها وضْعَ صيغة بديلة عن صَكِّ الانتداب، وقد واجهت معارضةً من الشعب العراقي ومقاومةً مسلحة. بموجِبِ هذه المعاهدة يعتبر العراقُ أوَّلَ دولة عربية مُنِحَت الاستقلال عن دولة الانتداب إلَّا أن هذا الاستقلال شكليٌّ وغيرُ مكتمل لاستمرار بريطانيا في فَرضِ سيطرتها على العراق بشكلٍ غيرِ مباشرٍ سواء عن طريق بنود المعاهدة البديلة عن الانتداب، أو عن طريق الصراع السياسي بين الطبقات الاجتماعية السياسية والعسكرية."},{"id":5045,"title":"ثورة ابن رفادة في شمال الحجاز .","date":["العام الهجري :1351","الشهر القمري : ربيع الأول","العام الميلادي :1932"],"text":"آلُ رِفادةَ هم شُيوخُ قَبيلةِ بَلِيٍّ من قُضاعةَ اليَمانِيَةِ مِن سُكَّانِ شَمالِ الحِجازِ، كان حامِدُ بنُ سالِمِ بنِ رِفادةَ البَلَويُّ أحَدَ شُيوخِ قَبيلةِ بَلِيٍّ ومِن فُرْسَانِها المشهورينَ، ومَعروفٌ بحامِدٍ العورِ، وكانت له صَولاتٌ وجَولاتٌ في المنطقةِ، وله كَلِمةٌ مَسموعةٌ وثِقلٌ كَبيرٌ وإن لم تكُنْ له رِئاسةُ قَبيلةِ بَلِيٍّ، كانت علاقَتُه بالأشرافِ قَوِيَّةً ومِن الموالِينَ لهم، وبعد دُخولِ المَلِكِ عَبدِ العَزيزِ الحِجازَ بايَعَه الشَّيخُ إبراهيمُ بنُ رِفادةَ بوصْفِه شَيخَ مَشايِخِ بَلِيٍّ، في حينِ رَفَضَ الشَّيخُ حامِدٌ التسليمَ والدُّخولَ تحتَ حُكمِ ابنِ سُعودٍ، وقام بالتحَصُّنِ في مدينةِ الوَجهِ، فقام الشَّيخُ إبراهيمُ بنُ رِفادةَ بمُحاصَرتِه وإخراجِه مِنَ الوَجهِ، فخرج ثائرًا، واتَّجَه إلى شَرقِ الأُرْدُنِّ ثمَّ استقَرَّ به المقامُ بمِصرَ، وهو يفكِّرُ في العَودةِ إلى الحِجازِ لإخراجِ المَلِكِ عَبدِ العزيزِ منها، فأخَذَ يُحَرِّضُ الباديةَ في شَمالِ الحِجازِ عليه، ويَجمَعُ الأنصارَ حَولَه، وانضَمَّ إلى حرَكَةِ رابطةِ الدِّفاعِ عن الحِجازِ التي أسَّسَها مجموعةٌ من الشَّخْصِيَّاتِ الحِجازيَّةِ، ثمَّ انتَقَل ابنُ رِفادةَ مِن مِصرَ إلى شَمالِ الحِجازِ بقُوَّةٍ نحوِ 400 رجُلٍ، ولَمَّا عَلِمَ المَلِكُ عبدُ العزيزِ بتحَرُّكاتِه أرسل وَحَداتٍ عَسْكَريةً لتطويقِه، وكان ابنُ رِفادةَ قد وصَلَ إلى جَبَلِ شار بضِبَا واحتَمى فيه هو وأنصارُه، فتمكَّنَ المَلِكُ عبدُ العزيزِ مِن استدراجِه مِنَ الجَبَلِ هو وقُوَّاتِه، وأوقع بهم هزيمةً قُتِلَ فيها ابنُ رِفادةَ وثلاثةٌ مِن أبنائِه ومُعظَمُ قُوَّاتِه، وبذلك انتَهَت هذه الحَرَكةُ."},{"id":5046,"title":"إعلان توحيد المملكة العربية السعودية .","date":["العام الهجري :1351","الشهر القمري : جمادى الأولى","العام الميلادي :1932"],"text":"استعاد المَلِكُ عبد العزيز الرياضَ من آل رشيد سنة 1319هـ، ثمَّ ضم إليها الخرجَ والأفلاج وبلاد نجد وما حولها، ثم ضم عنيزة وبريدة في معركة روضة مهنا، والأحساء وبقية المنطقة الشرقية، وانتزع حائل من آل رشيد، وضم عسير وقضى على آل عايض، وضم الحجاز وقضى على حُكم الأشراف نهائيًّا، وضم تهامة عسير المقاطعة الإدريسية، ثم في 21 جمادى الأولى من هذا العام 1351هـ الموافق 22 أيلول / سبتمبر 1932م صدر مرسومٌ مَلكيٌّ وحَّدَ أجزاء المملكة جميعًا، فأصبحت مملكةً واحدةً باسم (المملكة العربية السعودية) وأصبح لقب عبد العزيز مَلِكَ المملكة العربية السعودية."},{"id":5047,"title":"وفاة أمير الشعراء أحمد شوقي .","date":["العام الهجري :1351","الشهر القمري : جمادى الآخرة","العام الميلادي :1932"],"text":"هو أحمد شوقي بن علي بن أحمد شوقي، أميرُ الشعراء، ولد بالقاهرة سنة 1285 ونشأ بها، أمَّا أصلُه فأبوه تركي، وأمُّه يونانية. يقول شوقي عن نفسه: إني عربي، تركي، يوناني، جركسي، أصولٌ أربعة في فروع مجتمعة، تكفلها له مصر، وقد سمع أباه يردُّه إلى الأكراد فالعرب، ويقول: إنَّ والده قَدِمَ هذه الديار يافعًا يحمِلُ وصاةً من أحمد باشا الجزار إلى والي مصر محمد على باشا، فأدخَلَه في معيَّتِه، وظَلَّ يتقَلَّبُ في المناصب السامية حتى أقامه سعيد باشا أمينًا للجمارك المصرية. نشأ أحمد شوقي في بيئة مُترَفة؛ إذ عاش في قصر خديوي مصر؛ حيث كانت جدَّتُه من وصيفات القصر، ودخل كتَّابَ الشيخ صالح بحي السيدة زينب بالقاهرة وهو في الرابعة من عمره، ثم مدرسة المبتديان الابتدائية، ومنها إلى المدرسة التجهيزية، وقد مُنِحَ المجانية نظرًا لتفوُّقِه؛ قال الشعر في الرابعة عشرة من عمره، وأُعجِبَ به أستاذه الشيخ (حسين المرصفي).وممَّا يدُلُّ على نبوغه الشعري المبكر أنَّ أستاذه في اللغة العربية، وكان شاعرًا فصيحًا بهر بشاعريَّتِه، فكان يجلِسُ منه مجلسَ التلميذ من أستاذه، وكان هذا الشيخُ يَنظِمُ القصائد الطوال في مدح الخديوي توفيق، كلما حلَّ موسم أو جاء عيد، وقبل أن يرسِلَها إلى القصر لكي تُنشَرَ في الصحف يَعرِضُها على شوقي، فيُصلِحُ شوقي فيها، فيمحو هذه الكلمة أو تلك، ويعدل هذا الشطر أو ذاك، أو يُسقِطُ بعض الأبيات، وبعد أن أتمَّ أحمد شوقي تعليمه الثانوي التحق بمدرسة الحقوق لدراسة القانون، وقضى بها سنتين، ثم انضمَّ إلى قسم الترجمة ونال بعد سنتين إجازة للترجمة. وبحُكم تربيته في قصر الخديوي فقد أخذ يُنشِدُ قصائده في مدح الخديوي توفيق، وقد نُشِرَت أولى قصائده في جريدة الوقائع المصرية، ونظرًا لصلة شوقي بالقصر فقد أرسله الخديوي على نفقته في بعثة إلى فرنسا لإتمام دراسته في الحقوق والآداب بجامعة مونبليه بباريس، وعاد شوقي إلى مصر، فعَمِلَ في قسم الترجمة بالقصر، وظلَّ يتدرَّجُ في المناصب حتى أصبح رئيسًا لهذا القسم، وأصبح قريبًا من الخديوي عباس حلمي الذي خلف الخديوي توفيق، وأنيسَ مجلِسِه ورفيق رحلته، وأخذ شوقي يمدحُه بقصائده، حتى سمِّيَ (شاعر الأمير) ولَمَّا شبَّت الحرب العالمية الأولى خلعت إنجلترا بقوةِ الاحتلالِ الخديوي عن عرش مصر، ورأى الإنجليز يومئذ أن يغادر أحمد شوقي البلادَ بسبب شدة ولائه للخديوي، فاختار شوقي برشلونة من أعمال إسبانيا مقرًّا له ولأسرته، ولم يَعُدْ إلى مصر إلا بعد أن عاد السلام إلى العالم، فجُعِلَ من أعضاء مجلس الشيوخ إلى أن توفي. عالج شوقي أكثَرَ فنون الشعر: مديحًا، وغزلًا، ورثاءً، ووصفًا، ثم تناول الأحداثَ السياسية والاجتماعية في مصر والشرق والعالم الإسلامي، فجرى شعرُه على كل لسان. وكانت حياتُه كلها (للشعر) يستوحيه من المشاهدات ومن الحوادث. اتسعت ثروته، وعاش مُترَفًا في نعمة واسعة، ودَعةٍ تتخَلَّلُها ليال (نواسية) وسمَّى منزله (كرمة ابن هاني) وبستانًا له (عشَّ البلبل) وكان يَغشى في أكثر العشيات بالقاهرة مجالِسَ من يأنس بهم من أصدقائه، يلبثُ مع بعضهم ما دامت النكتةُ تسود الحديث، فإذا تحوَّلوا إلى جدل في سياسة أو نقاش في (حزبية) تسلَّل من بينهم، وأَمَّ سواهم. وهو أوَّلُ من جوَّد القَصَص الشعري التمثيلي، بالعربية، وقد حاول قبله أفرادٌ فبَزَّهم وتفَرَّد. وأراد أن يجمَعَ بين عنصرَيِ البيان: الشعر والنثر، فكتب نثرًا مسجوعًا على نمط المقامات، فلم يلقَ نجاحًا، فعاد منصرفًا إلى الشعر، وكان شوقي شاعرًا ذا طبع دقيق، وحِسٍّ صادق، وذوق سليم، وقد عالج شوقي الشعرَ التمثيلي، فنَظَم رواياته المعروفة؛ ومن آثاره: مصرع كليوباترا قصة شعرية، ومجنون ليلى، وقمبيز، وعلي الكبير، والست هدى، وقد جُمِعَ شِعرُه في ديوانه الشوقيات، يقع في أربعة أجزاء. وله في الشعر أيضًا كتاب عظماء الإسلام، ولشوقي نثر مسجوع جمع طائفةً كبيرة منه في كتاب اسمه: أسواق الذهب. توفي في القاهرة."},{"id":5048,"title":"تأسيس مجمع اللغة العربية بمصر .","date":["العام الهجري :1351","الشهر القمري : شعبان","العام الميلادي :1932"],"text":"تأسَّس مجمع اللغة العربية بالقاهرة عام 1351هـ، وبدأ العمل فيه سنة 1353هـ. وقد رأَسَه محمد توفيق رفعت، ثم أحمد لطفي السيد، ثم الدكتور طه حسين، ثم الدكتور إبراهيم مدكور، ثم الدكتور شوقي ضيف. وقد نَصَّ مرسومُ إنشاء مجمع اللغة العربية الذي أصدره الملك فؤاد الأول عام 1932م على أن يتكوَّنَ المَجمَع من 20 عضوًا من العلماء المعروفين بتبحُّرِهم في اللغة العربية، نصفُهم من المصريين، ونصفُهم الآخر من العرب والمستشرِقين."},{"id":5049,"title":"وفاة الملك محمد نادر شاه الأفغان وتولي ابنه محمد ظاهر .","date":["العام الهجري :1352","العام الميلادي :1933"],"text":"هو الملِكُ محمد نادر شاه بن محمد يوسف خان بن محمد يحيى خان؛ شاه أفغانستان. وكان جده الأكبر سلطان محمد خان شقيق الأمير دوست محمد خان؛ المؤسس الأوَّل لأسرة البركزاية في أفغانستان، وهو الذي باع بيشاور إلى السيخ. ولِدَ محمد نادر في ديرادون شمال الهند سنة 1883م. دخل نادر أفغانستان في سن 18 عندما سُمِحَ لجده يحيى خان بالعودة من المنفى، وفي عهد أمان الله خان دخل نادر شاه العسكريةَ سنة 1919م، وشارك في حرب الإنجليز، وبعد الحرب عيَّنه أمان الله سفيرًا في فرنسا, وفي عام 1929م اندلعت فوضى ضِدَّ الملك أمان الله، فقام ابن السقَّا أحد قطَّاع الطرق الطامعين باستغلال الأحداث، فاستولى على كابل، وفَرَّ الملك إلى قندهار وتنازل لأخيه الأكبر عناية الله، ولم يستطع عنايةُ الله مواجهةَ ابنِ السقا الذي تملَّكَ باسم حبيب الله غازي، وأخذ يعيث فسادًا في أفغانستان قرابة التسعة أشهر، حتى تمكَّن محمد نادر شاه -القائد الأفغاني الذي انتصر على الإنجليز سابقًا- من إلقاء القبض على ابنِ السقَّا وأعدَمَه، وتسلَّم أعباءَ الحكمِ، وساعده على ذلك سيرتُه الحميدة أمام الناس، وجهادُه المعروف ضد الصليبيين من روس وإنجليز، فقضى على الفوضى والفساد والرِّشوة، وقَدَّم خِدماتٍ واسعةً للبلاد، فأصلح البلادَ وحَسَّنها، ولكِنَّ أحد أبناء الذين شَمِلَهم الإعفاء من المناصب قام باغتيال الشاه محمد نادر انتقامًا لأبيه وحِقدًا على من قضى على أخذ الأموال بصورة غير شرعية بعد أن كانوا يتكسَّبون بذلك، فتسلَّم الحكمَ بعده ابنه محمد ظاهر شاه الذي لم يكن يزيد عمره على التاسعة عشرة."},{"id":5050,"title":"وفاة الشيخ إبراهيم بن محمد آل خليفة شيخ الأدباء في البحرين .","date":["العام الهجري :1352","العام الميلادي :1933"],"text":"هو الشيخ إبراهيم بن محمد بن خليفة بن سليمان آل خليفة: شيخ الأدباء في البحرين. وُلِدَ الشيخ إبراهيم بالبحرين عام 1267هـ / 1850م، وتربَّى في بيت ميسور الحال؛ فقد كان والده الشيخ محمد بن خليفة الحاكِمَ الرابع للبحرين؛ حيث عَهِدَ بتربيته إلى بعض عُلَماء نجد، فبرع باللغة العربية وآدابها، فكان من أوائل روَّاد النهضة في البحرين، وراعيَ حركتِها الأدبية والثقافية، وأحدَ رجال الإصلاح والتجديد الذين كانت لهم ريادةٌ خاصة في تأسيس التعليم الحديث الذي سبقت به البحرين شقيقاتِها في الخليج العربي، بل وحتى بعض الأقطار العربية مَشرِقًا ومغربًا. ساهم بإنشاء مدرسة الهداية الخليفية، وأسس نادي المحرق الأدبي سنة 1920م. كان الشيخ إبراهيم شاعرًا أديبًا مثقفًا واسع الإدراك، شيَّد جسورًا متينةً من الصِّلات مع قطاع كبير من المثقَّفين في عصره على امتداد الساحة العربية، وجعلَ مِن مجلِسِه في المحرق نقطةَ إشعاع لجيل أو أكثَرَ من مثقَّفي البحرين، وتحوَّل مجلِسُه إلى أول مدرسة وأول منتدًى إشعاعيٍّ للعلم والمعرفة. عاش الشيخ إبراهيم في فترة خصبة بالعطاء، وترك وراءه مجموعةً كبيرة من الشِّعر والرسائل، والتلاميذ الذين ساروا على نهجه."},{"id":5051,"title":"اكتشاف النفط في المملكة العربية السعودية .","date":["العام الهجري :1352","العام الميلادي :1933"],"text":"في عهد الملك عبد العزيز وقَّعت الحكومةُ السعودية اتفاقيةً مع شركة سوكال التي عُرِفَت فيما بعد باسم شركة الزيت العربية الأمريكية، أو أرامكو، للتنقيبِ عن الزيتِ، وبدأ البحثُ في إقليم الأحساء في النطاق الممتَدِّ من صحراء الدهناء إلى ساحل الخليج العربي، وظهر أولُ بئر في الدمام عام 1354هـ / 1935م، ولكن كميةَ الإنتاج كانت قليلةً، واستمَرَّ الحفر والتنقيب إلى أن عُثِرَ على آبار أخرى غنية استُخرِجَ منها النفطُ بكميات تجارية كبيرة جدًّا. كما قامت شركات أخرى بالتنقيب عن الزيت في أماكِنَ عدة في شرق البلاد، وأهم حقول النفط التي تم اكتشافها: حقل الدمام: وهو أول حقل اكتُشِف فيه الزيت، وحقل أبو حدرية، وحقل بقيق: يشغل هذا الحقل المركزَ الثاني في الإِنتاج، وحقل القطيف، وحقل الغوار، وحقل السفانية، وغيرها من الحقول في المنطقة الشرقية من المملكة العربية السعودية."},{"id":5052,"title":"صدور قرار ولاية العهد بعد الملك عبد العزيز .","date":["العام الهجري :1352","الشهر القمري : محرم","العام الميلادي :1933"],"text":"أمَرَ الملِكُ عبد العزيز بوضعِ نظامٍ لتولية العرش مِن بعدِه، فانعقد مجلِسَا الوكلاء والشورى، وأبرمَا قرارًا في 16 محرم 1352هـ الموافق 11/ 5 / 1933م بمبايعةِ كبير أبنائه الأمير سعود وليًّا للعهد،ثم أبرق الملِكُ على الأثرِ إلى سعود برقيةً جاء فيه: \" تفهَمُ أنَّنا نحن والناس جميعًا ما نُعِز أحدًا ولا نذِلُّ أحدًا، وإنما المعِزُّ والمذِلُّ اللهُ هو سبحانه وتعالى، ومن التجأ إليه نجا، ومن اغتَرَّ بغيره عياذَ اللهِ وقع وهلك، موقِفُك اليومَ غيرُ موقفك بالأمس؛ ينبغي أن تعقِدَ نيَّتَك على ثلاثةِ أمور: أولًا/ نية صالحة، وعزمٌ على أن تكونَ حياتُك وديدنك إعلاءَ كلمة التوحيد، ونصر دين الله، وينبغي أن تتَّخِذَ لنفسِك أوقاتًا خاصة لعبادة الله والتضَرُّع بين يديه في أوقات فراغك. تعبَّدْ إلى الله في الرخاء تجِدْه في الشدة، وعليك بالحرصِ على الأمر بالمعروف، والنهيِ عن المنكر، وأن يكون ذلك كلُّه على برهانٍ وبصيرة في الأمر، وصِدقٍ في العزيمة، ولا يصلُحُ مع الله سبحانه وتعالى إلا الصدقُ، وإلا العَمَلُ الخفيُّ الذي بين المرء وربه. ثانيًا/ عليك أن تجِدَّ وتجتهِدَ في النظر في شؤون الذين سيولِّيك الله أمْرَهم بالنصحِ سرًّا وعلانيةً، والعدلِ في المحبِّ والمُبغَض، وتحكيم الشريعة في الدقيق والجليل، والقيام بخدمتها باطنًا وظاهرًا، وينبغي ألَّا تأخُذَك في الله لومة لائم. ثالثًا/ عليك أن تنظُرَ في أمر المسلمين عامةً، وفي أمر أسرتِك خاصةً، اجعل كبيرَهم والدًا، ومتوسِّطَهم أخًا، وصغيرهم ولدًا، وهنْ نفسَك لرضاهم، وامحُ زلَّتَهم، وأقِل عَثرتَهم، وانصح لهم، واقضِ لوازِمَهم بقدر إمكانك، فإذا فهمت وصيتي هذه، ولازمت الصدق والإخلاص في العمل؛ فأبشر بالخير، وأوصيك بعلماء المسلمين خيرًا. احرص على توقيرِهم ومجالستِهم، وأخذِ نصيحتِهم. واحرِصْ على تعليم العِلمِ؛ لأنَّ الناس ليسوا بشيءٍ إلَّا بالله ثم بالعلم ومعرفة هذه العقيدة. احفَظِ الله يحفظك. هذه مقدمة نصيحتي إليك، والباقي يصلك إن شاء الله في غير هذا\"."},{"id":5053,"title":"عقد تنقيب النفط في السعودية مع شركة سوكال .","date":["العام الهجري :1352","الشهر القمري : صفر","العام الميلادي :1933"],"text":"على الرغمِ من الجُهودِ المُضنية والإغراءاتِ المتعَدِّدة التي بذلَتْها الحكومةُ البريطانية؛ من أجل حصولِ الشركات البريطانية على حقِّ امتياز التنقيبِ عن النفط إلَّا أن الملك عبد العزيز كان يدفَعُ المفاوضات باتجاه الشركات الأمريكية؛ وذلك للتخَلُّصِ من سيطرة وتحكُّم الحكومة البريطانية في الجانبِ الاقتصادي في بلادِه؛ ولذلك مَنَح إحدى الشركاتِ الأمريكية، وهي شركة سوكال \"ستاندر أويل أوف كاليفورنيا\" حقًّا استثنائيًّا لمدة 60 سنة؛ حيث وقِّعَ العقدُ معها في تاريخ 29 مايو 1933م. مثَّل الجانِبَ السعوديَّ وزيرُ المالية عبد الله السليمان، بينما مثَّل جانِبَ شركةِ سوكال هاملتون، وأقرت الحكومةُ السعودية الاتفاقيةَ بمرسومٍ ملكي في 27 يوليو 1933م، وفي عام 1936 أصبح للشركة قُدرات إنتاجية نفطية كبيرة، وفي عام 1944م تغيَّرَ اسم الشركة إلى \" أراب، أمريكانا أويل كومباني\" (أرامكو)."},{"id":5054,"title":"حل فرنسا الحزب الحر الدستوري التونسي .","date":["العام الهجري :1352","الشهر القمري : صفر","العام الميلادي :1933"],"text":"أعلن المقيمُ العامُّ الفرنسيُّ في تونس حَلَّ الحزبِ الحُرِّ الدستوري التونسي الذي استقى مبادِئَه من كتاب \"تونس الشهيدة\" لعبد العزيز الثعالبي. وكان من مطالِبِ الحزب: إرساءُ نظامٍ دستوريٍّ بتونس، والفَصلُ بين السلطات الثلاث, وضمانُ الحريات والمساواة, وإجبارية التعليم."},{"id":5055,"title":"الحركة الآشورية في العراق .","date":["العام الهجري :1352","الشهر القمري : ربيع الآخر","العام الميلادي :1933"],"text":"كان الآشوريون -وهم نصارى نساطرة- يقيمون في ولاية \"وان\" شرقيَّ الأناضول، وعاشوا تحت ظِلِّ الدولة الإسلامية آمنينَ على دمائِهم وأعراضِهم وأموالِهم، فلما اندلعت الحربُ العالمية الأولى، واستولى الروسُ على \"وان\" أغرَوا الآشوريِّينَ بالتمَرُّد على العثمانيين، وأمدُّوهم بالمالِ والسلاح، ولَمَّا انسحبت روسيا من \"وان\" بعد قيام الشيوعيَّةِ وجدت الدولةُ العثمانيةُ نفسَها مضطرةً للفَتكِ بهم؛ لِمَا أظهَروه من الخيانة والتمرُّدِ والقتل، ففَرَّ مَن استطاع منهم إلى إيران، ثمَّ عَمِلت بريطانيا على نقلِهم إلى العراق وأقاموا لهم مخيَّمات في ديالي وبعقوبة، ثم قاموا في العراق بإحداثِ عِدَّةِ فِتَن، منها فتنة سوق العتمة في محرم 1342 / 15 آب 1923م، وأخرى في رمضان من نفس العام، وهمَّت القبائل بالفتكِ بهم، فحمتهم بريطانيا، وألزمت الحكومة بإعطائهم الأراضيَ وإعفائِهم من الضرائِبِ، فأخذوا أكثَرَ ممَّا يستحقون، وعُين الضابط الإنجليزي فايكر لإسكانهم وله مطلقُ الحرية، ثم جاء إلى العراق نقيبٌ إنجليزي يُدعى هرمز رسام ادَّعى أنه نسطوري أصلُه من الموصِل، فأخذ يتجوَّلُ بين النساطرة الآشوريين ويحَرِّضُهم على طلب الانفصال عن العراق، وأسَّس جمعية لجنة إنقاذ الأقليات العراقية غير المسلِمة، وحاول الآشوريون عرقلةَ دخول العراق للأمَمِ المتحدة؛ لأنَّ بريطانيا ستتخلَّى عنهم حينَها، فأصبح بطريق الآشوريين \"مار شمعون\" يطالِبُ بسلطةٍ واسعةٍ على قومِه إداريًّا، ودعا قومَه للتمَرُّد، واستدعت الحكومةُ العراقية مار شمعون ونصحَتْه بالكَفِّ عن هذه الأفكارِ، فلم يمتَنِعْ، فمُنِعَ من العودة للمَوصِل؛ مما أثار الأوساطَ النصرانية كافةً، وكان الملك فيصل في لندن فأبرق منها بالسَّماحِ له بالعودة دون قيودٍ؛ وذلك بناءً على طلب بريطانيا منه ذلك، ولكِنَّ الحكومة لم تستجبْ ودُعِيَ بعض وجوه الآشوريين لعَقدِ مؤتمر، ولكن الآشوريين أعلنوا أنهم يريدون الانتقالَ إلى سوريا تحت حماية فرنسا، فانتقل ما يقارب من 1350 رجلًا، وأخبرت العراق فرنسا أنَّها لا تسمح بعودةِ أيِّ رجل من هؤلاء، إلَّا أن الفرنسيين أعلموا الحكومةَ العراقية في 11 ربيع الثاني 1352هـ أنهم قرَّروا إعادتهم، فأعادوهم بالسلاحِ، وبدؤوا التحرُّكَ للعراق فلاقَتْهم القوات العراقية فحصل اشتباكٌ قُتِلَ من الآشوريين ما يزيدُ على الألف، وقام النساطرة في الداخل باعتداءاتٍ على السكَّان، واضطر الملكُ فيصل للعودة من أوربا، وحاولت عُصبةُ الأمم التدخُّلَ، واندلعت الثورةُ الآشورية في عمومِ العراق في 14 من ربيع الثاني، فتشَكَّلت الوفودُ واللجان العالمية وكَثُرت الاحتجاجات وترجيات الأُمَم؛ لاستقبال المظلومين، وكل ذلك بدافع العصبية الدينية النصرانية، حتى انتهت أزمتُهم بحماية إنجلترا لهم، وإعادة تسكينِهم وتعويضِهم."},{"id":5056,"title":"وفاة الملك فيصل بن الحسين ملك العراق وتنصيب ابنه غازي .","date":["العام الهجري :1352","الشهر القمري : جمادى الأولى","العام الميلادي :1933"],"text":"هو المَلِكُ فيصل الأوَّلُ بن الحسين بن علي الحسني الهاشمي، أبو غازي ملك العراق. ولِدَ بالطائف سنة 1300هـ، وترعرع في خيام بنى عتيبة في بادية الحجاز. ورحل مع أبيه حين أُبعِدَ إلى الأستانة سنة 1308هـ، وعاد معه سنة 1327هـ، واختير نائبًا عن مدينة جدة في مجلس النواب العثماني سنة 1913م، فأخذ ينتقِلُ بين الحجاز والأستانة. زار دمشق سنة 1916م، وأقسم يمين الإخلاص لجمعية \"العربية الفتاة\" السرية. ولَمَّا ثار والده على الدولة العثمانية سنة 1916م تولى فيصل قيادةَ الجيش الشمالي. ثم سمِّي قائدًا عامًّا للجيش العربي المحارب في فلسطين إلى جانب القوات البريطانية، ودخل سورية سنة 1918م، محرم 1337هـ بعد جلاء الترك عنها، فاستقبله أهلُها استقبال المنقِذ. وسافر إلى باريس نائبًا عن والده في مؤتمر الصلح. وعاد إلى دمشق في أوائل سنة 1920م، فنودي به ملكًا دستوريًّا على البلاد السورية سنة 1338هـ - 8/ 3/ 1920م، فلما احتلَّ الجيش الفرنسي سورية طردوه من سوريا فرحل إلى أوربا، فأقام في إيطاليا ثم انتقل إلى إنجلترا. وكانت الثورة على الإنجليز لا تزال مشتعلة في العراق، فدعته الحكومةُ البريطانية لحضور مؤتمر عقدَتْه في القاهرة (سنة 1921م) برئاسة ونستون تشرشل، وتقرَّر ترشيحُه لعرشِ العراق مقابِلَ التوقيع على معاهدة تقوم مقامَ صَكِّ الانتداب، فقَبِلَ، فانتقل إلى بغداد، ونودي به ملكًا للعراق سنة 1339ه/1921م فانصرف إلى الإصلاح الداخلي، بوضع دستور للبلاد، وإنشاء مجلس للأمة. وأقام العلاقات بين العراق وبريطانيا على أسس معاهدات 1922- 1926- 1927 و1930. كان الملك فيصل في سويسرا في مستشفى برن، ثم لَمَّا تعافى رجع للعراق بسبب ثورة الآشوريين، ثم رجع إلى أوربا للاستجمامِ إلَّا أنَّ بعض الأطباء نصحه بدخول المستشفى مع أنَّ حالته الصحية كانت جيدة، وهذا ما ولَّد عند البعض أنَّ موتَه لم يكن طبيعيًّا؛ حيث توفِّيَ بعد دخوله المستشفى، فنُقِلَ جثمانه إلى بغداد ودفن فيها بعد أن قضى في الملك اثنتا عشرة سنة وخمسة أشهر، ثم بويع ابنه غازي ملكًا على العراق يوم وصول خبر وفاة أبيه، وكان عمره يومذاك اثنتين وعشرين سنة."},{"id":5057,"title":"قيام جمهورية إسلامية في تركستان الشرقية .","date":["العام الهجري :1352","الشهر القمري : رجب","العام الميلادي :1933"],"text":"قامت ثورةٌ عارمة في تركستان الشرقية ضِدَّ الصين سنة 1350هـ / 1931م كان سببُها تقسيمَ الحاكم الصيني المنطقةَ التي يحكمها \"شاكر بك\" إلى وحداتٍ إدارية، فبدأ التذمُّر، ثم وقع اعتداءٌ على امرأةٍ مسلمة من قِبَل رئيس الشرطة، فامتلأ الناسُ غيظًا وحِقدًا على الصينيين، وتظاهروا بإقامة حفلٍ على شَرفِ رئيس الشرطة وقَتَلوه أثناء الحَفلِ مع حرَّاسه البالغ عددُهم اثنين وثلاثين جنديًّا. وقد كانت ثورةً عنيفة، اعتصم خلالها بعضُ المسلمين في المرتفعات، ولم تستطع القواتُ الصينية إخمادَها، فاستعانوا بقوات من روسيا فلم تُجْدِ نفعًا مع بركان الغضب المسلِم، وانتصر المسلِمون عليهم، واستولوا على مدينة \"شانشان\"، وسيطروا على \"طرفان\" -شمال تركستان الصينية غرب الصين-، واقتربوا من \"أورومجي\" -مدينة في شمال غربي الصين- قاعدة تركستان الشرقية. وأرادت الحكومةُ الصينية تهدئةَ الأوضاعِ، فعزلت الحاكمَ العامَّ، غير أن المسلمين كانوا قد تمكَّنوا من الاستيلاء على \"أورومجي\"، وطردوا الحاكِمَ العامَّ قبل أن تعزِلَه الدولة، وتسلَّم قادةُ المسلمين السلطةَ في الولاية، ووزَّعوا المناصب والمراكز على أنفُسِهم، فما كان من الحكومة الصينية إلا أن رضخت للأمر الواقع، واعترفت بما حدث، وأقرَّت لقادة الحركة بالمراكز التي تسلَّموها. وقد امتَدَّ هذا الأمر إلى منطقة تركستان الشرقية كلِّها، وقام عددٌ من الزعماء بالاستيلاء على مدنهم، ثم اتجهوا إلى \"كاشغر\" -أشهر مدن تركستان الشرقية- واستولوا عليها، وكان فيها \"ثابت داملا\" أي: الملا الكبير، فوجدها فرصةً وأعلن قيامَ حكومة \"كاشغر الإسلامية\"، أما \"خوجانياز\" أو \"عبد النياز بك\"، فقد جاء إلى الثائرين في كاشغر ليفاوِضَهم وينهي ثورتَهم، إلا أنه اقتنع بعدالةِ ثورتِهم، فانضَمَّ إليهم وأعلن قيامَ حكومة جديدة باسم \"الجمهورية الإسلامية في تركستان الشرقية\"، وكان ذلك في (2 رجب 1352هـ / 12 نوفمبر 1933م، وقد اختير \"خوجانياز\" رئيسًا للدولة، و\"ثابت داملا\" رئيسًا لمجلس الوزراء. ولم تلبث هذه الحكومة طويلًا، فقد ذكر \"يلماز أوزتونا\" في كتابه \"الدولة العثمانية\" أنَّ الجيشَ الصيني الروسي استطاع أن يهزم \"عبد النياز بك\" مع جيشه البالغ (80) ألف جندي، بعد مقتل \"عبد النياز\" في 6 جمادى الآخرة 1356هـ / 15 أغسطس 1937م، وبذلك أسقط التحالفُ الصيني الروسي هذه الجمهوريةَ المسلِمةَ، وقام بإعدام أعضاء جميع أعضاء الحكومةِ مع عشرة آلاف مسلمٍ."},{"id":5058,"title":"افتتاح الخط الحديدي بين مراكش وتونس .","date":["العام الهجري :1352","الشهر القمري : شعبان","العام الميلادي :1933"],"text":"افتُتِحَ الخَطُّ الحديدي بين مراكش وتونس، وهو الخط الذي يربط بين الممتلكات الفرنسية، ويمكِّنُها من إرسال قوات من تونس إلى موانئ مراكش الواقعة على المحيط الأطلسي، وبذلك تتفادى طريق البحر المتوسط المحفوف بالأخطار."},{"id":5059,"title":"الحرب اليمنية السعودية  .","date":["العام الهجري :1352","الشهر القمري : ذي الحجة","العام الميلادي :1934"],"text":"قامت في اليمن حركةٌ بقيادة الإمام يحيى حميد الدين واجه فيها الدولةَ العثمانية التي انسحبت من اليمن في أعقاب الحرب العالمية الأولى فصفا له الجوُّ فيها. ويفصل بينه وبين مُلك الملك عبدالعزيز إمارة آل عائض في أبها، وإمارة آل إدريس في جازان، وقد قامت فيهما فِتَنٌ وأحداث انتهت بانضمامِهما إلى حكم الملك عبدالعزيز، وقد لجأ الحسَنُ الإدريسي وجمَعَ من أقاربه وخاصته إلى اليمن في ضيافة الإمام يحيى، وكان الملك عبد العزيز يصِلُهم بالإنفاق عليهم وهم هناك, وفي هذا العام تقدَّم جندٌ من جيش الإمام يحيى إلى جبال جازان بتحريضٍ من الحسن الإدريسي حتى وصلوا نجران, فلما علِمَ الملك عبد العزيز استعظمه وكتب للإمام يحيى يدعوه للاتفاق على رسمِ الحدود، فاجتمع مندوبو الطرفين دون أن يتمَّ الاتفاق على الحدود، فوجه الملك عبد العزيز إنذارًا للإمام يحيى لسَحبِ قوَّاتِه من نجران، ولَمَّا مضت مدة الإنذار ولم يكن له أثرٌ وجَّه الملك عبد العزيز جيشين في ذي الحجة أحدُهما بقيادة الأمير سعود بن عبد العزيز إلى الشمال ووجهته الجبل، فكانت وقعة حرض، وتوغَّل سعود في جبل السراة واقترب من غمدان، والجيشُ الثاني بقيادة الأمير فيصل بن عبد العزيز اتجه إلى الجنوب على الشاطئ، فاستولى على الحُديدة وبيت الفقيه وغيرهما، وبدَّد كل مقاومةٍ اعترضَتْه، وانهار جيش الإمام يحيى في أقل من شهر، فأبرق إلى مصر يستنجِدُ بالملك فؤاد فاعتذر منه لعدم استطاعته، فأُسقِطَ في يد الإمام يحيى، وانسحب من نجران، فأمر الملك عبدالعزيز بوَقفِ الزحف في 11 محرم 1353ه، وبدأت إجراءات التفاوض التي انتهت بمعاهدة الطائف."},{"id":5060,"title":"موازنة الدولة في عهد الملك عبد العزيز ونموها .","date":["العام الهجري :1353","العام الميلادي :1934"],"text":"كان خُمسُ الغنائم التي تحصُلُ عليها الدولة من الحروب التي حدثت في أيام تأسيس الدولة وتوحيد الجزيرة تشَكِّلُ جزءًا من إيرادات الدولة، وفي عام 1344ه أصدر الملك عبد العزيز مرسومًا يحدِّدُ مقادير الزكاة الشرعية، وطرق جبايتها، وكلَّف أمراءَ المقاطعات بالإشراف على استيفائها، وبعد ضَمِّ السواحل الشرقية للجزيرة العربية فَرَض رسومًا جمركية، ومع ذلك ظلت موارد الدولة فقيرةً مقابِلَ احتياجات الدولة لتمويل العمليات العسكرية لتوحيدِ البلاد، وإجراءات تأسيس الدولة الحديثة؛ فقد بلغت مجمل ضرائب عام 1346هـ: 1.5 مليون جنيه استرليني، وكانت أول محاولة أُجرِيَت لوضع ميزانية ثابتة للدولة في 1348هـ/ 1929م. تقرَّر اعتماد ميزانية للدولة في عام 1353هـ / 1934م، وقد فُصِّلَت فيها أبواب الواردات والنفقات العامة، واتُّبِع في وضعها طريقة تكليف الدوائر الرسمية أن تضَعَ مشروعات مفَصَّلة لموازنتها، ثم تقَدِّمَها إلى وزارة المالية، فتَدرُسَها وتبديَ ملاحظاتها عليها. ثم تحال إلى مجلس الشورى فيدَقِّقها ويحيلها إلى مجلس الوكلاء لرفعها واستصدار الموافقة الملكية عليها. وبلغت النفقات في موازنة هذا العام 1353ه حوالي 14 مليون ريال، وقُدِّرَت الواردات بمثل ذلك، وبعد اكتشاف النفط بلغت نفقات الدولة في عام 1367ه / 1948م \"214.586.500\" ريال، ومثلها تقدير الواردات، بحيث تضاعفت ميزانية هذا العام عن عام 1353 ما يزيد على 15 ضعفًا!"},{"id":5061,"title":"هجرة اليهود إلى فلسطين ووصول اثنين وأربعين ألف يهودي .","date":["العام الهجري :1353","العام الميلادي :1934"],"text":"منذ أواسط القرن التاسع عشر الميلادي كان لليهود محاولات للتسلُّل إلى فلسطين، وعندما عَلِمَ سلاطين الدولة العثمانية وضعوا قوانين صارمة لمنع مثل هذه التسلُّلات، وعاش من كان في فلسطين كأقليةٍ تعتمد على المعونات الخارجية، ثم بعد اضطهاد قيصر روسيا لليهود بسبب محاولتِهم اغتيالَه بدأ قسم كبيرٌ منهم بالهجرة إلى فلسطين، فقَدِمَ الفوجُ الأول إلى فلسطين سنة 1823م وأنشؤوا بعض المستوطنات بين يافا والقدس، لكِنَّها كادت أن تفشل لولا دعم روتشيلد بالأموال الطائلة، ثم قام السلطان عبد الحميد بعرقلة كثيرٍ من هذه العمليات بوضع القوانين الصارمة، أما الفوجُ الثاني فمن سنة 1903م إلى 1914م فقد تراوح عددهم ما بين خمسة وثلاثين ألفًا إلى خمسة وأربعين ألفًا معظمُهم من روسيا، ويتميزون بشدة تعصُّبهم للصهيونية، وشَيَّدوا المستعمرات الصهيونية بأيديهم، وكان ذلك أيام جماعة الاتحاد والترقي، أما الفوجُ الثالث من 1919م إلى 1923م فقُدِّرَ بخمسة وثلاثين ألفًا، وكانت خلال الانتداب البريطاني على فلسطين، وقاموا بتشكيلِ دائرة الهجرة في فلسطين، وبدأ اليهود يَقدَمون من كافة أنجاء أوربا؛ كألمانيا، وبولندا، ورومانيا، ومن اليمن، وأمريكا، وغالبهم أصحاب أموال واستثمارات ضخمة وأصحاب خبرات علمية."},{"id":5062,"title":"وفاة ليج أياسو إمبراطور الحبشة المسلم .","date":["العام الهجري :1353","العام الميلادي :1934"],"text":"هو ليج أياسو بن محمد علي إمبراطور الحبشة المسلم. في أواخِرِ القرن التاسع عشر الميلادي قام إمبراطورُ الحبشة منليك الثاني النصراني بدعمٍ وتحريضٍ من أوروبا الاستعمارية بشَنِّ حملة كبيرة على الإمارات الإسلامية التي كانت تقوم على معظم أراضي الحبشة، فنجح في احتلالِ مدينة هرر عاصمة إمارة هرر المسلمة، وتساقطت بعدها بقيةُ الإمارات المسلمة التي كانت متفرقةً وضعيفة، ثم زوَّج إمبراطور الحبشة منليك ابنته إلى محمد علي أمير إمارة ويلو المسلِمة في مسعًى منه لاجتذاب المسلمين، ومن هذا الزواج وُلِدَ ليج أياسو. وبعد أن هلك منليك الثاني عام 1913 تسلَّم العرشَ حفيدُه ليج أياسو الذي كان في الثامنة عشرة من عمره، فأظهر الإمبراطور ليج الإسلامَ ولَبِسَ العمامة واستبدل بعلم الدولة علمًا في قلبه الهلال بدل الصليب، وأرسله إلى القنصل العثماني في أديس أبابا، ثمَّ نقل عاصمةَ حكمه إلى مدينة هرر الإسلامية، وبنى المساجِدَ في هرر، وديرداوا، وجكجكا، بل واتصل بالقائدِ المسلم محمد عبد الله حسن مهدي الصومال، والذي كان يحارب الإنجليزَ هناك، فثارت ثائرةُ الكنيسة الحبشية، ورفضت تتويج ليج أياسو، بل أصدرت قرارًا بحِرْمانه من التاج؛ ممَّا اضطره إلى الهرب إلى بلاد الدناقل (أريتيريا) بعد أقل من 3 سنوات من تولِّيه الحكم؛ حيث بقي هناك إلى أن قُبِضَ عليه عام 1921، ثمّ قَتَله الهالكُ هيلا سيلاسي."},{"id":5063,"title":"سفر الأمير فاروق ابن الملك فؤاد للدراسة في بريطانيا .","date":["العام الهجري :1353","العام الميلادي :1934"],"text":"لَمَّا بلغ الأمير فاروق سن الرابعة عشرة طلب السير مايلز لامبسون من الملك فؤاد ضرورةَ سفر ابنه الأمير فاروق إلى بريطانيا لمواصلةِ الدراسة وأصَرَّ على ذلك بشدة رافضًا أيَّ محاولة من الملك فؤاد لتأجيل سفره حتى يبلغ سن السادسة عشرة، فتقرَّر سفرُ فاروق إلى بريطانيا ولكن دون أن يلتحِقَ بكلية إيتون، بل تم َّإلحاقه بكلية وولتش للعلوم العسكرية؛ ونظرًا لكونه لم يبلغ الثامنة عشرة -وهو أحد شروط الالتحاق بكلية وولتش- فقد تم الاتفاق على أن يكون تعليمُه خارج الكلية على يد معلِّمين من نفس الكلية، وقد رافق فاروق خلال سفرِه بعثةٌ مُرافِقةٌ له برئاسة أحمد حسنين باشا؛ ليكون رائدًا له -والذي كان له دور كبير في حياته بعد ذلك- بالإضافة إلى عزيز المصري الذي كان نائبًا لرئيس البعثة وكبيرًا للمعلمين، بالإضافة إلى عمر فتحي حارسًا للأمير وكبير الياوران فيما بعد، وكذلك الدكتور عباس الكفراوي كطبيب خاص، وصالح هاشم أستاذ اللغة العربية، بالإضافة إلى حسين باشا حسني كسكرتير خاص، والذي كان وجوده عاملًا مساعدًا للأمير على الانطلاق؛ فقد شجَّعه على الذهاب إلى المسارح والسينما ومصاحبة النساء ولعب القمار، بينما كان عزيز المصري دائم الاعتراض على كل تلك التصرفات، وكان فاروق بحُكمِ ظروف نشأته القاسية والصارمة يميل إلى حسين باشا ويتمرَّدُ على تعليمات وأوامر عزيز المصري، وفي تلك الفترة كان المرض قد اشتَدَّ على الملك فؤاد، وأصبح على فراش الموت، فاقترحت بريطانيا تشكيل مجلس وصاية مكوَّن من ثلاثة أعضاء، هم: الأمير محمد علي توفيق؛ ابن عم الأمير فاروق، وقد كان ذا ميول إنجليزية، وكان يرى دائمًا أنه أحق بعرش مصر، والثاني: هو محمد توفيق نسيم باشا، رئيس الوزراء الأسبق، وهو من رجال القصر، والثالث: هو الإمام الأكبر الشيخ المراغي، وعندما علم الأمير فاروق بشدَّةِ مرض والده ورغبته في أن يرى ابنه، طلب العودةَ إلى مصر لرؤية والده ووافقت بريطانيا بعد تردُّد على عودة فاروق إلى مصر في زيارة ليعودَ بعدها لاستكمال دراسته إلَّا أنه وقبل أن يسافر فاروق إلى مصر لرؤية والده كان والده الملك فؤاد الأول قد لقِيَ ربه في 28 أبريل 1936م. وعاد فاروق إلى مصر وقطع دراستَه ليجلس على كرسي العرش."},{"id":5064,"title":"معاهدة الطائف بين اليمن والسعودية .","date":["العام الهجري :1353","الشهر القمري : صفر","العام الميلادي :1934"],"text":"بعد أن توقَّف زحفُ الجيش السعودي على اليمن بقيادة الأمير سعود والأمير فيصل، استدعى الملكُ عبد العزيز عبدَ اللهِ ابنَ الوزير إلى الطائِفِ، وأطلَعَه على برقية الإمام يحيى -التي أرسلها بعد انهيار قوات جيشه- ثمَّ أملى الملك عبد العزيز على ابن الوزير ومن حضر من المستشارين السعوديين فقراتٍ أشبَهَ بالمواد التي تُبنى عليها معاهدةٌ للصلح، فتولى المستشارون وابن الوزير صياغتَها، فكانت معاهدة الطائف، ثم جرى توقيعها في جدة -بعد أن اطَّلع الإمامُ يحيى على نصها- في 6 صفر 1353ه - 21/ 5/ 1934م. على أن تكون الحُديدة لليمن، وجازان ونجران وعسير وتوابعها للسعودية، وقد وقَّعه نيابةً عن الملك عبد العزيز ابنُه الأمير خالد بن عبد العزيز، ونيابة عن الإمام يحيى عبدُ الله بن أحمد الوزير، وقد نصت المعاهدة على 23 مادة وملحق فيه خمس مواد، وممَّا ورد في هذه المعاهدة: 1/ تنتهي حالة الحرب القائمة بين البلدين بمجرَّد توقيع المعاهدة، وتنشأ فورًا بينهما حالةُ سلم دائم وصداقة وطيدة، وأُخوَّة إسلامية عربية دائمة. 2/ يعترف كل منهما للآخر باستقلالِ كُلٍّ من المملكتين استقلالًا تامًّا مطلقًا، ويُسقِطُ كلٌّ منهما أيَّ حَقٍّ يدعيه في قسم أو أقسام من بلاد آخر خارج الحدود القطعية المبينة في صلب هذه المعاهدة. 3/ خطُّ الحدود الذي يفصل بين بلاد كلٍّ مِن الفريقين المتعاقدين موضَّحٌ بالتفصيل الكافي كما هو في نص المعاهدة، ويعتبر هذا الخط حدًّا فاصلا قطعيًّا بين البلاد التي تخضع لكل منهما. 4/ نظرًا لرغبة الفريقين في دوام السلم والطمأنينة يتعهدان تعهدًا متقابلًا بعدم إحداث أي بناء لحصون في مسافة خمسة كيلومترات في كل جانب من جانبي الحدود في كل المواقع والجهات على طول خط الحدود. 5/ يتعهَّدُ كل من الفريقين بأن يسحب جندَه فورًا عن البلاد التي أصبحت بموجِبِ هذه المعاهدة تابعة للفريق الآخر، مع صون الأهلين والجند عن كل ضرر. 6/ يتعهد كل من الفريقين بأن يمنع كُلٌّ منهما أهاليَ مملكته عن كلِّ ضَررٍ وعدوان على أهالي المملكة الأخرى في كل جهةٍ وطريق، وبأن يمنعَ الغزوَ بين أهل البوادي من الطرفين، ويَرُدَّ كلَّ ما ثبت أخذه بالتحقيق الشرعي من بعد إبرام هذه المعاهدة، وضمان ما تَلَف وبما يلزم بالشَّرعِ فيما وقعَ من جناية قَتلٍ أو جرحٍ، بالعقوبة الحاسمة على من ثبت منهم العدوان. 7/ يتعهد كل من الفريقين تعهدًا متقابلًا بأن يمتنعا عن الرجوع للقوة لحلِّ المشكلات بينهما، وبأن يعملا جهدَهما لحلِّ ما يمكنُ أن ينشأ بينهما من الاختلاف، سواء كانت سببه ومنشؤه هذه المعاهدة، أو تفسير كل أو بعض موادها، أم كان ناشئًا عن أي سبب آخر بالمراجعات الودِّية."},{"id":5065,"title":"أمر أتاتورك بإيقاف الصلاة في جامع آيا صوفيا .","date":["العام الهجري :1353","الشهر القمري : رجب","العام الميلادي :1934"],"text":"أصدرت الحكومةُ التركيةُ برئاسة مصطفى كمال أتاتورك قراراً حكوميًّا بتوقف الصلاة في جامع آيا صوفيا، ونَزعِ سجاجيده، ومنبره، ولوحاته المكتوبة باللغة العربية، وتحويلِه إلى متحف سياحي!!"},{"id":5066,"title":"محاولة الاعتداء على الملك عبد العزيز في الحرم (حادث المطاف) .","date":["العام الهجري :1353","الشهر القمري : ذي الحجة","العام الميلادي :1935"],"text":"في صباح يوم النحر بينما كان الملك عبد العزيز يطوف طوافَ الإفاضةِ كعادته كلَّ سنةٍ في هذا الوقتِ مع قِلَّةٍ مِن الحُجَّاج، وخلفه ابنه الأمير سعود وبعض رجاله، وبعد استلامِه الحجرَ الأسود في بداية الشوط الخامس هجم عليه رجلٌ من فجوةٍ في الحِجْر عليه بَزَّة يمانية، وقد سَلَّ خِنجَرَه وهو يصيح صيحاتٍ مُنكرةً وانقض على المَلِك من ورائِه لِيطعَنَه بالخنجر فألقى سعود نفسَه على أبيه ودفع الرجلَ بيده الذي أطلق عليه حَرَس الملك فقَتَلوه، ثم انقَضَّ رجل آخر من فجوة ثانية من الحِجْر على الملك فجاءت الضربةُ في كتف الأمير سعود وعاجله رجالُ الملك عبدالعزيز فقتلوه، وكان هناك رجلٌ ثالث لما رأى مصرع صاحبيه أراد الفرارَ، لكِنَّ الحرس تمكَّنوا من قتْلِه، مرَّ الحادث وقُتِلَ فيه المعتدون الثلاثة وجُرِح الأمير سعود في كتفه الأيسر، كما قُتِلَ جندي واحد فقط، وجُرِح آخر، ثمَّ تلقى الملِكُ برقيةً من الإمام يحيى يستنكر بها الحادِثَ ويستفظعه ويتبرَّأُ منه."},{"id":5067,"title":"وفاة الشيخ محمد رشيد رضا .","date":["العام الهجري :1354","الشهر القمري : جمادى الأولى","العام الميلادي :1935"],"text":"هو الشيخُ محمد رشيد بن علي رضا بن محمد شمس الدين بن محمد بَهاء الدين بن منلا علي خليفة القلموني؛ البغدادي الأصل، الحسيني النَّسَب (على خلاف في صحة نسبه لآل البيت)، وهو أحَدُ رجال الإصلاح الديني في العصر الحديث. كان متعَدِّدَ الجوانب والمواهب، فكان مفكِّرًا إسلاميًّا غيورًا على دينه، وصحفيًّا نابهًا، وكاتبًا بليغًا في كثير من الصحف، ومفسرًا نابغًا، ومحدثًا مُتقِنًا في طليعة محدثي العصر، وأديبًا لغويًّا، وخطيبًا مفوَّهًا تهتَزُّ له أعواد المنابر، وسياسيًّا يشغل نفسَه بهموم أمته وقضاياه، ومربيًا ومعلِّمًا يروم الإصلاحَ ويبغي التقدم لأمته. أنشأ مجلة \"المنار\" ذات الأثر العميق في الفكر الإسلامي. ولِدَ في قرية القلمون بلبنان في 27 جمادى الأولى 1282هـ. كان الشيخ رشيد رضا من أكبر تلامذة محمد عبده، وقد تأثر به كثيرًا، واعتُبر واحدًا من روَّاد الإصلاح الإسلامي في مطلع القرن الرابع عشر الهجري، وقد تأثَّر بمنهج شيخ الإسلام محمد بن عبد الوهاب، وأقبل على كتبِ شيخِ الإسلام ابن تيمية فنَهل منها وتأثر بمنهجِه، وأصبح مرجِعَ الفتيا في التأليف بين الشريعة والأوضاع العصرية الجديدة. لما أُعلِنَ الدستور العثماني سنة 1326ه زار بلادَ الشام، واعترضه في دمشق، وهو يخطب على منبر الجامع الأموي، أحَدُ أعداء الإصلاحِ، فكانت فتنةٌ عاد على إثرها إلى مصر. وأنشأ مدرسة (الدعوة والإرشاد) ثم قصَدَ سورية في أيام الملك فيصل بن الحسين، وانتُخِبَ رئيسًا للمؤتمر السوري فيها. وغادرها على إثر دخول الفرنسيين إليها سنة 1920م، فأقام في وطنه الثاني مصر مدةً. ثم رحل إلى الهند والحجاز وأوربا. وعاد فاستقر بمصرَ إلى أن توفي فيها. أصدر مجلة المنار في 22 شوال 1315هـ، وحرَصَ الشيخ رشيد على تأكيدِ أنَّ هدَفَه من المنار هو الإصلاح الديني والاجتماعي للأمة، وبيان أنَّ الإسلامَ يتَّفِق والعقل والعلم ومصالح البشر، وإبطال الشبهات الواردة على الإسلام، وتفنيد ما يُعزَى إليه من الخرافات؛ ممَّا جعلها تنتشر انتشارًا واسعًا في العالم الإسلامي، وأصبحت مجلته هي المجلةَ الإسلامية الأولى في العالم الإسلامي، كتب رشيد مئات المقالات والدراسات، وخَصَّ العلماء والحكام بتوجيهاته، ومن مؤلفاته: \"تفسير المنار\" الذي استكمل فيه ما بدأه شيخه محمد عبده، والذي توقف عند الآية (125) من سورة النساء، وواصل رشيد رضا تفسيره حتى بلغ سورة يوسف، وحالت وفاتُه دون إتمام تفسيره، وله أيضًا: الوحيُ المحمدي ونداء للجنس اللطيف، وتاريخ الأستاذ الإمام، والخلافة، والسنة والشيعة، وحقيقة الربا، ومناسك الحج. توفي -رحمه الله- وهو عائِدٌ من توديع الأمير سعود بن عبد العزيز بالسويس، ورفض المبيتَ في السويس للراحة، وأصَرَّ على الرجوع، وكان طول الطريق يقرأ القرآنَ كعادته، ثم أصابه دوارٌ من ارتجاج السيارة، وطلب من رفيقيه أن يستريحَ داخل السيارة، ثم لم يلبث أن توفِّيَ، وكان ذلك في يوم الخميس الموافق 23من جمادى الأولى، وكانت آخِرُ عبارة قالها في تفسيره: \"فنسأله تعالى أن يجعَلَ لنا خيرَ حَظٍّ منه بالموتِ على الإسلامِ\"."},{"id":5068,"title":"وفاة القائد السوري \"إبراهيم هنانو\" .","date":["العام الهجري :1354","الشهر القمري : شعبان","العام الميلادي :1935"],"text":"القائدُ السوري \"إبراهيم بن سليمان بن أغا هنانو\" المعروف بـ\"إبراهيم هنانو\". قاد حركةَ الجهاد ضِدَّ المحتَلِّ الفرنسي بعد معركة \"ميسلون\". ولِدَ في حلب 1286هـ / 1869م، وتلقَّى تعليمَه في تركيا، وعَمِلَ في الوظائف الإدارية بسوريا. لَمَّا احتَلَّ الفرنسيون مدينةَ أنطاكية انتُدِبَ لتأليف عصابات عربية تُشاغِلُ الفرنسيين، وجعل مقَرَّه في حلب، وفوجِئَت سورية بنكبة ميسلون سنة 1338هـ، واحتلال الفرنسيين دمشق وحلب وما بينهما، فامتنع إبراهيمُ في بلاد بيلان (شمالي حلب) بقوةٍ مِن المتطوعين الوطنيين، ولَمَّا قاتله الفرنسيون ظفر بهم، وألف حكومةً وطنية، ولُقِّبَ بالمتوكل على الله، وكثُرَت جموعه واتسع نطاقُ نفوذه، خاض سبعًا وعشرين معركة لم يُصَبْ فيها بهزيمة، واستمَرَّ عامًا كاملًا ينفق مما يَجبيه عمالُه في الجهات التي انبسط فيها سلطانُه. ولما قدِمَ الشريف عبد الله بن الحسين عمان لتحرير سورية من الفرنسيين كاتَبَه إبراهيم، ثم قصده للاتفاق معه على توحيد الخطط، فاعترضته في طريقه قوةٌ كبيرة من الجيش الفرنسي يعاوِنُها بعض الإسماعيليين من سلمية، فقاتلهم، ونجا وبعضَ من كان معه، فبلغ عاصمة الأردن، فلم يجد فيها ما أمّل من الشريف عبد الله، فزار فلسطين، فاعتقله البريطانيون في القدس وسَلَّموه إلى الفرنسيين، الذين أخذوه إلى حلب، وحُكِمَ عليه فيها بالقتل، لكِنَّ القاضيَ الفرنسيَّ حَكَم ببراءته وأطلق سراحَه، وبعد محاكمته تحوَّل من العمَلِ الجهادي إلى العمل السياسي، واجتمعت على زعامته سوريةُ كلُّها, وقادها فأحسَنَ قيادَتَها. وكان منهاجُه: لا اعترافَ بالدولة المنتَدَبة فرنسة، ولا تعاونَ معها، واستمر إلى أن توفِّيَ بحلب."},{"id":5069,"title":"فوز حزب الوفد بأغلبية مقاعد مجلس النواب في مصر .","date":["العام الهجري :1355","العام الميلادي :1936"],"text":"فاز حزبُ الوفدِ بأغلبية مقاعِدِ مجلس النواب في الانتخابات التي أُجريت في البلاد، وقام مصطفى النحاس باشا رئيسُ حزب الوفد بتشكيلِ وزارة وفدية تمكَّنَت من عقد مفاوضات بين مصر وبريطانيا، فنتج عن تلك المفاوضات معاهدة 1936م."},{"id":5070,"title":"الاتحاد السوفيتي يعلن عن قيام جمهورية قيرغيزيا ويضمها إلى امبراطوريته .","date":["العام الهجري :1355","العام الميلادي :1936"],"text":"بدأ الاستعمارُ الروسيُّ في فيرغيزيا عام 1866م، وقد أدَّى الاحتلالُ الروسي لقيرغيزيا إلى تناقُصِ عَدَدِ القيرغيز؛ بسبب الثوراتِ، والهروب من البلاد، والموت جوعًا، وحرب الإبادة التي مارسها الروسُ ضِدَّ القيرغيز؛ ففي سنة 1916م قامت ثورة قُتِلَ فيها 150 ألف قيرغيزي، ومات جوعًا من القيرغيز أثناء هربهم إلى الصين -إبَّان طغيان الحكم الشيوعي والسيطرة الروسية من قَبلُ- عشرات الآلاف، وأثناء الحكم الشيوعي منذ عام 1936م حتى عام 1991م سيطر الشيوعيون على كلِّ نواحي الحياة في البلاد، وأطلقوا على عاصمة البلاد اسم فرونزى نسبةً إلى القائد الروسي ميخائيل فرونزي الذي قاد الجيشَ الروسي في قتال القيرغيز واستعمار بلادهم، وكان الروسُ يشَجِّعون العداء بين القيرغيز وسكان الصين، وبدؤوا يغَيِّرون التاريخ والآداب والثقافة القيرغيزية، واتهموا الشعراء والأدباء وكتَّاب القصة بأنهم يفضِّلون الثقافة القيرغيزية على الروسية. وقد قامت السياسة الروسية السوفيتية السابقة على مبدأ تحريم استخدام الحروف العربية في كتابة اللغة التركية، وأصدر الروسُ أمرًا مركزيًّا يفرِضُ على مسلمي تركستان -ومن بينهم القيرغيز- اتخاذ الحروف الروسية (الكيريلية) بديلًا، وكان هذا عام 1940م. ليس هذا فقط بل قام نظام التعليمِ السوفيتي باقتلاع مسلمي قيرغيزيا من الإسلام، وبالفعل مُنِعَ التعليمُ الديني بكافَّة صوره وأشكاله، بل حُرِّم الإسلامُ وجُرِّمَ من آمَن به، وقد نسِيَ مسلمو قيرغيزيا العبادةَ وجَهِلوا دينَهم الذي حرَّم السوفييت عليهم أن يتعلَّموه وأن يُعلِّموه، ومع أن الطفلَ القيرغيزي -منذ قيام الثورة الشيوعية- كان يتلقى في المدارس والجامعات والنوادي والاجتماعات الإيمانَ بالماركسية، وماركس، ولينين، وستالين وغيرهم من رموز الإلحاد، لكِنَّ نظام التعليم الروسي لم يستطِعْ أن يقلَعَ من النفوس ومن القلوب ومن المشاعر الإيمانَ بأنْ لا إلهَ إلَّا الله وأنَّ محمدًا رسولُ الله -صلى اللهُ عليه وسلم- فكانت الأمُّ والأب يلقِّنان الأولادَ أنَّ إسلامَهم أعظمُ وأكبَرُ من كل دعاوى الماركسية ونظام البلاد، وقام الروس أيضًا بتشجيع الهجرة للروس إلى قرغيستان، حتى أصبحوا يقاربون عدد السكان الأصليين إنْ لم يزيدوا. عندها أعلنت روسيا قيامَ جمهورية قرغيستان التابعة للاتحاد السوفيتي."},{"id":5071,"title":"معاهدة 1936 المصرية البريطانية (معاهدة الشرف والاستقلال) .","date":["العام الهجري :1355","العام الميلادي :1936"],"text":"وقَّع مصطفى النحاس -وهو رئيس الوزراء- ووزير الداخلية، ووزير الصحة: المعاهدةَ مع إنجلترا والتي عُرِفَت بمعاهدة 1936 وتنُصُّ على إنهاء الاحتلال العسكري والوصاية البريطانية، مع استثناء بعض القواعد العسكرية للدفاع عن وادي النيل وقناة السويس ضِدَّ أي عدوان خارجي، ووضْع الأراضي المصرية وطرق مواصلاتها ومطاراتها وموانيها تحت تصرُّف الجيش البريطاني في حالةِ قيام حرب، وتخلِّي إنجلترا عن المصالح الأجنبية، وتعهُّد إنجلترا بقَبولِ مِصرَ في عضوية عصبة الأمم، وإبقاء السودان شركةً بين مصر وإنجلترا، وتعهَّد الطرفانِ بعدم عقدِ معاهدة سياسية تتعارَضُ مع مضمون هذه المعاهدة، ومُدَّة المعاهدة عشرون سنة، ويعاد النظرُ بعدها فيها. وعاد مصطفى النحاس من لندن إلى مصر وبدأ يروِّجُ المعاهدةَ ويدعو إلى تأييدها، وأطلق عليها اسمَ معاهدة الشرف والاستقلال. فانشَقَّ أحمد ماهر وفهمي النقراشي عن حزب الوفدِ وشَكَّلا الهيئةَ السعديةَ، وألقيت قنبلةٌ على دُورٍ للسينما يرتادُها ضباط إنجليز ذهب ضحيَّتَها عددٌ من القتلى، وتعرَّض النحَّاسُ لمحاولة اغتيالٍ."},{"id":5072,"title":"معاهدة 1936 السورية - الفرنسية  .","date":["العام الهجري :1355","الشهر القمري : محرم","العام الميلادي :1936"],"text":"بعد أن رأى الكثيرُ من السوريين أنَّ الكفاحَ المسلَّحَ لا يتكافأُ مع القوات الفرنسية لجؤوا إلى الكفاح الدبلوماسيِّ، فبدأت تظهَرُ الكتلة الوطنية والجمعية التأسيسية التي دعت لوضع دستورٍ للبلاد، وعمَلِ انتخابات نيابية حُرَّة، وإلغاءِ الأحكام العرفية، ثم حصلت تطوراتٌ في إصدار دساتير عديدة، أحدها لدولة سوريا، وآخر لدولة العلويين في اللاذقية، وثالث للدروز، ثمَّ حُلَّت الحكومة المؤقتة، وعملت انتخابات جديدة، وحصل محمد علي العابد على رئاسة الجمهورية، ولكِنْ في أواخر سنة 1935م قام إضرابٌ عام في دمشق استمر خمسين يومًا، وحصلت اضطراباتٌ، واستقالت أكثَرُ من وزارة، وبسبب ذلك تم الاتفاقُ على معاهدة تضع حدًّا للانتداب، فشُكِّلَ وَفدٌ سوريٌّ مكَلَّفٌ بالتفاوضِ مع الحكومة الفرنسية برئاسة هاشم الأتاسي، وعضوية كلٍّ من فارس الخوري، جميل مردم، سعد الله الجابري: ممثِّلين عن الكتلة الوطنية، ومصطفى الشهابي، إدمون حمصي: ممثلين عن الحكومة، ونعيم أنطاكي سكرتيرًا، والقائم مقام أحمد اللحام أحد ضباط الجيش العربي سابقًا خبيرًا ومستشارًا عسكريًّا، التقى الوفدُ بسياسي وزارة خارجية فرنسا، وكانت العقبةُ الأساسية الأولى التي اختلف عليها الطرفان هي قضية توحيد الأراضي؛ فقد أصرَّ الجانِبُ السوري المفاوِضُ على وَحدة الأراضي السورية بالشَّكلِ الذي كانت عليه في عهد العثمانيين، وتوصَّل الطرفان المتفاوضان إلى حَلٍّ وَسطٍ يقضي بقيام دولتين مستقلَّتين في المنطقة سورية ولبنان، وأن يبقى لبنانُ ضِمنَ حدوده الراهنة، مقابِلَ موافقة الوفد الفرنسي على إعادة توحيد إقليمي جبل الدروز وجبل العلويين مع سورية، وأمَّا بالنسبة لسنجق الإسكندرونة فقد أقرَّت فرنسا بتبعيته لسورية، ولكنْ بشرط أن يكون له وضعٌ خاصٌّ يُتَّفَق عليه فيما بعد. وكانت العقبةُ الثانية أمام نجاح المفاوضات هي المتعلقة بالقوات السورية الخاصة بعد توقيع المعاهدة، وأصرَّ الوفدُ السوري على استعادة القوات فورًا؛ نظرًا لأنَّ نفقاتِها كانت من الموازنة السورية طيلةَ السنوات العشر الأخيرة، أمَّا الجانب الفرنسي فكان يرغَبُ بإبقائها تحت قيادة ضباط فرنسيين خلالَ فترة معينة يمكِنُ بعدها تسليمُها إلى الحكومة السورية بعد توقيع اتفاق عسكري معها، فتَمَّ الاتفاق على أنه يجوز للحكومة الفرنسية أن تحتَفِظَ ولمدة خمس سنوات ببعض القوات خارج المدن وبمطارين، وبقوات محدودةٍ ضِمنَ محافظتي جبل الدروز ومنطقة العلويين، على أن تعترف المعاهدةُ باستقلال سوريا. لكِنَّ المعاهدة لم يُنفَّذ منها شيء؛ لأنها لم تُعرَض على البرلمان الفرنسي، واقترح إضافة ملاحق جديدة على المعاهدة، منها إعطاءُ حكم ذاتي للدروز والنصيريين وسكان الجزيرة الفراتية حكمًا ذاتيًّا، وتعدى الاتفاق العسكري الذي يوجِبُ جلاء الجيش الفرنسي عن البلاد بحيث يصبِحُ هذا الوجود دائمًا."},{"id":5073,"title":"الثورة الفلسطينية الكبرى 1936م .","date":["العام الهجري :1355","الشهر القمري : محرم","العام الميلادي :1936"],"text":"تعتَبرُ الثورة الفلسطينية الكبرى في عام 1936م من أشَدِّ الثورات على اليهود وأعوانهم الإنجليز، وكانت ذاتَ طابَعٍ إسلامي واضِحٍ، وتركَّزت العمليات في شمالي فلسطين ولواء نابلس؛ حيث إن جماعة عز الدين القسَّام كان وجودها مكثفًا هناك، فقاموا باغتيال الحاكم البريطاني لمنطقة الجليل \"أندروز\"، وكان فوزي القاوقجي هو قائد عام الثورة، وتولَّى منطقة القدس عبد القادر الحسيني الذي قُتِلَ في معركة القسطل، واشتعلت الثورة في كافة أنحاء فلسطين حتى أعلنت بريطانيا أنَّ خسائِرَها بلغت مليوني جنيه استرليني، كما استدعت قوات إضافية من مصر، وأسهمت الطائرات والدبابات والأسلحة الفتاكة الأخرى في قمع الثورة، وهجر اليهودُ مستعمراتِهم وتجَمَّعوا في تل أبيب، ونُفِّذَت في هذه الثورة آلافُ العمليات العسكرية، ولم تهدأ الثورة حتى توسطت بريطانيا عند أصدقائها من الملوك والرؤساء العرب، وبعدها استعانت بريطانيا بسُدس جَيشِها الإمبراطوري بقيادةِ أقوى العسكريِّين، وعادت تحتلُّ فلسطين جزءًا جزءًا في حربٍ شرسة استخدموا فيها الطيرانَ والدباباتِ وكلَّ التقنيات العسكرية الحديثة التي يعرفونَها!"},{"id":5074,"title":"إصدار الحكومة الفرنسية قرارًا باعتبار اللغة العربية لغة أجنبية في الجزائر .","date":["العام الهجري :1355","الشهر القمري : صفر","العام الميلادي :1936"],"text":"أصدرت الحكومةُ الفرنسيةُ قرارًا باعتبارِ اللغة العربية لغةً أجنبية في الجزائر! ويأتي هذا القانونُ في سلسلة قوانينَ سَنَّها الاحتلال الفرنسي لمحاربةِ اللغة العربية، وفَرْنَسة الشعب الجزائري، وتسَبَّبت هذه القوانين في زحزحة اللغة العربية واحتلال اللغة الفرنسية لمكانةٍ متميزة في الإدارةِ والحُكمِ في الجزائر!"},{"id":5075,"title":"وفاة أحمد فؤاد ملك مصر وتولي الملك فاروق .","date":["العام الهجري :1355","الشهر القمري : صفر","العام الميلادي :1936"],"text":"هو المَلِكُ أحمد فؤاد الأوَّل بن الخديوي إسماعيل بن إبراهيم بن محمد علي ملك مصر. مولده ووفاته بالقاهرة. تعلَّمَ بها، ثم في جنيف، ثم في المدرسة الحربية بتورينو إيطاليا، وتخرَّج ضابطًا في الجيش الإيطالي، وأُلحِقَ بالبلاط الملكي برومة، ورحل إلى الأستانة فعُيِّنَ ياورا فخريًّا للسلطان عبد الحميد، فمُلحَقًا حربيًّا للسفارة العثمانية بعاصمة النمسا، وعاد إلى مصر سنة 1892 فعُيِّن (ياورا) للخديوي عباس الثاني، واستمَرَّ ثلاثة أعوام. وكان يُنتَدَب في بعض المهمات إلى أن دُعِىَ لتولي سلطنة مصر سنة 1335ه / 1917م بعد وفاة أخيه السلطان حسين كامل، والحماية البريطانية مضروبةٌ على مصر. وفي أيامه قامت مصر بحركتها الوطنية سنة 1918م بقيادة سعد زغلول، فرُفِعَت الحماية سنة 1922، وفي عام 1919 حدثت المظاهرةُ النسائية ضِدَّ الاحتلال الإنجليزي والتي خُلِعَ فيها الحجابُ في ميدان الإسماعيلية!! ووُضِعَ دستور للبلاد وقانون لتوارث العرش، وقانون لأمراء الأسرة الحاكمة، وتحوَّل لَقَبُه من سلطان إلى ملك, وفي أيامه أُنشئ مجمع اللغة العربية بمصر. وكان يُحسِنُ التحدث باللغة العربية وبالتركية والفرنسية والإيطالية ويفهم الإنجليزية. توفِّيَ بالقاهرة في السابع من صفر، وكان ولي عهده فاروق الذي كان يتابِعُ دراسته في إنجلترا، فعاد إلى مصر وتشَكَّل مجلس وصاية برئاسة الأمير محمد علي، وعضوية عبد العزيز عزت ومحمد شريف صبري، إلى أن بلغ الملك سن الرشدِ في تموز / 1938م / 1357هـ."},{"id":5076,"title":"قتل بلاس إنفانتي الأندلسي لدفاعه عن المسلمين بأسبانيا .","date":["العام الهجري :1355","الشهر القمري : جمادى الأولى","العام الميلادي :1936"],"text":"هو بلاس إنفانتي بيريث دي بارغاس رجلُ سياسة ومفكِّر وكاتب أندلسي، ويُعَدُّ أبا القومية الأندلسية الحديثة. ولِدَ سنة 1885م في بلدة قشريش بمقاطعة مالقة، ظهرت في أوائل القرن العشرين شخصيةُ بلاس إنفانتي الفَذَّة، الذي اعتنق الإسلام وعَمِلَ حَسَب طاقته في ذلك الحين على توعية المجتمع الأندلسي، وإزاحة الغشاء المظلِم الذي أنزله أعداؤه على تاريخِه وماضيه الإسلامي. تعرَّف بلاس إنفانتي إبَّان مُقامِه في غرناطة على التراثِ الإسلامي الأندلسي، فزار إنفانتي إشبيلية وقرطبة ومجريط، واجتمع بزعماء الحركة الأندلسية، وأصبح يعتقِدُ أنَّ الهُويَّةَ الأندلسية ليست هويةَ عِرقٍ أو دم، لكِنَّها هوية (وجود) و(معرفة). وفي سنة 1910م عُيِّن إنفانتي عَدلًا في بلدة قنطيانة، فسكن إشبيلية القريبةَ منها، وأصبح ينتقلُ بين البلدتين، تأثَّر إنفانتي في إشبيلية بمفكِّريها الأندلسيين، وساهم في أنشطتهم الثقافية، وفي 28-11-1913م قُبِل إنفانتي في مجلس المحامين، وفي سنة 1914م ظهرت الطبعةُ الأولى من كتابه النظرية الأندلسية. وفي سنة 1916م أسَّس إنفانتي أول مركز أندلسي في إشبيلية، تبعه مراكز أخرى في مدن الأندلس وقُراها، وأصدر مجلة الأندلس كلسان حال للمراكز الأندلسية، والحركة القومية الأندلسية، ومع الأيام تحوَّل مركز إشبيلية الأندلسي إلى مركز أنشطة أندلسية تثقيفية وتخطيطية، ومنه خرج المنشور الداعي إلى اجتماع المقاطعات الأندلسية في رندة، الذي استعمل عبارةَ الأمة الأندلسية لأول مرة، وهكذا أصبح إنفانتي بأفكاره وحركته رئيسَ تيار جديد للحركة القومية الأندلسية. وطرح فكرة \"إنشاء فدرالية تجمع بين بلاد المغرب والأندلس تجمعُهما أخوة سياسية بعيدًا عن الفكر الاستعماري\" وفي 13-1-1918م انعقد اجتماعُ مجلس المقاطعات الأندلسية في رندة، فعدد معالم القومية الأندلسية في حركتها المستقبلية، وطلبوا الاعترافَ بالأندلس كبلد وقومية ومنطقة ذات حكم ذاتي ديمقراطي، على أساسِ دستور أنتقيرة. ثم تقَدَّم بلاس إنفانتي، وخوزي أندرس باسكس، باسم المؤتمر لهيئة الأمم طالبينَ منها الاعتراف بالقومية الأندلسية، وفي 21/5/1919م تقدَّم إنفانتي لانتخابات إشبيلية باسم (الديمقراطية الأندلسية) المكونة من الجمهوريين الاتحاديين، والقوميين الأندلسيين، والاشتراكيين المستقلين، وندَّد في خُطَبِه الانتخابية بوضع الأندلس البئيس، فغَضِبَت عليه السلطة الحاكمة واليمين واتهموه وأتباعه بالتآمُرِ على أمن الدولة ووحدتها، وفي 13/1/1923م تحولت أسبانيا إلى الحكم الدكتاتوري الذي قضى على الحريات، وأغلقَ المراكز الأندلسية، واتهم القوميين الأندلسيين بمقاومة الدولة، وأسكت القوى المعادِية للكنيسة. فانتقل إنفانتي تحت ضغط عائلته إلى أيسلا كريستينا (مقاطعة ولبة) كموثِّق عدل، وانسحب من العمل السياسي. تعرَّف إنفانتي على بعض أبناء الأندلس المسلمين، فقَرَّر إشهارَ إسلامه على أيديهم، ثم حاول بعد إسلامِه ربطَ الحركة الأندلسية بالحركات الإسلامية والعربية. وفي سنة 1930م انهارت الدكتاتورية، وأصبح إنفانتي يمجِّدُ التاريخ الإسلامي كأساسِ الهوية الأندلسية، ويطالِبُ الأندلسيين باستعادة الهوية والتاريخ والأرض، وبإزاحة هيمنة الكنيسة على الدولة، ويهاجِمُها على جرائمها في القضاء على الأندلسيين، فكان كل ذلك دافعًا لأعدائهم إلى رميهم بالاتهامات المتواصلة، فحُوربت الحركة من طرف اليمين واليسار على حدٍّ سواء. وفي يوم الأحد 2/8/1936م بعد 14 يومًا من انفجار الحرب الأهلية الأسبانية، هجمت فرقةٌ من الكتائب على إنفانتي في بيته دار الفرح بقورية، وساقته إلى إشبيلية، حيث سجنته وأعدمته رميًا بالرصاص يوم الاثنين 10/8/1936م، فمات وهو يصرخُ مرتين: عاشت الأندلس حرة!"},{"id":5077,"title":"المعاهدة 1936 اللبنانية الفرنسية .","date":["العام الهجري :1355","الشهر القمري : جمادى الآخرة","العام الميلادي :1936"],"text":"خطَّطت فرنسا -بعد أن انتهت الثورةُ العربية الكبرى ضِدَّ العثمانيين- لما ستفعله في سوريا، فأول ما قامت به هو فَصلُ لبنان عن سوريا، وخاصة أن فيه كثيرًا من الموارنة النصارى، وقد سنَّت دستورًا خاصًّا للبنان الكبير، ومع أنَّ الدستور لم ينُصَّ على ديانة الرئيس إلَّا أن فرنسا كانت مصممة على ألَّا يليَ الرئاسة إلا نصراني، فعُيِّنَ أولًا شارل دباس، وحاول حبيب باشا السعد أن يجعل اللهجةَ العامية هي اللغة الرسمية للبلاد؛ ليقضيَ على اللغة العربية الأصيلة، وبدأ التمييز الديني بين النصارى والمسلمين؛ من هضم للحقوق، وتدني في المستوى الاجتماعي والمعيشي، وعمَّقَت فرنسا هذا الموضوع الطائفي، وفي أول سنة 1936م تسلَّم الرئيس إميل إدة مهامَّ رئاسة لبنان الكبير، وتزايدت في عهده حِدَّةُ الصراعات الطائفية، ثم بدأت المفاوضات اللبنانية الفرنسية التي حذت حذو المفاوضات السورية الفرنسية، وكانت الكتلة الدستورية برئاسة بشارة الخوري قد تقَدَّمت بالمطالبة بأن تحلَّ محلَّ الانتداب، ثم تداعت القوى الإسلامية والقومية الوحدوية من مختَلِف الطوائف إلى عقدِ مؤتمر الساحل والأقضية الأربعة في مارس 1936م، وكانوا يطالبون بالوحدة مع سوريا، ثم عُقِدَ مؤتمر آخر هو المؤتمر القومي الإسلامي في أكتوبر 1936م، وطالبوا بالاتحاد مع سوريا وأن تكون هناك بنودٌ واضحة لحقوق وواجبات الطوائف، ثم بعد المفاوضات والأخذ والرد وُقِّعَت المعاهدة في 13 نوفمبر 1936م من قِبَل رئيس الجمهورية إميل إدة، والمفوض الداني دي مارتل الفرنسي، وكانت مدتها خمسة وعشرين عامًا اعترفت فيها فرنسا باستقلال لبنان، وتعهَّدت بمساعدته للانضمام للأمم المتحدة على أن يبقى جنود فرنسيون في لبنان، وتمثِّلُ فرنسا لبنان في الشؤون الخارجية والعسكرية."},{"id":5078,"title":"قرارات لجنة بيل الملكية البريطانية ومشروع تقسيم فلسطين\n  .","date":["العام الهجري :1356","العام الميلادي :1937"],"text":"بعد أن قامت الثورةُ الفلسطينية الكبرى عام 1936م وعَمَّت كلَّ أرجاء فلسطين وتكَبَّد البريطانيون من ورائِها خسائرَ فادحةً: أرادوا أن يستغلُّوا هذه النقطةَ لصالِحِهم، فقاموا بتشكيلِ لجنةٍ برئاسة بيل، وهي ما تسمى باللجنة الملكية البريطانية؛ لدراسة أسباب الثورة، وكأن أسبابَها غامضةٌ تحتاج إلى دراسة، وكان الغرضُ الرئيس من هذه اللجنة وغيرها من اللجان امتصاصَ الثورة بظهور بريطانيا أمام العالم أنها مهتمَّةٌ بقضايا الشعب الفلسطيني التي هي مُنتدَبةٌ عليه، بالإضافة إلى المكسب الإعلامي، فقامت هذه اللجنةُ في تقريرها المقَدَّم إلى الحكومة البريطانية في السابع من يوليو 1937م بتقسيمِ فلسطين بين العرب وبين اليهود، وتضَمَّن التقريرُ مطالِبَ الشعب الفلسطيني حيالَ نوايا اليهودِ مِن إنشاءِ الوطن القومي اليهودي في فلسطينَ بمساعدةِ الحكومة البريطانية، وأوصت اللجنة أيضًا بضرورة إبدال نظام الانتداب بنظام المعاهداتِ التي اتبعَتْه بريطانيا في العراق، والتي اتَّبَعَتْه فرنسا في سوريا، وأيَّدت الحكومة البريطانية بشدةٍ التوصيةَ التي جاءت بها لجنة بيل حول تقسيم فلسطين، ورأت أنه الحَلُّ الأمثل للقضية الفلسطينية!!"},{"id":5079,"title":"ميثاق سعد آباد الذي ضم تركيا والعراق وإيران .","date":["العام الهجري :1356","الشهر القمري : ربيع الآخر","العام الميلادي :1937"],"text":"في عام 1937م بدأت الظروفُ العالمية تُنذِرُ بنشوب الحرب العالمية الثانية فاتَّخَذت الدولُ الغربية بعضَ الاحتياطات ضِدَّ ألمانيا وإيطاليا واليابان والاتحاد السوفييتي، وكان من جملةِ التدابير المتَّخَذة عقد (ميثاق سعد آباد) في الثامن من يوليو عام 1937م في إيران، وساهم عقدُ هذا الميثاق في التقارب العراقي الإيراني، حيث عُقِدَت المعاهدة عام 1937بين العراق، تركيا، أفغانستان، وإيران تحت إشراف بريطانيا، ثم توالى عقدُ معاهدات أخرى، فعُقِدت معاهدة صداقة ومعاهدة حلِّ الاختلافات بالطرق السلمية. وأبرز ما جاء في المعاهدة: تعديلُ الحدود في شَطِّ العرب بمنحِ إيران سبعة كيلومترات وثلاثة أرباع الكيلو متر أمام عبادان. وحقَّقت المعاهدةُ لإيران حقَّ استخدام شطِّ العرب والانتفاع منه دون إذنٍ عراقيٍّ، كما كان قبل توقيعِ المعاهدة. ومنح الدولتين حق تقرير الضرائب المالية والفنية المتعلقة بشطِّ العرب، وتقضي المادة الثالثة من المعاهدة بتأليف لجنةٍ مشتركة من البلدين لنَصبِ دعائم الحدود التي كانت قد عيَّنَتْها اللجنة المشتركة عام 1914م. باشرت اللجنةُ الجديدة أعمالَها عام 1938م لكِنَّها توقَّفَت عام 1940م، ويبدو أنَّ اندلاع الحرب العالمية الثانية كان أحد أسباب توقُّف عمل اللجنة، وظلَّت مشكلة الحدود قائمة. وكان من آثار المعاهدة وأدُ كلِّ حركة تحرُّر كردية في مهدِها، فتقول إحدى موادِّه: إنَّ كلًّا من الأطراف الموقِّعة تتعهَّدُ باتخاذ التدابير اللازمة للحيلولة دون قيامِ أيِّ نشاط لعصابات مسلحة، أو جمعيات، أو منظمات تهدف إلى إطاحة المؤسسات الحالية، التي تتحمَّلُ مسؤولية المحافظة على النظام والأمن في أي جزء من حدود الأطراف الأخرى، علمًا أنَّه انتهى أثَرُ ذلك الميثاق بنشوب الحرب العالمية الثانية."},{"id":5080,"title":"معاهدة الصداقة بين العراق وإيران .","date":["العام الهجري :1356","الشهر القمري : جمادى الأولى","العام الميلادي :1937"],"text":"بعد أن وُقِّع ميثاقُ سعد آباد بين كل من تركيا وأفغانستان والعراق وإيران في ربيع الثاني 1356هـ في هذا العام على ألَّا تتدخل أي دولة بشؤون الدول الأخرى الداخلية، وألَّا تتعدى عليها، ولا تعاوِن من يتعدى عليها، وما إلى ذلك، ثم وقِّعَت في 10 جمادى الأولى في العام نفسِه معاهدةُ صداقة دائمة لإقامة سِلمٍ دائم وصداقة لا تتغيَّرُ بين العراق وإيران، ووقِّعَت في طهران، ويتعهَّدُ الطرفان بأن يُعقَدَ بأسرعِ وقتٍ ممكن: اتفاقية حُسن جوار، ومعاهدة لاسترداد المجرمين، ومعاهدة إقامة وتجنيس، ومعاهدة تجارية، واتفاق تعاون قضائي، واتفاقية بريد وبرق، واتفاقية قنصلية."},{"id":5081,"title":"استيلاء الصينيين على تركستان الشرقية بمساعدة الروس. .","date":["العام الهجري :1356","الشهر القمري : جمادى الآخرة","العام الميلادي :1937"],"text":"تعرَّضت تركستان الشرقية لأربعِ غَزَوات صينية منذ عام 1277هـ / 1860م مرَّتين في عهد أسرة المانشو، ومرةً في عهد الصين الوطنية، ومرةً في عهد الصين الشيوعية. وقد أدت هذه الغزوات وما رافقها من مذابحَ صينيةٍ إلى إبادة كثير من المسلمين، وحدوثِ عِدَّةِ هِجرات من هذا الإقليم إلى المناطق المجاورة. وقد قامت ثورةٌ عارمة في تركستان الشرقية ضِدَّ الصين سنة 1350هـ / 1931م كان سببُها تقسيمَ الحاكم الصيني المنطقةَ التي يحكمها \"شاكر بك\" إلى وحدات إدارية، وفي عام 1352هـ أعلن المسلمون قيامَ حكومة جديدة باسم \"الجمهورية الإسلامية في تركستان الشرقية\"، ولم تلبث هذه الحكومة طويلًا؛ لأن التحالُفَ الصيني الروسي تمكَّن في عام 1356هـ من إسقاطِ هذه الجمهورية المسلمة، وقام بإعدامِ جميع أعضاء الحكومة مع عشرة آلاف مسلم. وحصل الروسُ مقابِلَ مساعدتهم للصين على حقِّ التنقيب عن الثروات المعدنية، واستخدام عددٍ مِن الروس في الخِدماتِ الإدارية في تركستان الشرقية."},{"id":5082,"title":"قيام الملك فاروق ملك مصر بحل مجلس النواب .","date":["العام الهجري :1356","الشهر القمري : ذي الحجة","العام الميلادي :1938"],"text":"بعد تولِّي الملِكِ فاروق عرشَ مصرَ قام بحل مجلسِ النواب الذي كان يتمتَّعُ فيه حِزبُ الوفد بأغلبية كبيرة، وكان الوفديُّون قد أحرزوا هذه الأغلبيةَ في الانتخابات التي أُجرِيَت في مايو 1936م، وكانت الحياةُ السياسية في مصر في تلك الفترة تعتَمِدُ على ثلاث قوى رئيسية فاعلة، هم: الإنجليز، والقصر، وحزب الوفد. قبل أن يدخُلَ الجيش إلى المعادَلةِ ويقلِبَ توازنات القوى فيها، جلس فاروق على العرش مع اهتزازِ وتراجُعِ شعبية حزب الوفد بعد توقيعِه على اتفاقية 1936 والتي كانت مكروهةً ومرفوضةً شعبيًّا. وعلى الرغم من حداثة سنِّ فاروق في تلك الفترة إلا أنَّه أدرك ضرورة اكتساب تلك الشعبية المفقودة من الوفد، قأقال حكومة النحاس الوفدية في 30 ديسمبر 1937، أي: في نفس العام الذي تسلَّم فيه سلطاتِه الدستوريةَ كمَلِكٍ على البلاد، وكلَّف محمد محمود الذي كان رئيسًا لحزب الأحرار الدستوريين المُوالي للقصر بتشكيل الوزارة. وكان أوَّلُ ما استصدرته الوَزارة الجديدة مرسومًا بتأجيل انعقاد البرلمان شهرًا، ثمَّ حَلِّ مجلِسِ النوابِ ذي الأغلبية الوفدية، إلى أن تمَّت الانتخابات في 1938 ولم يحصُلِ الوفدُ إلا على 12 مقعدًا فقط، والملاحَظُ في تلك الفترة هو التعددية الحزبية السياسية القائمة، حتى ولو بشكلٍ صوريٍّ؛ حيث سُمِح في انتخابات 1938 مثلًا بأن يتِمَّ ترشيح المستقلين، والذين حصلوا على 55 مقعدًا بجانب أحزاب الأحرار الدستوريين، والهيئة السعدية برئاسة أحمد ماهر المنشَقِّ عن حزب الوفد، بالإضافة إلى الحزب الوطني، وحزب الوفد."},{"id":5083,"title":"وفاة الشاعر محمد إقبال .","date":["العام الهجري :1357","الشهر القمري : صفر","العام الميلادي :1938"],"text":"هو محمد إقبال ابنُ الشيخ نور محمد؛ الشاعر المعروف، ولِدَ في سيالكوت إحدى مدن البنجاب الغربية في الثالث من ذي القعدة 1294هـ الموافق 9 من نوفمبر 1877م. ينتمي محمد إقبال إلى أسرة هندوكية من البراهمة، وهي جماعةٌ لها شأنٌ كبير في الهند رغم أنَّها تعبُدُ الأصنامَ وتقَدِّسُ التماثيل، لكِنَّ أسرة محمد إقبال تنازلت عن كلِّ هذه العظمة؛ لتدخُلَ في دين الإسلام في عهدِ السلطان زين العابدين بادشاه 1421 - 1473م، فاعتنق الجدُّ الأكبر لمحمد إقبال واسمه (بنديت) بعد أن هداه الله على يدِ أحدِ رجالِ الإسلامِ في كشمير، ففَضَّل بنديت الإسلامَ مع الفقرِ على عبادة الأصنام مع الغِنى والعظمة، ثمَّ أنجبت أسرتُه -التي كانت بالأمس القريب تعبدُ الأصنامَ وتحتَقِرُ الآخرينَ- محمد إقبال: فيلسوفَ الإسلامِ الكبيرَ وشاعِرَه. بدأ محمد إقبال تعليمَه في سن مبكرةٍ على يد أبيه، ثم التحق بأحَدِ مكاتب التعليم في سيالكوت، وفي السنة الرابعة من تعليمِه رأى أبوه أن يتفرَّغَ للِعلمِ الديني، ولكِنَّ أحد أصدقاء والده وهو الأستاذ مير حسن لم يوافِقْ، وقال: هذا الصبيُّ ليس لتعليم المساجِدِ، وسيبقى في المدرسة، وانتقل إقبال إلى الثانوية؛ حيث كان أستاذُه مير حسن يدَرِّسُ الآداب العربية والفارسية، وكان قد كرَّس حياتَه للدراسات الإسلامية. وبدأ إقبال في كتابةِ الشعر في هذه المرحلة المبكرة، وشجَّعه على ذلك أستاذه مير حسن، فكان يَنظِمُ الشعر في بداية حياته بالبنجابية، ولكِنَّ السيد مير حَسن وجَّهَه إلى النَّظْمِ بلغة الأردو، وكان إقبال يرسِلُ قصائده إلى ميرزا داغ دهلوي الشاعر البارز في الشعر الأردو حتى يبديَ رأيه فيها، وينصَحَه بشأنها وينقِّحها، ولم يمضِ إلا فترة بسيطة حتى قرَّر داغ دهلوي أنَّ أشعار إقبال في غنى تام عن التنقيح، وأتم إقبال دراستَه الأولية في سيالكوت، ثم بدأ دراسته الجامعية باجتياز الامتحان العام الأول بجامعة البنجاب 1891م، التي تخرَّج فيها وحصل منها على إجازة الآداب 1897م، ثمَّ حصل على درجة الماجستير 1899م، وتلقَّى إقبال دراساتِه الفلسفيةَ في هذه الكلية على يدِ الأستاذ توماس آرنولد، وكان أستاذًا في الفلسفة الحديثة، أجاد محمد إقبال الكثيرَ مِن اللغات؛ كالأوردية، والفارسية، والإنجليزية، والألمانية، وكان يَعرِفُ العربية. بعد أن أنهى (محمد إقبال) دراستَه الجامعية بلاهور عُيِّن أستاذًا للتاريخ والفلسفة والسياسة المدنية بالكلية الشرقية بلاهور، ثم أستاذًا للفلسفة واللغة الإنجليزية في الكلية الحكومية التي تخرَّج فيها، لكِنَّه كان طموحًا يريد مزيدًا من العلم، ويتمنى أن يرى البلاد الأوربية وحضارتها، فسافر إلى أوروبا سنة 1323هـ/1905م؛ حيث نال درجةً في الفلسفة من جامعة (كمبردج) ودرجةً في القانون من كلية لندن للعلوم السياسية، وعَمِلَ أستاذًا للغة العربية في جامعة لندن، كما حصل على درجة الدكتوراه في الفلسفة من جامعة (ميونيخ) بألمانيا، وعاد مرةً أخرى إلى لندن، فنال شهادةَ المحاماة من جامعة لندن. وهناك في بلاد الغرب كان محمد إقبال يدعو إلى دين الإسلام، ويدافِعُ عنه دفاعًا صادقًا من خلال المقالات التي كان ينشرُها والقصائد الشعرية التي كان يُبدِعُها، وكان دائمًا يفخَرُ بالإسلام الذي حرَّر الرؤوس، وطهَّر النفوس، وأصلح الأرضَ، وحصَّن العِرْض، ولم يعجِبْه الفِسقُ والكفر الذي يعيش فيه الأوربيون، وقال لهم محذِّرًا: (يا أهل الغربِ، إنَّ أرض الله ليست دارَ تجارة، ولسوف تنتحِرُ حضارتكم بخِنْجَرها؛ لأنَّها كالعش الذي بُني على غُصنٍ ضَعيفٍ لا قوة له). رجع إقبال إلى لاهور عام 1908م بعد رحلة استغرقت ثلاث سنوات، وبدأ العمَلَ بالمحاماة، يدافِعُ عن المظلومين، وعُرِفَ عنه في أثناء عمله بها أنَّه لا يقبل إلا قضايا الحق، كما عُرِفَ عنه أيضًا اقتدارُه في مهنته، وكان مؤهَّلا لبلوغ أعلى الدرجات فيها، لكنَّه ترك المحاماة وعمل أستاذًا للفلسفة واللغة الإنجليزية في الكلية الإسلامية بلاهور، ثم استقال من منصب الأستاذية، واشتغل بالسياسة، فانتُخِبَ عام 1926م في الجمعية التشريعية في بنجاب، وعَمِلَ في حزب الرابطة الإسلامية، ورأَسَ المؤتمر السنوي لها في \"إله آباد\" سنة 1930م، واشترك إقبال في مؤتمر المائدة المستديرة عام 1931م، 1932م في لندن؛ للنظر في وضع دستور للهند. وقد كان إقبال يحلُمُ بإنشاء دولة إسلامية لمسلِمي الهند، وسَخِرَ منه الناس حينئذ، ولكِنْ تحققت فكرتُه بقيام دولة باكستان الإسلامية، زار إقبال كثيرًا من الدول الإسلامية، فزار مصر، وأفغانستان، كما زار قرطبة، وصلَّى في مسجد قرطبة الشهير، وظَلَّ طيلة حياته المجيدة يدافِعُ عن الإسلام والمسلمين في المحافِلِ الدولية والمؤتمرات الإسلامية، والكتب والأشعار التي أبدعها، ويحاوِلُ قَدرَ طاقته إيقاظ المسلمين من غفلتهم، ومساعدة الأمة الإسلامية على النهوض، وكان إقبال دائمًا يعطِفُ على الفقراء والمساكين؛ يجلس معهم، ويهتمُّ بأمرهم، ويخالطهم في الطعام والشراب. كما كان يدعو المسلمين إلى المشاركة في حركة الحضارة والتقَدُّم، وكان له موقِفٌ أصيل من التصوف يقوم على رفض التصوُّفِ الذي يخالِفُ الكتاب والسنَّة، ويتأثر بفلسفات وَثَنية، كما رفض التصوفَ الذي يجعلُ من المسلم سلبيًّا لا يشارِكُ في خدمة مجتمعه، ومقاومة الظلم والدفاع عن المسلمين، وكان يسمِّي هذا اللون من التصوف بالتصوف الأعجمي، وكان إقبال في كل أسفاره يعمَلُ على نشر الإسلام، وأثَّر بشِعرِه وأسلوبه في كثير من الأوروبيين، ثم اجتمع المرضُ على إقبال في السنوات الأخيرة من عمره، فضَعُف بصره لدرجة أنه لم يستطع التعَرُّفَ على أصدقائه بسهولةٍ، وكان يعاني من آلام وأزمات شديدة في الحلق؛ مما أدى إلى التهاب حلقه، وأدى بالتالي إلى خفوت صوته، ممَّا اضطره إلى اعتزال مهنة المحاماة، وفكَّر في أن يقصِدَ فيينا طلبًا للعلاج إلا أن حالاته المادية لم تسمَحْ بذلك، وفي 21 من إبريل من هذا العام في تمام الساعة الخامسة صباحًا كانت وفاته رحمه الله. يقول الشيخ أبو الحسن الندوي عنه: ومن دواعي العجَبِ أنَّ كُلَّ هذا النجاح حصل لهذا النابغة، وهو لم يتجاوز اثنين وثلاثين عامًا من عُمُرِه!!"},{"id":5084,"title":"وفاة مصطفى كمال أتاتورك رئيس الجمهورية التركية .","date":["العام الهجري :1357","الشهر القمري : رمضان","العام الميلادي :1938"],"text":"هو مصطفى كمال أتاتورك الملقَّب بالغازي؛ رئيس الجهورية التركية، وكلمة أتاتورك، تعني: أبو الأتراك، وهو الذى أسقط الخلافةَ الإسلاميةَ سنة 1343ه / 1924م. ولِدَ مصطفى كمال عام 1296هـ في مدينة سالونيك اليونانية وكانت تابعة للدولة العثمانية، من أمٍّ تدعى زبيدة، ونُسِبَ في بداية الأمر إلى زوج أمه علي رضا الذي لم يلبث أن توفِّي، ولم يتجاوز ربيبُه مصطفى الثامنةَ من العمر، وكانت زبيدة مُستهترة، وتمكَّنَت من تأمين زوجٍ لها، فغَضِبَ ولدها مصطفى منها، وترك البيتَ وذهب إلى بيت أخت علي رضا زوج أمه السابق، ودرس في المدارس الحربية في سالونيك، ومناستر، ثم التحق بالكلية الحربية في استانبول وتخرَّج منها، ثم تخرَّج من كلية الأركان برتبة رائد عام 1333هـ، وألَّف جمعية الوطن والحرية في الشام مع بعض المنفيِّين إليها، وكان يتدرَّبُ في لواء الفرسان، وعندما تمَّ تدريبُه عُيِّنَ في يافا غيرَ أنَّه هرب إلى مصر، ومنها انتقل بحرًا إلى سالونيك، واستطاع أن يجد وسيلةً لتعيينه هناك عن طريق الارتباطات التي أصبحت له، وعَمِلَ لجمعيته التي لم تلبَثْ أن انضمَّت إلى جمعية الاتحاد والترقي، ولم يستطِع البروزَ والظهور فيها؛ لأن أعضاءها لم يحترموه؛ لاستهتاره بالقِيَمِ، وانقطاعه إلى الأماكن الموبوءة من حانات، ومحلات للفجور؛ لذا فقد حقد عليهم أيضًا، ويبدو أنه كان على صلةٍ بجهة لها إمكاناتُها ولها نفوذها توجِّهُه وتحميه وترسُم له وتمَنِّيه وتعِدُه بأعلى منصب، أرسله أنور باشا وزير الحربية إلى طرابلس للقضاءِ على ثورة هناك، لكنه هرب من ليبيا، ثم أُرسِلَ ملحَقًا إلى بلغاريا قضى أيامَه في الخمور والمجون، ولَمَّا اندلعت الحرب العالمية الأولى كان يشتركُ حسب الحاجة تحت إمرة أحد القادة الألمان. وبعد الحرب وتوقيع هدنة مودروس بدأ الإنجليزُ في تهيئة مصطفى كمال لإسقاط الخلافة العثمانية، وإقامة دولة تركيا العلمانية الحديثة، وقد نجحَت في صناعته حتى كان كمال أشَدَّ عداء للإسلام والمسلمين من اليهودِ والنصارى! وفَعَل في تركيا مالم تفعَلْه جيوشُهم مجتمعةً، فما إن تولَّى رئاسة الجمهورية التركية حتى شَنَّ حربًا لا هوادةَ فيها على الإسلام والمسلمين، وفرض إجراءاتِ عَلْمَنة تركيا وفَصْلِها عن الإسلام والمسلمين بقوَّة النظام والسلاح؛ فقد كان هذا الديكتاتور مثلًا فريدًا في القسوة والتنكيل والأنانية المدمِّرة. لقد تجلَّت سياسة أتاتورك العلمانية في برنامج حزبه (حزب الشعب الجمهوري) لعام 1349هـ مرة، وعام 1355هـ مرة ثانية، والتي نصَّ عليها الدستور التركي، وهي المبادئُ الستة التي رُسِمَت بشكل ستة أسهُمٍ على علَمِ الحِزبِ، وهي: القومية، الجمهورية، الشعبية، العَلْمانية، الثورة، سلطة الدولة. هلك مصطفى كمال في 18 رمضان 10 نوفمبر 1938م بعد أن أُصيبَ قبل وفاته بسنين بمرضٍ عضال في الكلية لم يُعرَفْ كُنهُه. وكان يتعرَّضُ لآلام مبَرِّحة مزمنة لا تطاق، كانت السببَ في إدمانه على شربِ الخمر؛ مما أدى إلى إصابته بتليف الكبد، والتهاب في أعصابه الطرفية، وتعرُّضه لحالات من الكآبة والانطواء. ولما توفي دُفِنَ بعد تسعة أيام من وفاته بعد أن أمضى أكثَرَ من خمس عشرة سنة في الحكم. ثم جرت الانتخاباتُ وانتُخِبَ عصمت إينونو رئيسًا للجمهورية؛ فهو ثاني رئيس للجمهورية التركية الحديثة."},{"id":5085,"title":"فرنسا تعطي لواء إسكندرون السوري لتركيا .","date":["العام الهجري :1357","الشهر القمري : شوال","العام الميلادي :1938"],"text":"كان لواء إسكندرون ضِمنَ المناطق الزرقاء التي تشمل سواحل بلاد الشام الشمالية، والتي أعطتها معاهدةُ سايكس بيكو إلى فرنسا، وكانت كذلك كيليكيا بيد فرنسا، فرغبت أن يكون لها قناة تواصُل مع الأتراك، كما للإنجليز فأعطت فرنسا -بعد مفاوضات- كيليكيا لتركيا، ورسمت الحدودَ بين سوريا وتركيا؛ حيث كان لواء إسكندرون في الأرض الشامية، ورَغِبَ مصطفى كمال في إظهار الإخلاص لأمَّتِه، فرفع طلبًا للأمم المتحدة لحَلِّ النزاع القائم بين سوريا ممثلةً بفرنسا، وبين تركيا؛ وذلك أن فرنسا تحتَلُّ لواء إسكندرون وأكثر سكانه من الأتراك، فاستجابت عصبةُ الأمم فأرسلت لجنة إلى إسكندرون، وأجرت الاستفتاءَ واتصلت بالسكَّان، وتعرفت على رغباتِهم، ومع أنَّ الاستفتاء أظهر أن نسبة الأتراك لا تزيد عن 35 % من السكَّان في اللواء إلا أنَّها أوصت بضَمِّه إلى تركيا، فتنازلت فرنسا عنه لصالح تركيا، وهو نوع من المداهنة الدولية لكسب تركيا في طرف الحُلَفاء وسَحْبِها إليهم بدَلَ أن تبقى في طرف الخصم ألمانيا، وأعطيَ اللواء استقلالًا ذاتيًّا من فرنسا وجُعِلَ تحت النفوذ التركي في 7 شوال 29 نوفمبر وأسمى الأتراكُ اللواءَ باسمِ هاتاي."},{"id":5086,"title":"إعلان إيطاليا ضم طرابلس وبرقة إلى ليبيا ومنحها الجنسية الإيطالية للسكان .","date":["العام الهجري :1357","الشهر القمري : ذي القعدة","العام الميلادي :1939"],"text":"قبل اندلاع الحرب العالمية الثانية بتسعة أشهر أعلنت إيطاليا ضمَّ طرابلس وبرقة إلى ليبيا سابقًا (ليبيا بالأصل تُطلَق على الصحراء التي تقع غربَ نهر النيل وجنوب برقة وطرابلس) ومنحت للسكَّان الجنسية الإيطالية، وألزمَتْهم تعلُّمَ اللغة الإيطالية، ومن عارضها هتكت عِرْضَه، وألقت كثيرًا من الناسِ مِن الطائرة وهم أحياء، إلى غير ذلك من الأعمال الوحشية."},{"id":5087,"title":"مقتل الملك غازي بن فيصل الأول ملك العراق وتولي ابنه فيصل الثاني  .","date":["العام الهجري :1358","الشهر القمري : صفر","العام الميلادي :1939"],"text":"هو الملِكُ غازي بن فيصل بن الشريف حسين الهاشمي ثاني ملوكِ العراق. ولِدَ سنة 1333هـ / 1912م في مكة التي كانت واقعةً ضِمنَ ممالك وولايات الدولة العثمانية، وهو الابنُ الوحيد للملك فيصل الأول الذي كان له 3 بنات. عاش في كنَفِ جَدِّه حسين بن علي شريف مكة قائد الثورة العربية المنادي لاستقلال العرب من الأتراك العثمانيين، مناديًا بعودة الخلافة للعرب. أرسله والِدُه الملك فيصل الأول إلى كلية هارو في إنجلترا سنة 1927ه، فدرس فيها سنتين، وعاد إلى بغداد فتخرَّج بالمدرسة العسكرية، وكان مُولعًا بالرياضة والصيد. سمِّيَ وليًّا للعهد عام 1924م، وناب عن والِدِه في تصريف شؤون الملك سنة 1933م، فحَدَثت فتنة \"الآشوريين\" وأبوه في انجلترا، فكان موقِفُه فيها حازمًا. تولى الحكم وهو شاب يبلغُ حوالي 23 عامًا، ثم ملكًا لعرش العراق عام 1933م بعد وفاة والده؛ لذا كان بحاجة للخبرة السياسية التي استعاض عنها بمجموعة من المستشارين من الضباط والساسة الوطنيين. كان الملك غازي ذا ميول قومية عربية. ناهضَ النفوذَ البريطاني في العراق واعتبرَه عقبةً لبناء الدولة العراقية الفتيَّة وتنميتها، كما اعتبره المسؤول عن نهب ثرواته النفطية والآثار المكتَشَفة حديثًا؛ لذلك ظهرت في عهدِه بوادر التقارب مع حكومة هتلر قبل الحرب العالمية الثانية. وشهد عهده صراعًا بين المدنيين والعسكريين من الذين ينتمون إلى تيارينِ مُتنازِعَينِ داخِلَ الوزارة العراقية: تيار مؤيد للنفوذ البريطاني، وتيار وطني ينادي بالتحَرُّر من ذلك النفوذ؛ حيث كان كلُّ طرف يسعى إلى الهيمنة على مقاليد السياسة في العراق. فوقف الملك غازي إلى جانب التيار المناهِضِ للهيمنة البريطانية؛ حيث ساند انقلابَ بكر صدقي وهو أوَّلُ انقلاب عسكري في العالم العربي. كما قرَّب الساسةَ والضباط الوطنيين إلى البلاط الملكي، فعَيَّن الشخصية الوطنية المعروفة معالي رشيد عالي الكيلاني باشا رئيسًا للديوان الملكي, ونادى بتحرُّر الأقاليم والولايات العربية المحتلة التي كانت متوحِّدةً تحت الحكم العثماني، ودعا إلى إعادة توحيدِها تحت ظلِّ دولة عربية واحدة، ومن هنا ظهرت دعوته لتحرير الكويت من الوصاية البريطانية، وتوحيدها مع العراق والإمارات الشرقية لِنَجدٍ؛ حيث قام بتأسيسِ إذاعة خاصة به في قصره الملكي؛ قصر الزهور، وأعَدَّ البرامج الخاصة بتحرير ووحدة الأقاليم العربية، ومنها توحيد الكويت بالعراق، والوقوف إلى جانب فلسطين التي كانت تحت الاحتلالِ البريطاني، والتي كانت في حالة حرب داخلية؛ بسبب تعرُّضِها لهجرات واسعة من المستوطنين اليهود مِن كافة أرجاء العالم، ووقوف القوى الفلسطينية بوجهِ هذه الهجرات. فوقف إلى جانب قادة الثورة الفلسطينية، كعز الدين القسَّام، وغسان كنفاني، ومفتي القدس الشيخ عبد القادر الحسيني، وفي الثاني من شهر صفر 4 نيسان قُتِلَ الملك غازي بن فيصل في حادث سيارة كان يقودُها بنفسه حيث اصطدم بعمود الهاتف الممغنط الذي جذبَها نحوه، ويبدو أن الأمرَ ليس طبيعيًّا، ولعلَّ الأمر مدَبَّر، كذلك وجود جروح خلفَ رأس الملك غازي بمكانِ وجود المُرافق أمرٌ مشكوك فيه؛ لأنَّه لم يكن مَرضيًّا عنه من قِبَل إنجلترا، ثم اجتمع مجلس الوزراء بعد مقتله وأعلن تنصيبَ ولي العهد الأمير فيصل بن الملك غازي ملكًا على العراق باسم فيصل الثاني، ووُضِعَ عبد الإله بن علي بن الحسين، وهو خال الملك غازي وصيًّا على الملك الذي لم يبلغ سن الرشد القانوني، وكانت الملِكة عالية زوجة الملك غازي قد أدلت بشهادتها أمام المجلِسِ بأن زوجها الملك غازي أوصاها في حالة وفاته بتسميةِ الأمير عبد الإله -شقيقها- وصيًّا على ابنها فيصل، ثم تُوِّجَ رسميًّا في شعبان من عام 1372هـ / 2 أيار 1953م حيث بلغ سن الرشد ورفعت وصاية خاله عليه."},{"id":5088,"title":"بداية تصدير النفط السعودي .","date":["العام الهجري :1358","الشهر القمري : ربيع الأول","العام الميلادي :1939"],"text":"في الثامن من ربيع الأول 18 إبريل وصل الملك عبد العزيز إلى الظهران، وأمضى يومين في استعراضِ مُنشآت النفط، بين الظهران وميناء رأس تنورة؛ ملازمًا في سيره خط الأنابيب، مُتَّبعًا مسيل الزيت من مكانِ خروجه إلى مكان انصبابه في الباخرة، وفي 11ربيع الأول صَعِدَ الباخرة في رأس تنورة، وافتتح مجرى انتقال الزيت إليها، فاندفع ما زِنَتُه عشرة آلاف طن، هي الحمولة التجارية الأولى، في أول باخرة شَحَنت شحنةً كاملة كأول تصدير نفطي غزير من بلاد المملكة العربية السعودية."},{"id":5089,"title":"الحرب العالمية الثانية .","date":["العام الهجري :1358","الشهر القمري : رجب","العام الميلادي :1939"],"text":"حربٌ كونيَّةٌ مُدَمِّرة شاركت فيها معظَمُ دول العالم، استمَرَّت ست سنوات من 1 سبتمبر 1939م إلى 2 سبتمبر 1945م انطلقت شرارةُ هذه الحرب مع هجومِ ألمانيا على بولونيا في 17 رجب 1358هـ/ 1 سبتمبر 1939م؛ ليتسع ذلك الخلاف بإعلانِ كُلٍّ مِن فرنسا وإنجلترا الحربَ على ألمانيا، ثم تشكَّلَ طرفا النزاع من حِلْفَين: الأول دُولُ الحُلَفاء على رأسِها كُلٌّ من بريطانيا وفرنسا وروسيا الشيوعية، ثم انضمَّت إليهم أمريكا وغيرها من دول أوربية أخرى، والطرف الثاني دُوَل المحور وأبرز من يمثِّلُها ألمانيا النازية بقيادة هتلر، وإيطاليا الفاشية بقيادة موسوليني، والنمسا واليابان ومن التحق بهم من دول أخرى أو شعوب تبحث عن الخلاصِ مِن نِيرِ الاستعمار الأوربي، وقد تعددت أسبابُ ومراحل هذه الحرب الكونية التي بدأت بغزو ألمانيا لبولندا، وانتهت بإلقاء قنبلتين ذريتين على اليابان، وشَمِلَت الحرب معظمَ أراضي القارات الأربع، وشارك فيها أكثر من 100 مليون جندي، وسَخَّرَت الدول الكبرى كلَّ طاقتها الاقتصادية والعسكرية والتقنية والبشرية، كما أسهم استخدامُ سلاح الجو وتطوره المحموم أثناء الحرب بين الدول الكبرى -لتحقيق أكبر قدر من النصر والمكاسب- في مضاعفة الخسائر البشرية والمادية أثناء سنوات الحرب وبعدها؛ حيث بلغت الخسائِرُ في الأرواح أكثر من 60 مليون قتيل، وعشرات الملايين من الجرحى والمشوَّهين والمشرَّدين الذين تم تدمير مدُنِهم بالكامل، ومن أبرز أسباب الحرب: أسبابٌ غيرُ مباشِرة للحرب، منها: 1/ الأزمة الاقتصادية في أعقاب الحرب العالمية الأولى وما خلَّفَتْه من تدهور لاقتصاديات الدول الأوربية خاصة ألمانيا. 2/ معاهدة فرساي بشروطها القاسية التي استهدفت إضعاف ألمانيا عسكريًّا. 3/ خرق هتلر منذ وصوله إلى السلطة سنة 1933م لشروط فرساي عندما رفع عددَ جنود بلاده عن المتاح له باعتمادِ التجنيد الإجباري، وتطوير عتاده الحربي. 4/ ضمُّ هتلر لعدة مناطق بأوربا، كإقليم السار سنة 1936م، النمسا سنة 1938م. 5/ قيامُ تحالف بين الديكتاتوريات الثلاث ألمانيا وإيطاليا واليابان منذ سنة 1937م؛ لتنفيذ برنامج الحزب النازي. 6/ انسحاب الدول الثلاث ألمانيا وإيطاليا واليابان من عصبة الأمم 7/ توسُّع اليابانية في جنوب شرق آسيا (الصين). وأمَّا الأسبابُ المباشرة فأهمُّها: زيادة توتُّر العلاقة بين ألمانيا وفرنسا بعد عقد الأخيرة تحالفًا عسكريًّا مع الاتحاد السوفييتي والذي اعتبرته ألمانيا موجَّهًا ضِدَّها، فصَمَّم هتلر على استعادة عدة مناطق كانت قد انتُزِعَت منه بدعوى أن أغلبيةَ سكانه ألمان، فأعلنت فرنسا وإنجلترا الحرب على ألمانيا، فتضافرت العوامِلُ غير المباشرة مع المباشرة فاندلعت حربٌ كونية ثانية. وقد مرَّت الحرب في مرحلتين: الأولى: بين عامي 1939م و1942م، وتميَّزت هذه المرحلة باعتماد الحرب الخاطفة وشَمِلَت عدة جبهات في آسيا وأوربا، كالهجوم الإيطالي الألماني على فرنسا واكتساحها وتوقيعها هدنة مع دول المحور، وشَنِّ دُوَل المحور هجومًا جويًّا على المدن الإنجليزية بما فيها لندن، دام ثلاثة أشهر نتج عنه خسائر بشرية ضخمة، واحتلال إيطاليا ألبانيا ويوغسلافيا واليونان ودخولها مصر، لكن الإنجليز تمكَّنوا من طرد الإيطاليين من مصر رغم تركُّز الألمان في عدة مناطق من مصر، والهجوم الألماني على الاتحاد السوفييتي وتدميرها للسلاح الجوي السوفييتي على الأرض ووصول الألمان إلى مشارف موسكو، وعجزهم في التقَدُّم بسبب قساوة المناخ والمقاومة السوفيتية، وخلَّف هذا الهجوم خسائِرَ مادية وبشرية هائلة، والهجوم الياباني على القواعد الأمريكية بالمحيط الهادي عام 1941م، وإعلان روزفلت الحربَ على اليابان, وبفضل اعتماد ألمانيا أسلوبَ الحرب الخاطفة واستعمال دول المحور أسلحة جديدة متطورة جوًّا وبرًّا وبحرًا حققت ألمانيا وحليفاتها انتصارات كبيرة خلال هذه المرحلة. أما المرحلة الثانية من الحرب فقد تميزت بشمولية الحرب لأراضي القارات الأربع، وبحار ومحيطات العالم خاصة بعد دخول الولايات المتحدة الأمريكية الحربَ، ورغبة كلِّ معسكر في الانتصار؛ فقد انتصر الحلفاء في معركة العَلَمين بمصر عام 1942م, وتقَدَّمت القوات الإنجليزية نحو طرابلس حيث التقت بجيوشِ الحلفاء القادمة من الدار البيضاء، وبالتالي طرد قوات المحور من ليبيا ومصر وتونس سنة 1943م، وانتصار المقاومة السوفييتية في ستالينغراد على ألمانيا، وتحرير الجيش الأحمر للأراضي السوفيتية، وتشكيل التحالف الأكبر بين الولايات المتحدة الأمريكية والاتحاد السوفييتي وإنجلترا، وشن هجوم على الألمان حُرِّرَت بموجبه فرنسا وتسلمت ألمانيا، وإعلان الحرب على اليابان، فكثفت الولايات المتحدة الأمريكية والاتحاد السوفييتي هجومهما على اليابان برًّا وبحرًا وجوًّا ما بين 1944م و1945م نتج عنه هزائم متتالية لليابان وإغراق 4 حاملات طائرات يابانية، واستعاد الحلفاء عدةَ مناطق في غينيا الجديدة، والفلبين، ولَمَّا رفضت اليابان الاستسلامَ بعد الإنذار الموجَّه لها من الولايات المتحدة تم إلقاءُ قنبلتين ذريتين على هيروشيما في 6 أغسطس، وناجازاكي في 9 أغسطس سنة 1945م ما أسفر عن استسلام اليابان. كان استخدام القنبلة الذرية آخِرَ فَصلٍ من فصول هذه الحرب، وقد ساهم التفوق اللوجستيكي الأمريكي والمقاومة السوفييتية في تغيُّرِ الحرب لصالح الحلفاء، وكان من أبرز نتائج هذه الحرب: تغيُّرُ موازين القوى على الصعيد العالمي، وتغيُّرُ خريطة أوربا حيت توسَّعت مساحةُ عدة دول كبولونيا، بلغاريا، فرنسا، ويوغسلافيا، وكذلك الاتحاد السوفييتي، في حين فقدت دول أخرى جزءًا من أراضيها، كالنمسا، وألمانيا، واليابان، كما تم تقسيمُ ألمانيا إلى أربع مناطِقِ نفوذ خاضعة للدول الأربعة المنتَصِرة في الحرب: إنجلترا، فرنسا، الولايات المتحدة الأمريكية، والاتحاد السوفييتي، وبنفس الطريقة قُسِّمَت برلين وفيينا؛ ومن أجل تجاوُزِ مخلَّفات الحرب الضخمة أنشأت الدولُ العظمى أثناء عقد مؤتمر سان فرانسيسكو سنة 1945م هيئةَ الأمم المتحدة."},{"id":5090,"title":"فرنسا تصدر قرارا بحل حزب الشعب الجزائري ذي الميول الشيوعية. .","date":["العام الهجري :1358","الشهر القمري : شعبان","العام الميلادي :1939"],"text":"بعد الأحداثِ التي عرفَتْها الساحةُ السياسية في الجزائر خلال الثلاثينيات، مثل انعقاد المؤتمر الإسلامي 1936، ووصول الجبهة الشعبية إلى الحكم في فرنسا، ثم خيبة أمل الحركة الوطنية الجزائرية في وعود الإصلاحِ مِن طَرَف الجبهة الشعبية ونتيجةً لحلِّ حزب نجم شمال إفريقيا سنة 1937؛ تم إعادة تشكيل حزب وطني جديد من قِبَلِ بعض أعضاء نجم شمال أفريقيا، فكان حزبُ الشعب الجزائري الذي تأسس في مارس 1937 في فرنسا، ويعتبر امتدادًا لحزب نجم شمال إفريقيا ذي الميول الشيوعية، وقد حضر الاجتماعَ التأسيسي أكثَرُ من 300 شخص، وتم انتخابُ مصالي الحاج \"ذي الميول الشيوعية\" رئيسًا للحزب الذي قرَّر نقل نشاطاته إلى الجزائر بعد عودتِه إليها في 18 جوان 1937، وأصبح حزبُ الشعب منظمةً سياسية قوية، وحركةً وطنية بحتة عُرِفت بقوة التنظيم وبسعة الانتشارِ في كل المدن الجزائرية مستفيدًا من أعضاء نجم شمال إفريقيا السابقين وتجاربهم السياسية، وأصدر حزبُ الشعب عدةَ صُحُف لنشر أفكاره ومبادئه، ومنها صحيفتا الأمة والشعب. ومنذ تأسيس حزب الشعب الجزائري اتخذ شعاره الخاص \"لا اندماج، لا انفصال، لكن تحرُّر\" في محاولة منه لتجنُّبِ المواجهة المباشِرة مع السلطات الفرنسية، وكان للحزب نشاطٌ سياسيٌ مكثفٌ، لكنَّ السلطات الفرنسية أصدرت قرارًا بحَلِّه."},{"id":5091,"title":"قيام الأمير إدريس السنوسي بعقد اجتماع هام في الإسكندرية .","date":["العام الهجري :1358","الشهر القمري : رمضان","العام الميلادي :1939"],"text":"بعد أن استقَرَّ الأميرُ إدريس السنوسي في القاهرة أصبحت حركتُه محدودةً بعد أن فَرَض عليه الاحتلالُ البريطاني في مصر عدَمَ الاشتغال بالسياسة، وكان من حينٍ إلى آخر يكتُبُ في الصحف المصرية حولَ قضية بلاده. وعندما اشتعلت الحربُ العالمية الثانية نَشِطَ إدريس السنوسي وعقد اجتماعًا في داره بالإسكندرية حضره ما يقرب من 40 شيخًا من المهاجرين الليبيين، وذلك في 6 رمضان 1359هـ/ 20 أكتوبر 1939م، وانتهى الحاضِرون إلى تفويضِ الأميرِ في أن يقومَ بمفاوضةِ الحكومة المصرية والحكومة البريطانية لتكوينِ جيشٍ سنوسيٍّ يشترِكُ في استرجاع الوطن بمجرَّدِ دُخولِ إيطاليا في الحربِ ضِدَّ الحلفاء. وبدأ الأميرُ في إعداد الجيوش لمساندة الحلفاءِ في الحرب، وأقيم معسكرٌ للتدريب في إمبابة بمصرَ بلغ المتطوعون فيه ما يزيد عن 4 آلاف ليبي، كانوا فيما بعد عونًا كبيرًا للحلفاء في حملاتِهم ضِدَّ قوى \"المحور\" في شمال إفريقيا، وساهموا مساهمة فعليةً في الحرب، بالإضافة إلى ما قدَّمه المدنيون في ليبيا من خِدماتٍ كبيرةٍ للجيوش المحارِبة ضِدَّ إيطاليا."},{"id":5092,"title":"ثورة الشيخ حيدر بالأحواز على الإيرانيين .","date":["العام الهجري :1359","الشهر القمري : محرم","العام الميلادي :1940"],"text":"كانت إيران قد احتلَّت الأحواز (عربستان) في عهد رضا بهلوي عام 1925 بعد أن منحته بريطانيا هذا الإقليمَ العربيَّ مكافأة له على مساندتِه لها في الحرب العالمية الأولى، وقد بلغ غضبُ الأحوازيين بعد الأوضاع الشاذة التي تعرَّض لها على أيدي السلطات الإيرانية المحتلَّة ذِروتَه هذا العامَ، فأخذ أحرارُ الأحواز يحَرِّضون العشائِرَ على الثورة ورَفْع الذلِّ الذي نكَّس رؤوسَهم طوال هذه السنوات, وغسل عار استعبادهم. وبات البركانُ يغلي، والشعبُ الأحوازي يريد الفرصةَ المواتية له حتى يُظهِرَ استياءَه من الوضع، ويعلِنَ غَضَبَه على التنكيل والتعسُّف اللذين يتعَرَّضُ لهما، والاحتقار والازدراء اللذين يلاقيهما من السلطات العسكرية الفارسية؛ فهو صاحب الأرض، ولكن لا مكان لسكناه، وهو صاحِبُ الخيرات إلا أن الجوعَ نصيبُه, وفي 10 فبراير من هذه السنة تفجَّر بركانُ غضب الأحوازيين، وكانت منطقةُ الميناو محلَّه، وعشائر كعب العربية (حكام الإقليم قبل الاحتلال) هم من فجَّر الثورة بإعلان ثورتِهم على الاستعباد، وغضبِهم على سالبي حريتِهم وكرامتِهم وحقوقِهم، وكان قادةُ هذه الثورة زعماء كعب، ومنهم: حيدر بن طُلَيل، وهو القائد الحقيقي للثورة؛ لذا سمِّيَت باسمه \"ثورة الشيخ حيدر\"، وطُلَيل تصغيرٌ لطلالٍ. ومن القادة مهدي بن علي بن عمير: رئيس عشيرة كعب منان. ومسلم السلمان: أحد شيوخ كعب آل حاجي. وكاطع الشذر: شيخ طوائف مزرعة العشائر العربية الموجودة في الميناو. وداود الحمود: من شيوخ بني كعب. وأبريج: شيخ خزرج. وكان هدفهم القضاءَ على حاميات الفُرس الموجودة في المنطقة، وقد تمكَّنوا من إزالة تلك الحاميات. وسيطروا على ثكناتِها سيطرةً كاملةً، وقد دامت السيطرةُ العربية مدةً طويلة على المنطقة جاوزت الأربعة أشهر، لكن استطاعت سلطاتُ الفرس الإيرانية بعد ذلك أن تلقيَ القبض على الشيخ حيدر وجماعته، وفورَ اعتقالِهم نُقِلوا إلى منطقة تدعى (قلعة سهر)؛ حيث نُصِبَت لهم محكمةٌ عسكرية قضت بإعدام: حيدر طليل، ومهدي بن علي، وأبريج شيخ خزرج."},{"id":5093,"title":"قرار لاهور (قرار باكستان) بشأن تقسيم الهند .","date":["العام الهجري :1359","الشهر القمري : صفر","العام الميلادي :1940"],"text":"كان المسلِمون في الهند قد قدَّموا مشروعاتٍ مِن أجل التقسيم؛ فمنهم من يرى الانقسامَ عن الهندوس، ومنهم من يرى البقاءَ وعدم التقسيم؛ لمصلحة الدعوة والأقليات، وكان محمد إقبال قد دعا إلى تشكيلِ دولة باكستان والانفصال عن الهندوس في 1356هـ، ولكنه توفِّيَ في العام التالي، ثم عُقِد مؤتمر السند الإقليمي للرابطة الإسلامية في كراتشي برئاسة محمد علي جناح، وقرر في شعبان 1357هـ / 10 أكتوبر 1938م أنَّه من الضروري تقسيم الهند إلى اتحادين: اتحاد للدول الإسلامية، وآخر للدول غير الإسلامية، ثم دعا حزب الرابطة إلى عقد مؤتمر في مدينة لاهور، وقد عُقِدَ المؤتمر وأقرَّت اللجنة العاملة للرابطة لعموم الهند في اجتماعها في صفر 1358هـ / 26 مارس 1939م تشكيلَ لجنة لدراسةِ المشروعات المقَدَّمة بشأن التقسيم والدستور، ومسألة حكم الأغلبية، ثمَّ عُقِدت اجتماعاتٌ للَّجنة العاملة ولمجلس الرابطة لعموم الهند في دلهي وجرت دراساتٌ جادة لمسألة تخصيص موطِنٍ منفصل للمسلمين، ثم تمَّ في الاجتماع الذي عقدته اللجنة العاملة في 12 صفر 1359هـ / 21 مارس 1940م تعيينُ لجنة خاصة لصياغة مشروعِ القرار الشهير بقرار لاهور، الذي طُرِحَ بعد يومينِ مِن التعيين المذكور، وفيه أنَّ المسلمين لن يقبَلوا بأيِّ خطة معدَّلة إلا إذا تم وضعُها بموافقتهم وإقرارهم ابتداءً، وأنَّه ما من خطة دستورية يمكِنُ أن تُقبَل إلَّا إذا أُعِدَّت وَفقَ مبادئ جوهرية يراها المسلمون، وفيه مسألةُ الدول المستقلة التي تتمتَّعُ الوحداتُ المكَوِّنة منها لها بحُكمٍ ذاتي وسيادة، وأن يتضَمَّن الدستور ضماناتٍ كافيةً مفوَّضًا بها من أجل الأقليات، وحيث يكون المسلمون أقليَّةً في إقليم يجِبُ أن يحَدَّد في الدستور ضماناتٌ كافية وفعَّالة ومفوَّض بها لحماية حقوقهم ومصالحهم الدينية، وأن يتسلَّمَ كُلُّ إقليم جميعَ السلطات، كالدفاع، والخارجية، والمواصلات، والجمارك، وبقية الأمور الضرورية الأخرى."},{"id":5094,"title":"وفاة الشيخ عبد الحميد بن باديس مؤسس جمعية العلماء المسلمين بالجزائر .","date":["العام الهجري :1359","الشهر القمري : ربيع الأول","العام الميلادي :1940"],"text":"هو الشيخُ عبد الحميد بن محمد المصطفى بن مكي بن باديس مؤسِّسُ جمعية العلماء المسلمين بالجزائر. ولِدَ في 11 من ربيع الآخر 1307هـ بمدينة قسنطينة، ونشأ في أسرةٍ كريمة ذات عراقة وثراء، ومشهورة بالعلم والأدب، سافر إلى تونس في سنة 1326هـ وانتسب إلى جامع الزيتونة، وتلقى العلومَ الإسلاميةَ على جماعةٍ مِن أكابر علمائه، أمثال الشيخ محمد الطاهر بن عاشور، ولقد آمن ابنُ باديس بأنَّ الطريق الأوَّلَ لمقاومة الاحتلال الفرنسي هو العلم؛ لذا عَمِلَ ابن باديس على نشر العلم، وقد بدأ ابن باديس جهودَه الإصلاحية بعد عودته من الحَجِّ بإلقاء دروس في تفسير القرآن بالجامع الأخضر بقسنطينة، ودعوته إلى تطهير العقائدِ مِن الأوهام والأباطيل التي علقت بها، ثم بعد بضعِ سنوات أسَّس جماعةٌ من أصحابه مكتبًا للتعليم الابتدائي في مسجد سيد بومعزة، ثم انتقل إلى مبنى الجمعية الخيرية الإسلامية التي تأسَّست سنة 1336هـ، وقد هدفت الجمعيةُ إلى نشر الأخلاق الفاضلة، والمعارف الدينية والعربية، والصنائع اليدوية بين أبناء المسلمين وبناتهم، ودعا المسلمين الجزائريين إلى تأسيسِ مِثلِ هذه الجمعية، أو تأسيس فروعٍ لها في أنحاء الجزائر؛ لأنه لا بقاءَ لهم إلا بالإسلام، ولا بقاءَ للإسلام إلا بالتربية والتعليم. وحثَّ ابنُ باديس الجزائريين على تعليم المرأة، وإنقاذها ممَّا هي فيه من الجهل، وتكوينها على أساسٍ من العِفَّة وحسن التدبير، وبعد احتفال فرنسا بالعيد المئوي لاحتلال الجزائر في سنة 1349هـ شُحِذَت همم علماء المسلمين في الجزائر وحماسهم وغيرتهم على دينهم ووطنهم، فتنادوا إلى إنشاءِ جمعية تُناهِضُ أهداف المستعمِر الفرنسي، وجعلوا لها شعارًا يعبِّرُ عن اتجاههم ومقاصدهم هو: \"الإسلام ديننا، والعربية لغتنا، والجزائر وطننا\"، وانتخبوا ابنَ باديس رئيسًا لها. وقد نجحت هذه الجمعيةُ في توحيد الصفوف لمحاربة المستعمِر الفرنسي، وحشْد الأمة الجزائرية ضِدَّها، وبَعْث الروح الإسلامية في النفوس، ونَشْر العلم بين الناس، وانتبهت فرنسا إلى خطر هذه التعبئة، وخَشِيَت من انتشار الوعي الإسلامي، فعطَّلَت المدارس، وزجَّت بالمدرسين في السجون، وأصدر المسؤول الفرنسي عن الأمن في الجزائر في عام 1352هـ تعليماتٍ مُشدَّدة بمراقبة العلماء مراقبةً دقيقة، كان ابن باديس مجاهِدًا سياسيًّا مجاهِرًا بعدم شرعية الاحتلال الفرنسي، وأنَّه حُكمٌ استبدادي غير إنساني، يتناقَضُ مع ما تزعُمُه مِن أن الجزائر فرنسية، وأحيا فكرةَ الوطن الجزائري بعد أن ظنَّ كثيرون أن فرنسا نجحت في جعْل الجزائر مقاطعةً فرنسية، وقد عبَّرَ ابن باديس عن إصرار أمَّتِه وتحديها لمحاولات فرنسا بقوله: \"إن الأمةَ الجزائريةَ ليست هي فرنسا، ولا يمكِنُ أن تكون فرنسا، ولا تريد أن تصير فرنسا، ولا تستطيع أن تصير فرنسا لو أرادت، بل هي أمةٌ بعيدةٌ عن فرنسا كلَّ البعد؛ في لغتها، وفي أخلاقِها وعنصرها، وفي دينها، لا تريد أن تندمِجَ، ولها وطن محدَّدٌ مُعَيَّن هو الوطن الجزائري\" ودخل في معركة مع الحاكم الفرنسي سنة 1352هـ واتَّهمه بالتدخُّل في الشؤون الدينية للجزائر على نحوٍ مخالفٍ للدين والقانون الفرنسي، وأفشل فكرةَ اندماج الجزائر في فرنسا التي خُدِعَ بها كثير من الجزائريين سنة 1353هـ. ودعا نوابَ الأمة الجزائريين إلى قَطعِ حبال الأملِ في الاتفاق مع الاستعمار، وضرورة الثقة بالنفس، وكانت الصحفُ التي يصدِرُها ابن باديس أو يشارِكُ في الكتابة بها من أهمِّ وسائله في نشر أفكاره الإصلاحية، وكان ابن باديس قد أصدر جريدة \"المنتقد\" سنة 1343ه وتولى رئاستَها بنفسِه، لكنَّ المحتَلَّ عطَّلها، فأصدر جريدة \"الشهاب\" واستمَرَّت في الصدور حتى سنة 1358هـ، واشترك في تحرير الصُّحُف التي كانت تصدِرُها جمعية العلماء المسلمين الجزائريين، مثل (السنة) و(الصراط) و(البصائر). توفِّي ابن باديس في 8 ربيع الأول، وكان سببُ وفاته التعب والإرهاق، وذلك أنه كان يلقي يوميًّا 15 درسًا، وفي عطلة نهاية الأسبوع كان يسافر إلى العاصمة، ثم يتنقِلُ من محطة القطار إلى الجامع الأخضر، وكان آخر درس ألقاه على النساء 3 أيام قبل وفاتِه في نفس الجامع، وكان كثير التنقُّل في الفترة الممتدَّة بين الصبح والظهر من البيت الذي يحضِّرُ فيه الدروس إلى مكان الإلقاء. وقد وافته المنيةُ في حدود الساعة الثانية بعد الظهر بحضور الدكتور ابن جلول ودكتور فرنسي وشقيقه الأكبر زبير، ولم يتمَّ تسميمُه ولم يُصَب بسرطان ولا بمَرَض أمعاءٍ، كما أشيعَ بعد موتِه."},{"id":5095,"title":"دول المحور تنقل ميدان الحرب إلى البحر المتوسط وبلدان شمال أفريقيا  .","date":["العام الهجري :1359","الشهر القمري : رمضان","العام الميلادي :1940"],"text":"اندلعت نارُ الحرب العالمية الثانية في 17 رجب 1358هـ، ودخلت إيطاليا إلى جانب ألمانيا واليابان مقابِلَ إنجلترا وفرنسا والولايات المتحدة الأمريكية وروسيا، ومعنى ذلك أن أرضَ ليبيا ستكون ساحةَ صراع بين الأطراف المتخاصِمة؛ فأرضُها مُحتلَّة من قِبَل إيطاليا، بينما إنجلترا محتَّلةٌ الأراضي التي تحدُّها من الشَّرقِ، وهي مصر. وفرنسا تحتَلُّ الأراضي التي تحدُّها من الغرب والجنوب، وهي: تونس والجزائر وتشاد والنيجر، وكان الأسطول الإنجليزي له قوَّتُه في البحر المتوسط، ثم يأتي بعده الأسطول الفرنسي، وإيطاليا لها سواحِلُ ممتدة في وسط البحر، فلما انتصر الألمانُ على فرنسا واستطاعوا احتلالَها وسيطروا على معظَمِ أوربا حاولوا النزول إلى إنجلترا ففشلوا، فأرادوا نقلَ المعركة إلى البحر المتوسط لضرب مواقع الإنجليز المهمَّة واحتلالها، وهي: جبل طارق ومالطة وقبرص والإسكندرية، فالتقى هتلر الألماني مع موسوليني الإيطالي في برينير في رمضان 1359هـ / أكتوبر 1940م وأعلمه بنقلِ المعركة إلى البحر المتوسط، فبدأ الطليان الهجومَ على مصرَ مِن ليبيا، واستطاعوا دخولها ولم يمضِ أكثَرُ من شهرين حتى وصلوا إلى موقع سيدي براني، وبعد شهرين آخرين قام الإنجليز ومعهم الأستراليون بهجوم كاسح والتقوا بالإيطاليين حتى بنغازي غيرَ أن الألمان والطليان بقيادة رومل قاموا بهجومٍ معاكِسٍ أجبروا فيه الإنجليزَ على الرجوع إلى حدود مصر في عام 1360هـ / حزيران 1941م ثم تابع سيرَه إلى الإسكندرية غيرَ أنه توقف في موقع العلمين، وبذلك وصل الألمان والطليان إلى ذِروةِ تفوُّقِهم."},{"id":5096,"title":"ثورة رشيد عالي الكيلاني ضد الاحتلال البريطاني في العراق .","date":["العام الهجري :1360","العام الميلادي :1941"],"text":"ثورةُ رشيد عالي الكيلاني هي سلسلةُ الأحداث الدستورية التي تصاعدت بسببِ تضارُبِ مدارس الحُكم الملكي في العراق وتياراتِه ما بين التيارِ الوطني الثوري التحرري، والتيار الليبرالي الميَّال لممالأة الإنجليز، في وقت كان العراقُ يمثِّل زعامةً ومدرسةً سياسيةً يُعتَدُّ بها في المنطقة العربية، فلما تفاقمت الأمورُ في الحكومة العراقية وتأزَّمت بسبب موقِفِ العراق من الحرب العالمية الثانية وموقِفِها من الدول المتحارِبة، وكذلك بسبب رفض إنجلترا تسليحَ العراق، شعرت إنجلترا بما يُساوِرُ نفوس العراقيين وما يختَلِجُها من الاستياء من سياستها في العراق، وكرههم للحكومة العراقية الموالية للمحتَلِّ ودورانها في فلَكِها، فأرادت بريطانيا أن تُخفِّفَ من وطأة هذه الكراهية عليها وعلى أعوانها، ورأت أن تُسلِّمَ الحُكمَ للمعارضة، وقد برز بين رجال المعارَضة رشيد عالي الكيلاني -المعروف بوطنيته وعدم ارتياحه للإنجليز- وأن تعمَلَ ما في وُسعِها ليدورَ في فلَكِها، وربما يحدِثُ هذا فيما إذا قرَّبه أعوانُها، وأظهرت رضاها عن ذلك، ولَمَّا لم تستطع تنفيذَ خططها بجَلبِه إلى دائرة سياستها أبرزت كيفيةَ تسلُّم الكيلاني الحكم، وأنه قد تمَّ عن ترشيح أصدقائها. وتبعًا لهذا فقد رشَّحه نوري السعيد والوصي معًا لتسلُّم السلطة، غير أن رشيد الكيلاني لم يعتَمِدْ على هذا الترشيح، وإنما كان يرتكِزُ على قاعدة قوية؛ فالشعبُ يَدعَمُه، والجيش يُؤيِّدُه، وإضافةً إلى هذا فقد أخذ تعهدًا من رجال السياسة سواء الذين يناوِئونه؛ أمثال نوري السعيد، وتوفيق السويدي، وعلي جودت الأيوبي، وجميل المدفعي، أم الذين يؤيدونَه؛ أمثال ناجي شوكت، وناجي السويدي. ورُفِعَ هذا التعهُّد إلى الوصي فأيَّده، وبذا كانت الأرضُ التي يقف عليها رشيد عالي الكيلاني صلبةً، وخاب فألُ إنجلترا من كل النواحي؛ فمن ناحية ابتهج الشعب به، وضَمِنَ سلامة الخط، فأبدى الكيلاني مُعارضتَه للسياسة البريطانية، وأخذ يُصرِّح بذلك، ومن ناحية ثانية لم تستطع إنجلترا جرَّ رشيد عالي الكيلاني إلى سياستها، بل أبدى قوَّةً في الشخصية، وأظهر استقلاليَّتَه؛ حيث رفض قطْعَ العلاقة مع إيطاليا التي أعلنت الحربَ ضِدَّ إنجلترا وفرنسا، وهذا ما أغضب إنجلترا أشَدَّ الغضب؛ إذ أحسَّت أن العراقَ ليست تحت نفوذها، ولا تسيرُ برأيها، غيرَ أنَّه من الجانب الآخر قد ألهب هذا التصرُّفُ الشعبَ في العراق حماسةً لموقِفِ حكومته، وهذا ما زاده مُعارضةً للسياسة الإنجليزية. وانهارت فرنسا أمام الألمان، فطار الشعبُ فرحًا ليس حبًّا بالألمان، ولكن كرهًا لفرنسا ولسياستها الاستعمارية، وفي الواقع فقد زادت الدعايةُ لدول المحور في العراق رغبةً في هزيمة الحلفاء، ولم تُقصِّر المفوضية الإيطالية بذلك، وحتى توقعت إنجلترا أن تستأنِفَ العراق عَلاقتها مع ألمانيا، وهذا ما خَشِيَته أشدَّ الخشية، واستشاطت إنجلترا غضبًا وأخذت تعمل للتخلُّص من حكومة رشيد عالي الكيلاني، وكان لها ما أرادت؛ إذ أوعزت إنجلترا لأعوانها بالانسحاب من الوزارة، فكان عليها أن تستقيلَ وتُفسِحَ المجالَ لحكومة جديدة وأرادت إنجلترا أن تخرُجَ من المأزق الذي وقَعَت فيه بتسليم رشيد الكيلاني الحكم، وأرادت أن تخرجَ من المأزق بهدوءٍ ولا تعطي السلطةَ لأحدِ أعوانها؛ فقد يؤدى إلى مظاهرات وربما تندلع ثورة، وبمجرد أن طلب الوصيُّ من الكيلاني أن يقَدِّمَ استقالة حكومته حتى اهتَزَّ الوضع وتحرَّك الجيشُ وقامت مظاهراتٌ تطالب بتحقيق رأي الكيلاني بحَلِّ المجلس النيابي، وإجراء انتخابات جديدة، وتشَكَّلت وزارة طه الهاشمي، وهو قريب من المعارضة، وفي الخامس من ربيع الأول 1360هـ اجتمع في معسكر الرشيد رشيد علي الكيلاني: رئيس الحكومة، واللواء أمين زكي: رئيس الأركان، وبعض الضباط، وأعلنوا الاستنفارَ بالمعسكر وقرَّروا القيام بانقلابٍ إذا رفضت حكومةُ طه الهاشمي الاستقالةَ، وهي الحكومة التي ترضى عنها بريطانيا ويؤيِّدُها الوصيُّ على الملك عبد الإله بن علي، ثمَّ طلبوا منه التفاهُمَ مع الكيلاني لتشكيل وزارة جديدة، فأبى ثم أُجبِرَ على الاستقالة، ولما أُعلِمَ الوصي بذلك هرب متسللًا ودعا طه أعضاء وزارته للاجتماع به، وكان الجيش قد دخل المدينةَ وسيطر على المداخل الرئيسة وحاصر قصر الوصي الذي هرب منه، ثم في صباح 6 من ربيع الأول ذهب رشيد الكيلاني إلى دار طه لإقناعه بالانضمام لحركتِهم فوجدوا الوزارةَ ما زالت مجتَمِعةً، فجرى نقاشٌ حادٌّ ثم اجتمع الرأي على إبقاء الوزارة في الحكمِ، وألا يتدخَّل الجيش في السياسة، ويتعهد المدنيون والعسكريون على السواء بأن يقبَلوا بما يتم الاتفاق عليه، ويُطلَب من الوصي العودة للعاصمة، الذي كان قد انتقل إلى البصرة، ثم عاد رشيد الكيلاني والضباط فسَحَبوا الثقة من حكومة طه، وقرَّر الجيش تحمُّل المسؤولية في هذه المرحلة الحَرِجة, وقام رشيد باستدعاء المستشار الإنجليزي بوزارة الداخلية، وأعلمه أن حكومة طه الهاشمي استقالت والوصي غائب، وبذلك فالجيش هو مصدرُ السلطة، وقد أوكل الجيشُ لرشيد الأمرَ وهرب الوصي ومن معه إلى فلسطين، وتمَّ عَزلُ الوصي عبد الإله، وتعيين وصي جديد هو الشريف شرف الذي قَبِلَ استقالة حكومة طه الهاشمي، وسُرَّ الشعب بحركة رشيد عالي الكيلاني، وأما إنجلترا فقد عَدَّت هذا عملًا غير مشروع فقررت التخلُّصَ من حركته بالقوة، فطلبت من الهند إرسالَ قوات فنزلت رغم أنف الحكومة الجديدة، وحاصر الجيشُ العراقي قاعدةَ الحبانية الجوية، وفي 5 ربيع ثاني وزَّعت السفارة البريطانية منشورًا تتهم فيه الكيلاني وقادةَ الجيش أنهم باعوا أنفسهم للألمان والطليان، وأنها خوَّلت سفيرها اتخاذ ما يراه مناسِبًا، وفي الغد صباح 6 ربيع الثاني بدأ الهجومُ الجوي الإنجليزي وضَرْب المواقع العراقية وقصَفَت معسكر الرشيد، وأعلن المفتي الفلسطيني الجهادَ، وجاءت قواتٌ ألمانية تُعِين العراقيين بحكم عدائها لبريطانيا ضِمنَ الحرب العالمية الثانية إلَّا أنَّ قَصْفَها ليس جادًّا بالنسبة لَمَّا عُرٍف عن السلاح الجوي الألماني، ثم تدخَّلت قوات برية إنجليزية من الأردن، فقام رشيد الكيلاني بتشكيلِ لجنة الأمن الداخلي واتصل بالسياسيين لوقف القتال، وفي 6 جمادى الأولى رحل رشيد الكيلاني ومفتي فلسطين وغيرهم إلى طهران، وفي 7 جمادى الأولى وافق أمينُ العاصمة أرشد العمري على شروطِ هدنة قاسية على العراقيين؛ لأنَّهم لم يعودوا قادرين على مقاومة الإنجليز، فلم يكن لهم خيارٌ غير القبول بالهدنة، وعاد الوصي عبد الإله ونوري السعيد ومن معهما من أعوان الإنجليز إلى بغداد على متن طائرة بريطانية، وبهذا انتهت حركةُ رشيد عالي الكيلاني التي تعلَّقَت بها آمال العراقيين في التخَلُّص من الاستعمار البريطاني بمساعدة أعداء بريطانيا المتمَثِّل في الألمان والطليان."},{"id":5097,"title":"دور الإمبراطور هيروهيتو في دخول اليابان الحرب العالمية الثانية  .","date":["العام الهجري :1360","العام الميلادي :1941"],"text":"خرجت اليابانُ مِن هذه الحرب بملايين القتلى والجرحى من شَعبِها، واقتصاد مدمَّر كلِّيًّا، وسيطرة كاملة على أراضيها مِن قِبَل القوات الأمريكية؛ فمن هو المسؤول عن إشراك اليابان في هذه الحرب المدمِّرة، وتعرُّض الشعب إلى الكوارث بسببها؟ يرى البعضُ أن الإمبراطور هيروهيتو غيرُ مسؤول؛ لأن الحكومة والجيش الياباني ذا التوجُّهات القومية المتطرِّفة والنزعة التوسعية يعملون خلال السنوات الأخيرة منذ عهد الإمبراطور السابق يوشيهيتوا على إحكامِ سيطرتهم على مقدَّرات البلاد، وأنه بعد وفاته واعتلاء ابنِه هيروهيتو العرش لم ترغب الحكومةُ ولا الجيشُ في إعادة السلطات والامتيازات التي حصلوا عليها خلالَ سنوات حُكمِ أبيه الأخيرة لهيروهيتو؛ ليحكموا باسمه أمام الشعب الياباني. بالإضافة إلى أن الإمبراطور هيروهيتو كان يبدي معارضته وامتعاضه منذ بدايةِ تنفيذ قادة الجيش والحكومة اليابانية لخطَّتِهم التوسعية في قارة آسيا وغزوهم الصين والمذابح التي ارتكبوها هناك قبل الحرب الثانية، وحاول حثَّ الحكومة اليابانية على حَلِّ خلافاتها مع الحكومة الأمريكية عن طريق الحوارِ؛ لأنه كان يريد السلامَ، لكِنَّهم لم يُصغُوا إليه ولا لتوسلاته. بينما يرى البعضُ الآخر أن الإمبراطور هيروهيتو هو سبب رئيس في دخول بلادِه الحرب؛ ولذا كان من الواجب أن يحاكَمَ دوليًّا لدوره في الحربِ؛ فقد حضر جميعَ الاجتماعات الخاصة بحكومته وقادة جيشه، وأنه كان يناقش ويحاور، وكان لا يوقِّع على أي مرسوم أو قرار حتى يفهَمَه ويعرف الغرض منه، كما أنَّ أحد أفراد العائلة المالكة ومن المقرَّبين إلى الإمبراطور ناشده هو وبعض مستشاري الإمبراطور في السنة الأخيرة من الحرب بوقف الحربِ والدخول في محادثات مع الحلفاء، فرفض مشيرًا إلى أنه اجتمع مع قوَّادِ جيشِه وأمرهم بفِعلِ كُلِّ ما يستطيعون لتحقيقِ بعض الانتصارات السريعة على القوات الأمريكية؛ لحفظ ماء وجه الإمبراطورية، وأنه في الشهور الأخيرة من الحرب أمر بالتعبئة الشعبية العامة؛ وذلك لإيجاد دروعٍ بشرية تواجِهُ أي إنزال بحري محتَمَل لقوات الحلفاء على السواحل اليابانية؛ حيث أدى هذا التعَنُّت في إيقاف الحرب إلى فقد مليون ونصف مليون ياباني حياتَهم خاصةً بعد إلقاء قنبلتي هيروشيما وناجازاكي، وأمَّا السبب في عدم محاكمة الإمبراطور هيروهيتو كمُجرمِ حَربٍ مثل بعض المسؤولين في الحكومة والجيش الياباني فهو أنه بعد إعلان اليابان استسلامَها ودخول طلائع قوات التحالف إلى الأراضي اليابانية، خَشِيَ قائد تلك القوات والمفوَّض بإدارة اليابان الجنرال الأمريكي دوغلاس مكارثر أن يواجِهَ هو وقواته مقاومةً عنيفة من الشعب الياباني خاصةً مع ورود تقارير تفيد بأن مجموعات كبيرة من السكان تنوى القيامَ بعمليات انتحارية ضِدَّ قوات التحالف إذا دخلت مُدُنَهم وقراهم؛ لذلك عقد مكارثر اتفاقًا مع الإمبراطور هيروهيتو ينصُّ على منح الإمبراطور هيروهيتو حصانةً من أن يحاكَمَ كمُجرم حرب أمام أي محكمة دولية، وأعطاه وعدًا بأن تقوم الولايات المتحدة بمساعدته في إعادة إعمار اليابان شريطةَ أن يدعَمَ وجود القوات الأجنبية في بلادِه، فتم الاتفاق وسارت الأمور كما أراد مكارثر، وقام الأمريكيون وحلفاؤهم بحملةٍ دعائية ترويجية عالَمية تبين أن هيروهيتو لم يكن له يدٌ فيما قام به الجيش الياباني خلال الحرب العالمية الثانية من غزوٍ ومذابح، وكان مغلوبًا على أمره أمام السيطرة الكلية لقادة جيشِه وأعضاء حكومته المتشَدِّدة."},{"id":5098,"title":"تنازل رضا شاه ملك إيران لولده محمد .","date":["العام الهجري :1360","الشهر القمري : شعبان","العام الميلادي :1941"],"text":"كانت إيران قد وقفت في الحرب العالمية الثانية مع ألمانيا ضِدَّ الحلفاء الذين طالبوا إيران بتسليمِ الألمان الموجودين في إيران، وفي 15 شعبان 1360هـ / 6 أيلول 1941م عاد الحلفاءُ فطلبوا من إيران طرْدَ البَعثات السياسية لدول المحور، وفي 23 شعبان / 14 أيلول طلبت بريطانيا وروسيا من الشاه رضا بهلوي التنازُلَ عن العرش لولي عهده محمد رضا، وإعلان الحرب على ألمانيا وبقية دول المحور، فرفض فأجبره الحلفاءُ على التنازل؛ ففي 25 شعبان / 16 أيلول تنازل الشاه لابنه عن الحكم، وقرأ محمد علي فروغي رئيس الوزراء وثيقةَ التنازل للمجلس، وترك رضا شاه طهران إلى أصفهان، ثم انتقل إلى جزيرة موريشيوس وفُرِضَت عليه الإقامة الجبرية هناك، ثم نقل إلى جوهانسبرغ جنوبي إفريقيا حتى توفِّيَ فيها، وبعد عدة سنوات نُقِل رفاته إلى طهران، أما ابنه فتُوِّجَ في نفس اليوم الذي تنازل له فيه والده عن الحكم، وتوِّجَ شاهًا على إيران وأدى اليمين الدستورية، وتعهد أمام المجلس بحِفظِ سيادة إيران، وصيانة حقوق الشعب، واحترام الدين الإسلامي، ورعاية الدستور والقوانين."},{"id":5099,"title":"اليابان تحتل جنوب شرقي آسيا .","date":["العام الهجري :1360","الشهر القمري : ذي القعدة","العام الميلادي :1941"],"text":"دخلت اليابان الحرب العالمية الثانية إلى جانب دول المحور تتزعَّمُهم ألمانيا النازية واستطاعت اليابان القيامَ بحروب خاطفة باحتلالِ جنوب شرقي آسيا، وكان من بين ما احتلَّتْه: جزيرة بورنيو (أندونيسيا)، وشبه جزيرة الملايو (ماليزيا) بعد حملة دامت أكثر من شهرين، وذلك في 20 ذي القعدة 1360هـ / 8 ديسمبر 1941م، كما استولت على سنغافورة مَعقِل القوات البريطانية في المنطقة، ووضعت البلادَ تحت الإدارة العسكرية اليابانية، فعَيَّنت رؤساء يابانيين مهمَّتُهم الإشراف، ولم يكن اليابانيون أرحمَ مِن غيرِهم؛ فالكُفرُ مِلَّةٌ واحدةٌ، وحِقدُه على الإسلام وأهلِه، ولكِنَّ الأمر لم يدُمْ طويلا؛ فبعد الانتهاء من الحرب وهزيمة اليابان ودول المحور عادت بريطانيا إلى البلادِ التي كانت فيها وخرج اليابانيون."},{"id":5100,"title":"مذبحة المسلمين في مقاطعة القراقي بالحبشة .","date":["العام الهجري :1361","العام الميلادي :1942"],"text":"بعد أن عاد هيلا سيلاسي إلى الحكم في عام 1361 / 1942م وبعد أن أتمَّ استئناف برامجه لتنصير المسلمين، جاءت الهيئاتُ التنصيرية السويدية بإيعازٍ منه إلى منطقة القراقي الإسلامية، والتي لا يوجَدُ فيها نصراني واحد، أو يهودي أو وثني، فهَبَّ شيخ المقاطعة عبد السلام يطالبُ عن طريق القانون منعَ دخول المنصِّرين إلى هذه المقاطعة الإسلامية؛ تجنُّبًا لِما يحدث من أضرار للمنَصِّرين، فاتهمته السلطاتُ بأنه يبَيِّت العدوان على المنصِّرين، فاعتقلَتْه وزجَّتْه في السجن، فاحتشد المسلمون في تلك المقاطعة أمام بيت الحاكم الأمهري، وطلبوا الإفراجَ عن الشيخ عبد السلام، فأخذ الجنود بضرب المسلمين، ثم تلاه إطلاقُ النار الذي خلَّف عشرات القتلى، وأعلن عن موت الشيخ بالسَّجنِ، فانتقم الأهالي بإحراقِ مراكز التنصير، فقام الإمبراطور هيلا سيلاسي بمنحِ أراضيهم الزراعية للمنَصِّرين، وشَرَّد من نجا مِن رَصاص جنودِه، وأصبحت القرية مِلكًا للنصارى بكامِلِها بعد أن كانت للمسلمين بأكمَلِها!"},{"id":5101,"title":"تحرر الحبشة من الاحتلال الإيطالي. .","date":["العام الهجري :1361","العام الميلادي :1942"],"text":"احتلَّت إيطاليا الحبشة عام 1354هـ / 1935م رغم مُعارضة الأمم المتحدة وفَرْض العقوبات الاقتصادية، ثم لَمَّا قامت الحرب العالمية الثانية قامت الثورات في الحبشة ضِدَّ الطليان بتحريضٍ مِن البريطانيين وباقي الحلفاء، وزحفت القوات البريطانية من السودان إلى الحبشة، وخرج الطليان من البلاد ودخل الإنجليز أديس أبابا عام 1360هـ / 1941م، وأعيد الإمبراطور هيلا سيلاسي من منفاه في العام نفسِه، وبعد أن استسلمت آخِرُ الحاميات الإيطالية في غوندار عام 1361هـ / 1942م أعلنت الحبشةُ الحرب على دول المحور، ووقفت بجانب الحلفاء، وانتهت الحرب، وفَصَلت الأمم المتحدة التي تشكلت بعد الحرب بين الحبشة وأريتريا، فعادت الحبشة دولةً مستقلةً، وهكذا لم تخضع الحبشةُ للاستعمار إلا لمدة سبع سنوات، بخلاف ما حدث لبقية الدول الأوربية وما ذلك إلا لنصرانيَّتِها."},{"id":5102,"title":"إنشاء الحاج أمين الحسيني معاهد لتخريج الأئمة في دول المحور  .","date":["العام الهجري :1361","العام الميلادي :1942"],"text":"أثناء إقامة المفتي الحاج أمين الحسيني في ألمانيا بعد فراره من الإنجليز أيامَ الحرب العالمية الثانية سَمِعَ بالمآسي التي حلَّت بالشعب البوسني المسلم عندما تصارعت عليه القوميتان الكرواتية والصربية؛ حيث اجتمع بزعماء بوسنة وهرسك، وبعد البحثِ معهم ومع قيادة القوات الألمانية في كيفية المحافظةِ على حياة البشناق (البسنويين) ومَنْع وقوع المذابح فيهم، وافقت الحكومة الألمانية على تجنيد الشبَّان منهم وتسليحهم للدفاعِ عن أنفسِهم وعائلاتهم، كذلك اتَّفق المفتي مع السلطات الألمانية على إنشاء معهد للأئمة لتوزيعهم على وحدات الفِرَق البوسنية الذين زاد عددُهم عن 100 ألف مقاتل، وقد أنشأ المعهد واختير له عدد من علماء البشناق؛ لتوجيه أولئك الأئمة، وأنشأ المفتي كذلك بالاتفاق مع الألمان معهدًا آخر في (دردسن)؛ لتخريج الأئمة الأذربيجانيين والقوقازيين وغيرهم، وبذلك زاد عدد المجندين في بلاد المحور من عرب وبوسنيين وأذربيجانيين وغيرهم على مائتي ألف مقاتل، استطاعوا أن يمنعوا المجازِرَ عنهم وعن جميع مُسلِمي البلقان وشرق أوروبا."},{"id":5103,"title":"الإنذار البريطاني لفاروق ملك مصر وأحداث 18 محرم 1361هـ .","date":["العام الهجري :1361","الشهر القمري : محرم","العام الميلادي :1942"],"text":"في منتصف محرم - 1 فبراير قامت مظاهراتٌ تطالب بإسقاط الحكومة بعد أن ظهر أنَّها توالي الإنجليز، وصادف ذلك هوًى في نفس فاروق الملك، فأقال الحكومةَ، وكلَّف علي ماهر بتشكيل وزارة جديدة، واستمَرَّت المظاهرات، وفي 17 محرم اتصل السفيرُ الإنجليزي مايلز لامبسون بالملك فاروق، وأخبره أنَّ الحكومة البريطانية تصِرُّ على تغيير الوزارة القديمة، وتشكيل حكومة وفدية برئاسة مصطفى النحاس، واجتمع المَلِكُ بالشخصيات السياسية، وبينها مصطفى ماهر، وفي صبيحة يوم الثامن عشر سلَّم السفير الإنجليزي لمكتب أحمد حسنين رئيس الديوان الملكي إنذارًا إنجليزيًّا خطيرًا، وينص: إذا لم أسمع قبل الساعة السادسة مساء هذا اليومَ أنَّ مصطفى النحاس قد دُعِيَ لتشكيل الوزارة فإن جلالة الملك فاروق يجِبُ أن يتحَمَّل ما يترتب على ذلك من نتائِجَ، فاجتمع الملك ثانية بزعماء مصر السياسيين، وقرأ عليهم الخطاب الذي أشعرهم بالإهانة جميعًا، فقَرَّروا إرسال احتجاج للسفير ووقَّعوه جميعًا، وأجمعوا على تشكيل وزارة وطنية برئاسة مصطفى النحاس الذي أصَرَّ أن تكون وفديةً خالصةً (يعني: كلهم من حزب الوفد) وهذا ما تريدُه إنجلترا؛ لثقتها بالنحاس كما كانت تثِقُ قبله بسعد زغلول فهي تتظاهَرُ في الظاهر بمخالفتِهم ليكبَروا في أعيُنِ الشَّعبِ ويُصبِحوا أبطالًا قوميِّين!! وفي الشدة تستعينُ بهم للاستفادة من زعامتهم، ورفض السفيرُ ذلك الاحتجاج وأخطر رئيسَ الديوان الملكي أنَّه سيزور الملك بنفسِه في التاسعة مساء، وقبل نصف ساعة من الموعد تحرَّكت دبابات بريطانيا وطوَّقت قصر عابدين والزعماء ما يزالون مجتَمِعين فيه، وجاء السفير ودخل كأنَّه مَلِكُ العالَم لا كأنَّه سفير دولة، دخل متغطرسًا فوثب الجميع وقوفًا وسلَّموا عليه، فجلس، وخَيَّرَ الملك فاروق بين أمرين لا ثالثَ لهما إمَّا التوقيع على وثيقة تنازُلِه عن العرش، وإما التوقيع على تكليف مصطفى النحاس بتشكيلِ الوزارة فورًا، فاختار الملك الخيار الثاني فشَكَّلها من أعضاء حزب الوفد، وأرسل مصطفى النحاس خطابَ شكر للسفير الذي بادله برسالةٍ مماثلة!! وبعد تأليف الوزارة في اليوم نفسِه ذهب السفير وهنَّأ النحاس بين هتافاتِ أفراد حزب الوفد بحياة بريطانيا!!"},{"id":5104,"title":"المعاهدة الثلاثية الإيرانية الروسية البريطانية .","date":["العام الهجري :1361","الشهر القمري : محرم","العام الميلادي :1942"],"text":"بعد أن أجبَرَ الإنجليز رضا شاه بهلوي بالتنازل عن الحكم لابنه محمد بسبب ميوله للألمان عُقِدَت معاهدة ثلاثية بين إيران وبريطانيا وروسيا في 12 محرم / 29 يناير اعترفت بريطانيا وروسيا فيها بوَحدة الأراضي الإيرانية واستقلالها وسيادتها، وتعهدت الدولتان بالدِّفاعِ عن إيران ضِدَّ أي اعتداء، كما احتفظتا بما تراه ضروريًّا من قوات برية وبحرية وجوية على أرض إيران، وتعهَّدتا بسحب قواتهما خلال ستة أشهر بعد انتهاءِ الحرب مع ألمانيا، ولكِنَّ المعاهدة كانت في الواقع عبارةً عن إطلاق يدِ كُلٍّ من هاتين الدولتين في إيران وسياستِها."},{"id":5105,"title":"سقوط مدينة طبرق الليبية في يد الجيش الألماني .","date":["العام الهجري :1361","الشهر القمري : ربيع الأول","العام الميلادي :1942"],"text":"شنَّت القواتُ الألمانية بقيادة المارشال إيروين روميل (رومل ثعلب الصحراء) هجومًا كاسِحًا على مدينة طبرق الليبية -مدينة ساحلية شرق طرابلس- التي كانت قد سقطت في أيدي القوات البريطانية في وقت سابق. لم يكن البريطانيون يتصوَّرون أن يفكِّرَ الألمان في مهاجمة مدينة طبرق التي تتميَّزُ بموقع استراتيجي؛ حيث يَسهُلُ الدفاعُ عنها بسبب وقوعِها على قمة هضبة مرتفعة تجعَلُ من الهجوم عليها مهمةً صعبة. وقد لعبت خطةُ روميل دورًا مهمًّا في ترسيخ هذا الاعتقاد لدى البريطانيين عندما جعل قواتِه تتمركزُ بصورة تعطي انطباعًا بأنَّه يعتزم المرورَ حولَ طبرق وتجاوُزَها دون محاولة اقتحامها، حتى يفاجئ البريطانيين بهجومِه الكاسحِ."},{"id":5106,"title":"هروب رشيد عالي الكيلاني من العراق .","date":["العام الهجري :1361","الشهر القمري : جمادى الأولى","العام الميلادي :1942"],"text":"بعد فَشَلِ حركة رشيد عالي الكيلاني في العراق بمناهضة الاحتلالِ الإنجليزي هرب إلى إيران، فلما دخلَتْها الجيوش البريطانية والروسية فرَّ إلى تركيا، والتقى هناك بعددٍ من الزعماء العرب الذين طالبوه بالعمَلِ السريع من أجل العرب، وحرَّر المجتَمِعون وثيقةً تتضَمَّنُ اعتراف الحكومة الألمانية بأنَّه رئيس وزراء العراق لتكونَ لمحادثاتِه صِفةٌ رسمية، وأن يحصُلَ على تصريح رسمي من الحكومتين الإيطالية والألمانية باحترام استقلال الدول العربية المستقِلَّة، وتأييد استقلال البلدان الواقعة تحت سيطرة الاستعمار البريطاني والفرنسي، ومنها فلسطين، ونَسْف وعد بلفور، كما عليه العمَلُ على الحصول على تصريحٍ رسمي من دول المحور لاحترام اتحاد البلدان العربية الذي سيعملون على تنفيذه بعد الحرب. وقابل الكيلاني وزيرَ الخارجية الألمانية، كما قابل هتلر، وسافر الكيلاني ومفتي فلسطين إلى إيطاليا، وقابلا وزيرَ الخارجية (تشيان) وموسوليني والملك. بعد هزيمة ألمانيا اتجه رشيد الكيلاني إلى سويسرا غير أنها رفضت دخوله، فاتجه إلى بلجيكا، ثم فرنسا، ومن مرسيليا هرب إلى بيروت، ومنها إلى دمشق، ومن دمشق سار إلى الرياض حيث حصل على حقِّ اللجوء السياسي، ورفض الملك عبد العزيز تسليمَه إلى العراق رغم ضغط إنجلترا الشديد، ثم انتقل الكيلاني إلى مصر، ومُنِحَ حق اللجوء السياسي، وبَقِيَ فيها حتى قُضِيَ على العهد الملكي في العراق في 37 ذي الحجة 1377هـ 14 تموز 1958م وأُعلِنَ النظام الجمهوري، فانتقل الى العراق حيث استُقبِل استقبال الأبطال، ما أزعج السفير الإنجليزي الذي طلب من عبد الكريم قاسم قَتْلَه بأي ثمن، وأشيعَ أن الكيلاني يُدبِّر انقلابًا للإطاحة بحكم عبد الكريم قاسم، فألقِيَ القبض عليه، وقُدِّم للمحكمة التي قضت بقتله شنقًا بتهمة العمل لتغيير نظام الحكم لصالح الجمهورية العربية المتحدة، ولم ينفَّذْ فيه حكم القتل، ولكِنْ بقي في السجن، ثم أفرِجَ عنه يوم 1 صفر 1381هـ 14 تموز 1961م، فسافر إلى بيروت، ومنها إلى القاهرة، وبعد زوال حكم عبد الكريم قاسم في 15 رمضان 1383هـ 8 شباط 1963م رجع إلى بغداد، ومنها انتقل إلى بيروت، وبقي فيها إلى أن توفي عام 1385ه"},{"id":5107,"title":"معركة العلمين غرب الإسكندرية بين الحلفاء والألمان  .","date":["العام الهجري :1361","الشهر القمري : شوال","العام الميلادي :1942"],"text":"معركةُ العَلَمين الثانية هي المعركة التي وقعت في العلمين التي تبعد 90 كيلومترًا عن الإسكندرية، وكانت بين القوات الألمانية والإيطالية بقياده إرفين رومل، وبين القوات البريطانية بقيادة برنارد مونتغمري، وتُعَدُّ هذه المعركة من أهم معارك التحَوُّل في الحرب العالمية الثانية، كما أنها كانت من أهم معارك الدبَّابات على مدار التاريخ، وبعد انتصار القوات الألمانية في معارك الصحراء، وكان الفرقُ بين قوات الجانبين يتمثل في: 1/ عدد الجنود: 195,000 جندي بريطاني ومن الحلفاء، مقابل 104,000 جندي من قوات المحور. 2/ الدبابات: 1029 دبابة للبريطانيين مقابل 489 للمحور. 3/ المَدافع: 2311 مِدفَعًا للبريطانيين مقابل 1219 للمحور. 4/ الطائرات: 750 طائرة للبريطانيين مقابل 675 للمحور. إضافة إلى ذلك كان طريق الإمدادات قصيرًا بالنسبة للبريطانيين؛ حيث يَبعُد ميناء الإسكندرية حوالي 110 كم عن الجبهة، ويبعد ميناء السويس حوالي 345 كم عن الجبهة. أما بالنسبة للمحور فإن أقرب ميناء وهو طبرق يَبعُد أكثر من 590 كم عن الجبهة، كما يبعُد ميناء بنغازي أكثر من 1050 كم، ويبعد ميناء طرابلس أكثر من 2100 كم. فضلًا على أن طريق الإمدادات بالنسبة لقوات المحور يتعَرَّض للغارات من جزيرة مالطا، ومن الفدائيين في الصحراء, وأدى النقصُ الكبير في الوَقود عند الألمان بسب إغراق البريطانيين لحاملة النفطِ الإيطالية إلى شَلَلٍ في حركة تقَدُّم الدبَّابات، فاستطاعت القواتُ البريطانية طرْدَ الألمان إلى ليبيا، ثم مِن كُلِّ أفريقيا وصولًا إلى مالطة. وهذه المعركةُ هي التي شهدت بداية الخسائر التي ألحقت بالألمان، التي خَسِرَ فيها الألمان المئاتِ من الدبابات، بالإضافة إلى آليات أخرى وعتاد وذخائر، وكان من الأسباب التي أدت لخسارة الألمان نجاح البريطانيين في فكِّ شفرة الاتصالات الألمانية، وهو خَلَلٌ في القيادة الألمانية التي ظَلَّت تحارب 6 سنوات بدون تغييرِ شَفرةِ الإرسال التي اعتَقَدوا أنها مُعَقَّدة وغير قابلة للكشف. وأصبح الحلفاءُ في ميدان المعركة على عِلمٍ بكل التحركات الألمانية قبل حدوثِها، وهو ما ساعد مونتغمري على اكتشافِ خطة رومل قبل بدء المعركة."},{"id":5108,"title":"تأسيس الأحزاب السياسية في ليبيا. .","date":["العام الهجري :1362","العام الميلادي :1942"],"text":"اتجه النضال في طرابلس نحو العمل السياسي والمطالبة بوحدة أراضيه والاستقلال، فأنشئ النادي السياسي الأول عام 1362هـ / 1943م في مدينة طرابلس، وافتتح فروعًا له في النواحي. وازداد نفوذ النادي حتى تمكَّن بعد عامين من تنظيم مظاهرة كبرى أزالت اللافتاتِ الفاشية من الشوارع. وتقَدَّم بعضُ الذين سبق لهم التعاونُ مع الإيطاليين بعرائض طالبوا فيها بوصاية بريطانية. ونشأ كرَدِّ فعل لهذه الحركة الحزبُ الوطني عام 1364هـ/ 1945م برئاسة (علي بن حسن الفقيه، وسالم بن منتصف. ونَشَر الحزب الوطني ميثاقَه في أول شعبان 1364هـ /1944م دعا فيه إلى مقاومة عودة إيطالية، والعمل على إلغاء القوانين الإيطالية، ومنع هجرة الإيطاليين إلى طرابلس. وعلى الرغم من أهداف الحزب المعتدلة فإن الإدارة العسكرية البريطانية لم تعترفْ به إلا في عام 1365 وضاق بعض الأعضاء وعلى رأسهم رئيس الحزب باعتدال الحزب، فانشَقُّوا وشكلوا في الكتلة الوطنية الحرة، وأرادت الإدارة العسكرية البريطانية إضعاف هذين الحزبين، فشكلت في 10 مايو حزبا ثالثًا من المتعاونين أيام الاحتلال مع الإيطاليين برئاسة سالم المنتصف، وعضوية الشيخ محمد أبو الإسعاد مفتي طرابلس في العهد الإيطالي، وسمي الحزب بالجبهة الوطنية المتَّحدة، وأعضاء الجبهة ينتمون إلى أسر كبيرة عُرِفوا بتعاونهم مع السلطات الإيطالية. وانشَقَّ عن الكتلة الوطنية الحرة ثلاثة أعضاء وشكَّلوا في 16 ديسمبر 1365 حزب الاتحاد المصري الطرابلسي برئاسة علي رجب الذي دعا إلى الاتحاد مع مصر. كذلك ألَّف العمال حزبًا في شوال 1366هـ، وشكَّل صادق بن زارع وكيل الحزب الوطني حزبَ الأحرار في الأول من جمادى الأول 1367هـ!!"},{"id":5109,"title":"مؤتمر الدار البيضاء (أنفا) .","date":["العام الهجري :1362","الشهر القمري : محرم","العام الميلادي :1943"],"text":"عُقِد مؤتمر الحلفاء بعد انتصارِهم على دول المحور في الحرب العالمية الثانية بحضور الرئيس الأمريكي فرانكلن وروزفلت ورئيس الوزراء البريطاني تشرشل، ومَثَّل فرنسا الحرة الجنرال شارل ديغول، واعتذر عن الحضور رئيس الوزراء الروسي جوزيف ستالين؛ لانشغاله بمتابعة القتال الدائر في ستالينغراد. انعقد المؤتمر في فندق أنفا بمدينة الدار البيضاء بالمغرب؛ بهدف رسم الاستراتيجية الأوروبية للحلفاء بعد الحرب، وقد أسفرت المفاوضات عن \"إعلان الدار البيضاء\" المتمثل في مبدأ الاستسلام غير المشروط من قِبَل دول المحور."},{"id":5110,"title":"ليبيا تحت نفوذ الحلفاء .","date":["العام الهجري :1362","الشهر القمري : محرم","العام الميلادي :1943"],"text":"كانت ليبيا تحت الاحتلال الإيطالي، وبعد سنة من بدء الحرب العالمية الثانية بدأت الحربُ بين إيطاليا وإنجلترا في ليبيا ومصر؛ حيث كانت مصر تحت احتلال إنجلترا، وكانت الحرب سِجالًا، حتى استطاعت إنجلترا ومعها حلفاؤها من القوات أن تدخُلَ طرابلس الغرب في تاريخ 17 محرم 1362هـ / 23 يناير وانسحب الإيطاليون بعد أسبوعين، واستمَرَّ تراجع دول المحور المقابلين لدول الحلفاء، فأصبحت ليبيا تحت النفوذ الإنجليزي التابع لدول الحلفاء، وبينما كانت القواتُ الإنجليزية تتقَدَّمُ، وتنهارُ في نفس الوقت المقاومةُ الألمانية الإيطالية كانت القواتُ الفرنسية تتقَدَّمُ من الجنوب، وقد احتلت فران فأصبحت ليبيا تحت دولتين من دول التحالف، وأقامت فرنسا حُكمًا عسكريًّا في فران، كما حصلت أمريكا على قواعِدَ جوية فيها، ثم فَصَلت إنجلترا بين برقة وطرابلس ومَيَّزت في الحكمِ بينهما."},{"id":5111,"title":"استيلاء الحلفاء على مدينة قفصة التونسية .","date":["العام الهجري :1362","الشهر القمري : ربيع الأول","العام الميلادي :1943"],"text":"استطاع الحلفاءُ أن يستولوا على مدينة قفصة التونسية، وذلك بعد طرد القوات الألمانية منها أثناء الحرب العالمية الثانية."},{"id":5112,"title":"قوات الحلفاء تستعيد احتلال المغرب من الألمان .","date":["العام الهجري :1362","الشهر القمري : ذي القعدة","العام الميلادي :1943"],"text":"لَمَّا اندلعت الحرب العالمية الثانية لم تلبث فرنسا كثيرًا حتى انهارت أمامَ ألمانيا وقامت حكومةُ فيشي برئاسة الجنرال بيتان الذي وقَّع الهدنة مع الألمان، وكان مواليًا لهم، وتَبِعَت المغرب حكومةَ فيشي، إلَّا أن السلطان كان بجانب ألمانيا كُرهًا لدول الحلفاء، ثم استطاعت قوات الحلفاء أن تنزل بالمغرب في 11 ذي القعدة 1362هـ / 8 نوفمبر وخرج منها أتباع حكومة فيشي، علمًا أن أسبانيا خلال هذه الفترة احتلت طنجة وسمحت للألمان بالتدريب في المنطقة المراكشية الخاضعة لنفوذها، وقامت مظاهرات تطالِبُ الحكومة باحتلال المحمية الفرنسية من مراكش."},{"id":5113,"title":"تأسيس حزب الاستقلال في المغرب  .","date":["العام الهجري :1363","الشهر القمري : محرم","العام الميلادي :1944"],"text":"نشأ حزبُ الاستقلالِ مع انطلاق الحركة الوطنية التي سعت للتحرُّر من الهيمنة الأجنبية، واستعادة السيادة المغربية. فقام الحزبُ بتقديم عريضة المطالبة بالاستقلال والديمقراطية يوم 11 يناير 1944، ومن هذا التاريخ أصبح الحزبُ الوطني يحمِلُ اسم حزب الاستقلال. وفي 28 يناير تمت حملةُ اعتقالات في صفوف مسيِّري الحزب وقادته وفي مقدِّمتِهم الأمين العام أحمد بلفريج؛ حيث نُفِيَ إلى جزيرة كورسيكا، فعمت البلاد موجةٌ من الإضرابات وسقط عددٌ من القتلى، وخاصة في فاس والرباط وسلا. كما قُدِّم عدد من المعتقلين إلى محكمة عسكرية بتهمة المساس بالأمن العام، ونُفِّذ الحكم فيهم بالقتل. واستمرت سنوات القمع حتى ربيع سنة 1946م حيث تم الإفراج عن المعتقلين كالزعيم علال الفاسي من المنفى بالغابون، وأحمد بلفريج من كورسيكا، وبقية القيادة الاستقلالية، وسُمِحَ بإنشاء بعض الصحف تحت الرقابةِ."},{"id":5114,"title":"الشعب المغربي يعلن وثيقة تطالب بالاستقلال .","date":["العام الهجري :1363","الشهر القمري : ربيع الآخر","العام الميلادي :1944"],"text":"بعد أن خرجت الحكومة الفرنسيى من المغرب أخذت الحركة الوطنية بنشاطها من جديد؛ حيث نشأ حزب الاستقلال في 1363هـ / 27 ديسمبر 1943م وحلَّ محَلَّ الحزب الوطني ونال تأييدًا شعبيًّا واسعًا، ثم التقت الأحزابُ المغربية واتخذت ميثاقًا تضمَّن أهدافَ الشعب المغربي، وفوَّضوا حزب الاستقلال بتقديم المطالب للملك، وإلى المقيم الفرنسي العام ومتابعة مراحل المطالبة بالاستقلال، وكانت أهم بنود الميثاق: المطالبة بالاستقلال التام، ووحدة الأراضي المغربية، وإقرار الملكية الدستورية كنظام للحكم، وغيرها من البنود، وقَدَّم الحزبُ الوثيقةَ للمَلِك وللحاكم الفرنسي العام، فأيَّدها الملِكُ، وأما الحاكم الفرنسي فكان ردُّه القبضَ على زعماء الحزب ونفيَهم إلى الجنوب، ووقعت أحداث دامية وامتلأت السجون."},{"id":5115,"title":"وفاة الشيخ عبد العزيز الثعالبي  .","date":["العام الهجري :1363","الشهر القمري : ذي القعدة","العام الميلادي :1944"],"text":"هو عبد العزيز بن إبراهيم بن عبد الرحمن الثعالبي: زعيمٌ تونسيٌّ، وهو عالم، أديب، كاتب، خطيب، سياسي، صحافي, جزائري الأصلِ، ولِدَ بتونس في 15 شعبان 1293هـ. حَفِظَ القرآن الكريم وأتمَّ الدراسة الأولية في البيت على يد مدرس خاص، ثم دخل مدرسة \"باب سويقة الابتدائية\" في تونس، ثم التحق بجامع الزيتونة وتخرج سنة 1896م، وأخذ يتردَّدُ على المدرسة الخلدونية حتى حصل على الدراسات العليا. وبظهور أولِ حزب لتحرير تونس ومقاومة الاستعمار الفرنسي حزب \"تونس الفتاة\" كان الثعالبي من أوائل من انضم إليه؛ ليؤسِّسَ بعدها الحزبَ الوطني الإسلامي الذي كان يدعو إلى تحرير العالم العربي كله، وقيام الوحدة بين أقطاره. وكان قد كتب وعمل محررًا في صحيفتي \"المبشر\" و\"المنتظر\" إلى أن عطَّلَتْها الحكومة، ثم أصدر جريدة \"سبيل الرشاد\" وكرَّسها للوعظ والإرشاد والدعوة إلى الإصلاح. وبعد سنة عطَّلتْها الحكومة وأصدرت قانونًا قيَّدت به الصحافة. جاهر الثعالبي بطلبِ الحرية لبلاده، فسجنه الفرنسيون، ولَمَّا أُطلِقَ سَراحُه سافر إلى باريس، وزار الأستانة والهند وجاوى، وعاد إلى تونس قُبيلَ سنة 1332ه / 1914م، وقد حلَّ الفرنسيون حزب تونس الفتاة، فعَمِل في الخفاء مع بقايا من أعضائه بالدعاية والمنشورات. وسافر إلى باريس بعد الحرب العالمية الأولى فطبع كتابه \"تونس الشهيدة\" بالفرنسية. واتُّهِم بالتآمر على أمن الدولة الفرنسية، فاعتُقِلَ ونقل سجينًا إلى تونس، وأخلي سبيله بعد 9 أشهر سنة 1920م، فرأس حزب \"الدستور\"، وقد ألفه أنصاره وهو في السجن، وأنشأ مجلة \"الفجر\" في أغسطس 1920, ثم غادر الثعالبي تونس مرة أخرى سنة 1923م متنقلًا بين مصر وسورية والعراق والحجاز والهند، مشاركًا في حركاتها الوطنية، ولا سيما مقاومة الاستعمار الفرنسي، ثم عاد إلى تونس سنة 1937م، فناوأه بعضُ رجال حزبه، فابتعد عن الشؤون العامة إلى أن توفي في تونس. من كُتُبِه: تاريخ شمال إفريقية، وفلسفة التشريع الإسلامي، ومحاضراتُه في جامعة آل البيت ببغداد نُشِرت تباعًا في مجلَّتِها، وتاريخ التشريع الإسلامي، ومذكرات في خمسة أجزاء عن رحلته إلى مصر والشام والحجاز والهند وغيرها، و\"معجزة محمد رسول الله صلَّى الله عليه وسلم\"."},{"id":5116,"title":"جهاد الجزائريين للفرنسيين في الجزائر .","date":["العام الهجري :1364","العام الميلادي :1944"],"text":"لم يتجاوب الشعب الجزائري مع السياسة الفرنسية في جميع الجهاتِ بدون استثناء؛ فلم يكن هناك أثَرٌ في فَرْنَسة الشعب الجزائري المسلِم، وهو ما دفع مخطِّطي السياسة الفرنسية إلى اتهام الجزائريين بأنَّهم شَعبٌ يعيش على هامش التاريخ. حارب الجزائريون سياسةَ التفرقة الطائفية، وقد رأى المصلِحون من أبناء الجزائر في ظِلِّ فَشلِ حركات المقاومة يتقَدَّمُهم الشيخ العالِم عبد الحميد بن باديس أنَّ العمل يجب أن يقومَ في البداية على التربية الإسلامية؛ لتكوين قاعدة صلبة يمكِنُ أن يقومَ عليها الجهاد في المستقبل، مع عدم إهمال الصراع السياسي؛ فتمَّ تأسيس جمعية العلماء المسلمين الجزائريين عام 1350هـ -1931م بزعامة عبد الحميد بن باديس، وعلى الصعيد السياسي بدأ الجزائريون المقاومةَ من خلال التنظيم السياسي الذي خاض هذا الميدانَ بأفكار متعددة، وظهرت عدةُ تنظيمات سياسية، ولَمَّا اشتعلت الحربُ العالمية الثانية ذهب كثيرٌ من الجزائريين إلى الحرب للدفاع عن فرنسا، فدُمِّر الإنتاج في الجزائر وزادت صعوباتُ الحياة؛ لذلك تقدَّموا ببيان إلى السلطات الفرنسية يطالبون فيه بحَقِّ تقرير المصير، تقدَّم به فرحات عباس زعيم حزب اتحاد الشعب الجزائري، ورفضت فرنسا قَبولَ البيان كأساسٍ للمحادثات، فأحدث ذلك ردَّ فِعلٍ عنيفًا عند الجزائريين الذين أصَرُّوا على تمسُّكِهم بالبيان والتزامهم به، ففرض الجنرال كاترو الحاكِمُ العام في الجزائر الإقامةَ الجبرية على فرحات عباس وغيره من الزعماء الجزائريين، فاستغلت فرنسا قيامَ بعض المظاهرات في عدد من المدن الجزائرية وإحراقها للعلم الفرنسي، فارتكبت مذبحةً رهيبة سقط فيها (45) ألف شهيد جزائري، فاتجه الجزائريون بعد تلك المذابح البَشِعة إلى العَمَل السري، وكان يتم اختيارُ أفراد هذا العمل من خيرة الشبانِ خُلقًا وأدبًا، فلم يكن يُسمَحُ بضَمِّ المُلحِدين أو الفوضويين، وبدأت خلايا المجاهِدين تنتشر في الجزائر طولًا وعرضًا، وأحيطت أساليبُ العمل بسريةٍ تامةٍ؛ مما كان له أكبر الأثر في نجاح الثورة، واستطاع هذا التنظيمُ الدعايةَ للثورة في صفوف الشعب وإعداده للمعركة القادمة."},{"id":5117,"title":"إنشاء جامعة الدول العربية .","date":["العام الهجري :1364","العام الميلادي :1944"],"text":"بدأت سلسلة من المشاورات الثنائية بين مصر من جانب، وممثِّلي كلٍّ من العراق وسوريا ولبنان والمملكة العربية السعودية والأردن واليمن من جانب آخرَ، وهي المشاورات التي أسفرت عن تبلور اتجاهين رئيسين بخصوص موضوع الوحدة العربية: الاتجاه الأول يدعو إلى ما يمكِنُ وصفه بالوَحدة الإقليمية الفرعية وقوامها سوريا الكبرى أو الهلال الخصيب. والاتجاه الثاني يدعو إلى نوعٍ أعَمَّ وأشمل من الوحدة يظلِّلُ عموم الدول العربية المستقلة، وإن تضمَّنَ هذا الاتجاه بدوره رأيين فرعيين: أحدهما يدعو لوحدة فيدرالية أو كونفدرالية بين الدول المعنية، والآخر يطالب بصيغةٍ وسط تحقِّقُ التعاون والتنسيق في سائر المجالات وتحافِظُ في الوقت نفسه على استقلال الدول وسيادتها. وعندما اجتمعت لجنةٌ تحضيرية من ممثلين عن كلٍّ مِن سوريا ولبنان والأردن والعراق ومصر واليمن (بصفة مراقب) في الفترة 25/9 إلى 7/10/ 1944م رجحت الاتجاه الداعي إلى وحدة الدول العربية المستقلة بما لا يمَسُّ استقلالها وسيادتها. كما استقرت على تسمية الرابطة المجسِّدة لهذه الوحدة بـ \"جامعة الدول العربية\" وآثرَتْه على مسمى \"التحالف\" و\"الاتحاد\". وعلى ضوء ذلك تم التوصلُ إلى بروتوكول الإسكندرية الذى صار أوَّلَ وثيقة تخصُّ الجامعة، والذي نص على المبادئ الآتية: - قيام جامعة الدول العربية من الدول العربية المستقلةِ التي تقبَلُ الانضمام إليها، ويكون لها مجلِسٌ تمثل فيه الدول المشتركة في الجامعة على قدم المساواة. مهمةُ مجلس الجامعة هي: مراعاة تنفيذ ما تبرِمُه الدول الأعضاء فيما بينها من اتفاقياتٍ، وعَقدُ اجتماعات دورية لتوثيق الصلات بينها، والتنسيق بين خططها السياسية تحقيقًا للتعاون فيما بينها، وصيانة لاستقلالها وسيادتها من كل اعتداء بالوسائل السياسية الممكِنة، والنظر بصفةٍ عامة في شؤون البلاد العربية. قرارات المجلِس مُلزِمة لِمن يقبلُها فيما عدا الأحوال التي يقع فيها خلافٌ بين دولتين من أعضاء الجامعة، ويلجأ الطرفان إلى المجلسِ لفَضِّ النزاع بينهما. ففي هذه الأحوال تكون قراراتُ المجلس مُلزِمة ونافذة. لا يجوزُ الالتجاء إلى القوة لفَضِّ المنازعات بين دولتين من دول الجامعة، كما لا يجوزُ اتِّباع سياسة خارجية تضرُّ بسياسة جامعة الدول العربية، أو أية دولة من دولها. يجوزُ لكل دولة من الدول الأعضاء بالجامعة أن تعقِدَ مع دولة أخرى من دول الجامعة أو غيرها اتفاقاتٍ خاصةً لا تتعارَضُ مع نصوص هذه الأحكام وروحها. وأخيرًا الاعترافُ بسيادة واستقلال الدول المنظمة إلى الجماعة بحدودها القائمة فعلًا. كما اشتمل البروتوكول على قرار خاص بضرورة احترام استقلال لبنان وسيادته، وعلى قرارٍ آخَرَ باعتبار فلسطين ركنًا هامًّا من أركان البلاد العربية، وحقوق العرب فيها لا يمكن المساسُ بها من غير إضرارٍ بالسلم والاستقلال في العالم العربي، ويجِبُ على الدول العربية تأييدُ قضية عرب فلسطين بالعمل على تحقيقِ أمانيهم المشروعة، وصون حقوقهم العادلة!! وأخيرًا نص في البروتوكول على أن (تُشكَّل فورًا لجنةٌ فرعية سياسية من أعضاء اللجنة التحضيرية المذكورة للقيام بإعداد مشروع لنظام مجلس الجامعة، ولبحث المسائل السياسية التي يمكن إبرامُ اتفاقيات فيها بين الدول العربية) ووقع على هذا البروتوكول رؤساءُ الوفود المشاركة في اللجنة التحضيرية، وذلك في 7/10/1944 باستثناء السعودية واليمن اللتين وقعتاه في 3/1/1945 و5/2/1945 على التوالي بعد أن تمَّ رفعُه إلى كلٍّ من الملك عبد العزيز آل سعود، والإمام يحيى حميد. ولقد مثَّلَ هذا البروتوكول الوثيقةَ الرئيسية التي وُضِع على أساسها ميثاقُ جامعة الدول العربية، وشارك في إعداده -أي الميثاق- كلٌّ من اللجنة السياسية الفرعية التي أوصى بروتوكول الإسكندرية بتشكيلِها، ومندوبي الدول العربية الموقِّعين على بروتوكول الإسكندرية، مضافًا إليهم مندوب عام كلٍّ من السعودية واليمن، وحضر مندوب الأحزاب الفلسطينية كمراقب. وبعد اكتمال مشروع الميثاق كنتاج لستة عشر اجتماعًا عقدتها الأطراف المذكورة بمقَرِّ وزارة الخارجية المصرية في الفترة بين 17/2 و3/3/1945 أُقِرَّ الميثاق بقصر الزعفران بالقاهرة في 19/3/1945 بعد إدخال بعض التنقيحات عليه. وفى 22/3/1945 تم التوقيعُ على ميثاق جامعة الدول العربية من قِبَل مندوبي الدول العربية عدا السعودية واليمن اللتين وقَّعتا على الميثاق في وقت لاحق. وحضر جلسة التوقيع ممثِّلُ الأحزاب الفلسطينية، وأصبح يوم 22 مارس من كل عامٍ هو يومَ الاحتفال بالعيد السنوي لجامعة الدول العربية."},{"id":5118,"title":"تأسيس الهيئة العربية العليا لفلسطين في مصر .","date":["العام الهجري :1364","العام الميلادي :1944"],"text":"عندما انتقل الحاج أمين الحسيني مفتي القدس من باريس إلى مصر شكَّل الهيئةَ العربية العليا لفلسطين برئاسته؛ حيث نظَّم الحركةَ الوطنية الفلسطينية تنظيمًا حديثًا، وقرَّر إعداد الشعب لخَوضِ الكفاح المسلَّح ضِدَّ الصهاينة والإنجليز، وألَّف لجنة من قادة المجاهدين الفلسطينيين وبعض الضبَّاط السوريين والعراقيين والمصريين لوضع الخطط وتحديد المطلوب من الأسلحة والمعَدَّات للجهاد الذي كان أوانه قد اقترب بعد بروز فكرة التقسيم من جديد في الأوساط الأمريكية والبريطانية والصهيونية ومحيط الأمم المتحدة، كما أعاد تنظيمَ جيشِ الجهاد المقدَّس، وأسند قيادته إلى عبد القادر الحسيني، وأنشأ المفتي كذلك منظمة الشباب الفلسطيني التي انصهرت فيها منظَّمات الفتوَّة والجوالة والكشافة، وأسند قيادتها للمجاهد الصاغ محمود لبيب أحد قادة الحركة الإسلامية بمصر، وكلَّفه بمهمة تدريب الشباب على القتال."},{"id":5119,"title":"إلقاء أمريكا القنبلتين الذريتين على هيروشيما وناغازاكي .","date":["العام الهجري :1364","الشهر القمري : شعبان","العام الميلادي :1945"],"text":"حصلت الكارثة الذَّرِّية بتاريخ 6 آب/ أغسطس عام 1945م عندما أمرت حكومة الرئيس الأمريكي هاري ترومان بإلقاء القنبلة الذرية على اليابان. عندما رفضت اليابان الإنذارَ الأمريكي بالاستسلام غير المشروط، فأغار الطيرانُ الأمريكي على وسط مدينة هيروشيما، وألقى القنبلةَ الذرية المعبَّأة باليورانيوم والتي كانت تزِنُ أكثَرَ 4.5 أطنان من على ارتفاع 1980 قدمًا عند الساعة الثامنة والربع من صباح ذلك اليوم، عندما كان معظم سكان المدينة في الشوارع متَّجِهين لأعمالهم؛ لتتحول المدينة بعد دقائق قليلة إلى كومة من اللهب والرماد، وبمحيط انفجار بلغ 13كم2، وذلك في أكبر تفجير عالمي كان معروفًا حتى ذلك الوقت!! وأسفرت هذه الكارثة عن سقوط نحو 140 ألف قتيل؛ نحو 30 % من عدد السكان، ومثلهم من الجرحى الذين مات معظمُهم لاحقًا متأثرين بالتسمم الإشعاعي الناتج عن التفجير، فيما وصل ارتفاع سحب الدخان الناتج عن الانفجار إلى 1000 متر فوق سطح المدينة، وبعد مرور نحو ساعتين على الانفجار سقطت أمطارٌ سوداء شحمية في أماكِنَ متفرقة من المدينة كانت بفعل اختلاط أبخرة الماء مع المواد المشِعَّة! ورغم إلقاء القنبلة الذرية على هيروشيما رفضت حكومةُ اليابان بقيادة الإمبراطور هيرو هيتو الاستجابةَ للإنذار الذي وجَّهه لها ترومان بالاستسلامِ، فأعطى الأخيرُ أوامره بإلقاء قنبلة أخرى في 9 أغسطس على مدينة ناغازاكي اليابانية بعد ثلاثة أيام من قنبلة هيروشيما؛ حيث شملت هذه الكارثة تدميرَ مساحة 6 كم2، ومقتل نحو 40 ألف ياباني، و70 ألف جريح، وفي النهاية لم تجِدْ طوكيو خيارًا أمامها سوى الاستسلام بعد الخراب الذي لحِقَ بها!! فاستسلمت للحلفاء في 14 أغسطس 1945م، ثم وقَّعَت وثيقة الاستسلام في الثاني من شهر أيلول/ سبتمبر في نفس العام. ولم تقتصر أضرار القنبلة الذرية التي أُلقِيَت على هيروشيما وناغازاكي على وقتِ حدوث الانفجار، بل امتدت إلى سنين طويلة في مستقبل الأجيال؛ بسبب استمرار التأثيرات الضارَّة الناجمة عن التلوُّث الإشعاعي؛ فمن لم يقتل ساعة الانفجار مات بعد ذلك بسبب تأثيرات الإشعاع الضارة التي تشيرُ الدراسات إلى أن تأثيرها مستمِرٌّ حتى اليوم!! وتتسبَّبُ في الإصابة بالسرطان، وإصابة المواليد بعيوب خِلقية. وقد قامت إحدى الجامعات اليابانية بدراسةِ آثار الإشعاع الناجم عن القنبلة، فتبين للباحثين أنَّه بين كل 4 مواليد من أبناء الجيل الأوَّل لضحايا الكارثة يصابُ واحد منهم بعيوب خِلقية، ولا يستطيع أحَدٌ في الوقت الحالي أن يقرِّرَ إلى أي حدٍّ مِن الأجيال سيستمر توارثُ آثارِ الإشعاع، كما أدت الكارثة إلى أضرار كبيرة على البيئة والطبيعة!!"},{"id":5120,"title":"قيام حكومة إسلامية في أندونيسيا، ومؤتمر جاكرتا الإسلامي .","date":["العام الهجري :1364","الشهر القمري : رمضان","العام الميلادي :1945"],"text":"ما إن انتهت الحربُ العالمية الثانية، وكانت اليابان قد هُزِمَت، بعد أن أُلقِيَت عليها القنبلةُ الذَّرية الأمريكية، وكانت اليابان قد احتَلَّت فيما احتلَّتْه جزرَ أندونيسيا، وبعد يومين من الهزيمة اليابانية أُعلِنَ عن قيام حكومة أندونيسية برئاسة أحمد سوكارنو، ونائبه محمد حتا، وأخذت الحكومةُ تعمَلُ على الحيلولة دون عودة المحتلين الهولنديين، فتحركوا لنزعِ السلاح من اليابانيين، وأُسِّسَت حكومة وسط جزيرة جاوه، عرفت باسم دار الإسلام، وأطلقوا على عاصمتِهم اسمَ المدينة المنورة، وجعلوا من اللغة العربية لغةً رسمية للبلاد، وعَمِلوا على تطبيق الشريعة برئاسة زين العارفين، لكِنَّ الحلفاء أصدروا أوامِرَهم لليابانيين بإبقاء السلاح معهم ريثما تصِلُ قوات التحالف، ثم حضر الإنجليز ومعهم الهولنديون الذين أخذوا باعتقالِ الزعماء الأندونيسيين، ولَمَّا بدا للسكان نواياهم الاستعمارية الجديدة بدأ القتالُ بينهم، وتداعى المسلِمون من أرجاء أندونيسيا لعقد اجتماعٍ بعد أن وجدوا أنَّ الحركات الاستعمارية الصَّليبية والشيوعية الإلحادية والمحلية العلمانية ومَن معهم للمصلحةِ: كُلُّهم يقفون ضدَّ المسلمين. عُقِدَ لقاءٌ في جاكرتا في ذي الحجة 1364هـ / نوفمبر، وكان أكبَرَ مؤتمر إسلامي، وتم الاتفاق على الانضواء في تنظيمٍ إسلاميٍّ واحدٍ سُمِّي مجلس شورى مسلمي أندونيسيا، وعرف باسم ماشومي، وأيقن الاستعماريون قوةَ مِثلِ هذا التحالف، فأخذوا في التفاهم مع العلمانيين الذين عُرِفوا باسم الوطنيين، ونتج عنه توقيعُ اتفاق لنيجار دجاتي الذي اعترفت هولندا بموجِبِه بسلطة الحكومة القائمة الفِعلية على جزر جاوه وسومطرة ومادورا فقط."},{"id":5121,"title":"إصدار الوثيقة الأولى لإنشاء جامعة الدول العربية .","date":["العام الهجري :1364","الشهر القمري : شوال","العام الميلادي :1945"],"text":"في أعقابِ الحرب العالمية الثانية اتَّفَق قادة خمس دول عربية في مدينة الإسكندرية بمصر على إنشاء منظمةٍ تربطُ العربَ بعضهم ببعض، فتمَّ إنشاء جامعة الدول العربية في العام التالي. وكلُّهم توافقوا على ما يسمى اليوم ببروتوكول الإسكندرية. وكان الهدفُ الرئيسي لهذه المنظمة هو تعزيزَ العلاقات بين الدول العربية والمشاركة بفعاليةٍ في تنسيق الخطَطِ السياسية، والسياسة الخارجية من دونِ التدخُّلِ في استقلاليتها، وإيجاد الوسائل المناسِبة للحماية في حالة العدوان على دولة أو سيادتها. شمِلَ الاجتماع الذي عُقِد في الإسكندرية خمسَ لجان مع ممثِّلي الأعضاء المستقبليين في جامعة الدول العربية من البلدان في الشرق الأوسط وشمال إفريقيا. وهذه الدول: مصر، والعراق، وسوريا، والأردن، ولبنان. وقد احتوى البروتوكول عددًا من المبادئ، ووقَّع عليه رؤساء الوفود المشارِكة في اللجنة التحضيرية، وذلك في 7 أكتوبر 1944م."},{"id":5122,"title":"استقلال سوريا ولبنان .","date":["العام الهجري :1365","العام الميلادي :1945"],"text":"بعد أن انتهت الحرب العالمية وانتصر الحلفاء أرسل ممثِّل فرنسا مذكرةً إلى حكومتي سوريا ولبنان؛ مذكرةً تضَمَّنت طلباتٍ متعسفة تتعارضُ مع السيادة الوطنية، وكان فيها إصرارٌ شديد لعقد اتفاقيات تجعل لفرنسا مكانًا متميزًا وأوضاعًا استراتيجيةً، فلم ترضَخِ الحكومتان لهذه الضغوط، وبدأ الهياجُ الشعبي، ثم قام الفرنسيون بواسطةِ جنود سنغاليين بقتل رجال الشرطة المكلَّفين بحراسة مبنى مجلس النواب، ثم وُجِّهَت المدفعية إلى مبنى مجلس النواب، وقام الطيران الفرنسي بقَصفِ قلعة دمشق، ثم تدخَّلت بريطانيا لوقفِ إطلاق النار وسَحْب القوات الفرنسية إلى الثكنات، حتى لم يبق من القوات الفرنسية عمليًّا إلا القوات الخاصة، وكانت سوريا ولبنان قد بدأتا بموجِبِ صَكِّ الانتدابِ بتسلُّم ما سمي بالمصالح المشتركة التي كانت تدارُ عن طريق المفوَّض السامي الفرنسي مثل الجمارك وسكك الحديد والدفاع المدني، حتى تم تسلُّم المصالح عام 1944م، ثم تم جلاء القوات الفرنسية نهائيًّا عن سوريا ثم عن لبنان."},{"id":5123,"title":"مقاطعة ساراواك (ماليزيا) تصبح مستعمرة بريطانية .","date":["العام الهجري :1365","العام الميلادي :1945"],"text":"أصبحت مقاطعةُ ساراواك (التابعة لماليزيا) عام 1365هـ مُستعمرةً تابعة للتاج البريطاني؛ حيث تنازل حاكِمُ الولاية عن سلطته على الولاية إلى التاجِ البريطاني."},{"id":5124,"title":"إعلان ألبانيا جمهورية شعبية بعد إلغاء الملكية .","date":["العام الهجري :1365","الشهر القمري : صفر","العام الميلادي :1946"],"text":"بعد استقرارِ الأحوال في ألبانيا، أُجريت انتخابات عامة وعلى إثر فوز أنور خوجا بها أُعلنت ألبانيا جمهوريةً شعبية، وأُلغيت الملكية رسميًّا، وأصبح أنور خوجا رئيسًا للبلاد، وما إن أمسك بمقاليد الأمور حتى بادر إلى قطعِ العلاقات مع كلٍّ مِن بريطانيا والولايات المتحدة الأمريكية. وكان أنور خوجا من المعجَبين بستالين: دكتاتور الاتحاد السوفيتي الشيوعي، فوقف إلى جانِبِه حين نشب خلافٌ سنة 1367هـ / 1948م بينه وبين \"تيتو\" الرئيس اليوغسلافي، على الرغم من مساندة الحزب الشيوعي اليوغسلافي للشيوعيين الألبان في أثناء الاحتلال الإيطالي لبلادِهم، غير أنَّ هذا التأييد الذي أبداه أنور خوجا للسياسة السوفيتية توقَّفَ بعد وفاة ستالين سنة 1373هـ / 1953م، وانتهاج خلفائِه سياسةً مغايرة؛ فتحوَّل التأييد إلى عداءٍ مُستحكم، انتهى بقطع العلاقات بين البلدين في سنة 1381هـ / 1961م، وكان من الأسباب التي أدَّت إلى هذه النتيجة وقوف \"خوجا\" إلى جانب الصين في صراعها الأيديولوجي المذهبي ضِدَّ الاتحاد السوفيتي، ثم أعقب ذلك انسحابُ ألبانيا من حلف \"وارسو\" سنة 1388هـ / 1968م، والتوقُّف عن المشاركة في \"الكوميكون\"، وهو المجلس المشترك لمساعدة دولة الكتلة الشرقية."},{"id":5125,"title":"سيطرة الشيوعيين على ألبانيا .","date":["العام الهجري :1365","الشهر القمري : صفر","العام الميلادي :1946"],"text":"بَقِيَت ألبانيا تحت الاحتلالِ الإيطالي نحو أربع سنوات، ثم وقَعَت تحت الاحتلال الألماني، لكِنَّها ما لبثت أن انسحبت منها بعد عام واحد، وكانت الهزائِمُ قد توالت عليها، ولم تجد مفرًّا من تَرْك ألبانيا؛ فتسَلَّم الحكمَ فيها جبهةُ التحرير القومية بقيادة الشيوعيين، وكانت هذه الجبهةُ قد تأسَّست في سنة 1360هـ / 1941م، وقادت حركةَ المقاومة ضِدَّ الغزو الإيطالي والألماني. ولما وضعت الحربُ أوزارَها، وعاد الهدوء إلى ألبانيا؛ أُجريت انتخاباتٌ في سنة 1365هـ أسفرت عن فوز \"أنور خوجا\" زعيم الحزب الشيوعي الألباني، وأُعلِنَت ألبانيا جمهوريةً شعبية. حكم خوجا بلادَه بالحديد والنار، وفَرَض عليها عزلةً صارمة. وحارب الأديانَ كُلَّها، وأصدر على مدارِ سنواتِ حُكمِه العديدَ من القرارات التي هدفت إلى تجريم ممارسة الشعائر الدينية، وإلى تحويل المساجِدِ إلى متاحفَ ومخازن ومتاجر ومراقِصَ!! وظل أنور خوجا يحكُمُ ألبانيا إحدى وأربعين سنة حتى تُوفي في 20 رجب 1405هـ / 11 إبريل 1985م، عن عمر يناهز السابعة والسبعين، وخلفه \"رافر عليا\" الذي قام بعددٍ من الإصلاحات، بعد أن هبَّت رياح الحرية في أوربا الشرقية، وشَمِلَت هذه الإصلاحات التي قام بها رفعَ القيود على ممارسة الألبان لشعائِرِهم الدينية، وإعادة فتحِ المساجدِ التي أُغلِقَت من قَبلُ، والموافقة على حرية السفر، والاعتراف بحقِّ كُلِّ مواطن في الحصول على جواز سفر. واتجهت ألبانيا بعد ذلك إلى الانفتاحِ على أوربا والتقارب مع دولها، ورفع القيود عن الاستعمار الأجنبي، وإنهاء الحظر على التعددية الحزبية."},{"id":5126,"title":"مبادرة الملك الأردني عبد الله الأول للدعوة إلى إحياء مشروع \"سوريا الكبرى\" .","date":["العام الهجري :1365","الشهر القمري : ربيع الآخر","العام الميلادي :1946"],"text":"بعد أن منحت بريطانيا شرقَ الأردن حَقَّ الاستقلال -بموجِبِ صَكِّ الانتداب- دعا ملِكُ الأردني عبد الله الأول إلى إحياءِ مشروع \"سوريا الكبرى\" الذي يضمُّ الأردن وسوريا ولبنان، إلَّا أن المجلس النيابيَّ السوري رفض هذا المشروع في سبتمبر 1947م."},{"id":5127,"title":"معاهدة بريطانيا الأردن الثانية واستقلال الأردن  .","date":["العام الهجري :1365","الشهر القمري : ربيع الآخر","العام الميلادي :1946"],"text":"بعد أن قضى الانتدابُ البريطاني في شرق الأردن 25 سنة من 1921م مَنَحت بريطانيا شرقَ الأردن حقَّ الاستقلال بموجِبِ صَكِّ الانتداب -الذي يقضي ببقاء شرق الأردن تحت الحكم البريطاني 25 سنة- تمَّ إبرامُ المعاهدة البريطانية الأردنية الثانية في 22 مارس التي تعترف باستقلالِ شرقِ الأردن. وتم إعلانُ استقلال إمارة شرق الأردن، وإعلانُ قيام المملكة الأردنية الهاشمية، ويكون المَلِكُ عبد الله الأول بن الحسين ملكًا عليها يوم 25/5/1946، إلَّا أن الجيش الأردني بقِيَ تحت قيادة الضباط البريطانيين على رأسهم (أبو حنيك) غلوب باشا حتى عام 1957م."},{"id":5128,"title":"إعلان قيام حزب الأمة السوداني .","date":["العام الهجري :1365","الشهر القمري : ربيع الآخر","العام الميلادي :1946"],"text":"أسَّس عبد الرحمن المهدي زعيمُ جماعة الأنصار المهدية حزبَ الأمة السوداني كامتدادٍ سياسي للحركة المهدية في السودان، وكان شعارُه \"السودان للسودانيين\" وتحقيق المطامح الوطنية في الاستقلال عن مصر، والتخلُّص مما يُعرَف بدولتي الحُكمِ الثنائي (مصر وبريطانيا)، وبناء الدولة السودانية المستقلَّة على أُسُس المساواة والحرية والعدل، وكان حزبُ الأمة السوداني يطالِبُ باستقلال السودان عن بريطانيا ومصر رافعًا راية الاستقلال الكامِل عن الدولتين، وسُمِّي مؤيِّدوه بالاستقلاليين."},{"id":5129,"title":"إطلاق اسم الأردن رسميًّا على إمارة شرق الأردن .","date":["العام الهجري :1365","الشهر القمري : جمادى الأولى","العام الميلادي :1946"],"text":"تمَّ إطلاق اسم الأردن رسميًّا على إمارة شرق الأردن، وقد تأسَّست هذه الإمارة سنة 1920 تحت الانتدابِ البريطاني بموجِبِ صَكِّ الانتداب الذي وقَّعَه عبد الله بن الحسين أمامَ وزير المستعمرات البريطاني تشرشل مقابِلَ تنصيبِه مَلِكًا على شرق الأردن، وقد حَصَلت الإمارة على استقلالِها في 25 مايو 1946م، واعتُبِرَ ذلك اليوم عيدًا للاستقلال، وتألَّفت في هذه الإمارة 18 وزارة قبل إعلانها مملكةً تحت اسم المملكة الأردنية الهاشمية."},{"id":5130,"title":"مؤتمر القمة العربي غير العادي (قمة أنشاص) .","date":["العام الهجري :1365","الشهر القمري : جمادى الآخرة","العام الميلادي :1946"],"text":"يعتبَرُ أول مؤتمر قمة عربي عُقِدَ هو مؤتمر قمة أنشاص هذا العام من 29 إلى 30 يوليو، (وهو مؤتمر قمة غير عادي) عُقِدَت هذه القمَّةُ بدعوة من الملك فاروق في قصرِ أنشاص بالشرقية في مِصرَ، وضَمَّت الدولَ السبع المؤسِّسة للجامعة العربية (22 آذار 1945م)، وهي: مصر، وشرق الأردن، والسعودية، واليمن، والعراق، ولبنان، وسوريا، وطالب المجتَمِعون بالحفاظ على عروبة فلسطين، ووقْف الهجرة اليهودية إليها، ولم يَصدُرْ عن مؤتمر القمة بيانٌ ختامي، وإنما مجموعةٌ من القرارات أهمها: - مساعدة الشعوب العربية المستعمَرة على نيل استقلالها.- قضية فلسطين قلبُ القضايا القومية، باعتبارها قطرًا لا ينفصل عن باقي الأقطار العربية.- ضرورةُ الوقوف أمامَ الصهيونية باعتبارها خطرًا لا يداهمُ فلسطين وحسب، وإنما جميع البلاد العربية والإسلامية.- الدعوةُ إلى وقف الهجرة اليهودية وقفًا تامًّا، ومَنْع تسرب الأراضي العربية إلى أيدي الصهاينة، والعمل على تحقيق استقلال فلسطين.- اعتبارُ أي سياسة عدوانية موجَّهة ضد فلسطين تأخذُ بها حكومتا أمريكا وبريطانيا هي سياسة عدوانية تجاه كافة دول الجامعة العربية.- الدفاع عن كيان فلسطين في حالة الاعتداء عليه.- مساعدة عرب فلسطين بالمالِ وبكل الوسائل الممكنة.- ضرورة حصول طرابلس الغرب على الاستقلال.- العمل على إنهاض الشعوب العربية وترقية مستواها الثقافي والمادي؛ لتمكنها من مواجهة أي اعتداء صهيوني داهم!!"},{"id":5131,"title":"إصدار مجلس السوفييت الأعلى قرارا بإلغاء \"جمهورية القرم\" .","date":["العام الهجري :1365","الشهر القمري : رجب","العام الميلادي :1946"],"text":"أصدر مجلِسُ السوفييت الأعلى قرارًا بإلغاء \"جمهورية القرم\" ذات الاستقلال الذاتي؛ بذريعة خيانة شعب القرم للسوفييت أثناء الحرب العالمية الثانية، وتعاونهم مع الألمان. وشِبهُ جزيرة القرم جمهوريةٌ ذاتُ حكم ذاتي تقع حاليًّا في أوكرانيا، ويحيط بها البحرُ الأسود من الجنوب والغرب، وبحر أزوف من الشرق، وتبلغ مساحتها 27 ألف كم، وعدد سكانها 2.5 مليون نسمة. وقد تمكَّن الروسُ من غزوها في سنة 1198ه - 1783م في عهد كاترين الثانية إمبراطورة روسيا المتعصبة للنصرانية. وهكذا فقَدَت دولةُ تتار القرم حريتَّهَا، وبدأ الاضطهاد الديني لمسلِمي القرم، وطَرَد الروس من شبه جزيرة القرم نِصفَ مليون نسمة، وصدرت عدةُ قوانين تحَرِّم الدعوةَ إلى الإسلام، وظَلَّ هذا الغَبنُ مفروضًا على التتار المسلمين طيلةَ قرن وربع، ولَمَّا صدر قانون حرية التعبُّد أعلن التتار الدعوةَ الإسلامية، بعد أن كانوا يمارِسونَها سِرًّا بين جيرانهم، وزاد عدد الداخلين في الإسلام. ونَشِط تتار القرم في استعادة كيانهم منذ صدور قانون حرية العقيدة في روسيا القيصرية في سنة 1323ه - 1905م، فلما استولى الشيوعيُّون على حكم روسيا في سنة 1336ه - 1917م، وقاوم المسلِمون من تتار القرم الخضوعَ لهم، لجأ السوفييت الشيوعيون إلى حربِ التجويعِ والحصار، وقد نشرت جريدةُ أزفسيتا السوفيتية جانبًا من حرب التجويعِ التي فُرِضَت على تتار القرم، واستمَرَّت طيلة عام 1922، ومات في هذه المجاعة أكثر من ستين ألف مسلمٍ من تتار القرم، وقُتِلَ مئة ألف، وحُكِمَ على خمسين ألفا بالنفي!! وهكذا قَدَّم تتار القرم العديدَ من الضحايا قبل الاستسلام لحكمِ السوفييت، وأُعلِنَ قيام جمهورية القرم السوفييتية، وخضعت للحكم الذاتي. وفي سنة 1347ه - 1928م اتَّجه الروس إلى جَعلِ شبه جزيرة القرم موطِنًا ليهود روسيا، واحتجت حكومةُ القرم، فأُعدِمَ رئيسُ جمهوريتها وأعضاءُ حكومته، ونفيَ أربعون ألف مسلم من القرمِ إلى سيبيريا (تشمل منطقة آسيا الشمالية). وبعد قرار إلغاء \"جمهورية القرم\" شُرِّدَ تتارُ القرم وأُرغِمَ أهلُها على الهجرة الإجبارية إلى سيبيريا وآسيا الوسطى خصوصًا في أوزبكستان، وهرب مليون وربع مليون منهم إلى تركيا وأوروبا الغربية، وبعضهم إلى بلغاريا ورومانيا، وأُعدم الكثير، ولم يبقَ مِن خمسة ملايين مسلم من تتار القرم غير نصف مليون، وهدم السوفييت ألفًا وخمسمائة مسجد في شبه جزيرة القرم، والعديد من المعاهد والمدارس!! وفي سنة 1387ه - 1976م قرَّر مجلس السوفييت براءةَ تتار القرم من تهمة التعاون مع الألمان بعد تشريدِ شَعبٍ كاملٍ، وإلغاء جمهوريته؛ نتيجةَ تهمة باطلة أُلصِقَت به، وطالب تتار القرم بالعودةِ إلى وطنهم!!"},{"id":5132,"title":"تأسيس حزب الاتحاد الديمقراطي في الجزائر .","date":["العام الهجري :1365","الشهر القمري : رمضان","العام الميلادي :1946"],"text":"أسَّس الجزائريُّ فرحات عباس حزبَ الاتحاد الديمقراطي للبيان الجزائري، بعد أن قَمَعت السلطاتُ الفرنسية بالجزائر كلَّ الأحزاب والمنظمات السياسية. وكانت للحزب صحيفةٌ اسمُها التفاهم تصدُرُ باللغة الفرنسية وتنطِقُ باسم الحزب. كان الحزبُ يَعرِض مساوئَ الحكم الفرنسي في الجزائر، ويطالبُ بالمساواة في الحقوق والمعاملة بين الفرنسيين والجزائريين. ولم يكن يؤيِّدُ الكفاحَ المسلَّح أو الانفصال عن فرنسا. توقَّف نشاط الحزب عند اندلاع الثورة الجزائرية في نوفمبر 1954م، وانضم رئيسُه فرحات عباس إلى الثورة الجزائرية سنة 1956م."},{"id":5133,"title":"اندلاع أعمال عنف بين الهندوس والمسلمين في مدينة كالكوتا الهندية .","date":["العام الهجري :1365","الشهر القمري : رمضان","العام الميلادي :1946"],"text":"اندلعت أعمالُ عُنفٍ بين الهندوس والمسلمين في مدينة كالكوتا الهندية، وامتدَّت أعمال العنف إلى عددٍ من المدن الأخرى، واستمرَّت الاشتباكات لمدة 3 أيام متواصلة أسفرت عن سقوط 7 آلاف قتيل!"},{"id":5134,"title":"معاهدة صدقي بيفن بين مصر وإنجلترا ومظاهرات تطالب بالجلاء .","date":["العام الهجري :1365","الشهر القمري : ذي الحجة","العام الميلادي :1946"],"text":"قام إسماعيل صدقي بتشكيل حكومة وزارية في مصرَ، هو رئيسها، وقرَّرت في 16 ربيع الثاني 1356هـ / 19 آذار 1946م تأليفَ لجنة للمفاوضات وعرضت على حزب الوفد الاشتراكَ، لكِنَّه لم يشترِكْ لعدم الاتفاق على عدد النواب، وكان رأسُ الوفد البريطاني أرنست بيفن وزير الخارجية، وأخفق الوفدُ في المفاوضات، ثم سافر إسماعيل صدقي مع إبراهيم عبد الهادي وزير الخارجية إلى لندن، ووضع مشروع معاهدة، وأخذت إنجلترا تماطِلُ بالتوقيع رسميًّا، ولكِنَّها وقَّعت في النهاية، فعاد إسماعيل صدقي ورفيقه يحمِلان مشروع المعاهدة وعُرِفَت باسم صدقي بيفن، ونَصَّت على إنهاء العمل بمعاهدة 1936، وجلاء القوات البريطانية عن مصر في موعدٍ أقصاه 1949م، والاحتفاظ بمعاهدة 1899م المتعلِّقة بالسودان وغيرها، ولما عُرِضَت على هيئة المفاوضات رفضَتْه، وحاول إبراهيم عبد الهادي السفَرَ إلى لندن للتوقيعِ على مشروع المعاهدة، فقامت المظاهراتُ وأعمال الشغب وإلقاء المتفجرات وأعمال التخريب، واضطر إسماعيلُ للاستقالة، وقامت مظاهراتٌ تطالِبُ بالجلاء العاجل والاستقلال ورحَّلت القواتُ البريطانية قواتِها إلى السويسِ."},{"id":5135,"title":"نشأة حزبي الشعب وبرشام الشيوعيين في أفغانستان .","date":["العام الهجري :1366","العام الميلادي :1946"],"text":"بدأ تجمُّع أصحاب الفكر الشيوعي والاشتراكي في أفغانستان منذ عام 1361هـ تحت اسم (ويش ذلميان) أي: حركة يقظة الشباب، وكان من أعضائها نور محمد تراقي، وبابرك كارمل، وكانت جريدة (أنجاد البرلمان) تنشر آراءهم، وتهاجم الإسلام، ثم أُلغيت هذه الجريدة عام 1393هـ، ثم نما هذا التجمُّع في عهد وزارة محمد داود، وأصدر محمد تراقي جريدةَ خلق، وفي 28 شعبان 1384هـ الأول من كانون الثاني عام 1965 نشرت جريدة خلق خبرَ ميلاد حزب (ديمقراتيك خلقي أفغانستان) أي: حزب الشعب الديمقراطي الأفغاني، وعُقد أول اجتماع له في بيت تراقي، حضره 27 عضوًا، يُمثِّلون 77 مؤيدًا، وانتُخِب في ذلك اللقاء نور محمد تراقي رئيسًا للجنة المركزية التي ضمَّت 9 أعضاء، واختير بابرك كارمل نائبًا له، وكان من أعضاء اللجنة حفيظ الله أمين، وشاه ولي كريم، وطاهر بدخشي، ومير أكبر خيبر. دخل الحزبُ الانتخاباتِ عام 1385هـ / 1965م، وفاز بثلاثة مقاعد، اثنان عن كابل، والمقعد الثالث عن قندهار، ثم أخذت صحيفةُ خلق الشيوعية تدعو صراحةً لمبادئه الإلحادية، فتعالت الصيحاتُ ضِدَّها، فأُغلقت بتهمة العمل ضِدَّ الإسلام والهجوم عليه. ثم في سنة 1387هـ حدث انشقاقٌ في الحزب بين تراقي من قبيلة البشتو وبابرك كارمل من قبيلة الطاجيك؛ فانشق بابرك مع جماعته، فأسس حزب برشام (الراية) وأصدر صحيفة برشام، وأنشأ تراقي حزب الشعب مع أعوانه، ومنهم حفيظ الله أمين، وشجَّعت روسيا هذا الانقسام."},{"id":5136,"title":"قرار 1947م تقسيم فلسطين لدولتين .","date":["العام الهجري :1366","الشهر القمري : محرم","العام الميلادي :1946"],"text":"كانت اللجنةُ المَلَكية البريطانية (لجنة بيل الملكية) سنة 1356هـ / 1937م قد أصدرت بعد دراسةٍ عدَّةَ توصياتٍ؛ منها: تقسيم فلسطين حيث أوصت اللجنة بقيام كيانٍ صهيوني في فلسطين بناءً على أحلام اليهود، وإعطائهم نصف فلسطين؛ لتكون دولتهم مستقلة تمامًا، مع وضع القدس وما حولها تحتَ الانتدابِ البريطاني؛ لأنها مدينة مقدسة لدى كافة الأديان، ورفضَ العرَبُ هذا القرار، واليهود كذلك رفضوه لأنهم لا يريدون نصفَ فلسطين فقط، بل يريدونها كلها!! ثم حاولت بريطانيا تشكيلَ لجنة فنية، هي لجنة وود هيد؛ لدراسة مشروع التقسيم، إلى أن تراجَعَت بريطانيا عن المشروعِ بسبب مقاطعة الطرفين للَّجنة، ونادت بدلًا عنه بضرورة إقامة سلام بين العرب واليهود، ثمَّ رُفِعَ أمر القضية الفلسطينية إلى عُصبة الأمم في حينها التي شَكَّلت هي الأخرى لجنةً لتحقيقٍ شاملٍ، والتي لم تقَدِّم تقريرها إلا للأمم المتحدة في آب 1947م واشتمل على مشروعين: الأول وهو مشروع الأكثرية، ويوصي بتقسيم فلسطين إلى دولتين عربية ويهودية، مع وحدة اقتصادية بينهما، والثاني: مشروع الأقلية ويوصي بقيامِ دولةٍ عربية يهودية اتحادية مستقلَّة، تكون مدينةُ القدسِ عاصمةً لها، وتبَنَّت الجمعية العمومية للأمم المتحدة مشروعَ الأغلبية، وأوصت بتقسيم فلسطين، كما أوصت بإنهاء الانتداب البريطاني، ورفض قرارَ التقسيمِ كُلُّ الدول العربية والإسلامية."},{"id":5137,"title":"نشأة حزب البعث العربي الاشتراكي .","date":["العام الهجري :1366","الشهر القمري : جمادى الأولى","العام الميلادي :1947"],"text":"تأسَّس في أربعينات القرن الماضي بدمشق على يَدِ كُلٍّ من ميشيل عفلق (نصراني) وصلاح الدين البيطار (مسلم سني) وزكي الأرسوزي (علوي سوري الأصل فرنسي الهوية ولم يتحدَّث بالعربية إلا في آخر أيامه), اندمج حزبُ البعث العربي الذي أسَّسه الأرسوزي مع حركة البعث العربي الذي أسَّسه عفلق، وتولى عفلق قيادته، وفي عام 1952م اندمج حزبُ البعث مع حزب أكرم الحوراني (الحزب الاشتراكي العربي)، فصار اسمُ الحزب حزبَ البعث العربي الاشتراكي، وتبنى الحزبُ القوميَّةَ العربية، فلما تسلَّم قيادة الحركة العربية نادى بالوحدة العربية، فأصبحت الاشتراكية في نظر حزب البعث جزءًا جوهريًّا من القومية العربية، وقد لعب حزبُ البعث العربي الاشتراكي دورًا مهمًّا في لبنان والأردن والعراق، فضلًا عن سوريا. ومن أبرز مبادئ الحزب: 1/ الأمة العربية وَحدة ثقافية جميعُ الفوارق القائمة بين أبنائها عُرضةٌ زائفة عَرَضية تزول جميعها بيقظة الوجدان العربي. 2/ الأمة العربية ذات رسالة خالدة تظهَرُ بأشكال متجددة متكاملة في مراحل التاريخ، وترمي إلى تجديد القِيَم الإنسانية وحَفْز التقدم البشري، وتنمية الانسجام والتعاون بين الأمم. 3/ حزب البعث العربي الاشتراكي قومي يؤمنُ بأن القومية حقيقة حية خالدة، وبأن الشعور القومي الواعي الذي يربط الفرد بأمته رباطًا وثيقًا هو شعور مقدَّس حافل بالقوى الخالقة، وحافز على التضحية، وباعث على الشعور بالمسؤولية، وعامل على توجيه إنسانية الفرد توجيهًا عمليًّا مُجديًا. 4/ حزب البعث العربي الاشتراكي يؤمِنُ بأن الاشتراكية ضرورة منبعثة من صميم القومية العربية؛ لأنها النظام الذي يسمح للشعب العربي بتحقيق إمكانياته وتفتُّح عبقريته."},{"id":5138,"title":"إصدار البرلمان البريطاني قانون استقلال الهند وتقسيمها .","date":["العام الهجري :1366","الشهر القمري : رجب","العام الميلادي :1947"],"text":"أصدر البرلمانُ البريطاني قانونَ استقلال الهند وتقسيمها إلى دولتي الهند وباكستان، وقام بمنحِ الإمارات والولايات الحَقَّ الكامِلَ في الانضمام إما إلى الهند أو باكستان."},{"id":5139,"title":"انفصال باكستان عن الهند وتعيين محمد علي جناح حاكمًا عليها .","date":["العام الهجري :1366","الشهر القمري : شعبان","العام الميلادي :1947"],"text":"كانت قضيةُ تقسيم الهند بين المسلمين والهندوس قضيةً شائِكةً جِدًّا، وبقيت سنواتٍ عِدَّةً بين أخذ ورد ومقترحات ومشروعات ومفاوضات وتدخلات بريطانية، وما إلى ذلك، وكان من آخِرِها اللجنةُ الوزارية المؤلَّفة من ثلاثة بريطانيين مهمَّتُهم المباحثة مع زعماء الهند، وأجرت المحادثات وادَّعت أن الشعب باستثناء الرابطة الإسلامية يرغَبُ في وحدة الهند، وأنهم سيرون موضوعَ استقلال باكستان، وزعموا أنَّ إقامةَ دولة باكستان لن يحلَّ المشكلة، وإن كان ففي حدود أضيق مما يطالب به الانفصاليون، وقام مجلِسُ الرابطة الإسلامية برَدِّ مقترحات هذه البَعثة الوزارية، والتي من بينها تقسيمُ البنجاب والبنغال، وقامت مظاهراتٌ واشتدت في كلِّ أرجاء الهند، وعَمِلَ الهندوس خلالها على قتلِ كُلِّ من يُنسَب إلى حزب المؤتمر الهندي من المسلمين، وفتكوا بالتجَّار القادمين من دلهي، ثم دُعِيَ الأطراف الممثِّلون عن حزب الرابطة والمؤتمر وطائفة السيخ للسفَرِ إلى لندن للمشاورة، واستمَرَّ النزاع فأعلنت بريطانيا عن خطة جديدة؛ ففي 25 شعبان 1366هـ / 14 تموز قُدِّمَ إلى المجلس النيابي البريطاني قرارُ استقلال الهند مؤلَّفًا من عشرين مادة وثلاثة جداول، ثم حاز القرارُ على التصديق الملكي في 29 شعبان، وجاء فيه: تنشأ اعتبارًا من 27 رمضان 1366هـ / 14 آب دولتانِ مستقلَّتان من طراز الدومنيونات (مستعمرات لها نظام حكم ذاتي واستقلال وحكومة خاصة مع بقائها تحت التاج الملكي البريطاني) في الهند تُعرَفُ إحداهما بالهند، وثانيهما باكستان، وسيكونُ في كل دولة حاكِمٌ يدير الدومنيين، ويتم تعيينُه من قِبَلِ صاحبِ الجلالة، (وتم تعيين محمد علي جناح حاكمًا عامًّا على باكستان)، ثم جرى خلافٌ حول بعض المقاطعات، مثل: جوناكاد (التي أخذها الهنودُ بالقوة العسكرية بمباركة إنجلترا ) وحيدر أباد (التي أيضا أخذها الهنودُ بالقوة العسكرية عام 1367هـ بسكوت إنجلترا وعصبة الأمم) وكشمير (التي ما يزال الخلاف عليها قائمًا إلى اليوم) ونيبال وبوتان وسيلان وسكيم (وهذه مقاطعات لم تدخُلْ ضِمنَ التقسيم، وإنما شَكَّلت دولًا مستقلة، ولكن سكيم انضمت للهند عام 1396هـ) وغوا (احتفظ بها البرتغاليون كميناء تابع لهم) وبونديشيري (احتفظ الفرنسيون بهذا الميناء)، ومن الجدير بالذكر أن هذا التقسيم لم يتمَّ بسهولة؛ فقد عمل الهندوس على تفريغ أكبر قدر من عصبيَّتِهم قبل أن يُفلِتَ المسلمون من أيديهم، فأقاموا الحواجز التي تمنع وصولَ المسلمين وارتكبوا المذابِحَ الشنيعة، وأحرقوا القطارات التي تنقل المسلمين إلى باكستان، حرقوا وسَبَوا ودمَّروا القرى ومحطات السكك، وفعلوا ما تقشعر منه الأبدانُ وخاصَّةً في دهلي والبنجاب الشرقية."},{"id":5140,"title":"المعاهدة العراقية الأردنية .","date":["العام الهجري :1366","الشهر القمري : رمضان","العام الميلادي :1947"],"text":"عُقِدَت معاهدةٌ أردنية عراقية في 20 رمضان 1366هـ / 7 آب كان القَصدُ منها الدفاعَ المشترك، وكان القصدُ الإنجليزي منها إثارةَ الحُكمِ السعودي والضَّغط عليه؛ للحصول على بعض المنافِعِ، أو تمرير بعض المخطَّطات، ورأى العراقيون في المعاهدةِ مَصلحةً للأردن والعراق كدَعمٍ لقضية فلسطين التي كانت تشغَلُ المسلمين عامةً، والأمصارَ المجاورةَ خاصَّةً، وقد وقف الشيوعيون في العراق موقِفًا مؤيِّدًا لليهود بكلِّ صراحةٍ، وأعلنوا ذلك في صحُفِهم ومنشوراتِهم."},{"id":5141,"title":"الإعلان عن تشكيل حكومة كشمير الحرة (آزار كشمير) .","date":["العام الهجري :1366","الشهر القمري : ذي القعدة","العام الميلادي :1947"],"text":"أعلن الشيخ محمد إبراهيم في 19 ذي القعدة تشكيلَ حُكومةِ كشمير الحرَّة (آزاد كشمير)، وتأليف الجيش الكشميري الذي استطاع أن يسيطرَ على كثير من المناطق ويقيمَ حكومة، وذلك بعد انعقادِ مؤتمر الفلَّاحين الكشميريين، والمطالبة بانضمام الولاية إلى باكستان، لكِنَّ المهراجا الهندوسي \"هري سنغ\" حاكِمَ كشمير المسلِمةِ رفض هذا الطلب، وقام بتوزيعِ الأسلحة على الهنادكة؛ فسارع رجالُ القبائل من باكستان لنجدة إخوانهم الكشميريين، ولَمَّا رأى محمد عبد الله -الذي أفرج عنه المهراجا، وهو زعيم حزب \"المؤتمر الوطني الإسلامي\" الذي أُسِّس في كشمير نتيجة اشتداد اضطهاد الهنادكة للمسلمين- تأزُّمَ الأوضاع خَشِيَ من انفلات الأمور، فأعلن وقوفه بجانب المهراجا، وتسلَّم رئاسة الحكومة، وقُتِلَ يومها من المسلمين حوالي (62) ألفًا على يدِ الهنادكة، وفي هذه الأثناء فرَّ المهراجا سنغ إلى الهند، واستقر في دلهي العاصمة تاركًا كشمير تغرق في بحار الدماء. وعندما وجد المهراجا أنَّ الأمور خرجت عن سيطرته وقدرته أراد أن يضربَ ضربته الأخيرة ضِدَّ المسلمين الكشميريين، فعقد مع الهند أثناء وجودِه في دلهي اتفاقية في (12 من ذي الحجة/ 27 من أكتوبر) تتضمَّنُ انضمام الولاية إلى الهندِ، ورغم أنَّ هذه الاتفاقية المجحِفة لا يوافقُ عليها أغلبية الشعب، وتتناقَضُ مع اتفاقيته السابقة مع باكستان، بالإضافةِ إلى عدم تمتُّعِه بالشرعية لانتهاء المائة عام من الحماية التي نَصَّت عليها اتفاقية أمريتسار لأسرته؛ فإنه أعلن انضمامَه للهند لتبدأ فصولُ مأساة جديدة!!"},{"id":5142,"title":"إعلان الهند موافقتها الرسمية على انضمام ولاية جامو وكشمير .","date":["العام الهجري :1366","الشهر القمري : ذي الحجة","العام الميلادي :1947"],"text":"أعلنت الهندُ موافقَتَها الرسميَّةَ على انضمام ولاية جامو وكشمير بعد طلب حاكِمِها الهندوسي المهراجا سينج الانضمامَ للهند، وأمرَت الهندُ قواتِها النظامية بالتدخُّل في الولاية جامو وكشمير، وهي ولاية إسلامية؛ فالمسلمون بها أغلبية لا أقلية، فنسبة المسلمين فيها تصِلُ إلى أكثر من 75% وبسبب استيلاء الهند على النصيب الأكبر من أرض الولاية أصبح المسلمون أقليَّةً وسط هذا المحيطِ البشريِّ!"},{"id":5143,"title":"إبادة جيش الهند الهندوسي مسلمي كشمير .","date":["العام الهجري :1366","الشهر القمري : ذي الحجة","العام الميلادي :1947"],"text":"بعد إعلان انفصال باكستان عن الهند لم تكن كشمير قد حُسِم وضعُها في التقسيم بين البلدين، على الرغم من أن طبيعتها وسكَّانها وموقعها الجغرافي هي أقرب إلى باكستان من الهند، ولكن الهند بمكرٍ وخداع عرضت على باكستان أنَّ حَلَّ قضية كشمير مرهون باستفتاء السكان، ووافقت باكستان على هذا العرض، وقد أكَّد على هذا رئيس وزراء الهند جواهر لال نهرو، لكن الهند أرادت أن تجعل من كشمير منطقةَ نزاع مع باكستان تتحرَّش بها متى ما أرادت؛ ولذلك لما أعلن حاكم كشمير الهندوسي (هري سنغ) اتفاقيةَ ضَمِّ كشمير إلى الهند- وهذا خلاف ما تم الاتفاق بين باكستان والهند عليه- أرسلت حكومة دلهي قوةً لحماية ولاية جمو الكشميرية من أي اعتداء، وأعلن وجوب خروج المسلمين إلى باكستان التي تطالِبُ بهم؛ فاجتمع المسلمون في أماكن محددة، وأُحضِرت السيارات لنقلهم، فلما وصلت بهم السيارات خارج القرى والمدن تعرضت لهم القوات الهندوسية، فأخذت الفتيات الشابات وقتلت الباقي، واستمر القتلُ والوحشية بأبشع صورة مدةً طويلة، فقُتِلَ ما يزيد عن نصف مليون كشميري، وهُجِّر نصف مليون مسلم ممن تمكن من الفرار إلى باكستان وغالبهم من الرجال دون النساء والأطفال الذين تعرضوا للقتل على يد الهندوس، أو ماتوا في الطريق إلى باكستان."},{"id":5144,"title":"إعلان قيام المملكة الأردنية الهاشمية .","date":["العام الهجري :1367","العام الميلادي :1947"],"text":"كان الأميرُ عبد الله بن الحسين قد تعاون بقواتِه مع الحلفاء في شمال شرق سوريا ضِدَّ دول المحور، فقامت بريطانيا - كنوع من المكافأة- بوعده بمنحِه الاستقلالَ، وفعلًا وقَّعت بريطانيا والأردن معاهدةً في لندن في 22 آذار 1946م اعترفت بموجِبِها بريطانيا بشرقي الأردن دولةً مستقلة، على أن تحتَفِظَ دولة الانتداب بحقِّ إبقاء قواتٍ لها في الأردن، مع استخدام التسهيلات في النقل والمواصلات، وتدريبِ قواتِه المسلَّحة، والتشاور التام والصريح في أمور السياسة الخارجية التي يمكِنُ أن تؤثِّرَ على مصالحهما المشتركة، وبعد الحرب في 25 أيار 1946م أصبحت الإمارةُ تحمِلُ اسم المملكة العربية الهاشمية، ثمَّ وُقِّعَت معاهدة جديدة بين الطرفين في 15 آذار 1948م خُفِّضَت فيها صلاحياتُ بريطانيا العسكرية في الأردن، ومع ذلك احتفظت بحَقِّ تملك قاعدتين جويتين في الأردن إحداهما في عمان، والأخرى في المفرق وهب مدينة في هضبة حلب الجنوبية."},{"id":5145,"title":"استباحة نصارى الحبشة مدينة هرر المسلمة .","date":["العام الهجري :1367","العام الميلادي :1947"],"text":"هَبَّت مدينة هرر المسلمة في الحبشة في عهد هيلا سيلاسي تطالبُ بحقوقها العادلة، فجَهَّزت لها الحكومةُ الغاشمةُ ثلاثةَ ألويةٍ مِن الجيشِ اقتحمت المدينةَ وعَمَلَت فيها السَّلبَ والنهب، فصودرت المتاجِرُ والمزارع والمدارس، واعتُقِلَ الآلافُ فامتلأت السجونُ، وأقيمت محاكمُ التطهير، وأُخِذَت أوقاف المساجد وأُبعِدَ الزعماء، وتعرَّض الناسُ لأشد أنواع العذاب. وكان التعذيبُ وحشيًّا لم يقتَصِرْ على إطفاء السجائر في الأجساد، بل تعريضهم للشمس اللافحة في حالةٍ مِن الجوع والظمأ الشديدين، وقد وُضِعَت براميل الماء والطعام على مقربة منهم دون أن يُسمَحَ لهم بالأكل أو الشرب منها، وهُتِكَت الأعراض على مرأًى من الأزواج والآباء، ودُقَّ خصي الرجال بأعقاب البنادق، ثم قذفوا بين أسلاك شائكة تمزِّقُ أجسادهم، والجنود يتلذَّذون بذلك المنظر الوحشي.. واستمرت هذه الأعمال الوحشية سبعةَ أشهر كاملة!"},{"id":5146,"title":"إصدار مجلس الأمن قرارًا بتقسيم فلسطين .","date":["العام الهجري :1367","الشهر القمري : محرم","العام الميلادي :1947"],"text":"وردت فِكرةُ تقسيم فلسطين إلى دولتين إسلامية ويهودية مع تحديدِ منطقة دولية حول القدس في تقريرِ لجنة پيل الملكية البريطانية عام 1937م، وتقرير لجنة وود هيد من 1938، وصدر هذان التقريران عن لجنتين تم تعيينُهما على يد الحكومة البريطانية لبحثِ قضية فلسطين إثرَ الثورة الفلسطينية الكبرى التي دارت بين السنوات 1933 و1939م. بعد الحربِ العالمية الثانية وإقامة هيئة الأمم المتحدة بديلًا لعصبة الأمم، طالبت الأممُ المتحدة بإعادةِ النظر في صكوكِ الانتداب التي منحَتْها عصبة الأمم للإمبراطوريات الأوروبية، واعتبرت حالةُ الانتداب البريطاني على فلسطين من أكثَرِ القضايا تعقيدًا وأهميةً. وقامت هيئةُ الأمم المتحدة بمحاولة لإيجادِ حَلٍّ للنزاع الإسلامي/ اليهودي القائم على فلسطين، وقامت هيئةُ الأمم بتشكيل لجنة خاصةٍ مَعنيَّة بدراسة حكومة فلسطين المستقبلية بطلبٍ مِن بريطانيا عُرِفَت هذه اللحنة باسم \"UNSCOP\" والمتألِّفة من دول متعدِّدة باستثناء الدُّوَل دائمة العضوية لضمان الحياد -بزعمهم- في عملية إيجاد حلٍّ للنزاع. قامت اللجنةُ بطرح مشروعَينِ لحَلِّ النزاع، تمثَّل المشروعُ الأولُ بإقامة دولتين مستقلَّتين، وتُدار مدينة القدس من قِبلِ إدارة دولية. وتمثَّل المشروع الثاني في تأسيس فيدرالية تضمُّ كلًّا من الدولتين اليهودية والإسلامية. ومال معظمُ أفراد اللجنة تجاه المشروع الأول والرامي لتأسيس دولتين مستقلَّتين بإطار اقتصادي موحَّد. وقامت هيئة الأمم المتحدة بقَبولِ مشروع اللجنة الدَّاعي للتقسيم مع إجراءِ بعض التعديلات على الحدودِ المشتركةِ بين الدولتين، على أن يسريَ قرار التقسيم في نفسِ اليوم الذي تنسَحِبُ فيه قوات الانتداب البريطاني من فلسطين. أعطى قرار التقسيم 55% من أرض فلسطين للدولة اليهودية، وشملت حصَّةُ اليهود من أرض فلسطين على وسط الشريط البحري (من إسدود إلى حيفا تقريبًا، ما عدا مدينة يافا) وأغلبية مساحة صحراء النَّقب (ما عدا مدينة بئر السبع، وشريط على الحدود المصري). واستند مشروعُ تقسيم الأرض الفلسطينية على أماكنِ تواجد التَّكتُّلات اليهودية بحيث تبقى تلك التكتُّلات داخِلَ حدود الدولة اليهودية."},{"id":5147,"title":"الحرب الباكستانية الهندية الأولى  .","date":["العام الهجري :1367","الشهر القمري : محرم","العام الميلادي :1947"],"text":"ما إن بدأ العمل على انفصال باكستان عن الهند حتى نظم المسلمون في كشمير المناطق التي تمكَّنوا من بسط نفوذهم عليها، وألَّف محمد إبراهيم حكومةَ كشمير الحرة (أزاد كشمير) في ذي 19 القعدة 1366 هـ / تشرين الأول، وتألف الجيشُ الكشميري، فلما وصلت القوات الهندية انضمَّت إلى قوات الحاكم الهندوسي في كشمير وبدؤوا بعمليات التطهير والقتل الجماعي لمسلمي كشمير، فنشب القتال بين الجيش الهندوسي ومجاهدي كشمير، ومع أنَّ المجاهدين كانوا يحملون أسلحة عادية أو من غير سلاح إلا أنهم استطاعوا المحافظة على أرض حكومة كشمير الحرة، وعند انتهاء الجيش الهندوسي من الاستعداد بوصول جميع قواته جوًّا من الهند قام بهجوم واسع النطاق؛ مما عرَّض باكستان نفسَها للخطر، فأرسلت باكستان ولأول مرة قواتٍ لها إلى كشمير؛ لاتخاذ مواقف دفاعية لحماية نفسِها من أي عدوان هندوسي."},{"id":5148,"title":"وفاة هدى شعراوي زوجة علي شعراوي  .","date":["العام الهجري :1367","الشهر القمري : محرم","العام الميلادي :1947"],"text":"هي هدى محمد سلطان المعروفة بهدى شعراوي؛ نِسبةً إلى لَقَبِ زَوجِها علي شعراوي على الطريقة الغربية؛ ولدت في المنيا من مصر الوسطى ونشأت في القاهرة، وكان أبوها رئيس أول مجلس نيابي في مصر، وهي التي خَرَجت بالمظاهرة النسائية سافرةً وحَرَقت حجابَها فتَبِعَها بعضُ النساء على ذلك! فكانت أولَ امرأةٍ مُسلِمةٍ في مصرَ تخلَعُ الحجابَ! مات زوجُها تاركًا لها ثروةً هائلةً كانت سبب بطرها، ألَّفَت جمعيةَ الاتحاد النسائي بمصر، وتوفِّيَت في القاهرة."},{"id":5149,"title":"اتفاق رانفيل ثم مؤتمر لاهاي لنقل السلطة للحكومة الأندونيسية .","date":["العام الهجري :1367","الشهر القمري : صفر","العام الميلادي :1948"],"text":"بعد أن قامت هولندا بإعطاء اعتراف للحكومة الأندونيسية بسيطرتِها على بعضِ الجُزُرِ عادت للتدخُّل العسكري وأعمال عسكرية ضِدَّ الحكومة، ثم تدخَّلت الأمم المتحدة وألزمت هولندا بإيقافِ إطلاق النار، ثمَّ وقِّع اتفاق رانفيل (اسم الباخرة الأمريكية التي عُقِدَت على متنها المفاوضات) واقتصرت على قسمٍ مِن جزيرة جاوه وقطعةٍ مِن سومطرة، وكانت العاصمة جوكجاكرتا (عاصمة أندونيسيا القديمة) ولم ينتهِ العامُ حتى عاد الهولنديون للأعمال العسكرية واحتلُّوا العاصمةَ واعتَقَلوا الزعماء والوزراء، وعاد القتالُ وقامت حربُ العصابات التي أنهكت الهولنديين الذين اضطرُّوا إلى الموافقة على عقد مؤتمر المائدة المستديرة في لاهاي في شوال 1368هـ / آب 1949م للمفاوضة على نقل السلطات كاملةً إلى الحكومة الأندونيسية، ودون قيدٍ أو شرط، ثم في 7 ربيع الأول 1369هـ / 27 ديسمبر 1949م تمَّ نَقلُ السلطات في احتفالٍ في مدينة لاهاي، وكان يمثِّلُ أندونيسيا محمد حتا."},{"id":5150,"title":"ارتكاب عصابات الهاجاناه مجزرة في بلدة الشيخ بفلسطين .","date":["العام الهجري :1367","الشهر القمري : صفر","العام الميلادي :1948"],"text":"قامت عصابات الهاجاناه بارتكابِ مجزرةٍ جديدة في حقِّ سكان بلدة الشيخ (يطلق عليها الآن اسم تل غنان) بفلسطين، وقامت بقتل نحو 600 قتيل فيها، وقد وُجِدَت جثث غالبيتهم داخِلَ منازل القرية. والهاجاناه منظمة صهيونية يقصد بها (الدّفاع) تأسست في العام 1921م في مدينة القدس وهي تكتّل عسكري في الانتداب البريطاني على فلسطين في الفترة السّابقة لإعلان دولة إسرائيل."},{"id":5151,"title":"تدمير قرية يجو بالحبشة .","date":["العام الهجري :1367","الشهر القمري : صفر","العام الميلادي :1948"],"text":"في شهر ديسمبر رفض المسلِمون في قرية يجو الحبشية أعمالَ السخرة في مزارع الإقطاعيين الأحباش، كما رفضوا دفعَ ضريبة الكنيسة المتزايدةِ مِن أجلِ بناء الكنائس ومراكزِ التنصير لمحاربة الإسلام، فأمر هيلا سيلاسي بإبادةِ القريةِ أسوأَ إبادة؛ فقُتِلَ المسلمون وأُحرقت مساجِدُهم وهُدِّمَت، وزُجَّ بعُلمائِها في سجن \"ألم بقا\" وهو يعني نهايةَ الحياة."},{"id":5152,"title":"ارتكاب عصابات \"الأرغون\" الصهيونية مجزرة يافا بفلسطين .","date":["العام الهجري :1367","الشهر القمري : صفر","العام الميلادي :1948"],"text":"ارتكبت عصابات \"الأرغون\" الصهيونية مجزرةَ يافا بفلسطين؛ حيث قَتَلت 30، وجرحت 98 آخرين."},{"id":5153,"title":"تأسيس المؤتمر الوطني الليبي .","date":["العام الهجري :1367","الشهر القمري : صفر","العام الميلادي :1948"],"text":"قام السنوسي بإيقاف نشاط نادي عمر المختار، ومَنَع جميعَ الأحزاب السياسية عن العمل في ديسمبر 1947م، وألَّفَ المؤتمرَ الوطنيَّ بحجة التحدُّث باسم أهالي برقة جميعًا. إلَّا أن المؤتمر كان يتكوَّنُ مِن الجيل القديم من قادة القبائل الموالين له، وكان المؤتمرُ برئاسة أخيه محمد رضا السنوسي، وفي طرابلس كانت الأحزابُ السياسية في اضطراب وبلبلة. ووُجِدَ في المنطقة أكثر من عشرة أحزاب وجماعات ونوادي ذات أهدافٍ مختلفة تسعى كلُّها للاستقلالِ وتوحيدِ مناطِقِ طرابلس وبرقة وفزان. ولكِنَّ الاختلاف كان على من يقودُ هذا الاتحاد. وهل هو ملكِيٌّ أو جمهوريٌّ، وقد تكوَّنت من الحزب الوطني الكتلة الوطنية بقيادة أحمد الفقي حسن لِمناهضة السنوسية والدعوة لإقامة جمهورية."},{"id":5154,"title":"رفع قضية كشمير إلى هيئة الأمم المتحدة للفصل فيها .","date":["العام الهجري :1367","الشهر القمري : صفر","العام الميلادي :1948"],"text":"رُفِعَت قضيةُ كشمير -موضع النزاع بين الهند وباكستان- إلى هيئة الأمم المتحدة للفصل فيها، وقد أصدرت الأممُ المتحدة قرارها في 12 صفر 1368 هـ/ 13 ديسمبر 1948 بوَقفِ القتال بين البلدين، وإجراء استفتاءٍ تحت إشرافِ الأمم المتحدة؛ لتقريرِ مسألةِ انضمامِ كشمير إلى الهند أو باكستان."},{"id":5155,"title":"ارتكاب العصابات الصهيونية مجزرة فندق سميراميس بفلسطين .","date":["العام الهجري :1367","الشهر القمري : ربيع الأول","العام الميلادي :1948"],"text":"قامت العصابات الصهيونية بارتكابِ مجزرة فندق سميراميس بفلسطين؛ حيث فجَّرَ صهاينةٌ قنبلةً في شارع صلاح الدين في حيفا، فقتلوا 31 من الرجال والنساء والأطفال، وأصابوا 31 آخرين."},{"id":5156,"title":"وفاة الإمام يحيى حميد الدين حاكم اليمن .","date":["العام الهجري :1367","الشهر القمري : ربيع الآخر","العام الميلادي :1948"],"text":"هو الإمام يحيى بن محمد بن يحيى حميد الدين الحسني العلويُّ الطالبي: ملك اليمن، الإمام المتوكل على الله ابن المنصور بالله، من أئمة الزيدية. وُلِدَ بصنعاء، وتفقَّه وتأدب بها، وخرج منها مع أبيه إلى صعدة سنة 1307 هـ وولي الإمامةَ بعد وفاة أبيه سنة 1322هـ في \"قفلة عذر\" شماليَّ صنعاء. وكانت صنعاءُ في أيدي العثمانيين فحاصرها، حتى استسلمت له حاميتها ودخلها، فأعادوا الكرَّةَ عليها، فانسحب منها، وواصل القتالَ شماليَّ صنعاء وبلاد ذمار إلى سنة 1326، واشتدَّت المعارك ولَقِيت الجيوش العثمانية الشدائدَ في تلك الديار، فأرسلت حكومة الأستانة وفدًا برئاسة عزت باشا اتَّفق مع الإمام يحيى، وأمضيا شروطًا للصلح، وانتهى الأمر بجلاء الترك عن البلاد اليمنية سنة 1336 بعد دخول الدولة العثمانية الحرب العالمية الأولى. دخل الإمام صنعاء، وخَلَص له مُلكُ اليمن استقلالًا. وطالت أيامه، وهو كلُّ شيء في اليمن، ومرجِعُ كل أمرٍ دقَّ أو جَلَّ، وما عداه من موظفين وعمال وعسكر وحكام أشباحٌ وشخوصٌ لا سلطان لهم ولا رأي، وكان شديدَ الحذر من الأجانب، آثَرَ العزلة والانكماش في حدود بلاده. وله اشتغال بالأدب ونظمٌ كثير. ومن كلامه: \"لَأن تبقى بلادي خَرِبةً وهي تحكُمُ نفسَها، أولى من أن تكون عامرةً ويحكمها أجنبي\"، وكان يرى الاستبدادَ في الحكم خيرًا من الشورى، حتى ضاقت صدورُ بعض بنيه وخاصته، وفيهم الطامع بالعرش، والمتذمِّر من سياسة القمع، والراغب بالإصلاح، فتألَّفت جماعات في السرِّ تظهر له الإخلاص وتُبطِن نقيضَه، وعلى رأس هؤلاء أقرب الناس إليه: عبد الله بن أحمد المعروف بابن الوزير، وخرج ولد له يدعى إبراهيم عن طاعته، فلجأ إلى عدن، وجعل دأبه التنديدَ بأبيه والتشهيرَ بمساوئ الحكم في عهده. وكان هذا على اتصالٍ بابن الوزير وحزبِه، ومرض الإمام يحيى، فدبَّر ابن الوزير مَن قتَلَه في 17 فبراير، ودُفِن في مقبرة كان قد أعدَّها لنفسه. وخلَّف 14 ولدًا يلقَّبون بسيوف الإسلام. وبعد مقتلِه نصب عبد الله ابن الوزير نفسَه إمامًا لليمن، لكِنَّ حكمه لم يدم أكثر من 24 يومًا؛ فقد ثار عليه سيف الإسلام أحمد ابن الإمام يحي وانتزع منه الحكم وقتَلَه."},{"id":5157,"title":"عبد الله بن أحمد بن الوزير، وزير الإمام يحيى حميد الدين .","date":["العام الهجري :1367","الشهر القمري : جمادى الأولى","العام الميلادي :1948"],"text":"هو عبد الله بن أحمد بن الوزير، وزير الإمام يحيى حميد الدين، وهو ثائِرٌ من دهاة اليمن وأعيانها وشجعانها، من أسرة علوية النسب هاشمية, ومن عُلَماء الزيدية من أهل صنعاء. ولد سنة 1302هـ بقرية بيت السيد، ودرس بهجرة بيت الوزير. كان من مستشاري الإمام يحيى حميد الدين وثقاته، أرسله سنة 1343هـ على رأس جيش لإخضاعِ جموعٍ مِن العصاة في الجوف شمال صنعاء، ووجَّهه إلى التهائم، فاستسلمت له باجل والحُدَيدة، وضبط موانئَ ابن عباس والصليف واللحية وميدي، وأرسله الإمام يحيي سفيرًا عنه إلى الملك عبد العزيز آل سعود سنة 1353هـ فعاد بمعاهدة الطائف، وحجَّ في آخر هذه السنة التي حدثت فيها مؤامرة بعض اليمانيين لاغتيال الملك عبد العزيز. كانت له إمارةُ الحُدَيدة بضع سنوات، فاستقدمه الإمام يحيى إلى صنعاء فجعله عنده بمكانةِ رئيس الوزراء فاتَّسع نفوذه بين زعماء اليمن، من علماء وقواد وأمراء وقضاة، ولما مَرِض الإمام يحيى طَمِعَ في الملك، فاتصل ببعض الناقمين، فدبر له من قتله في ظاهر صنعاء سنة 1367 هـ، وأبرق إلى ملوكِ العرب ورؤسائهم يخبرُهم بأن الإمام يحيى قد مات وأنَّ الإمامة عُرِضَت عليه فاعتذر، ثمَّ اضطرَّه ضَغطُ الأمة إلى قبولها، وأنَّه نُصِّب إمامًا شرعيًّا وملكًا دستوريًّا، فارتاب ملوك العرب، فتريَّثوا في قَبول دعواه حتى انجلى لهم الأمرُ أن الإمام يحيى مات مقتولًا وأنَّ دَمَه في عنق ابن الوزير. وكانت البيعةُ قد عُقِدَت له في قصر غمدان، وتلقَّب بالإمام الهادي إلى الله، وألَّف مجلسا للشورى من ستين فقيهًا، جعل سيف الحق إبراهيم ابن الإمام يحيى رئيسًا له، وأرسل إلى سيف الإسلام أحمد- وهو كبير أبناءِ الإمام يحيى ووليُّ عهده- يدعوه إلى البيعة، ويهَدِّده إن تخلف. وكان سيف الإسلام أحمد في حجَّة يومئذ، فلم يجِبِ ابن الوزير، ودعا إلى نفسِه وإلى الثأرِ لأبيه، وعجز ابنُ الوزير عن إحكام أمرِه، فزحفت القبائِلُ على صنعاء تسلبُ وتنهَبُ. واعتصم هو بغمدان، وانتشرت الفوضى. وأبرق إلى ملوكِ العرب يستنصِرُهم لكِنَّهم لم يجيبوه، وما هي إلا 24 يومًا مدة ابن الوزير في الإمامة والملك (18 فبراير- 14 مارس 1948) حتى كان أنصار الإمام أحمد بن يحيى في قصر غمدان، يعتَقِلون ابن الوزير ومن حوله. وحملوا إلى حجة؛ حيث أمر الإمام أحمد بقتله وقتل وزيرِ خارجيته الكبسي، فقُتِلا بالسيف في صبيحة الخميس 29 جمادى الأولى 1367هـ"},{"id":5158,"title":"مجزرة دير ياسين ضد المدنيين الفلسطينيين  .","date":["العام الهجري :1367","الشهر القمري : جمادى الآخرة","العام الميلادي :1948"],"text":"منذ إعلانِ قيام الكيان الصهيوني سنة 1948م مارست الحكومةُ الصهيونيةُ الضغطَ على العرب الذين بَقُوا في فلسطين واستخدمت معهم أبشَعَ الأساليب من استيلاء للأراضي والمصادرات، وإقامة المستعمرات والتهجير الإجباري للفلسطينيين، وإضافةً لهذا كله مارسوا اعتداءاتِهم على الفلسطينيين من قتل واغتيالات، وكان من أبشع تلك العمليات مجزرةُ دير ياسين التي ارتكبها اليهودُ في شهر نيسان 1948م؛ قتلوا فيها الأبرياء من السكان من أهل القرية من النساء والأطفال، حتى بلغ عدد القتلى أكثر من مائتين وخمسين قتيلًا، وألقوا بهم في الآبار المهجورة، وبَقَروا بطون الحوامِلِ، ومَثَّلوا بالجُثَث، وطافوا بالنساء في سيارات مكشوفةٍ في شوارع القدس وشهروا بهنَّ! فكان لهذه المجزرة البشعة أثَرٌ كبير على نفوس الفلسطينيين الذي انتقموا من قافلة يهودية وقتلوا أفرادَها المكوَّنين من سبعة وسبعين جنديًّا."},{"id":5159,"title":"ارتكاب عصابات الهاجاناه الصهيونية مجزرة قرية ناصر الدين قضاء طبريا بفلسطين .","date":["العام الهجري :1367","الشهر القمري : جمادى الآخرة","العام الميلادي :1948"],"text":"قامت عصابات الهاجاناه الصهيونية بارتكاب مجزرةٍ جديدةٍ في حقِّ الشعب الفلسطيني، وذلك في قرية ناصر الدين قضاء طبريا بفلسطين؛ حيث قتلت 50 فلسطينيًّا من سكان القرية البالغ عددهم 90."},{"id":5160,"title":"بريطانيا تلغي انتدابها على فلسطين  .","date":["العام الهجري :1367","الشهر القمري : رجب","العام الميلادي :1948"],"text":"كانت الأممُ المتحدة أوصت بتقسيم فلسطين إلى دولتين عربية ويهودية عام 1366هـ، ورفضت الدولُ العربيةُ والإسلاميةُ هذا القرارَ، ثمَّ عَمَّت البلادَ الفلسطينيةَ ثورةٌ ضِدَّ المستعمِرِ البريطاني وضِدَّ الصهيونية، واحتدم النزاعُ بين العرب واليهود الصهاينة، وشهدت فلسطين ستة أشهر من المعارك والقتال العنيف، ثم على إثرِ ذلك انسحبت القواتُ البريطانية من فلسطين في 14 مايو 1948م، وكانت مدينة القدس هي أولَ مدينة انسحبت منها بعد أن أخذت منها العديد من الآثار النادرة، وفي يوم انسحابِ بريطانيا أعلن اليهود قيامَ دولتِهم وكيانِهم في فلسطين، وبادرت أمريكا بالاعترافِ بها وشرعيَّتِها ثم تلتها روسيا، ثم توالت دُوَلُ الكُفرِ بالاعتراف بالمولود غيرِ الشرعي الجديد الذي تمخَّضَت عنه بريطانيا!!!"},{"id":5161,"title":"ارتكاب العصابات الصهيونية مجزرة قرية أبو شوشة قضاء القدس بفلسطين .","date":["العام الهجري :1367","الشهر القمري : رجب","العام الميلادي :1948"],"text":"ارتكبت العصاباتُ الصهيونيةُ مجزرة قرية أبو شوشة قضاء القدس بفلسطين، وراح ضحيَّتَها 50 قتيلًا من النساء والرجال والشيوخ والأطفال، وقد ضُرِبت رؤوس العديد منهم بالهراوات، وأطلق جنود \"لواء جفعاتي\" الصهيوني -الذي نفذ المذبحة- النارَ على كلِّ شَيءٍ متحَرِّك دون تمييز، وحتى الحيوانات لم تسلَمْ من المجزرة."},{"id":5162,"title":"إعلان قيام دولة الكيان الصهيوني يوم إنهاء الانتداب البريطاني على فلسطين .","date":["العام الهجري :1367","الشهر القمري : رجب","العام الميلادي :1948"],"text":"تم الإعلانُ عن قيام دولة الكيان الصهيوني يوم 14 مايو 1948م، وفيما يلي نصُّ إعلان الكيان نفسِه، ونحن نذكُرُه هنا لأغراضِ المعرفةِ بالعَقلِ الصهيوني ومبادئِه في تأسيس دولته.. بصَرفِ النظر عما يعتريه من تشويهٍ متعَسِّف للتاريخ والجغرافيا. \"أرضُ إسرائيل هي مهْدُ الشعب اليهودي، هنا تكوَّنت شخصيتُه الروحية والدينية والسياسية، وهنا أقام دولةً للمرة الأولى، وخَلَق قيمًا حضارية ذات مغزًى قومي وإنساني جامع، وفيها أعطى للعالم كتابَ الكتب الخالد. بعد أن نُفِيَ عَنوةً من بلاده حافَظَ الشَّعبُ على إيمانه بها طيلةَ مدة شتاته، ولم يكُفَّ عن الصلاة أو يفقِدِ الأملَ بعودته إليها واستعادة حريته السياسية فيها. سعى اليهود جيلًا تلوَ جيل مدفوعين بهذه العلاقةِ التاريخية والتقليدية إلى إعادة ترسيخ أقدامِهم في وطنهم القديم. وعادت جماهيرُ منهم خلالَ عقود السنوات الأخيرة. جاؤوا إليها روَّادًا ومدافعين فجعلوا الصحارى تتفتَّحُ وأحيوا اللغة العبرية وبنَوا المدن والقرى وأوجَدوا مجتمعًا ناميًا يسيطِرُ على اقتصاده الخاص وثقافته، مجتَمع يحب السلام لكنه يعرف كيف يدافع عن نفسه، وقد جلب نعمةَ التقدم إلى جميع سكان البلاد، وهو يطمح إلى تأسيس أمة مستقلة. انعقد المؤتمر الصهيوني الأول في سنة 5657 عبرية (1897 ميلادية) بدعوةٍ من تيودور هرتزل الأب الروحي للدولة اليهودية، وأعلن المؤتمرُ حَقَّ الشعب اليهودي في تحقيق بَعثه القومي في بلاده الخاصة به. واعترف وعد بلفور الصادر في 2 نوفمبر 1917 بهذا الحَقِّ، وأكَّدَه من جديدٍ صَكُّ الانتداب المقَرَّر في عصبة الأمم، وهي التي منحت بصورةٍ خاصة موافَقَتَها العالمية على الصلة التاريخية بين الشعب اليهودي وأرض إسرائيل، واعترافها بحَقِّ الشعب اليهودي في إعادة بناء وطنه القومي\"!!"},{"id":5163,"title":"إنشاء جيش الدفاع الإسرائيلي  .","date":["العام الهجري :1367","الشهر القمري : رجب","العام الميلادي :1948"],"text":"بعد إعلانِ قيامِ ما يُعرَفُ بدولة الكيان الصهيوني في 15 مايو 1948م، قَرَّرت أولُ حكومة صهيونية بزعامة رئيس الوزراء الصهيوني ديفيد بن جوريون تشكيلَ \"جيش الدفاع الإسرائيلي\" من عناصر عصابة \"الهاجاناه\" وهي عصابة صهيونية تأسَّست في مدينة القدس كرَدِّ فعل للثورة التي اندلعت في فلسطين من العام 1920م إلى العام 1921م، وكان الهدفُ من إنشائها العمَلَ على حماية المغتصِبين اليهود المهاجرين إلى فلسطين، وطرد السكَّان من مدُنِهم، وساهمت في بناء أكثر من 50 مغتَصَبة صهيونية و\"الهاجاناه\" كلمةٌ عبريةٌ تعني بالعربية \"الدفاع\"، ومنها تكوَّن ما يُعرَف بجيش الدفاع \"الإسرائيلي\" الحالي بعد دمجِها في عصاباتٍ صهيونيةٍ أخرى، مثل عصابات الأرجون زفاي، وشتيرن، وغيرها. وقبل تأسيسِها كانت هناك عصابةٌ تعرف بـ \"هاشومير\"، وتعني بالعربية \"الحارس\" تكونت من 100 شخص، وكانت مسؤولة عن حراسة المغتَصَبات الصهيونية؛ خوفًا من أي رد فعل على قَتلِ وتهجير الفلسطينيين من أراضيهم، وفي عام 1936م أصبح عددُ أفراد عصابة \"الهاجاناه\" العاملين 10 آلاف صهيوني، و40 ألفًا كاحتياطٍ لهم."},{"id":5164,"title":"نكبة 48 الحرب العربية الإسرائيلية الأولى وخسائر العرب .","date":["العام الهجري :1367","الشهر القمري : رجب","العام الميلادي :1948"],"text":"بعد إعلان قرارِ التقسيم تزايدَ الصِّراعُ مع اليهود أكثَرَ، ثم بلغ أوْجَهُ عند انتهاء الانتداب البريطاني على فلسطين، وكانت الأوضاعُ العربيةُ وشعوبُها المستقِلَّة استقلالًا صوريًّا غير قادرة على أعمالٍ موازية لِما يقوم به اليهود وبجانبهم بريطانيا، وخاصة من ناحية التسليح؛ حيث وصل عدد اليهود الذين يستطيعون القتال أكثر من سبعين ألفًا مقابل عشرين ألفًا من الجيوش العربية، بالإضافة للفلسطينيين والمتطوِّعين من المسلمين، وبعد الخامس من أيار/ يوليو 1948م حدثت نكبةُ 48 حين دخلت الجيوشُ العربية فلسطينَ وأهمُّها الجيش المصري، والأردني، والعراقي، والسوري، وكانت المدنُ الفلسطينية حيفا ويافا وصفد وطبريا وعكا وغيرها من القرى الصغيرة بأيدي اليهودِ، ثم توزَّعت الجيوشُ العربية على الجبَهاتِ؛ فالجنوبية للمصريين، والشرقية للأردنيين والعراقيين، والشمالية للسوريين، ولم يكن هناك تنسيقٌ مُنظَّمٌ بين هذه الجبهات، فكُلُّ جيش خاض المعركةَ وحده بدون دعم الجيوش الأخرى، فلم ينجَح الجيش السوري في التقَدُّم من جهة الشمال، وأما الجيش الأردني والعراقي فاحتفظا بالضَّفة الغربية، وقاتل الجيشُ الأردني في القدس الشرقية في باب الواد والجيش العراقي في جنين، أما الجيش المصري فحُوصِرَ في الفالوجة وعراق المنشية، ثم انسحب واحتفظ بقطاعِ غزَّة، وفشل الجيش الأردني في المحافظة على اللد والرملة وأم الرشراش (إيلات) على الرَّغمِ من أنه أكثر الجيوش العربية تطورًا وتكتيكًا، وكان يقوده مجموعةٌ من الضباط البريطانيين!، ثم أخطأت الجيوشُ العربية بقَبولِها الهدنة الأولى في أواسط صيف 1948م، فأحضر اليهود مزيدًا من الأسلحة والمقاتلين والطائرات، وفكُّوا خلالها حصارَ القدس الغربية؛ حيث كان فيها مائة ألف يهودي على وَشْك الاستسلام، فكانت نسبةُ الأراضي التي أصبحت بعد هذه الحرب في يد اليهودِ أكثَرَ من ثلاثة أرباع فلسطين، فكانت نكبةً حقيقية على العرب وجيوشِهم التي مُنِيَت بالخسائر الفادحة دون أن تحَقِّقَ شيئا، هذا بالإضافةِ لهجرة الكثير من الفلسطينيين إلى الدول العربية المجاورة والذين لم يستطيعوا العودةَ إلى الآن، وهم المعروفون بعربِ الثماني والأربعين، فهاجر منهم أكثر من 750 ألفًا ما بين سوريا والأردن وكذلك عدد لا بأس به منهم في مصر، وأقل منه في العراق والسعودية."},{"id":5165,"title":"بدء الهدنة الأولى في فلسطين بين الجيوش العربية والعصابات اليهودية أثناء حرب 1948م .","date":["العام الهجري :1367","الشهر القمري : شعبان","العام الميلادي :1948"],"text":"بعد أن زحفت الجيوشُ العربية على فلسطين في حرب 48 من الشمال والشرق والجنوب، وأعلنت حالة الحصار البحري، لم يمضِ أسبوعان على الزحفِ العربي حتى كانت الجيوشُ العربية تسيطِرُ على المناطق المخصَّصة للعرب طبقًا لمشروع التقسيم، باستثناء يافا وقِسمٍ من الجليل الأعلى، وبات متوقعًا أن تتمكن القوات العربية من إنهاء عملياتها الحربية في فترة قصيرة، فاستنجدت السلطاتُ الصهيونية والولايات المتحدة الأمريكية بهيئة الأمم المتحدة، فاتخذ مجلس الأمن قرارًا في 22/5/1948م وجَّه فيه النداء إلى المتحاربين بوقفِ القتال خلال ست وثلاثين ساعة من منتصف ليلة 22-23 أيار. ولكِنَّ الحكومات العربية رفضت الاستجابةَ لهذا النداء، فكرَّر مجلِسُ الأمن نداءَه لقبول قرار الهدنة، وتقَدَّمت بريطانيا إلى مجلس الأمن بمشروعٍ يدعو الطرفين إلى وَقفِ القتال مدَّةَ أربعة أسابيع مع التعهُّد بعدم إرسال محاربين ومواد حربية إلى فلسطين في أثناء هذه المدة، وتطبيق العقوبات المدنية والعسكرية على من يخالِفُ الأمر. وعُيِّن وسيط بين المتحاربين هو الكونت السويدي فولك برنادوت، قبلت اللجنة السياسية لجامعة الدول العربية طلبَ مجلس الأمن في 2/6/1948. وقد جاء في ردِّها على المجلس ما يلي: \"إن تلبية الدول العربية لدعوة مجلس الأمن إلى وقف القتال أربعة أسابيع مع إخفاق جميع المحاولات لَأكبرُ دليل على صادق رغبتها في التعاوُنِ مع الأمم المتحدة للوصولِ إلى هذا الحَلِّ، على الرغم من تمكُّن جيوشها من ناصية الأمر\" وقَبِلَ الإسرائيليون كذلك الهدنة، ولكنهم قرنوا القبولَ بزَعمِهم أنَّ كيان دولتهم أصبح أمرًا مفروغًا منه. بدأت الهدنةُ الأولى في فلسطين بين الجيوش العربية والعصابات اليهودية، رفض اليهودُ توصيات الكونت \"فولك برنادوت\" خاصةً فيما يتعلق بوَضعِ حَدٍّ للهجرة اليهودية في فلسطين، ووضع القُدسِ كُلِّها تحت السيادة الفلسطينية؛ لذلك اغتاله اليهود بسبب هذين الاقتراحين. استغل اليهود الهدنة لتقويةِ جُنودِهم وتنظيمِهم فكانت سيولُ المهاجرين تتدَفَّق على فلسطين خلال الهدنة بصورةٍ واسعة لم يسبقْ لها مثيل، بينما كان اللاجئون العرب يخرجون جماعاتٍ من فلسطين هاربين من اضطهاد الإرهاب اليهودي وتعَسُّف السلطات اليهودية؛ فالهدنة كانت لصالح اليهودِ دون العرب!!"},{"id":5166,"title":"قيام وحدة كوماندوز صهيونية بارتكاب مجزرة بمدينة اللّد بفلسطين .","date":["العام الهجري :1367","الشهر القمري : رمضان","العام الميلادي :1948"],"text":"ارتكَبَت وَحدة كوماندوز صهيونية بقيادة \"موشيه ديان\" مجزرةً في مدينة اللُّد بفلسطين؛ حيث اقتحمت المدينة وقت المساء تحت وابل من القذائف المدفعية. واحتمى المواطِنون من الهجوم في مسجد دهمش، وقُتِلَ في الهجوم 426 فلسطينيًّا. ولم يتمَّ الاكتفاء بذلك بل بعد توقُّف عمليات القتل اقتِيدَ المدنيون إلى ملعب المدينة؛ حيث تم اعتقال الشباب، وأعطيَ الأهالي مهلة نصف ساعة فقط لمغادرة المدينة سيرًا على الأقدام دون ماء أو طعام؛ مما تسبَّب في وفاة الكثير من النساء والأطفال والشيوخ."},{"id":5167,"title":"قيام ثورة في أندونيسيا وإعلانها قيام حكومة تابعة للشيوعيين .","date":["العام الهجري :1367","الشهر القمري : ذي القعدة","العام الميلادي :1948"],"text":"كان عامر شرف الدين الشيوعي رئيسًا للحكومة ووزيرًا للدفاع في أندونيسيا، ولكنه أُقيل من منصبه بعد الضَّغطِ الشعبي على الرئيس أحمد سوكارنو الذي عيَّنه بنفسه، فثار الشيوعيون، وألف الحزبُ الشيوعي الأندونيسي مجلسًا للثورة وقيادة عليا وقَدَّم أحدهم هو عيديد مذكرةً للحكومة للمطالبة بالتبادل السياسي مع الدول الشيوعية، وبالتأميم، ومصادرة الأملاك، وإقالة الحكومة، والسير مع الدول الماركسية، والانضمام إلى المعسكر الشيوعي تحت لواء الكرملين، وبدؤوا أيضا باختطاف الضباط من الجيش، وقاموا بأعمال تخريبية، وقتلوا بعض القياديين المسلمين، وهاجموا مراكزَ الشرطة، ثم في 16 من ذي القعدة 1367هـ / 19 أيلول أعلنت إذاعةُ ماديون عن قيام جمهورية أندونيسيا السوفيتية التي يتولى رئاسةَ حكومتِها عامر شرف الدين، فأصبح في أندونيسيا على هذا حكومتان، فأعلن المسلمون الجهادَ وتحَرَّك الجيش الأندونيسي واستطاع القضاء على هذه الثورة الشيوعية التي كان من نتائجِها قَتلُ ألف وخمسمائة من العلماء وأساتذة المدارس الإسلامية، وإحراق جثثهم بعد إعدامهم، وكُوِيَت أعيُنُ عدد كبير من الأطفال، ثم سيقَ زعماء الثورة الشيوعية وقُدِّموا للمحاكمة، وأعدِمَ عَدَدٌ منهم رميًا بالرصاص، وفي مقدمتهم عامر شرف الدين."},{"id":5168,"title":"وفاة محمد علي جناح مؤسس دولة باكستان وتولي نظام الدين .","date":["العام الهجري :1367","الشهر القمري : ذي القعدة","العام الميلادي :1948"],"text":"هو محمد علي جناح أول حكام باكستان المستقِلَّة في 8 ذي القعدة (11 أيلول 1948م)، لقَّبه مواطنوه بلقب \"قائد أعظم\" وهو مؤسس دولة باكستان. ولد في 27 ديسمبر سنة 1876، وكان أبوه تاجرًا متوسط الثراء، وعضوًا في أسرة من الخوجات تعيش في كراتشي. وتلقى محمد تعليمَه الأول في بومباي، ثم في مدرسة الإسلام السندية، وفي المدرسة العليا لجماعة المبعوثين المبشرين في كراتشي. ولَمَّا حصل على إجازة القبول في الجامعة بُعِث إلى إنجلترا سنة 1892 حيث نال شهادة القانون سنة 1896 من كلية لنكولن. وعاش في لندن في الأيام الأخيرة للأحرارِ على مذهب غلادستون، وأظهر في هذه الأثناء اهتمامًا شديدًا بالحياة العامة، وفي هذه المرحلة أيضًا اتخذ سمة الإنجليز في الظاهر -وقد جرى حتى السنة الأخيرة من حياته على لُبس اللباس الإنجليزي الخالص، وكان يُلقي جميع أحاديثه الهامة بالإنجليزية حتى الكلمة التي ألقاها في الإذاعة بمناسبة قبول خطة التقسيم، ثم ترجمها آخرون إلى الأوردية -حتى أصبح \"مستر جناح\" الذي عاد إلى الهند سنة 1896م، وبدأ في السنة التالية يمارس مهنة المحاماة في بومباي. ولم يلبث بعد عدة سنوات عجاف أن أصبح من أئمة رجال المحاماة في بومباي. وكانت استجابة الجماهير لجديته واستقامته، وليس لحرارة كلماته. وكانت أوَّلُ مشاركة لجناح في السياسة الهندية هي عضويتَه للمؤتمر الوطني الهندي، وقد حضر دورة انعقاد سنة 1906 بوصفه كاتِبَ سر خاص لنوروجي الذي كان في حينها رئيسًا للمؤتمر الوطني. وبعد ذلك بثلاث سنوات -أي في يناير سنة 1910- اتخذ مقعده عضوًا في أول مجلس تشريعي ليمثِّلَ مُسلِمي بومباي، وكان أول عضو غير رسمي يحقِّقُ سَنَّ قانون تشريعي، وكان في هذه الحالة قانونًا يصَحِّحُ وضع الأوقاف الإسلامية. وفي سنة 1913 انضم جناح إلى الرابطة الإسلامية، وهو باق شخصية مؤثرة في المؤتمر الإسلامي, وفي سنة 1919 استقال من المجلس التشريعي؛ احتجاجًا على توسيع سلطة الشرطة في القمع. وكان جناح قد تزوَّج للمرة الأولى وهو بَعدُ طفل قَبلَ رحيله إلى إنجلترا سنة 1892، ولكن زوجته توفيت وهو في خارج البلاد، وكان زواجُه الثاني من ابنة سَريٍّ من سراة اليارسيين سنة 1918. ولم يكن زواجًا موفَّقًا، فانفصل الطرفان فكانت أخته فاطمة ترعى شؤونه المنزلية معظم حياته. ولعب جناح دورًا في الحياة الهندية العامة ما بين سنتي 1920 و 1931. وقد انتُخِبَ في جمعية مركزية، وكان مندوبًا في المؤتمرين الأولين للمائدة المستديرة (سنة 1930 - 1931). وفي هذه المرحلة بدأ يعمل في المجلس الخاص للمحامين، وأقام دارًا في لندن، وأصبح لا يزور الهندَ إلا زيارات متقطعة. وكانت عودتُه الأخيرة سنة 1935 بعد تنفيذ الأحكام الدستورية الجديدة، وقد نظَّم وقاد حركة باكستان، وأصبح أول حاكم عام للدولة الجديدة. فإن الرابطة في انتخابات سنة 1946 قد كسبت جميع مقاعد المسلمين تقريبًا، ولم يستطع أحد إنكار موقف جناح من حيث هو المتحَدِّث باسم الأغلبية الساحقة. وقد اشترك جناح اشتراكًا فعَّالًا في المفاوضات التي أدت إلى قيام مشروع التقسيم، وكان لا يكُفُّ عن الإلحاح بأن المسلمين يجِبُ أن يُسمَحَ لهم بأن يختاروا لأنفُسِهم دولة مستقلة. وفي يونيه سنة 1947 تحقق غرضه وقامت دولة باكستان في منتصف ليلة 14 - 15 أغسطس سنة 1947. وتولى هو منصِبَ الحاكِم العام لها ورئيس الجمعية التأسيسية. وقد وجه جناح جهوده الأولى نحو إنهاء سَفكِ الدم والحقد الجماعي. وما وافى هذا الوقت حتى كان جناح قد بلغ السبعين من عمره، وكانت صحَّتُه تبدو عليها أمارات الانهيار. ومع ذلك فقد رأسَ إقامة الجهاز الحكومي وكان مسيطرًا سيطرة فعالة على تدبير الأمور. وفي خلال سنة 1948 ازدادت صحتُه وَهْنًا على وَهنٍ، وأدركته المنية في 11 سبتمبر. وكان جناح رجلا غيَّرَ مجرى التاريخ، صحيحٌ أنه كان ثمة شعور قومي إسلامي قبله، لكنه أسبغ عليه الثقة بالنفس، وكان جناح رجلًا نزيهًا لا يحيد، وربما كان من العسير على المرء أن يحِبَّه غيرَ أنه يحمل المرءَ على الإعجاب به. كان وطنيًّا مُسلِمًا، وإن لم يكن في أعماقه رجلَ دين. وعنده أنَّ التراث الإسلامي حضارة وثقافة وكيان قومي. ثم هو قد أسس دولة ثابتة الأركان، قيل إنه كان إسماعيليًّا، وفي قول آخر أنَّه كان شيعيًّا، وبغَضِّ النظر عن انتمائه الطائفي فإنه لم يظهر أي أثر للطائفية في عَمَلِه في باكستان، بل قيل إنه أوصى أحد علماء السنة أن يصلِّيَ عليه بعد موته، وبعد وفاة جناح تم تعيينُ الخواجا نظام الدين الذي كان رئيسًا لحكومة البنغال قبل استقلال باكستان."},{"id":5169,"title":"مجزرة البعنة ودير الأسد على يد العصابات الصهيونية .","date":["العام الهجري :1367","الشهر القمري : ذي الحجة","العام الميلادي :1948"],"text":"في الساعة العاشرة صباحًا في 27 ذي الحجة / 31 أكتوبر دخلت وَحدةٌ من جيش العدو الإسرائيلي إلى قريتي (الدير والبعنة) وقامت بتجميعِ السكان في حقل بين القريتين، وبحلولِ وقت العصر أصيب الأطفالُ والشيوخ بالإنهاك الشديد، وكانوا في أشد الحاجة إلى الماء، وطلب بعض الشباب الإذن من جنود الوحدة المعادية لإحضار بعض الماء من بئر قريبة، ليسدُّوا رمق الشيوخ والأطفال والنساء، واستعد لهذه المهمة شابان من قرية (دير الأسد ) وشابان من قرية (البعنة) وذهب هؤلاء الشباب الأربعة لإحضار الماءِ، لكنهم لم يعودوا؛ لأنَّهم عندما وصولوا البئر أعدمتهم عصاباتُ الاحتلال رميًا بالرَّصاصِ بينما كانوا يهمُّون بإخراج الماء منه، بعدها اقتادوا مجموعةً من الشباب مشيًا على الأقدام إلى قرية الرامة، ومن هناك نقلوهم بالحافلات حتى معتَقَل صرفند، ويُذكَر أنه عند اقتيادهم للشبان أمروا السكان بمغادرة القريتين، فمنهم من نزح إلى لبنان، ومنهم من نزح إلى القرى المجاورة، ثم عادوا لاحقًا إلى قريتِهم، بينما أولئك الذين نزحوا إلى لبنان فقد أُقفِلَت الحدود وتعذَّر عليهم العودة ثانية، والدير والبعنة قريتان عربيتان فلسطينيتان تقعان إلى الشمال من الطريق الرئيسي الذي يربط عكَّا بصفد."},{"id":5170,"title":"مجزرة الدوايمة على يد العصابات الصهيونية. .","date":["العام الهجري :1367","الشهر القمري : ذي الحجة","العام الميلادي :1948"],"text":"بعد أداء صلاة الجمعة والناس غافلون مُنهَمِكون في أسواقهم وأشغالهم وحقولهم، إذ بالجنودِ الصهاينة يقتَحِمون قريةَ الدوايمة التي تبعُدُ عن الخليل نحو 24 كيلو متر ويحاصِرونَها، فقتلوا المئات من الشيوخ والشباب، وحطَّموا رؤوس الأطفال بالهراوات أمام أمهاتهم، ثم قتلوا الأمهات. واعتدَوا على النساء أمام ذويهن دون أن يعبؤوا بصياحهنَّ واستنجادهن، يقول أحد قادة حزب المابام الصهيوني (إسرائيل جاليلي) إنه شاهَدَ مناظِرَ مُروِّعة من قَتلِ الأسرى، واغتصاب النساء، وغير ذلك من أفعال مَشينة. وبعد ذلك قيَّدوا الرجال الذين تم الإمساك بهم بالحبال والسلاسل، وقادوهم كما تقاد الأغنامُ ووضعوهم في أحد المنازل ومنَعوا عنهم الماء، وفجَّروا المنزل بالديناميت على رؤوسهم. وكان الملاذ الأخير لأهل القرية (الجامع) اعتقادًا منهم أن الجنودَ سيحترمون المسجد، فدخلوا المسجدَ وهم يكَبِّرون، ويقرؤون القرآن الكريم، وما هي إلا لحظات قليلة، وتمَّ قتلهم جميعًا، وكان عددهم (75) شخصًا معظَمُهم من كبار السن والعَجَزة، حيث أُحرِقَ المسجد بمن فيه بعد إغلاقِه بإحكام خوفًا من خروج الجرحى، إذا كان هناك جرحى!! يقول المؤرخ الصهيوني بني موريس: لقد تمت المجزرة بأوامِرَ من الحكومة (الإسرائيلية)، وإن فقرات كاملة حُذِفَت من محضر اجتماع لجنة (حزب المابام) عن فظائع ارتُكِبَت في قرية الدوايمة، وأن الجنود قاموا بذبح المئات من سكان القرية؛ لإجبار البقية على المغادرة. وبلغ عدد قتلى مذبحة الدوايمة ما بين 700 إلى 1000، عدا الذين كانوا يحاوِلون التسلُّل للقرية لأخذ أمتعتهم وطعامهم بعد أيامٍ مِن حصول المجزرة."},{"id":5171,"title":"الأمم المتحدة تقرر تدويل مدينة القدس .","date":["العام الهجري :1368","العام الميلادي :1948"],"text":"منذ صدورِ قرار التقسيم رقم 181 عن الأمم المتحدة الصادر في 29 نوفمبر 1947م (وهو أول قرار دولي يصدُرُ عن الأمم المتحدة يتناول القضية الفلسطينية) بدأت القدسُ تأخذ خصوصيةً معينة في الصراع العربي الإسرائيلي؛ حيث عالج القرار في جزئه الثالث قضية القدس، وجعل منها كيانًا منفَصِلًا خاضعًا لنظام دولي خاص يتبَعُ إدارة الأمم المتحدة، وعين مجلس وصاية دولي ليقوم بأعمال السلطة الإدارية نيابةً عن الأمم المتحدة، وقدَّم مجلس الوصاية مشروعًا إلى الجمعية العمومية للأمم المتحدة من أجلِ إدارة شؤون الأماكن المقدَّسة التي أصبحت تحت السيادة الجماعية للأمم المتحدة، ويقوم بإدارتها مندوبٌ تابع للمنظمة الدولية، ويساعده مجلس تشريعي مكوَّن من أربعين عضوًا لمدة ثلاث سنوات، وصدرت عشراتُ القرارات الدولية بعد ضَمِّ إسرائيل للقُدسِ الشرقية، وتوحيد المدينة تحت السيادة الإسرائيلية طالبت فيها إسرائيلَ بالتراجع عن إجراءاتها ووقْف أعمالِها غير الشرعية، وكانت لجنةُ التوفيق الدولية قد أعدت مشروعًا يستند إلى قرار التقسيم من أجل إيجاد آلية تنفيذية لقضية القدس، وقدَّمَته إلى الجمعية العمومية للأمم المتحدة في أيلول 1949م، وينص على تقسيم القدس إلى منطقتين عربية ويهودية، وكُلٌّ يدير القسم الذي له، ونزْع السلاح من منطقة القدس، وتبقى القدس منطقةً محايدة لا تكونُ عاصِمةً لأحدٍ، ويشكَّل مجلِسٌ عام للمنطقة، ويوضَعُ نظام خاص للأماكن المقدسة داخل منطقة القدس، أما الأماكن المقدسة التي تقع خارج هذه المنطقة فيُشرِفُ عليها مندوبٌ الأمم المتحدة."},{"id":5172,"title":"اكتشاف نفط السفانية تحت الماء بين السعودية والكويت .","date":["العام الهجري :1368","العام الميلادي :1948"],"text":"في هذا العام تقدَّمت إحدى شركات التنقيب عن النفط لحكومة الملك عبد العزيز بمشروع البحثِ عن النفط تحت الماء في الخليج العربي، فأذِنَ عبد العزيز بمنحها الامتيازَ بالتنقيب فيما سمِّيَ بالمنطقة المحايدة بين السعودية والكويت، وبُشِّرَ عبد العزيز في أواخر عام 1370هـ / 1951م باكتشاف الآبار النفطية في حقل السفانية، على منتصف الطريق بحرًا، بين شواطئ المملكة وشاطئ الكويت، وتم الاتفاق بين الحكومتين على اقتسامِ الفائِضِ، وتوفي الملك عبد العزيز قبل أن يرى الأنابيبَ تنقُلُ الزيتَ من قاع السفانية إلى رأس المشعاب، ثم إلى الأسواق التجارية في أنحاء العالم، ويعتبر حقلُ السفانية أكبَرَ حَقلِ نفطٍ بحريٍّ في العالم."},{"id":5173,"title":"مقتل حسن البنا .","date":["العام الهجري :1368","الشهر القمري : ربيع الآخر","العام الميلادي :1949"],"text":"هو حسن بن أحمد بن عبد الرحمن البنا، ولِدَ سنة 1324هـ / 1906م في المحمودية بالقُربِ من الإسكندرية، ووالده هو الشيخ المعروف بالساعاتي، صاحب كتاب الفتح الرباني. نشأ حسن البنا في ظِلِّ عائلة متدينة، تخرَّج من مدرسة المعلِّمين الأولية في (دمنهور)، والتحق بدار العلوم وأنهى دراسته فيها عام 1927. عُيِّنَ بعد ذلك معلِّمًا للغة العربية في المدرسة الابتدائية الأميرية في الإسماعيلية، وبَقِيَ في هذه الوظيفة إلى أن استقال منها عام 1946م؛ وفي الإسماعيلية أخذ في الدعوة إلى الله عزَّ وجَلَّ، وكان البنَّا قد شارك في إنشاءِ عدَدٍ مِن الجمعيات الدينية، إلى أن أسَّس جمعية الشبان المسلمين عام 1927، وخلص منها إلى تأسيس جماعة الإخوان المسلمين في مدينة الإسماعيلية في مارس 1928، وقرَّرت \"جمعية الحضارة الإسلامية\" أن تنضَمَّ بمركزها وجميعِ فروعِها إلى \"جماعة الإخوان المسلمين\"، وبذا نشأت أول شُعبة للإخوان في القاهرة، والتي ما لبث أن ازداد نشاطُها وأصبحت فيما بعد المركزَ العامَّ للإخوان المسلمين، وكان ذلك في عام 1932م. ثم طلب البنَّا الانتقال إلى القاهرة، فنقل إليها في أكتوبر عام 1932م، وأنشأ مجلة (الإخوان المسلمون) اليومية، وكان يقوم بإعداد معظَمِها، ثم أسَّس مجلةَ (النذير) وعَهِدَ بتحريرها لصالح عشماوي. وفي مساء الأربعاء 8 ديسمبر 1948 أعلن رئيسُ الوزراء المصري محمود فهمي النقراشي حَلَّ جماعة الإخوان المسلمين ومصادرة أموالها، واعتقال معظم أعضائِها. وفي 12 فبراير 1949 أُطلِقَ النار على حسن البنَّا أمام جمعية الشبَّان المسلمين."},{"id":5174,"title":"إعلان استقلال برقة في ليبيا .","date":["العام الهجري :1368","الشهر القمري : شعبان","العام الميلادي :1949"],"text":"بعد أن تأسَّس المؤتمر الوطني البرقاوي، وكانت دعوتُه أصلًا إلى استقلال إقليم برقة شرق ليبيا، وقيام حكومة دستورية فيها برئاسة محمد إدريس السنوسي، وكان هذا المؤتمَرُ هو الهيئة السياسية الوحيدة المعتَرَف بها، وقد عُقِدَ هذا المؤتمر في بنغازي في 5 شعبان 1368هـ / 1 حزيران 1949م، وأعلِنَ فيه عن مَولِد دولة برقة وأيد المؤتمر بالإجماع واعترفت إنجلترا بالدولة الجديدة مباشرة، أما الشعبُ فقد أبدى استياءً عامًّا، وخرجت المظاهرات ضِدَّ هذا القرار، وحتى بعد إعلان استقلال ليبيا لم يُلقِ السنوسي بالًا لذلك، وبقي يعمل كأنَّه دولةٌ مستقلة."},{"id":5175,"title":"قيام العقيد حسني الزعيم بالانقلاب العسكري الأول في سوريا  .","date":["العام الهجري :1368","الشهر القمري : شعبان","العام الميلادي :1949"],"text":"قام العقيد حسني الزعيم بأول انقلاب عسكري في سوريا، ويعَدُّ الانقلاب الذي قاده العقيد \"حسني الزعيم\" في سوريا في 29 شعبان سنة 1368هـ/ 30 مارس هو الانقلابَ الأوَّلَ في تاريخ الدول العربية الحديثة. فبعد رحيلِ الفرنسيين عن سوريا كان الأمريكيون يخشون من تنامي التيارات العقائدية داخِلَ البلاد، خاصة الشيوعية واليسارية، ورأى الأمريكيون أنَّ تَرْكَ المسرح السوري للقوى السياسية للتفاعل فيه سيقود حتمًا إلى أن يوجد السوفييت في سوريا؛ ولذا رأوا ضرورةَ إحداث انقلاب عسكري للمحافظة على الأوضاع القائمة. فشجعت المفوضية الأمريكية في دمشق الجيشَ السوري على القيام بانقلاب. وقد رأى الأمريكيون أن حسني الزعيم أفضَلُ الخيارات المطروحة أمامهم؛ حيث كان يتَّفِقُ معهم في العداء للسوفييت، ومن ثم عقَد الأمريكيون معه عدةَ لقاءات عام 1948م. وكانت الأوضاعُ في سوريا قلقةً مضطربة خاصةً بعد نكبة فلسطين؛ حيث اتُّهِم بعض قيادات الجيش بالفساد، وجرى التحقيق مع بعضهم، واتُّهِم بعض السياسيين بسرقةِ المجهود الحربي للجيش، فاستقال وزير الدفاع، ثم استقالت الوزارة، واحتدمت النقاشاتُ بين السياسيين في البرلمان، حتى إن الشرطة تدخَّلت أكثر من مرة لفَضِّها، وانهارت الحكومةُ للمرة الثانية خلال فترة وجيزة. استغل حسني الزعيم الذي عُيِّن قائدًا للجيش في ذي القعدة 1367ه / سبتمبر 1948م هذه الظروف للقيام بانقلابه، فقام بإصدارِ أوامره إلى وحدات من الجيش بمحاصرةِ مبنى الرئاسة والبرلمان والوزارات المختلفة، وتمَّ اعتقال الرئيس \"القوتلي\"، ورئيس الوزراء، وعدد من القيادات والشخصيات السياسية. ثم قام حسني الزعيم عَقِبَ نجاح انقلابه بحَلِّ البرلمان، وشكَّل لجنة دستورية لوضع دستورٍ جديد، وقانون انتخابي جديد، وأعلن أنه سيتِمُّ انتخابه من الشعب مباشرة، وبدأ بخوضِ الانتخابات الرئاسية كمرشح وحيد، وفاز فيها بنسبة 99.99% في يونيو 1949م!! وقد نمت في عهدِه أجهزة المخابرات والأمن بطريقة غير مسبوقة، وتم استخدامُ أساليب الاعتقال والتعذيب مع المعارضين. أمَّا أخطر سياساته فهي اتجاهُه للتعاون مع الغرب بطريقة مبالَغ فيها، ووقَّع على اتفاقية الهدنة مع إسرائيل، وبدأ يعتَمِدُ على الأقليات في المخابرات والجيش. رضي الشعب عن الزعيم بادئَ الأمر، ولكِنَّه بعد ذلك أخذ يرصُدُ أخطاءه الكثيرة، واستنكَرَ سياسته القائمة على كمِّ الأفواه وخنق الحريات، وحَلِّ البرلمان وتعليق الدستور. وكانت التجربةُ الاستبدادية القصيرة لحكم الزعيم كافيةً لتغذية السَّخط والتبرم بين صفوف الضبَّاط والمثقَّفين، فلم يلبَثْ أن حدَث الانقلابُ الثاني ليلة 14 أغسطس 1949، وذهب ضحيَّتَه الزعيمُ ورئيس وزرائِه."},{"id":5176,"title":"الانقلاب العسكري الثاني في سوريا بقيادة العقيد سامي الحناوي  .","date":["العام الهجري :1368","الشهر القمري : شوال","العام الميلادي :1949"],"text":"بدأ الأمريكان بالتخلِّي عن مساندة حسني الزعيم، وسعيهم للتخلص منه، بعدما أبدى قدرًا من الرغبة والمساعي للخروج عن الوصاية الأمريكية، فرأى الأمريكان أنه ما دام الجيشُ هو المؤسَّسةَ التي تملِكُ القوَّةَ، وتحتكر أدواتَها، فعليهم أن يتحَرَّكوا من داخِلِه للتخلُّصِ من الزعيم وبسرعة، وتحقَّق للأمريكيين ما أرادوا؛ حيث لم يمضِ إلا وقت قليل حتى وقع انقلابٌ مضادٌّ بقيادة العقيد سامي الحناوي في 20 من شوال 14 أغسطس، وتمَّ تشكيلُ محاكمة سريعة للغاية للزعيم، وأصدرت الحُكمَ عليه بالقتل، وتم تنفيذُ الحُكمِ في اليوم التالي رميًا بالرصاص!!"},{"id":5177,"title":"وفاة حسني الزعيم حاكم سوريا .","date":["العام الهجري :1368","الشهر القمري : شوال","العام الميلادي :1949"],"text":"هو حسني ابن الشيخ رضا بن محمد بن يوسف الزعيم؛ ثائر سوري من أهل دمشق، من القواد العسكريين. ولد حسني الزعيم في حلب سنة 1315هـ/ 1897م، وهو كردي الأصل، وكان والِدُه مفتيًا في الجيش العثماني. حكم الزعيم سوريا حكمًا مُطلقًا مدة 136 يومًا. تعلَّم الزعيم في المدرسة الحربية بالأستانة، وأصبح ضابطًا في الجيش العثماني، واعتقله الحلفاءُ أثناء الحرب العالمية الأولى، ثم التحقَ بجيش الثورة العربية بقيادة فيصل بن الحسين، وحارب العثمانيين في دمشق، وتطوَّع في الجيش الفرنسي أثناء الانتداب على سوريا، وترقى في عهد استقلالها إلى رتبة كولونيل (رُتبة عسكرية رفيعة المستوى)، وتولَّى رئاسة أركان الحرب في عهد الرئيس شكري القوتلي، ثم انقلب عليه بدَعمٍ مِن الأمريكان، في 30 مارس 1949 وتلقَّب بالمشير، وألَّف وَزارةً، ودعا إلى انتخاب رئيس للجمهورية، فخافه الناسُ فانتخبوه في آخر شعبان 1368 / 26 يونيه 1949م، فوضع نُصبَ عينيه صورَ نابليون وأتاتورك وهتلر، وأظهر نشاطًا غير مألوف، واعترفت الدولُ به وبحكومتِه. وظهر بمظهرِ الحاكِمِ المطلق، فساء ذلك بعضَ أنصارِه من العسكريين، فقتلوه في انقلابٍ قام به العقيدُ سامي الحناوي بتدبيرٍ مِن الأمريكان."},{"id":5178,"title":"العمل على توحيد مملكتي العراق والأردن .","date":["العام الهجري :1369","العام الميلادي :1949"],"text":"كان الملك عبد الله بن الحسين مَلِكُ الأردن قد وضع أُسُسَ الاتحاد بين المملكتين الهاشميتين، وبعث بهذه الأسس إلى الوصيِّ على ملك العراق عبد الإله، والملك فيصل الثاني، وأرسل الأسُسَ مع وزير بلاطه سمير الرفاعي في 6 شعبان عام 1369هـ / 2 حزيران ليرى الوصيُّ فيها رأيَه، وكان فيها التعاون العسكري وإزالة الموانع الجمركية والمرور، وتنسيق المعارف، وتوحيد السياسة الخارجية، وغيرها من الشروط، ودرست الحكومةُ العراقية هذه الأسُسَ واقترحت مشروعًا آخر فيه أن يكونَ مَلِكُ العراق هو وليُّ عهدِ الأردن، وأن يكونَ الاتحاد بالتاج دون التشريعات الداخلية، وتوحيد العملة، ولكِنَّ مقتل الملك عبد الله المفاجئ في 16 شوال 1370هـ / 20 تموز 1951م حال دون تحقيقِ المشروع."},{"id":5179,"title":"قيام دولة جمهورية أندونيسيا .","date":["العام الهجري :1369","العام الميلادي :1949"],"text":"كانت أندونيسيا اتحادية من الدويلات التي صنعَتْها هولندا، فكادت الحربُ أن تقومَ بينها فتقَدَّم محمد ناصر أحدُ زعماء حزب ماشومي في المجلس النيابي باقتراحٍ عُرِفَ باقتراح محمد ناصر الوحدوي، ويقضي بأن تقومَ كُلُّ دولة من دول الاتحاد بما في ذلك جمهورية أندونيسيا (جمهورية جوكاجكرتا) بحلِّ نفسِها، ثم تقومُ على أنقاض الجميعِ دولة جمهورية أندونيسيا، وقد حصلت الموافقةُ على هذا الاقتراح بالإجماعِ، وتم ذلك وابتعد شبحُ الحرب الأهلية."},{"id":5180,"title":"تأسيس كلية الشريعة بمكه المكرمة .","date":["العام الهجري :1369","الشهر القمري : جمادى الآخرة","العام الميلادي :1950"],"text":"كُلِّيَّةُ الشَّريعةِ بمكَّةَ المكَرَّمةِ أوَّلُ كُلِّيَّةٍ شَرعيَّةٍ تُؤَسَّسُ في المملَكةِ العَربيَّةِ السُّعوديَّةِ، وكان ذلك في عَهدِ المَلِكِ عبدِ العزيزِ رحمه الله، تغَيَّرَ اسمُها إلى كُلِّيَّةِ الشَّريعةِ والتَّربيةِ عام 1373هـ تحتَ إشرافِ وَزارةِ المعارِفِ، ثمَّ انفَصَلت عنها كُلِّيَّةُ التَّربيةِ عام 1382هـ، وأصبح اسمُها كُلِّيَّةَ الشَّريعةِ والدِّراساتِ الإسلاميَّةِ، وتحتَها ثلاثةُ أقسامٍ: الشَّريعةُ، واللُّغةُ العَربيَّةُ، والتَّاريخُ والحَضارةُ الإسلاميَّةُ. وهي الآنَ مِن كُبرى كُلِّيَّاتِ جامِعةِ أمِّ القُرى بمكَّةَ المكَرَّمةِ."},{"id":5181,"title":"اعتراف بريطانيا بضم الأردن للضفة الغربية .","date":["العام الهجري :1369","الشهر القمري : رجب","العام الميلادي :1950"],"text":"اعترفت بريطانيا بضَمِّ الأردن للضفة الغربية. وتبلغُ مساحتها 5.878 كم أي 21,7% من مساحة فلسطين، لكنَّ إسرائيل استولت عليها بعد نكسة 1967م."},{"id":5182,"title":"مشكلة منطقة البريمي مع الإنجليز في عهد الملك عبد العزيز .","date":["العام الهجري :1369","الشهر القمري : شعبان","العام الميلادي :1950"],"text":"البريمي واحةٌ في جنوب شرقي المملكة العربية السعودية على الحدودِ مع عمان والإمارات، وهي تابعة للأحساءِ، وعندما طلب الملكُ عبد العزيز من مهندسي شركة الزيت العربية الأمريكية (أرامكو) التنقيبَ فيها عن النفط منَعَت بريطانيا المنقِّبين عن مواصلة العمل باسمِ بَعضِ محميَّاتِها في الخليج؛ بدعوى أنَّها من الأراضي غير المتَّفَقِ على تبعيتها، ووافق الملك عبد العزيز حسمًا للنزاع مع الإنجليز على سحب المنقبِّين وتأجيل العمل إلى أن يتِمَّ الاتفاق على الحدود، وبينما الملِكُ ينتظر صدى تسامحِه إذا به يعلَمُ أنَّ عُمَّالًا تابعين لشركة نفط بريطانية يقومون بالحَفرِ والتنقيب في نفس الأرضي التي قالوا بالأمسِ إنها غيرُ متفق على تبعيتها، واحتجَّت حكومة الملك عبد العزيز وعُقِدَ مؤتمران لهذا الغرض بين الطرفين أحدُهما في لندن، والآخر في الدمام، وفي المؤتمر الثاني طلب الوفد البريطاني تأجيلَ اجتماعاته شهرًا، ووافق الوفد السعودي غير أن هذا الشهر لم ينتهِ، فأرسل الملك عبد العزيز أميرًا من أهل الرياض هو تركي بن عطيشان للنظرِ في شؤون البريمي، فنزلت على مقربةٍ مِن مقَرِّه قوةٌ بريطانية مسلَّحة سدَّت في وجهه سُبُلَ التموين والاتصال بالخارج، وبدأت الطائرات تحوم فوق موقع إقامة ابن عطيشان، فأبرق الملِكُ إلى سفارته في لندن في 29 / 12 /1371هـ برقيةً شخصية توصِلُها إلى وزير الخارجية البريطانية يستنكِرُ فِعلَ الحكومة البريطانية في البريمي مع مندوبه ابن عطيشان، ويهَدِّدُ برفع شكوى إلى مجلس الأمن، فأكد وزير الخارجية البريطاني على أهمية استمرار الصداقة ورغبتِهم الصادقة في حلِّ النزاع وسَحْب القوات البريطانية من البريمي في الوقت الذي ينسحب ابن عطيشان منها, ورفض الملِكُ سَحْبَ ابن عطيشان؛ وذلك لأن البريمي أرضٌ سعودية، وتوفي الملك عبد العزيز والوضعُ قائِمٌ على حاله: ابن عطيشان محصور والشركات البريطانية تعمَلُ منفردةً في التنقيب عن النفطِ."},{"id":5183,"title":"محمود جلال بايار يصبح رئيسًا لتركيا بعد فوزه بالانتخابات .","date":["العام الهجري :1369","الشهر القمري : شعبان","العام الميلادي :1950"],"text":"بقي عِصمت إينونو على نَهجِ سَلَفِه مصطفى كمال؛ إذ إنَّ حِزبَه الذي أسَّسه مصطفى -حزب الشعب الجمهوري- حكم البلادَ وتعَسَّف وأساء حتى كَرِهَه الناس، وكرهوا بقاءَ التمجيد للهالِكِ أتاتورك، ولَمَّا انتهت الحرب العالمية الثانية وأعطِيَ النَّاسُ بعض الحرية حصل خلافٌ بين رئيس الجمهورية عصمت إينونو وبين محمود جلال بايار أدَّى إلى الانشقاقِ في داخِلِ الحزب الذي ينتميان إليه، وهو الحِزبُ الحاكمُ حِزبُ الشعب الجمهوري، فقام محمود بتشكيلِ حِزبٍ جديد سمَّاه الحزب الديمقراطي، ورغم أنَّهما مِن مِشكاةٍ واحدة لكِنْ كُرهُ الناس لحزب الشعب أدَّى إلى فوز الحزب الديمقراطي عندما أُجرِيَت الانتخابات الرئاسية في (أيار 1950م) فنجح محمود جلال بايار فأصبح رئيسًا لتركيا."},{"id":5184,"title":"معاهدة الدفاع والتعاون المشترك لدول الجامعة العربية .","date":["العام الهجري :1369","الشهر القمري : رمضان","العام الميلادي :1950"],"text":"وقَّعَت أعضاءُ دُول الجامعة العربية معاهدةَ دفاع وتعاون مشترك بينها، نصَّت على الآتي: إنَّ حكومات حضرة صاحب الجلالة مَلِك المملكة الأردنية الهاشمية، وحضرة صاحب الفخامة رئيس الجمهورية السورية، وحضرة صاحب الجلالة ملك المملكة العراقية، وحضرة صاحب الجلالة ملك المملكة العربية السعودية، وحضرة صاحب الفخامة رئيس الجمهورية اللبنانية، وحضرة صاحب الجلالة ملك المملكة المصرية، وحضرة صاحب الجلالة ملك المملكة المتوكلية اليمنية رغبةً منها في تقوية وتوثيق التعاون بين دُول الجامعة العربية حِرصًا على استقلالِها والمحافظة على تراثها المشتركِ، واستجابةً لرغبة شعوبها في ضَمِّ الصفوف لتحقيق الدفاعِ المشتَرَك عن كيانها وصيانة الأمن والسلام وفقًا لمبادئ ميثاق جامعة الدول العربية وميثاق الأمم المتحدة ولأهدافِها، وتعزيزًا للاستقرار والطمأنينة وتوفير أسباب الرفاهية والعمران في بلادها: قد اتَّفَقَت على عقد معاهدة لهذه الغاية، وأنابت عنها مفوضين، وقد اتَّفَقوا على ما يأتي: المادة 1: تؤكِّدُ الدول المتعاقدة حرصًا على دوام الأمن والسلام واستقرارهما وعَزمِها على فَضِّ جميع منازعاتها الدولية بالطُّرُق السلمية سواءٌ في علاقاتها المتبادلة فيما بينهما أو في علاقاتها مع الدول الأخرى. المادة 2: وتطبيقًا لأحكام المادة السادسة من ميثاق جامعة الدول العربية والمادة الحادية والخمسين من ميثاقِ الأمم المتحدة يخطر على الفور مجلس الجامعة ومجلس الأمن بوقوعِ الاعتداء وما اتُّخِذ في صدده من تدابيرَ وإجراءات. المادة 3: تتشاور الدولُ المتعاقدة فيما بينها بناءً على طلب إحداها كلمَّا هددت سلامةَ أراضي أية واحدة منها أو استقلالها أو أمنها, وفي حالة خطر حرب داهم أو قيام حالة دولية مفاجئة يخشى خطرها تبادر الدولُ المتعاقِدةُ على الفور إلى توحيدِ خطَطِها ومساعيها في اتخاذ التدابير الوقائية والدفاعية التي يقتضيها الموقف. المادة 4: رغبةً في تنفيذ الالتزامات السالفة الذكر على أكمل وجهٍ تتعاون الدول المتعاقدة فيما بينها لدعمِ مقوِّماتها العسكرية وتعزيزها وتشترك بحسَبِ مواردها وحاجاتها في تهيئة وسائلها الدفاعية الخاصة والجماعية؛ لمقاومة أي اعتداء مسلح. المادة 5: تُؤلَّف لجنة عسكرية دائمة من ممثِّلي هيئة أركان حرب جيوش الدول المتعاقدة لتنظيم خطط الدفاع المشترك، وتهيئة وسائله وأساليبه. وتحَدَّد في ملحق هذه المعاهدة اختصاصات هذه اللجنة الدائمة، بما في ذلك وضع التقارير اللازمة المتضَمِّنة عناصر التعاون والاشتراك المشار إليهما في المادة الرابعة، وتَرفَعُ هذه اللجنة الدائمة تقاريرَها عمَّا يدخل في دائرة أعمالها إلى مجلس الدفاع المشترك المنصوص عنه في المادة التالية. المادة 6: يُؤلَّفُ تحت إشراف مجلس الجامعة مجلِسٌ للدفاع المشترك يختَصُّ بجميع الشؤون المتعلِّقة بتنفيذ أحكام المواد 2،3،4،5 من المعاهدة، ويُستعان على ذلك باللجنة العسكرية الدائمة المشار إليها في المادة السابقة. ويتكَوَّن مجلس الدفاع المشترك المشار إليه من وزراء الخارجية والدفاع الوطني للدول المتعاقدة أو من ينوبون عنهم. وما يقرِّرُه المجلس بأكثرية ثلثي الدول يكون ملزِمًا لجميع الدول المتعاقدة. المادة 7: استكمالًا لأغراض هذه المعاهدة وما ترمى إليه من إشاعة الطمأنينة وتوفير الرفاهية في البلاد العربية ورفع مستوى المعيشة فيها تتعاون الدول المتعاقدة على النهوض باقتصاديات بلادِها، واستثمار مرافِقِها الطبيعية، وتسهيل تبادل منتجاتها الوطنية الزراعية والصناعية، وبوجهٍ عام على تنظيم نشاطها الاقتصادي وتنسيقِه، وإبرام ما تقتضيه الحال من اتفاقات خاصة لتحقيق هذه الأهداف. المادة 8: ينشأ مجلس اقتصادي من وزراء الدول المتعاقدة المختصِّين بالشؤون الاقتصادية، أو من يمثِّلونهم عند الضرورة؛ لكي يقترح على حكومات تلك الدول ما يراه كفيلًا بتحقيق الأغراض المبيَّنة في المادة السابقة. وللمجلس المذكور أن يستعينَ في أعماله بلجنة الشؤون الاقتصادية والمالية المشار إليها في المادة الرابعة من ميثاق جامعة الدول العربية. المادة 9: يعتبر الملحَقُ المرفق بهذه المعاهدة جزءًا لا يتجزَّأُ منها. المادة 10: تتعهد كل من الدول المتعاقدة بألَّا تعقد أي اتفاق دولي يناقضُ هذه المعاهدة. وبألَّا تسلك في علاقاتها الدولية مع الدول الأخرى مسلكًا يتنافى مع أغراض هذه المعاهدة. المادة 11: ليس في أحكامِ هذه المعاهدة ما يمَسُّ أو يقصد به أن يمس بأية حال من الأحوال الحقوق والالتزامات المترتبة، أو التي قد تترتب للدول الأطراف فيها بمقتضى ميثاق الأمم المتحدة أو المسؤوليات التي يضطلع بها مجلس الأمن في المحافظة على السلام والأمن الدولي. المادة 12: يجوز لأية دولة من الدول المتعاقدة بعد مرور عشر سنوات من نفاذ هذه المعاهدة أن تنسحب منها في نهاية سنة من تاريخ إعلان انسحابها إلى الأمانة العامة لجامعة الدول العربية. وتتولى الأمانةُ العامة إبلاغَ هذا الإعلان إلى الدول المتعاقدة الأخرى. المادة 13: يُصَدَّق على هذه المعاهدة وفقًا للأوضاع الدستورية المرعيَّة في كل من الدول المتعاقدة. وتُودَع وثائق التصديق لدى الأمانة العامة لجامعة الدول العربية، وتصبح المعاهدة نافذةً من قِبَلِ من صدَّق عليها بعد انقضاء خمسة عشر يومًا من تاريخ استلام الأمانة العامة وثائق تصديق أربع دول على الأقل. وحُرِّرت هذا المعاهدة باللغة العربية في الإسكندرية بتاريخ 2 رمضان سنة 1369هـ الموافق 17 يونيو سنة 1950م من نسخة واحدة تُحفَظُ في الأمانة العامة لجامعة الدول العربية، وتُسَلَّم صورة منها مطابِقة للأصل لكل دولة من الدول المتعاقدة."},{"id":5185,"title":"تحرير أرتيريا من الاستعمار الإيطالي ودخولها في اتحاد مع الحبشة .","date":["العام الهجري :1370","الشهر القمري : صفر","العام الميلادي :1950"],"text":"كانت أرتيريا تحت الاستعمار الإيطالي، وعندما تحرَّرت الحبشة من الاستعمار بَقِيَت باقي المستعمرات الإيطالية لم تتحَرَّر، وكانت الحبشة تطالِبُ بضَمِّ هذه المستعمرات لها، وطال بحثُ قضية أرتيريا في أروِقةِ الأمم المتحدة وأخيرًا صدر قرارها في 22 صفر / 2 ديسمبر بإقامةِ اتحاد سياسي بين أرتيريا والحبشة كحَلٍّ يرضي بريطانيا؛ حيث لم تتخَلَّ عن الحبشة كليًّا فتعطي أرتيريا استقلالَها الذاتي وترتَبِطُ مع الحبشة باتحادٍ لامركزي."},{"id":5186,"title":"الحكومة الباكستانية تطالب الجماعة الإسلامية بوضع دستور إسلامي .","date":["العام الهجري :1370","الشهر القمري : ربيع الأول","العام الميلادي :1950"],"text":"أدَّت مطالبة الجماعة الإسلامية بقيادة أبي الأعلى المودودي تطبيقَ الشريعة الإسلامية إلى اعتقالِ المودودي وعددٍ من رموز الجماعة، ثم عَمِلت الحكومة الباكستانية على وضع أهدافٍ تحدِّد الوجهةَ الإسلامية لباكستان وذلك في 13 جمادى الأولى 1368 هـ / 12 مارس 1949م. وبعد عام في 11 شعبان 1369 هـ / 28 مايو 1950م اضطرت الحكومةُ إلى إطلاق سراح المودودي وزملائه، وبدأت الجماعةُ الإسلامية دراسةَ قرار الأهداف الموضوعة في حيِّز التنفيذ، وفي الوقت نفسِه كانت الحكومة -التي أقلقتها مطالب الشعب- تسعى إلى وضع مقترحاتها الدستورية، وأعطت لنفسها سلطات واسعة للسيطرة على الرعية، فقام المودودي بإلقاء خطاب في اجتماع عام بلاهور في المحرم 1370 هـ / أكتوبر 1950م، قام فيه بتوجيه النقد إلى تلك المقترحات الدستورية التي تمهِّد الطريق للديكتاتورية؛ فثار الرأي العام وهو ما اضطرَّ الحكومة إلى التراجع عن مقترحاتها، وتحدَّت علماءَ الجماعة الإسلامية في أن يجتمعوا على ترتيب مُسَوَّدة دستور إسلامي، وقَبِلَ العلماءُ التحدي؛ فاجتمع 31 عالِمًا يمثِّلون الفِرَق الإسلامية المختلفة في باكستان في ربيع الآخر 1370 هـ / يناير 1951م بمدينة كراتشي، واشترك المودودي معهم في صياغة النقاط الدستورية التي اتَّفقوا عليها، ولكِنَّ الحكومةَ قابلت المقترحات الدستورية التي تقدَّمت بها الجماعة الإسلامية بالصَّمتِ، وإزاءَ ذلك قامت الحركة الإسلامية بعقد عدَّةِ اجتماعات شعبية، فقامت الحكومة بإعلان الأحكام العسكرية في لاهور في جمادى الآخر 1372 هـ / مارس 1953م. وفي رجب 1372 هـ / مارس 1953م تمَّ اعتقال المودودي للمرة الثانية مع اثنين من زملائه دون توضيح أسباب هذا الاعتقال، وبعد 4 أيام من اعتقاله حُكِمَ عليه بالقتل إلَّا أن الحكومة تراجعت إلى سَجنِه مدى الحياة."},{"id":5187,"title":"تشكيل أول حكومة اتحادية مؤقتة في ليبيا برئاسة محمود المنتصر. .","date":["العام الهجري :1370","الشهر القمري : جمادى الآخرة","العام الميلادي :1951"],"text":"أعلنت الجمعيةُ التأسيسيَّةُ في ليبيا عن تشكيلِ أوَّلِ حكومة اتحادية لليبيا مؤقَّتة في طرابلس برئاسة محمود المنتصر، وفي يوم 12/10/1951م نُقِلَت إلى الحكومة الاتحادية والحكومات الإقليمية السلطة كاملة ما عدا ما يتعلَّقُ بأمور الدفاع والشؤون الخارجية والمالية، فالسُّلُطاتُ المالية نُقِلت إلى حكومة ليبيا الاتحادية في 15/12/1951م، وأعقَبَ ذلك في 24 ديسمبر 1951م إعلان الدستور واختيار إدريس السنوسي ملِكًا للمملكة الليبية المتَّحِدة بنظام فيدرالي يضم ثلاثة ولايات (طرابلس، برقة، فزان)."},{"id":5188,"title":"رفض مصر قرار إلغاء مجلس الأمن الدولي على السفن الإسرائيلية .","date":["العام الهجري :1370","الشهر القمري : ذي القعدة","العام الميلادي :1951"],"text":"أصدر مجلِسُ الأمن الدولي قرارًا بإلغاء القيود التي تفرِضُها دولةُ مِصرَ على ملاحةِ السفن الإسرائيلية في قناة السويس، لكِنَّ مصر رفضت هذا القرارَ."},{"id":5189,"title":"استقالة بشارة خليل الخوري من رئاسة لبنان .","date":["العام الهجري :1370","الشهر القمري : ذي الحجة","العام الميلادي :1951"],"text":"استقال الرئيسُ اللبناني بشارة خليل الخوري من رئاسة لبنان، وذلك بعد 9 سنوات قضاها في الحكم، وكان قد انتُخِبَ رئيسًا للجمهورية سنة 1943م، بعد أن أسهم في التوفيق بين الطوائف اللبنانية، وفي المقاومة التي أدَّت إلى الاستقلال وجلاء الفرنسيين. وأُجبِرَ على الاستقالة بعد مظاهرات ضخمة على خلفية اتهامه بالفساد؛ وخوفًا منه على تفاقم الأمور استدعى قائِدَ الجيش فؤاد شهاب، وقَدَّم إليه استقالتَه بعد أن كلَّفه بتشكيل حكومة عسكرية تتولَّى إجراء انتخابات رئاسية، وخلفه في رئاسة لبنان كميل شمعون."},{"id":5190,"title":"حركة الضباط الأحرار الأردنيين  .","date":["العام الهجري :1371","العام الميلادي :1951"],"text":"تنظيمٌ سِلمي تأسس في خمسينيات القرن العشرين من قِبَلِ مجموعة من الضباط الأردنيين الوطنيين بمباركة الملك حسين، وأهداف الحركة تتمثَّلُ في إلغاء المعاهدة الأردنية البريطانية، وتعريب قيادة الجيش العربي بطرد الجنرال الإنجليزي غلوب باشا، وقد تمَّ للحركة ما خطَّطت له، وقد تعرضت الحركة إلى وشاية بريطانية أمريكية أنَّ مِن أهداف الحركة قلبَ نظام الحكم كحركة الضباط في مصر، فاعتقل الملك حسين بعض الضباط، وفَرَّ البعض الآخر، ثم عفا عنهم."},{"id":5191,"title":"تنحية الحاكم الباكستاني نظام الدين وتولية غلام محمد .","date":["العام الهجري :1371","الشهر القمري : محرم","العام الميلادي :1951"],"text":"اغتيل رئيسُ وزراء باكستان لياقت علي خان في 16 محرم 1371هـ / 16 أكتوبر، فتَمَّ تعيين غلام محمد حاكِمًا على باكستان، وكان قبل ذلك وزيرًا للمالية، وكلف الحاكم السابق خواجا نظام الدين برئاسة الوزراء."},{"id":5192,"title":"قيام أديب الشيشكلي بالانقلاب العسكري الثالث في سوريا .","date":["العام الهجري :1371","الشهر القمري : صفر","العام الميلادي :1951"],"text":"قام العقيد أديب الشيشكلي بانقلاب عسكري ثالث في سوريا، واستولى على السلطة، وقام بحَلِّ الأحزاب السياسية، وتشكيل \"حزب حركة التحرير العربي\". وقد قام الشيشكلي بانقلابِه العسكري الأول هذا في 19 ديسمبر، لكِنْ وقع انقلابٌ عسكري ضِدَّ الشيشكلي في 25/2/1954م، فاضطر إلى مغادرة سوريا متَّجِهًا إلى لبنان."},{"id":5193,"title":"استقلال ليبيا .","date":["العام الهجري :1371","الشهر القمري : ربيع الأول","العام الميلادي :1951"],"text":"اتَّفَقت بريطانيا وإيطاليا في 10 مارس 1949م على مشروع (بيفن سيفورزا) الخاص بليبيا الذي يقضي بفرضِ الوصاية الإيطالية على طرابلس، والوصاية البريطانية على برقة، والوصاية الفرنسية على فزان، على أن تُمنَح ليبيا الاستقلالَ بعد عشر سنوات من تاريخ الموافقةِ على مشروع الوصاية، وقد وافقت عليه اللجنةُ المختصة في الأمم المتحدة في يوم 13 مايو 1949م وقُدِّمَ إلى الجمعية العامة للأمم المتحدة للاقتراع عليه، ولكِنَّ المشروع باء بالفشل؛ لحصوله على عدد قليل من الأصوات المؤيِّدة، ثم أصدرت الجمعية العامة للأمم المتحدة القرارَ رقم 289 في 21/11/1949م الذي يقضي بمنح ليبيا استقلالَها في موعد لا يتجاوز الأول من يناير 1952م، وكُوِّنت لجنة لتعمل على تنفيذ قرار الأمم المتحدة، وفي شهر أكتوبر 1950م تكوَّنت جمعية تأسيسية من ستين عضوًا يمثِّلُ كُلَّ إقليم من أقاليم ليبيا الثلاثةِ: عِشرون عُضوًا، وفي 25 نوفمبر من السنة نفسها اجتمعت الجمعية التأسيسية برئاسة مفتي طرابلس؛ لتقرر شكل الدولة، وكلفت الجمعية التأسيسية لجنةً لصياغة الدستور، فقَدَّمت تقريرها إلى الجمعية التأسيسية في سبتمبر 1951م، وكانت قد تكوَّنت حكومات إقليمية مؤقتة بليبيا، وفي 29 مارس 1951م أعلنت الجمعيةُ التأسيسية عن تشكيل حكومة اتحادية لليبيا مؤقتة في طرابلس برئاسة السيد محمود المنتصر، وفي يوم 12/10/1951م نقلت إلى الحكومة الاتحادية والحكومات الإقليمية السلطةُ كاملة ما عدا ما يتعَلَّق بأمور الدفاع والشؤون الخارجية والمالية؛ فالسلطات المالية نُقِلَت إلى حكومة ليبيا الاتحادية في 15/12/1951م، وأعقَبَ ذلك في 24 ديسمبر 1951م إعلان الدستور واختيار إدريس السنوسي ملِكًا للمملكة الليبية المتحدة بنظام فيدرالي يضم ثلاثة ولايات (طرابلس، برقة، فزان). ولكن على الرغم من كل ما قامت به بعض الدوائر الاستعمارية بعد 1951م من أجل الإبقاءِ على ليبيا مقَسَّمة وضعيفة تحت ذلك النظام الاتحادي، فإنَّ شعب ليبيا عَبْرَ ممثليه المنتَخَبين قاموا في 26 إبريل 1963م بتعديل دستورهم، وأسَّسوا دولة ليبيا الموحَّدة وأزالوا جميع العقبات التي كانت تحولُ دون وحدة ليبيا تحت اسم المملكة الليبية وعاصمتها مدينة البيضاء."},{"id":5194,"title":"حريق القاهرة بتدبير من الاحتلال البريطاني في مصر .","date":["العام الهجري :1371","الشهر القمري : ربيع الآخر","العام الميلادي :1952"],"text":"حريقُ القاهرة هو حريق هائل اندلع في عدةِ منشآت في مدينة القاهرة عاصمة مصر. وفي خلال ساعات قلائل التهمت النار نحو 700 محل وسط المدينة؛ بينها أكبر وأشهر المحلات التجارية في مصر، ومكاتب لشركات كبرى، وشققًا سكنية، وفنادق مشهورة، منها: فندق متروبوليتان، وفيكتوريا، ودورسينما، ومعارض كبرى للسيارات، وأندية ومقاهي ومطاعم. وقد أسفر هذا الحادث عن قتلى وجرحى  وتشريدِ عِدَّة آلاف من العاملين في المنشآت التي احترقت."},{"id":5195,"title":"الحكومة التركية تسمح بدخول السلالة العثمانية عدا أبناء السلاطين .","date":["العام الهجري :1371","الشهر القمري : رمضان","العام الميلادي :1952"],"text":"سمحت الحكومة التركية بدخول جميع أعضاء السلالة العثمانية -عدا الأمراء أبناء السلاطين- إلى تركيا بعد إلغاء الخلافة العثمانية في مارس 1923م، وطَرْد سلالة بني عثمان إلى خارج تركيا، بعد ما حكموا البلاد مدة 963 عامًا، منها 407 أعوام هي مدة الخلافة."},{"id":5196,"title":"ثورة الضباط الأحرار، وتنازل الملك فاروق عن الملك ومغادرته لمصر .","date":["العام الهجري :1371","الشهر القمري : ذي القعدة","العام الميلادي :1952"],"text":"تنظيم الضباط الأحرار في الجيش المصري هو تنظيم  بقيادة اللواء محمد نجيب ومعه جمال عبد الناصر الذين كانوا على صلة وقتها بجماعة الإخوان المسلمين،  قام التنظيم بانقلاب مسلح لم ترق به دماء، وسيطر على المرافق الحيوية في البلاد وأذاع البيان الأول\" للثورة \" بصوت أنور السادات وأجبر التنظيم الملك فاروق على التنازل عن العرش لولي عهده الأمير أحمد فؤاد ومغادرة البلاد، وكانت إدارة البلاد بيد مجلس قيادة الثورة المشكل من 13 ضابطا برئاسة محمد نجيب وكانوا هم قيادة تنظيم الضباط الأحرار."},{"id":5197,"title":"الحبشة تحتل أرتيريا .","date":["العام الهجري :1372","العام الميلادي :1952"],"text":"بعد أزمة أرتيريا مع الحبشة وقرارِ هيئة الأمم عام 1370هـ بقيامِها باتحادٍ لامركزيٍّ مع الحبشةِ، وهذا يعني أن تتمتَّعَ أرتيريا بسلطات تشريعية وتنفيذية وقضائية في الشؤون الداخلية، وأما خارجيًّا فمرتبطة بالحبشة، وكذلك ماليًّا ودفاعيًّا، ولم ترضَ الحبشةُ كليًّا بدمج أرتيريا بها، بل تريد ابتلاعَها كأرض لها، فأمر الإمبراطور الحبشي هيلا سيلاسي جيشَه عام 1952م باحتلال أرتيريا وتواطأت بريطانيا معها علنًا، فسَلَّمَت ثكناتها، وعين الإمبراطور سيلاسي صهرَه أند لكاتشو ماساي ممثلًا له في أرتيريا. واستولت الحبشة بالتواطؤ مع البريطانيين على كافة الممتلكات الإيطالية التي تخصُّ الحكومةَ الأرتيرية، واستولت كذلك على سكك الحديد، والجمارك، والبريد، والبرق، وسائر المواصلات والمطارات والموانئ ومصانع الملح، ثم أسَّسَت محاكِمَ خاصة أذاقت الشعبَ الأرتيري الويلات، وملأت السجون بأبناء الشعب، وحرَّمت تدريس اللغة العربية ومنعت دخول الكتب العربية والمدرسين الوافدين من الدول العربية، ونصبت عَلَمَ الحبشة مكان العلم الأرتيري، ثم وطَّدت علاقتها باليهود في فلسطين، وأسكنت النصارى في أماكن المسلمين، وفي 17 جمادى الآخرة 1382هـ / 14 نوفمبر 1962م أصدرت الحكومةُ الحبشيةُ قرارًا باحتلال أرتيريا عسكريًّا وضمِّها إلى أملاكِها رسميًّا."},{"id":5198,"title":"ثورة الشعب المغربي ضد الفرنسيين .","date":["العام الهجري :1372","الشهر القمري : ربيع الأول","العام الميلادي :1952"],"text":"قدَّمت الدولُ العربية احتجاجًا إلى هيئة الأمم المتحدة، وإلى فرنسا؛ على الأعمال التي تقومُ بها فرنسا في المغرب، ورفعت مذكرات الاحتجاج من السعودية ومصر وسوريا والأردن، غير أنَّ فرنسا رفضت كلَّ ذلك، وأما مَلِكُ المغرب الملك محمد الخامس فقد قام بتقديمِ مذكِّرة إلى رئيس فرنسا أيَّدَ فيه مطالِبَ شَعبِه بالاستقلال، وإلغاء الحماية الفرنسية، ورفضت فرنسا كلَّ ذلك أيضًا، وقدَّمت العراق مذكِّرةً إلى هيئة الأمم المتحدة، وطلبت عرضَ القضية عليها وأيَّد العراق ثلاث عشرة دولة، وأعلن حزب الاستقلال واتحاد النقابات في المغرب الإضرابَ العامَّ تضامنًا مع تونس التي أضربت بسَبَبِ مَقتَلِ فرحات حشَّاد على أيدي السلطات الفرنسية، فاستغَلَّ الفرنسيون الفرصةَ وقاموا بمذبحةٍ في مدينة الدار البيضاء ذهب ضحيَّتَها أربعة آلاف مواطن، كما اعتقلوا زعماء حزب الاستقلال، ورؤساء اتحاد النقابات في المغرب، وأعلنوا حلَّ حزب الاستقلال، وعطَّلوا الصحف العربية، وقاموا بإجراءات تعسُّفية، وتفاقَمَ الوضع أكثر بعد أن نفى الفرنسيون الملكَ محمد الخامس إلى كورسيكا من قِبَل فرنسا في شهر ذي الحجة من هذا العامِ، فتضافر معظَمُ شعب المغرب وهَبَّ لتأييد المَلِك والعمل على إعادته، وانقض الثائرون على عددٍ كبير من المتعاونين مع فرنسا والموالين لها، ففتكوا بهم، وتجاوز الأمرُ الحمايةَ الفرنسية ووصل إلى منطقة الريف؛ حيث الحماية الأسبانية. وحاول الفرنسيون اغتيالَ بعض الشخصيات فزاد الاضطراب وقاطع السكانُ البضائعَ الفرنسية، ونشأ جيشُ التحرير السري الذي استطاع أن يقومَ ببعض العمليات الناجحة على ثكناتِ الجيش الفرنسي وعلى بعض مؤسَّساته، بل وصل إلى اغتيال بعضِ أفراده."},{"id":5199,"title":"إلغاء السلطنة في المالديف وإعلان الجمهورية .","date":["العام الهجري :1372","الشهر القمري : ربيع الآخر","العام الميلادي :1953"],"text":"أُعلنت الجمهوريةُ في المالديف في يناير 1953م بعد أن أُلغِيَت السَّلطنة في العام نفسه، وانتُخِبَ محمد أمين ديدي أولَ رئيسٍ للجمهورية."},{"id":5200,"title":"تشكيل لجنة السودنة .","date":["العام الهجري :1372","الشهر القمري : جمادى الأولى","العام الميلادي :1953"],"text":"لجنةٌ شُكِّلت من عضوٍ مصري وآخر بريطاني وثلاث أعضاء سودانيين؛ لوضع إجراءاتِ إنهاء الحكم الثنائي (المصري البريطاني للسودان) بإشرافٍ دوليٍّ، وقد ورد لفظُ لجنة السَّوْدَنة في الاتفاقية التي وُقِّعَت بين مصر وبريطانيا بشأن الحكم الذاتي، وتقرير حق المصير للسودان."},{"id":5201,"title":"الموافقة على إعطاء السودان حق تقرير المصير .","date":["العام الهجري :1372","الشهر القمري : جمادى الآخرة","العام الميلادي :1953"],"text":"وقَّعت الحكومتان المصرية والبريطانية اتفاقيةً يتِمُّ بمقتضاها منح السودان حقَّ تقرير المصير في خلال ثلاث سنوات كفترةٍ انتقالية تطبيقًا لبنود الاتفاق. وقد تمَّت أول انتخابات نيابية في السودان في أواخر عام 1953م، وتم تعيين أول حكومة سودانية وذلك في 9 يناير 1954م. بالإضافة إلى تركِ المناطق التي استحوذ عليها البارونات في أيديهم؛ وفي 19 أغسطس قامت وحدات من الجيش السوداني الجنوبي بالتمَرُّد، وتم القضاء على حركة التمرد عن طريق الجيش. وفي 30 أغسطس وافق البرلمانُ على إجراء استفتاء عام لتحديد مستقبل البلاد السياسي، وفي نفس الوقت وافقت مصرُ وبريطانيا على الانسحابِ مِن السودان في 12 نوفمبر 1955، وفي 19 ديسمبر أعلن البرلمان السودانَ كدولةٍ مستقلةٍ بعد إجراء الاستفتاء العام.  وقد تم إعلانُ جمهورية السودان رسميًّا في 1 يناير 1956م."},{"id":5202,"title":"تتويج حسين بن طلال ملكًا للأردن .","date":["العام الهجري :1372","الشهر القمري : شعبان","العام الميلادي :1953"],"text":"بعد مَقتلِ الملك عبد الله تُوِّجَ ابنُه الأكبر طلال بن عبد الله خلفًا لوالِدِه، ولكن خلال عام أجبره البرلمان الأردني على التنحِّي عن المُلكِ بدعوى أنَّه مصاب بمرض عقليٍّ أو نفسي، فأُعلن ابنُه الأمير حسين ملكًا على الأردن، وذلك في 11 أغسطس 1952 وكان عمره آنذاك 17 سنة، ولم يكنْ يبلغ السن القانونية، فشُكِّلَ مجلِسٌ للوصاية على العرشِ، وتم تتويجُه ملِكًا في 2 مايو عام 1953."},{"id":5203,"title":"وفاة الشريف عبد الله بن الحسين ملك الأردن  .","date":["العام الهجري :1372","الشهر القمري : شعبان","العام الميلادي :1953"],"text":"الشريف عبد الله بن الحسين بن علي بن محمد الحسني الهاشمي، من آل عون أمير شرقيَّ الأردن، ثم ملك المملكة الأردنية الهاشمية. ولد بمكة سنة 1299هـ، وتلقى مبادئ العلوم في الأستانة أيام إقامة أبيه فيها، وعاد مع أبيه إلى الحجاز سنة 1326ه، وسمي نائبًا عن مكة في مجلس النواب العثماني سنة 1327، فكان يقيم بعض شهور السنة في العاصمة العثمانية، وبقيَّتَها في الحجاز. وقام مع والده في الثورة على الترك سنة 1334ه / 1916م فقاد جيشًا حاصر الحامية العثمانية في الطائف، إلى أن استسلمت. وأرسله أبوه نجدةً لأخيه علي بن الحسين في حصاره للمدينة، فأقام مرابطًا في وادي العيص إلى أن انتهت الحرب، وفي عام 1919م انهزم أمام قواتِ الإخوان  (إخوان من أطاع الله) في تربة، وفي عام 1921م نصبه الإنجليز ملكًا على شرق الأردن مقابِلَ التوقيع على صك الانتداب، وفي يوم 20 يوليو 1951م كان الملك عبد الله في طريقه إلى المسجد اعترضه \"مصطفى شكري عشي خياط\" وهو من القُدسِ، وعضو فرقة المقاومة بقيادة فوزي القطب التي كانت تقاتِلُ اليهود, فأطلق على الملك عبد الله النارَ فأرداه قتيلًا على دَرَجاتِ الحَرَمِ القدسي؛ وذلك جراء ما وُصِفَ بأنه تآمر مع بريطانيا على ترك فلسطين لليهود مقابِلَ تمكينه في منطقة بادية الشام شرقيَّ نهر الأردن؛ لإقامة إمارة ثم مملكة له ولأبنائه من بعده. وبعد اغتياله تولى المُلكَ بعده ابنه الأكبر طلال."},{"id":5204,"title":"إعلان النظام الجمهوري في مصر برئاسة محمد نجيب .","date":["العام الهجري :1372","الشهر القمري : شوال","العام الميلادي :1953"],"text":"بعد أن تنازل المَلِكُ فاروق مجبَرًا عن الملك لابنِه ولي العهد أحمد فؤاد الثاني، لم يكن للملك الجديد أيُّ عمل؛ إذ كان ما يزال طفلًا تحت الوصاية، وكان الأمر والنهي كله بيد قادةِ ثورة يوليو الضبَّاط الأحرار الذين أجبروا أباه على التنازُلِ، وفي 6 شوال / 18 حزيران أصدر مجلِسُ قيادة الثورة قرارًا بإلغاء النظام الملكي وإعلان النظامِ الجمهوري بمصر، وبعد أن عدَّد القرارُ سلبياتِ الأسرةِ الحاكمة من خيانةٍ وعبوديةٍ، وعدم احترام للدستور، إلى غير ذلك. أعلن البيان الموقَّع من مجلس قيادة الثورة الجمهورية، وتولي اللواء محمد نجيب قائدِ الثورة رئاسةَ الجمهورية مع احتفاظه بسُلُطاتِه في ظِلِّ الدستور المؤقَّت الصادر في 10 شباط 1953م، ويستمِرُّ هذا النظام طوالَ فترة الانتقال، ويكونُ للشَّعبِ تحديدِ نوعِ الجمهورية، واختيار الرئيس عند إقرار الدستور الجديد."},{"id":5205,"title":"فرنسا تنفي السلطان المغربي محمد الخامس إلى جزيرة كورسيكا .","date":["العام الهجري :1372","الشهر القمري : ذي الحجة","العام الميلادي :1953"],"text":"لم تتوقَّف المطالِبُ المغربيَّةُ بالاستقلالِ طوالَ السنواتِ الماضيةِ، والمَلِكُ يؤيِّدُها، فكاد الفرنسيون للمَلِك فألزموا الكثيرَ من الوجهاء والقادة على التوقيعِ على عريضة تطالِبُ بخَلعِ الملك؛ لمعارضته الإصلاحاتِ وعدمِ أهليتِه، وكانت فرنسا قد قرَّرت التخَلُّصَ من الملك بأيِّ صورة، فأَرسَلَت له في 9 ذي الحجة - أي يوم عرفة- وثيقةً عن طريق الحاكم العام الفرنسي تتضَمَّنُ تخييره بين التنازل عن الملك أو النفي، فقام الملِكُ بتمزيق الوثيقةِ، ثم في اليوم التالي يوم العيد جاءت قوةٌ فرنسية واعتَقَلت الملك وأفراد أسرته ونقلَتْهم بالطائرةِ إلى أجاكسيو عاصمة جزيرة كورسيكا، ثم حُمِلَ إلى جزيرة مدغشقر في المحيط الهندي في شرق أفريقيا، ونُصِبَ مكانَه أحد أفراد أسرتِه، وهو محمد بن عرفة."},{"id":5206,"title":"وفاة الملك عبد العزيز آل سعود ملك المملكة العربية السعودية .","date":["العام الهجري :1373","الشهر القمري : ربيع الأول","العام الميلادي :1953"],"text":"هو المَلِكُ عبد العزيز بن عبد الرحمن بن فيصل بن تركي بن عبد الله بن محمد بن سعود آل مقرن: مَلِكُ المملكة العربية السعودية، ومؤسِّسُ الدولة السعودية الثالثة، وأحدُ رجالاتِ العَصرِ. وُلِدَ في الرياض عام 1293هـ / 1876م، ودَولةُ آبائِه في ضَعفٍ وانحلال، وصَحِبَ أباه في رحلته إلى البادية، يطارده محمد بن عبد الله ابن رشيد، واستقَرَّ مع أبيه في \"الكويت\" سنة 1309ه (1891 م) وشبَّ فيها. وشنَّ الغارات على آل رشيد وأنصارهم. وفاجأ عامِلَ ابن رشيد في الرياض بوثبةٍ فاستولى عليها سنة 1319ه / 1902م، وضَمَّ إلى الرياض الخرج، والمحمل، والشعيب، والوشم، والحوطة والأفلاج ووادي الدواسر. واستولى على بلاد القصيم سنة 1324هـ, شَكَّل قواتِ الإخوان (إخوان من أطاع الله)  العسكرية من خلال نظامِ الهجر التي كان لها أكبَرُ الأثر في إتمامه لتوحيد الجزيرة العربية، فأخضَعَ آل عائض أمراء عسير في الجنوب، وأزال إمارة آل رشيد في الشمال سنة 1340هـ. وكانت بينه وبين الشريف حسين بن علي أحداثٌ انتهت بالقضاء على دولة الهاشميين في الحجاز سنة 1343ه / 1925م فنودي به مَلِكًا على الحجاز وسلطانًا لنَجدٍ، وكان مِن قَبلُ يلقَّب بالأمير أو السلطان والإمام. ثار عليه بعضُ كبار قادة الإخوان فقضى على قوَّتِهم في معركة السبلة، ثم برزت فتنة \"ابن رفادة\" في الشمال فتمَكَّنَ مِن القضاء عليها. وفي سنة 1351ه / 1932م أعلن توحيدَ الأقطار الخاضعة له، وتسميتها \"المملكة العربية السعودية\"، ولم يشغَلْه خوضُ المعارك وتجهيزُ الجيوش وقمع الفتن عن تنظيم بلاده، وسنِّ ما يلائِمُها من النظم الحديثة، وإنشاء العلاقات السياسية والاقتصادية مع الدول العربية والأجنبية. واكتُشِف البترول في عهده، وكانت الدولة محدودةَ الموارد، فانتعَشَت واتجهت إلى العمران، وحلَّ الأمنُ محَلَّ الخوف في الصحاري والحواضر. وحوَّل كثيرًا من أهل الخيام إلى سكَّان قرى، وأوصل مملكتَه المترامية الأطراف بشبكاتٍ لاسلكيةٍ. وأتى بكثير من الطائرات التي سهَّلت على الناس التنقُّل، وأنشأ موانئَ وعبَّد طرُقًا. وأعفى الحجَّاجَ مِن الرُّسوم. واستكثَرَ من الأطباء والزراعيين والمدرسين، وأرسل بعثاتٍ من أبناء الحجاز ونجد إلى البلدان القريبة والبعيدة؛ لتلَقِّي العِلمِ في جامعاتها, ثم وافاه الأجَلُ رحمه الله بعد أن قضى في الملك قرابة 54 سنة، وكان قد عيَّنَ ابنَه الكبير سعودًا وليًّا للعهد، فتسَلَّمَ زِمامَ المُلكِ بعد وفاة أبيه."},{"id":5207,"title":"إعادة نظام السلطنة للمالديف وتنصيب محمد فريد ديدي سلطانا .","date":["العام الهجري :1373","الشهر القمري : جمادى الآخرة","العام الميلادي :1954"],"text":"لم يدُمِ النظام الجمهوري في المالديف كثيرًا؛ حيث طُرِح موضوعُ رئاسة الجمهورية على الجمعية الوطنية التي صوَّتَت بإعادة السلطنة، فتمَّ ذلك ونُصب محمد فريد ديدي سلطانًا على المالديف في شباط 1954م خلَفًا لابن عمِّه الرئيس السابق."},{"id":5208,"title":"تنحي رئيس مصر محمد نجيب وتولي جمال عبد الناصر .","date":["العام الهجري :1373","الشهر القمري : شعبان","العام الميلادي :1954"],"text":"زادت مُضايقاتُ بعضِ رجالِ الثَّورةِ -وخاصةً جمال عبد الناصر، وجمال سالم، وصلاح سالم- لرئيس الجمهورية محمد نجيب، فكانت تُختصَرُ كلماتُه في وسائل الإعلام، بل وتُهمَلُ أحيانًا، ويُطلَبُ منه إبعادُ بعض أعوانه دون سبب، بل ويُشتَمُ أمام أنصاره ويُطلَبُ منهم إبلاغه بذلك! وأمام هذه المضايقات قَدَّم الرئيس محمد نجيب استقالتَه إلى مجلس الثورة، وبعد ثلاثة أيام صدر قرارُ مجلس قيادة الثورة بقَبولِ الاستقالة على أن يقومَ جمال عبد الناصر بكافَّةِ سلطاته حتى تحَقِّقَ الثورةُ أهدافَها بجَلاءِ المستعمِر، وقامت المظاهراتُ المؤيِّدة للرئيس محمد نجيب ولَمَّا استفحل الأمرُ قَرَّروا إعادة محمد نجيب للرئاسةِ على أساسِ تحويلِ مِصرَ إلى جمهوريةٍ نيابية باسمِ الجمهورية النيابية المصرية، وتَشكيلِ جمعية تأسيسية تمثِّلُ كافة هيئات الشعب المختلفة، وإجراء انتخابات بعد ذلك لإجراء الحياة النيابية، وقَبِلَ محمد نجيب على هذا الأساس، ثم عادت الاضطراباتُ مَرَّةً أخرى فقدم استقالتَه وحَلَّ مكانه جمال عبد الناصر، وشَكَّل وزارته الثانية في 11 شعبان 1373هـ / 17 نيسان."},{"id":5209,"title":"تولي الأمير فيصل بن عبد العزيز رئاسة مجلس الوزراء .","date":["العام الهجري :1373","الشهر القمري : ذي الحجة","العام الميلادي :1954"],"text":"بعد وفاة الملك عبد العزيز رحمه الله عام 1373هـ/ 1953م بويع الأميرُ سعود بن عبد العزيز مَلِكًا على البلادِ خَلَفًا لوالده، كما بويع الأمير فيصل بولاية العهد، وتبعًا لذلك ولتمرُّسه على شؤون الحكم والإدارة وأمور السياسة عُيِّن نائبًا لرئيس مجلس الوزراء، كما احتفظ بمركزِه السابق كوزير للخارجية، ثم عَهِدَ إليه الملك سعود في 16 ذي الحجة من هذا العام برئاسةِ مجلس الوزراء."},{"id":5210,"title":"الاستقلال الداخلي لدولة تونس .","date":["العام الهجري :1373","الشهر القمري : ذي الحجة","العام الميلادي :1954"],"text":"أعلنَ رئيس الوزراء الفرنسي \"بيير منديس فرانس\" في تونس أنَّ الحكومة الفرنسية تعترف بالاستقلالِ الداخلي للدولة التونسية."},{"id":5211,"title":"الاتفاقية المصرية البريطانية لجلاء القوات البريطانية من قناة السويس .","date":["العام الهجري :1374","الشهر القمري : صفر","العام الميلادي :1954"],"text":"جاء في المعاهدةِ التي وقَّعَها رئيس وزراء مصر وزملاؤه ووزير الدولة بوزارة الخارجية البريطانية، والسفير البريطاني بشأن قاعدة السويس، والغرض منه إقامةُ علاقات مصرية إنجليزية على أساسٍ جديدٍ مِن التعاون، وإنهاء معاهدة 1936، وجلاء القوات البريطانية جلاءً تامًّا عن الأراضي المصرية في مدة أقصاها عشرون شهرًا من تاريخ الاتفاقية، على أنه يحِقُّ للقوات البريطانية العودةُ في حالة الاعتداء على مصر، ويبقى بالتالي خبراءُ بريطانيون في القاعدة لا يتجاوز عددهم الألف خبير، وبناءً على هذه الاتفاقية بدأت القواتُ البريطانية بالجلاء عن القناة في 5 ذي القعدة 1375هـ / 13 حزيران 1956م."},{"id":5212,"title":"محاولة اغتيال جمال عبد الناصر في حادثة المنشية .","date":["العام الهجري :1374","الشهر القمري : صفر","العام الميلادي :1954"],"text":"أقيمَ حَفلُ تكريم لجمال عبد الناصر ورفاقه في حديقة المنشية بمدينة الإسكندرية في 29 صفر / 26 أكتوبر، واتُّخِذَت التدابير الأمنية المعروفة، وفي أثناء الحفل تقَدَّم أحد الرجال وأطلق ثمانيةَ أعيرة نارية باتجاه جمال عبد الناصر الذي لم يُصَبْ هو ولا الوفد بأيِّ أذًى، وبدأت الصحف تتكَلَّمُ عن الحادثة وعن القبض على المجرم، وشُكِّلَت محكمةُ الشعب برئاسة جمال سالم وعضوية أنور السادات، وحسين الشافعي، فصدرت ضِدَّ أعضاء جماعة الإخوان المسلمين أحكام بالسجن، بدأت من عشر سنوات إلى الأشغال الشاقة المؤبَّدة، والقتل بحَقِّ سبعة من قيادات الجماعة، هم كُلٌّ من: محمود عبد اللطيف؛ ويوسف طلعت، وإبراهيم الطيب، وهنداوي دوير، ومحمد فرغلي، وعبد القادر عودة، وحسن الهضيبي الذي خُفِّفَ عنه الحكم لاحقًا إلى المؤبَّد؛ لكبر سنه ومَرَضِه، ونُفِّذَ حكم القتل بالآخرين، ثم زُجَّ بالآلاف في السجون."},{"id":5213,"title":"الثورة الجزائرية الكبرى (المليون شهيد) ضد قوات الاستعمار الفرنسي .","date":["العام الهجري :1374","الشهر القمري : ربيع الأول","العام الميلادي :1954"],"text":"قام فرحات عباس زعيم حزب اتحاد الشعب الجزائري بتقديم بيانٍ إلى السلطات الفرنسية يطالبون فيه بحث تقرير المصير, إلَّا أن فرنسا رفضت واعتقلت فرحات عباس، ولم يمضِ وقتٌ طويل حتى استغلت فرنسا قيامَ بعض المظاهرات في عددٍ من المدن الجزائرية وإحراقها للعَلَم الفرنسي حتى ارتكبت مذبحةً رهيبة سقط فيها 45 ألف قتيل جزائري، وكان ذلك تحولًا في كفاح الجزائريين من أجلِ الحرية والاستقلال؛ فتشَكَّلت لجنة سرية من اثنين وعشرين عضوًا، وفوضت محمد بوضياف لاختيارِ قيادة لعمل منظم سري، فشكَّلَها من تسعة أعضاء وعُرِفَت باللجنة الثورية للوَحدةِ والعمل، وارتحل ثلاثة منهم للتنسيق مع أحزاب المغرب وتونس من أجل الثورة في البلاد كلِّها جميعًا، ومن أجل الدعم، وحُدِّد يوم 1 نوفمبر 1954م موعدًا لبدء الثورة الجزائرية الحاسمة -وهو يصادف عيد القديسين عند الفرنسيين- وفوجئت السلطات الاستعماريةُ الفرنسية بوقوعِ سلسلة من الهجمات المسلَّحة شَنَّها الثوار الجزائريون على المنشآت والمراكز العسكرية الفرنسية في كامل أنحاءِ البلاد، وكان ذلك إيذانًا ببداية حرب طويلة الأمد استمَرَّت سبع سنوات ونصف، وقد بادرت جبهةُ التحرير الجزائرية باستعدادها لمفاوضة فرنسا من أجلِ وقف القتال, بعد أن بلغ الشهداءُ أكثر من مليون شهيد، لكِنَّ فرنسا رفضت تلك المبادرة، وزادت قواتِها الاستعمارية إلى أكثر من نصف مليون مقاتل، وقامت بأحدَ عَشَرَ هجومًا ضخمًا واسِعَ النطاق؛ العمل الذي عُرف بمشروع شال. فزاد جيش التحرير الجزائري قواتِه إلى أكثر من 120 ألف مجاهد. وامتَدَّت عملياته إلى الأراضي الفرنسية؛ حيث تم تدمير مستودعات بترولية ضخمة. استطاعت فرنسا اختطافَ طائرة مغربية على مَتنِها أربعة قواد من قادة الثورة الجزائرية، وهم: حسين آيات أحمد، وأحمد بن بله، ومحمد خضير، ومحمد بو ضياف، فأصبحت القضيةُ الجزائرية مُعضِلةً، ومِن أضخم المشكلات الدولية، وتعدَّدت مناقشاتها في الأمم المتحدة، واكتسبت تعاطفًا دوليًّا متزايدًا على حساب تآكُلِ الهيبة الفرنسية عسكريًّا وسياسيًّا واقتصاديًّا، وتشكَّلت حكومة جزائرية مؤقتة في 19 سبتمبر 1958م برئاسة عباس فرحات، ولم يمضِ شهر واحد على تشكيلها حتى اعترفت بها 14 دولة. وفي نوفمبر 1959م أعلن الرئيس الفرنسي ديجول عن قبول فرنسا للمفاوضاتِ، فأعلنت الحكومة الجزائرية المؤقتة أنَّها كلفت الزعماء الجزائريين المختطَفين في فرنسا بإجراءِ المفاوضات حولَ تقرير المصير، فرفض ديجول هذا المقتَرَح. في مارس 1962م تم الاتفاقُ على إيقاف إطلاق النار بين الجيش الفرنسي وجبهة التحرير الجزائرية, ثم جرى استفتاء في 1 يونيو 1962م على استقلال الجزائر جاءت نتيجته 97.3% لمصلحة الاستقلال. وأُعلِنَ الاستقلال في 5 يونيو من نفس العام, وقامت الدولةُ الجزائرية برئاسة يوسف بن خده."},{"id":5214,"title":"تأسيس حلف بغداد .","date":["العام الهجري :1374","الشهر القمري : رجب","العام الميلادي :1955"],"text":"اقترحت أمريكا على إنجلترا أن تشكِّلَ أحلافًا عسكرية من الدوَلِ المحيطة بروسيا على أن تكونَ إنجلترا وأمريكا أعضاءً فيها؛ ليتمَكَّنوا من التدخُّلِ وقتما شاؤوا، واقترحت إنجلترا أن يكون المكانُ بغدادَ، فبدأت ولادة حلف بغداد، ودُعِيت له عدةُ دول غيرَ أنَّ بَعضَها رفض الحلف، وأخذ السياسيون ورجال التخطيط والمخابرات يتردَّدون على بغداد؛ من أجل الحلف وترتيباته اللازمة، وأخذوا يتَّصِلون بمن يقَعُ عليهم الاختيار. ووقَفَت سوريا ومصر والسعودية موقِفَ المعارض، ثم انضَمَّت بريطانيا للحِلفِ ثم باكستان ثم إيران، فعُزِل العراق بذلك عن بقية الدول العربية؛ مما أدى إلى توجيه النقد من قِبَلِ أحزاب المعارضة لحكومة نوري السعيد الذي كان وقتها رئيس الوزراء للحكومة العراقية."},{"id":5215,"title":"قيام منظمة دول عدم الانحياز .","date":["العام الهجري :1374","الشهر القمري : شعبان","العام الميلادي :1955"],"text":"بعد أن وضعت الحربُ العالميةُ الثانية أوزارَها، وظهَرَ في العالَمِ قُطبَان ثنائيَّان يتمثَّلُ في الولايات المتحدة التي تمثِّلُ المعسكر الرأسمالي والاتحاد السوفيتي الذي يقود المعسكر الشيوعي، وبدأ العالم يدخل فيما يُعرَفُ بالحرب الباردة بين القطبين، كما بدأت تتشَكَّلُ تكتُّلات أو أحلاف عسكرية تدورُ في فَلَك أحد القطبين، وفي ظِلِّ هذا الاستقطاب انبعثت حركةُ عدم الانحياز من قِبَلِ عددٍ مِن الدول التي تمكَّنَت من الاستقلال والتحرُّر من هيمنة الدول الاستعمارية في آسيا وأفريقيا وأمريكا اللاتينية، وأخذت تبحَثُ لها عن مكانة في الساحة الدولية، وقد كان يجمَعُ هذه الدول قاسمٌ مشترك هو معارضتُها لسياسة الارتباط بأحد المعسكرين، والسعي لتحقيق التنمية السياسية والاقتصادية والاجتماعية والثقافية لدولها بعيدًا عن الهيمنة الأجنبية، وفي 18 / 4 / 1955 عُقِدَ أوَّلُ مؤتمر لدول عدم الانحياز بمدينة باندونغ في أندونيسيا حضرته وفود 29 دولة."},{"id":5216,"title":"مؤتمر (باندونغ) والقضية الجزائرية .","date":["العام الهجري :1374","الشهر القمري : شعبان","العام الميلادي :1955"],"text":"عُقِدَ المؤتمر في أندونيسيا وأصدر قرارًا ينُصُّ على حق الشعب الجزائري والمغربي والتونسي في تقرير المصير والاستقلال. وقد تزامن ذلك مع انتصاراتِ جيش التحرير الوطني في الشمال بقسطنطينة، وفي المنطقة الغربية من الجزائر."},{"id":5217,"title":"مذابح الإسرائيليين في خان يونس بفلسطين .","date":["العام الهجري :1375","العام الميلادي :1955"],"text":"قام الإسرائيليون بقيادة إريل شارون في هذه السنة بمذبحة مروعة في خان يونس بفلسطين، أسفَرَت عن استشهاد 36 شخصًا، وإصابة 31 من المواطنين العزَّل."},{"id":5218,"title":"عودة السلطان محمد الخامس إلى عرش بلاده وإعلان استقلال المغرب .","date":["العام الهجري :1375","الشهر القمري : ربيع الآخر","العام الميلادي :1955"],"text":"لَمَّا رأت فرنسا أنَّ السيل صار كالتيار الجارف وزاد التأييدُ الدولي واستنكار أعمال فرنسا في المغرب وجرائمها فيه، اتصلت بالملك محمد الخامس في منفاه ووقَّعت اتفاقية مغربية فرنسية في \"إكس لي بان\" في شهر ذي الحجة 1374هـ / آب 1955م حدَّدت فيها كيفية عودته إلى بلاده، ثم في غُرة ربيع الثاني 1375هـ / نوفمبر 1955م أعيد إلى عرشه، ووقَّعَت فرنسا معاهدةَ الانسحاب من المغرب، وفي شعبان 1375هـ  وقَّعت إسبانيا اتفاقيةَ الخروج من المغرب، وبذلك توحَّدَت الأقسام الرئيسة، أما وثيقة الاستقلال فصَدَرت بعد متابعة المفاوضات بين الطرفين الفرنسي والمغربي في تاريخ 20 رجب 1375هـ / 2 آذار 1956م؛ حيث أعلِنَ إلغاءُ الحماية الفرنسية واستقلال المغرب ووحدة أراضيه."},{"id":5219,"title":"استقلال السودان .","date":["العام الهجري :1375","الشهر القمري : جمادى الأولى","العام الميلادي :1956"],"text":"كانت السودانُ مرتبطةً بمصر وتعَدُّ جزءًا منها؛ فحاكمُهما واحد، وسلطانهما واحد، فهي تابعة إداريًّا لمصر، ولكِنَّ هذا الارتباط كان يشكِّلُ أحيانًا عقبة أمام المصريين في مباحثاتهم مع الإنجليز بشأنِ الجلاء عن مصر، لذلك رأى الضباطُ الأحرار قادةُ انقلاب 23 يوليو 1952م / 1371هـ في مصر أنَّ علاج مشكلة السودان كفيلٌ بحَلِّ مشكلة الجلاء عن مصر، فقامت الحكومةُ المصرية بتقديم مذكِّرة للحكومة البريطانية بشأن الحُكمِ الذاتي للسودان وحقِّ تقرير مصيره، وتضَمَّنت بنودًا يتحصل من ورائها السودان على الحكم الذاتي، ثم أصدر القانون العام التفصيلي للحكم الذاتي الكامل في السودان، وأبلغت حكومة السودان دولتي الحكم الثنائي بقرار الجمعية التأسيسية بالرغبة في مزاولة حَقِّ تقرير المصير، وقبلت الدولتان مصر وإنجلترا قرارَ اللجنة، وفي 24 ربيع الأول 1375هـ / 9 نوفمبر 1955م جلت قوات الدولتين المصرية والإنجليزية عن الأراضي السودانية نهائيًّا، وتركت الحكومة المصرية جميعَ الأسلحة الثقيلة الخاصة بها إلى السودان، وفي 5 جمادى الأولى / 19 ديسمبر أصدر مجلِسُ النواب السوداني قرارًا يقضي بأن يُعَدَّ جلاء الجيوش عن أرضه استقلالًا له، فلا حاجة إلى إجراء استفتاء لاختيار نوع الحكم، وأعلنت الحكومة السودانية قيامَ الجمهورية السودانية رسميًّا في 1 يناير 1956، وقد أصبح السودان عضوًا في جامعة الدول العربية في 19 يناير، وفي الأمم المتحدة في 12 نوفمبر من نفس العام. وأبلغت مصر وبريطانيا بذلك ودعت الحكومة السودانية لانتخاب جمعية تأسيسية لتضع الدستورَ النهائيَّ للسودان."},{"id":5220,"title":"مشروع إصلاح التعليم بتونس .","date":["العام الهجري :1375","الشهر القمري : جمادى الآخرة","العام الميلادي :1956"],"text":"أعدَّ الفرنسيُّ جان دوبياس مديرُ التعليم الثانوي في تونس خطةً مِن ستين صفحة سُمِّيَت مشروع إصلاح التعليم بتونس، دعا فيها إلى إلغاءِ التعليم الأصلي الديني على اعتبار أنَّه مكَلِّف ماديًّا. وقوبل هذا المشروع بالرفضِ مِن الأمين الشابي وزير التربية القومية آنذاك، واستقال من منصبه لنفس السبب؛ لأنه كان من المتحمسِّين لعملية التعريب رافضًا بذلك \"مشروع إصلاح التعليم بتونس\" بروحه الفرنسية. وبالمقابل كان دوبياس يرى ضرورة التخلي عن نظام التعليم التقليدي؛ لأنه مكلِّف جدًّا، مع ضرورة مواصلة تدريس العلوم التقنية بالفرنسية في العشرية المقبلة."},{"id":5221,"title":"منح فرنسا تونس الاستقلال .","date":["العام الهجري :1375","الشهر القمري : شعبان","العام الميلادي :1956"],"text":"تم التوقيع على وثيقة الاستقلال التي أنهت الحمايةَ الفرنسية على تونس، والتي وقعها الحبيب بورقيبة مع فرنسا بعد أن ربط نفسَه وبلاده باتفاقيات ثقافية واقتصادية معها، وتم تكليفه بتشكيل حكومةٍ تبدأ بالبناء على أساس أنَّ البلاد قد حَصَلت على الاستقلال."},{"id":5222,"title":"قيام نظام جمهوري في باكستان .","date":["العام الهجري :1375","الشهر القمري : شعبان","العام الميلادي :1956"],"text":"كان حاكِمُ باكستان غلام محمد يعاني شللًا أفقده القدرةَ على العمل، فترك منصبه في 17 ذي الحجة 1374هـ / 1955م فقبض على السلطة الجنرال إسكندر مرزا، وفي 11 شعبان 1375هـ أُجريت الانتخابات العامة وتألفت جمعيةٌ تأسيسية لوضع الدستور، وكان أهم أعمالها أن وحَّدَت باكستان الغربية بعد أن كانت عددًا من المقاطعات، ثم جرت الانتخاباتُ الرئاسية وانتُخِب في 23 رجب 1375هـ إسكندر مرزا رئيسًا لباكستان، وفي 11 شعبان من العام نفسه أعلن الدستور، وقام النظام الجمهوري وانتهى نظام الدومنيون السابق، وأصبح اسمُ البلاد حسبما نص الدستور الأول: \"جمهورية باكستان الإسلامية\"."},{"id":5223,"title":"مقاطعة ليبيا دولة الاحتلال الإسرائلي في فلسطين .","date":["العام الهجري :1375","الشهر القمري : رمضان","العام الميلادي :1956"],"text":"طبَّقَت المملكة الليبية قانونَ مقاطعة دولة الاحتلال إسرائيل، وذلك بعد الضغوط الشعبية الكبيرة التي طالبَتْها بذلك، وقامت من أجلِ ذلك بإنشاء مكتب للمقاطعة في طرابلس."},{"id":5224,"title":"انتخاب جمال عبد الناصر لمنصب رئاسة الجمهورية المصرية  .","date":["العام الهجري :1375","الشهر القمري : ذي الحجة","العام الميلادي :1956"],"text":"في جمادى الآخرة 1375هـ / 16 يناير 1956م صدر الدستورُ المؤقَّتُ بمصر بعد نهاية المرحلة الانتقالية التي تولى فيها جمال عبد الناصر السلطة على إثرِ تنازُلِ محمد نجيب عام 1954م عن السلطة. أعلن جمال عبد الناصر عن نفسِه للترشُّح لرئاسة الجمهورية، ولم يرشِّحْ أحدٌ نفسَه، أو لم يجرؤْ أن يرشِّحَ أحدٌ نفسَه، وجرى الاستفتاء الشعبي لكسبِ الصفة الشرعية بناءً على الدستور فحصل على نسبة 99.999 % من الأصوات، وبذا أصبح رئيسًا للجمهورية وانتهت مهمة مجلس قيادة الثورة."},{"id":5225,"title":"جمال عبد الناصر يؤمم قناة السويس .","date":["العام الهجري :1375","الشهر القمري : ذي الحجة","العام الميلادي :1956"],"text":"كان أوَّلُ عمل رسميٍّ قام به جمال عبد الناصر بعد فوزِه برئاسة الجمهورية المصرية هو تأميم قناة السويس (أي نقل ملكيتها للحكومة من القطاع الخاص للعام)؛ ففي يوم 18 ذي الحجة /26 تموز 1956م وكان هذا الفعل منه ردًّا على وزير خارجية أمريكا جون فوستر دلاس في قولِه: إنَّ الاقتصاد المصري منهارٌ، ثم وضعت مصرُ يَدَها على أموال الشركة في البنك العثماني وقيمتها خمسة ملايين جنيه، وجمَّدت إنجلترا الحسابَ الجاري لمصر، وفرضت الحماية على أموال الشركة في لندن، وجمَّدَت فرنسا أرصدةَ مصر في البنوك الفرنسية، وكذلك جمَّدت أمريكا أرصدةَ مصر في بنوكها، كما رفضت فرنسا وإنجلترا دفعَ رسوم على سفُنِها التي تمرُّ في القناة وكانت من قَبلُ تدفع الرسوم للشركة القديمة في لندن وباريس."},{"id":5226,"title":"نشأة حركة الضباط الأحرار في العراق .","date":["العام الهجري :1376","العام الميلادي :1956"],"text":"بدأ العمل داخِلَ الجيش العراقي منذ عودته من فلسطين، فتشكَّلَت عدةُ مجموعات سرية أولُها نَظَّمَها الرائد \"رفعت الحاج سري\" عام 1952م، وقد انضَمَّ معه في التنظيم عددٌ من الضباط، على الرغم من تبايُنِ توجُّهاتِهم الفكرية، ثم تشكَّلت مجموعات أخرى من التنظيمات السرية، ثم اندمجت مجموعتا بغداد والمنصور في مجموعة واحدة وتولَّى قيادتها العميد عبد الكريم قاسم، وكان لقيادات هذه المجموعات صِلاتٌ مع قيادات بعض الأحزاب السياسية المعارضة أو بعض المسؤولين الكبار في الدولة، سواء كانوا مدنيين أو عسكريين؛ من أجل الدعم أو الحماية، فكان العميد عبد الكريم قاسم شديدَ الصلة برئيس الوزراء نوري السعيد حتى غدا من المقرَّبين إليه ويثِقُ به ولا يهتَمُّ بما يقال عنه، بينما كان عبد السلام عارف يتَّصِلُ بالفريق رفيق عارف ويتودَّدُ إليه حتى صار من أعوانه؛ يدافِعُ عنه ويحميه، وليس بينهما صلة قرابة، وإنما تشابُهٌ في اسم الأسرة. وتدريجيا صار أكثَرُ هؤلاء الضباط في هذه المجموعات على الرغم من تبايُنِ توجُّهاتهم الفكرية وتنوُّع انتماءاتهم يَعرِفُ بعضهم بعضًا، ويجمعهم هدف مشترك هو معارضة الحكم الملَكي القائم والرغبة في تغييره، فأطلقوا على أنفسهم \"الضبَّاط الأحرار\" نفس الاسم الذي تسمى به قادة ثورة 23 يوليو في مصر، ثم شكَّلوا لجنةً منهم لتنظيم الأمر أطلق عليها \"المنظمة المركزية\" دلالة على تأثرهم بالحركة الشيوعية، ووصل عدد أعضاء هذه المنظَّمة قبل الثورة بسنة 14 ضابطًا: اثنين عمداء، وستة برتبة مقدم، واثنين برتبة رائد. جميعُهم عرب، ولم يكن بينهم أيُّ كُردي، وأغلبهم سُنَّة عدا اثنين شيعة، وكانت أكثر اللقاءات تُعقَدُ في منزل الرائد الطيار محمد السبع، ولَمَّا لم يكن جميعُ أعضاء المنظَّمة المركزية أصحاب فكر واحد؛ لذا لا يمكن أن يتَّفِقوا على صيغة محددة للعمل بعد نجاح حركتِهم، وإنما اكتَفَوا بوضع خطوط عريضة أطلَقَ عليها اسم \"الميثاق الوطني\"، وكان هدفهم إنهاء الحكم الملكي في العراق."},{"id":5227,"title":"تشكيل \"هيئة المنتفعين\" لمعالجة مشكلة تأميم قناة السويس .","date":["العام الهجري :1376","الشهر القمري : محرم","العام الميلادي :1956"],"text":"قرَّرت أمريكا وفرنسا وإنجلترا عقدَ مؤتمر في لندن للدُّوَل البحرية المنتَفِعة من قناة السويس وعددُها ثمانٍ، موقعة على معاهدة استانبول إضافة إلى 16 دولة أخرى تنتفع من قناة السويس، وقرَّروا إنشاء هيئة دولية لإدارة القناة مع مصرَ تُعرَفُ بهيئة المنتفعين، مع الاعتراف بحق مصر في السيادة على القناة، وضمان دخل عادل لها، وتم إرسال لجنة برئاسة رئيس وزراء استراليا لإبلاغ عبد الناصر بالقرار غيرَ أنَّه رفض، فعرضت فرنسا وإنجلترا الأمرَ على مجلس الأمن الذي أصدر ست قراراتٍ وافقت مصر عليها وعُرِفَت فيما بعد بالمبادئ الست."},{"id":5228,"title":"اتفاقية التضامن بين مصر وسوريا والأردن والسعودية .","date":["العام الهجري :1376","الشهر القمري : ربيع الأول","العام الميلادي :1956"],"text":"عقد عبد الناصر اتفاقياتِ دفاع مشترك مع بعض الدولِ العربية، مثل سوريا والأردن والسعودية واليمن وذلك بعد أن رفَضَت كلٌّ من أمريكا وبريطانيا وفرنسا تمويلَ بناء السد العالي مما كان سببا في تأميمَ قناة السويس في 16 أغسطس 1956م من أجل الاستفادة من عائداتها لبناءِ السد العالي."},{"id":5229,"title":"العدوان الثلاثي (بريطانيا وفرنسا وإسرائيل) على مصر عام 1956م .","date":["العام الهجري :1376","الشهر القمري : ربيع الأول","العام الميلادي :1956"],"text":"بعد أن قام جمال عبد الناصر بتأميم قناة السويس، ورفضت فرنسا وإنجلترا دفعَ الرسوم على سُفُنِها، وتم الاتفاق مع ثمانية دول أخرى كلُّها من المنتفعين بالقناة؛ تم الاتفاق بينهم على إنشاء هيئةٍ عُرِفَت بهيئة المنتفعين؛ بهدف تولي إدارة القناة مع اعترافهم بسيادة مصر عليها، وأصدر مجلِسُ الأمن قراراتٍ أخرى قبلتها مصر إلَّا أن فرنسا وإنجلترا أصرَّتا على قرار هيئة المنتفعين، وبدأ الاستعدادُ بين هذه الدول بالإضافة إلى إسرائيل على عملٍ عسكري ضِدَّ مصر، وفي يوم 25 ربيع الأول 1376هـ / 29 أكتوبر من يوم الاثنين قامت إسرائيلُ بالهجوم على سيناء وأنزلت المظليين عند ممر متلا، وأرسلت إنجلترا وفرنسا إنذارًا لكل من مصر وإسرائيل بسَحبِ قوَّاتِهما بعيدًا عن القناة بما لا يقِلُّ عن عشرة أميال، وأن قوات فرنسا وإنجلترا ستحتَلُّ النقاط الرئيسة في كلٍّ من بور سعيد والإسماعيلية والسويس لضمان الملاحة بالقناة لجميع سفُنِ العالم، فانسحبت القواتُ المصرية من سيناء وبدأت الغاراتُ على القاهرة، واستمَرَّت يومين، ودمَّرت الطائراتِ المصريةَ بضربة واحدةٍ! كما ازدادت الغاراتُ على بورسعيد، فتقرر الانسحاب منها، وبعد أن توقَّف إطلاقُ النار وانسحبت فرنسا وإنجلترا في جمادى الأولى 1376هـ / 23 ديسمبر، وبعد ثلاثة أشهر انسحبت إسرائيل ولكن بَقِيَت قوة دولية في شرم الشيخ كي تتمكَّن إسرائيل من الملاحة في خليج العقبة، والانطلاق منه إلى البحر الأحمر فشرقي إفريقيا وجنوبي آسيا وشرقيها."},{"id":5230,"title":"وفاة الشيخ العلامة عبد الرحمن بن سعدي .","date":["العام الهجري :1376","الشهر القمري : جمادى الآخرة","العام الميلادي :1957"],"text":"هو الشيخُ العلامة أبو عبد الله عبد الرحمن بن ناصر بن عبد الله بن ناصر بن حمد آل سعدي، من بني تميم. وُلِدَ في عُنيزة في القصيم في 12 محرم سنة 1307هـ. نشأ الشيخُ يتيمًا؛ فقد توفِّيَت أمُّه وله من العمر أربع سنوات، ثم توفِّيَ والِدُه وهو في السابعة، لكنه نشأ نشأةً صالحة، وقد أثار إعجابَ مَن حوله فاشتهر منذ حداثته بفطنته، وذكائه، ورغبته الشديدةِ في طلب العلم وتحصيله، فحَفِظَ القرآن عن ظهر قلبٍ وعمُرُه أحد عشر عامًا، ثم اشتغل بالعلم على يد علماءِ بلَدِه حتى نال الحظَّ الأوفر من كل فَنٍّ من فنون العلم، ولَمَّا بلغ من العمر ثلاثًا وعشرين سنة جلس للتدريسِ، فكان يَتعلَّمُ ويُعلِّمُ، ، وكان من أحسَنِ الناس تعليمًا وأبلَغِهم تفهيمًا، حصل له من التلاميذ المحصلين عددٌ كثير. كان ذا معرفةٍ فائقة في الفقه وأصوله، وكان أوَّلَ أمره متمسِّكًا بالمذهب الحنبليّ تبعًا لمشايخه، ويحفظ بعضَ متون المذهب. وكان أعظَمُ اشتغاله وانتفاعه بكتُبِ شَيخِ الإسلام ابن تيمية، وتلميذه ابن القيم، وحصل له خيرٌ كثير بسببهما في علم الأصول والتوحيد، والتفسير، وغيرها من العلوم النافعة. وبسبب استنارتِه بكُتُبِ الشيخين المذكورين صار لا يتقيَّدُ بالمذهب الحنبلي، بل يرجِّحُ ما تَرَجَّحَ عنده بالدليل الشرعي، أما مُصنَّفاتـه، فكان ذا عنايةٍ بالغة بالتأليف، فشارك في كثير من فنون العلم، فألَّف في التوحيد، والتفسير، والفقه، والحديث، والأصول، والآداب، وغيرها. وأغلَبُ مؤلَّفاته مطبوعة إلا اليسير منها؛ أشهرها: ((تيسير الكريم الرحمن في تفسير كلام المنان))، طبعت مؤلفاته في مجموع بعنوان ((مجموع مؤلفات الشيخ العلامة عبد الرحمن بن ناصر السعدي)) في 27 مجلدًا. توفي رحمه الله في عُنَيزة بالقصيم بعد عمر دام تسعًا وستين سنة قضاها في التعلُّم والتعليم والتأليف."},{"id":5231,"title":"إعلان إسرائيل سحب قواتها من قطاع غزة ومنطقة خليج العقبة .","date":["العام الهجري :1376","الشهر القمري : رجب","العام الميلادي :1957"],"text":"أعلنت إسرائيلُ سَحْبَ قوَّاتِها من قطاع غزة ومنطقة خليج العقبة، على افتراض أنَّ حرية المرور ستستمرُّ في خليج العقبة، وأنَّ قوات الطوارئ التابعة للأمم المتحدة ستُديرُ قِطاعَ غزة حتى يتِمَّ الاتفاق على تسوية سِلمية."},{"id":5232,"title":"الاتحاد القومي المصري الناصري .","date":["العام الهجري :1376","الشهر القمري : شوال","العام الميلادي :1957"],"text":"أسَّس جمال عبد الناصر الاتحادَ القوميَّ كتجَمُّع سياسي يحكُمُ عن طريقه البلد، وقد بَعَث علي صبري إلى البرتغالِ لدراسة الاتحاد القومي هناك الذي نظَّمَه \"سالازار\" طاغية البرتغال. وقد نصَّ دستور عام 1956م على هذا التنظيم، وذكر أن هذا التجمُّع سياسيٌّ يعمَلُ على تحقيق الأهداف التي قامت من أجلها ثورة يوليو عام 1952م، ولم يكُنْ هذا التنظيم حزبًا سياسيًّا كما جرت العادة، وإنما كان تنظيميًّا حكوميًّا؛ حيث تتحمَّلُ خزينة الدولة كامِلَ نفقاته. وقد أعلن عن قيام هذا التنظيم في 29 شوال / 28 أيار, وتولَّى أنور السادات منصِبَ الأمين العام له، ثم رأى جمال عبد الناصر غيرَ ذلك، فأصدر مرسومًا بتعيين كمال الدين حسين مُشرِفًا عامًّا عليه، يُمارِسُ أعمال الأمين العام، وكان شعارُ هذا التجمع السياسي الحكومي \"اشتراكيَّتُنا اشتراكيةُ تمليكٍ، وليست اشتراكيةَ مُصادرة\" وهذا يعني أن التنظيم كان اشتراكيًّا من نوع جديد، ولم يَطُل عمر هذا الاتحاد القومي؛ إذ حُلَّ مع قيام الوحدة بين مصر وسوريا."},{"id":5233,"title":"تشكيل أول حكومة ذات استقلال ذاتي صوري في موريتانيا .","date":["العام الهجري :1376","الشهر القمري : شوال","العام الميلادي :1957"],"text":"استمَرَّت المقاومة في موريتانيا ولم تهدأ رغمَ سُقوطِ الدولة العثمانية، ورغْم استطاعة الفرنسيين بَسْطَ سيطرتهم ونفوذِهم على البلاد بسبَبِ تفوُّقِهم العسكري في الرجال والسلاح. وفي أثناء أحداثِ الحرب العالمية الثانية بدأت بوادِرُ الدعوة للاستقلال بالظهور؛ إذ برز حزبان هما: حزب الاتحاد الوطني، وحزب منظمات الشباب. بعد ذلك انحصرت مطالِبُ الحزبين بالمطالبة بالاستقلال المباشر، فتوحَّدا في حزب واحد عام 1367هـ وهو حزب التفاهم الموريتاني، إلَّا أن الانقسامَ عاد من جديد فظهر حزب التفاهم الموريتاني بزعامة أحمد بن حرمة بابانا. وحزب الاتحاد التقدمي الموريتاني بزعامة المختار أنجاي. وأجريت انتخاباتٌ عامة لاختيار نائب في الجمعية الوطنية الفرنسية بباريس (حسب نص دستور فرنسا على أن يكون أعضاء مجلس الجمعية الوطنية من الوحدات الإقليمية) ففاز المختارُ أنجاي بالنيابة في عام 1376 هـ. أما أحمد بن حرمة فقد غادر موريتانيا ليعيشَ في المغرب بعد عودة الملك محمد الخامس من المنفى. بعد ذلك زادت المطالبةُ بالاستقلال؛ فعُقِد في منتصف عام 1379 /1958 مؤتمَرٌ في عاصمة مالي باماكو. وكان من مقرراته ضرورةُ اعتراف فرنسا بحق تقرير المصير؛ إذ كانت تخشى اندلاع الثورات كما حدث في الجزائر. فأصدر رئيس وزراء فرنسا «غي موليه» قانونَ الإصلاح الإداري عام 1376 / 1957 والذي نصَّ على إجراء انتخابات في كلِّ إقليم؛ لاختيار جمعية عامة تتولى تشكيل الحكومة. وفي 21 شوال 1376ه / 20 أيار 1957 تشكَّلت أولُ حكومة ذات استقلال ذاتي في موريتانيا. وأوجدت السلطاتُ الفرنسية نظامًا خاصًا أسمته استقلالًا داخليًّا؛ حيث عَيَّنَت إلى جانب الحاكم العام شخصًا موريتانيًّا اسمه نائب رئيس المجلس، وكانت الحكومةُ صوريَّةً."},{"id":5234,"title":"إلغاء نظام الباي في تونس وإعلان الجمهورية .","date":["العام الهجري :1376","الشهر القمري : ذي الحجة","العام الميلادي :1957"],"text":"حصلت تونس على الاستقلالِ في عام 1375هـ ثم شكَّلَ الحبيب بورقيبة الوزارةَ، وكان همُّه الأول ترسيخَ قواعده والعمَلَ على التخلص من مُناوئيه؛ لذا فقد عَمِلَ قَبلَ كُلِّ شَيءٍ على تصفية خصومه السياسيين، وفي 28 ذي الحجة 25 تموز ألغى منصِبَ الباي (النظام الملكي) وأعلن الجمهوريةَ وتسَلَّمَ مَنصِبَ الرئاسة."},{"id":5235,"title":"منح الأمير فيصل بن عبدالعزيز صلاحيات إدارة شؤون الدولة .","date":["العام الهجري :1377","العام الميلادي :1957"],"text":"وَلِيَ الأمير فيصل بن عبدالعزيز ولايةَ العهد ورئاسةَ مجلس الوزراء في عام 1373هـ، وفي هذا العام أُعطيت له صلاحيات مطلقة في الأمور الإدارية والمالية والخارجية، وصدر بذلك مرسوم ملكي."},{"id":5236,"title":"مذابح المسلمين في الصين بكاشغر \"تركستان الشرقية\" .","date":["العام الهجري :1377","العام الميلادي :1957"],"text":"بدأت مأساةُ المسلمين في الصين الشيوعية منذ عام 1954م حين حاربت الصينُ الشيوعية الإسلامَ، وذلك بتعطيل المساجد، وسَجْنِ العلماء أو قتلِهم، كما قامت الصينُ الشيوعية بتقسيم تركستان الشرقية، وتهجير المسلمين منها، وقتلت منهم 360 ألف مسلمٍ في مدينة كاشغر في معركةٍ مع الشيوعيِّين."},{"id":5237,"title":"الوحدة العربية بين مصر وسوريا .","date":["العام الهجري :1377","الشهر القمري : رجب","العام الميلادي :1958"],"text":"قام وفدٌ نيابيٌّ من سوريا بزيارة مصر ودعا إلى الوَحدةِ بين الدولتين العربيتين وبادلهم وفدٌ مصري الزيارةَ، وكان جمال عبد الناصر يريد الاتحادَ ولا يرى الدَّمجَ، يعني الوحدة، غير أنَّ الوضع في سوريا كان قلقًا جِدًّا، وكان الشعب يريدُ الوَحدةَ؛ لعله يتخَلَّصُ مِمَّا هو فيه من التسلُّطِ العسكري وتحكُّم البعثيِّينَ والشيوعيِّين، وكان رئيسُ الأركان السوري عفيف البزري ذو الميول الشيوعية يعرِفُ رغبة جمال في الاتحاد لا الوحدة، فأراد أن يقترح الوَحدةَ فيرفُضَها جمال فينفردَ هو بسوريا، لكنَّ جمالًا رَضِيَ بالوحدة، وربما أدرك نوايا عفيف، فتم الاتفاقُ على الوحدة في 12 رجب 1377هـ / 1 شباط، وعَيَّن جمال أربعة نواب لرئيس الجمهورية: اثنان من مصر، واثنان من سوريا، أما الوزارة فكانت مركزيةً في القاهرة التي أصبحت عاصِمةَ الجمهورية العربية المتحدة، وهو الاسم الذي اختير لهذه الوَحدة، وأما المجلِسُ التنفيذي ففي القاهرة، وآخر في سوريا، وأطلق على مصر الإقليم المصري أو الجنوبي، وعلى سوريا الإقليم السوري أو الشمالي."},{"id":5238,"title":"الاتحاد العربي بين العراق والأردن .","date":["العام الهجري :1377","الشهر القمري : رجب","العام الميلادي :1958"],"text":"بعد أن قامت الوحدة بين سوريا ومصر في رجب من عام 1377هـ / 1 شباط 1958م،كان لهذه الوحدةِ أثَرٌ على العراق والأردن، فاقترح وزيرُ الخارجية البريطانية سلوين لويد إقامةَ اتحاد بين العراق والأردن، واجتمع فعلًا الوفدان العراقي والأردني في عمان، وكان الأردن قد اشترط لتحقيقِ الاتحاد أن تنسَحِبَ العراق من حلف بغداد، لكِنَّ العراق رفض ذلك، فبَقِيَ العراق في حلفه وبقيت الأردن في هدنتها مع إسرائيل، وتم الاتفاقُ بين الطرفين على إنشاء اتحادٍ عربي بين المملكة العراقية والمملكة الأردنية الهاشمية، باسم الاتحاد العربي اعتبارًا من 24 رجب 1377هـ الموافق 14 شباط، ويكون مفتوحًا لأي دولة عربية تريد الانضمامَ إليه، ويكون مَلِكُ العراق رئيسًا لحكومة الاتحاد، ومقر الاتحاد بغداد ستة أشهر، وفي عمان ستة أشهر، وغيرها من البنود، علمًا أن دول حلف بغداد لم تكن راضيةً عن هذا الاتحاد."},{"id":5239,"title":"وفاة الشيخ أبي الكلام آزاد الهندي .","date":["العام الهجري :1377","الشهر القمري : شعبان","العام الميلادي :1958"],"text":"هو الشيخُ أبو المكارم محيي الدين أحمد بن خير الدين الهندي المشهور بلقب \"أبو الكلام آزاد\", من أسرة أفغانية هاجرت إلى الهند زمنَ الإمبراطور بابر مؤسِّس الدولة المغولية، ولِدَ بكلكتا عام 1306هـ / 1888م وبها استتَمَّ دراستَه الأولية. وقصد الأزهرَ في الرابعة عشرة من عمره، فدرس على علمائِه ودرَّس في خارجه، ثم عاد إلى وطن أبيه (الهند) فسكن كلكتا، وقد أخذ كنيةَ أبي الكلام لكونِه خطيبًا بارعًا، أما كلمة آزاد فتعني في اللغة الأردية \"الحـَّر\"، تربَّى تربية صوفية، وأتقن الإنجليزية والفارسية وتنقَّل بين كلكتا وبومباي، كما زار القاهرة وتركيا وفرنسا، وقد تأثَّر برشيد رضا، وكان من أعضاء حزب المؤتمر الهندي الذي أقرَّ برنامج المهاتما غاندي القائل بالمقاومة السلبية. ثم كان مستشارًا للبانديت نهرو. قام بتأسيس جماعةٍ دينية في كلكتا سماها \"حزب الله\"، ثم أسَّس مدرسة سماها \"دار الرشاد\"، وقام بإصدار مجلة \"الهلال\" في 1912، وبلغت كمية توزيعها 25 ألف نسخة أسبوعيًّا، وهو عددٌ ضَخمٌ جِدًّا في تلك الفترة. وهاجم الاستعمارَ البريطاني فاعتقله الإنجليزُ (المستعمرين للهند في ذلك الوقت) وقاموا بمنعِ إصدار المجلة في 1915. وسرعان ما أصدر أبو الكلام في نفسِ العام مجلةً أخرى هي مجلة البلاغ، لكِنَّها مُنعت أيضًا. ثم تمَّ إبعاده عن كلكتا ومُنِعَ من دخول ولايات البنجاب ودلهي وبومباي؛ فقد حصل له القَبولُ العظيم في بلاد الهند لمهارته في أساليب الكلام، فقصد البنغال، وقد تكرر اعتقال البريطانيين له. ولم يصرِفْه ذلك عن هدفه في مقاومة الإنجليز، واستقَرَّ بمدينة \"رانشي\" التي كتب فيها تفسيره للقرآن الكريم، وترجم معانيه إلى اللغة الأردية. وقد تعرَّض بعد ذلك للسجن لمدة ثلاث سنوات ونصف حتى العام 1920. وتولَّى رئاسة حزب المؤتمر بدلهي 1923 و 1939م، تحول أبو الكلام من مصلح ديني وداعية إسلامي إلى زعيم وطني وقائد سياسي، وقد صرف فكرَه ونشاطَه -بعدما رأى تفكُّك الوحدة بين الشعوب الإسلامية- من المجال الإسلامي إلى المجال الوطني. وفي سنة 1356هـ ألَّفَ حزب المؤتمر الوطني الوزارةَ في عدة ولايات هندية، وكان أبو الكلام من كبارِ المشرفين والموجِّهين في هذا التأليف، له الكلمة النافذة والرأي الوجيه في اختيار الوزراء، واستقالت هذه الوزارةُ سنة 1358هـ، وقد قَوِيَت حركة العصبة الإسلامية في هذه المدة ومطالبتها بانفصال باكستان، وثار المسلمون في جميع البلاد الهندية في تأييد هذه الفكرة، وتعَرَّض أبو الكلام وزملاؤه الذين كانوا يعارضون هذه الفكرة، ويدعون إلى فكرة الهند غير المنقسِمة للسَّخَط العام من المسلمين، واكتسحت فكرةُ الانفصال الكثرة من المسلمين، وبقي أبو الكلام على مبدئه وفكرته، وأصرَّت العصبة الإسلامية تحت قيادة رئيسها محمد علي جناح على المطالبةِ بالتقسيم، فحصل الانقسام، كان أبو الكلام مع عِلمِه بالعربية يكتُبُ تآليفه ومجلاته ومقالاته بالأردية، وقد تُرجِمَ بعضها إلى العربية، وكان قد صَنَّف في السجن كتابه (التذكرة) بالأردية، سجَّل فيه فلسفته الثورية، وعقيدته السياسية. بعد تولي أبي الكلام وزارة المعارف في الحكومية المركزية انطوى على نفسه بعيدًا عن المجامع الشعبية، حتى وافته المنية رحمه الله في دلهي، وصلى عليه جمع كبير من المسلمين."},{"id":5240,"title":"وفاة الشيخ المحقق أحمد شاكر .","date":["العام الهجري :1377","الشهر القمري : ذي القعدة","العام الميلادي :1958"],"text":"هو الشَّيخُ الأستاذ العلَّامة المحَدِّث أبو الأشبال أحمد بن محمد شاكر بن أحمد بن عبد القادر من آل أبي علياء. وُلِدَ بعد فجر يوم الجمعة في 29 جمادي الآخرة سنة 1309هـ / 1892م بالقاهرة، ووالده هو العلَّامة الشيخ محمد شاكر، لَمَّا عُيِّن والده الشيخ محمد شاكر قاضيًا بقضاءِ السودان سنة 1900م أخذه معه وأدخله كلية غوردون، فبقي بها حتى عودة والده إلى الإسكندرية سنة 1904م، فالتحق بمعهد الإسكندرية. وفي سنة 1327هـ / 1909م عُيِّن والده الشيخ محمد شاكر وكيلًا لمشيخة الأزهر، فالتحق الشيخُ أحمد شاكر وأخوه علي بالأزهر، فاتَّصَل بعلماء القاهرة ورجالها، وعرف طريقَه لدُور الكتب العامة والمكتبات الموجودة في مساجدها. ومن أشهر العلماء الذين استفاد منهم: والِدُه العلامة محمد شاكر، وكان أعظَمَ الناس أثرًا في حياته. والشيخ عبد السلام الفقي، تعلم منه كتُبَ الأدب واللغة والشعر، والشيخ محمود أبو دقيقة، تعلم منه الفقه وأصوله بالإضافة إلى أنه تعلَّم منه الفروسية، والرماية، والسباحة، وعلامة الشام الشيخ جمال الدين القاسمي، وعلَّامة المغرب ومحدِّثُها الشيخ عبد الله بن إدريس السنوسي، وقد أجازه برواية صحيح البخاري وبقية الكتب الستة، والشيخ طاهر الجزائري من كبار علماء الشام، والعلَّامة محمد رشيد رضا، كما أخذ عن الشيخ محمد بن الأمين الشنقيطي كتابَ بلوغ المرام، وحصل على شهادة العالمية بالأزهر سنة 1917م، فعيِّن مدرِّسًا بمدرسة ماهر. ثم عُيِّن عضوًا بالمحكمة الشرعية العليا، وظَلَّ في سلك القضاء حتى أحيلَ إلى التقاعُد سنة 1951م. عمل مشرفًا على التحرير بمجلة الهدْي النبوي سنة 1370هـ، ولما كانت سنة 1911م اهتمَّ بقراءة مسند الإمام أحمد بن حنبل، وظَلَّ منذ ذلك التاريخ مشغولًا بدراسته حتى بدأ في طبع شرحه على المسنَدِ سنة 1365هـ / 1946م بعد أن ظَلَّ في دراسته 35 سنة، وعاجلَتْه المنية دون أن يتمكَّنَ من مراجعته، تولى القضاءَ في مصر أكثر من ثلاثين سنة، وكان له فيها أحكامٌ مشهورة في القضاء الشرعي، قضى فيها باجتهادِه غيرَ مقلِّدٍ ولا متَّبِع. حقق كتاب ((الرسالة)) للشافعي، وكتاب ((الشعر والشعراء)) لابن قتيبة، و ((لباب الأدب)) لأسامة بن منقذ، وشرح كتاب الحافظ ابن كثير اختصار علوم الحديث، وله كتاب ((عمدةُ التفسير))، وهو تهذيب لتفسير ابن كثير، وله تحقيقُ ((الإحكام)) لابن حزم، وجزأين من المحلى لابن حزم، و ((العمدة في الأحكام)) للحافظ عبد الغني المقدسي، ومن كتبه كتاب ((نظام الطلاق في الإسلام))، دلَّ فيه على اجتهاده وعدم تعصُّبِه لمذهب من المذاهب، و ((الكتاب والسنة يجب أن يكونا مصدر القوانين)) و ((كلمة الفصل في قتل مدمني الخمر)). وللشيخ أحمد جهودُه في المجال السياسي والاجتماعي، فقد عاش الشيخ في فترة امتازت بكثرة الأحداث وتواليها، والدول الإسلامية تئِنُّ تحت نِيرِ الاستعمارِ الإنجليزي والفرنسي، واليهود يخطِّطون لاحتلال فلسطين، فانبرى الشيخُ للتصدي لكل الأفكار الهدَّامة متمسِّكًا بكتاب الله ملتَزِمًا بعقيدة السلف، يقارعُ الأعداء وتلامذة الغرب من المستشرقين دون أن تلينَ له قناة أو تخور له عزيمة، مع قلةٍ من أمثاله من الرجال، وصار يدبِّج ببراعة مقالاتٍ نفيسةً وتعليقاتٍ مفيدةً على بعض ما حقَّقه من الكتب، وتصدَّى للمبتدعين والخرافيين والمستشرقين وغيرهم، وتوفي الشيخ أحمد رحمه الله في السادسة بعد فجر يوم السبت 26 ذي القعدة 14 يونيه."},{"id":5241,"title":"ثورة عبد الكريم قاسم وانتهاء الحكم الملكي في العراق .","date":["العام الهجري :1377","الشهر القمري : ذي الحجة","العام الميلادي :1958"],"text":"نشأت \"حركة الضباط الأحرار\" عام 1376هـ تحت قيادة عبد الكريم قاسم ذو الميول الشيوعية، وعبد السلام عارف ذو الميول الإسلامية، وقد قامت الحركةُ بعدة محاولاتٍ لقَلبِ نظام الحُكمِ لكِنَّها فَشِلت، إلى أن تمكنت من توجيه ضربة قاضية ضِدَّ الحكم الملكي، فقتلت كلًّا من الملك فيصل الثاني بن غازي ملك العراق، والوصي عليه خاله عبد الإله بن علي، ونوري السعيد رئيس الحكومة، وسيطرت على الوَضعِ ورحَّبت بعض الدولُ العربية بالحركة الانقلابية، ثم قامت عملياتٌ عسكرية احتَلَّ فيها عبد السلام عارف بغدادَ، وأعلن بنفسه من إذاعة بغداد قيامَ الجمهورية العراقية، ثم أعلن مجلِسُ قيادة الثورة المعروف بمجلس السيادة تعيينَ عبد الكريم قاسم رئيسًا أعلى للقوات المسلحة، ومُنِحَ صلاحيات واسعة، كما عُيِّن رئيسًا للوزراء لحكومة مدنية مؤقتة، ووزيرًا للدفاع بالوكالة، كما عين عبد السلام عارف مساعدًا له في رئاسة القوات المسلحة، ونائبًا له في رئاسة الحكومة، ووزيرًا للداخلية بالوكالة، وكانت كلُّ البيانات تَصدرُ باسم مجلس السيادة، وخرجت المظاهراتُ المؤيِّدة، وأيَّدَت الجمهورية العربية المتحدة (مصر وسوريا) الوضعَ بكُلِّ ثِقلِها، وأعلنت استعدادَها للدَّعمِ، وتسلَّم عبد الكريم قاسم السلطةَ وبدأ يُصدِرُ القرارات وإعلان الأحكامَ العُرفيةَ، ومصادرة الأملاكَ الملَكيَّة."},{"id":5242,"title":"وفاة نوري السعيد رئيس حكومة العراق .","date":["العام الهجري :1377","الشهر القمري : ذي الحجة","العام الميلادي :1958"],"text":"هو نوري بن سعيد بن صالح ابن الملا طه، من عشيرة القره غولي البغدادية رئيس حكومة العراق. سياسيٌّ عَسكريُّ المنشأ، فيه دهاء وعنف. ولدَ ببغداد سنة 1306هـ / 1888م، وتعلَّم في مدارسها العسكرية. وتخرَّج بالمدرسة الحربية في الأستانة (1906) ودخل مدرسة أركان الحرب فيها عام 1911م، وحضر حرب البلقان 1912 – 1913م، وشارك في اعتناق \"الفكرة العربية\" أيام ظهورها في العاصمة العثمانية. فكان من أعضاء جمعية العهد السرية. وقامت الثورة في الحجاز 1916م ولحِقَ بها، فكان من قادةِ جيش الشريف فيصل بن الحسين في زحفه إلى سورية. ودخل قبله دمشق. وآمن بسياسة الإنجليز. فكان المؤيِّدَ لها في البلاط الفيصلي بسورية ثم في العراق، ومجاهرًا بذلك إلى آخر حياته. تولى رئاسة الوزارة العراقية مراتٍ كثيرةً في أيام فيصل وابنه غازي وحفيده فيصل بن غازي، وائتلف مع عبد الإله بن علي: الوصي على عرش العراق في أيام فيصل الثاني. وقامت الثورة في بغداد 14 يوليو 1958م، فكان فيصل وعبد الإله من قتلاها. واختفى نوري يومًا أو يومين، ثم خرج في زيِّ امرأة، فعرفه بعضُ أهل بغداد، فقتلوه، وقيل إنه انتحر عندما اكتشفوه, وله آثارٌ كتابية مطبوعة، منها: أحاديث في الاجتماعات الصحفية، واستقلال العرب ووحدتهم، ومحاضرات عن الحركات العسكرية للجيش العربيِّ في الحجاز وسورية."},{"id":5243,"title":"وفاة الشيخ حافظ الحكمي .","date":["العام الهجري :1377","الشهر القمري : ذي الحجة","العام الميلادي :1958"],"text":"هو الشيخُ العلَّامة حافظ بن أحمد بن علي الحكمي، ولد في 24 رمضان سنة 1342هـ في قرية السلام في جازان، نشأ بدويًّا يرعى الغَنَم. بدأ تعلُّمَه في سن مبكرةٍ، وكان آيةً في الحِفظِ؛ فحفظ القرآن وبعض المتون وهو يرعى الغنم صغيرًا، ثم قيَّض الله له الداعية الشيخ عبد الله القرعاوي الذي اهتَمَّ به فأفاده من علومِه وفقهِه، ثم اشتهر بالعلمِ ولمع نجمُه، حتى أصبح معلِّمًا، ثم تولى النيابةَ في إدارة مدارس التعليم بسامطة، ثم عُين مديرًا للمعهد العلمي فيها 1374هـ، واستمَرَّ إلى أن توفِّيَ بمكة. ومن مؤلَّفاته: ((سُلَّم الوصول إلى علم الأصول)) في فن التوحيد، وهي منظومة شرحها في ((معارج القبول))، و ((أعلام السنة المنشورة لاعتقاد الطائفة المنصورة))، و ((دليل أرباب الفلاح لتحقيق فن الاصطلاح)) في مصطلح الحديث، و ((اللؤلؤ المكنون في أحوال الأسانيد والمتون))، وهو نظم فريد، و ((السبل السوية لفقه السنن المروية))، وهو نظم أيضًا، فقد كان بارعًا في النظم والشعر، وغيرها، ومعظَمُ مؤلَّفاته طُبِعَت على نفقة الملك سعود رحمه الله، وأما وفاته رحمه الله فكانت في اليوم 18 ذي الحجة على إثر مرض ألمَّ به وهو في الخامسة والثلاثين من عمره ودُفِنَ بمكة المكرمة."},{"id":5244,"title":"الخلاف بين قيادات ثورة تموز عبد الكريم قاسم وعبد السلام عارف .","date":["العام الهجري :1377","الشهر القمري : ذي الحجة","العام الميلادي :1958"],"text":"كان الخلافُ بين عبد الكريم قاسم ذو الميول الشيوعية وعبد السلام عارف أبرَزَ مشاهد الصراع على السلطة بين قادة (الضباط الأحرار)؛ فقد بدأ الخلافُ بينهما من اليوم الأول؛ إذ يعدُّ كل واحدٍ منهما نفسَه أنه هو الذي أنشأ الحركةَ وقادها، فعبد الكريم قاسم رأسُ المنظَّمة ومنه تَصدُرُ الأوامر، وهو الذي يرى نفسَه أنَّه هو المُخطِّط لهذه الثورة، ولا يتِمُّ عمَلٌ دونه، ويرى عبد السلام عارف أنه هو الذي قاد الحركة وخاطر، وتسلَّم الإذاعةَ، وهو أوَّلُ من أذاع نبأ الحركة إلى الرعيَّة، وأعطى التعليماتِ اللازمة للسيطرة على الموقف، وكان عبد السلام يدعو إلى الوَحدةِ العربية الشاملة والانضمام إلى الجمهورية العربية المتَّحِدة، كما أنه كان معجبًا بعبد الناصر؛ ولم يكن قاسم يرى ما يراه عبد السلام، ولَمَّا زار عبد السلام دمشق بعد الثورة بخمسةِ أيام عرض على عبد الناصر الوَحدةَ فلما سأله عن رأي عبد الكريم قاسم قال له: مصيرُه مصيرُ محمد نجيب! ولَمَّا عَلِمَ قاسم بهذا الحوار أسَرَّها في نفسه، ثم قام عبد السلام بجولةٍ في أنحاء العراق وكان يُلقي خُطبًا وينقل للجموع تحيات الرئيس جمال عبد الناصر كأنه رئيس البلاد دون أن يذكُرَ عبد الكريم قاسم زعيم العراق، فأخذ قاسِمٌ في إبعاد عبد السلام عن مركز القيادة في البلاد تدريجيًّا، فألغى منصب عبد السلام كنائب قائد القوات المسلحة بحُجَّةِ أنَّ عددًا من الضباط أصحاب رتب أعلى منه، ثم عزله عن منصب نائب رئيس الوزراء ووزير الداخلية بالوكالة للمصلحة العامة، وفي نفس اليوم أصدر قرارًا بتعيينه سفيرًا للعراق في ألمانيا الغربية، لكِنَّ عبد السلام رفض هذا المنصب وأصرَّ على البقاء في بغداد، وفي 25 جمادى الأولى 1378هـ ألقت الشرطةُ القبض على عبد السلام عارف بتهمة محاولة قتل عبد الكريم قاسم، وأودِعَ السجنَ ثم حُكِمَ عليه بالقتل، لكن قاسم لم يصادق على الحُكمِ وبَقِيَ في السجن إلى أن أفرجَ عنه قاسم في ربيع ثاني 1381هـ وقد أحيل بعضُ أعوان عبد السلام عارف إلى التقاعُدِ والبعض نُقِلوا إلى مراكز غير حسَّاسة، أما الشيوعيون منهم فقد التفُّوا حول قاسم."},{"id":5245,"title":"استقلال غينيا  .","date":["العام الهجري :1378","الشهر القمري : ربيع الأول","العام الميلادي :1958"],"text":"جرت الانتخاباتُ المحلية في غينيا عام 1377هـ / 1957م إثرَ مؤتمر باماكو الذي ضَمَّ ممثِّلي أفريقيا الغربية، وكان من مقرراته اعترافُ فرنسا بحَقِّ تقرير المصير لشعوب المنطقة، وفاز في غينيا حزبُ غينيا الديمقراطي، واحتفلت غينيا باستقلالها في 19 ربيع الأول / 2 أكتوبر بعد استعمارٍ دام قرنًا من الزمن، وكان أوَّلُ رئيس لغينيا الرئيس أحمد سيكوتورى، وغينيا من دول أفريقيا ذات الأغلبية المسلمة."},{"id":5246,"title":"حركة رشيد عالي الكيلاني ضد عبد الكريم قاسم  .","date":["العام الهجري :1378","الشهر القمري : ربيع الأول","العام الميلادي :1958"],"text":"نتيجةً لاستبداد عبد الكريم قاسم بالسلطة وإقصاء غيرِ الشيوعيين من زملاء الثورة جرت في البلادِ عِدَّةُ محاولات للانقلاب على عبد الكريم قاسم؛ منها محاولة رشيد عالي الكيلاني الذي عاد للبلاد بعد نجاحِ الثورة وإنهاء الحُكم المَلَكي، وأخذ عددٌ من الضباط الناقمين على قاسم بالتردُّد على الكيلاني في بيته، ويتحدثون في السياسة بكل صراحة، فترامى إلى قاسم أنَّ رشيد الكيلاني يُعِدُّ لانقلاب ضده، فدبر عبد الكريم قاسم مكيدةً للكيلاني عن طريق أكبر أعوانه، وهما عبد الرحيم الراوي، ومبدر الكيلاني ابن أخي رشيد، فاتهمهم العسكر أنَّهم قد أسَّسوا جمعيةً سياسية، وأن الكيلاني سيدعمُهم بالسلاح؛ لذلك تم القبضُ على الكيلاني وأعوانه، وحُكِمَ على رشيد الكيلاني بالقتل، لكنه لم ينفَّذ، ولما أُفرِجَ عنه انتقل إلى بيروت، وعاد إلى العراق بعد الانقلاب على قاسم وقتله في رمضان 1382هـ."},{"id":5247,"title":"أيوب خان رئيسًا لباكستان بعد إسكندر مرزا .","date":["العام الهجري :1378","الشهر القمري : ربيع الآخر","العام الميلادي :1958"],"text":"كان الرئيس إسكندر مرزا قد ألغى الدستورَ وحَلَّ المجلسَ النيابي وفرض الأحكامَ العُرفيَّة، وحَلَّ الحكومة المركزية والأحزاب كافة، ثم استولى أيوب خان القائدُ العام للجيش والقوات المسلحة في 4 ربيع الثاني / 17 أكتوبر على مقاليدِ الأمور في البلادِ إثرَ انقلابٍ أطاح بحكومةِ إسكندر ميرزا الذي غادر البلادَ بعد عشرة أيام، وتسلَّم أيوب خان السلطةَ مكانَه ليحلَّ الحكم العسكري في البلاد، وبعد ثلاثة أيام فقط من تسَلُّم أيوب السلطة غيَّرَ اسم جمهورية باكستان الإسلامية إلى الجمهورية الباكستانية، ونقل العاصمةَ من كراتشي إلى روالبندي."},{"id":5248,"title":"وفاة الشيخ محمد حامد الفقي مؤسس جماعة \"أنصار السنة المحمدية\" .","date":["العام الهجري :1378","الشهر القمري : رجب","العام الميلادي :1959"],"text":"هو الشيخُ المحقِّق محمد حامد بن أحمد عبده الفقي مؤسِّسُ جماعة أنصار السنة المحمدية. ولِدَ الفقي بقرية نكلا العنب في سنة 1310ه الموافق 1892م بمركز شبراخيت مديرية البحيرة بمصر، أمضى ست سنوات من دراسته بالأزهر. وتخرُّجِ عام 1917م بعد أن نال الشهادة العالمية من الأزهر، وكان عمرُه حينذاك 25 سنة. ثم انقطع منذ تخرجه إلى خدمة كتاب الله وسنة رسولِه صلى الله عليه وسلم. وأثمرت تلك الجهود في إنشاء جماعة أنصار السنة المحمدية واتخذَ لها دارًا بعابدين. ثم أنشأ مجلة الهدْي النبوي، وصدر العدد الأول في 1937هـ, ومن جهودِه قيامُه بتحقيق العديد من الكتب القيمة، ومنها: ((اقتضاء الصراط المستقيم))، ((القواعد النورانية الفقهية))، ((المنتقى من أخبار المصطفى)), ((الرسالة التدمرية))، توفِّيَ الشيخ حامد رحمه الله فجر الجمعة 7 رجب 1378هـ الموافق 16 يناير على إثرِ عملية جراحية أجراها بمستشفى العجوزة، وبعد أن نجَحَت العملية أصيب بنزيفٍ حادٍّ، وعندما اقترب أجَلُه طلب ماءً للوضوء، ثم صلى ركعتي الفجر بسورة الرعدِ كُلِّها. وبعد ذلك طلب من إخوانه أن يُنقَلَ إلى دار الجماعة؛ حيث توفي بها."},{"id":5249,"title":"محاولة اغتيال الرئيس العراقي عبد الكريم قاسم .","date":["العام الهجري :1379","الشهر القمري : ربيع الأول","العام الميلادي :1959"],"text":"رأى حِزبُ البعثِ العراقي أنَّه لا بدَّ من التخلص من رئيس العراق باغتيالِه، فاختاروا عشرة من المغامِرين ودرَّبوهم، وأعدَّ الحزبُ العُدَّةَ لتسلُّم السلطة بعد تنفيذ العملية، وقَطْع الطريق على الشيوعية، واتصل الزعماءُ البعثيون برئيس مجلس القيادة الفريق محمد نجيب الربيعي، ووافقهم على تسلُّم الرئاسة وتشكيل مجلس ثورة جديد بعد نجاح العملية، ثمَّ تقَرَّر التنفيذ في 5 ربيع الثاني 1379هـ / 7 أكتوبر، فقام المغامرون بالتنفيذ، ولكِنْ قُتِلَ السائق الخاص للرئيس ومُرافِقُه، وجُرِحَ الرئيسُ، وقُتِلَ من المغامرين عبد الوهاب الغريري برصاصِ رفاقِه، وجُرِح صدام حسين التكريتي، وسمير نجم، ثم استطاع رئيسُ الأركان أحمد صالح ضَبْطَ الأمور، وتم إلقاء القبض على المغامرين إلا صدام حسين؛ فإنه هرب وقُدِّموا للمحاكمة، وأُصدِرَ حُكمُ القتل فيهم، لكِنَّه لم يصدق وخرجوا من السجن بعد زوال حُكمِ عبد الكريم قاسم."},{"id":5250,"title":"قتل عدنان مندريس رئيس وزراء تركيا .","date":["العام الهجري :1379","الشهر القمري : ذي الحجة","العام الميلادي :1960"],"text":"هو علي عدنان إرتكين مندريس المعروف بعدنان مندريس رئيس وزراء تركيا، ولِدَ في مدينة أيدين سنة 1317هـ، وهو سياسيٌّ حقوقي، ورجل دولة تركي ومن دهاة الأتراك, شارك في تأسيسِ رابع حزب معارِض معتَرَف به في تركيا، كما أنه يعتبَرُ أوَّلَ رئيس وزراء منتَخَب ديمقراطيًّا في تركيا عام 1385هـ, دخل الانتخاباتِ مُرشَّحًا للحزب الديموقراطي سنة 1950م ببرنامج توقَّعَت له كلُّ الدراسات الفشَلَ المطلق، فمع أنَّه خرج من حزب أتاتورك العلماني بعد أن انشقَّ عنهم، فقد كان من ضمن تعهُّداتِه التي أطلقها للأتراك في حملته الانتخابية أنَّه إذا نجح في الانتخابات برئاسة الوزراء يتعَهَّدُ بعودة الأذان باللغة العربية، والسماح للأتراك بالحَجِّ، وإعادة إنشاء المساجد، وتدريس الدين بالمدارس، وإلغاء تدخُّل الدولة في لباس المرأة، فكانت نتيجة الانتخابات حصولَ حزب أتاتورك العلماني على 32 مقعدًا، بينما حصل حزب مندريس الديموقراطي على 318 مقعدًا! وتسَلَّم عدنان مندريس منصِبَ أوَّلِ رئيس منتخب للوزراء، وجلال بايار رئيس الحزب رئيسًا للجمهورية، وقد عمل مندريس منذ فوزِ حِزبِه في الانتخابات على استعادة هويَّة تركيا الإسلامية التي صادرها كمال أتاتورك، فشرع بتنفيذِ وُعودِه التي أعلنها أثناء العملية الانتخابية؛ فعقد أول جلسة لمجلس الوزراء في غرة رمضان تيمُّنًا بالشهر الكريم، وسَمَح بالأذان باللغة العربية، وأطلق حريةَ لباس المرأة، وحرية تدريس الدين، وبدأ بتعمير آلافِ المساجد بعد أن كانت ممنوعةً من البناء، وأخلى المساجِدَ التي كانت الحكومةُ السابقة تستعمِلُها مخازن للحبوب، وأعادها لتكونَ أماكن للعبادة، كما سمح بتعليم اللغة العربية، وقراءة القرآن الكريم وتدريسه في جميع المدارس حتى الثانوية، وأنشأ أكثَرَ من عشرين معهدًا لتخريج الوعَّاظ والخطباء وأساتذة الدين، وسمح بإصدار المجلات والكتب التي تدعو إلى التمسك بالإسلام، وتقارَبَ مع العرب ضِدَّ إسرائيل، وفرض الرقابةَ على الأدوية والبضائع التي تُصنَعُ في إسرائيل، بل طَرَد السفير الإسرائيلي سنة 1956م، فتآمر عليه الأعداءُ في الداخل والخارج، فانقلب عليه جنرالات الجيش، وتم قتله -رحمه الله- شنقًا مع اثنين من وزرائه بعد محاكمةٍ صورية!"},{"id":5251,"title":"جمال غورسيل يترأس تركيا بانقلاب عسكري ضد محمود بايار .","date":["العام الهجري :1379","الشهر القمري : ذي الحجة","العام الميلادي :1960"],"text":"قام رئيسُ الأركان جمال غورسيل بانقلاب عسكري على الحزبُ الحاكم الديمقراطي برئاسة محمود جلال بايار فقُبِضَ على عدنان مندريس رئيس الوزراء، وأعدِمَ مع اثنين من وزرائه، وأمَّا رئيس الجمهورية محمود جلال بايار فخُفِّفَ عنه حكم القتل لكِبَر سنه، فسُجِنَ سَجنًا مؤبَّدًا حتى قضى نحبه فيه عام 1391هـ، وأصبح جمال غورسيل رئيسًا للجمهورية في عام 1381هـ بعد إجراء انخابات صورية."},{"id":5252,"title":"استقلال الغابون (الجابون) .","date":["العام الهجري :1380","العام الميلادي :1960"],"text":"في نهايةِ القرن الثالث عشر الهجري وصل الفرنسيُّون إلى الغابون، فاشتَرَوا قطعة من الأرض، وأقاموا عليها مستعمرةً صغيرة وبعد مضي عشر سنوات أقاموا مركزًا لتجارة الرقيق قُربَ الساحل، ثم امتَدَّ نفوذهم إلى داخل الغابون، وضَمُّوها إلى الكنغو الفرنسي، ثم فُصِلَت الجابون لتصبِحَ مُستعمَرةً قائمة بذاتها، وفي هذا العام نالت الغابون استقلالَها، وفي ظِلِّ الاستقلال هاجر العديدُ من المسلمين من مالي، وبنين، والسنغال إلى الجابون، وفي سنة 1973هـ / 1393م اعتنق رئيسُ الجمهورية (البرت برنارد بونجو) الإسلامَ وسُمِّي (عمر بونجو) وأسلمت معه أسرتُه ومعظم أفراد قبيلة البونجوي، ويوجد عددٌ كبير من الوزراء المسلمين بالجابون."},{"id":5253,"title":"استقلال الصومال .","date":["العام الهجري :1380","الشهر القمري : محرم","العام الميلادي :1960"],"text":"تنازلت بريطانيا إثرَ إلغاء الخلافة سنة 1342هـ عن منطقة جوبا السفلي أقصى جنوبي الصومال، لإيطاليا، وكانت مِن قَبلُ تتبع كينيا، وأعطت كينيا مقابِلَ ذلك الأراضي الصومالية الواقعة شرق بحيرة رودولف، ثم بعد الحرب العالمية الثانية كَثُرَ الجدل في الأمم المتحدة حولَ الوصاية على الصومال، ثم فازت إيطاليا بالوصاية على القسم الجنوبي من الصومال، وحُدِّدت بعشر سنوات تنتهي في جمادى الآخرة 1379هـ / ديسمبر 1959م، وأما القسم الشمالي فللإنجليز الذين رغبوا بضَمِّ الصومال الإيطالي لتتِمَّ السيطرة على القرن الإفريقي كاملًا، ولما انتهت مدة الوصاية طالب الشعبُ الصومالي بالاستقلالِ، وجرت الانتخاباتُ، وشاركت الأحزابُ الداعية إلى وحدة الصومال واستقلاله، واجتمع ممثِّلون عن المنطقتين في شوال 1379هـ / نيسان 1960م، واتفقوا على دَمْج جزأي الصومال في جمهورية مستقلة، ومَنْح الصومالِ الإنجليزي الاستقلالَ في مطلع عام 1380هـ / 26 حزيران، وأعلن عن قيام جمهورية الصومال المستقلة، وانتُخِب آدم عبد الله عثمان أوَّلَ رئيس للجمهورية الجديدة، وأصبح اسم الدولة جمهورية صوماليا."},{"id":5254,"title":"استقلال ساحل العاج  .","date":["العام الهجري :1380","الشهر القمري : صفر","العام الميلادي :1960"],"text":"بعد الحَربِ العالمية الثانية أصبحت دولةُ ساحل العاج ضِمنَ الاتحاد الفرنسي، وانتُخِبَت أول جمعية وطنية عام 1366هـ / 1947م وبعد عشر سنوات تشكَّلَت فيها أوَّلُ حكومة تتمَتَّعُ بالاستقلال الذاتي، ثم وافقت على دستور ديغول المعروف، فحصلت على الاستقلال الداخلي في 1378هـ / 1958م فأُعلِنَت الجمهوريةُ ضِمنَ مجموعة الشعوب الفرنسية، ثم مع الحزب الديمقراطي لساحل العاج حصلَ على الاستقلال التام في 14 صفر 1380هت / 7 آب، وانتُخِبَ زعيم الحزب فيلكس هوفويه بوانييه رئيسًا للجمهورية. ومع أنَّ أكثر السكان من المسلمين إلَّا أن الوظائف كانت من اختصاصِ النصارى، ولم يكن يُسمَح بتعليم اللغة العربية حتى في الكتاتيب المُلحَقة بالمساجد، واستأنفت الدولةُ علاقاتها مع اليهود في فلسطين، وأعلن الرئيسُ العاجي عام 1406هـ رغبةَ البلاد بأن تُعرَفَ دوليًّا باسمها الفرنسي \"كوت دي فوار\" وليس بالترجمة العربية، وقد قُبِلَ هذا الطلب فيما بعدُ لدى الأمم المتحدة، وبنى الرئيس على نفقته كاتدرائية ضخمة في ياموسوكرو."},{"id":5255,"title":"فرض جامعة الدول العربية مقاطعة اقتصادية على إيران .","date":["العام الهجري :1380","الشهر القمري : صفر","العام الميلادي :1960"],"text":"قامت جامعةُ الدول العربية بفَرضِ مقاطعة اقتصادية على دولةِ إيران؛ وذلك بسبب إقدامها على الاعتراف بدولة إسرائيلَ، وعزمها على تبادُلِ التمثيل الدبلوماسي بينهما."},{"id":5256,"title":"استقلال تشاد  .","date":["العام الهجري :1380","الشهر القمري : صفر","العام الميلادي :1960"],"text":"كانت تشاد تحت الاستعمار الفرنسي الذي كان قد قضى على إمارة رابح الإسلامية، حتى عُدَّت تشاد عام 1363هـ / 1944م جزءًا من الجمهورية الفرنسية فيما وراء البحار؛ بسبب وقوف حكَّامِها آنذاك مع حكومة ديغول الحرة التي قامت بعد هزيمة فرنسا أمام ألمانيا أثناء الحرب العالمية الثانية، وبالتالي شارك سكان تشاد في الحرب بجانب الفرنسيين، ووافقت فرنسا على تأسيس الأحزاب السياسية فيها بما أنَّها من الدولة الفرنسية، وأصبحت تشاد ذاتَ استقلال ذاتي عام 1378هـ / 1959م، وحصلت على الاستقلال التام عام 1380هـ بعد أن مكثت تحت الاستعمار الفرنسي قرابة ستين عامًا، وأصبح فرانسوا تمبالباي رئيسًا للجمهورية مع احتفاظه برئاسة الوزراء، وأصبحت اللغةُ الفرنسية هي اللغةَ الرسمية."},{"id":5257,"title":"استقلال فولتا العليا (بوركينافاسو) .","date":["العام الهجري :1380","الشهر القمري : صفر","العام الميلادي :1960"],"text":"كان المُستعمِرون قد قَسَّموا البلاد في غرب أفريقيا إلى أقسام، وأزالوا من الخارطة اسم فولتا العليا (بوركينافاسو حاليًّا)، ثم بعد الحرب العالمية الثانية وفي عام1366هـ / 1947م أعيدت الدولةُ بنفس الحدود السابقة، وجرت انتخابات واختار السكان جمعيةً وطنية بقيت تحت إشراف فرنسا بشكلٍ تام قرابةَ العشر سنوات، ثم أقيمت أوَّلُ حكومة للحكم الذاتي في 19 شوال 1376هـ / 18 أيار 1957م، وجاء بعدها ديغول وطرح دستوره المعروفَ، ووافقت عليه فولتا العليا فأصبحت في جمادى الأولى 1378هـ / ديسمبر 1958م عضوًا في الجماعة الفرنسية، ووُضِع دستور للبلاد واختير موريس ياميغو رئيسًا للجمهورية، وتولى بنفسه رئاسةَ الوزراء، وأعلن عن قيامِ فولتا العليا واستقلالِها في 12 صفر 1380هـ / 5 آب 1960م."},{"id":5258,"title":"استقلال داهومي (بنين) .","date":["العام الهجري :1380","الشهر القمري : صفر","العام الميلادي :1960"],"text":"كانت داهومي (بنين حاليًّا) تحت الاستعمار الفرنسي، ورُسِمَت الحدود بين نيجيريا وداهومي بشكلٍ دقيق بعد اتفاقية بين بريطانيا وفرنسا وُقِّعَت عام 1316هـ / 1898م، ثم رُسِمَت الحدود مع التوغو بعد اتفاقية مع ألمانيا عام 1330هـ / 1912م وأخذت داهومي شكلها الحاليَّ تقريبًا، ثم ركَّزت جهودَها التنصيرية أكثَرَ مِن أي منطقة أخرى، ثم تشَكَّلت حكومةٌ شبه مستقلة في الداهومي بعد الحرب عام 1366هـ / 1947م، وبعد عشر سنوات حصلت على الاستقلال الذاتي وأصبحت ضمنَ المجموعة الفرنسية، ووضعت دستورًا لنفسها، وجرت الانتخابات لاختيار مجلس تشريعي، وفي 8 صفر 1380هـ / آب أعلنت داهومي استقلالَها التامَّ وأصبح هيوبرت ماغا رئيسًا للدولة."},{"id":5259,"title":"استقلال النيجر  .","date":["العام الهجري :1380","الشهر القمري : صفر","العام الميلادي :1960"],"text":"اتفقت إنجلترا وفرنسا عام 1308هـ / 1890م على تعيين الحدود واقتسام مناطق النفوذ بينهما في منطقة وسط أفريقيا، وكانت منطقة النيجر من نصيبِ فرنسا، وتمكَّنَت من السيطرة التامة على النيجر كاملةً عام 1341هـ / 1923م وأخذت تطَبِّقُ سياسَتَها الاستعمارية، ثم بعد الحرب العالمية الثانية قَبِلَت النيجر بدستور ديغول وحصَلَت على الاستقلال الداخلي، وأعلنت الجمهورية ضِمنَ المجموعة الفرنسية، ثم أخذت بالمطالبة بالخروج من المجموعة والاستقلال التام، وحصلت عليه في 10 صفر 1380هـ / 3 آب وتولى هاماني ديوري زعيمُ الحزب النيجري التقدمي رئاسةَ الجمهورية."},{"id":5260,"title":"استقلال السنغال .","date":["العام الهجري :1380","الشهر القمري : ربيع الأول","العام الميلادي :1960"],"text":"انضَمَّت السنغال إلى السودان الفرنسي ليؤلِّفَا معًا اتحادَ مالي في شوال 1378هـ / نيسان 1959م، وبعد أقل من عام أصبح اتحادُ مالي مستقلًّا وانحلَّ الاتحاد وأصبحت السنغال جمهوريةً مستقلة في 27 صفر 1380هـ / 20 آب 1960م، ثم استقلت رسميًّا عن فرنسا في 14 ربيع الأول 1380هـ / 5 أيلول، وكانت تحت حُكمِ حزب الاتحاد التقدمي السنغالي، ورئيسه هو رئيس الجمهورية ليوبولد سنجور."},{"id":5261,"title":"تأسيس منظمة أوبك ودور السعودية في نشأتها\n  .","date":["العام الهجري :1380","الشهر القمري : ربيع الأول","العام الميلادي :1960"],"text":"درست الحكومةُ السعودية دراسةً دقيقة سوقَ النفط في العالم, وبدأت تدرِكُ مدى الأرباح الطائلة التي تحصل عليها شركات النفط خارجَ السعودية, مع وجود مبدأ \"المناصفة\"، وفي نيسان (أبريل) 1959 عُقِد أول مؤتمر نِفطي عربي حضره ممثِّلون عن السعودية، وبدأت البلدان المصدِّرة للنفط تُدرِكُ ضرورةَ القيام بنشاطات جماعية. وقد أثار بالغ القلق لدى هذه البلدان انخفاض الأسعار القياسية. ففي الفترة من سنة 1957 حتى سنة 1960 انخفض السعرُ القياسي للنفط؛ مما أدى إلى تقلُّص كبير في عائدات البلدان المصدِّرة للنفط، وفي أيلول (سبتمبر) عام 1960 أُسِّسَت في بغداد منظمة البلدان المصدِّرة للنفط (أوبك) ضَمَّت العراق، وإيران، والكويت، والسعودية، وفنزويلا. وفيما بعد انضَمَّت إليها أبو ظبي، وقطر، وليبيا، والجزائر، وأندونيسيا، ونيجيريا، والأكوادور، والغابون. وكان الهدف الرئيسي لأوبك إجراء مشاورات بين أعضاء أوبك والشركات حينما تظهر حاجةٌ لتغيير الأسعار, ومراقبة حجم الإنتاج عند الضرورة."},{"id":5262,"title":"استقلال مالي .","date":["العام الهجري :1380","الشهر القمري : ربيع الأول","العام الميلادي :1960"],"text":"كانت مالي تقع ضمن بلاد السودان الفرنسي تحت سيطرة الاحتلال الفرنسي، وعندما طُرِحَ دستور ديغول قَبِلَته مالي، فتكوَّنَت جمهورية مالي ذاتُ الاستقلال الذاتي ضِمنَ مجموعة الشعوب الفرنسية، وأُلغِيَت وظيفةُ الحاكم الفرنسي العام، ثم في شهر شوال 1378هـ / نيسان 1959م تمَّ اتحاد بين السودان الفرنسي والسنغال حَمَل اسم مالي رمزًا لمملكة مالي القديمة، وحصل الاتحاد على الاستقلال ضِمنَ المجموعة الفرنسية عام 1379هـ / 1960م، لكِنَّ هذا الاتحاد لم يلبَثْ أكثَرَ من ثلاثة أشهر، فأَعلَنَ السودان الغربي نفسَه جمهوريةً مُستقِلَّةً استقلالًا تامًّا في ذي الحجة 1379هـ / 1960م مع الاحتفاظِ باسم مالي، وتم الإعلانُ عن جمهورية مالي بدلًا من اتحاد مالي في غرة ربيع الثاني 1380هـ / 22 أيلول، وانتُخِبَ موديبو كيتا رئيسًا للجمهورية بالإجماعِ، وهو من أسرة كيتا التي أسَّست إمبراطورية مالي قديمًا."},{"id":5263,"title":"استقلال موريتانيا  .","date":["العام الهجري :1380","الشهر القمري : جمادى الآخرة","العام الميلادي :1960"],"text":"بعد انتهاءِ الحرب العالمية الثانية بدأت الأحزابُ تدعو إلى الاستقلال، وفي عام 1378هـ / 1958م أصبحت موريتانيا ضِمنَ الشعوب الفرنسية التي تتمتَّعُ بالاستقلال الداخلي مع بقاء السلطاتِ بيَدِ الحاكم العام الفرنسي، وبقيت الأحزابُ تُطالِبُ بالاستقلال، ثم جرت الانتخاباتُ وتشَكَّلت الجمعية التأسيسية، وقُدِّم الدستور إلى الجمعية الوطنية فوافقت عليه في رمضان 1378هـ / آذار 1959م، وجاء فيه أنَّ اسم البلاد هو الجمهورية الإسلامية الموريتانية، والدين هو الإسلام، واللغة الوطنية: العربية، والرسمية: الفرنسية، والشريعة المدنية: الفقه الإسلامي، وكانت المغرب تطالِبُ بضم موريتانيا إليها، وعُرِضَت القضية على الأمم المتحدة فقَرَّرت الجمعية السياسية للأمم المتحدة منح موريتانيا الاستقلالَ بتاريخ 7 جمادى الآخرة 1380هـ / 26 نوفمبر، وبعد يومين نالت موريتانيا الاستقلالَ، وتأخَّرت الدول العربية بالاعتراف؛ لأن هذا يعتبر فصلًا لدولة عربية وتقسيمها إلى أجزاء."},{"id":5264,"title":"مؤتمر (برازفيل) لضم دول غرب ووسط أفريقيا للاتحاد الفرنسي .","date":["العام الهجري :1380","الشهر القمري : جمادى الآخرة","العام الميلادي :1960"],"text":"مؤتمر برازافيل (مؤتمر اتحاد الدول الأفريقية والملاجاشية) عُقد في الفترة من 15 إلى 19 ديسمبر 1960م. وكان الهَدفُ منه تحقيقَ تعاون بين بعض الدول الأفريقية الواقعة تحت الاستعمار الفرنسي وترغب في الاستقلال، وترفُضُ الانضمامَ إلى المجموعة الفرنسية. وقد بذلت هذه الدولُ جهودًا كبيرةً في إنشاء تجمُّع أفريقي غيرِ مرتبط بأيِّ دولة أوروبية. عُقِدَ أوَّلُ مؤتمر في مدينة أبيدجان، عاصمة ساحل العاج من 3 إلى 7 أكتوبر عام 1960م، وحضر هذا المؤتمر: السنغال، وأفريقيا الوسطى، والكونغو، وبرازافيل، وموريتانيا، وداهومي، وساحل العاج، والنيجر، والكاميرون، وغينيا. وكان الهدفُ من المؤتمر تنظيم التعاون بين هذه الدول. كما اتفقوا على مداومة الاجتماعات والمؤتمرات؛ لزيادة التعاون. عُقد المؤتمر الآخر في برازافيل من 15 - 19 ديسمبر، وحضرته الدولُ التسع التي سبق لها حضور المؤتمر الأول في أبيدجان، إضافة إلى الكنغو ليوبولدفيل (زائير والكنغو الديمقراطية حاليًّا)، وتشاد. (أكثر هذه الدول غالبية سكانها مسلمون) وتوصَّل هذا المؤتمر إلى وضع مشروع منظمة أفريقية تضُمُّ إليها مالاجاش، وسمُيِّت هذه المنظَّمةُ بمجموعة برازافيل، نسبةً إلى المكان الذي انعقد فيه هذا المؤتمر، وتقَرَّر فيه إقامةُ هذه المنظمة. اتَّفَقَت هذه الدُّولُ على مجموعة من المبادئ تحكُمُ علاقاتِها المتبادلة، والعلاقات بينها وبين الدول الأفريقية. وكان أهمها:1. العمل الدائم من أجل السلام، ويتمثَّلُ ذلك في عدم الدخول في أي تحالفٍ يُعَدُّ موجَّهًا ضِدَّ أي دولة من دول المنظمة، وعدم اللجوء إلى الحرب. 2. عدم التدخُّل في الشؤون الداخلية، وذلك بعدم قيام أي دولة بتأييد حكومةٍ في المنفى، مع تعهُّد كل دولة بتحريم كل أنواع النشاط الهدَّام.3. التعاون الاقتصادي والثقافي بين الدول الأفريقية على أساس المساواة. 4. التعاون الدبلوماسي بين دول الفرانكوفون، والعمل في إطار سياسة دولية محايِدة."},{"id":5265,"title":"مؤتمر الدار البيضاء لدول أفريقية بالمغرب .","date":["العام الهجري :1380","الشهر القمري : رجب","العام الميلادي :1961"],"text":"عُقِدَ مؤتمر الدار البيضاء الدولي بالمغربِ بدعوة من الملك محمد الخامس؛ ملك المغرب بعد عدة لقاءات واجتماعات بين ممثِّلي الدول الأفريقية التي وقَّعت فيما بعد ميثاقَ المنظمة. اشترك في هذا المؤتمر سِتُّ دول، هي: الجمهورية العربية المتحدة، والمغرب، وحكومة الجزائر المؤقتة، وغانا، وغينيا، ومالي. كما حضر المؤتمر مراقبان من ليبيا وسيلان، على الرغمِ من أن سيلان ليست دولةً أفريقية. وكان الهدف من المؤتمر تبادُلَ وجهاتِ النظر في المشاكل الأفريقية، والمشاركة الجماعية في تحرير دول القارة، ودعم الدول المستقلة. وكانت أهم القرارات التي اتَّخَذها المؤتمَرُ مساندة شعب الجزائر وحكومته المؤقتة؛ لتحقيق استقلاله، واستنكار الاستعمار الصهيوني، وضرورة حل قضية فلسطين والاعتراف بالحقوق الفلسطينية، واستنكار التجارب الذرية خاصةً الفرنسية التي تجري على أراض أفريقية، وتأييد مطالب المغرب في موريتانيا. ووقع المجتَمِعون في نهاية المؤتمر ميثاقًا لتنظيم العلاقات بينهم يضمن أهم المبادئ التالية: مبدأُ الوحدة الأفريقية، مبدأ عدم الانحياز، مبدأ محاربة الاستعمار القديم والجديد بجميع أشكاله. مبدأ المحافظة على سيادة الدول ووحدة أراضيها، والتعاون بين الدول الأفريقية. وأنشأ ميثاق الدار البيضاء عِدَّة لجانٍ لتنسيق العمل بين الدول الأعضاء، وتحقيق التعاون في جميع المجالات، وسَمَح ميثاق المجموعة بقَبول عضوية كل دولة أفريقية، على أن يوافِقَ الأعضاءُ على قبولها بالإجماع. وعلى الرغمِ من جميع هذه الإيجابيات فإنَّ الانسجام بين الدول الأعضاء لم يكنْ كاملًا، ولكن مع ذلك فإن تشكيلَ هذا التجمُّع أسهم في نشرِ فكرة الوحدة الأفريقية، وإبراز الشخصية الأفريقية."},{"id":5266,"title":"نشأة وزارة المعارف في السعودية .","date":["العام الهجري :1380","الشهر القمري : رجب","العام الميلادي :1961"],"text":"اتَّسَعت أعمالُ إدارة المعارف بعد وفاة الملك عبد العزيز فجُعِلت وزارةً كسائر وزارات الدولة، وتولاها الأميرُ فهد بن عبد العزيز، وفي عهده أُنشِئَت جامعة الرياض، ثم تولى الوَزارةَ الشيخ عبد العزيز بن عبد الله آل الشيخ، ثم تولاها أخوه حسن بن عبد الله آل الشيخ الذي توسَّع نطاقُ جامِعة الرياض في عَهدِه، فشَمِلَت كليَّات العلوم والصيدلة والآداب والتجارة والزراعة، ثم الهندسة، وأُنشِئَت جامعة الملك عبد العزيز الأهلية في جُدة، والجامعة الإسلامية في المدينة المنورة."},{"id":5267,"title":"وضعُ حجر الأساس لبناء السد العالي في أسوان .","date":["العام الهجري :1380","الشهر القمري : رجب","العام الميلادي :1961"],"text":"وُضِعَ حَجَرُ الأساس لبناء السد العالي في أسوان، بحضور الرئيس المصري جمال عبد الناصر، وكان الغرَضُ من بناء السد تخزينَ المياه، وموازنة الفيضانات المرتفعة والمنخفضة، وتوليد الكهرباء، وتحسين الملاحة بالنيل، وقد أُنجِزَت المرحلة الأولى في بناء السد سنة 1964م."},{"id":5268,"title":"وفاة محمد الخامس ملك المغرب وتولي ابنه الحسن الثاني .","date":["العام الهجري :1380","الشهر القمري : رمضان","العام الميلادي :1961"],"text":"هو محمَّدُ الخامس بن يوسف بن الحسن بن محمد بن عبد الرحمن الحسني العلويّ، أبو الحسن المنصور باللَّه: ملك المغرب، ورمزُ نهضته الحديثة. وُلِدَ بفاس سنة 1329هـ وتعَلَّم بها وبالرباط، وكان بفاس يوم بُويِعَ له بعد وفاة والده سنة 1346ه 1927م، فانتقل إلى الرباط عاصمة المغرب في عهد أبيه. وكان الاحتلالُ الفرنسي المعبَّرُ عنه بالحماية هو المرجِعَ الأعلى في سياسة البلاد وإدارتها، وليس للملك الذي كان يُدعى بالسلطان ولا للقصر الملكي الذي يُسمَّى المخزَن إلَّا المظهرُ الديني في مواسِمِ الأعياد الإسلامية، ووَضْع الطابع الشريف -أي: الخاتم- على الأحكام الشرعية، وشؤون الأوقاف، أُعلِنَ استقلال المغرب يوم 3 مارس 1956 وزار أسبانيا فاتَّفَق مع حكومتِها على أن تعترف باستقلال المغرب ووَحدةِ ترابه، وأدخل المغربَ في الأُمَم المتحدة. وربَطَ بلادَه بعلاقات سياسية واقتصادية مع أكثر دول العالم. وكان يدورُ في سياسته حول دول الغرب (أمريكا ومن معها) فمَدَّت إليه الدول الاشتراكية يَدَها، فتعاون معها متحفِّظًا بحُسنِ صِلاتِه بالأولى. وكان لمدينة طنجة نظامٌ دولي يَفصِلُها عن المغرب، فألغى ذلك النِّظامَ وأدخل بلادَه في جامعة الدول العربية، ولَمَّا مَرِضَ الملك محمد الخامس سافر إلى سويسرا للعلاج، وعَيَّن ابنَه الحسن وليًّا للعهد، ثم توفي في 11 رمضان 1380هـ، فتسَلَّم المُلْكَ بعده ابنُه الحسن الثاني بعد خمسة أيام من وفاته."},{"id":5269,"title":"استقلال سيراليون  .","date":["العام الهجري :1380","الشهر القمري : ذي القعدة","العام الميلادي :1961"],"text":"كثُرت الأحزاب السيرالونية حتى بلغت تسعةَ أحزاب أجمعت كلُّها على المطالبة بالاستقلال من الحماية البريطانية، وشَكَّلت وفدًا سافر إلى لندن عام 1380هـ / 1960م، وقد شكل أعضاؤه بعد عودتهم حكومةً ائتلافية استطاعت أن تظفَرَ بالاستقلال في 12 ذي القعدة 1380هـ / 27 نيسان ضِمنَ رابطة الشعوب البريطانية، وسيراليون من دول غرب أفريقيا ذات الأغلبية المسلمة."},{"id":5270,"title":"استقلال الكويت .","date":["العام الهجري :1381","الشهر القمري : محرم","العام الميلادي :1961"],"text":"تعودُ النشأةُ الحديثةُ لدولة الكويت إلى الشَّيخِ مبارك الصباح الذي حكَمَ الفترة ما بين 1896م إلى 1915م، واستند نظامُ الحكم فيها إلى أساس السلطة المُطلَقة للحُكَّام، ولم تحصل تطوراتٌ جوهرية على النظامِ حتى حصول الكويت على الاستقلال، وذلك بعد إلغاء اتفاقيَّة الحماية التي عُقِدَت في 1899م بينها وبين بريطانيا، وقد قُبِلَت الكويت في الجامعة العربية في 20 تموز 1961م، وفي الأمم المتحدة في 14 آذار 1963م. وفي 11 نوفمبر 1962 تم إصدارُ دستور دولةِ الكويت."},{"id":5271,"title":"انفصال الوحدة بين مصر وسوريا .","date":["العام الهجري :1381","الشهر القمري : ربيع الآخر","العام الميلادي :1961"],"text":"بدأت العلاقةُ بين الطرفين المصري والسوري تسوء عندما عُيِّنَ المشير عبد الحكيم عامر حاكِمًا على سوريا في عام 1379هـ / 1959م فاستقال وزراءُ حزبِ البعث ونائِبُ رئيس الجمهورية البعثي أكرم الحوراني؛ وحدث استياءٌ عام في سوريا في الوسط المثقَّف والتعليمي وفي الجيش وحتى بين الشيوعيين الذين غادر أكثَرُهم البلاد، وعلى رأسهم زعيمهم خالد بكداش، فبدأ بعض الضباط السوريين العمل سرًّا لانفصال الوحدة، ومن بينهم عبد الكريم النحلاوي: مدير مكتب المشير عبد الحكيم عامر ومدير شؤون الضباط، واستطاع أن يجمع حوله عددًا من الضبَّاط من اختصاصات مختلفة منتظرًا الوقت المناسب، حتى كان يوم 18 ربيع الثاني 1381هـ / 28 أيلول 1961م وقع الانفصالُ الذي دبَّره النحلاوي مع الضباط السوريين."},{"id":5272,"title":"ثورة 26 سبتمبر في اليمن ونهاية حكم الأئمة وإعلان الجمهورية .","date":["العام الهجري :1381","الشهر القمري : ربيع الآخر","العام الميلادي :1961"],"text":"بعد أن انفصلت اليمنُ عن الدولة العثمانية أثناء الحرب العالمية الأولى استقلَّ بحكمِها الإمام يحيى حميد الدين حتى سنة 1948م حكمًا يجمع بين الإمامة الدينية والسلطة السياسية، وعاونه في الإدارة أولادُه، ولما قتل الإمام يحيى في شباط 1948م في مؤامرة بسبب صراع أسري، تولى الحكم ابنُه أحمد الذي انفتح على العالم بانضمامه إلى الجامعة العربية، ثم لهيئة الأمم المتحدة، بل وفتح باب العلاقة مع دول المعسكر الشيوعي الاشتراكي، فقَبِل عروض الأسلحة من الاتحاد السوفيتي مع بقاء قبوله لمعونات أمريكا وألمانيا، ثم بعد موت الإمام أحمد حكم ابنُه محمد البدر، وبعد حكمه بأسبوع أعلن الأحرار اليمنيون الثورةَ ومعهم ضباط من الجيش بزعامة عبد الله السلال بتحريض ودعم من جمال عبد الناصر، وذلك في 27 ربيع الثاني / 26 سبتمبر، وأعلنت مصر تأييدَها للثورة في اليوم الثاني من قيامها، فهاجم الثوارُ قصر الحاكم البدر بن أحمد، وأعلنوا أنهم قتلوه وأصدروا في 3 أكتوبر 1962م دستورًا مؤقتًا يعلن النظام الجمهوري في البلاد ويلغي النظام الملكي وحُكم الأئمة، وتم تشكيل مجلس ثورة برئاسة محمد علي عثمان يتبعه مجلس استشاري من الزعماء القبليين ومجلس وزراء، وأعلنوا إلغاءَ الرِّقِّ ونظام الطبقات والتمييز الطائفي بين الزيدية والشافعية، ثم اختيرَ عبد الله السلال رئيسًا للجمهورية اليمنية الشمالية، والتي استمرت قرابة 8 سنوات 1962م إلى 1970م بين مدٍّ وجزر."},{"id":5273,"title":"حرب اليمن الأهلية (دعم مصر للجمهوريين ودعم السعودية للملكيين) .","date":["العام الهجري :1381","الشهر القمري : جمادى الأولى","العام الميلادي :1961"],"text":"لما توفي الإمام أحمد خلفه في الإمامة ابنه البدر، ولم تلبث أن قامت الثورة عليه بإمرة العقيد الناصري عبد الله السلال، وذلك في 27 ربيع الثاني / 26 سبتمبر، وهرب البدر من البلاد، وأخذ يستعد للعودة. أيدت السعودية الملكية اليمنية وأيَّدت مصر الثورة ووصلت طلائع القوات المصرية إلى اليمن في 7 جمادى الأولى 1383هـ، وفي اليوم التالي من وصولها قطعت مصر علاقتَها بالسعودية، ثم وصل أنور السادات حيث عَقَد مع اليمن معاهدةَ الدفاع المشترك. كانت الحربُ غير متكافئة بين الثوار مدعومين بالجيش المصري، واليمنيين المدعومين من الحكومة السعودية، والذين كانوا يخوضون حرب عصابات ضِدَّ الجيش المصري، فكبَّدوهم خسائر فادحة في الأموال والأرواح، وأوقعوا المصريين في ورطة لم يستطيعوا التخلُّص منها، ولم يخرج الجنود المصريون من اليمن إلا بعد 4 سنوات بعد عام 1387هـ، وبعد نكسة حزيران 1967م، واستمرَّت الحرب بعد خروج المصريين من اليمن إلى 1389هـ، وكان الخروجُ نتيجة الاتفاق الذي تم بين الملك فيصل بن عبدالعزيز والرئيس جمال عبد الناصر، وذلك في مؤتمر الخرطوم بالسودان."},{"id":5274,"title":"استقلال تانجانيقا (تنزانيا) .","date":["العام الهجري :1381","الشهر القمري : رجب","العام الميلادي :1961"],"text":"كانت تنزانيا الحالية تتكون من منطقتين؛ المنطقة الأولى هي تانجانيقا، والأخرى زنجبار، فأما تانجانيقا وهو الساحل الجنوبي الشرقي فقد كان تحت الاحتلال الألماني، وعرفت باسم أفريقيا الشرقية الألمانية، وقد تمكنت إنجلترا بعد الحرب العالمية الأولى من انتزاع تانجانيقا من ألمانيا، ووُضعت تحت وصاية عصبة الأمم، ثم أصبحت بريطانيا هي الوصية عليها بتصديق من عصبة الأمم عام 1341هـ / 1922م، فاتبع فيها نظام الانتداب، ثم أعلنت إنجلترا في عام 1376هـ / 1956م أنها ستمنح تانجانيقا حكومة ذات استقلال داخلي، وجرت أول انتخابات عامة في ربيع الأول 1378هـ / أيلول 1958م وجرت الانتخابات وفاز حزب الاتحاد الوطني الإفريقي، واتخذت الأمم المتحدة قرارًا بإنهاء الوصاية وبعدها أصبحت تانجانيقا مستقلة ضمن رابطة الشعوب البريطانية في 2 رجب 1381هـ / 9 ديسمبر, وانتُخِب يوليوس نيريري رئيسًا للجمهورية، ثم بعد أن انضمَّت زنجبار إلى تانجانيقا في عام 1383هـ / 1964م أصبحتا دولة واحدة والرئيس هو نفسه يوليوس، وسمِّيَ الاتحاد الجديد تانزانيا، وذلك في 1384هـ / 1964م، وتنزانيا من دول شرق أفريقيا وفيها نسبة عالية من المسلمين خاصة زنجبار فأهلها كلهم مسلمون."},{"id":5275,"title":"اتفاقية إيفيان الأولى ووقف إطلاق النار بين جبهة التحرير الجزائرية وفرنسا .","date":["العام الهجري :1381","الشهر القمري : شوال","العام الميلادي :1962"],"text":"بدأت المفاوضاتُ بين الجزائريين والفرنسيين في إيفيان من 20 مايو، واستمرت لمدة عام، تمَّ في بدايتها الاتفاقُ على إعلان وقف إطلاق النار بين جبهة التحرير الجزائرية وفرنسا. وبناءً على اتفاقية إيفيان تمَّ إقرار مرحلة انتقالية وإجراء استفتاء تقرير المصير. والاتفاق على أن تتولى شؤون الجزائر حكومةٌ مؤقتة تتكون من 12 عضوًا. كما تضمَّنت هذه الاتفاقيات جملةً من اتفاقيات التعاون في المجالات الاقتصادية والثقافية سارية المفعول لمدة 20 سنة."},{"id":5276,"title":"انقلابات عسكرية في سوريا ضد الوحدة مع مصر .","date":["العام الهجري :1381","الشهر القمري : شوال","العام الميلادي :1962"],"text":"قام عبد الكريم النحلاوي بانقلاب عسكري في سوريا ضدَّ الجمهورية العربية المتحدة برئاسة جمال عبد الناصر، ويعد النحلاوي المسؤولَ الرئيسي عن انفصال سوريا عن مصر في الوحدة التي نشأت بين القطرين تحت اسم \"الجمهورية العربية المتحدة\"، ثم قام النحلاوي في 28 مارس 1962م بانقلابٍ آخر فحَلَّ البرلمان وأقال حكومة معروف الدواليبي. ثم وقع انقلاب عسكري بعد يومين ضد \"النحلاوي\"."},{"id":5277,"title":"رؤية ولي العهد فيصل بن عبد العزيز في الإصلاح السياسي والإداري .","date":["العام الهجري :1382","العام الميلادي :1962"],"text":"شكَّل الأميرُ فيصل بن عبد العزيز الحكومةَ الجديدة، ثم طرح مجموعةً من الرُّؤى الإصلاحية؛ كالنِّظام الأساسي للحُكم، ونظامِ القضاء، ومجلسٍ للإفتاء، وهيئةٍ للأمر بالمعروف والنهي عن المنكر، واعتماد مجانيَّة الطبِّ والتعليم، ودعم الموادِّ الاستهلاكية الضرورية، والضَّمان الاجتماعي، وتنظيم وتطوير الوضع الاقتصاديِّ والتجاريِّ والاجتماعيِّ، وإلغاء الرِّقِّ بشكلٍ مُطلَق، وحَظْرِه وعتق العبيد جميعًا. وقد تحقق كثيرٌ من ذلك في عهده، إلَّا أن النظام الأساسي للحُكم في السعودية لم يصدُرْ إلا في عهد الملك فهد في 27 / 8 / 1412هـ."},{"id":5278,"title":"استقلال الجزائر .","date":["العام الهجري :1382","الشهر القمري : صفر","العام الميلادي :1962"],"text":"توقَّفت الثَّورةُ الجزائريةُ الكبرى -التي اندلعت في جميعِ أرجاء الجزائر ثم انتقلت لأرض فرنسا نفسِها- بعد اتِّفاق الجزائريِّين والفرنسيِّين في مفاوضاتٍ سابقة على وقفِ إطلاق النار، وتشكيل حكومةٍ جزائرية مؤقَّتة؛ فأعلنت فرنسا عن قَبولها للمفاوضات، وعيَّنَ المجلسُ الوطني الجزائري العقيدَ هواري بومدين قائدًا عامًّا لجيش التحرير، ثم أعلنت الحكومةُ الجزائريةُ والفرنسيةُ في 25 ذي القعدة 1380هـ / 10 أيار 1961م الشُّروعَ في محادثات إيفيان، وكانت فرنسا تماطِلُ بل وتتوقف من أجلِ موضوع الصحراء إلى أن اعترفت أخيرًا بحقِّ الجزائريين في الصحراء، وتمَّ الاتفاقُ على وقف إطلاق النار، وأن تتولى شؤونَ الجزائر هيئةٌ مؤقتة تتألَّفُ من اثني عشر عُضوًا، وفي محرم 1382هـ / تموز 1962م جرى الاستفتاءُ على استقلال الجزائر، فكانت النتيجةُ 97.3% لصالح الاستقلال، فأُعلِنَ استقلالُ الجزائر في 3 صفر 1382هـ / 5 تموز، وقامت الدولةُ الجزائرية، ووُضِع الدستورُ وأقرَّه المجلس، وبموجِبِه انتُخِبَ أحمد بن بلة رئيسًا للدولة، الذي أعلن القوانينَ الاشتراكية، ومن الناحية السياسية الدولية بَقِيَت فرنسا صاحبةَ النفوذ الفعلي رغم الخلافِ معها."},{"id":5279,"title":"اتفاقية ميثاق الطائف بين السعودية والأردن .","date":["العام الهجري :1382","الشهر القمري : ربيع الآخر","العام الميلادي :1962"],"text":"اجتمع الملكُ سعود -مَلِكُ السعودية-، والملكُ حسين -ملك الأردن- في الطائف، ووقَّعا اتفاقيةً على رسم الحدود بين البلدين، وعُرِفَت هذه الاتِّفاقيةُ بميثاق الطَّائف."},{"id":5280,"title":"إصدار الحكومة الإثيوبية قرارًا باحتلال إريتريا عسكريًّا .","date":["العام الهجري :1382","الشهر القمري : جمادى الآخرة","العام الميلادي :1962"],"text":"أصدرت الحكومةُ الإثيوبية قرارًا باحتلال إريتريا عسكريًّا وضَمِّها إلى أملاكها الرسمية، ويتعارض هذا القرارُ مع قرار الأمم المتحدة الصادر في 2 يناير 1950م بشأن إقامة اتحادٍ لامركزيٍّ بين الحبشة وإريتريا."},{"id":5281,"title":"إقامة صلاة الجمعة في جامع كتشاوة بالجزائر .","date":["العام الهجري :1382","الشهر القمري : جمادى الآخرة","العام الميلادي :1962"],"text":"تمَّت إقامةُ صلاة الجمعة في جامع كتشاوة بالجزائر، وكان خطيبُها الشيخَ الجزائري \"البشير الإبراهيمي\"، وكانت هذه هي الجُمعةَ الأولى التي تقامُ في ذلك المسجد بعد مائة عام مِن تحويلِ الاحتلال الفرنسي هذا المسجِدَ إلى كنيسةٍ!"},{"id":5282,"title":"مبادرة الرئيس الأمريكي جون كندي لحل نزاع اليمن .","date":["العام الهجري :1382","الشهر القمري : جمادى الآخرة","العام الميلادي :1962"],"text":"وجَّه الرَّئيسُ الأمريكي جون كندي رسائلَ إلى رئيس الوزراء السعودي الأمير فيصل، وملك الأردن حسين، ورئيس مصر عبد الناصر، والرئيس اليمني عبد الله السلال, ضمَّنَها تصوراتِه حول سُبُل حلِّ نزاع اليمن. وقد تجاهل الرئيسُ الأمريكي الإمامَ محمد البدر وحاشيته. واقترح كندي على مصر سَحْبَ قواتها المسلَّحة من اليمن, وفي المقابل اقترح على السعودية والأردن ومشايخ وسلاطين اتحاد جنوب الجزيرة وقْفَ المساعدات للمَلَكيِّين قواتِ الإمام البدر. وفي اليوم نفسِه أعلن الأميرُ فيصل عن رفضه اقتراحَ كندي. وفي اليوم التالي رفض الرئيس جمال عبد الناصر بدوره اقتراحَ كندي, وأعلن أنَّه لن يوافق على سحب القوَّات المصرية من أراضي اليمن إلَّا إذا زال الخطرُ الذي يهدِّد اليَمَن الجُمهوري! ولم يوافِقْ على مبادرة كندي إلا الرئيس اليمني عبد الله السلال. وفي خاتمة المطاف اعتبرت واشنطن قضيةَ الملكيين مَيؤوسًا منها. وفي 14 ديسمبر/ ديسمبر 1962 أعلنت حكومةُ الجمهورية العربية اليمنية أنَّها ستُغلِق السفاراتِ والبَعَثاتِ الدبلوماسية لجميع البلدان التي لم تعترفْ بالجمهورية اليمنية. وفي 19 ديسمبر أعلنت وزارةُ الخارجية الأمريكية رسميًّا عن اعتراف الولاياتِ المتحدة بالجُمهورية اليَمَنيَّة."},{"id":5283,"title":"إصدار مرسوم بإلغاء الرق في المملكة العربية السعودية  .","date":["العام الهجري :1382","الشهر القمري : جمادى الآخرة","العام الميلادي :1962"],"text":"صدر مرسومٌ بإلغاء الرِّقِّ، والتزمت حكومةُ المملكة العربية السعودية بموجِبه دفع 700 دولار عن كل عبدٍ لسيِّدِه، و1000 دولار عن الأَمَةِ، وحُدِّد آخِرُ موعد لتقديم طلبات التعويض في 14 صفر 1383هـ / 7 يوليو 1963م، وبلغ العدد الإجمالي للرقيق الذين طالب أسيادُهم بدفع تعويضٍ عنهم 1682 شخصًا، ودفعت الحكومةُ التعويضات وأعتقَتْهم، واعتُبر سائرُ الرقيق معتوقين بعد التاريخ المذكور الذي حُدِّد كأجَلٍ نهائي لدَفعِ التعويضاتِ."},{"id":5284,"title":"وفاة محمد بن عبد الكريم الخطابي قائد الثورة المغربية .","date":["العام الهجري :1382","الشهر القمري : رمضان","العام الميلادي :1963"],"text":"هو محمد بن عبد الكريم الخطابي (بالأمازيغية موحند نعبد لكريم لخطابي) الذي اشتُهِر بين الريفيين بـ (عبد الكريم الخطابي)، وهو قائدُ الثورة المغربية في منطقة الريف شماليَّ المغرب. وُلِدَ سنة 1299هـ / 1882م في أجدير قرب الحسيمة، من ريف المغرب. وُلِدَ في بيت علمٍ وجهادٍ، من قبيلة \"ورياغل\" إحدى كبريات القبائل البربرية في جبال الريف. حَفِظ القرآن وبَعَثه والِدُه إلى القرويين بفاس، فتعَلَّم وعاد إلى الريفِ، وأقام في مدينة مليلة فوَلِيَ قضاءَها. وامتد احتلالُ الإسبان من مليلة وتطوان إلى (شفشاون)، فأظهر عبد الكريم والد محمد معارضتَه لهم، وكان من أعيان القوم، فانتقم الإسبانُ منه بعزل ابنه محمد من القضاء واعتقاله في سجن كبالرزا سنة 1920م، وأراد محمدٌ الفرار من المعتقل فسَقَط وكُسِرَت ساقه، فأُطلِق من سِجنِه، فجمع محمد الخطابي أنصارًا من ورياغل (قبيلته) وقد آلت إليه زعامتُها بعد أبيه، وقاتل الإسبانَ، فظَفِرَ في معركة (أنوال) من جبال الريف في يوليو 1921 / 1339 ه، وتتابعت معاركه معهم؛ فاستردَّ شفشاون -مدينة في شمال المغرب- 1925م وحاول استردادَ تطوان، وقُدِّر عددُ جيشه بمئة ألف. أنشأ جمهورية الريف، وخاف الفرنسيون امتداد الثورة إلى داخل المغرب، فتحالفوا مع الإسبان ضِدَّه. فأطبقت عليه الدولتان، فاستسلم مُضطرًّا إلى الفرنسيين في 25 مايو 1926م / 12 ذي القعدة 1344هـ بعد أن وعدوا بإطلاق سراحه، ولكنَّهم لم يَفُوا به. فنفوه إلى جزيرة (رينيون) في بحر الهند شرقيَّ إفريقية؛ حيث مكث 20 عامًا, فلما أردوا نَقْلَه إلى فرنسا سنة 1947 م، 1366 هـ وبلَغوا السويس تمكَّن الخطابي أن يهرب من الباخرة واستقَرَّ في القاهرة إلى أن توفِّيَ رحمه الله بها بسكتة قلبية."},{"id":5285,"title":"انقلاب البعثيين على الرئيس العراقي عبد الكريم قاسم ومقتله .","date":["العام الهجري :1382","الشهر القمري : رمضان","العام الميلادي :1963"],"text":"لم تنجح المحاولاتُ التي بذلتها المجموعاتُ والأحزابُ المعارِضة لعبد الكريم قاسم في إنهاء حُكمه؛ لقدرة قاسم على كشف كلِّ المحاولات ثم إحباطِها؛ فبدأ كلُّ حزب يعمل على حِدةٍ وبسِرِّية حتى تمكَّن حِزبُ البعثِ من تصفيته وتقويضِ حُكمه؛ ففي الأول من شعبان عام 1382هـ / 27 ديسمبر 1962م قامت مظاهرات طلابية بسبب تدخل المهداوي رئيس المحكمة العسكرية في شؤون إحدى المدارس، فاستغلَّ الحزبيون الموقفَ فورًا، ولما تم اعتقال أحد الضباط الحزبيين -وهو صالح مهدي- اجتمع زعماءُ الحزب المدنيون، فعلم الرئيس بهم فأمرَ باعتقالهم، ومن بينهم رئيس الحزب علي السعدي، فرأى العقيد أحمد حسن البكر رئيس المجموعة الحزبية في الجيش إعلان الثورة قبل أن تعمَّ الاعتقالاتُ؛ فبدأ التمردُ في 14 رمضان / 8 شباط في حامية أبو غريب غرب بغداد، فتمَّ اغتيالُ قائد سلاح الجو، ثم احتلوا الإذاعةَ، وبدأ القصفُ الجوي على وزارة الدفاع، وأعلنت الإذاعةُ أن حكم عبد الكريم قاسم قد انهار، مع أن المقاومة كانت ما تزال عنيفةً، وطُرِح اسم عبد السلام عارف كرئيسٍ مؤقَّتٍ لرئاسة الجمهورية؛ لسمعته الطيبة، ثم اضطرَّ عبد الكريم قاسم للاستسلام، فتشكَّلت محكمةٌ فورية قضت عليه بالقتل ونفذته فورًا، وأُذيعَ نبأُ تعيين عبد السلام عارف رئيسًا للجمهورية العراقية، وتشكيل مجلس ثورة يضم 20 عضوًا من البَعثيين وغيرهم، برئاسة العقيد أحمد حسن البكر رئيس، وكان نائبه صالح مهدي عماش، ثم رُشِّح صدام حسين التكريتي لتولِّي منصب نائب رئيس مجلس الثورة."},{"id":5286,"title":"انقلاب حزب البعث السوري  ووصوله إلى السلطة في سوريا .","date":["العام الهجري :1382","الشهر القمري : شوال","العام الميلادي :1963"],"text":"كانت سوريا قد دخلت في الوَحدة مع مصر من تاريخ 1958م وتأسَّست الجمهورية العربية المتحدة، ثم تمَّ إلغاءُ الوحدة بعد أن رأى السوريون أنهم لم يتسَلَّموا أي سلطات تُذكَر تحت السيادة المصرية، وبعد أن تمَّ الانفصال في 28 أيلول 1961م وصل حزبُ البعث السوري إلى السلطة في سوريا في ثورة الثامن آذار (مارس) 1963م، وكان مشيل عفلق (نصراني) هو رئيس الحزب ومُنَظِّره، وبعد نجاح الانقلاب كُلِّف صلاح الدين البيطار (سُني بعثي) بتشكيل الوزارة الجديدة، وأصبح أمين الحافظ (سُني بعثي) رئيسًا للبلاد. وتولى البيطار الوزارة 4 مرات، إلى أن انقلب عليهم صلاح جديد (نصيري بعثي) عام 1966م."},{"id":5287,"title":"ضم القسم الغربي من جزيرة غينيا الجديدة (إيريان الغربية) إلى أندونيسيا .","date":["العام الهجري :1382","الشهر القمري : ذي الحجة","العام الميلادي :1963"],"text":"جزيرة غينيا الجديدة أكبر جزر أندونيسيا وثاني أكبر جُزُر العالم، وتنقَسِمُ إلى قسمين: القسم الغربي، ويُعرَف باسم إيريان الغربية، ولم تستطع أندونيسيا وهولندا الاتفاقَ عليها في معاهدة 1369هـ / 1949م في لاهاي؛ فبقيت تحت السيطرة الهولندية، وبعد الضغط العسكري على هولندا جرى استفتاءٌ عامٌّ بين السكان عام 1380هـ / 1960م فتحوَّل الإقليم إلى إشراف الأمم المتحدة في 1382هـ / 1962م، ثم انتهى الأمرُ إلى أن ضُمَّ إلى أندونيسيا في ذي الحجة 1382هـ / أيار، ثم جرى استفتاءٌ في ربيع الأول 1389هـ / حزيران 1969م، فأعطت الغالبيةُ من السكان أصواتَهم إلى جانب البقاء تحت الحكم الأندونيسي، وعاصمة هذا القسم سوكارنابورا، والقسم الشرقي كان يتبع ألمانيا، ثم صار إلى أستراليا."},{"id":5288,"title":"الفاتيكان يصدر وثيقة تبرئة لليهود ليضفي على الدولة الإسرائيلية الشرعية .","date":["العام الهجري :1383","العام الميلادي :1963"],"text":"كانت المنظماتُ الصهيونيةُ تُصعِّد ضغوطَها منذ عام 1960م لاستصدار وثيقةٍ من الفاتيكان بتبرئة اليهود من دمِ المسيح، وقد صَدَرت بالفعل وثيقة فاتيكانية بعنوان (نوسترا ايتاتي) تعلن أن موت السيد المسيح  -على زعمهم- لا يمكن أن يُعزَى عشوائيًّا إلى جميع الذين عاشوا في عهده أو إلى يهود اليوم. وكان البابا يوحنا الثالث والعشرون قد ألغى من الصلاة الكاثوليكية مقطعًا يتحدَّث عن اليهود الملعونين، كما ألغى من النصوصِ الدينية جُرْمَ قَتْل الرب، على اعتبار أن الوثيقة المذكورة نصَّت أيضًا على ألا يُنظَرَ إلى اليهود كمنبوذين من الرب وملعونين، كما لو جاء ذلك في الكتاب المقدس. وسَعَت الجماعاتُ اليهودية والصهيونية إلى استثمار سريع لوثيقة 1965م، ولكِنَّ عدوان يونيو 1967م ووقوع القدس في القبضة اليهودية أوجد متغيَّرًا جديدًا أمام الفاتيكان، فركَّز منذ ذلك الوقت على تدويل القدس، وأظهر تعاطفًا مع الكفاح الفلسطيني، وبدأت تظهرُ أيضًا تعبيرات الشعب اليهودي في تصريحاته، والإشارة إلى ما تحمَّله (الشعب اليهودي) من مآسٍ. وبعد عشرين عامًا خطا البابا يوحنا بولس الثاني الخطوةَ التالية في الاتجاه نفسه، فألغى عمليًّا التعديلات التي سبق أن أُدخِلت على الوثيقة الأصلية بتأثير اعتراضات الكنائس المسيحية في البلدان العربية في حينه، وأصدر في 24/6/1985م وثيقة لجنة الفاتيكان للعَلاقات الدينية التي تضمنت تبرئة سائر أجيال اليهود من دمِ المسيح، كما تضمَّنت الربطَ الوثيق بين اليهود وإسرائيل؛ توطئةً لما قام لاحقًا من علاقات مباشرة ودبلوماسية بينهما. ورافق إصدارَ الوثيقة تعميمٌ جديد يقضي بمزيد من تعليمات الفاتيكان لسائر الكنائس الكاثوليكية؛ لتعديل ما ينبغي تعديلُه من نصوص الصلوات والمناهج المدرسية وغيرها، وفقًا للنصوص البابوية. وزاد على ذلك في 13/4/1986م قيام يوحنا بولس الثاني بزيارة كنيس يهودي في روما، وذلك لأول مرة في تاريخ الكنيسة الكاثوليكية؛ حيث خاطب سَدَنَتَه بقوله: الأحبَّاء الأعزَّاء والإخوة الكبار، وكان بينهم الحاخام الأكبر في الكنيس اليهودي، وقد اعتُبرت خطوةً رئيسة لمزيد من التقارب مع اليهود."},{"id":5289,"title":"جلاء فرنسا عن ميناء بنزرت بعد معارك مع التونسيين .","date":["العام الهجري :1383","العام الميلادي :1963"],"text":"كانت وثيقةُ الاستقلال وما جرى من مفاوضاتٍ قبلَها بين تونس وفرنسا قد تركت \"بنزرت\" قاعدةً لفرنسا، وبدأت تونس المطالبةَ بها والعمل على استرجاعها؛ من أجل مصلحة البلاد وما تقتضيه الظروفُ السياسية من تحجيم النُّفوذ الفرنسي والإنجليزي، ولكِنَّ الحكومةَ كانت تحتاج إلى إعادة تقوية لمركزها؛ فبدأت المطالبة بـ\"بنزرت\" من فرنسا وأن تنسحبَ منها، ولكِنَّ فرنسا رفضت ذلك وأصرَّت على البقاء، فأخذت المقاومة تُغِيرُ على القاعدة وتَضرِبُ أهدافًا فرنسية، ووقعت أزمةٌ بين الدولتين انتقلت إلى الأوساط الدولية وإلى أَرْوقة الأمم المتحدة، واضطرَّت فرنسا إلى الانسحاب من \"بنزرت\" بعد ذلك في 1383هـ / 1963م بعد أن جرت عدةُ معاركَ بين التونسيين والفرنسيين."},{"id":5290,"title":"التحضير لنشأة منظمة التحرير الفلسطينية وانعقاد جلسته الأولى  .","date":["العام الهجري :1383","الشهر القمري : محرم","العام الميلادي :1963"],"text":"بعد وفاة أحمد حلمي -رئيس حكومة عمومِ فلسطين، وممثل فلسطين لدى الجامعة العربية- صدر قرارٌ باختيار أحمد الشقيري لهذا المنصب، وأكَّد القرار أنَّ الشعب الفلسطيني هو صاحب الحقِّ الشرعي في فلسطين، وأن من حقِّه أن يستردَّ وطنَه، ويقرِّرَ مصيره، ويمارسَ حقوقه الوطنية الكاملة، وأنَّ الوقتَ قد حان ليتولى أهلُ فلسطين أمرَ قضيتهم، وأنَّ مِن واجب الدول العربية أن تتيحَ لهم الفرصةَ لممارسة هذا الحق. وبادر الشقيري بتسهيلات من الحكومة المصرية إلى زيارة عمان ودمشق وبيروت وقطاع غزة، وأعلن تأسيسَ منظمة التحرير الفلسطينية عام 1384هـ / 1964 بعد انعقاد المؤتمر العربي الفلسطيني الأوَّل في القدس؛ نتيجةً لقرار الجامعة العربية في اجتماعها الأول بالقاهرة عام 1964."},{"id":5291,"title":"اتفاقية الجزائر بين العراق وإيران .","date":["العام الهجري :1383","الشهر القمري : ربيع الأول","العام الميلادي :1963"],"text":"أثناء انعقاد مؤتمر القمة للدول الأعضاء في منظمة الأوبك، وبمبادرة من الرئيس الجزائري هواري بومدين تقابل مرَّتين شاه إيران وصدام حسين نائب رئيس مجلس قيادة الثورة، وأجرَيا محادثاتٍ مُطَوَّلة حول العلاقات بين الدولتين، وقرَّر الطرفان إجراءَ تخطيط نهائي لحدودهما البرية، بناء على اتفاق القسطنطينية سنة 1913م، وتحديد الحدود النهرية حسب خط تالوك (أعمق النقاط في وسط النهر)، وإعادة الثقة المتبادلة، ووضع حدٍّ للتسَلُّلات التخريبية، وإعادة الروابط التقليدية لحُسن الجوار والصداقة، واتَّفقوا على أن يتمَّ اجتماع وزراء خارجيتهما في طهران لترتيب الأعمال النهائية لتطبيق الاتفاق."},{"id":5292,"title":"تولي اللواء أمين الحافظ الرئاسة في سوريا .","date":["العام الهجري :1383","الشهر القمري : ربيع الأول","العام الميلادي :1963"],"text":"تولَّى اللواء أمين الحافظ الرئاسة في سوريا، وذلك بعد استقالة اللواء لؤي الأتاسي. وشهد حكمُ أمين الحافظ انقلابًا عسكريًّا دمويًّا انتهى بإقصائه عن السلطة واعتقالِه، وأصبح نورُ الدين مصطفى الأتاسي رئيسًا للجمهورية، وحافظ الأسد وزيرًا للدفاع."},{"id":5293,"title":"استقلال ماليزيا (اتحاد ماليزيا) .","date":["العام الهجري :1383","الشهر القمري : ربيع الآخر","العام الميلادي :1963"],"text":"اقترح رئيس وزراء الملايو تانكو عبد الرحمن في 10 شوال 1380هـ / 27 آذار 1961م العملَ مع بريطانيا وشعوب بلاد سنغافورة وبورنيو الشمالية وبروناي وسارواك؛ للوصول إلى اتفاقٍ لوضع مخطَّط يهدف إلى إيجاد تعاون سياسي واقتصادي بين هذه البلدان يؤدِّي إلى وَحدتِها، ما دامت كُلُّها تعود إلى أصلٍ واحد، فتجاوب الزعماء لهذا الاقتراح، ثم جرت محادثاتٌ، وأعلن الاتحادُ بموجِبِ استفتاء جرى في ربيع الثاني 1382هـ / أيلول 1962م إلَّا بروناي لم تقرر الدخولَ في الاتحاد، ثم عُقِدَ الاجتماع مع بريطانيا في صفر 1383هـ / تموز 1963م ونصَّ الاتفاق على السيادة في برونيو الشمالية التي أصبح يُطلق عليها اسم صباح، وفي ساراواك وسنغافورة من يد البريطانيين إلى حكومة ماليزيا في ربيع الثاني 1383هـ / 31 آب 1963م، ولكنَّ سنغافورة عادت وانسحبت من الاتحاد."},{"id":5294,"title":"ثورة 14 أكتوبر في اليمن .","date":["العام الهجري :1383","الشهر القمري : جمادى الأولى","العام الميلادي :1963"],"text":"انطلقت الشَّرارةُ الأولى لثورة 14 أكتوبر في الجزء الجنوبي من اليمن ضِدَّ الاستعمار البريطاني، من جبال ردفان، بقيادة راجح بن غالب لبوزة الذي قُتِلَ في اليوم الأول للثورة، وقد شَنَّت السلطاتُ الاستعماريةُ حملاتٍ عسكريةً غاشمةً استمرَّت ستةَ أشهر، ضربت خلالها القرى والسَّكَّان الآمنين بمختلِف أنواعِ الأسلحة؛ فتشَرَّد على إثْرِها آلاف المدنيين العُزل، واتَّبعت القوات البريطانية في هجماتها وغاراتها على مناطق ردفان سياسةَ \"الأرض المحروقة\"، وخلَّفت كارثةً إنسانيةً فظيعةً!"},{"id":5295,"title":"استقلال نيجيريا باسم اتحاد نيجيريا .","date":["العام الهجري :1383","الشهر القمري : جمادى الأولى","العام الميلادي :1963"],"text":"أعلنت بريطانيا عام 1318هـ / 1900م قيام محمية نيجيريا الشمالية، وعَيَّنت مندوبًا ساميًّا مِن قِبَلها، وفي عام 1333هـ / 1914م جاء الحاكم الإنجليزي لوغارد، فحكم البلاد حكمًا ثنائيًّا بين نيجيريا الشمالية ونيجيريا الجنوبية، وجعل من الجنوبيةِ مُستعمَرةً، ومن الشمالية محميَّةً، وكانت تحاوِلُ أن تنصِّرَ عددًا من الناس يتسَلَّمون الحكم من بعدها، وقد برز قُبَيل الحرب العالمية الثانية ناندي أزيكوي الذي قدَّم أثناء الحرب العالمية الثانية مذكِّرةً للحكومة البريطانية يطالب فيها بتوحيد أجزاء نيجيريا كلِّها، وإنهاء الاستعمار، وتأسيس إدارة وطنية للحصول على الاستقلال، وبعد الحرب العالمية الثانية جرى تطور سريع في الحياة الدستورية؛ ففي عام 1365هـ / 1946م صدر دستور وحَّد القسمين، وأقام مجالسَ نيابية، وفي شوال 1376هـ / أيار 1957م قرَّر المجلس النيابي الاتحادي بالإجماع المطالبةَ باستقلال نيجيريا بعد عامين، واستقلَّ الإقليمُ الشمالي في رمضان 1378هـ / آذار 1959م. وفي رجب 1379هـ / كانون الثاني 1960م أثار رئيسُ الوزراء قضيةَ قرار الاستقلال مُطالبًا منحَ الاستقلال لنيجيريا في ربيع الثاني 1380هـ / تشرين الأول 1960م، واتُّخذ القرارُ بالإجماع، وهكذا أصبح اتحاد نيجيريا دولةً مستقلة ضمن رابطة الشعوب البريطانية، وبقيت الدولةُ تحت رئاسة بريطانيا، وعُيِّن ناندي حاكِمًا للبلاد، وفي ربيع الثاني 1383هـ / أيلول 1963م وافق المجلسُ النيابي النيجيري على دستور جمهوريٍ يُعلِن عن قيام جمهورية اتحادية ضمن رابطة الشُّعوب البريطانية."},{"id":5296,"title":"استقلال كينيا .","date":["العام الهجري :1383","الشهر القمري : رجب","العام الميلادي :1963"],"text":"في القرن الثامن الميلادي استوطن التجَّارُ العَرَبُ الساحِلَ الشرقي لأفريقيا، وفي القرن السادس عشر سيطر البرتغاليون على البلاد. وفي عام 1887م قامت شركة أفريقيا الشرقية باستئجار جزءٍ من أرض الساحل. وفي عام 1895م ادَّعت بريطانيا أحقيَّتَها في منطقة داخلية كبيرة أسمَتْها محميَّةَ شرق أفريقيا. في عام 1920م أصبحت محميَّةُ شرق أفريقيا تعرف باسم كينيا. وفي عام 1923م رفضت بريطانيا مطالَبةَ المستوطِنين البيض بالحكم الذاتي. في سنة 1944م تمَّ تأسيسُ الاتحاد الأفريقي الكيني للمطالبة بحقوق السُّكان الأفارقة، وفي سنة 1952م بدأت جمعية ماوماو بطرد المستوطِنين البيض من أراضي القبائل الأفريقية. في عام 1956م مُنِحَ الأفارقةُ حقًّا انتخابيًّا محدودًا، وفي عام 1960م أعلنت بريطانيا عن مشروعها لإعداد كينيا لحُكمِ الأغلبية الأفريقية. وفي سنة 1963م حقَّقت كينيا استقلالها، وتولَّى كينيانا رئاسةَ الوزارة، وفي عام 1964م أصبحت كينيا جمهوريةً. ثم في عام 1969م أصبحت كينيا دولةَ الحزب الواحد الذي هو حزبُ الاتحاد الوطني الأفريقي الكيني."},{"id":5297,"title":"وفاة الشيخ محمود شلتوت شيخ الجامع الأزهر .","date":["العام الهجري :1383","الشهر القمري : رجب","العام الميلادي :1963"],"text":"هو الشيخ محمود شلتوت شيخ الجامع الأزهر بين سنة 1958 و1963م. ولِدَ في منية بني منصور، مركز إيتاي البارود بمحافظة البحيرة في مصر سنة 1893م. وحفظ القرآن الكريم وهو صغير، ونال إجازةَ العالمية سنة 1918م، وكان خطيبًا موهوبًا جهير الصوتِ. عُيِّن مدرسًا بالمعاهد، ثم بالقسمِ العالي، ثمَّ مدرِّسًا بأقسام التخصص، ثم وكيلًا لكلية الشريعة، ثم عضوًا في جماعة كبار العلماء، ثم شيخًا للأزهر، وكان أولَ حامل لِلَقَب الإمام الأكبر. نادى بتكوين مكتب عِلمي للردِّ على مفتريات أعداء الإسلام، وتنقية كتب الدين من البِدَع والضلالات، وكانت مقدِّمةً لإنشاءِ مجمع البحوث الإسلامية؛ سعى إلى إصلاح الأزهر فعارضه بعضُ كبار الشيوخ،  له 26 مؤلَّفًا، منها: ((التفسير)) لم يتم، و ((القرآن والمرأة))، و ((القرآن والقتال))، و ((هذا هو الإسلام))، و ((عنصر الخلود في الإسلام))، و ((الإسلام والتكافل الاجتماعي))، و ((حكم الشريعة الإسلامية في تنظيم النسل))، و ((الإسلام عقيدة وشريعة))، و ((الإسلام والوجود الدولي)).. وغيرها."},{"id":5298,"title":"مؤتمر القمة العربية الأول (قمة القاهرة) .","date":["العام الهجري :1383","الشهر القمري : شعبان","العام الميلادي :1964"],"text":"انعقد مؤتمرُ القمة العربية الأوَّل لأعضاء دول الجامعة العربية في القاهرة ما بين 13 إلى 16 من الشهر الأول لعام 1964م، وترأَّسه الرئيسُ جمال عبد الناصر، وحضره الرئيس أحمد الشقيري مندوبًا عن فلسطين، وقد نتج عن هذا المؤتمر عدةُ قرارات، كان من أبرزها: إنشاءُ قيادة عسكرية عربية واحدة لحماية تنفيذ المشروعات العربية بشأن استغلال مياه نهر الأردن وروافده، وإنشاءُ كِيانٍ فلسطيني يجمع إرادةَ شعب فلسطين، ويقيم هيئةً تطالب بحقوقه، وتنشيطُ المجهود العربي الإعلامي لدعم القضية الفلسطينية، وبناءً على تكليفٍ من مؤتمر القمة العربية الأول قام أحمد الشقيري بإجراء اتِّصالات مع الدُّول العربية والفعاليات والجمعيات والهيئات الفلسطينية، وقد أسفرت هذه الاتصالاتُ عن عَقْدِ المؤتمر الفلسطيني الأول في القدس بتاريخ 28 / 5 / 1964م."},{"id":5299,"title":"وفاة الكاتب الشهير عباس محمود العقاد .","date":["العام الهجري :1383","الشهر القمري : شوال","العام الميلادي :1964"],"text":"هو عباس بن محمود بن إبراهيم بن مصطفى العقَّاد، الكاتب المشهور، إمامٌ في الأدب، من المكثرين كتابةً وتصنيفًا مع الإبداع. أصلُه من دمياط، انتقل أسلافُه إلى المحلة الكبرى، وكان أحدُهم يعمل في عقادة الحرير. فعُرِف بالعقَّاد. وعمل أبوه صرَّافًا في إسنا، فتزوج بكُردية من أسوان، ووُلِدَ عباسٌ في أسوان وتعلَّم في مدرستها الابتدائية. وشُغِف بالمطالعة. وسعى للرِّزق فكان موظفًا بالسكة الحديدية، ثم بوزارة الأوقاف بالقاهرة، ثم مُعَلِّمًا في بعض المدارس الأهلية. ثم انقطع إلى الكتابة في الصحف والتأليف، وأقبل الناسُ على ما ينشر. تعلَّمَ الإنجليزيةَ في صباه وأجادها، ثمَّ ألمَّ بالألمانية والفرنسية، وظلَّ اسمُه لامعًا مدة نصف قرن، أخرج في خلالها من تصنيفه 83 كتابًا، في أنواع مختلفة من الأدب الرفيع؛ منها كتاب ((عن الله))، و((عبقرية محمد))، و((عبقرية خالد))، و((عبقرية عمر))، و((عبقرية علي))، و((عبقرية الصِّدِّيق))، و((رَجْعة أبي العلاء))، و((الفصول))، و((مراجعات في الأدب والفنون))، و((ساعات بين الكتب))، و((ابن الرومي))، و((أبو نُواس))، و((سارة)) و((سعد زغلول))، وقد اشتهر بمعاركه الفكرية مع الدكتور زكي مبارك، والأديب مصطفى صادق الرافعي، والدكتور العراقي مصطفى جواد، والدكتورة عائشة عبد الرحمن ((بنت الشاطئ)). أسَّس بالتعاون مع إبراهيم المازني وعبد الرحمن شكري \"مدرسة الديوان\"، وكانت هذه المدرسةُ من أنصار التجديد في الشعر، والخروج به عن القالَب المعروف. ثم توفي رحمه الله."},{"id":5300,"title":"تخلي الملك سعود بن عبد العزيز عن إدارة الحكم لأخيه الأمير فيصل .","date":["العام الهجري :1383","الشهر القمري : ذي القعدة","العام الميلادي :1964"],"text":"أصدر العُلماء فتوى أيَّدها معظمُ أفراد الأسرة المالكة حول تسليمِ السلطة بأكملها للأمير فيصل، على أن يبقى الملكُ سعودٌ ملكًا للبلاد، وعلى إثْرِ هذه الفتوى أصدر مجلسُ الوزراء سلسلةً من القرارات تمَّ من خلالها تشكيلُ وزارة الدفاع، ووزارة الداخلية."},{"id":5301,"title":"استقلال زنجبار (تنزانيا) .","date":["العام الهجري :1383","الشهر القمري : ذي الحجة","العام الميلادي :1964"],"text":"في عام 1381هـ استقلَّت المنطقة الأولى من تنزانيا، وهي تانجانيقا، أمَّا المنطقة الثانية، وهي زنجبار، فقد كانت محميَّةً بريطانية منذ عام 1308هـ / 1890م وسلطانها عبد الله خليفة، ومعه مقيمٌ بريطاني يُعَدُّ هو المسيطرَ الفعليَّ والحاكمَ الرسمي، ثم أصبحت سلطنةً مستقلة عن الأسرة الحاكمة في عمان عام 1383هـ / 1963م، ثم لم يلبَثْ أن وَقَع انقلاب في زنجبار بتاريخ 27 شعبان 1383هـ / 12 كانون الثاني 1963م وأُزيحَ السلطان جلمشيد بن عبد الله، وأُعلِنَت الجمهورية، وأصبح عبيد كرومي رئيسًا للجمهورية، ثم في 11 ذي الحجة 1383هـ / 23 نيسان 1964م وقَّعت الحكومةُ مرسومًا مع تانجانيقا للاتحاد في دولة واحدة؛ حيث نشأت من الاتحاد دولةُ تنزانيا."},{"id":5302,"title":"نشأة منظمة التحرير الفلسطينية  .","date":["العام الهجري :1384","الشهر القمري : محرم","العام الميلادي :1964"],"text":"مُنظَمَّةٌ سياسية شِبهُ عسكرية معترَفٌ بها في الأمم المتحدة والجامعة العربية كمُمَثِّل شرعي وحيد للشعب الفلسطيني داخل وخارج فلسطين، ولتمثيل الفلسطينيين في المحافِلِ الدولية، وهي تضُمُّ معظمَ الفصائل والأحزاب الفلسطينية تحت لوائِها. ويُعدُّ رئيسُ اللجنة التنفيذية فيها رئيسًا لفلسطين والشعب الفلسطيني في الأراضي التي تسيطِرُ عليها السلطةُ الفلسطينية في الضفة الغربية وقطاع غزة، بالإضافة إلى فلسطينيِّي الشَّتات. كان الهدفُ الرئيسي من إنشاء المنظمة هو تحرير فلسطين عبر الكفاح المسلَّح، إلا أنَّ المنظمة تبنَّت فيما بعدُ فكرةَ إنشاء دولة ديمقراطية علمانية ضِمنَ حدودِ فلسطين الانتدابيَّة."},{"id":5303,"title":"عقد المؤتمر الفلسطيني الأول .","date":["العام الهجري :1384","الشهر القمري : محرم","العام الميلادي :1964"],"text":"قام أحمد الشقيري مندوب فلسطين في الجامعة العربية بناءً على تكليفٍ من مؤتمر القمة العربية الأول في القاهرة بإجراء اتصالات مع الدول العربية والفعاليات والجمعيات والهيئات الفلسطينية، وقد أسفرت هذه الاتصالاتُ عن عقد المؤتمر الفلسطيني الأول في القدس بتاريخ 28 مايو، وصدرت عنه قرارات، أهمها:1- قيامُ إسرائيل خَطَرٌ أساسي يجب دَفْعُه سياسيًّا واقتصاديًّا وإعلاميًّا.2- إنشاءُ قيادة عربية موحَّدة لجيوش الدول العربية يبدأ تشكيلُها في كنف الجامعة العربية بالقاهرة.3- إنشاء \"هيئة استغلال مياه نهر الأردن\" لها شخصيةٌ اعتبارية في إطار جامعة الدول العربية، مهمَّتُها تخطيطُ وتنسيقُ وملاحظة المشاريع الخاصة باستغلال مياه نهر الأردن.4- إقامةُ قواعِدَ سليمة لتنظيم الشعب الفلسطيني؛ لتمكينه من تحرير وطنه وتقرير مصيره. وتمَّ توكيل أحمد الشقيري أمرَ تنظيمِ الشعب الفلسطيني."},{"id":5304,"title":"مؤتمر القمة العربية الثاني (قمة الإسكندرية) .","date":["العام الهجري :1384","الشهر القمري : جمادى الأولى","العام الميلادي :1964"],"text":"عُقِدَ مؤتمر القمَّة العربية الثاني لأعضاء جامعة الدول العربية \"قمة الإسكندرية\" في 11 مايو / أيلول 1964م بقصر المنتزَهْ بالإسكندرية، بحضورِ أربعة عشر قائدًا عربيًّا، وصدرَ عن المؤتمر بيانٌ ختامي تضمَّن مجموعةً من القراراتِ."},{"id":5305,"title":"تنحية الملك سعود عن الحكم ومبايعة أخيه ولي العهد الأمير فيصل بالملك .","date":["العام الهجري :1384","الشهر القمري : جمادى الآخرة","العام الميلادي :1964"],"text":"اجتمع العلماءُ في منزل مفتي الديار السعودية محمد بن إبراهيم آل الشيخ, ثمَّ عَقَدوا اجتماعًا مع الأمراءِ في فندق الصحراء بالرياض, ثم صادق مجلِسُ الوزراء على قرارين: فتوى العُلَماء بمبايعة ولي العهد الأمير فيصل مَلِكًا للبلاد, ورسالة وقَّعها جميعُ أفراد الأسرة المالكة تبايع الأميرَ فيصلًا ملكًا للبلاد. كما بايع الملِكَ الجديد أعضاءُ مجلس الشورى، وممثِّلو أهمِّ مناطق المملكة، ثمَّ توجَّه أعضاءُ الحكومة برئاسة الأمير خالد بن عبد العزيز إلى الملك سعود لإعلامِه بالقرارِ."},{"id":5306,"title":"مؤتمر القمة الثاني لحركة عدم الانحياز .","date":["العام الهجري :1384","الشهر القمري : جمادى الآخرة","العام الميلادي :1964"],"text":"عُقِد مؤتمرُ القمة الثاني لحركة عدم الانحياز في القاهرة بين 5- 10 أكتوبر نوقِشَت فيه قضية فلسطين ضمن البند الخاص \"بتحرير البلاد المستَعمَرة واستئصال الاستعمار بشكليه القديم والجديد، وكذلك الإمبريالية\". وتقرَّر في النهاية إدانةُ السياسة الاستعمارية المتَّبَعة في الشرق الأوسط، و\"تأييد استعادة حقوق الشعب الفلسطيني كاملةً في بلده، وحقُّه الثابت في تقرير المصير\"، كما أعلن القادةُ المشاركون في هذه القمة تأييدَهم الكامِلَ للشَّعَب العربي الفلسطيني في نضالِه من أجل التحرُّر من الاستعمارِ والعُنصرية."},{"id":5307,"title":"استقلال غامبيا .","date":["العام الهجري :1384","الشهر القمري : شعبان","العام الميلادي :1964"],"text":"كانت غامبيا قطعةً صغيرة من السنغال لكِنَّها بَقِيَت تحت الحماية الإنجليزية، بينما باقي السنغال تحت الحماية الفرنسية، حصلت غامبيا على الاستقلال الذاتي وأصبحت دولةً مستقلَّةً ضِمنَ رابطة الشعوب البريطانية (الكومنولث) في 17 شوال 1384هـ / 18 شباط، وأصبح الحكمُ جمهوريًّا فيها في محرم 1390هـ/ نيسان 1970م، وغالبية سكَّان غامبيا من المسلمين."},{"id":5308,"title":"حل الجماعة الإسلامية في باكستان ومصادرة أموالها .","date":["العام الهجري :1384","الشهر القمري : رمضان","العام الميلادي :1965"],"text":"صدرت أوامِرُ مِن حكومة أيوب خان (سُنِّي) رئيس باكستان بحلِّ الجماعة الإسلامية، ومُصادرة أموالها، وكانت الحكومةُ مِن قبل شهرٍ قد صادرت مجلة ترجمان القرآن، التي كان يُصدِرُها أبو الأعلى المودودي، وزجَّت به مع أعضاءِ جماعته البارزين في السُّجون، وكان هذا قبل وقوعِ  الحرب الثانية بين الهند وباكستان على كشمير."},{"id":5309,"title":"وفاة الزعيم الأمريكي المسلم مالكوم إكس .","date":["العام الهجري :1384","الشهر القمري : شوال","العام الميلادي :1965"],"text":"هو مالكوم إكس بن أورلي ليتل، أو الحاج مالك شباز؛ من الشخصيات الأمريكية المسلِمة البارزة في منتصف القرن الماضي، كانت حياتُه سلسلةً من التحولات؛ حيث انتقل من قاع الجريمة والانحدار إلى تطرُّف الأفكار العنصرية، ثم إلى الإسلام. وُلِد مالكوم في 6 ذي القعدة 1343هـ/ 19 مايو 1925م، وكان أبوه \"أورلي ليتل\" قسيسًا أسود من أتباع \"ماركوس كافي\" الذي أنشأ جمعيةً بنيويورك ونادى بصفاء الجنس الأسود وعودته إلى أرض أجداده في أفريقيا. وكانت العنصرية في الولايات المتحدة على أشُدِّها في ذلك الوقت. كان أبوه حريصًا على اصطحابه معه إلى الكنيسة في مدينة \"لانسينغ\"؛ حيث كانت تعيشُ أسرته على ما يجمعه الأب من الكنائس، وكان يحضُرُ مع أبيه اجتماعاتِه السياسيةَ في \"جمعية التقدُّم الزنجية\" التي تكثر خلالها الشِّعاراتُ المعادية للبِيضِ، وكان الأبُ يختم هذه الاجتماعات بقوله: إلى الأمامِ أيها الجنس الجبَّار، بوُسعِك أن تحقِّقَ المعجزاتِ. وكان هو وعائلته الزنوجَ الوحيدين بالمدينة؛ لذا كان البِيضُ يُطلِقون عليه الزِّنجيَّ أو الأسودَ، حتى ظنَّ مالكوم أن هذه الصفات جزءٌ من اسمِه، وفي عام 1931م وُجِد والده مقتولًا عند سكة القطار، فاتهمت عائلتُه مجموعةً من البِيض العُنصريين، وفي عام 1938م دخلت والدته المصحَّة العقلية بسبب معاناتها بعد فَقْدِ زوجها. قصد مالكوم بوسطن بعد انتهاء المرحلة الثانوية، وأخذته الحياةُ في مجرًى جديد؛ حيث أُصيب بنوع من الانبهار في المدينة الجميلة، وهناك انغمس في حياة اللهو والمجون. ألقت الشرطةُ القبضَ عليه وحُكِم عليه سنة 1946م بالسجن عشر سنوات، فدخل سجن \"تشارلز تاون\" العتيق، وكانت قضبانُ السجن ذات ألمٍ رهيب على نفس مالكوم؛ لذا كان عنيدًا يسُبُّ حرَّاسه، فيُحبَس حبسًا انفراديًّا، وتعلَّم من الحبس الانفرادي أن يكون ذا إرادة قويَّة يستطيع من خلالها التخلِّيَ عن كثير من عاداته، وفي عام 1947م تأثَّر بأحد السجناء ويُدعى \"بيمبي\" الذي كان يتكلَّم عن الدين والعدل، فزعزع بكلامِه ذلك الكفرَ والشَّكَّ من نفس مالكوم، وكان بيمبي يقول للسجناء: إنَّ مَن خارجَ السجن ليسوا بأفضَلَ منهم، وإنَّ الفارق بينهم وبين من في الخارج أنهم لم يقعوا في يد العدالةِ بَعدُ! ونصحه بيمبي أن يتعلَّم، فتردَّد مالكوم على مكتبة السجن وتعلم اللاتينية. وفي عام 1948م انتقل إلى سجن كونكورد، وكتب إليه أخوه \"فيلبيرت\" أنَّه اهتدى إلى الدِّينِ الطبيعي للرجل الأسود (الإسلام)، ونصَحَه ألا يدخِّن، وألا يأكُلَ لحم الخنزير، وامتثل مالكوم لِنُصح أخيه، ثم عَلِمَ أن إخوته جميعًا في دترويت وشيكاغو قد اهتَدَوا إلى الإسلام، وأنهم يتمنَّونَ أن يُسلِم مثلهم، ووجد في نفسه استعدادًا فِطريًّا للإسلام، ثم انتقل مالكوم إلى سجن \"ينورفولك\"، وهو سجنٌ مُخَفَّف في عقوباته، ويقع في الريف، ويحاضِرُ فيه بعض أساتذة الجامعة من هارفارد وبوسطن، وبه مكتبةٌ ضخمة تحوي عشرة آلاف مجلد قديم ونادر. أسلم مالكوم في السجن، وكان سبيلُه الأوَّلُ هو الاعترافَ بالذنب، ورأى أنَّه على قَدْرِ زَلَّته تكونُ توبته. وبدأ يراسِلُ كلَّ أصدقائه القدامى في الإجرام ليدعوَهم إلى الإسلام، وفي أثناء ذلك بدأ في تثقيفِ نَفسه، وبدا السجن له كأنَّه واحةٌ أو مرحلةُ اعتكافٍ علمي. خرج مالكوم من السجن سنة 1952م وذهب إلى أخيه في دترويت، وهناك تعلَّم الفاتحة وذهب إلى المسجد، وتأثَّر بأخلاق المسلمين. والتقى بالداعية إليجا محمد، وانضمَّ إلى حركة أمة الإسلام، وتبنى دعوةَ إليجا في استخدام العنف في حلِّ المشكلة العُنصرية بين السُّود والبيض في أمريكا، فبدأ يدعو الشبابَ الأسود إلى هذه الحركة، فتأثر به كثيرون؛ لأنَّه كان خطيبًا مفوَّهًا ذا حماس شديد، فذاع صيتُه حتى أصبح في فترة وجيزةٍ إمامًا ثابتًا في مسجد دترويت. وامتاز بأنه يخاطِبَ الناس باللُّغة التي يفهمونها: لغةِ العنف. وزار عددًا من المدن الكبرى، فاهتدى على يديه كثيرٌ من السود. التقى مالكوم بمارتن لوثر كينغ (نصراني وزعيم أمريكي من أصول إفريقية) يدعو إلى التفاهم مع البيض والتعايش السِّلمي ونبذ العنف، وإنهاء التمييز العنصري ضِدَّ السُّود, فاختلف معه مالكوم وهاجمه في أكثرَ من مناسبة، إلا أن مالكوم إكس أخيرًا تأثَّر بفكرة لوثر تجاه العنف وتحوَّل إلى فكرة التفاهم والتعايش مع البِيض؛ ولذلك اختلف مع إليجا، وعندما طُرد من حركة أمة الإسلام؛ بسبب مخالفته لتوجيهات إليجا في الموقف من اغتيال كندي، وقرَّر أداءَ فريضة الحج في عام 1964م، وزار العالمَ الإسلاميَّ ورأى في الطائرة التي أقلعت به من القاهرة للحَجِّ أنَّ بها ألوانًا مختلفةً من الحجيج، وأنَّ الإسلامَ ليس دينَ الرجلِ الأسودِ فقط، بل هو دينُ الإنسان. وتأثَّر مالكوم بمشهد الكعبة المشرَّفة وأصوات التلبية، وبساطة وإخاء المسلمين؛ يقول في ذلك: \"في حياتي لم أشهَدْ أصدَقَ من هذا الإخاء بين أناسٍ من جميع الألوان والأجناس، إنَّ أمريكا في حاجة إلى فهم الإسلام؛ لأنَّه الدين الوحيد الذي يملك حلَّ مشكلة العنصرية فيها\"، وقضى 12 يومًا جالسًا مع المسلمين في الحج، ورأى أنَّ الناس متساوون أمام الله بعيدًا عن سرطان العنصرية. وغيَّر مالكوم اسمَه إلى الحاج مالك شباز، وغادر مالكوم جدة في إبريل 1964م، وزار عددًا من الدول العربية والإفريقية، ورأى في أسبوعين ما لم يرَه في 39 عامًا، وخرج بمعادلة صحيحة هي: \"إدانةُ كلِّ البِيض = إدانة كلِّ السُّود\". وصاغ بعد عودته أفكارًا جديدة تدعو إلى الإسلام الصحيح؛ الإسلام اللاعُنصري، وأخذ يدعو إليه، ودعا إلى التعايش بين البِيض والسود، وأسَّس منظمةَ الاتحاد الإفريقي الأمريكي. وفي إحدى محاضراته يوم الأحد (18 شوال 1384هـ / 21 فبراير 1965م) صعد مالكوم ليلقيَ محاضرته، ونشبت مشاجرةٌ في الصف التاسع بين اثنين من الحضور، فالتفت الناسُ إليهم، وفي ذات الوقت أطلق ثلاثةُ أشخاصٍ من الصف الأول 16 رصاصةً على صدر مالكوم إكس، فتدفَّق منه الدمُ بغزارة، وفارق الحياةَ!."},{"id":5310,"title":"وفاة ملك مصر السابق فاروق بن فؤاد .","date":["العام الهجري :1384","الشهر القمري : ذي القعدة","العام الميلادي :1965"],"text":"هو الملك فاروق بن الملك فؤاد الأول بن الخديوي إسماعيل بن إبراهيم باشا بن محمد علي باشا. آخِرُ ملوك مملكة مصر والسودان. ولِدَ في 11 فبراير 1920م في القاهرة، ونشأ بها كابن وحيدٍ بين خمسِ شقيقات أنجبهم الملك فؤاد الأول، ثم أكمل تعليمَه بفرنسا وإنجلترا، أصبح وليًّا للعهد وهو صغيرُ السن، واختار الملك الوالِدُ فؤادُ الأولُ لولي عهده لقَبَ أمير الصعيد. وتحمَّل فاروقٌ المسؤولية وهو صغير السن؛ حيث إنه تولَّى العرش في 16 من عمرِه بعد وفاة والده الملك فؤاد الأول، ولأنَّه كان قاصرًا فقد تمَّ تشكيل مجلس وصاية رأَسَه ابنُ عمه الأمير محمد علي بن الخديوي توفيق أخي الملك فؤاد الأول، وكان سببُ اختياره أنه أكبر الأمراء سنًّا في ذلك الوقت، واستمَرَّت مدة الوصاية ما يقارب السنة وثلاثة شهور؛ إذ إنَّ والدته الملكة نازلي خافت بأن يطمَعَ الأمير محمد علي بالحُكمِ ويأخذه لنفسه، فأخذت فتوى بأن يُحسَب عُمرَه بالتاريخ الهجري، وأدَّى ذلك إلى أن يتوَّج فاروق مِلكًا رسميًّا بتاريخ 29 يوليو 1937، وتمَّ تعيينُ الأمير محمد علي باشا وليًّا للعَهدِ، وظَلَّ بهذا المنصب حتى ولادة ابن فاروق الأول أحمد فؤاد. استمرَّ حكمُ فاروق مدة ست عشرة سنة إلى أن أرغمته ثورة 23 يوليو 1952 على التنازل عن العرش لابنه الطفل أحمد فؤاد، الذي كان عمره حينها ستة أشهر، والذي ما لبث أن خُلِعَ بتحويل مصر من ملكية إلى جمهورية، وبعد تنازل فاروق عن العرش أقام في منفاه بروما عاصمة إيطاليا، وكان يزور منها أحيانًا سويسرا وفرنسا، وذلك إلى أن توفِّيَ بروما، ودُفِن في المقبرة الملكية بمسجد الرفاعي بالقاهرة حَسَب وصيَّتِه."},{"id":5311,"title":"وفاة عبدالله بن سليمان وزير الملك عبد العزيز .","date":["العام الهجري :1385","العام الميلادي :1965"],"text":"هو معالي الوزير عبد الله بن سليمان الحمدان وزير الملك عبد العزيز، وُلِدَ سنة 1305هـ 1887م بمدينة عنيزة في القصيم. قصد الهند بعد أن تجاوز الطفولةَ، ثم تنقَّل بينها وبين البحرين وبعض بلاد الخليج في طلب الرزق، ثم استقرَّ في الرياض؛ حيث كان له أخٌ اسمُه محمد يعمل في ديوان الملك عبدالعزيز قبل أن يتمَّ تنظيم الديوان، ولما مَرِضَ محمد ناب عنه عبد الله سنة 1338هـ 1919م، ولما رأى الملك عبد العزيز حُسنَ خَطِّه وذكاءَه ونشاطَه سَلَّمه صندوقَ دراهمه يُنفِقُ منه على بيتِه وأضيافِه. تقدَّم ابن سليمان في عمله حتى كفى الملكَ همَّ توفير المال. استمرَّ ابنُ سليمان وهو الشخصية الأولى في الدولة بعد الملك وكبار الأمراء مدةَ وزارته الطويلة، فلم يبلغْ إنسان من رجال عبد العزيز ما بلغه عنده من وثوقٍ ونفوذِ كلمة، وتمكُّنٍ؛ لذا لم يقتصِرْ عمله على المالية، بل أضيفت له مهامُّ خطيرة أخرى، كالدفاع قبل أن تنشأ وزارةُ الدفاع، ووكالةِ الخارجية أحيانًا، وشُؤون المعادن، ومنها البترول وما يتَّصِل بذلك من اتفاقيات ومداولات داخلية وخارجية؛ فهو الذي وقَّع اتفاقيةَ منح شركة \"استاندر أويل أوف كاليفورنيا\" -التي أصبحت فيما بعدُ أرامكو- حقَّ امتياز التنقيب عن النفط، وكانت من عادة ابن سليمان حين يجمعُه بالملك بلدٌ واحد أن يدخل عليه في غرفة النوم بعد صلاة الفجر كلَّ يوم، فيَعرِض عليه ما يهمُّه ويخرج بالموافقة على ما يريد، وكانت لا تخرجُ برقية من ديوان الملك إلَّا أرسلت بالبرق ثلاث نُسَخٍ منها: إلى ولي العهد، والنائب العام، وابن سليمان. استقال ابنُ سليمان بعد وفاة الملك عبد العزيز من العمل من الحكومة، وتحوَّل إلى رجل أعمال، فأنشأ فنادِقَ وشركات. خدم الملك 35 سنة، وسمِّي ابن سليمان وزيرًا للمالية سنة 1347هـ / 1929م، واستقال في مطلع محرم 1374هـ 1954م وتوفِّي بجدة."},{"id":5312,"title":"نشأة منظمة مجاهدي خلق المعارضة في إيران  .","date":["العام الهجري :1385","العام الميلادي :1965"],"text":"منظمة مجاهِدي خلق المعارضة الإيرانية أكبر وأنشط حركة معارضة إيرانية. تأسَّسَت المنظَّمة على أيدي مثقَّفين إيرانيين؛ بهدف إسقاط نظامِ الشاه، وقد أعدَمَ نظامُ الشاه مؤسِّسيها وعددًا كبيرًا من أعضاء قيادتِها، وبعد سقوطِ نظام الشاه إثرَ قيام \"ثورة الخميني الإيرانية\" أدَّت منظمة مجاهدي خلق دورًا كبيرًا في انتصار الثورة، وقد اعتمد على قوَّتها أبو الحسن بني صدر أوَّلُ رئيس للجمهورية الإيرانية، لكِنْ ظهرت فيما بعدُ خلافاتٌ بين الحركة وبين نظام الحُكم الإيراني الجديد، وصلَت بعد عامين ونصف العام من الثورة إلى حدِّ التقاتل بين الجانبين، في صراعٍ محتدِمِ ومُستمرٍّ، فقامت الحكومةُ الإيرانية بإعدام عشرات الآلاف من أعضائها والمنتمين إليها، ولكِنَّ المنظَّمة شَدَّت عزمها على مواصلة نشاطاتها داخلَ إيران وخارجَه؛ بهدف إسقاط السُّلطة الإيرانية الحالية، وتُعَدُّ منظمَّة مجاهدي خلق الإيرانية جزءًا من ائتلافٍ واسعٍ شامل يسمَّى المجلِسَ الوطني للمقاومة الإيرانية، الذي يعمل كبرلمان إيراني في المنفى، والذي يضمُّ 5 منظمات وأحزاب، و550 عضوًا بارزًا وشهيرًا من الشخصيات السياسية والثقافية والاجتماعية، والخبراء والفنانين والمثقَّفين والعلماء والضباط، إضافةً إلى قادة ما يسمى بجيش التحرير الوطني الإيراني: الذِّراعِ المسلَّح لمنظمة مجاهدي خلق الإيرانية، والذي يتمركزُ حتى اليوم في معسكر أشرف في العراق، وتكوَّنت أغلبيةُ قادته من النساء. كان مسعود رجوي من أبرز قيادات المنظمة، الذي تولى في الوقت نفسِه رئاسةَ المجلس الوطني للمقاومة الإيرانية، وفي عام 1993م انتُخِبَ بالإجماع ابنته مريم رجوي رئيسة للجمهورية للفترة الانتقالية، وهي تتولَّى مسؤوليةَ الإشراف على نقل السلطة بشكلٍ سلمي إلى الشعب الإيراني بعد سقوط النظام الإيراني."},{"id":5313,"title":"عزل الرئيس الجزائري أحمد بن بلة وتولي هواري بومدين .","date":["العام الهجري :1385","الشهر القمري : صفر","العام الميلادي :1965"],"text":"بعد أن انتُخب أحمد بن بلة رئيسًا للجزائر لم تَرُقْ للناسِ طريقتُه في الحكم؛ حيث أعلن القوانينَ الاشتراكيَّةَ ولم يُطَبِّقْها، وأبقى القانونَ الفرنسي ولم يُقِمِ المحاكِمَ الشرعية، وبقيت السياسةُ الخارجية بيد فرنسا، فتمَّ تشكيلُ مجلس عسكري برئاسة العقيد هواري بومدين في 20 صفر 1385هـ / 19 حزيران, فقَرَّر هذا المجلس عزلَ الرئيس أحمد بن بلة والقَبضَ عليه بتهمة استخدام أموال الدولة في غير وجهِها الشرعي، وتسلَّم العقيدُ هواري بومدين الرِّئاسةَ."},{"id":5314,"title":"ثورة ظفار التحررية في عمان .","date":["العام الهجري :1385","الشهر القمري : صفر","العام الميلادي :1965"],"text":"تعد ثورةُ ظفار في الجزء الجنوبي من سلطنة عمان على حُكمِ السلطان سعيد بن تيمور واحدةً من أطولِ الثورات العربية؛ حيث امتدَّت زهاءَ عشرة أعوام، وقد واكبت حقبةَ الثورات التحرُّرية من الاستعمار العالمي، والتي شَهِدتْها المنطقة العربية في الخمسينيات والستينيات من القرن العشرين، ومن أسبابِ الثورة وقيامها: حالةُ التخَلُّف التي سادت سلطنةَ مسقط وعمان بشكلٍ عامٍّ، وإقليم ظفار بشكل خاص، وكثرة الممنوعات والمعاناة من الضرائب الباهظة التي أثقلت كاهلَ العمانيين، وبعدما تعرَّف الظفاريون على أنماط المعيشة المختلفة في دول الخليج التي يعملون بها والراقية قياسًا بالوضعِ في عمان خُلِقت لديهم الرَّغبةُ الجامحة في التغيير، كما أنَّ الأوضاعَ التي عاشتها المنطقةُ آنذاك، وانتشارَ المد القومي العربي بزعامة جمال عبد الناصر أدَّى إلى تأثُّر أبناء الأمة العربية، ومِن ضمنِهم الظفاريون بأفكار القومية العربية المنادية بالوحدة والتحَرُّر من الاستعمار ومقاومته بشتى الوسائل؛ مما ولَّد لدى الظفاريين النزعةَ نحو الثورة ضِدَّ الوجود البريطاني في عمان. عَمِلَ الظفاريون على تنفيذ الثورة من خلالِ تشكيل تنظيمات سريَّة متعَدِّدة كان لها دوافِعُ وانتماءات مختلفة بين قوميٍّ عربيٍّ هدفُه مقاومةُ بريطانيا، وتمثَّل في التنظيم لحركة القوميين العرب، وآخَرَ هدفُه تحسينُ الأوضاع الاجتماعية في عمان، وتمثَّل في الجمعية الخيرية الظفارية. وتُنسَب بدايةُ الثورة إلى مسلم بن نفل الذي كان يعمَلُ في مزرعة قصر السلطان سعيد بن تيمور والذي أقصاه من عمله في القصر السلطاني عام 1963 بسبب أفكاره الثورية, فكانت بداية الثورة في أبريل 1963 من خلال هجومٍ مسلح على حافلات شركة النفط، خطَّط له مسلم بن نفل، ثم فرَّ مسلم بن نفل مع 30 رجلًا من جماعته خارج عمان حيث رحلوا إلى العراق التي كانت تُحكَمُ من قبل النظام البعثي، فتلقَّوا تدريبًا عسكريًّا، وفي صيف 1964 عادت مجموعةُ ابن نفل إلى ظفار بدعم مالي وعسكري من عدد من الدول العربية، منها: مصر، واليمن الجنوبي، ولم يلبث عام 1965م أن شهد إعلان قيام \"جبهة تحرير ظفار\" التي أعلنت الثورةَ ضِدَّ حكم السلطنة، كما دعا بيانٌ للجبهة الظفاريين إلى الانضمام إلى الثوَّار؛ من أجل تحرير الوطن من حكم السلطان سعيد بن تيمور، وتحرير البلاد من البطالة والفقر والجهل، وإقامة حكم وطني ديمقراطي. بدأت حربُ ظفار بعمليات كرٍّ وفرٍّ ضِدَّ أهداف تابعة لحكومة السلطان سعيد بن تيمور، وكانت الحربُ سِجالًا بين الثوار وقوَّات السلطان سعيد، وفي 28 أبريل 1966 وقعت محاولةٌ لاغتيال السلطان سعيد بن تيمور احتجب بعدها السلطانُ عن الظهور، الأمر الذي جعل الثوَّارَ يعتقدون أنه قُتِل، وأن السلطات البريطانية هي التي تدير شؤون السلطنة. إلَّا أن الثوار تلقَّوا هزائم متكررة، وبعد تولِّي السلطان قابوس بن سعيد مقاليدَ الحكم في 23 يوليو 1970م كمبادرة منه لإنهاء ثورة ظفار أعلن العفوَ العامَّ عن جميع المتمرِّدين، ووعد أيَّ ظفاري مشترِك في حركة التمرد بمعاملة حسنة، ووعد كذلك بتحقيق مطالبِ المتمرِّدين الرئيسية وَفق برنامج إصلاحي اجتماعي، وقد حصل السلطانُ بوعدٍ من إيران بتقديمِ مساعدة عسكرية للقضاء على حركة التحرر، وقام السلطان بحملةِ قتل جماعية في حقِّ عدد من أعضاء الجبهة قُدِّرَ عَددُهم بـ 300 عضو، وفي نفس الفترة قام مسلم بن نفل بتسليم نفسه إلى قوات السلطان، ثم تزايدت الاغتيالات في صفوف الجبهة؛ حيث تمَّ تنفيذ أحكام قتل على مجموعة كبيرة أخرى من الظفاريين قريب من 40 شخصًا. كما زاد عددُ الذين يستسلمون لجيش السلطان، ثم ينضمون بأسلحتهم إلى ما يسمى بالفِرَق الوطنية لمحاربة قادتهم السياسيين في جبهة تحرير ظفار، وبلغ عددهم 2000 مقاتل، ومع بداية عام 1975م بات الثوارُ غير قادرين على مواجهة قوات السلطان المدعومة بالقوات الإيرانية على جميع جبهات القتال، ولأولِ مرة منذ 10 أعوام أصبح كل إقليم ظفار تحت سيطرة الحكومة، وفي الجانب السياسيِّ توصَّلت سلطنة عمان واليمن الجنوبي برعاية سعودية إلى اتفاقٍ ينهي الخلافات القائمةَ بينهما، وتوقَّف اليمن الجنوبي عن دعم الثوار؛ ممَّا أدى إلى استسلام العديد من قياداتها للسلطنة، كان من أبرزهم عمر بن سليم العمري الذي كان من القادة المتنفذين في الجبهة، ولم يمضِ عام 1976م حتى تمَّت التصفية النهائية للثورة في ظفار، وبعد القضاء على الحركة أعلن السلطانُ قابوس في العيد الوطني السادس للسلطنة في نوفمبر 1976م دمج إقليم ظفار في سلطنة عمان."},{"id":5315,"title":"استقلال جزر المالديف  .","date":["العام الهجري :1385","الشهر القمري : ربيع الأول","العام الميلادي :1965"],"text":"جُزُر المالديف مجموعةُ جُزُر صغيرة تقع في قارة آسيا في المحيط الهندي، جميعُ سُكَّانها مسلمون، وأوَّلُ من استعمرها هم البرتغاليون، ثم خلَفَهم الهولنديون، ثم الإنجليز عام 1211هـ، لكِنْ بَقِيَ الهولنديون أصحابَ النفوذ إلى عام 1305هـ؛ حيث أصبحت الجُزُر كُلُّها تحت الحماية الإنجليزية، ولكِنَّ قبضة الإنجليز بدأت بالتراخي عام 1350هـ؛ فأعلن السلطان شمس الدين إسكندر الدستورَ، وتغيَّرَ أسلوبُ الإنجليز الذين أصبحوا يفضِّلون النفوذَ والسيطرة الاقتصادية، وأمَّا الحكم فيسلمونه لأنصارهم وأعوانهم، فأُعلِنت الجمهوريةُ المالديفية عام 1373هـ، وعُين محمد أمين ديدي سلطانًا على البلاد، ثم تعهَّدت إنجلترا عام 1380هـ بدعم جُزُر المالديف ماديًّا، وبعد خمسة أعوام 1385هـ اتَّفَقت مع إنجلترا على معاهدة جديدة؛ تأكيدًا لاتفاقية عام 1376هـ، واحتفظت بموجِبها إنجلترا بقاعدةٍ جوية في جزيرة جان بمقاطعة أصول، ونالت بعدها البلادُ الاستقلالَ، وخرجت من عضوية رابطة الشعوب البريطانية (الكومنولث)، وقُبِلَت المالديف عضوًا في الأمم المتحدة."},{"id":5316,"title":"الحرب الثانية بين باكستان والهند بشأن كشمير .","date":["العام الهجري :1385","الشهر القمري : جمادى الأولى","العام الميلادي :1965"],"text":"اخترق الجيشُ الهندي خطَّ وَقْفِ النار في كشمير، واحتَلَّ أربعة مراكز في دولة كشمير الحرة، فقامت باكستان مباشَرةً برَدِّ فعلٍ مفاجئ بجنوبي كشمير التي تحتلُّها الهند، فقامت الهندُ بشنِّ هجوم على الحدود الباكستانية في منطقة لاهور بالإضافة إلى قصفِ المُدُن الباكستانية بالقنابل، فانتقلت الحربُ من أرض كشمير إلى أرض باكستان، ثم فتحت الهند جبهةً أخرى في جنوبي باكستان على محور كراتشي، فردَّ الباكستانيون الهجومَ بكل قوة، غير أنَّ مجلسَ الأمن أصدر قرارًا بوقف إطلاق النار وإنهاء القتال في 29 شعبان 1385هـ / 22 ديسمبر 1965م؛ فتوقَّفت الحرب."},{"id":5317,"title":"محاولة انقلاب فاشلة على الرئيس العراقي عبد السلام عارف  .","date":["العام الهجري :1385","الشهر القمري : جمادى الأولى","العام الميلادي :1965"],"text":"كان عبد السلام عارف من المعارِضين للوَحدة مع مصر، وكان عارف عبد الرزاق رئيسُ الحكومة يطمَحُ برئاسة الجمهورية، فما إنْ سافر الرئيس إلى الدار البيضاء لحضور مؤتمر القمة حتى بدأ نشاطُه، وأخذ الضبَّاطُ الناصريون بالاتِّصالِ بالضبَّاط أصحاب المراكز الحساسة، ويشجِّعونهم على العمل ضِدَّ الرئيس عارف، ووضعوا خطةً للانقلاب؛ فقاموا بعمل مظاهراتٍ من الطلَّاب والعمَّال بتوجيه من الضباط الناصرِّيين، وفي الوقتِ نَفسِه كان الموالون للرئيس عبد السلام عارف يعملون على إحباط مخطَّطاتهم، وفي 11 جمادى الأولى / 16 أيلول حرَّك الانقلابيون المدرَّعات، فوقف بوجهِهم آمِرُ بغداد وآمِرُ الشرطة، وكانت القواتُ بيدهم أيضًا، فهددوهم بأنَّهم على استعدادٍ لتدميرهم فورًا، ففَشِلَ الانقلاب وهرب رئيسُ الحكومة عارف عبد الرزاق إلى مصر."},{"id":5318,"title":"فشل الثورة الشيوعية الثانية في أندونيسيا .","date":["العام الهجري :1385","الشهر القمري : جمادى الآخرة","العام الميلادي :1965"],"text":"أعاد الحزبُ الشيوعي في أندونيسيا تنظيمَ نفسه مجدَّدًا بعد أن فَشِلَت ثورته الأولى عام 1367هـ، وبدأ بتقويةِ وَضْعِه وخاصةً مع مساعدة الرئيس أحمد سوكارنو لهم بالإضافة للأموال الضخمةِ من المعسكر الشيوعي، ثم أعلن الحزبُ الشيوعي أنَّه سيكون الحزبَ الوحيدَ، وأنَّه سيحوِّل البلادَ إلى دولة تسير حَسَب المنهج الشيوعي، وبدأت أعمالُ الشيوعيين الإرهابية، وأخافوا الناس؛ فهجموا على المدارس الإسلامية والشخصيات البارزة، وقرروا إعلان الثورة في 5 جمادى الآخرة / 30 أيلول، وبرَّروا ذلك بمرض الرئيس أحمد سوكارنو، وبعدم مبالاة القوات المسلحة بالأمر، وبعدم أهليةِ مجلس الجنرالات، ورغبته في الاستيلاء على السلطة، وكذلك زعمُهم حمايةَ البلاد من الرجعية والإمبريالية، وفي يوم إعلان الثورة أمر رئيسُ الحرس الجمهوري باختطاف بعض كبار الضباط، وفي اليوم التالي للثورة أذاع الشيوعيون أوَّلَ بياناتهم بالإذاعة الرسمية، ولكِنَّ وزير الدفاع الذي استطاع الإفلاتَ من محاولة القضاء عليه أعطى أوامِرَه للقضاء على الثورة الشيوعية، وانتفض الشعبُ أيضًا، ولم تمضِ ساعاتٌ حتى فَشِل الشيوعيون، وسيطرت القواتُ المسلَّحةُ على الوضع."},{"id":5319,"title":"وفاة الشيخ محمد بن عبد العزيز ابن مانع .","date":["العام الهجري :1385","الشهر القمري : رجب","العام الميلادي :1965"],"text":"هو الشيخُ الفقيه محمد بن عبد العزيز بن محمد بن مانع الوهيبي التميمي النجدي. ولِدَ في مدينة عنيزة إحدى مدن القصيم سنة 1300 هـ، ولما بلغ السابعةَ أدخله والده الكتاتيبَ؛ ليتعلم بها القرآنَ، ولم يلبث والدُه أن توفِّي، فشرع في القراءةِ على عُلماء بلده، فقرأ على عمِّه الشيخ عبد الله، وعلى الشيخ صالح العثمان القاضي، ولما بلغ الثامنةَ عَشْرة من عمره سافر إلى بغداد، واتصل بالعلامة السيد محمود شكري الألوسي، فقرأ عليه وعلى ابن عمه السيد علي الألوسي، وقرأ على غيرِهما من مشاهير العلماء ببغداد، فقرأ في النحو والصرف والفقه، والفرائض والحساب، ثم توجَّه إلى مصر فأقام في الأزهر مدةً قرأ فيها على الشيخ محمد الذهبي، ثم سافر إلى دمشق الشام ولازم الشيخ جمال الدين القاسمي، وحضر دروسَ الشيخ بدر الدين محدِّث الشام، وحضر دروس العلامة الشيخ عبد الرزاق البيطار، ثم رجع إلى بغدادَ ولازم القراءةَ على العلامة محمود شكري الألوسي، فقرأ عليه كثيرًا من مؤلفات شيخ الإسلام ابن تيميَّة، وكثيرًا من الكتب والشروح والرسائل المختصرة، وفي هذه المدة دعاه بعضُ الأكابر من أهل بغداد؛ ليكونَ إمامًا له ويقرأ عليه كتبَ الحديث، فقرأ عليه بعضًا من صحيح البخاري، وجميعَ صحيح مسلم، والجزءَ الأوَّلَ مِن زاد المعاد لابن القيم، والجزءَ الأوَّلَ من مسند الإمام أحمد بن حنبل، والموطَّأ للإمام مالك، وكثيرًا من كتب التاريخ، وقرأ نزهةَ النظر للحافظ ابن حجر، ثم رجع إلى بلده مدينة عنيزة سنة 1329هـ وقرأ على قاضيها الرَّوض المُرْبِع، ثمَّ توجه إلى بلد الزبير سنة 1330هـ وقرأ على الفقيه الحنبلي المشهور في بلدة الزبير محمد العوجان في الفقه الحنبلي والفرائض والحساب، ثم دعاه مُقبل الذكير أحد تجار نجد وأعيانها -المقيمين في البحرين للتجارة- دعاه لمكافحة التنصير، وفتح له لهذا الغرض مدرسة لتعليم علوم الشريعة واللغة سنة 1330هـ، فأقام في البحرين أربعَ سنين شرح في أثنائها العقيدةَ السفارينية، ثم دعاه حاكم قطر عبد الله بن قاسم بن محمد بن ثاني، فتوجَّه إليها في شوال سنة 1334هـ فتولَّى القضاءَ والخطابة والتدريس، ورحل إليه كثيرٌ من الطلاب أخذوا عنه العلمَ في قَطَر، وأقام في قطر أربعًا وعشرين سنة تولى خلالها القضاءَ والفتيا، وتزوَّج في قطر وأنجب أبناءه الثلاثة: الشيخ عبد العزيز، وأحمد، وعبد الرحمن، وأنشأ في قَطَر أوَّلَ مدرسةٍ علمية سنة 1336هـ، واستمرَّت نحو سبعة عشر عامًا. وبَقِيَ في قَطَر إلى صَفَر سنة 1358هـ، فقَدِمَ الأحساءَ ومكث بها إلى شهر جمادى الآخرة، وفي هذه الأثناء قَدِمَ الأحساءَ معالي الوزير ابن سليمان وزير الملك عبد العزيز، فاتصل به وقابله وأشار عليه ابن سليمان أن يقابِلَ الملك عبد العزيز، فقَدِمَ عليه في مدينة الرياض فأكرمه وعيَّنه مدرسًا في الحرم المكي الشريف، فأقام في مكَّةَ واجتمع عليه كثيرٌ من طلاب العلم يقرؤون عليه في الفقه والحديث، والنحو والفرائض، منهم الشيخ عبد العزيز بن رشيد رئيس هيئة التمييز بنجد، والشيخ عبد اللطيف بن إبراهيم بن عبد اللطيف الباهلي، والشيخ البصيلي، والشيخ ناصر بن حمد الراشد الرئيس العام لتعليم البنات، والشيخ عبد الله بن زيد بن محمود، ومن أبرز تلامذته: الشيخ عبد الرحمن السعدي؛ علَّامة القصيم، وبعد قيامه بواجب التدريس بالمسجد الحرام عيَّنه الملك عبد العزيز زيادةً على ذلك رئيسًا لثلاث هيئات: هيئة تمييز القضايا، وهيئة الأمر بالمعروف، وهيئة الوعظ والإرشاد. وقام بهذه الأعمال إلى جانب قيامِه بالتدريس في المسجد الحرام بعد صلاتَي الفجر والمغرب، وفي عام 1364هـ عيَّنه الملكُ مديرًا للمعارف، وفي سنة 1366هـ أسند إليه رئاسةَ دار التوحيد، ولما شُكِّلت وزارةُ المعارف سنة 1373هـ وعُيِّن الأمير فهد بن عبد العزيز وزيرًا لها نُقِلَ الشيخ ابن مانع مستشارًا برتبة وكيل وزارة إلى عام 1377ه،ـ حيث طلبه حاكِمُ قطر، ولازم الشيخ علي بن الشيخ عبد الله بن قاسم بن ثاني إلى أن توفي رحمه الله ببيروت على إثر عملية جراحية أُجريت له، ونُقِل جثمانه إلى قَطَر ودُفِن بها، وخَلَّف ثلاثة أبناء: عبد العزيز، وأحمد، وعبد الرحمن, ومكتبةً كبيرة حافلة بنوادر الكتب، ومؤلفات كثيرة، منها: ((إقامة الدليل والبرهان بتحريم الإجارة على قراءة القرآن))، و ((تحديث النظر في أخبار الإمام المهدي المنتظر))، و ((إرشاد الطلاب إلى فضيلة العلم والعمل والآداب))، و ((الأجوبة الحميدة: رسالة تتعلق بالتوحيد))، و ((حاشية على دليل الطالب))، و ((سبل الهدى شرح قطر الندى))، وله ((الكواكب الدرية شرح الدرة المضيئة))، و ((القول السديد فيما يجب لله على العبيد))."},{"id":5320,"title":"انعقاد مؤتمر طشقند لحل النزاع الهندي الباكستاني .","date":["العام الهجري :1385","الشهر القمري : رمضان","العام الميلادي :1966"],"text":"بعد أن أُوقِفَ إطلاقُ النارِ بين الهند وباكستان بقرارٍ من مجلس الأمن تمَّ اقتراحُ تدخُّل الاتحاد السوفيتي كوسيط؛ لفضِّ النزاعِ بين باكستان والهند حول قضية كشمير، وذلك في أعقاب حرب 1965م، فطَرَحت روسيا أن يجتَمِعَ الطرفان في \"طشقند\" قاعدةِ جمهورية أوزبكستان الإسلامية، فعُقِدَ مؤتمرٌ حَضَره رئيس وزراء الهند والرئيس الباكستاني، وكان الرئيس الروسي طوال المؤتمر في طشقند، وقد تمَّ التوصُّلُ إلى اتفاقٍ محدود يتضمَّنُ موافقةَ الطرفين على حلِّ المشاكل التي ترتَّبت على حرب 1965م، وتأجيلَ بحثِ ومناقشة قضيةِ كشمير إلى حينٍ آخَرَ، وصَدَرَ إعلانُ طشقند المتضَمِّنُ إعادةَ العلاقات السِّلمية بين البلدين، وسحْبَ القَّوات المسلحة."},{"id":5321,"title":"وفاة الحاج سير أحمدو بلو زعيم إقليم شمال نيجيريا .","date":["العام الهجري :1385","الشهر القمري : رمضان","العام الميلادي :1966"],"text":"هو الحاج سير أحمدو بلو بن الأمير إبراهيم بن فودي: زعيمٌ سياسيٌّ نيجيري شمالي. مفكرٌ إسلاميٌّ سياسي كان من أبرز قادةِ مقاومة الاستعمار الإنجليزي. وُلِدَ سنة 1909م بقرية رابا، وتعلَّم في كُتَّابها سنتين، ثم أخذه أخوه إلى مدينة صكتو؛ لِيُلحِقَه بمدرسةٍ ابتدائية هناك، فدرس فيها القرآنَ الكريم، والحساب، واللغة الإنجليزية، والتاريخ، لكنَّه أبدى أسَفَه حين رأى أنَّ التاريخَ الذي يَدرسُه تاريخ إنجلترا بدلًا من تاريخ بلادِه. كان جادًّا في دراسته ما جعَله بعد خمسِ سنين يتخرَّجُ بتفوق على أقرانه، وفي عام 1926م انتقل إلى كلية المعلِّمين في كاتسينا؛ ليتخرَّج معلِّمًا، فعاد إلى مدرسته الأولى في صكتو ليدرِّسَ بها اللغةَ الإنجليزية، والهندسة، ومبادئ اللغة العربية، وفي عام 1934م عيَّنه السُّلطان رئيسًا لمركز (رابا) مسقط رأسِه بعد وفاة ابن عمِّه، فكان أصغرَ رئيسٍ من بين 45 رئيسًا؛ إذ كان عمره 24 سنةً، فكان أوَّلُ عملٍ أقدَمَ عليه هو مكافحةَ الجهل والأميَّة في قريته، حتى إنه لم يكُنْ فيها مَن يَعرف القراءةَ والكتابةَ سواه، فأنشَأ مدرسةً تولَّى التَّدريسَ فيها بنفسه، فلمَّا تعلَّم عددٌ من أهل القرية القراءة والكتابة فَتح فصولًا أخرى، حتى بُنيت أوَّلُ مدرسةٍ نظاميَّة في القرية. في عام 1938م انتقل أحمد بلو إلى (غسو)، وقد عيَّنه السلطان الحاج أبو بكر تفاوة بيليوا رئيسُ وزراء حكومة اتحاد نيجيريا مُشرفًا على 14 مركزًا في سلطنة صكتو، وبهذا اكتسب بلو مهاراتٍ إدارية. ولما أُعلِنَت الحربُ العالمية الثانية عُيِّن بلو ضابطًا للحرب في صكتو. وفي عام 1948م سافر بلو إلى لندن؛ لدراسة نظُمِ الحكم المحلي، وفي عام 1949م ذهب إلى عاصمة نيجيريا لاجوس لأوَّلِ مرة حين توفي وزير صكتو، وأصبح يمثِّل صكتو، وحين بدأت إجراءاتُ تعديل الدستور النيجيري اجتمع الشماليون في (كدونا)، واختاروا مندوبَين منهم للاشتراك في هذا العمل المهم، وكان أحدهما: أحمدو بلو. وفي عام 1953م تقلَّد وزارتَيْ تطوير المجتمع والحكومة المحلية، وفي أكتوبر 1954م أصبح بلو رئيسًا لوزراء الإقليم الشمالي، وظل في هذا المنصب حتى تم اغتياله رحمه الله."},{"id":5322,"title":"انقلاب عسكري بعثي في سوريا على أمين الحافظ رئيس الجمهورية .","date":["العام الهجري :1385","الشهر القمري : شوال","العام الميلادي :1966"],"text":"بعد انقلابِ حزبِ البَعثِ السوري على الحكومة العربية السورية في الثامن آذار عام 1963م في سوريا قامت حكومةٌ ضعيفة توالى عليها ثلاثةُ رؤساء، وبدأت الحكوماتُ البعثيةُ بسلسلة من الإجراءات الاشتراكية، إلا أنَّ الفترة الأولى من الحكم البعثي الاشتراكي في سوريا كانت مضطربةً؛ فوقع انقلابٌ عسكريٌّ بعثيٌّ في 23شباط / فبراير 1966م بقياده صلاح جديد (نصيري بعثي) بهدف الإطاحة بحكومة الجمهورية العربية السورية التي يرأسها أمين الحافظ (سُني بعثي)، ففَرَّ أمين الحافظ ورئيس الوزراء صلاح الدين البيطار (سُني بعثي) إلى خارج سوريا."},{"id":5323,"title":"وفاة عبد السلام عارف رئيس جمهورية العراق .","date":["العام الهجري :1385","الشهر القمري : ذي الحجة","العام الميلادي :1966"],"text":"هو عبد السلام محمد عارف الجميلي: ثاني رؤساء العراق بعد سقوطِ المَلَكيَّة وقيام الجمهورية العراقية، وقد وُلِدَ في مدينة \"حديثة\" على نهر الفرات في أسرة فقيرة، ثم انتقل مع أسرته إلى بغداد والتحق بالمدارس الحكومية، ثم دخل الكليةَ الحربيَّةَ وتخرَّج منها برتبة ملازم، ثم اشترك في حربِ فلسطين، وقابل هناك عبدَ الكريم قاسم، وانضمَّ عن طريقه إلى اللجنة المركزية للثورة العراقية، وقام بدورٍ كبير في الثورة على المَلَكية في ذي الحجة سنة 1377هـ؛ حيث قاد اللواءَ العشرين ببغداد، واستولى على مبنى الإذاعة وأصدر بيانَ الثورة، وأعلن قيامَ الجمهورية؛ ولذلك كان يُعِدُّ نفسَه القائدَ الفعليَّ للثورة، وقد تمَّ تعيينُه نائبًا للرئيس عبد الكريم قاسم. أصبح عبد السلام عارف رئيسًا للعراق سنة 1382هـ بعد خلافاتٍ شديدة مع عبد الكريم قاسم انتهت بمقتل قاسم بعد سلسلةٍ من المظاهرات والاضطرابات ضِدَّ حُكمِه، كان عبدُ السلام عارف ذا مُيولٍ أخلاقيَّة إسلامية، ولكنَّه كان شديدَ الانبهار بالرئيس المصري جمال عبد الناصر، وكان يرى وجوبَ الانضمامِ إلى مصر على نمطِ الاتحاد المصري السوري، فلما تولى الرياسةَ نظَّم الحكمَ على النَّمَطِ النَّاصري؛ مما أثار عليه حزبَ البعث والأحزاب الشيوعية، ثم زادت الأمورُ اضطرابًا بعد فشل الاتحاد بين مصر وسوريا؛ بسبب حزبِ البعث السوري، فبَطَش عارف بالبعثيين في العراق لإرضاء عبد الناصر، ثم أخذ في إرساءِ قواعد الوَحدة بين مصر والعراق، وحضر حفلَ تدشين بناء السد العالي سنة 1384ه، وبدأ في تنظيمِ الدستور العراقي بصورةٍ تشبه لحدٍّ كبيرٍ الدستورَ المصري، وأمَّم المصارِفَ والصناعات الكبرى، ولكنَّه قام أيضًا بإلغاء الأحكامِ العرفيَّة، والمحاكم العسكرية، وأطلق سراحَ المعتقلين السياسيين. بعد ذلك أخذ الخلافُ يظهر بين أتباع الحزب الناصري الذين يريدون الوَحدةَ مباشرةً دون دراسةٍ والخضوعَ التامَّ لعبد الناصر، وبين عبد السلام عارف الذي لم يقبَلْ بالوحدة، وحاول الناصريونَ الانقلابَ على عارف أثناء وجوده في مؤتمر القمة العربية بالدار البيضاء سنة 1385هـ، وطلب جمال عبد الناصر من عبد السلام عارف العفوَ عن المتآمرين وقادةِ الانقلاب، ولكنَّ عارفًا رفض بشدة، ثم زادت الشُّقَّةُ بين الرجلين وشعر عبد الناصر بأنَّ عارفًا لم يكن يومًا من أتباعِه أو أنصارِه. وفي يوم 23 من ذي الحجة سنة 1385هـ وأثناء رحلة داخلية لعبد السلام عارف بالطائرة الهليكوبتر وعند قرية «القرنة» قرب البصرة انفجرت الطائرةُ بسبب قنبلةٍ وُضِعَت فيها، ليلقى عبد السلام عارف ورفاقُه مصرعَهم في الحال، وقد أذاعت الحكومةُ العراقيَّةُ أنَّ سَبَبَ الحادثة العواصِفُ الرَّعديةُ! وهكذا انتهت حياتُه  بصورةٍ غامضة."},{"id":5324,"title":"عودة العلاقة شكليًّا بين السعودية ومصر .","date":["العام الهجري :1386","العام الميلادي :1966"],"text":"استأنفت السعوديةُ عَلاقتَها الوُدِّيَّةَ شَكليًّا مع مصر بعد تقديمِ تنازلاتٍ من عبدالناصر. وأضحت السعوديةُ قادرةً على  تقديمِ المساعدة الماليَّة لدُولِ المجابهة العربية مع إسرائيل, وكانت مصرُ قد استنزفتها حربُ اليمن وهزمَتها إسرائيلُ في حزيران 67, ففقدت شبه جزيرة سيناء، وعوائدَ قناة السويس, فتركَّزت كُلُّ جهودها على استعادة قدرتها الدفاعيَّة، واتِّباع سياسةٍ خارجيةٍ أكثرَ مرونةً؛ فقَدَّمت تنازلاتٍ للسعودية."},{"id":5325,"title":"تنازل الرئيس التركي جمال غورسيل وفوز جودت صوناي بالرئاسة .","date":["العام الهجري :1386","العام الميلادي :1966"],"text":"سار الرَّئيسُ التركي جمال غورسيل على نهجِ مصطفى كمال، خاصةً وأنَّ حُكمَه كان حُكمًا عسكريًّا، ثم إنَّ أوضاعَ الرئيس جمال الصحيَّة ساءت؛ ممَّا دعاه إلى الاعتزالِ قبل انتهاء فترةِ الرئاسة بما يقرُبُ من السنتين، وأُجريت انتخاباتٌ لاختيار رئيسٍ مكانه، فنجح جودت صوناي."},{"id":5326,"title":"تحويل اتحاد نيجيريا إلى جمهورية نيجيريا الاتحادية .","date":["العام الهجري :1386","الشهر القمري : صفر","العام الميلادي :1966"],"text":"قام قائدُ الجيش جونسون أغوي إيرونسي وهو من قبائل الإيبو (الوثنية) بإقالةِ الحكومة الاتحادية والحكومات الإقليمية، وعيَّن حاكِمًا عسكريًّا لكل إقليم، وبذلك صارت البلاد كلُّها تحت قبضته، وشكَّل مجلسًا عسكريًّا أعلى، وأعلنت السلطةُ العسكريةُ مقترحاتٍ في شوال 1385هـ / شباط 1966م لإلغاء الدولة الاتحادية وإقامة دولة وَحدَوية، ثم غيَّرَت السلطة العسكرية اسمَ البلاد؛ فأصبحت جمهورية نيجيريا الاتحادية بعد أن كانت اتحاد نيجيريا."},{"id":5327,"title":"وفاة الشيخ عبد الرحمن المعلمي .","date":["العام الهجري :1386","الشهر القمري : صفر","العام الميلادي :1966"],"text":"هو الشيخُ العلامة أبو عبد الله عبد الرحمن بن يحيى بن علي بن أبي بكر المعَلِّمي العتمي اليمني، وُلِدَ في أولِ سنة 1313هـ بقرية المحاقرة  التابعة لمحافظة صنعاء، قرأ القرآنَ على والدِه، ثم درس في المدرسةِ الحكومية، وتعلَّم القرآنَ والتجويدَ والحسابَ، ثم قرأ النحو، ثم ارتحل إلى جازان سنة 1336هـ، فترأَّس فيها القضاءَ، ثم ارتحل إلى عَدَن ثمَّ الهند مصحِّحًا لكتب الحديث وعلومه، ثمَّ إلى مكة سنة 1371هـ وكان بارعًا في علم الحديثِ والرِّجالِ والجَرح والتعديل، وله مؤلفات، منها: ((التنكيل بما في تأنيب الكوثري من الأباطيل))، و ((الأنوار الكاشفة بما في كتاب أضواء على السُّنَّة من الزلل والتضليل والمجازفة))، في الردِّ على أبي رَيَّة. و ((علمُ الرجال وأهميته))، وله بحوث كثيرة مستقِلَّة، وله تحقيقات، منها تحقيق كتاب الرد على الأخنائي لابن تيمية، والفوائد المجموعة، والجَرح والتعديل وتقدِمتُه، والمنار المنيف في الصحيح والضعيف، وغيرها كثير، توفي رحمه الله في مكَّةَ المكرمة، وعمره ثلاث وسبعون سنة."},{"id":5328,"title":"محاولات انقلاب فاشلة على الرئيس العراقي عبد الرحمن عارف .","date":["العام الهجري :1386","الشهر القمري : ربيع الأول","العام الميلادي :1966"],"text":"كان عارف عبد الرزاق (ناصريُّ التوجُّه) قد حاول الانقلابَ على رئيس العراقِ عبد الرحمن عارف الجميلي في جمادى الأولى 1385هـ / 16 أيلول بالاشتراكِ مع عددٍ من كِبار الضبَّاط العراقيِّين، وبدعمٍ مِن المخابراتِ السُّوريَّةِ؛ لِقَلبِ نظامِ الحُكمِ في العراق, ففَشِلَ وهرب إلى مصرَ، ثم تسَلَّل من مصرَ إلى بغدادَ مع بعض الأشخاص، وفي 11 ربيع الأول من هذا العامِ استولى على المطارِ العسكريِّ بالموصل، وهاجمت الطائراتُ الحرسَ الجُمهوريَّ والإذاعةَ ببغداد، ولكِنَّ الهجومَ الجويَّ فَشِل، وتحرَّكت المدرَّعات إلى العاصمة؛ للاستيلاءِ عليها، وأُذيعَ نجاحُ الانقلابِ، ولكِنَّ محطَّةَ إذاعةٍ حكوميةٍ أذاعت فَشَلَ الانقلابِ واستسلامَ المتمَرِّدين، وقام رئيسُ الحرس الجمهوري العقيدُ بشير طالب بهجومٍ مُعاكسٍ ضِدَّ المتمَرِّدين، وأمر الرئيسُ الشُّرطةَ المواليةَ له في الموصل بالقَبضِ على عارف عبد الرزاق فاعتُقِل، وسيطرت الحكومةُ على المطار، وانتهى أمرُ الانقلابِ الذي لم يدُمْ أكثَرَ من يومين، وسُجِن عارف عبد الرزاق."},{"id":5329,"title":"قتل سيد قطب .","date":["العام الهجري :1386","الشهر القمري : جمادى الأولى","العام الميلادي :1966"],"text":"هو سيد قطب بن إبراهيم؛ ولد في قرية موشا في أسيوط سنة 1324هـ / 1906م. نشأ سيد في مجتمعٍ قُروي صعيدي. حفظ القرآنَ الكريمَ كاملًا من نفسِه وهو في سن العاشرة؛ ذهب إلى القاهرة في سن الرابعة عشرة وعاش عند خاله، والْتَحَق أوَّلًا بإحدى مدارس المعلِّمين الأوَّليَّة وعمل مدرسًا ابتدائيًّا. بدت في القاهرة في هذه المدَّة سوءاتُ الاحتلالِ الأجنبي ومفاسدُه؛ حيث سادت عوامِلُ التمزُّق الطَّبَقي والصِّراع الحزبي، واختار سيد حزبَ الوفد؛ ليستأنسَ بقيادته في المواجهة، وكان يضمُّ وقتذاك عباس محمود العقاد وزملاءه من كُتَّاب الوفد، وارتفعت الصلةُ بينه وبين العقَّاد إلى درجة عالية من الإعجاب؛ لما في أسلوبِ العقَّاد من قوة التفكير ودقة التعبير. تخرَّج من كلية دار العلوم بالقاهرة سنة 1352 هـ / 1933 م وعمل في جريدة الأهرام. وكتب في مجلَّتَيِ الرسالة والثقافة، وعُيِّن مدرسًا للعربية، فمُوظَّفًا في ديوان وزارة المعارف، ثمَّ مراقبًا فنيًّا للوزارة. وأُوفِدَ في بعثةٍ لدراسة برامج التعليم في أمريكا. عاد سيد قطب من أمريكا في 23 أغسطس 1950 ليعمَلَ بمكتب وزير المعارف، فأخذ ينتقِدُ البرامجَ المصرية، وكان يراها من وضْعِ الإنجليز، وطالب ببرامِجَ إسلامية، إلَّا أنه تمَّ نقلُه أكثَرَ من مرة حتى اضطرَّ أن يقَدِّمَ استقالته في 18 أكتوبر 1952، ومنذ عودتِه من أمريكا تأكَّدت صلته بالإخوان المسلمين إلى أن دُعِيَ في أوائل عام 1953 ليشارك في تشكيلِ الهيئة التأسيسيَّة للجماعة؛ تمهيدًا لتولِّيه قِسمَ الدعوة، حاول جمال عبد الناصر أن يحتويَ سيد قطب قبل انضمامِه للإخوان، وعندما انشَقَّ سيد عن الإخوان انضَمَّ لهيئةِ التحرير التي أسَّسها الضبَّاطُ الأحرار بعد عام من ثورة يوليو، فأقامت الهيئةُ لسيد قطب احتفالًا كبيرًا، ثمَّ تمَّ اعتقاله بعد حادث المنشية عام 1954م؛ وحُكِمَ عليه بالسجن 15 سنة، كتب فيه عددًا من كتبه ثم أُفرِجَ عنه بعفوٍ صحيٍّ في مايو 1964، ثم قُبِضَ عليه مرةً أخرى، وقُدِّم مع كثير من الإخوان للمحاكمة، وحُكِمَ عليه وعلى 7 آخرين بالقتل، ونُفِّذ فيه الحُكمُ في فجر الاثنين 13 جمادى الأولى 1386هـ."},{"id":5330,"title":"تنحية الرئيس الأندونيسي أحمد سوكارنو وتولية سوهارتو  .","date":["العام الهجري :1386","الشهر القمري : ذي القعدة","العام الميلادي :1967"],"text":"بعد أن فَشِلَت الثَّورةُ الشُّيوعيَّةُ الثانية، وكان الرئيسُ الأندونيسي أحمد سوكارنو يؤيِّدُها ويريدُ أن يعيدَ وَضعَ الشيوعيَّةِ على ما كانت عليه، ومع أنَّ الشَّعبَ كان قد انتخبه رئيسًا مدى الحياة، إلَّا أنَّه قد ثار عليه النَّاسَ؛ فقامت المظاهراتُ ضِدَّه وضِدَّ الشيوعيَّة، وأعلنت الأحزابُ السياسيَّة في \"جاوه الغربية\" مطالبتَها المجلسَ الاستشاريَّ بالنَّظرِ في أمر تنحيتِه، وأعلنت رابطةُ القضاة والمحامين وجوبَ تقديمه للمحاكَمة بصفتِه المسؤولَ الأوَّلَ عن الثَّورة الشُّيوعيَّة الثانية، فاتخذَ المجلسُ الاستشاريُّ الأعلى قرارًا بإلغاء رئاسة أحمد سوكارنو مدى الحياة، وحدَّدها بإجراءِ الانتخابات بعد عامين، ثم وقَّع أحمد سوكارنو على وثيقةٍ يتنازل فيها عن السلطة ويُعطي الصلاحياتِ جميعَها إلى سوهارتو الذي لا يختلف عنه كثيرا وتمَّ تعيينُه رسميًّا رئيسًا للجمهورية."},{"id":5331,"title":"دعم اليمن الجنوبي لثوار ظفار التحررية .","date":["العام الهجري :1387","العام الميلادي :1967"],"text":"يعدُّ الانتماءُ المشترك للجبهة القومية في اليمن الجنوبي والجبهة الشعبية لتحرير ظفار إلى الجناحِ اليساري في حركة القوميين العرب عامِلًا مهمًّا في دَعمِ ثوار ظفار التحررية، حيث أعلن اليمنُ الجنوبي استعدادَه لتقديم كلِّ الدعم للمُعارضة العمانية باعتبار أنَّ ذلك جزء من أهدافه الوطنية. وعسكريًّا وفَّر اليمنُ الجنوبي قواعِدَ للجبهة في كلٍّ من حوف والغيظة والمكلا وعدن، إضافةً إلى وسائل التدريب العسكري، بالإضافةِ إلى تحمُّل حكومة اليمن الجنوبي جزءًا كبيرًا من ميزانية الجبهة، كما كانت أغلبُ الوسائل الإعلامية للجبهة في اليمن؛ فمحطة الإذاعة في المكلا، وصحيفة صوت الشعب في عَدَن، إضافةً إلى ما تقدِّمُه وسائل الإعلام اليمنية من دعمٍ وإعلام."},{"id":5332,"title":"الحرب العربية الإسرائيلية الثالثة نكسة 5 حزيران (حرب الأيام الستة) .","date":["العام الهجري :1387","الشهر القمري : صفر","العام الميلادي :1967"],"text":"قامت إسرائيل بشنِّ غارةٍ على سوريا انتقامًا من الفدائيِّين الذين دخلوا فلسطينَ من الجبهة السورية، وأسقطت بعضَ الطائرات السورية فوق ضواحي دمشق، فأمر جمال عبد الناصر القواتِ المصريَّة أن تزحَفَ إلى سيناء، وطلب إنهاءَ عمل قوات الطوارئ الدوليَّة فيها، وأعلنت مصرُ إغلاقَ خليج العقبة أمامَ السُّفُن الإسرائيلية والسُّفُن التي تحمِلُ البضائع لها، ونصحت روسيا مصر ألَّا تبدأ هي بالهجومِ حتى يكونَ الإسرائيليون هم البادئين، وصدَّق جمال النصيحةَ فباغتةَ اليهود في صباح 27 صفر 1387هـ / 5 حزيران 1967م واستهدفوا المطاراتِ بغاراتٍ خاطفة وما هي إلا ساعة، وغدا الطيرانُ المصري مشلولًا عاجزًا! وجاءت الأوامرُ بالانسحابِ من سيناء، وكان الطيرانُ الإسرائيلي يتصيَّد المنسحبين، وطلبت مصرُ وقف إطلاق النار، وتوقَّفت الحربُ على الجبهة المصرية بعد أن خَسِرَت مصر غزة وسيناء، ودُمِّر ثمانون بالمائة من أسطولها الجوي الذي استغرق بناؤه نحو 15 سنة، ثم التفَّتْ إسرائيلُ على الجبهة الأردنية التي كانت هادئة، فاحتلَّت الضفةَ الغربية، ثم طَلَبت الأردن وقفَ إطلاق النار، فكان ذلك، فاتجَهت إسرائيلُ إلى الجبهة السورية فسقطت الجولان بأيدي اليهود، وتصيَّد اليهودُ الذين انسحبوا بشكلٍ عشوائي، واحتلَّت إسرائيلُ القنيطرة، وتوقَّف القتال، وانتصرت إسرائيلُ على الجبهات الثلاث واحدةً تِلوَ الأخرى!! وتُعرَفُ هذه الحرب في كلٍّ من سوريا والأردن باسمِ نكسة حزيران، وفي مِصرَ باسم نكسة 67، وتسمَّى في إسرائيل \"حرب الأيَّام السِّتة\"."},{"id":5333,"title":"عبد الرشيد علي رئيسًا للصومال بعد آدم عبد الله .","date":["العام الهجري :1387","الشهر القمري : ربيع الأول","العام الميلادي :1967"],"text":"انتَخَب المجلسُ الوطني في الصومال رئيس الوزراء عبد الرشيد علي شيرمارك رئيسًا لجمهورية الصومال مكانَ آدَم عبد الله."},{"id":5334,"title":"وفاة رجل الأعمال السعودي محمد بن عوض بن لادن .","date":["العام الهجري :1387","الشهر القمري : جمادى الأولى","العام الميلادي :1967"],"text":"وُلِدَ المعَلِّمُ محمَّدُ بنُ لادِن عام 1326ه الموافِق 1908م في وادي دوعن بحَضرَمَوتَ، ثمَّ هاجَرَ إلى السُّعوديَّةِ للعَمَلِ، وكان أمِّيًا لا يُجيدُ ‏القِراءةَ والكِتابةَ، لكِنَّه ذو فِطنةٍ وذَكاءٍ، وعَزيمةٍ ومُثابَرةٍ، وقُدرةٍ على تحَمُّلِ المَسؤوليَّةِ؛ فانخَرَط في أعمالِ المُقاوَلاتِ والبِناءِ، واكتَسَب خِبراتٍ كَبيرةً، ثمَّ أنشَأَ شَرِكةً صَغيرةً في مجالِ المقاوَلاتِ، وقام ببناءِ مُنشَآتٍ حُكوميَّةٍ، حتى أصبَحَت شَرِكتُه مِن كُبرى شَرِكاتِ المَملكةِ، والتي عُرِفَت بعد ذلك بمجموعةِ (بن لادِن)، ومِن أشهَرِ مَشاريعِه التي نَفَّذَها: تَوسِعةُ الحَرَمينِ الشَّريفَينِ، وعِمارةُ مَسجِدِ قُبَّةِ الصَّخرةِ بالمسجِدِ الأقصى، وطَريقُ الهَدَا الموصِلُ بين مكَّةَ والطَّائِفِ، وعَدَدٌ مِن الأعمالِ الكَبيرةِ في شَرِكةِ أرامكو بالمَنطِقةِ الشَّرقيَّةِ وغَيرِها، توفِّيَ -رَحِمَه اللهُ- وعُمِّرَ 59 عامًا، عندما اصطَدَمت طائِرتُه المِروحيَّةُ وهو يتفَقَّدُ مَشروعَ الهَدَا."},{"id":5335,"title":"اللاءات الثلاث المعبرة عن الموقف العربي المشترك من إسرائيل .","date":["العام الهجري :1387","الشهر القمري : جمادى الأولى","العام الميلادي :1967"],"text":"تمَّ خِلالُ مؤتمر الخرطوم وضعُ وإقرارُ مبادئ تنسيق الدول العربية, وخاصةً فيما يخصُّ التسوية في الشرق الأوسط. وُضِعَت في الخرطومِ صيغةُ اللاءات الثلاث المعروفة، والمعبِّرة عن الموقف العربي المشتركِ حيال إسرائيل \"لا صُلحَ, لا مفاوضاتِ, لا اعتِرافَ\", والتي تمسَّكت بها طوالَ السنوات اللاحقة جميعُ الدول العربية إلى أن خَرَقَت مصرُ في عهدِ السادات هذا الإجماعَ بعقدِ صُلحٍ منفردٍ ومباشِرٍ مع إسرائيل"},{"id":5336,"title":"وفاة المشير عبد الحكيم عامر .","date":["العام الهجري :1387","الشهر القمري : جمادى الآخرة","العام الميلادي :1967"],"text":"هو المشيرُ محمد عبد الحكيم بن علي عامر، وُلِدَ في 11 ديسمبر 1919م في قرية أسطال مركز سمالوط بمحافظة المنيا في أسرةٍ ثرية، وكان والِدُه عمدةَ القرية، ويُعدُّ المشير أحد رجال ثورة يوليو عام 1952م في مصر. وكان صديقًا مقربًا للرئيس جمال عبد الناصر، ورئيسِ المخابرات صلاح نصر، ووزيرِ الحربية شمس بدران حتى حرب 1967. وقائدًا عامًّا للقوات المسلحة المصرية، ونائِبَ رئيس الجمهورية. تخرَّج عامر من الكلية الحربية عام 1939، وشارك في حرب 1948 في نفس وَحدة جمال عبد الناصر. لعِبَ عامر دورًا كبيرًا في القيام بالثورة عام 1952, وفي العام التالي للثورة، وفي عام 1954 تولى وزارة الحربية، ثمَّ تمَّ ترقيتُه من رتبة صاغ (رائد) إلى رتبة لواء متخطيًا ثلاث رتب، وأصبح رئيسًا للأركان. وقاد القواتِ المصريَّةَ والمقاوَمةَ في حرب العدوان الثلاثي عام 1956، وبعد الوحدة مع سوريا عام 1958 أصبح القائِدَ الأعلى للقوات المشتركة. وفي عام 1964 أصبح نائبًا أوَّلَ لرئيس الجمهورية. فَسَدَت العلاقةُ بين الرئيس عبد الناصر والمشير عامر على نحوٍ سريع عقب حرب 1967 بعد إصدار الرئيس عبد الناصر قرارًا بتنحيةِ عبد الحكيم عامر عن قيادة الجيش، وتعيينه نائبًا لرئيس الجمهورية، وهو القرارُ الذي رفضه عامر بشدَّة، فوُضِعَ قَيدَ الإقامةِ الجبرية في منزله، حتى مات فيه، قيل مسمومًا وقيل منتحرًا."},{"id":5337,"title":"إعلان جمهورية اليمن الجنوبية الشعبية استقلالها عن بريطانيا .","date":["العام الهجري :1387","الشهر القمري : شعبان","العام الميلادي :1967"],"text":"كان اليمنُ الجنوبي يمثِّل مجموعةً من المحميات الخاضعة للاحتلال البريطاني، وتنقَسِمُ إلى محميَّات غربية عاصمتها عدن، ومحميَّات شرقية عاصمتها المكلا، وفي حوالي سنة 1960م بدأ يظهرُ حزبُ البعث العربي الاشتراكي باليَمَن الجنوبي متأثرًا بالمدِّ الاشتراكي القومي العربي: مذهبِ جمال عبد الناصر! وتوسَّع في صفوفِ العُمَّال العَدَنيين، وكان يطالِبُ بالاستقلال التام، وبدأ يَقوَى حتى اجتاح البلادَ بالمظاهراتِ والاصطداماتِ مع القوى البريطانية، ثمَّ بعد سنة ونصف انفجرت الثورةُ في اليمن الشمالي وتَبِعَها اليمنُ الجنوبي؛ فقامت المظاهراتُ الدامية في عَدَن، وبدأت حربُ العصابات في الجبال، وعَقَدت بريطانيا مؤتمرًا في لندن سنة 1964م لحكَّام الجنوب، فرفضت المعارضةُ الحضور، فقرَّر المؤتمرُ تحديدَ موعد الاستقلال في سنة 1968م، وتطوير نطام الحُكم، والسماح للأحرار بالعودة للبلاد، ولكِنْ بسبب تزايُد حدة الاضطرابات قُدِّم الموعِدُ إلى 20 نوفمبر 1967م، وأُعلِنَت فيه جمهوريةُ اليمن الجنوبية الشعبية، وكانت هناك جبهتان، هما: جبهةُ تحرير الجنوب العربيِّ التي قامت على أساسِ حِزبِ البعث الاشتراكي، وجبهةٌ قوميَّةٌ ذاتُ ميول وطنية تطالِبُ باستقلال اليمن وتوحيدِه، وتنافست الجبهتانِ على قيادة الحركة الوطنية والثورة، وانتصرت الجبهةُ القومية، واستطاعت بعد معارِكَ دامية أن تَكونَ القوةَ الشعبيَّةَ الأولى والوحيدةَ في البلاد، وفاوض الإنجليزُ رئيسَها قحطان الشعبي الذي أصبح فيما بعدُ رئيسًا للجمهورية، وانسحبت بريطانيا عن اليمن بعد تدخُّل كلٍّ من الولايات المتحدة والاتحاد السوفيتي، وتمَّ الجلاء عن القواعد العسكرية من بحريةٍ وجوية، وتسليم كافة الجُزُر للجنوبيين. وبعد انسحاب بريطانيا من جنوب اليمن حدثت تحوُّلاتٌ اجتماعية متأثِّرةً بالمد الماركسي، فاضطرَّ كثيرٌ من أُسَرِ اليمن الجنوبي إلى الهرب إلى السعودية حتى قبل إعلان الاستقلال."},{"id":5338,"title":"قرار مجلس الأمن 242 (الأرض مقابل السلام)  .","date":["العام الهجري :1387","الشهر القمري : شعبان","العام الميلادي :1967"],"text":"أصدر مجلسُ الأمن الدولي في 22 نوفمبر قرارًا برقم 242 وذلك في أعقاب نكسة حزيران 67 التي أسفرت عن هزيمة الجيوشِ العربيَّة، واحتلال إسرائيل لمناطِقَ عربية جديدة، وقد جاء هذا القرار كحَلٍّ وسطٍ بين عدة مشاريع طُرِحَت للنقاش بعد الحرب. تضمَّن القرار في مادته الأولى في (الفقرة أ) انسحابَ القوات الإسرائيلية من الأراضي التي احتُلَّت في النزاع الأخير، وإنهاء حالة الحرب والاعتراف ضمنًا بإسرائيلَ دون ربط ذلك بحلِّ قضية فلسطين التي اعتبرها القرارُ مشكلة لاجئين. ويشكِّلُ هذا القرار منذ صدوره أساسَ كل مشاريع السَّلام والمساعي الدولية العربية؛ لإيجادِ حَلٍّ للصراع العربي الإسرائيلي! فقد اعتمدت عليه المعاهدةُ المصرية الإسرائيلية (اتفاقية كامب ديفيد) وما بعدها."},{"id":5339,"title":"معركة الكرامة  .","date":["العام الهجري :1387","الشهر القمري : ذي الحجة","العام الميلادي :1968"],"text":"كان الفلسطينيون يشكِّلون نسبةً عاليةً من تَعداد سكان الأردن في تلك الفترة، يتمركزون في بلدة الكرامة على الجانب الأردني، وكانوا قد استهدفوا إسرائيلَ مرارًا عبر هَجَمات خلال الحدودِ مِن قِبَل الفدائيين الفلسطينيين. وكرَدِّ فعلٍ على مجموعةٍ من الهجمات التي صدرت من جانب حدود الأردن قام جيشُ الدفاع الإسرائيلي باجتياح بلدة الكرامة في 21 مارس، وقد أعلن رئيسُ الوزراء الإسرائيلي ليفي إشكول في حينها أنَّ الهدفَ من العملية هو منعُ موجة جديدة من الإرهاب؛ فقُتِلَ في ذلك الاجتياح 128 فلسطينيًّا، وقيل 170. وكاد الإسرائيليون أن ينتصروا ويُكمِلوا اجتياحهم لولا تدخُّل الجيش الأردني بقيادة \"مشهور حديثة\" فقامت معركة كبيرةٌ بين الجيشين عُرِفَت باسم معركة الكرامة. قُتِلَ في المعركة 250 جندي إسرائيلي وجُرح 450، كما فقد جيشُ الدفاع الإسرائيلي مئات الآليات. وقُتِل من جانب الجيش الأردني 60 جنديًّا. وصُنِّف هذا النصرُ على أنَّه أول انتصار لجيش عربي على إسرائيل."},{"id":5340,"title":"مؤتمر الأديان في جاكرتا أندونيسيا .","date":["العام الهجري :1387","الشهر القمري : ذي الحجة","العام الميلادي :1968"],"text":"دعت الحُكومةُ الأندونيسيَّةُ إلى عقدِ مؤتمر للأديان في جاكرتا عام 1387هـ / 1967م فلبَّى الدعوةَ مَن وُجِّهت إليهم، وعُقِدَ المؤتمر في دار المجلس الاستشاري الأعلى ووجَّه فيه الرئيسُ سوهارتو نداءً إلى أتباع الأديان؛ كي يركِّزَ كُلٌّ منهم اهتمامَه التامَّ على مهمة تصعيد مستوى الوعيِ الدينيِّ في أبناء طائفته، وأن يحرصوا على الحيلولة دونَ أن تُحِسَّ طائفة من الطوائف أنَّها مُعَرَّضة لدعايات طائفة أخرى ومُستهدَفة لنشاطها، وقدَّم الجانبُ الإسلامي في المؤتمر أسلوبًا للتراضي، وقد صِيغَ في مشروع ميثاق بين الأديان ملبيًّا نداءَ الرئيس سوهارتو، ولكِنَّ الجانب النصراني -سواء كان الكاثوليكي أو البروتستانتي- قد قابل ذلك المشروعَ بالرَّفض التام، على الرغم من أنَّ النصارى أقلِّيَّة وقد سُوُّوا بالأكثرية المُطلَقة!"},{"id":5341,"title":"صدور الميثاق الوطني الفلسطيني .","date":["العام الهجري :1388","الشهر القمري : ربيع الآخر","العام الميلادي :1968"],"text":"في عام 1964م أصدر المجلسُ الوطني الفلسطيني -(وكان اسمه المؤتمر العربي الفلسطيني) في دورته الأولى التي عُقِدَت في القدس- الميثاقَ القوميَّ الفلسطينيَّ المبنيَّ على قرارات المؤتمرات السابقة, وأعلن قيامَ منظمة التحرير الفلسطينية. وفي الدورة الرابعة للمجلس الوطني الفلسطيني المنعقد في القاهرة في 10/7/1968م أقرَّت تسميتَه الميثاق الوطني الفلسطيني, وصار الميثاقُ هو البرنامجَ الاستراتيجيَّ لتحرير فلسطين. وتضمَّن ثلاثًا وثلاثين مادة، لا يُعَدَّل هذا الميثاقُ إلا بأكثرية ثُلُثَي مجموع أعضاء المجلس الوطني في منظمة التحرير الفلسطينية، وفي جلسةٍ خاصة يُدعى إليها من أجْلِ هذا الغرض."},{"id":5342,"title":"انقلاب بعثي يطيح بالرئيس العراقي عبد الرحمن عارف .","date":["العام الهجري :1388","الشهر القمري : ربيع الآخر","العام الميلادي :1968"],"text":"لما انتُخِبَ عبد الرحمن عارف رئيسًا للجمهورية كان لمدةٍ سنة واحدة فقط مع إمكان تجديدِها، وكان من المفترض تعديلُ الدستور، ولكِنَّ العدوانَ اليهوديَّ على مصر والأردن وسوريا ومساهمة العراق بالمساعدة أخَّر ذلك، ومع ذلك وقبل انتهاء فترة حُكمِ الرئيس حدث انقلابٌ أطاح بعبد الرحمن عارف؛ فقد قام تنظيمٌ سري باسم (الثوريون العرب) حرَّكه مديرُ الاستخبارات العسكرية وتمكَّن من التواصُلِ مع رئيس الحرس الجمهوري، وتعاونوا مع الجناحِ المعتدل من حِزبِ البعثِ الذي يمثِّلُه أحمد حسن البكر وجماعته، ولما شعروا بالاستعداد قاموا بتحريكِ الدَّبَّابات باتجاه القصر الجمهوري ولم يُبدِ رئيسُ الحرس الجمهوري أيَّ مساعدة للحكم، وبعد عِدَّة طلقات استسلم الفريقُ عبد الرحمن عارف وألقيَ القبضُ عليه وأُذيع نبأُ الانقلاب، وأُعلِنَ عن تشكيل مجلس لقيادة الثورة، واختير أحمد حسن البكر رئيسًا للجمهورية، وأُعلِنَ أن الهدف من الحركة هو الوحدة الوطنية، وأحيل عبدُ الرحمن عارف إلى التقاعُدِ ونُفيَ خارجَ البلد إلى لندن. وبعد ثلاثة عشر يومًا فقط من الانقلاب انفرد البعثيُّون بالسُّلطة، وأُبعِدَ رئيس الحكومة فغادر إلى لندن، كما أُبعدَ أعوانُه."},{"id":5343,"title":"قيام النظام الجمهوري في المالديف كبديل لنظام السلطنة .","date":["العام الهجري :1388","الشهر القمري : شعبان","العام الميلادي :1968"],"text":"بعد أن استقلَّت جُزُرُ المالديف سنة 1385هـ وبعد ثلاث سنوات جرى استفتاءٌ شعبي، فوافق الشعبُ على إقامة النظام الجمهوري في الحُكمِ كبديلٍ لنظام السَّلْطنة الذي كان قائمًا، وأُعلِنَ النظام الجمهوري في 20 شعبان 1388هـ / 11 تشرين الثاني، وتسلَّم إبراهيم ناصر رئاسةَ الجمهورية، وكان قبل ذلك يَشغَلُ مَنصِبَ رئاسة الوزراء، وكانت البلاد تُعرَف باسم جُزُر المالديف، ثم أُطلِقَ عليها عام 1389هـ / 1969م اسمَ جمهورية المالديف."},{"id":5344,"title":"انقلاب عسكري يطيح برئيس مالي موديبو كيتا .","date":["العام الهجري :1388","الشهر القمري : شعبان","العام الميلادي :1968"],"text":"قاد الملازمُ أول موسى تراوري انقلابًا عسكريًّا في مالي ضِدَّ نظام الرئيس موديبو كيتا الذي كان يومَها يتنزَّهُ بقاربه الشِّراعي في نهر النيجر، وعند عودتِه إلى الشاطئ ألقِيَ القَبضُ عليه من قِبَل الانقلابيين، وتولَّى الحكمَ لجنةٌ عسكريةٌ تضُمُّ أربعة عشر ضابطًا، ثم نَصَب موسى تراوري نفسه رئيسًا للجمهورية."},{"id":5345,"title":"وفاة الشيخ محمد فؤاد عبد الباقي .","date":["العام الهجري :1388","الشهر القمري : ذي القعدة","العام الميلادي :1969"],"text":"هو الشيخُ محمد فؤاد بن عبد الباقي، باحثٌ ومؤلِّفٌ متخَصِّصٌ في الحديث النبوي، وعالمٌ بتنسيق الأحاديث النبوية ووَضْع الفهارس لها ولآيات القرآن الكريم، وهو مترجِمٌ باللغتين الفرنسية والإنجليزية لكتُبِ المستشرقين في معاجمِ الحديث والقرآن. ولِدَ في إحدى قرى القليوبية في جمادى الأولى 1299هـ / مارس 1882م، ونشأ في القاهرة، وفي سنة 1317 هـ / 1899م عَمِل بمركز تلا التابع لمحافظة المنوفية مدرسًا للُّغة العربية في مدرسة جمعية المساعي المشكورة، وبعد فترة عَمِلَ ناظرًا لإحدى المدارس في قرى الوجه البحري، وظلَّ في هذه الوظيفة سنتين ونصفًا. ولما أعلن البنكُ الزراعي عن وظيفة مترجِم تقدَّم لها وعُيِّن بالبنك في 3 ذي القعدة 1323هـ / 30 ديسمبر 1905م، وقد هيأ له استقرارُه في هذه الوظيفة أن ينصَرِفَ إلى القراءة ومُطالعة أمَّهات كتب الأدب في العربية والفرنسية، وأن يرتبطَ بصداقات مع أعلام عَصرِه. وكان ممن ارتبط بهم بصداقةٍ وتَلمَذة الشيخُ محمد رشيد رضا, فلازمه إلى وفاتِه، ونهل من علمه، وفتح له آفاقًا واسعةً في علوم السنة، فانطلق يخدمُ السنةَ النبوية، سواءٌ فيما يتَّصِلُ بتحقيق أمهاتها، أو التأليف فيها، أو تخريج أحاديثها، ومن أعظَمِ جهودِ عبد الباقي التي خَدَم بها سنة المصطفى صلَّى الله عليه وسلَّم ترجمتُه لكتاب ((مفتاح كنوز السنة)) لفنسك أستاذ اللُّغات الشرقية بجامعة لندن، ومن مؤلفاته أيضًا في خدمة السنة: ((اللؤلؤ والمرجان فيما اتَّفَق عليه الشيخان)). توفي رحمه الله بالقاهرة عن عمر ناهز التسعين."},{"id":5346,"title":"حرب الاستنزاف .","date":["العام الهجري :1388","الشهر القمري : ذي الحجة","العام الميلادي :1969"],"text":"حربُ الاستنزاف تعبيرٌ أطلقه الرئيس جمال عبد الناصر على العمليَّات العسكرية التي كانت تدور بين القوَّات المصرية شَرقَ قناة السويس والقوات الإسرائيلية المحتلَّة لمنطقة سيناء عَقِبَ حربِ الأيام الستة (نكسة حزيران 67) والتي احتلَّت فيها إسرائيلُ الأرضَ العربيةَ في كلٍّ مِن الضَّفَّة الغربية، وقطاع غزة، وهضبة الجولان، وسيناء. وانتهت حربُ الاستنزاف بموافقة عبد الناصر على مبادرة وزير الخارجية الأمريكي روجرز لوقفِ إطلاق النار في 8 أغسطس 1970م. تضمَّنت حربُ الاستنزاف هجماتٍ مُتعدِّدةً ضِدَّ الاحتلال في سيناء وحتى في مناطِقَ خارجَ منطقة الصراع تمامًا، مثل عملية تفجير حفَّار إسرائيلي في المحيط الأطلنطي، ومن أهمِّ عمليات حرب الاستنزاف: عمليةُ ايلات التي تمَّ خلالها الهجومُ على ميناء أم الرشراش الذي أسمَتْه إسرائيل إيلات بعد احتلالِه؛ حيث تمَّ تلغيمُ الميناء، وقَتْلُ عددٍ مِن العسكريين، وإغراقُ بارجة إسرائيلية من قِبَل المصريين بالتعاون مع القوات الأردنية والعراقية ومنظمة التحرير الفلسطينية."},{"id":5347,"title":"وفاة الملك سعود بن عبد العزيز .","date":["العام الهجري :1388","الشهر القمري : ذي الحجة","العام الميلادي :1969"],"text":"هو سعودُ بن عبد العزيز بن عبد الرحمن الفيصل آل سعود: مَلِكُ المملكة العربية السعوديَّة، وهو أوَّلُ ملك للبلادِ بعد أبيه المؤسِّسِ الملك عبد العزيز رحمهما الله. وُلِدَ سعود في الكويت سنة 1319هـ العام الذي استعاد فيه الملك عبد العزيز الرياض، ونشأ سعود في الرياض. وقرأ على بعض مشايخها. وقام برحلاتٍ إلى الخارج. وقاد المعاركَ في حروب أبيه. وتولى العرشَ السعودي عام (1373هـ / 1953) فور وفاة أبيه، وبعهدٍ منه، وزار مصر واليمن، وفي سنة (1384 / 1964) اجتمع أعيانُ آل سعود وعُلماء الرياض فأصدروا بيانًا بتنحية الملك سعود ومبايعة الأمير فيصل. فرحل سعودٌ بأهله وبعض أبنائه ونزل بالعاصمة اليونانية أثينا للعلاجِ والإقامة في فندق قريبٍ منها. وقد كانت وفاتُه -رحمه الله- بأثينا، ونقلته طائرةٌ سعودية من أثينا إلى جدة؛ حيث صلَّى عليه أخوه الملك فيصل بمكَّةَ وحملته الطائرة إلى مدافِنِ الأسرة في الرياض."},{"id":5348,"title":"اعتزال الرئيس الباكستاني أيوب خان السلطة وتولية محمد يحيى خان .","date":["العام الهجري :1389","الشهر القمري : محرم","العام الميلادي :1969"],"text":"تأزَّم الأمرُ في باكستان كثيرًا -وخاصةً بعد الحربِ مع الهند- وزادت المعارَضةُ، وبدأت المطالَبةُ بتقسيم باكستان إلى إقليمين، وفُصِلَ الإقليمُ الشرقي، وزادت الاضطراباتُ، وكانت مكانةُ أيوب خان (سُنِّي) في باكستان بدأت تَضعُفُ؛ بسَبَبِ ازدياد المعارِضين لسياسته، وزاد من قوَّتِها انتقادُ وزير الخارجية ذي الفقار علي بوتو (شيعي) للمعاهدة، وفي هذه الأوضاع تأسَّس حزبُ الشعب الاشتراكي بهدف إقصاءِ أيوب خان عن السلطة، وتكَوَّنت أحزابٌ سياسيَّةٌ أخرى اجتمعت كلُّها على إسقاط حكومة أيوب خان، وأخذت شعبيَّةُ أيوب خان في الانهيارِ عندما أحسَّت قطاعاتٌ عريضةٌ من الشعب الباكستاني بفشلِه في الحُصولِ على تأييد عددٍ مِن الدول الإسلامية ذاتِ الثِّقلِ الدولي، وتدهور الموقِفُ السياسي الداخلي بسبب اشتدادِ المعارضة واندلاع المظاهراتِ الطُّلَّابية الحاشدة، فلم يجِدِ الرئيسُ أيوب خان بدًّا من اعتزالِ الحكم، فتركه وسلَّمه إلى رئيسِ هيئة أركان الحرب في الجيش الباكستاني الجنرال يحيى خان الذي تسلَّم السلطة، فشَكَّل حكومةً عَسكريةً، وفرَضَ الأحكامَ العُرفية، وحَلَّ الهيئاتِ النيابيَّة، ومَنَع الإضراباتِ والمظاهراتِ."},{"id":5349,"title":"انقلاب عسكري بقيادة جعفر النميري في السودان .","date":["العام الهجري :1389","الشهر القمري : ربيع الأول","العام الميلادي :1969"],"text":"كان جعفر محمد النميري قد أُرسِلَ إلى أمريكا للحصول على رتبةِ أركان حرب، ورجع بعد أقل من سنتين ورُفِع إلى رتبة عقيد، وكان قد عُيِّن كقائدٍ ثان في مدرسة المشاة في جبيت، وفي 9 ربيع الأول 1389هـ / 25 أيار قام بانقلابٍ عسكريٍّ واستولى على الحُكم، وأزاح وزارةَ محمد أحمد محجوب، وشكَّل مجلِسًا للثَّورة والحكومة، وأعاد عددًا من الضبَّاط الذين كانوا قد أُقيلوا سابقًا، وكان الانقلابُ العسكريُّ قد استهدف الجبهةَ الإسلاميَّةَ قبل غيرها؛ إذ اعتَقَل أعضاءَها قبل أن يعتَقِلَ أعضاءَ الحكومة، وحَمَل الانقلابُ عنوانًا اشتراكيًّا، وضَمَّ عناصرَ مختَلِفةً مِن شيوعيَّة واشتراكيَّة مع عملهم بالوقتِ نفسِه بخَطِّ الرأسمالية، وبدأت الحركةُ بتطبيق الاشتراكية في بعض القطاعاتِ، وانقسمت البلادُ إلى قسمين: الحكومةُ وأنصارُها من جهةٍ، وجبهةُ المقاومةِ الشَّعبيةِ مِن جهةٍ أخرى."},{"id":5350,"title":"استعادة المغرب لمنطقة سيدي إفني المحتلة من قبل إسبانيا .","date":["العام الهجري :1389","الشهر القمري : ربيع الآخر","العام الميلادي :1969"],"text":"كانت منطقة \"سيدي إفني\" التي تقع جنوبَ مدينة أغادير بالمغرب على المحيطِ الأطلسي بحُكمِ مَوقِعِها الاستراتيجي: محطَّ أطماعٍ استعماريَّةٍ، وهدفًا سَعَت قواتُ الاحتلال الإسباني إلى تحقيقِه باعتبارها بوابةً بحريةً مؤهِّلةً للإنزال العسكري والعمليَّات الحربية؛ ولطبيعةِ سيدي إفني وأرضيتها الصالحة لهُبوط الطائرات وتضاريسها التي تجعل منها حِصنًا يُطِلُّ على امتداداتٍ شاسعةٍ مِن عُمقِ تراب آيت باعمران (وهو نطاق اتحاد قبائِلَ مغربيَّة) والأقاليم الجنوبية عمومًا. وهكذا حطَّت جيوشُ الاحتلال بكل ثِقلِها في المنطقة منذ سنة 1934م، وعزَّزت وجودَها بكثافةٍ. وظَلَّ المغربُ مع ذلك متمسكًا بمطالبه في تحرير أراضيه، وظل أبناءُ الصحراء يقاومون الاحتلالَ الإسباني، واستطاع المغربُ من جديدٍ أن يحقِّق خطوةً كبيرة على دربِ استكمال التحرير، وعلى الرَّغمِ من تراجُع جيش التحرير وبقاء \"سيدي إفني\" محاصرةً إلَّا أن إسبانيا سلَّمتها للمغربِ في 30 يونيو 1969."},{"id":5351,"title":"وفاة القارئ الشيخ محمد صديق المنشاوي .","date":["العام الهجري :1389","الشهر القمري : ربيع الآخر","العام الميلادي :1969"],"text":"هو المقرئُ الشيخ محمد صديق المنشاوي، أحدُ رُوَّادِ التلاوة بمصر، تميَّز بأسلوبٍ مُمَيَّز وحزين في تلاواتِه. وُلِدَ بقرية البوري بمحافظة سوهاج بمصر، وأتمَّ حِفظَ القرآن وهو في الثامنة؛ حيث نشأ في أسرةٍ تهتَمُّ بالقرآن حفظًا وتلاوةً؛ فأبوه الشيخ صديق هو الذي علَّمه فنَّ قراءة القرآن الكريم، ذاع صِيتُ محمد ولَقِيَ قَبولًا حسنًا لعُذوبةِ صَوتِه وجماله وانفرادِه بذلك، كان متقِنًا لمقاماتِ القراءة والانفعال العميقِ مع معاني وألفاظ القرآن, ويُعدُّ المنشاوي من أشهَرِ القرَّاء في العالم الإسلامي. أصيب الشَّيخُ في آخر أيامِه بمرض دوالي المريء، ورَغمَ مَرضِه ظلَّ يقرأ القرآن حتى وافته المنية -رحمه الله- يوم الجمعة 5 ربيع الثاني من هذا العام."},{"id":5352,"title":"ثورة الفاتح بقيادة معمر القذافي وإنهاء الحكم الملكي في ليبيا .","date":["العام الهجري :1389","الشهر القمري : جمادى الآخرة","العام الميلادي :1969"],"text":"زادت نِقمةُ النَّاسِ على النِّظامِ الحاكم في ليبيا، وكانت تزدادُ كُلَّما ازداد التودُّدُ للإيطاليين الذين كانوا بالأمسِ محتلِّين وأذاقوا الناسَ الويل، وأيضًا لعدَمِ مقاطعتهم لإسرائيل رغمَ صدور قرار المقاطعة من الجامعة العربية، ثمَّ ازدياد النفوذ الأمريكي في المنطقة، وغيرها من الأمور التي ولَّدت الحِقدَ الشعبيَّ، وظهرت المعارضةُ. وفي 19 جمادى الآخرة 1389هـ / 2 أيلول (سبتمبر) تحرَّك الجيشُ بقيادةِ العقيد معمَّر القذافي، وقضى على الوَضعِ القائم الذي وَجَدَه هشًّا؛ إذ نِقمةُ الشَّعبِ كانت عارمةً على النظام الملكي، وتشكَّل المجلسُ الأعلى لقيادة الثورة، وتشكَّلت حكومةٌ جديدة من عسكريِّين ومَدَنيين، وعلى إثر ذلك انسحبت أمريكا وانجلترا من ليبيا، فأصبح لهذه الثورةِ مكانتُها في أعُينِ النَّاسِ، ثمَّ مِن الناحية الإسلاميَّة أصدرت الثورةُ قانونًا بمنع تعاطي الخُمورِ في ليبيا، وطبَّقت الزكاةَ، وأصدرت مجموعةَ قوانين تدور حولَ هذا الفَلَك الإسلامي! ثم أبدى القذافيُّ قائدُ الثورة بعد وفاة جمال عبد الناصر أنَّه الوريثُ للزعامة العربية! وعَمِلَ على إقامة اتحادِ الجُمهوريات العربية المتَّحَدة بين ليبيا ومصر وسوريا."},{"id":5353,"title":"اليهود يحرقون المسجد الأقصى .","date":["العام الهجري :1389","الشهر القمري : جمادى الآخرة","العام الميلادي :1969"],"text":"إنَّ مِن أهدافِ اليهود إزالةَ المسجد الأقصى ومسجد الصَّخرة؛ لإقامةِ هيكلِ سليمانَ المزعومِ الذي يدَّعون زُورًا وبهتانًا أنَّه كان مُقامًا في نفسِ مكان المسجد، وأنَّ بناءه هو السَّبيلُ لظهور مسيحِهم المنتظَرِ الذي يدَّعون أنَّهم سيقتلون العالَم أجمعَ معه، فكان من تخطيطِهم إحراقُ المسجدِ مِن أجْلِ هَدمِه؛ فقامت السُّلطاتُ اليهودية ُبهدمِ العقاراتِ الملاصقة للمسجد الأقصى، ثم قامت بنَسفِ جميع المباني العربية المجاوِرة، واحتلَّت بقوةٍ بابَ المغاربة وسَمَحت لليهود بإقامةِ صَلَواتهم في المسجد، ثمَّ قامت بعد ذلك بتدريبِ بعض الأفراد وزوَّدتهم بما يلزم لافتعالِ حريق في المسجد الأقصى، فقام في 7 جمادى الآخرة / 21 آب (أغسطس) بعضُ اليهود المجرمين بإضرامِ النار في داخِلِ المسجد الأقصى وسَطْحِه وعِدَّة مناطق منه، وتظاهرت السلطاتُ اليهوديةُ في البداية أنَّها لا علاقةَ لها بالأمر، فتباطأت بشكلٍ ظاهرٍ في عمليات الإطفاء، وهَبَّ الفلسطينيون لإطفاءِ الحريق وجاءت سياراتُ الإطفاء من رام الله والخليل للإطفاء، وقَطَعت شركةُ كهرباء القُدس التيَّارَ حتى لا يتفاقمَ الأمرُ حتى استطاع الأهالي إطفاء الحريق، وأعلن الشيخ حلمي المحتسب رئيسُ الهيئة الإسلامية بالقدس أنَّ الاعتداءَ كان من قِبَلِ السلطات اليهودية، ونُشِرَ تقريرٌ مفصَّل في القدس عن الحريق وافتعاله."},{"id":5354,"title":"عقد أول مؤتمر قمة إسلامي في الرباط .","date":["العام الهجري :1389","الشهر القمري : رجب","العام الميلادي :1969"],"text":"بعد أن أقدم اليهودُ على إحراقِ المسجِدِ الأقصى، واستاء العالمُ الإسلامي جميعًا من هذا الفعلِ المُجرِم، بادر الملِكُ الحسن الثاني مَلِكُ المغرب بتوجيهِ دعوةٍ إلى رؤساء العالم الإسلامي للاجتماعِ في الرِّباطِ عاصمةِ المغرب؛ للاتفاقِ على خِطَّةِ عَمَلٍ إسلامية موحَّدة تهدف إلى الدِّفاعِ عن القدس الشريف، وحمايةِ البِقاع المقَدَّسة ومعالمه الحضارية؛ فعُقِدَ بالفعلِ أوَّلُ مؤتمر قمة إسلامي في الرباط في الفترة من 9 إلى 12 رجب سنة 1389هـ / 22 إلى 15 أيلول، دُعِيَ إليه 35 بلدًا إسلاميًّا, بَيْدَ أن 25 بلدًا فقط أرسلت وفودَها, علمًا بأنَّ عشرة بلدان فحسب مثَّلت برؤساءِ دُوَلِها، وحضرته منظمةُ التحرير الفلسطينية بصفةِ مراقب، وأعلن المؤتمَرُ في ختامه إدانةَ العملِ الإجرامي، والمطالبةَ بانسحاب إسرائيل من جميع الأراضي العربية التي احتلَّتْها إسرائيلُ في حرب 1967م، وتأكيدَ عودةِ القدس إلى وَضعِها السَّابقِ قبل حرب حزيران 1967م، وتأكيدَ تضامُنِ الدول الإسلامية مع الدول العربية في صراعِها مع العدُوِّ الإسرائيلي، ومساندةَ المؤتمر وتأييدَه الكامل للشعب الفلسطيني؛ من أجلِ استعادة حقوقِه المغتَصَبة، وتحرير أرضه من براثنِ الصهيونية. وقرَّر المؤتمِرون ضرورةَ عقد اجتماعٍ لوزراء خارجية الدُّوَل المشاركة بجدة في شهر مارس 1970م؛ وذلك لبحثِ نتائج العَمَل المشترك الذي قامت به الدُّوَل المشاركة على الصعيد الدولي في موضوعِ القرارات الواردةِ في إعلان مؤتمر القِمَّة الإسلامي بالرباط، وإقامة أمانة دائمة يكونُ من جملة واجباتها الاتصالُ مع الحكومات الممثلة في المؤتمر والتنسيق بين أعمالها، وبعد حرب 1973 أخذ يتزايدُ في المؤتمرات الإسلامية الاهتمامُ بقضايا التعاوُن الاقتصادي والإجراءات المشتركة ضِدَّ أعمال إسرائيل التوسُّعية العدوانية, ودعْم حقوقِ الشعب العربي الفلسطيني."},{"id":5355,"title":"اغتيال الرئيس الصومالي عبد الرشيد وتولي محمد سياد بري .","date":["العام الهجري :1389","الشهر القمري : شعبان","العام الميلادي :1969"],"text":"اغتال أحدُ أفراد شرطة الصومال رئيسَ الجُمهورية عبد الرشيد علي شيرمارك في 4 شعبان 1389هـ / 15 تشرين الأول، وبعد ستةِ أيام سيطر الجيشُ بانقلابٍ عسكريٍّ على الحُكمِ عَشيَّةَ اليوم الذي كان مقررًا فيه إجراءُ انتخاب رئاسي، واستولى على السلطةِ قائِدُ الجيش والقوَّات المسلحة محمد سياد بري الذي حلَّ المجلِسَ الوطني، وألغى الأحزابَ السياسيَّةَ، وشكَّل حُكومةً جديدة من قِبَل المجلِسِ الثوري الأعلى الذي يرأسه، وأعلن جمهوريةَ الصومال الديمقراطية، وفي شعبان 1390هـ / تشرين الأول 1970م أعلن محمد سياد بري دولةَ الصومال الاشتراكية."},{"id":5356,"title":"وفاة الشيخ محمد بن إبراهيم آل الشيخ مفتي الديار السعودية .","date":["العام الهجري :1389","الشهر القمري : رمضان","العام الميلادي :1969"],"text":"هو الشَّيخُ العلَّامة محمد بن إبراهيم بن عبد اللطيف بن عبد الرحمن بن حسن بن محمد بن عبد الوهاب التميمي مفتي الديار السعودية. وُلِدَ يوم عاشوراء من عام 1311هـ، ونشأ نشأةً عِلميَّةً في بيتِ عِلمٍ ودين، فحَفِظَ القرآنَ مبكرًا، ثم بدأ الطلَبَ على العلماء قبل أن يبلُغَ السادسة عشرة، ثم أصيب بمرَضٍ في عينيه وهو في هذه السن ولازمه حتى فَقَد بصَرَه وهو في سن السابعة عشرة، وكان يَعرِفُ القراءة والكتابة قبل فَقدِه لبصرِه. كان متوسِّطَ الطول، مليءَ الجِسم، متوسِّط اللون، ليس بالأبيض ولا بالأسمر، خفيفَ شعرِ العارِضَين جدًّا، يوجَدُ شَعرٌ قليل على ذَقَنِه، إذا مشى يمشي بوقارٍ وسكينة، وكان كثيرَ الصَّمت، وإذا تكلَّم لا يتكلَّم إلَّا بما يفيد، وكان ذكيًّا، و كان صاحِبَ غَيرة شديدة على دين الله، مع حزمٍ وشِدَّة يرهب لها الجميع، وكان رغمَ شِدَّتِه وحزمه وهيبةِ الناسِ له صاحِبَ دُعابةٍ خُصوصًا مع خاصَّته، ومن مشايخِه الذين تعَلَّم عليهم عَمُّه الشيخ عبد الله بن عبد اللطيف، والشيخُ سعد بن حمد بن عتيق، والشيخ محمد بن عبد العزيز بن مانع. ومن أعمالِه أنَّه تولى القضاءَ في الغطغط، وكان إمامًا وخطيبًا للجامع الكبير بالرياض، ولما افتُتِحَت رئاسةُ المعاهد والكليات كان هو الرئيسَ، ولما تأسَّسَت رئاسةُ القضاء عُمِّد رسميًّا برئاسةِ القضاء، ولما افتُتِحَت رئاسةُ البنات كان هو المشرفَ العامَّ عليها، وكان هو مفتي البلاد، ولما افتُتِحَت رابطةُ العالم الإسلامي كان هو رئيسَ المجلس التأسيسي لها، وكان أمينُ الرابطة وقتها محمد سرور الصبان، ولما افتُتِحَت الجامعة الإسلامية في المدينة كان هو المؤسِّسَ لها، وعَيَّن نائبًا له الشيخ عبد العزيز بن باز, وفي سنة 1373 هـ أنشأ المكتبةَ السعودية العامة في الرياض، وجمع فيها حوالي 15.000 كتابٍ مطبوعٍ، و 117 مخطوطًا، وأملى من تأليفِه كُتُبًا، منها: ((الجواب المستقيم))، و ((تحكيم القوانين))، ومجموعة من أحاديث الأحكام، والفتاوى في عدة مجلَّدات، وكان الملكُ عبد العزيز قد أمر بجَمعِها وطباعتها. ومن تلاميذه: الشيخ عبد الله بن حُمَيد، والشيخ عبد العزيز بن باز، والشيخ سليمان بن عبيد، والشيخ صالح بن غصون، والشيخ عبد الله بن جبرين. وقد أصيب الشيخُ بمرضٍ، فصدر أمرٌ ملَكيٌّ بنقله إلى لندن لمواصلة العلاج، فلما وصل لندن أجرَوا له الفحوصاتِ اللازمةَ فرأوا أنَّ المرضَ بلغَ غايةً لا ينفَعُ معها علاجٌ، ثم دخل في غيبوبة وهو هناك، فأُتيَ به إلى الرياضِ على طائرة خاصة، وبَقِيَ في غيبوبة حتى وافته المنيَّةُ -رحمه الله- صباحَ يوم الأربعاء 24 رمضان، وصلِّيَ عليه بعد صلاة الظهر من نفس اليوم، وأمَّ النَّاسَ عليه الشيخُ ابن باز، وامتلأ المسجِدُ وجميعُ الطُّرُقات المؤدية إليه، حتى إن كثيرًا من النَّاسِ لم يُدركوا الصلاةَ عليه، ودُفِن في مقبرة العود."},{"id":5357,"title":"اقتسام المنطقة المحايدة بين السعودية والكويت .","date":["العام الهجري :1389","الشهر القمري : ذي القعدة","العام الميلادي :1970"],"text":"اقتَسَمت السعوديةُ والكويت إدارةَ المنطقة المحايِدة الواقعة في الحدودِ بين الكويت والسعودية، وبدأت مفاوضاتُ التقسيم بعد وقتٍ قصير من لقاءِ حُكَّام الكويت والسعودية في تشرين الأول عام 1960م، وتم الاتفاقُ على وجوب تقسيمِ المنطقة المحايِدة (المجاورة) أراضي كلٍّ منها، مع المحافظة على اتفاقية سابقةٍ تقضي بتقاسُمِ الموارد النِّفطية بينهما مناصَفةً، وتمَّ التوقيعُ على اتفاق ترسيم تقسيم المنطقة المحايدة في 17 ديسمبر 1967م، لكِنَّ الاتفاقية لم تأخُذْ طابَعَها الرسمي حتى تمَّ تبادل الوثائق والتواقيع التي جرت في الكويت في 18 ديسمبر من هذا العام، ثم تَبِعَها إجراءاتُ التصديق في 18 يناير 1970م."},{"id":5358,"title":"مذابح المسلمين الكبرى في الفلبين .","date":["العام الهجري :1390","العام الميلادي :1970"],"text":"نُفِّذت مَذابحُ مُروِّعةٌ ضِدَّ مُسلِمي الفلبينِ على يَدِ حُكومة الدِّكتاتور فرديناند ماركوس، الذي حكَم الفلبينَ من 1965 إلى 1986م بالحديدِ والنارِ؛ حيث ارتكَبَت قُوَّاته أفظَعَ الجرائمِ في حقِّ المسلمين؛ مِن قتْلٍ جَماعيٍّ، وإحراقِ الأحياءِ، وانتهاكِ الأعراضِ والحُرماتِ، وَفَقْءِ أعيُنِ الرجالِ، وبقْر بُطون الأطفالِ، وذبْحٍ بالخناجرِ، وفصْلٍ للرُّؤوس عن الأجسادِ! وما بين عامي 1392- 1404هـ قُتِل أكثرُ مِن 30.000 مسلمٍ من النِّساء والأطفالِ وكِبار السِّن، وفرَّ أكثرُ من 300.000 مسلمٍ، وتمَّ إحراقُ 300 ألفِ مَنزلٍ، وتدميرُ مائةُ قريةٍ ومدينةٍ إسلامية، وأكثرِ من 500 مسجدٍ!"},{"id":5359,"title":"النزاع السعودي الإيراني في الخليج العربي .","date":["العام الهجري :1390","العام الميلادي :1970"],"text":"ظلَّت السُّعودية تَنظُر بكثيرٍ من الحذَرِ لخُطَط ونشاطاتِ طهرانَ في المنطقةِ، ولكنها لم تَصِلْ إلى حدِّ النِّزاع أو الاشتباكِ. وفي كانون الثاني (يناير) 1968 قرَّرت حُكومةُ حِزب العُمال البريطانيةُ إبطالَ مَفعولِ المعاهداتِ المعقودةِ حولَ مَحْميات البحرينِ، وقَطَر، وإماراتِ ساحلِ الصلحِ السَّبعة (أبو ظَبي، وعجْمان، ودُبي، والفُجيرة، ورأْس الخيمة، والشارِقة، وأم القيوين)، وسحْبَ جُزءٍ كبير مِن قُواتها من هناك. وفي أوَّل آذار (مارس) 1971 أعلَنَت حُكومة المحافظينَ التي تَسلَّمت مقاليدَ الحُكْم في حُزَيران (يونيو) 1970 أنَّ الجلاءَ سوف يُنجَزُ قبْل نِهايةِ عامِ 1970م. اتَّخذت لَندن هذا القرارَ، وأخَذت تبحَثُ بنَشاطٍ عن فُرَصٍ للحِفاظ على نُفوذِها الاقتصادي والسِّياسي في المنطقةِ؛ ولهذا الغرَضِ طرَحَت خُطةَ إنشاءِ اتِّحادٍ مِن الإمارات التِّسع التي كانت خاضعةً لِلحِماية البريطانية، بَيْدَ أن إيرانَ عارَضَت انضمامَ البحرينِ إلى الاتِّحاد العربيِّ، وأعلَنت أنها تَعتبِرُها جُزءًا من أراضيها. وكانت للملِكِ فَيصل عَلاقاتٌ وُدِّيةٌ مع أمير البحرينِ، فرفَض الملِكُ فَيصل مَطامِعَ إيرانَ في البحرينِ. كما كانت إيرانُ والسُّعوديةُ على خلافٍ في قَضايا أخرى أيضًا. وفي ربيع عامِ 1971 أعلَن شاه إيرانَ أنَّ بِلاده تَتحمَّل مَسؤوليةَ الدِّفاع عن الخليجِ بعدَ انسحابِ البريطانيين مِن هناك، واعتزَمَت إيرانُ تَثبيتَ سيَطرتِها على الخليجِ عَسْكريًّا دونَ إقامةِ اعتبارٍ لرأي العرَبِ. أخفَقَت فِكرةُ إنشاء اتِّحادٍ مِن تسعِ إماراتٍ؛ فقد سعى أميرَا البحرينِ وقَطَر إلى الاستقلالِ، كما أنَّ الحكومةَ الإيرانيةَ عارضت عَمليًّا إنشاءَ اتِّحاد \"الإمارات التِّسع\"؛ لذا قرَّرت بِريطانيا تأسيسَ دَولةٍ جديدة تضُمُّ إماراتِ ساحلِ الصلحِ السَّبع. بعدَ إعلانِ استقلالِ البحرينِ، تخلَّت إيرانُ شكليًّا عن مَطامعِها فيها؛ لذا فقد خفَّت حِدَّة الخلافاتِ بين الشاهِ والملِك فَيصلٍ، غيرَ أنَّ خُطط إيرانَ في مَنطقةِ الخليج لم تَتوقَّفْ."},{"id":5360,"title":"معركة جزيرة أبا في السودان بين جماعة الأنصار وحكومة النميري .","date":["العام الهجري :1390","الشهر القمري : محرم","العام الميلادي :1970"],"text":"بدَأَت الصِّداماتُ في السُّودان بين حُكومة النميريِّ الاشتراكيةِ وأنصارها مِن جِهةٍ، وبين حَرَكة المقاوَمة الشَّعبيةِ مِن جِهةٍ أخرى، وكان أوَّل الصِّداماتِ دُخول قُوَّات الأمْن إلى مَسجدِ عبدِ الرحمن المهدي الذي يَتجمَّع فيه الأنصارُ عادةً، فقُتِل ثلاثونَ رجلًا مِن الأمن في حِين قُتِل ألْفُ رجلٍ مِن الأنصارِ جَماعةِ المهديِّ، ثم رفَض الهادي زِيارةَ النميريِّ لجِزيرة \"أبا\" الواقعةِ في النِّيل الأبيض جَنوب الخرطومِ ويَملِكُها المهديُّ، وتجمَّعت قوَّاتُ جبهْة المقاومة الشَّعبيةِ في الجزيرةِ، قامت قُوَّات الحكومةِ بمُداهَمة جَزيرة \"أبا\" بالمدفعيةِ والمدرَّعات والطائراتِ، واشترَكَ فيها الطيرانُ المصريُّ، فقتَلَت أعدادًا كبيرةً من قُوَّات الجبهةِ، بل ومِن السُّكَّان أيضًا، حتى وصَل عددُ الضَّحايا إلى خمسةٍ وعشرين ألفَ قَتيلٍ، ثم أُذِيعَ بعدَ خمْسة أيامٍ عن مَقتلِ الهادي المهديِّ عندَ الحدودِ الشَّرقية مع الحبَشةِ أثناءَ مُحاولتِه الهربَ من البلادِ، وكانت القُوةُ العسكرية التي أرسَلَها النميريُّ إلى الجزيرةِ بقِيادةِ العميد أبي الذهب، ومعه قائدُ حامية كوستي، وبرُفْقته سِتُّ مائة جُنديٍّ، وبعد هذه المعركةِ عمِلَ الشُّيوعيون في الحكومةِ على جَرِّها لتَصفيةِ أعدائهم تَصفيةً جَسديةً؛ فعَمَّ القتْلُ في البلادِ وساد الخوفُ والذُّعرُ."},{"id":5361,"title":"مبادرة روجرز أول مبادرة سلام في الصراع العربي الإسرائيلي .","date":["العام الهجري :1390","الشهر القمري : ربيع الآخر","العام الميلادي :1970"],"text":"عرَض وزيرُ الخارجية الأمريكيةِ وليام رُوجرز مشروعَه في 9 ديسمبر، وتألَّفَ مشروعُ رُوجرز في دِيباجة مُوجَزة تدْعو إلى عقْدٍ اتفاقٍ نهائيٍّ ملزِمٍ بصورةٍ مُتبادلة بين مصرَ وإسرائيلَ، يَجري التفاوضُ بشَأْنه تحت رِعاية السَّفير السويديِّ \"غونار يارنغ\" الممثِّل الشَّخصي للأمين العامِّ للأُمَم المتحِدة، ويَستنِد هذا الاتِّفاق إلى نِّقاط عشْر، أهمها أن تقومُ مصرُ وإسرائيلُ بتَحديد الجدْول الزَّمني والإجراءات المتعلِّقة بانسحاب القواتِ المسلَّحة الإسرائيلية مِن أراضي جُمهورية مصرَ العربيَّة التي احتُلَّت في النِّزاع عامَ 1967م. وانتهاء حالةُ الحرب بين مِصرَ وإسرائيلَ وتُقام حالةٌ رَسميةٌ للسلامِ، ويُوافِق الجانبانِ على أن مَضيق تِيران ممرٌّ مائيٌّ دَولي، وعلى أنَّ مَبدأ حُرِّية الملاحة يسْري على جميعِ الدُّول بما فيها إسرائيلُ، وفي الجانب الأردني: تَحسِم إسرائيلُ والأردنُّ معًا مسألةَ السَّيطرة على القدسِ، مع الاعترافِ ببَقاء المدينة مُوحَّدة، وحُرِّية التنقُّل في جَميع أجزائها، ويَتقاسَمُ البَلَدانِ المسؤولياتِ المدنيةَ والاقتصادية لحكومةِ المدينة. ويَشترِك الأردنُّ وإسرائيلُ في العمل على إتمامِ الإجراءاتِ النهائية لإدارةِ قِطاع غَزَّة، ويُعطى اللَّاجِئون الفِلَسطينيون (من حرب 48) الخيارَ بين العودةِ إلى إسرائيلَ، أو الإقامةِ الدائمة في الدُّول العربيَّة مع تَعويضاتٍ إسرائيليةٍ. وانتهَت مُبادرةُ رُوجرز -كأوَّل مُبادَرةٍ للسلامِ بين العربِ وإسرائيل خلالَ عهْدِ إدارة نِيكسون- إلى الفشَلِ؛ فقد رفَض الاتِّحاد السُّوفيتي مشروعَ رُوجرز بسَببِ عَدَم تَوازُنه وانحيازِه لإسرائيلَ، ورفَضَتْه إسرائيلُ! أما الفِلَسطينيون فقد رفَضوا مشروعَ رُوجرز؛ لأنَّه يتنكَّر لحُقوقِهم الوطنية، واعتَبَروه مُؤامرةً ضدَّ الكفاحِ الفِلَسطيني المسلَّح. أما الموقفُ المصري فعلى الرَّغم مِن تَرحيب عبد الناصرِ بها وإيقافِه لحرْب الاستنزافِ، إلا أن مُبادَرة روجرز رُفِضَت في الأخير؛ لأنها لم تَشتمِلْ على حلٍّ شامل لجميعِ المناطقِ العربيَّة المحتلَّة."},{"id":5362,"title":"استقلال عُمان وانقلاب السلطان قابوس على أبيه .","date":["العام الهجري :1390","الشهر القمري : ربيع الآخر","العام الميلادي :1970"],"text":"كانت سَلْطنة عُمانَ من بيْن أوائل الدُّول التي نالَت استقلالَها في المنطقةِ. بعدَ أنْ أنهى السُّلطان قابوس دِراساتِه العسكريةَ في لَنْدن وقِيامِه بجولةٍ حولَ العالم، تمَّ استدعاؤه إلى الوطَنِ، ووُضِعَ قابوس في عُزْلة في قصْر صلالةَ؛ بسَبب تَعارُض أفكارِه التقدُّميةِ العالمية مع مُيول والِدِه في الإبقاءِ على محافظةِ وانعزاليةِ عُمان. وبدَعْمٍ مِن البريطانيين والصَّفوة السياسية في عُمان استولَى السُّلطان قابوس (البالغ مِن العُمر 30 عامًا) على الحكْمِ إثرَ انقلابٍ نفَّذه ضِدَّ أبيه سعيدِ بن تَيمور، ثم نَفى والدَه إلى لَندن؛ حيث مات هناك عام 1972م، وما إنْ تَسلَّم السُّلطانُ قابوس السُّلطةَ في يوليو 1970م حتى حصَل على اعترافٍ عالميٍّ كامل يَمنَحُه الاستقلالَ التامَّ عن بِريطانيا. وتمَّ تَغييرُ اسمِ الدَّولة من \"سَلْطنة مسْقطَ وعُمان\" إلى \"سَلْطنة عُمان\"، وبالإضافةِ إلى دَور قابوس كسُلْطانٍ يَشغَلُ قابوس مناصبَ رئيسِ الوزراء، ووزيرِ الخارجية، ووزيرِ الماليَّة، ووزيرِ الدِّفاع. جاء آل بوسعيد إلى حُكْمِ عُمان عام 1154هـ / 1741م، وما زالوا يَحكُمون إلى الآن، ويعودُ تاريخُ بوسعيد إلى أحمدَ بنِ سعيد الذي عُيِّن مُستشارًا لسيف بنِ سُلطان، آخِر مَن حكَمَ عُمان مِن اليعاربةِ، فلمَّا رأى اضطرابَ الأمورِ في البلادِ، وضَعْفَ الحاكمِ سيفِ بن سُلطان، وتفتُّتَ البلاد في عهْدِه؛ عمِلَ على تَوحيد الصُّفوف، وقضى على القواتِ الفارسيةِ الموجودةِ بالبلاد، وعلى إثْر ذلك بُويِعَ إمامًا للبلادِ، وتوالى الأئمةُ مِن آل بوسعيد حتى آل الأمْرُ للسُّلطان قابوس بنِ سعيد."},{"id":5363,"title":"توقف العمليات العسكرية في اليمن الشمالي .","date":["العام الهجري :1390","الشهر القمري : جمادى الأولى","العام الميلادي :1970"],"text":"توقَّفت العملياتُ الحربيةُ في شَمال اليمنِ ونصَّت اتِّفاقيةٌ وقَّعتها السُّعوديةُ والجُمهورية العربيَّة اليمنيةُ في هذا الشَّهر على تخلِّي الحكومةِ اليمنيةِ عن العديدِ مِن مُنجَزات الثَّورة. وبدَأ تَطهيرُ الجيش وهَيئات أمْن الدولة في اليمنِ مِن العناصر اليَساريةِ، وعاد مِن السُّعودية الكثيرُ من الملكِيينَ الذين تَبوَّأَ عددٌ منهم مناصبَ في هَيئات السُّلطة العليا، ثم اعترَفَت السُّعودية رسميًّا بالجُمهورية العربيَّة اليمنيةِ، وأعقَبَ ذلك اعترافُ بِريطانيا."},{"id":5364,"title":"إعلان الملك حسين الأحكام العرفية في الأردن .","date":["العام الهجري :1390","الشهر القمري : رمضان","العام الميلادي :1970"],"text":"أعلَن الملِكُ حُسين بن طلالٍ الأحكامَ العُرْفية في الأردنِّ، وتَنصيبَ حُكومة عسكريةٍ بَدلًا مِن مَدَنية في عَمان، فعيَّن مُستشارَه العسكريَّ حابس المجالي حاكمًا عسكريًّا عامًّا للأردنِّ، وشكَّل وزارةً جديدة برئاسةِ الزعيمِ داود خلَفًا لوزارةِ عبد المنعم الرفاعي المستقيلةِ، وعيَّن حُكامًا عسْكريين في كلِّ مُحافظات الأردنِّ، وكان هذا قبل هُجوم الجيش الأردني على المنظَّمات الفِلَسطينية في الأردن في 15 أيلولَ، والتي عُرِفَت بـ\"أيْلول الأسود\". واستمَرَّت الأحكامُ العُرْفية إلى أن أُعلِنَ عن إنهائِها عام 1991."},{"id":5365,"title":"أيلول الأسود (الصدام الفلسطيني الأردني) .","date":["العام الهجري :1390","الشهر القمري : رمضان","العام الميلادي :1970"],"text":"\"أيلول الأسودُ\" هو الاسمُ الذي يُشار به إلى شَهر أيلولَ من هذا العامِ؛ ففي هذا الشَّهر تحرَّك حُسين بن طلال ملِكُ الأردنِّ لإجهاضِ مُحاولةٍ لمنظَّمات فِلَسطينية لإسقاطِ نِظامِ حُكمِه الملكيِّ؛ حيث استمرَّ القتالُ المسلَّح حتى يُوليو عام 1971م؛ حيث كان الفِلَسطينيون يُشكِّلون نِسبةً عالية من تَعدادِ سُكان الأردنِّ في تلك الفترة، وكانوا مَدْعومين من قِبَل أنظمةٍ عربية مُختلِفة، خاصَّةً من الرئيس المصريِّ جَمال عبد الناصر. بدَأَت قُوات الأمنِ الأُردنية وقُوات الجيش تَفقِد سُلْطتها؛ حيث بدَأت قُواتُ منظَّمة التحرير الفِلَسطينية النِّظامية بحمْلِ السلاحِ بشَكلٍ عَلَني، وإقامة نِقاطِ تَفتيشٍ، وجمْع ما أطلقوا عليه مُصطلح \"ضَرائب القضيةِ الفِلَسطينية\". هذا الانتشارُ الفِدائي على الساحة الأُردنية بدَأ يُقلِق الملِكَ حُسينًا، الذي بات يَشعُر أنَّ هناك دولةً بدأَت تنْمو داخلَ دَولتِه. وخلالَ مُفاوضاتِ نوفمبر عام 1968 تمَّ التوصُّل إلى اتِّفاقية من سبْعة بُنود بين الملِك حُسين والمنظَّمات الفِلَسطينية، لكن لم تَصمُد الاتفاقيةُ، وأضْحَت منظَّمة التحرير الفِلَسطينية دولةً داخلَ الدولةِ في الأردنِ، وأصبَح رِجالُ الأمنِ والجيش الحُكومي يُهاجَمون ويُستهزَأ بهم، وما بين مُنتصَف عام 1968 ونهاية عام 1969م كان هنالك أكثرُ مِن 500 اشتباكٍ عنيف وقَع بين الفصائل الفِلَسطينية وقُوات الأمْن الأُردنية. وأصبَحَت أعمالُ العُنْف والخطْف تَتكرَّر بصُورةٍ مُستمِرَّة، كما أن المنظَّمات الراديكاليةُ في مُنظَّمة التحرير الفِلَسطينية -الجبْهة الشَّعبية لتحريرِ فِلَسطين لجورج حبش، والجبْهة الديمقراطيةُ لتَحرير فِلَسطين لنايف حواتمة، والجَبْهة الشعبيةُ لتَحرير فِلَسطين القيادة العامة لأحمد جبريل قرَّرت تقويضَ نِظام الملِك حُسين بن طلال. وفي 9 يونيو نجا الملِكُ حُسين من مُحاولة فاشلةٍ لاغتياله أثناءَ مُرور مَوكبه في منطقة صويلح، ومحاولةٍ فاشلة أُخرى بوسط عَمان؛ حيث قام قنَّاص فِلَسطيني كان مختبئًا على مِئذنة المسجدِ الحُسيني بإطلاق النارِ على سيَّارة الملِك، واستقرَّت إحدى الرصاصاتِ في ظَهر زَيد الرفاعي الذي كان يُحاوِل حِمايةَ الملِك، كانت تلك الفترةُ الأكثرَ حسْمًا ودَمويةً؛ حيث بدَأ الجيشُ الأردني في التوجُّهِ إلى المدن والمخيَّمات الفِلَسطينية والهجومِ على القواعدِ الفدائيةِ فيها بعدَ 16 أيلول، وفي أيَّام الحرب طرَح النِّظام الأُردني سيناريو التدخُّلِ الأمريكي والإسرائيليِّ البريِّ والجويِّ لدَعْم جيش الأُردنِّ، خصوصًا بعدَ أن أعلَنَت سُوريا والعراقُ دَعمَهما للمقاومةِ الفِلَسطينية في الأردنِّ، فتحرَّكت 300 دبابةٍ من القوات السُّورية لتُحِيط بمدينةِ إربد الأُردنية في 20 مِن أيلول، وما بين فِبراير ويونيو من عامِ 1970 قامت مُصادماتٌ بين قُوات الأمْن وقوَّات المنظَّمات الفِلَسطينية. انتهَت المعاركُ بين الطرفينِ في 28 أيلول بعدَ توقيعِ اتفاقيةٍ بين ياسر عَرفات والملِك حُسين في القاهرةِ بحُضور جمال عبد الناصرِ في أعقابِ القِمة العربيَّة الطارئةِ في القاهرةِ في أيلول / سبتمبر، وقُدِّر عددُ القتْلى والإصاباتِ بين الأُردنيين والفِلَسطينيين بعشَراتِ الآلافِ، وتُمثِّل أحداثُ \"أيلول الأسود\" نُقطةَ تحوُّل في الهُوية الأردنية؛ حيث باشَرَت المملكةُ ببرنامجِ \"أرْدَنة المجتمَع\"، وطرْد القُوات الفِلَسطينية إلى لُبنان؛ حيث أسَّست فتح \"منظَّمة أيلول الأسود\"، وفي 28 نوفمبر 1971 في القاهرة اغتِيلَ رَئيس الوزراء الأردني وَصفي التل على يَدِ أربعةٍ من أعضاء مُنظَّمة فتْح، وكان (التل) قد اتَّسم بالعنْف في عملية إجلاءِ الفِدائيين من الأردنِّ."},{"id":5366,"title":"مؤتمر القمة العربية غير العادي الأول بسبب أحداث أيلول الأسود .","date":["العام الهجري :1390","الشهر القمري : رمضان","العام الميلادي :1970"],"text":"عُقِدت هذه القِمة (غير العادية وغير الرَّسمية) في القاهرة على إثرِ الاشتباكاتِ العنيفةِ في الأردنِّ بين الأرُدنيين والفِلَسطينيين، ولم تَعقِدْ هذه القِمةُ جلساتٍ عامةً، وتحوَّلت إلى مُشاوَرات بين رُؤساء الدُّول؛ ولهذا فإنَّ الجامعة العربيَّة لم تُدرِجْها في سِجِلاتها الرسمية للقِمَمِ العربيَّة، وانتهَت هذه القِمة -التي قاطعَتْها كلٌّ من سُوريا والعراقِ، والجزائر والمغربِ- بمُصالحةٍ بين منظَّمة التحرير الفِلَسطينية والأردنِّ، وصَدَر عنها بَيانٌ خِتامي، وأهمُّ قَراراتِه:1- الإنهاءُ الفَوريُّ لجميع العملياتِ العسكريةِ مِن جانب القوَّات المسلَّحة الأُردنية وقُوات المقاوَمة الفِلَسطينية.2- السحْبُ السريعُ لِكِلتا القُوَّتين من عَمّان، وإرجاعُها إلى قواعِدِها الطبيعيةِ والمناسبة.3- إطلاقُ المعتقلينَ مِن كِلا الجانبينِ.4- تكوينُ لجنة عُلْيا لمتابَعة تَطبيق هذا الاتِّفاق. وانتهت مُشاورات المؤتمر إلى مُصالحة كلٍّ مِن ياسر عَرفات رئيس منظَّمة التحريرِ الفِلَسطينية والملِكِ حُسَين."},{"id":5367,"title":"وفاة جمال عبد الناصر حاكم مصر ونهاية الحكم الناصري  .","date":["العام الهجري :1390","الشهر القمري : رمضان","العام الميلادي :1970"],"text":"هو جَمال عبد الناصرِ بن حُسين بن خَليل بن سُلْطان عبْد الناصر، رئيسُ الجُمهورية العربيَّة المتحِدة، وقائدُ ثَورة يُوليو 52 العسكرية (ثَورة الضُّباط الأحرار). وُلِدَ في قَرية بني مُر بمحافظةِ أسيوطَ سنة 1336هـ / 1918م، وانتقَلَ إلى القاهرةِ وعُمره ثمانِ سنواتٍ، فعاش مع عمٍّ له اسمه خَليل. وتعلَّم بها ثم بالإسكندريةِ، وحصَل على البكالوريوسِ سنةَ 1936، وشارَك في المظاهَرات المعاديةِ للإنجليزِ، وجُرِح مرَّتين سنةَ 1933 و1935، وتخرَّج من الكُلِّية الحربية سنةَ 1938، ودرَّس بها. وتخرَّج بكُلِّية أركانِ الحرب، وشارَك في حرْب فِلَسطين 48، وجُرِح وشُفِي، وعاد وحُوصِر في الفالوجة بفِلَسطين 4 أشهر، وخرَجَ مع زُملائه من الفالوجةِ ناقمينَ على الحُكْم في مصرَ، فقاموا سنةَ 1952م بثَورة الضُّباط الأحرار على الملِكِ فاروق آخِرِ مُلوك مصرَ، فنزَل عن العرشِ لابنه أحمدَ فؤاد، ثم لم يَلبَثوا أن خَلَعوه وأعْلَنوا الجُمهورية، وسمَّوا لرئاستِها أحدَ كبارِ الضُّباط محمَّد نجيب، وتولَّى جمالٌ رئاسةَ الوزراء. وأُذِيعَ أنَّ نَجيب يُريد إبعادَ الجيش عن الحُكْم وإعادتَه إلى المدنيينَ، فحجَزه جمالٌ في بَيته وتسلَّم زِمامَ السُّلطة عامَ 1954م، وفي 1956م انتُخِب عبد الناصر رئيسًا للجُمْهورية العربيَّة المتحِدة، وفي عهْدِه تمَّت اتِّفاقية جَلاء الإنجليزِ مِن الأراضي المصرية، وأمَّمَ شَركة قناة السُّويس، وترتَّب على ذلك العُدوان الثُّلاثي على مصرَ؛ حيث قامت بِريطانيا وفرنسا وإسرائيلُ بالاعتداءِ على مصرَ 1956م، فاحتلَّت إسرائيلُ أجزاءً من مصرَ وسُورية والأردنَّ، وأعلَنَ الوَحدةُ المصرية السُّورية 1958م، ثم انفصَلَت في عام 1961م، وحوَّل مصرَ إلى النِّظام الاشتراكيِّ 1961م، وبنى السَّدَّ العالي 1959 – 1970م، وخاض حرْبَ اليمنِ الأهليةِ بيْن عاميْ 1963 - 1968م عندما دعَم ثَورة العقيدِ عبد الله السلالِ ضِدَّ الملكيِّين المدعومينَ من السُّعودية، وفي حُزَيران 1967م قاد الأمَّةَ العربيَّة إلى نَكسة حُزيران بسِياساته المتعجرفةِ الإعلاميةِ أمام إسرائيلَ، بدَأت عَلاقة عبدِ الناصر بالمخابراتِ الأمريكية منذُ آذار / مارس 1952م، أي: قبْل قِيام الثورة بأربعةِ أشهرٍ، كما اعترَف بذلك أحدُ رِفاقه، وهو خالد مُحيي الدِّين، وتحدَّث اللِّواء محمَّد نجيب أولُ رئيسٍ لمصرَ بعد الثَّورة عن هذه العَلاقة في مُذكِّراته، وأنهم همُ الذين كانوا يَرسُمون له الخُطط الأمْنيةَ، ويَدعُمون حرَسَه بالسياراتِ والأسلحةِ الجديدةِ. نشَأَت في عهْدِه الناصريةُ، وهي حركةٌ قوميةٌ عربيةٌ استمرَّت بعدَ وفاتِه، واشتُقَّت اسمُها من اسمِه، وتبنَّت الأفكارَ التي كان يُنادي بها، وهي: الحرِّية، والاشتراكيةُ، والوَحدة، وهي نفْس أفكار الأحزابِ القومية اليَساريةِ العربيَّة الأخرى. أما عن وَفاته ففي أثناءِ تَوديعِه لرُؤساء الدُّول العربيَّة بعدَ مؤتمرِ القِمة العربيَّة الطارئِ الذي عُقِد في القاهرة، وأثناءَ تَوديعه لآخِرِ المسافرين أميرِ الكويتِ في يوم الاثنين 28 رجب 29 سبتمبر؛ تُوفِّي جمالُ عبد الناصر بعدَ أن دامَت رِئاسته أكثرَ من أربعةَ عشَرَ عامًا، وتسلَّم أنور السادات النائبُ الأولُ لرئيس الجُمهورية منصِبَ الرِّئاسةِ بالنِّيابة حتى تتَّفق الهيئاتُ العليا على رئيس جديدٍ، ثم رشَّح الساداتُ نفْسَه مِن قِبَل الاتِّحاد الاشتراكيِّ لتولي المنصبِ، وتمَّ الاستفتاءُ في شعبان / 15 تشرين الأول 1970م، وانتُخِب الساداتُ رئيسًا لمصرَ."},{"id":5368,"title":"الحرب الهندية الباكستانية الثالثة .","date":["العام الهجري :1391","العام الميلادي :1971"],"text":"أعدَّت الهِند عُدَّتها لفصْل شَطْري باكستانَ عن بعضِهما، وعقَدَت حِلفًا عسكريًّا مع رُوسيا لردْعِ أيِّ مُحاولةِ تهديدٍ تأتي من الصِّين، وقد كانت القواتُ الهِندية تَفوق القواتِ الباكستانيةَ في الجبهةِ الشرقيةِ بما يُعادِل ستة أضعافها، ومُجهَّزة بكلِّ الوسائل الحديثةِ في القتالِ، تَدعُمها رُوسيا، بينما إمكانياتُ الباكستانيينَ في الشرْق ضَعيفةٌ، واندلَع القِتالُ على كافَّة الجبهاتِ الشرقيةِ والغربيةِ وكَشمير، وتقدَّمت الهِندُ في بنجلاديشَ، وبرغْم المقاومةِ الباسلةِ التي أبداها الباكستانيون في الشَّرق إلا أنَّهم اضطرُّوا للاستسلامِ. أما في الغرْبِ فكانت الحربُ سِجالًا بين الطرفينِ، وأعلَن مجلسُ الأُمَّة وقْفَ القتال، إلا أنَّ الهِندوس والروسَ قد عارَضوا، حتى توقَّف القتالُ في نهاية 1391هـ، ولا يمكِنُ وصْف المجازرِ والمذابح التي أُقِيمت للمسلمين في بِنغلاديش بعدَ إعلان الاستسلامِ؛ فقد تفنَّن الهنودُ في أساليب القتْل والتعذيبِ للمُسلمين."},{"id":5369,"title":"افتتاح السد العالي بمصر أكبر مشروع كهرومائي في الشرق الأوسط .","date":["العام الهجري :1391","العام الميلادي :1971"],"text":"بدَأ العملُ في بِناء السَّدِّ العالي في 10 / 7 / 1379هـ / 9 يناير1960م، وتَمَّ الانتهاءُ مِن تنفيذ المرحلةِ الأولى في 16 مايو 1964م، وانتهى تَنفيذ المرحلةِ الثانية في 15 يناير 1971م، والسَّدُّ العالي: هو سَدٌّ مائيٌّ على نَهر النِّيل في جَنوب مصرَ، أُنشِئَ في عهد جمالِ عبد الناصرِ، وشارك السُّوفيتُ في بِنائه. وقد ساعَد كثيرًا في التحكُّم في تدفُّقِ المياهِ، والتخفيفِ مِن آثار فَيضانِ النِّيل. ويُستخدَمُ لتوليدِ الكهرباء في مصرَ. ويَبلُغ طولُ السَّدِّ 3600 متر، وعرْضُ القاعدةِ 980 مترًا، وعرْضُ القمَّة 40 مترًا، والارتفاعُ 111 مترًا، وحجْمُ جِسم السَّدِّ 43 مليون متر مكعَّب مِن إسمنت وحديدٍ وموادَّ أُخرى، ويمكِن أن يَمُر خلالَ السدِّ تدفُّقٌ مائيٌّ يصِل إلى 11000 متر مكعَّب من الماء في الثانية الواحدةِ."},{"id":5370,"title":"الانقلاب العسكري الثاني في تركيا ضد سليمان ديميريل (انقلاب المذكرة) .","date":["العام الهجري :1391","الشهر القمري : محرم","العام الميلادي :1971"],"text":"أثار الرُّكود الاقتصاديُّ موجةً من الاضطراباتِ الاجتماعية التي تمثَّلت في المظاهراتِ التي تجوبُ الشوارعَ، وإضراباتِ العُمَّال، والاغتيالاتِ السِّياسية، كما تمَّ تَشكيلُ حركاتٍ عُمَّالية وطُلابية يساريةٍ تُعارِضُها الجماعاتُ اليَمِينية القوميةُ المسلَّحة والإسلاميَّة، وبحُلولِ يناير 1971 عَمَّت الفوضى أرجاءَ تركيا، وتوقَّفت الجامعاتُ عن العملِ، وأضربت المصانع، وقام الطُّلاب بسَرِقة البنوكِ، وخطْف الجُنود الأمريكانِ، ومُهاجَمة أهدافٍ أمريكية، وأصبَحت الحركةُ الإسلاميَّة أكثَرَ نشاطًا، وقام حِزْبُها -حزبُ النِّظام الوطني- برفْض فِكرة عَلْمانيةِ أتاتورك، والفِكْر الكَماليِّ بشَكْل عَلَني؛ مما أثار غضَب القواتِ المسلَّحةَ، فقام رئيسُ هيئة الأركان العامة التُّركية مَمدوح تاجماك بتَسليمِ رئيس الوزراءِ مُذكِّرةً تصِلُ إلى حَدِّ إنذارٍ أخير من القواتِ المسلَّحة، وطالَبَ فيها \"بتَشكيل حُكومةٍ قويةٍ ذاتِ مِصداقيةٍ في إطار المبادئِ الديمقراطية تضَعُ حدًّا للوضْعِ الفَوضوي الحاليِّ، وتُطبَّق من خلال وجهاتِ نَظَر أتاتورك القوانينُ الإصلاحية المنصوصُ عليها في الدُّستور، وإذا لم تتِمَّ تلبيةُ هذه المطالِب فإنَّ الجيش سوف يُمارِس واجِبَه الدُّستوري ويَتولى السُّلطة\"، فقدَّمَ الرئيسُ سليمان ديميريل استقالتَه بعد اجتماعٍ استمرَّ ثلاثَ ساعات مع حُكومته، واستنكَر زعيمُ المعارَضة والسياسيُّ المخضْرم عصمت إينونو بشِدةٍ أيَّ تدخُّل عسكريٍّ في السِّياسة، وكان بعض كبارِ الضُّباط يروا أنه مِن المستحيلِ أن يَحدُثَ تقدُّم في نِظام ديمقراطي لِيبراليٍّ، وأنَّ التسلُّطَ سيَجعلُ مِن تركيا أكثرَ مُساواةً واستِقْلالية و\"عصْرية\"، بينما رأى ضُباط آخَرون ضَرورةَ التدخُّل، ولو لإحباطِ هذه العناصر فقط، وعُرِف هذا الانقلابُ (بانقلاب المذكِّرة)؛ نَتيجةً لِما أحدَثَته المذكِّرةُ التي سلَّمها رئيسُ هيئة الأركان العامة لِرَئيس الوزراء التُّركي، فحدَث الانقلابُ دونَ تدخُّلٍ عَسْكري."},{"id":5371,"title":"عودة العلاقة الدبلوماسية بين السعودية والجمهورية اليمنية .","date":["العام الهجري :1391","الشهر القمري : محرم","العام الميلادي :1971"],"text":"عادَت العَلاقات الدُّبلوماسيةُ بين السُّعودية والجُمهورية اليمنيةِ، وقام رَئيس وُزراء الجُمهورية العربيَّة اليَمَنيةِ عبد الله الحجريُّ بزِيارة الرياضِ. ونصَّ بلاغٌ سُعودي يَمَنيٌّ مشترَك على أنَّ الحُدودَ بين البلدينِ ثابتةٌ ونهائيةٌ، كما نصَّت عليها معاهدةُ الطائفِ عام 1353هـ / 1934م. وأدَّى تقارُب صَنعاءَ مع الرِّياضِ إلى تَحسين عَلاقات اليمنِ الشماليِّ بالولايات المتحِدةِ وبريطانيا وألمانيا الغربيةِ، وإلى إضْعاف روابطِ التعاوُنِ مع البُلدانِ الاشتراكيةِ."},{"id":5372,"title":"قيام الجمهورية العربية المتحدة بين (مصر وسوريا وليبيا) .","date":["العام الهجري :1391","الشهر القمري : صفر","العام الميلادي :1971"],"text":"عمِلَت الثورة اللِّيبيةُ على إقامة اتِّحاد الجُمهوريات العربيَّة المتحِدة الذي تألَّف مِن مصرَ وسُوريا ولِيبيا، وكانت طرابلسُ مَقرَّ المباحثاتِ التي دارت لإقامةِ هذا الاتِّحاد، ووُقِّع الميثاقُ في بَنغازي ووُقِّع بعدها الاتِّفاقُ على الوَحدةِ الاندماجيةِ مع مصرَ، وتمَّ حلُّ هذا الاتِّحادِ في آذار 1977 مع بِداية المفاوَضات بين الساداتِ وإسرائيلَ، وقد عانى الاتِّحاد مُنذ خُطواته الأولى من الكثيرِ من المشاكلِ الناشئة عن تَوالي الأحداثِ في المنطقةِ العربيَّة، وفي دُوَل الاتِّحاد ذاتِها، وكان أبرَزَها الخلافاتُ الدَّائمة بين دُولِ الاتِّحاد، ثم الحربُ العربيَّة الإسرائيليَّة في تِشرين الأوَّل عام 1973، كما جاءت رُدود فِعلِ الحكومة العراقيةِ بسَبب الإعلانِ عن الاتِّحاد دونَ تَوجيهِ الدعوةِ لها بالانضمامِ إليه؛ كونَها أحدَ الأطرافِ الرئيسة التي لها دَورٌ أساسيٌّ في العملِ العربي المشترَكِ، ولأنَّ العراقَ قد طرَح مشروعًا بديلًا لذلك الاتِّحاد، هو مَشروعُ الوَحدةِ المقاتِلة عام 1972، موجِّهًا الدعوةَ لكلٍّ مِن سورية ومصرَ بالانسحابِ من اتِّحاد الجُمهوريات العربيَّة المتحِدةِ، والانضمامِ إلى مَشروعه الجديدِ؛ لكونِه يلبِّي طُموحات المرحلة، والقَبولِ بمَشروعه كبديلٍ إستراتيجيٍّ لمواجهة الأخطارِ التي كانت تُواجِه الأمة العربيَّةَ، ولكن مَشروع العراقِ لم يَلْقَ الاستجابةَ من مِصرَ وسُورية."},{"id":5373,"title":"محاولة الشيوعيين الانقلاب على حكومة النميري .","date":["العام الهجري :1391","الشهر القمري : جمادى الأولى","العام الميلادي :1971"],"text":"انقسَمَ الشُّيوعيون في السودانِ إلى قِسمينِ: قسمٌ يَرى تطبيقَ الشُّيوعيةِ وإعلانَ الحُكْمِ الشُّيوعي، وقسمٌ يَرى الإفادة مِن الحُكْم القائمِ إلى أنْ يَتهيَّأ الجوُّ المناسِبُ؛ إذ لا يمكِنُ حمْل الناس على الشُّيوعية وغالبُهم يَرفُضها، واستطاع أصحابُ هذا الرأيِ إبعادَ الرأي الآخَرِ عن مجلس قِيادةِ الثَّورة، وابتدَأ جَعفرٌ النميري يُهاجِم الحزْب الشُّيوعي الجِناح المعارِضَ الذي أبعَدَ بعضَ أعضائه، وكانت حُكومةُ السُّودان قد عَزَمت على الدُّخول مع مصرَ وليبيا في اتِّحادٍ عربيٍّ، ولكنَّ الشيوعيين عارَضوا ذلك، ثم تحرَّكت بعضُ القطاعات العسكريةِ بإمْرة الرائد هاشم العطا (من رُؤوس الشيوعية المُبعَدين) وسيطَرَت على الوضعِ، واعتقَلَت اللِّواء جَعفرًا النميريَّ في 26 جُمادى الأولى 1391هـ / 19 تموز، غيرَ أنها لم تَستطِعِ السيطرةَ على الحكم لأكثرَ مِن ثلاثة أيامٍ؛ حيث قامت القطاعاتُ الموالية لِلنميريِّ -بدَعْمٍ من القوات المصريةِ، بالإضافة إلى الطَّيرانِ المصري- بإنهاء الانقلابِ، ولَمَّا فَرَّ زُعماء الانقلابِ بطائرةٍ إلى لَندن أجْبَرتها لِيبيا على الهبوطِ، ثم سلَّمتهم إلى النميريِّ. وبعد فشَلِ الانقلابِ تمَّت محاكَمة هشام العطا وقادةِ الحزْبِ الشُّيوعي فيما يُعرف بـ\"محاكمة الشَّجرة\"، التي ترأَّسَها الرئيسُ جَعفرٌ النميري. وتمَّ الحكمُ على جميعِ قادة الانقلابِ بالقتل رميًا بالرصاصِ."},{"id":5374,"title":"استقلال البحرين  .","date":["العام الهجري :1391","الشهر القمري : جمادى الآخرة","العام الميلادي :1971"],"text":"فرضت بريطانيا حمايتها على البحرين منذ سنةَ 1820م، فكانت البحرين تقَعُ تحتَ الاستعمارِ البريطانيِّ، وكانت قِيادة الشؤون الخارجيةِ بيَدِ البريطانيينَ، حتى أضْحَت البحرينُ القاعدةَ البريطانية الأساسيةَ في الخليجِ العربي، وانتقَلَ المقرُّ السِّياسي البريطاني مِن \"بوشهر\" إليها، ثم إنَّ الشَّعب البحرينيَّ بدَأ يتحرَّك لِنَيل بعضِ الحقوقِ، ومنها إصدارُ العُمْلة الخاصَّة به، وكانت لإيرانَ أطماعٌ في البحرين، فقامَت الأُمَم المتحِدة بإرسالِ ممثِّليها إلى البحرينِ لإجراءِ استفتاءٍ عامَ 1970م، فوجَدوا أن الأكثريةَ تَطلُب الاستقلالَ التامَّ، فأعلَنت البحرينُ استقلالَها وألْغَت في اليومِ التالي مُعاهداتها مع البريطانيينَ، ودخَلت الجامعةَ العربيَّةَ في نفْس العام، وكذلك في الأُمَم المتحِدة."},{"id":5375,"title":"استقلال قطر .","date":["العام الهجري :1391","الشهر القمري : رجب","العام الميلادي :1971"],"text":"كانت قَطَر قد تخلَّى عنها العُثمانيون بعدَ أن وقَّع الشيخ جاسمٌ اتفاقيةً معهم، ثم في سنةِ 1916م عقَد البِريطانيون معاهدةَ حِمايةٍ، فأضْحَت تابعةً للضابط البِريطاني في البحرينِ، وبقِيَت كذلك إلى أنِ استقلَّت 12 رجَب 1391هـ / 3 أيلول (سبتمبر)، ونشَرَت دُستورًا لها فورَ استقلالِها، ودخَلت الجامعة العربيَّة، والأُمَم المتحِدةَ، ومنظَّمةَ \"الأوبك\"."},{"id":5376,"title":"انقسام باكستان الشرقية وقيام دولة بنغلادش فيها .","date":["العام الهجري :1391","الشهر القمري : شوال","العام الميلادي :1971"],"text":"بدَأت المطالَبةُ في باكستانَ بتَقسيم باكستانَ الشرقيةِ (بنغلادش حاليًّا) عن باكستانَ الغربيةِ (باكستان الحالية)، وكان شَيخ مُجيب الرحمن (مُيوله اشتراكيةٌ) في باكستانَ الشرقيةِ هو الداعيَ إلى هذا الانفصالِ، وكان مِن المؤيِّدين أيضًا لهذا الانفصالِ ذو الفقار علي بوتو الشِّيعي، وأيَّد الأمريكانُ هذا التَّيار بمِثل ما أيَّدوا به مُجيب الرحمن، إضافةً إلى أنَّ الرئيسَ يحيى خان الشِّيعي أوعَز للشِّيعة بتَأْييد ذي الفقارِ هذا، وكان هذا الانفصالُ لصالِح الهندِ بالدَّرجة الأولى؛ لأن باكستانَ الدَّولةُ الوحيدةُ القادرة على التَّصدِّي لها في المنطقةِ، تفجَّر العصيانَ المسلَّح في باكستانَ الشرقيةِ، وارتُكِبت أبشعُ الجرائمِ، وسُلِبت المحلاتُ التِّجارية، وحُرِّق الناسُ وهم أحياءٌ، وهُتِكت الأعراضُ! فبدَأت الحربُ الثالثةُ بين باكستانَ والهندِ على طُول الجبهات في الشَّرْق والغرب، وكانت الهندُ قد عقَدت حِلفًا مع رُوسيا؛ لضَمان عدَمِ تدخُّل الصينِ، وكان على الهندِ أن تَرمِيَ بكلِّ ثقلِها على الجبهةِ الشرقيةِ؛ لتَنْتهي منها، فدفَعت باثنتيْ عشْرةَ فرقةً من المشاةِ وعِدَّةِ ألويةٍ مِن المدرَّعات؛ لتَقتحِمَ حُدود باكستانَ الشرقيةِ، وكان عددُ الجنود يَزيد على 240 ألف جُنديٍّ، ومعهم دبَّابات رُوسية ذاتُ مدافعَ ثقيلةٍ، بالإضافة للطائراتِ الرُّوسية، وهكذا تقدَّمت الهِند في الجبْهة الشرقيةِ برًّا وبحرًا، وكان في المقابلِ الدفاعُ الباكستانيُّ يَزيد عن ثمانينَ ألف مُقاتِل بدون طيرانٍ، ومع عدَم وُصول الإمدادات وانحصارِها من أكثرَ مِن جهةٍ، اندَحَرت القوات الباكستانيةُ، ثم استسْلَمت باكستانُ الشرقيةُ، وبدَأت الإبادةُ الجماعيةُ والمذابحُ الرهيبةُ؛ فقُتِل العلماءُ والناسُ، ومَثَّلوا بالجُثَث، وأُعلِنَ عن قِيام دَولة بنغلادش، فتسلَّم رئاسةَ الدولة نصرُ الإسلام، وغدا الجيشُ الباكستاني في الجناح الشرقيِّ كلِّه أسيرًا، ووقَّع قائدُه الجنرال نيازي وَثيقةَ الاستسلام، وأعلَنَ مَندوب بنغلاديش في بَيروت جلال الدين أحمد أنَّ دَولتَه ستَقوم على أساسٍ عَلْماني، وأمَّا على الجبهة الغربيةِ فلم تَستطِع الهندُ تحقيقَ الكثيرِ، ثم خرَج قرارٌ من الجمعية العُمومية بوقْفِ إطلاق النارِ ورَغم مُوافَقة باكستانَ على القرارِ، استمرَّت الهندُ في العُدوان إلى أن توقَّف القِتالُ في 29 شوَّال 1391هـ / 17 ديسمبر 1971م."},{"id":5377,"title":"استقلال إمارات مشيخة الخليج العربية (دولة الإمارات العربية المتحدة)  .","date":["العام الهجري :1391","الشهر القمري : شوال","العام الميلادي :1971"],"text":"كان البريطانيُّون يُعانون مِن \"القواسمِ\" في إمارة الشارقةِ، الذين تأثَّروا بدَعوة الشيخ محمَّد بن عبد الوهَّابِ، وأخَذوا يعمَلون على نشْرِها في سواحل الإماراتِ، وفرْضِ سِيادتِهم على تلك السواحلِ، ولكن الإنجليزَ -وبمُساعدةٍ مِن سُلْطان مسْقطَ- استطاعوا القضاءَ على حَركة القواسمِ وتَدمير أساطيلِهم، وإخضاعِ السواحلِ التابعة لتلك المناطقِ لِلْحمايةِ البريطانية، حتى أقامت قاعدةً عَسكريةً واسعةً في مَشيخة الشارقةِ؛ لتَحلَّ مَحلَّ عَدن كقاعدةٍ أساسية في المنطقةِ، وكانت بِريطانيا تُمارِسُ سياسةً استعمارية واضحةً، ثم أعلَنَت بِريطانيا سنة 1968م أنها ستَنسحِب من الخليجِ العربي عام 1971م، فاجتمَع حاكِمَا أبي ظبي ودُبي، فعَقَدا اتفاقيةَ دُبي في شباط 1968م، نصَّت على تأْسيسِ مجلسٍ أعلى للاتِّحاد ودُستورٍ دائمٍ يَتناوب فيه حُكَّام الإماراتِ على رِئاسته، ثم في 2 ديسمبر 1971م أُعلِنَ رَسميًّا قيامُ دولةِ الإمارات العربيَّة المتحِدةِ مؤلَّفة مِن سِتِّ إماراتٍ، لم تَلبَث أن أصبَحت سبعًا بانضمامِ رأسِ الخيمة إليها في شُباط 1972م، وقد اختِيرَ لرئاسةِ الاتِّحاد الشيخُ زايدُ بن سلطان آل نَهيان، حاكمُ أبي ظبي، بيْنما تسلَّم رِئاسةَ الوزراءِ الشيخُ راشد بن سعيد آل مكتومٍ حاكِمُ دُبي."},{"id":5378,"title":"احتلال إيران الجزر الإماراتية (أبو موسى وطمب الصغرى والكبرى) .","date":["العام الهجري :1391","الشهر القمري : شوال","العام الميلادي :1971"],"text":"في تِشرين الثاني (نوفمبر) 1971 عُقِدت اتِّفاقيةٌ بين إيرانَ وإمارةِ الشارقة، ملَكَت إيرانُ بمُوجِبها عمليًّا جزيرةَ \"أبو موسى\" التي ظلَّت من الناحية الشَّكلية جُزءًا من إمارة الشارقةِ، وحصَلت إيرانُ على حقِّ إقامة قاعدةٍ عسكرية في الجزيرةِ، على أنْ تَدفَع مُقابِلَ ذلك لشيخ الشارقةِ 1.5 مليون جنيه إسترليني سَنويًّا، ويَستمرُّ الدفْع لحين بُلوغ دخْلِ الشيخ من النِّفط 3 ملايين جنيه إسترليني سنويًّا، وقد أخفَقَت مُحاولاتُ إيرانَ لحمْل شيخ رأس الخيمةِ على التخلِّي عن حُقوقه في جزيرتى طمب الكُبرى وطمب الصُّغرى الهامَّتينِ إستراتيجيًّا والواقعتينِ في مَضيق هُرْمز عند مَدخل الخليجِ. وحينما أعلَنَت بِريطانيا في 30 تشرين الثاني (نوفمبر) 1971 أنها لم تَعُدْ تتحمَّل مسؤوليةَ الدِّفاع عن إمارات ساحلِ الصلح البحري، أدخَلَت إيرانُ قواتها إلى هاتينِ الجزيرتينِ، كما هي الحالُ بالنِّسبة لجزيرةِ \"أبو موسى\"، ويبْدو أن طهرانَ ولَندن توصَّلَتا إلى اتِّفاق حيالَ هذه العملياتِ. وانتقامًا مِن بريطانيا لِمُساندتها إيرانَ في احتلال الجُزر، أمَّمت لِيبيا مُمتلكات \"شركة النِّفط البريطانية\"، وسحَبَت ودائعَها من البُنوك البريطانية. واتَّهَم العراقُ بريطانيا بتواطُئِها مع إيرانَ عند احتلالِها للجُزر، فقطَعت العَلاقاتِ الدُّبلوماسيةَ معهما. كما ندَّدت الكويتُ وسوريا باحتلالِ إيرانَ الجُزرَ. وفى الأوَّل من دِيسمبر (كانون الأول) 1971 طالَبَت مصرُ بسحْب القواتِ الإيرانية من الجُزر الثلاث."},{"id":5379,"title":"انقلاب عيدي أمين على رئيس أوغندا ميلتون أوبوتي .","date":["العام الهجري :1391","الشهر القمري : ذي القعدة","العام الميلادي :1972"],"text":"ظهَرت شخصيةُ عيدي أمين كقائدٍ للجيش سنة 1384هـ، وهو ضابطٌ مسلِم تدرَّب في إسرائيلَ، وهو ذو طبيعةٍ استبدادية، تأثَّر بشَخصيَّة عبد الناصر، فقام بانقلابٍ ضدَّ ميلتون أوبوتي، وتسلَّم على إثْره الحكْمَ، وفَرَّ أبوتي إلى تَنزانيا التي رفضَت الاعترافَ بحُكْم عيدي أمين، قام عيدي أمين بعدَّةِ إجراءاتٍ، كان من شأْنِها إثارةُ القوى الصَّليبية والصُّهيونية ضِدَّه؛ فقد قام بطَرْد البَعثة الإسرائيلية مِن أوغندا وسجَن بعضَ أفرادها؛ إذ كانت تَتصرَّف بحُرِّية متناهيةٍ، وقامت إسرائيلُ بعمَلية نوعيةٍ أنقَذَت لها أفرادَ بَعثتها الموقوفينَ في مطار عنتيبي، وقام عيدي أمين بالحدِّ مِن نشاط الإرساليات النَّصرانية، وأعدَم أحد القساوسةِ، واتَّجه لنشْر الدعوة الإسلاميَّةِ، فزاد تَعدادُ المسلمين في أيامه، وأعلَن عيدي أمين انضمامَ أوغندا لمنظَّمة المؤتمر الإسلاميِّ."},{"id":5380,"title":"تنحي يحيى خان عن رئاسة باكستان وتولي ذي الفقار علي بوتو .","date":["العام الهجري :1391","الشهر القمري : ذي القعدة","العام الميلادي :1972"],"text":"بعدَ أنِ انتهَت الحربُ الباكستانية الهِنْدية الثالثة التي لم تَستمِرَّ إلا أسبوعينِ، وانتهَت بهزيمة الجيشِ الباكستاني هَزيمة مُنكَرةً، أُسِر فيها 93 ألفَ جُنديٍّ باكستاني. كما أدَّت إلى انفصال القِسم الشرقيِّ من باكستانَ وقِيام دولة بنغلاديش، فخرَجَت مُظاهراتٌ في باكستانَ تطالِبُ باستمرار الحرْب، وتقديمِ الرئيسِ يحيى خان للمُحاكَمة بسبب تَقصيرِه، فاسْتَدعى الرئيسُ يحيى خان من نيويورك ذا الفقار علي بوتو (الذي كان هناك يَعرض قضيَّة بِلاده على هيئة الأُمَم)، فسلَّمه السُّلطة في 3 من ذي القعدة / 20 ديسمبر؛ ليصبحَ رئيسًا لباكستان، وغادر يحيى خان البلادَ إلى إيرانَ، لكنه لم يَلبَثْ طويلًا فعاد، وبقِيَ تحت الإقامة الجَبْرية في بَيته."},{"id":5381,"title":"منح الدول المصدرة للنفط حق تحديد أسعار النفط  .","date":["العام الهجري :1391","الشهر القمري : ذي الحجة","العام الميلادي :1972"],"text":"وُقِّعت في 14 شباط (فبراير) في طَهرانَ اتِّفاقيةٌ بين البلدان الخليجيةِ الأعضاءِ في \"أوبك\" وشَركات النِّفط، منَحَت عَمَليًّا البلدانَ المصَدِّرة للنِّفط حقَّ الإشراف على الأسعار القياسيةِ، وبهذا يكون أعضاءُ \"أوبك\" قد حقَّقوا الأهدافَ المطروحةَ عام 1960. ولكن ظلَّت مُعلَّقةً مسألةُ مساهمةِ حُكومات البلدان المصدِّرة للنِّفط في ممْتلكات ونشاط الشَّركات، وفي 21 كانون الثاني (يناير) 1972 بدَأت مُفاوضاتٌ بهذا الخصوص بين \"أوبك\" وشركات النِّفطِ."},{"id":5382,"title":"وفاة أديب الحجاز محمد بن سرور الصبان .","date":["العام الهجري :1391","الشهر القمري : ذي الحجة","العام الميلادي :1972"],"text":"وُلِد محمَّدُ بنُ سُرورٍ الصَّبَّانُ عامَ 1316هـ الموافِق 1898م في مدينةِ القُنْفُذةِ بالمَمْلَكةِ العَرَبيَّةِ السُّعوديَّةِ أيَّامَ حُكمِ الأشرافِ، ثمَّ انتَقَل والِدُه بأُسْرَتِه إلى جُدَّةَ عامَ 1320هـ، ثمَّ اتَّجَهوا إلى مَكَّةَ المُكَرَّمةِ واستقَرُّوا بها. وكان زَعيمَ الحرَكةِ الأدَبيَّةِ في الجَزيرةِ العَرَبيَّةِ، ورائِدَ الأُدَباءِ والمثَقَّفينَ في مكَّةَ المُكَرَّمةِ، أَسَّس أوَّلَ مَكتبةٍ لبَيعِ الكُتُبِ في مكَّةَ المُكَرَّمةِ وسَمَّاها (المَكْتَبة الحِجازيَّة)عيَّنه المَلِكُ عَبدُ العزيزِ آلُ سُعودٍ رئيسًا لكُتَّابِ بَلَديَّةِ مَكَّةَ المكَرَّمةِ عامَ 1343هـ، ثمَّ سِكِرْتِيرًا للمَجلِسِ الأهليِّ، وترَقَّى في الوَظائِفِ الحُكوميَّةِ حتَّى عُيِّنَ وَزيرًا للماليَّةِ في عَهدِ المَلِكِ سُعودٍ، وفي عامِ 1382هـ عيَّنه المَلِكُ فَيصَلٌ أمينًا عامًّا لرابِطةِ العالَمِ الإسلاميِّ بمكَّةَ المُكَرَّمةِ.أنشَأَ عَددًا مِنَ الشَّرَكاتِ؛ منها: الشَّرِكةُ العَرَبيَّةُ للطَّبعِ والنَّشْرِ، وشَرِكةُ الفَلاحِ للسَّيَّاراتِ، والشَّرِكةُ العَرَبيَّةُ للصَّادِراتِ، والشَّرِكةُ العَرَبيَّةُ للتَّوفيرِ والاقتِصادِ، وشَرِكةُ مُصحَفِ مَكَّةَ.قام بطباعةِ عَدَدٍ مِنَ الكُتُبِ على نَفَقتِه الخاصَّةِ؛ منها: (الطُّرُقُ الحُكميَّةُ) و (مدارِجُ السَّالِكينَ) كلاهما لابنِ قَيِّمِ الجَوزيَّةِ، (العِقدُ الثَّمين في تاريخِ البَلَدِ الأَمين) و (شِفاءُ الغَرام بأخبارِ البَلَدِ الحرام) كِلاهما للفاسيِّ، (مُختارُ الصِّحاحِ لأبي بكرٍ الرَّازي)، (تفسيرُ معاني كَلِماتِ القُرآنِ لمحمَّد حَسَنين مخلوف)، وغَيرُها مِنَ الكُتُبِ.تُوُفِّيَ رَحِمه اللهُ في القاهِرةِ، ونُقِل جُثمانُه إلى مكَّةَ المُكَرَّمةِ، وصُلِّيَ عليه بالمَسجِدِ الحرامِ، ودُفِنَ في مَقبَرةِ المُعَلَّاةِ."},{"id":5383,"title":"اتفاقية سيملا بين باكستان والهند .","date":["العام الهجري :1392","الشهر القمري : جمادى الأولى","العام الميلادي :1972"],"text":"بعدَ أنْ وضَعَت الحربُ الثالثةُ أوزارها بين الدولتينِ: الهند وباكِستان، وفي 17 جُمادى الأولى / 28 حُزيران، بدَأت محادثاتُ القِمة بين الرئيسِ الباكستاني ذي الفقار علي بوتو، ورئيسةِ وُزراء الهندِ أنديرا غاندي في مدينة سيملا الهِنديةِ، وذلك في مُحاولةٍ للتوصُّل إلى تَسوية المشكِلات المعلَّقة والناجمةِ عن حَرْب شوَّال 1391هـ / ديسمبر 1971م، وعن تَقسيمِ باكستانَ، وانفصال الجَناح الشَّرقي، وقِيام دَولة بنغلادش فيه، وتمَّ الاتفاق على: استعادة باكستانَ كلَّ الأقاليمِ التي فقدَتْها في الحرب، باستثناءِ التي تقَعُ في كشمير، انسحاب القُوَّات الهِنْدية إلى مَوقعها قبل الحرْب، إعادة باكستانَ الأراضي التي احتلَّتْها في قِطاع البنجابِ للهند، إعادة التواصُل بين الدولتينِ والتعاوُن الاقتصاديِّ والتِّجاري."},{"id":5384,"title":"محاولة اغتيال الملك الحسن الثاني ملك المغرب .","date":["العام الهجري :1392","الشهر القمري : رجب","العام الميلادي :1972"],"text":"في سنةِ 1391هـ وقعَت مُحاولةٌ لاغتيالِ الملِك الحسن الثاني في القصْر، وهو في حَفلة عِيد ميلادِه الـ(42)، ولكنها فشَلت، وفي 7 رجب / 16 آب من هذا العامِ عندما كان الملك عائدًا من فرنسا على متْن طائرةٍ، وقعَت مُحاولةٌ ثانية لاغتيالِه بتَدْبيرٍ من اللِّواء محمَّد أوفقير؛ حيث انطلَقَت 6 طائراتٍ هُجومية مِن قاعدة القُنَيطرة المغربيةِ، وبدَأت بضَرْبِ طائرة الملِك، ونَفِدت ذَخائرُ طائرتينِ، وأما طائرةُ قائد الهجومِ فقد اختَلَّ مَدْفَعه فاضطرَّ للهبوطِ المِظَلِّي بنفْسِه، وقد قُبِضَ عليه هو واللِّواء كويرة، واستطاعت طائرةُ الملِكِ أنْ تَهبِطَ سالمةً في مطار سلا بالرِّباط، على الرَّغم مِن تعرُّضها لإصاباتٍ خطيرة، ولمَّا عَلِم المتمرِّدون بنَجاةِ الملِك هاجموا المطارَ لمدَّة ساعةٍ، وهاجموا القصْر الملكيِّ، لكنهم فَشَلوا أيضًا في اغتيالِه، وقُبِض على المتمرِّدين، وعُرِف أن قائِدَهم هو اللِّواء محمَّد أوفقير الذي أنقَذ الملِكَ من الاغتيالِ في السَّنة الماضية، وقد تمَّ قتل أوفقير بخمْسِ رُصاصاتٍ في مساءِ يوم مُحاوَلةِ الاغتيال في القصْر الملكي."},{"id":5385,"title":"الرئيس الصومالي محمد سياد بري يعلن تطبيق الاشتراكية في الصومال .","date":["العام الهجري :1392","الشهر القمري : رجب","العام الميلادي :1972"],"text":"لمَّا تولَّى محمَّد سياد بري رئاسةَ الصُّومال عام 1390هـ بعد انقلابٍ عَسْكري، أعلَن أنَّ الصُّومال دَولةَ اشتراكيةٌ، وفي هذا العامِ قام بري بتَنْفيذ حملةِ قتل، فتوجَّه نحوَ العُلَماء والتنظيماتِ الإسلاميَّة، وقد أذاع الرئيسُ محمَّد سياد بري بَدْء تَطبيق الاشتراكيةِ في الصُّومال، والتي أسَّسها كارل ماركِس، وطبَّقها لينين، وفي رَمضان / تشرين الأول، وفي يومِ الذِّكرى الثالثة للثَّورة؛ أعلَن بري إلغاءَ اللُّغة العربيَّةِ، واستخدامَ الحُروف اللاتينيةِ."},{"id":5386,"title":"محاولة انقلاب ضد السلطان قابوس .","date":["العام الهجري :1392","الشهر القمري : ذي القعدة","العام الميلادي :1972"],"text":"بعدَ الهزائم التي مُنِيت بها \"الجبْهة الشَّعبية\" في ثَورة ظَفار، توجَّهت إلى التخطيطِ للقيامِ بانقلابٍ ضدَّ السُّلطان قابوس ونِظام حُكْمِه في السَّلْطنة، وقد تمَّ التخطيطُ للانقلابِ في العراقِ في أكتوبر 1972م عن طَريق بعض العناصرِ التي أوفَدَتْها الجبهةُ إلى هناك، بالإضافة إلى بَعض أعضاءِ المكتبِ السِّياسي في اليَمَنِ الجنوبيِّ، وقد تمَّ تحديدُ موعدِ الانقلابِ في 31 ديسمبر 1972م. غيرَ أنَّ هذه المحاولةَ انتهَت بالفشَلِ الذَّريع، وتمَّ القبْض على العديدِ من عناصرِ الجبْهة، وقد قامت السَّلْطَنة إثرَ هذه المحاولة الانقلابيةِ بَحَركة اعتقالاتٍ شمِلَت عشراتِ المُنْتَمين للجبْهة، قُدِّموا للمحاكمة وصدَرت أحكامُ القتل على 10 منهم، بينما صدَرت أحكامٌ بالسَّجْن المؤبَّد أو لِمُدَد مختلفةٍ بالنِّسبة لبقيَّة المتَّهمينَ."},{"id":5387,"title":"ليبيا تحتل شريط أوزو في تشاد .","date":["العام الهجري :1393","العام الميلادي :1973"],"text":"قامت لِيبيا باحتلالِ شَريط أوزو في شمالي تشادَ، وادَّعت لِيبيا أنها لم تَقُمْ بذلك إلا بناءً على الاتفاقية التي جَرَت بين فرنسا وإيطاليا عام 1362هـ / 1943م، واستقرَّت قوةٌ لِيبية في تشادَ، قوامُها خمسةَ عشَرَ ألفَ جُنديٍّ، ثم قدَّمت اقتراحاتٍ لقيامِ وَحدةٍ بين لِيبيا وتشادَ، لكنها لم تَنجَح؛  فسحَبَت ليبيا قُواتها في مَطلع عام 1402هـ، ووُضِعَت محلَّها قواتُ حِفظ السلامِ الدوليةِ."},{"id":5388,"title":"فخري ثابت كورتورك رئيسًا لتركيا بعد جودت صوناي .","date":["العام الهجري :1393","الشهر القمري : ربيع الأول","العام الميلادي :1973"],"text":"انتهَت مُدَّة الرئيسِ جودت صوناي في الحكْم، وحدَثَت أزمةٌ في انتخابِ رئيس جديدٍ؛ إذ رشَّح الجيشُ فخري ثابت تورتورك رئيس الأركانِ التُّركي، فاستقال مِن منْصبِه ليَدخُل في مجلِس الشيوخ؛ لأنَّ الرئيسَ يجِب أنْ يكون عضوًا في هذا المجلسِ، ورشَّح حِزْب العدالةِ (المؤسَّس أصْلًا على أنقاض الحِزْب الديمقراطي) تاكين أريبون، وخُشِي مِن وُقوع صِدامٍ مع العسكريين؛ لذا بحَثَ الساسةُ إمكانيةَ تَمديد فترة الرئاسةِ لجودت صوناي مدَّة سنتينِ، ولكنَّ الانتخاب قد تمَّ، وأُعطِيت الرِّئاسة لفخري كورتورك، وهو عديلُ الرَّئيس جودت؛ فزَوجتاهما شَقيقتانِ."},{"id":5389,"title":"محمد داود يترأس أفغانستان بعد انقلاب عسكري ضد الشاه محمد .","date":["العام الهجري :1393","الشهر القمري : جمادى الآخرة","العام الميلادي :1973"],"text":"كان محمَّد داود (وهو ابنُ عمِّ الشاه محمَّد ظاهر، وزَوج شقيقتِه) قد أصبَح رئيسًا للوزراءِ في أفغانستانَ، إضافةً إلى احتفاظِه بوزارتيِ الدَّاخلية والدِّفاع، وكان يَمِيل إلى الرُّوس؛ حيث تعامَل معهم وعقَد معهم معاهداتٍ مِن تسليحٍ وغيرِه، ولمَّا عرَف الشاهُ مُيولَه وأطماعَه نحَّاه عن منْصبِه، وهذا ما ولَّد النِّقمةَ عنده، ثم إنَّ الرُّوس وأعوانَهم لمَّا رأَوُا ازديادَ النَّشاط الإسلاميِّ ونُموَّه بشكلٍ ملحوظٍ جدًّا في ظِلِّ الشاه، خافوا ذلك، فأيَّدوا محمَّد داود ووَعَدوه بالنُّصرة، وهو رَبيبُهم والمقرَّبُ لَدَيهم، فقام في صباح الثلاثاء 17 جمادى الآخرة / 17 تموز بانقلابٍ عسكريٍّ ناجحٍ، وإن لقِيَ مُقاومةً عنيفة، وأعلَنَ أنَّ الذي دفَعَه للانقلابِ كثرةُ الفساد في الإدارةِ، وسُوء استخدام السُّلطة، وتفشِّي الرِّشوة، ثم قام بإلغاء النِّظام الملكِي وأعلَن النِّظام الجُمهوري، ونصَّب نفْسَه رئيسًا للجُمهورية الأفغانيةِ."},{"id":5390,"title":"وفاة الطاهر بن عاشور .","date":["العام الهجري :1393","الشهر القمري : رجب","العام الميلادي :1973"],"text":"هو الشيخُ محمَّد الطاهر بنُ محمَّد بنِ محمَّد الطاهر بن عاشورٍ، الشَّهير بالطاهرِ بنِ عاشورٍ، أحدُ الأعلامِ المشهورين والمفسِّرين المعروفين، وكان أديبًا خطيبًا، ومِن طلائع النَّهضة الحديثةِ النابهينَ في تُونس. كانت حياتُه -التي زادت على 90 عامًا- جهادًا في طلَبِ العِلم، أحدَثَت آراؤه نَهضةً في عُلوم الشريعة والتفسيرِ، والتربيةِ والتعليمِ، والإصلاح. وُلِدَ بتُونسَ سنةَ 1296هـ في أُسرةٍ عِلْمية عريقةٍ، تَمتدُّ أُصولها إلى بلادِ الأندلسِ. حفِظَ القرآنَ الكريمَ، وتعلَّم اللُّغة الفرنسيةَ، والْتَحق بجامعِ الزَّيتونةِ سنة 1310هـ وهو في الرابعة عشرة مِن عُمره، ولم تَمْضِ سنواتٌ قليلةٌ حتى عُيِّن مدرِّسًا من الطَّبقة الأُولى بعد اجتيازِ اختبارِها سنةَ 1324هـ. واختِيرَ للتَّدريسِ في المدرسة الصادقيةِ، وكان لهذه التَّجرِبة المبكِّرة في التدريسِ بين الزَّيتونة -ذات المنْهج التَّقليدي- والصادقيةِ -ذات التعليمِ العصْري المتطوِّر- أثَرُها في حياتِه، ثم اختِيرَ شيخًا لجامع الزَّيتونة في 1351هـ، وحاز الطاهرُ بن عاشور على لقبِ \"شيخُ الإسلامِ المالكيُّ\"؛ فكان أولَ شُيوخ الزَّيتونة الذين جَمَعوا بين هذينِ المنصبينِ، ولكنه لم يَلبْثَ أن استقالَ مِن المشيخة بعدَ سَنةٍ ونصفٍ؛ بسَبب العراقيلِ التي وُضِعت أمام خُطَطِه لإصلاحِ الزَّيتونة، وأُعِيدَ تعيينُه سنة 1364هـ، وفي هذه المرَّة أدخَل إصلاحاتٍ كبيرةً في نِظام التعليم الزَّيتوني، فارتفَع عددُ الطُّلاب الزَّيتونيين، وزادت عددُ المعاهدِ التَّعليمية. ولَدى استقلالِ تُونس أُسندت إليه رئاسةُ الجامعةِ الزيتونية سنةَ 1374هـ، وقد أحدَثَت آراؤه نَهضةً في عُلوم الشريعةِ والتفسيرِ، والتربيةِ والتعليمِ، والإصلاحِ، وكان لها أثَرُها البالغُ في استمرار جامعةِ الزَّيتونة في العطاء والرِّيادةِ، وكان ابنُ عاشور دَؤوبًا على مُكافَحةِ الاستعمار الذي كان يُسمَّى بالحمايةِ، وألْقى محاضراتٍ في جامعة السُّوربون بفرنسا، وجامعةِ إستانبول في تركيا، وجامعة عليكره في الهندِ. وشارَك في نَدوات علميةٍ كثيرة، وفي بعضِ مُؤتمرات المستشرقينَ، وكان عضوًا في المجمَع اللُّغوي بالقاهرةِ، ورابطةِ العالم الإسلامي بمكَّة. ومِن مُؤلَّفاته: كتاب تَفسير القُرآن المسمَّى بـ ((التَّحرير والتنوير)) الذي احتوى على خُلاصة آرائهِ الاجتهادية والتَّجديدية، وله كِتاب ((مَقاصِد الشريعة)). ومن المواقِف المشهورةِ للطاهرِ بنِ عاشورٍ رفْضُه القاطعُ استصدارَ فَتوى تُبِيحُ الفِطرَ في رمضانَ، وكان ذلك عام 1381هـ عندما دعا الحَبيب بُورقيبة الرئيسُ التُّونسي آنذاكَ العُمَّال إلى الفِطر في رمضانَ بدَعوى زِيادة الإنتاج، وطلَب من الشيخِ أنْ يُفتِيَ في الإذاعة بما يُوافِقُ هذا، لكن الشيخَ صرَّح في الإذاعةِ بما يُريده اللهُ تعالى، بعد أن قرَأ آية الصِّيام، وقال بعدها: \"صدَق اللهُ، وكذَبَ بُورقيبة\"، تُوفِّي الطاهر بنُ عاشورٍ رحمه الله في 13رجب 1393 هـ."},{"id":5391,"title":"الحرب العربية الإسرائيلية الرابعة (أكتوبر 1973م) .","date":["العام الهجري :1393","الشهر القمري : رمضان","العام الميلادي :1973"],"text":"بعْدَ نَكبة 1948م، والعُدوان الثُّلاثي في 1956م، ونَكسة حُزَيران في 1967م؛ وفي 6 أكتوبر من عام من عام 1973، 10 رمضان 1393هـ اجتازتِ القواتُ المصريةُ قَناة السويسِ، وانتقَلت إلى الضفةِ الشرقيةِ واقتَحَمت خطَّ بارليف الذي أقامه اليهودُ على حُدود شِبه جزيرة سَيناء الغربية، والذي حصَّنوه جيدًا، ووَضَعوا أمامه تلًّا تُرابيًّا؛ لِيَحميَ تَحرُّكَهم عن أعيُنِ المصريين، ولكن لم يُتابِع الجيشُ المصري تقدُّمَه في سَيناء لتَحريرِها، ولم يتَّجِه للمضائقِ ليَغلِقَها بوجْهِ اليهودِ! بل أخَذ مواقعَ دِفاعيةً على بُعد عشَرة كيلو مترات مِن شاطئ القناة الشَّرقي داخلَ سَيناء، فنقَلت إسرائيلُ قوَّاتها من الجبهةِ المصرية إلى الجبهةِ السُّورية بكلِّ ثِقَلِها، واستطاع الإسرائيليونَ أن يُكبِّدوا الجبهةَ السورية خسائرَ كبيرةً، ثم في 20 رمضان عَبَرت عدَّةُ دباباتٍ يهوديةٍ قناةَ السويس في مَنْطقة الدفرسوار وفتَحَت ثغرةً في القواتِ المصرية، ثم انتشَرَت على طُول القناة على الضفَّة الغربيةِ، وحاصَرَت مُدُن القناةِ، وحجَزت القواتِ المصريةَ في سَيناء، ثم تقدَّم وَزيرُ خارجية أمريكا كِسينجر بمُبادرةٍ لوقْفِ إطلاق النارِ في 14 شوال / 9 تشرين الثاني، فتمَّت الموافَقةُ على فضِّ الاشتباكِ بين مصرَ وإسرائيلَ في 24 ذي الحجة / 17 كانون الثاني 1974م، أما سُوريا فقد تمَّت الموافقةُ منها على فضِّ الاشتباكِ بعدَ ستَّة أشهرٍ من مُوافَقةِ مصرَ."},{"id":5392,"title":"سلاح النفط والضغط على الولايات المتحدة في حرب 6 أكتوبر .","date":["العام الهجري :1393","الشهر القمري : رمضان","العام الميلادي :1973"],"text":"دعَت السُّعودية واشنطن إلى الضَّغط على إسرائيلَ وحمْلِها على تنْفيذ قرارِ مجلِس الأمْن رقم (242) الصادرِ في 22 تشرين الثاني (نوفمبر) عام 1967، الذي يَقضي بالانسحابِ من جميع الأراضي العربيَّة المحتلَّة في حُزيران (يونيو) 1967، وإلَّا فإنَّ الولاياتِ المتحِدةَ سوف تُواجِه عقَبات تَقليص تَصديرِ النِّفط. لم تأخُذْ الولاياتُ المتحِدةُ وأوربَّا الغربية هذه التَّحذيراتِ على مَحملِ الجِدِّ، فألْمحتِ السُّعودية في صَيف 1973 إلى أنها ستُؤيِّد مصرَ عند نُشوب حربٍ جديدةٍ مع إسرائيلَ. بدأت الحربُ في 6 أكتوبر، وفي 7 أكتوبر -أي في اليوم الثاني للحرْبِ- أرسَل وزير الخارجيةِ الأمريكي كِيسنجر برقيةً إلى الملِك فَيصل يَدعوه فيها إلى إقناعِ مصرَ وسوريا بوَقْف العملياتِ الحربيةِ، وردَّ الملِكُ فَيصل بأنه يُؤيِّد مصرَ وسوريا تأييدًا تامًّا، ودَعا واشنطن إلى بَذْل الجهودِ لحمْلِ إسرائيلَ على الانسحاب مِن الأراضي التي تَحتلُّها. عقَدَ وُزراءُ النِّفط في عشْرة بُلدان عربيةٍ اجتماعًا في 17 أكتوبر، اتُّخِذ فيه قرارٌ بتَقليصِ استخراج النِّفط بنِسبة لا تقلُّ عن 5 % شهريًّا، حتى تتمَّ تَسوية النِّزاع في الشرْق الأوسط. وفي الواقع قلَّصت السُّعودية والكويتُ الإنتاجَ بنِسبة 10 % دفعةً واحدةً، ولمَّا أقامت الولاياتُ المتحِدةُ \"جسرًا جويًّا\" لتزويدِ إسرائيلَ بالسلاحِ، عمَدَت السُّعودية وسائرُ البُلدان العربيَّة إلى اتِّخاذ إجراءاتٍ تباعًا، وذلك بوَقْفِ ضَخِّ النِّفط إلى الولايات المتحِدةِ، ومِن ثَم إلى هُولندا التي اتَّخذت مَوقفًا مواليًا لإسرائيلَ، كما فُرِضَ الحظْرُ على تَصديرِ النِّفط الخامِّ لمعاملِ التَّكريرِ التي تُصدِّر مُشتقَّات النِّفط إلى الولايات المتحِدة، أو تَبيعها إلى الأسطولِ البَحريِّ الأمريكي. وعلاوةً على فرْض الحظْرِ قام العراقُ بتَأميم حِصَّة الولايات المتحِدة وهُولندا في \"شركة نِفط البصرة\". فجاء ردُّ فِعل دُولِ أوربَّا الغربية دون إبطاءٍ؛ ففي صباح 6 تشرين الثاني (نوفمبر) دعَت حُكومات البُلدان \"التسعة\" إلى تَنفيذ قَرارات مجلِس الأمْن حول العمليات الحربيةِ، وكذلك القرار رقم (242) بكلِّ بُنوده، بما في ذلك الجلاءُ عن الأراضي العربيَّة المحتلَّة عام 1967. وفي مَطلع ديسمبر (كانون الأول) 1973 قرَّر أعضاءُ منظَّمة البلدان العربيَّة المصدِّرة للنِّفط (أوبك التي أُسِّست عام 1968) المجتمِعون في الكويت إلغاءَ القرار القاضي بتَقليص استخراجِ النِّفط بنِسبة 5% في شهر ديسمبر (كانون الأول). وعزوا القرارَ إلى الرَّغبة في تحسينِ أوضاع البلدان الأعضاءِ في الجماعة الاقتصاديةِ الأوروبية التي اتَّخَذت موقفًا وُديًّا حيالَ العرَب. كما أشار البلاغُ الصادرُ عن اجتماع الكويتِ إلى أن الدُّول الإفريقية والإسلاميَّة سوف تَحصُل على النِّفط وَفق العقود المتَّفَق عليها. واستمرَّ لمدةٍ من الوقت حظْرُ تَصدير النِّفط إلى الولايات المتحِدة وهُولندا."},{"id":5393,"title":"وفاة الدكتور طه حسين .","date":["العام الهجري :1393","الشهر القمري : رمضان","العام الميلادي :1973"],"text":"هو الدُّكتور طه بن حسين بنِ عليِّ بن سلامةَ. وُلِد سنةَ 1889م في قرية (الكيلو) بمَغاغةَ مِن مُحافَظة المِنْيا (بالصعيد المصْري)، وأُصِيب بالجُدريِّ في الثالثة مِن عُمرِه، فكُفَّ بصَرُه. وكان السابعَ من إخوته وأخواتِه الذين بلَغَ عَددُهم (13)، وكان والدُه ذا مركزٍ مَرموقٍ في الضاحيةِ، حرَصَ على تَعليمِ أولادِه؛ وحرَص أنْ يُعلِّم ابنَه طه، فأدْخَله الكُتَّاب، وحفِظ فيه القرآنَ الكريمَ، وحفِظَ الكثير مما كان يَسمَع مِن أدعيةٍ وأشعارٍ وقصصٍ، وحفِظَ قواعدَ التَّجْويد، وحين تَرعرعَ راح أخوه الأزهريُّ يُحفِّظه الألفيَّةَ؛ لِيَعُدَّه للحياة الجديدةِ في الأزهر. دخَل الأزهرَ عام 1902، وتفتَّح ذِهْنُه، واتَّسعَت آفاقُ تَفكيرِه حين بَدأ يَحضُر دُروس الأدبِ على يَدِ سيد علي المَرْصفيِّ، والأستاذُ ينْحو في دُروسِه مَنْحى اللُّغويين والنُّقاد، مع مَيلٍ لِلتَّفقُّهِ والتحليلِ، ويُعنى بمُفردات اللُّغة، وإظهارِ ما في الشِّعرٍ من بَيانٍ وبديعٍ ومَعانٍ. وظهَرَت لَدَيه مَلَكة النَّقْد، وكان عامُ 1908 عامًا فاصلًا بينه وبين حياةِ الأزهرِ وشُيوخ الأزهرِ؛ ففي هذا العامِ فُتِحَت الجامعةُ المصريَّةُ الأهلية، فانْتَمى إليها وقَضى فيها سنواتٍ ثلاثًا يَختلِفُ إليها وإلى الأزهرِ. وقد وجَدَ في دُروس الجامعةِ اختلافًا كثيرًا ووجَدَ حُرِّيةَ البحثِ، فشُغِف بهذه الدُّروسِ حُبًّا، وتفتَّحَت لها نفْسُه، وكان أثَرُ ذلك عميقًا فيها، ووجَدَ في الجامعةِ مُبتغاهُ، وفي ظِلِّ البحثِ التَّحليليِّ أخْرَج رِسالتَه عن أبي العَلاءِ المَعرِّي ((ذِكرى أبي العَلاء)) التي نال بها دَرجةَ الدُّكتوراه، وهو أوَّلُ مَن نال شَهادةَ الدُّكتوراه من الجامعةِ المصرية عام 1914م، فلما وُزِّعت مَطبوعةً ثارت حَولها ضجَّةٌ، ورُمِيَ بالإلحاد، وقَدَّمَ أحدُ النُّواب إلى الجمعية العامَّةِ استجوابًا أثار به مَوضوعَ رِسالة طه حُسين، وطالَب بفَصْلِه ونزْعِ الشَّهادة عنه، ولولا تَداركُه مِن رئيس المجلِسِ (سعد زغلول) لَتغيَّر مجْرى حَياتِه. وفي 5 مارس 1914 سافَر على نَفقةِ الجامعةِ إلى فرنسا لِيُكمِل دِراستَه، فكان ذلك حَدَثًا لم يَتيسَّر لغَيرِه من أمثالِه. وفي جامعةِ مونبيليه التي يُدرَّس فيها الأدبُ الفرنسيُّ واللُّغةُ اللاتينيةُ، تعرَّف على سُوزان التي كانت زَميلتَه في الجامعة أثناءَ بَعثتِه إلى فرنسا، وقد كانت سُوزان تَقرأُ عليه كُتبًا من عُيون الأدبِ الفرنسيِّ والتاريخِ الرُّوماني واليونانيِّ. واقترَنَ بها يومَ 19 أغسطس 1919 م، فكان لِسُوزانَ الأثرُ الأكبر في توجُّهاته القادمةِ. تزوَّج بها طه وهو يَستعِدُّ للدُّكتوراه برسالةٍ عن \"ابن خَلْدون\" وفَلسفتِه الاجتماعيةِ، وفي السَّنة التي تزوَّج فيها بسُوزانَ عاد إلى مصرَ، وتمَّ تعيينُه أستاذًا للتاريخ القديمِ. وفي عام 1925 أُلحِقَت الجامعةُ بالحكومةِ، فتمَّ تَعيينُه أستاذًا دائمًا للأدبِ العربيِّ بكُلِّية الآدابِ، ثم عَميدًا لهذه الكُلِّية، فوَزيرًا للمعارِفِ، وفي هذه المدَّةِ تمكَّن طه مِن جعْلِ التعليمِ الثانوي والفنِّي مجانًا، وعيَّنته جامعةُ الدُّول العربيَّةِ رئيسًا لِلَجْنتِها الثقافية فأدارها مدَّةً. كان طه حُسين خلالَ هذه الفترة جمَّ النَّشاطِ؛ يَكتُب ويُحاضِر، ويَنشُر ويُؤلِّف حتى ذاع صِيتُه. وأخرَجَ مُحاضراته (في الظَّاهرة الدِّينية عند اليونان) في كِتابٍ عام 1919 يَحمِل اسمَ \"آلهة اليونانِ\". وفي 1926 نُشِر كِتابُه \"الشِّعر الجاهِلي\"، فأثار ظُهورُه ثورةً عاصفةً كادت تَعصِفُ بطه حُسين وكُرسِيِّه وأدَبِه، وانبَرَت أقلامُ الأدباء والمؤرِّخين وعُلماء المسلمين يَرُدُّون عليه، وأُحِيل طه حُسين سنةَ 1926 إلى النِّيابة وحَقَّقت معه، وانتهَت مِن قَرارِها سنة 1927. وكان قرارُها بتَفْنيدِ انحرافاتِ طه حُسين الفِكْرية في كِتابِه، وتَفنيدِ ما أخَذَه من المستَشْرقينَ أمْثال رِينان، ومَرْغليوث، وغَيرِهما، وصُودِرَ كتابُه وجُمِع من الأسواقِ. وقد حصَل على الدُّكتوراه الفَخْرية من جامعةِ مَدريد وجامعة كمَبِردج، ونال وِسامَ الباشويةِ ووِسامَ الليجيون دونير مو طَبقة كراند أوفيسيه، ونال الدُّكتوراه الفَخْريةَ من جامعاتِ ليون، ومونبيليه، ومَدْريد، وأكْسُفورد، وانتُخِبَ رئيسًا للمَجْمَع اللُّغوي بعدَ وَفاةِ أحمد لُطفي السَّيِّد سنة 1963. وكان مُشتغِلًا بالترجمةِ كثيرًا. أنْجَبَت سُوزانُ لِطه: أمينةَ، ومُؤنس الذي اعتنَقَ النَّصرانيةَ وأعْلَنها في إحدى الكنائسِ بفرنسا! وتُوفِّي طه حُسين عام 1973م."},{"id":5394,"title":"دعم إيران لسلطان عُمان لمواجهة حركة التحرير في ظفار .","date":["العام الهجري :1393","الشهر القمري : ذي القعدة","العام الميلادي :1973"],"text":"قام السُّلطان قابوس في شَهر أكتوبر عامَ 1971م بزيارةٍ رسميةٍ إلى إيرانَ؛ للمُشارَكة في الاحتفالات التي أقامها الشاهُ محمَّد رضا بَهلوي بمُناسبة عرْشِ الطاوسِ في بلادِ فارسَ، فطلَب السُّلطان قابوس مِن شاه إيرانَ مُساعدتَه في مُواجهة ثوارِ ظَفار، فأبدى الشاهُ استِعدادَه والوقوفِ إلى جانبِ قوَّات السُّلطان في حَرْبها ضِدَّ الثُّوار، وكان مِن أهمِّ الدوافعِ التي دفَعَت الشاهَ الإيرانيَّ للدعْمِ هو طُموحُه في أنْ يَحلَّ محلَّ بِريطانيا كحامٍ للمنطقةِ بعْدَ انسحابِها منها عام 1971م، وخشْيتُه مِن تعرُّضِ مَضيقِ هُرْمزَ للخطَر في حالة نَجاحِ الثَّورة في إقامة نِظامٍ مُعادٍ للأنظمة الملَكَيةِ في عُمانَ، وما قد يؤدِّي إليه ذلك من تَهديدٍ لأمْن الخليجِ وتِجارة النِّفط، وفي يوليو 1972م أرسَل السُّلطان قابوس وفْدًا رسميًّا إلى إيرانَ برِئاسة ثويني بنِ شهاب، وتمَّ التوصُّلُ إلى وضْع اتِّفاقية التدخُّل العَسْكري الإيراني في السَّلْطنةِ مُستقبَلًا عند الطَّلَب لِلقضاء على الثَّورة المسلَّحةِ. وفي 30 نوفمبر 1973م وصَلَت إلى السَّلْطَنة أُولى طلائعِ القوَّاتِ الإيرانيةِ التي بلَغَت ما يُقدَّرُ بثلاثةِ آلافٍ عَسكريٍّ إيرانيٍّ، و كان للمساعدةُ الإيرانيةُ أثر كبير في قمْعِ ثَورة ظَفار."},{"id":5395,"title":"وفاة ديفيد بن غوريون أول رئيس وزراء للاحتلال الصهيوني .","date":["العام الهجري :1393","الشهر القمري : ذي القعدة","العام الميلادي :1973"],"text":"وُلِد في مَدينة \"بلونسك\" البُولنديَّة، ولِتَحمُّسِه للصُّهيونيةِ هاجَر إلى فِلَسطين في 1906. امتهَنَ ابن غُوريون الصحافةَ في بِداية حياته العَمَلية، وبدَأ باستعمالِ الاسمِ اليهودي \"ابن غُوريون\" عندما مارَس حياتَه السِّياسيةَ. وهو أوَّلُ مَن تقلَّد مَنصِب رئيس وُزراءٍ لإسرائيلَ مِن سنةِ 1948م حتى سنة 1953م، وتقلَّد المنصبَ مدَّةً أُخرى بدَأت في 1955م، وانتهَت في 1963م، وعندما تولَّى منْصبَ رئيسَ الوزراءِ أمَر بتَشكيل \"جَيش الدِّفاع الإسرائيلي\" مِن عناصر عِصابةِ \"الهاجاناه\"، وهي عصابةٌ صُهيونية. أسَّسه ابنُ غوريون في مَدينة القُدس كرَدِّ فِعلٍ للثَّورة التي اندلَعَت في فِلَسطين من العام 1920م. كان ابن غُوريون مِن طلائع الحرَكةِ العُمَّالية الصُّهيونيةِ في مَرْحلة تأْسيس الكيانِ الصُّهيوني \"إسرائيل\". وهو الذي قاد إسرائيلَ في حرْب 1948 التي يُطلِق عليها الإسرائيليُّون \"حرْب الاستقلالِ\". وقد استقالَ مِن رِئاسة الوزراءِ عام 1963م مُعلِنًا رغبتَه في التفرُّغ للدِّراسة والكتابةِ، لكنه ظلَّ مُحتفِظًا بمَقعدِه في الكِنيست، غيرَ أنه لم يُخلِدْ تمامًا لهذا النَّمَط الجديدِ من الحياةِ، فأسَّس عام 1965م حِزبًا مُعارِضًا أسماه (رافي)، ويُعَدُّ ابنُ غوريون من المؤسِّسين لحزْبِ العَمَل الإسرائيلي، والذي تبوَّأ رئاسةَ الوزراءِ الإسرائيليَّة لمدَّة 30 عامًا منذُ تأْسيس الكيانِ الصُّهيوني \"إسرائيل\". وهلك ابن غُوريون عن عُمرٍ ناهَزَ 87 عامًا."},{"id":5396,"title":"مؤتمر القمة العربية السادس (قمة الجزائر) .","date":["العام الهجري :1393","الشهر القمري : ذي القعدة","العام الميلادي :1973"],"text":"ما إنْ أُعلِنَ وقفُ إطلاق النارِ في حرْب 6 أكتوبر / تشْرين الأول بقَرارِ رقم 338 مِن الأُمَم المتحِدة في 22 أكتوبر، حتى تمَّ عقْدُ قِمَّة عربيةٍ في الجزائرِ من 26 - 28 تشْرين الثاني، وحضَرَتْه 16 دولةً عربية بمُبادرةٍ من سُوريا ومصرَ، وقاطعَتْه العراقُ ولِيبيا، وكانت القضيةُ الرئيسةُ التي تمَّ طرْحُها في القمةِ هي: \"الصُّلح مع إسرائيلَ\" بشروط؛ حيث صَدَر عن المؤتمر بَيانٌ خِتاميٌّ ومجموعةٌ من القراراتِ؛ أهمُّها:- إقرارُ شَرْطينِ للسلام مع إسرائيلَ:الأوَّل: انسحابُ إسرائيلَ من جميعِ الأراضي العربيَّة المحتلَّة، وفي مُقدِّمتها القدسُ.والثاني: استعادةُ الشعْب الفِلَسطيني حُقوقَه الوطنيةَ الثابتة.ومن القرارات: تَقديم جميعِ أنواع الدَّعْم المالي والعسْكري لِلجبهتينِ السُّورية والمصريةِ؛ مِن أجْل استمرار نِضالِهما ضدَّ العدُوِّ الصُّهيوني. استمرارُ استخدامِ سلاحِ النِّفط العَرَبي ورفْعُ حظْرِ تَصدير النِّفط للدُّول التي تَلتزِم بتأْييدها القضيةَ العربيَّة العادلةَ. وتَوجيه تَحيةِ تَقديرٍ للدُّول الإفريقيةِ التي اتَّخذت قراراتٍ بقطْعِ عَلاقاتها مع إسرائيلَ."},{"id":5397,"title":"شيخ مجيب الرحمن يتولى رئاسة بنغلاديش .","date":["العام الهجري :1393","الشهر القمري : ذي الحجة","العام الميلادي :1974"],"text":"كان شيخُ مُجيب الرحمن قد قام مع حِزْبه بالتأليبِ للانفصالِ عن باكستانَ وقِيام دولةٍ مُستقِلة، وهذا ما تمَّ بالفِعل عامَ 1391هـ، وكان قد اعتُقِل مُجيب ثم أُطلِقَ سراحُه، وعاد إلى دكا عاصمةِ بنغَلاديشَ، ثم في 22 ذي الحجةِ 1393هـ / 15 كانون الثاني 1974م انتُخِب مُجيب الرحمنِ رئيسًا لِلجُمهورية، أو نصَّب نفْسَه، ويُعَدُّ الثالثَ مِن رُؤساء دَولةِ بنْغلاديش بعد نصْرِ الإسلامِ وأبي سَعيد شودري اللذينِ كانا مجرَّدَ صورةٍ، بيْنما السُّلطة الحقيقية كانت بيَدِ مُجيب الرحمنِ، ثم أطلَقَ مُجيب الرحمنِ على نفْسِه لَقَب البانجاباندهو -أي: أبو الأُمَّة- واستبدَّ بالحكْمِ."},{"id":5398,"title":"وفاة الشيخ العلامة محمد الأمين الشنقيطي صاحب تفسير (أضواء البيان) .","date":["العام الهجري :1393","الشهر القمري : ذي الحجة","العام الميلادي :1974"],"text":"هو الشَّيخ العلَّامةُ محمَّدُ الأمين بنُ محمَّد المختارِ بنِ عبد القادر الشِّنقيطي الجَكَني الحِمْيري، وُلِدَ سنةَ 1325هـ في شِنْقيط في كيفا شرق موريتانيا، ونشَأَ يتيمًا في بيوت أخوالِه، وحفِظ القرآنَ وهو ابنُ عشْرِ سِنينَ، وتعلَّم رسْمَ المصحفِ على يَدِ ابن خالِه، وأخَذ الأدَب وعُلوم اللُّغة على يَدِ زوجةِ خالِه، فكانت مَدرستُه الأولى بَيتَ خالتِه، تعلَّم الفِقْه المالكيَّ، وهو السائدُ في بِلاده، فدرَس مُختصَر خليلٍ على يَد الشيخِ محمَّد بنِ صالح إلى قسْم العبادات، ثم درَس عليه أيضًا ألفيةَ ابن مالكٍ، ثم تعلَّم عُلوم القرآنِ من التَّفسير والمعاني والقِراءاتِ. تعلَّم الشِّنقيطي على مَشايخَ مُتعدِّدين، وكلُّهم من الجَنَكيين، وهي القَبيلةُ التي ينْتمي إليها، وكانت مَعروفةً بالعِلم، برَع في العُلوم كلِّها حتى فاق أقرانَه، أراد مكَّة حاجًّا وزائرًا، وأرادَه اللهُ معلِّمًا ومفسِّرًا، إنْ تَحدَّث في التفسيرِ خِلْتَه الطبَريَّ، وإنْ أنشَأَ في الشِّعر حَسِبتَه المتنبِّي، وإنْ جال في الحديثِ وعُلومِه ظنَنتَه ابنَ حَجَرٍ العَسْقلاني، فكان رحِمه الله مفسِّرًا، ومحدِّثًا، وشاعرًا، وأديبًا. خرَج قاصدًا الحجَّ من بلادِه سنةَ 1367هـ، ثم استقرَّ في المدينةِ النَّبوية، ودرَّس في المسجدِ النَّبوي، وفي سَنةِ 1371هـ افتُتِح معهدٌ عِلْمي بالرياضِ، وكُلِّيةٌ للشَّريعة وأُخْرى للُّغة، واختِيرَ الشيخ للتَّدريس بالمعهد والكُلِّيتينِ؛ فتولَّى تدْريسَ التفسيرِ والأصول. مكَث الشَّيخ بالرِّياضِ عشْرَ سَنواتٍ، وكان يقضي الإجازةَ بالمدينةِ لِيُكمِلَ التفسيرَ، وكان يدرِّس في مسجدِ الشيخ محمَّد آلِ الشيخ في الأُصول، كما كان يخُصُّ بعْضَ الطلَّاب بدرْسٍ آخَرَ في بيتِه، وقد كان بيتُه أشبهَ بمدرسةٍ يَؤُمُّها الصغيرُ والكبيرُ، والقريبُ والبعيد، ثم عاد إلى المدينةِ لمَّا أُنشِئَت الجامعة الإسلاميَّةُ سنةَ 1381هـ، فكان الشيخُ عَلَمًا من أعلامِها، ووَتَدًا من أوتادِها، يَرجِعُ إليه طُلَّابها كما يَرجِع إليه شيوخُها، وفي سنةِ 1386هـ افتُتِح معهدُ القضاءِ العالي بالرِّياض، فكان الشيخُ يَذهبُ لإلْقاء المحاضراتِ المطلوبةِ في التفسير والأصولِ، ولمَّا شُكِّلت هَيئةُ كِبار العلماءِ عيٍّن عضوًا فيها، وكان رئيسًا لإحدى دَوراتها، كما كان عضوًا في رابطةِ العالَمِ الإسلامي. كان رحِمه الله بحْرًا لا ساحلَ له من العِلْم والحفْظ، والإتقانِ والضبْط، وتَدلُّ مَصنَّفاته على غَزيرِ عِلمه وكَمال ورَعِه؛ فمِن أشهرِها: ((أضواءُ البيانِ في إيضاح القرآنِ بالقرآن))، و ((منْعُ جَواز المجازِ في المنزَّل للتعبُّد والإعجازِ))، و ((دفعُ إيهامِ الاضطرابِ عن آيات الكتابِ))، و ((مُذكِّرة في أُصول الفِقه على رَوضة الناظِر))، و ((آدابُ البحثِ والمناظَرة))، و ((شرحٌ على مَراقي السُّعود في الأُصول))، وغيرها مِن المؤلَّفات التي أفاد بها العالَمَ الإسلاميَّ، وكانت وفاتُه رحمه الله في مكَّة وغُسِّل في بَيته في مكَّة في شارع المنصورِ، وصلَّى عليه الشيخ عبدُ العزيز بن بازٍ في المسجِدِ الحرام بعدَ صلاة الظُّهر، ودُفِن بمَقبرةِ المعلَّاة بريع الحَجونِ بمكَّة المكرَّمة."},{"id":5399,"title":"الوحدة بين ليبيا وتونس .","date":["العام الهجري :1393","الشهر القمري : ذي الحجة","العام الميلادي :1974"],"text":"جرَت اتِّصالاتٌ سَريعةٌ بين الحكومتينِ اللِّيبيةِ والتُّونسية في 18 ذي الحجةِ / 12 يناير؛ حيث وقَّع الزعيمُ التُّونسي الحبيب بُوْرقيبة والعقيدُ اللِّيبي معمَّر القذَّافي على \"بيان جربة\"؛ لتَوحيدِ البلدينِ تحت رايةِ جُمْهورية واحدةٍ تُسمَّى بـ\"الجُمهورية العربيَّة الإسلاميَّة\" تكونُ وَفْقَ سُلْطةٍ تَنفيذيَّة وتشْريعية وقَضائيةٍ ودُسْتورية واحدةٍ، على أنْ يكون بُورقيبة رئيسًا لها، والقذَّافي نائبًا له، أو وزيرًا أوَّلَ في حُكومة الوَحْدة، لكنَّ هذه الوَحدةَ لم يطُلْ عُمرُها أكثرَ من 48 ساعةً، فانفصلَت عُراها وفشَلَت الوَحدةُ بسُرعةٍ، وأُقِيل وزير الشُّؤون الخارجية التُّونسي محمَّد المصْمودي في 21 ذي الحَجة / 14 كانون الثاني. كان هَدَفُ بُورقيبةَ مِن الوَحدةِ الاستفادةَ من نِفْط لِيبيا، بينما كان القذَّافي يَطمَع في رِئاسة الوَحدةِ بعْدَ بُورقيبة، ومِن أبْرز أسبابِ فَشَل الوَحدةِ عَدَمُ دعْم جماعةِ بُورقيبة له في الوَحدة، وخاصَّةً الوزير الأوَّل الهادي نُويرة الذي كان مُسافِرًا إلى طَهرانَ وقْت عقْدِ الوَحدةِ."},{"id":5400,"title":"حركة التمرد البولشستانية في باكستان للانفصال بدولة مستقلة .","date":["العام الهجري :1394","العام الميلادي :1974"],"text":"قامت في باكستانَ حركةُ تمرُّد في ولاية بالوشستان بزعامة حزب عوامي الوطنيِّ، وتهدُف هذه الحركةُ إلى انفصالِ بالوشستان عن باكستانَ، وتأسيس دولة خاصَّةٍ على أساس القوميَّة البالوشستية، وضمِّ المناطق الأفغانية التي يقيم فيها البالوش إليها، وكان وراء هذه الحركةِ الشيوعيون الذين عملوا في الخفاء لتجزئة الأمصارِ الإسلامية؛ لإضعافِها، وخاصَّة المجاورة لروسيا، ولكن قُضي على هذا التمرُّد ولم يحصل المتمرِّدون على مرادِهم."},{"id":5401,"title":"إلغاء حظر النفط عن الولايات المتحدة وتطور العلاقة مع السعودية .","date":["العام الهجري :1394","الشهر القمري : صفر","العام الميلادي :1974"],"text":"أُلغي حظرُ تصدير النفطِ إلى الولايات المتحدة في 18 آذار (مارس). وقد ساعد إلغاءُ الحظرِ على حدوث بعض الانفراجِ في العلاقات السعودية الأمريكية؛ مما أتاح الفرصةَ للتوصلِ إلى اتفاقية ثُنائيةٍ حولَ التعاون الاقتصاديِّ والفني عقَدها البلَدانِ في 8 حزيران (يونيو) 1974. وبعد مرور فترة قصيرةٍ وُقِّعَت اتفاقيةٌ حول تصديرِ معدَّاتٍ عسكرية أمريكية إلى السعودية، وتدريب الحرس الوطني السعوديِّ على يد مُدرِّبين أمريكان، وفي 9 حزيران (يونيو) 1974م أُعلن عن توقيع اتفاقية حول نقلِ60% من أسهم شركة أرامكو للسعودية."},{"id":5402,"title":"وفاة الشيخ محمد أحمد أبو زُهرة .","date":["العام الهجري :1394","الشهر القمري : ربيع الأول","العام الميلادي :1974"],"text":"هو الشيخُ العلَّامة محمد بنُ أحمد بنِ مصطفى بنِ أحمد المعروف بأبي زُهرةَ. وُلِدَ بالمحلَّة الكبرى التابعة لمحافظة الغربية بمصر في 6 ذي القعدة 1315هـ/ 29 مارس 1898م، ونشأ في أسرة كريمةٍ عُنِيت بولدها، فدفعت به إلى أحد الكتاتيب التي كانت مُنتشرة في أنحاء مصر تُعلِّم الأطفال وتحفِّظهم القرآن الكريم؛ فحفظ القرآنَ الكريم، وأجاد تعلُّم مبادئ القراءة والكتابةِ، ثم انتقل للتعلُّم بالجامع الأحمديِّ بمدينة طنطا، كان يُطلق عليه الأزهر الثاني؛ لمكانته الرفيعةِ، ثم تقدَّم لمدرسةِ القضاءِ الشرعيِّ سنة 1335هـ، فكان من أول المقبولين على الرغم من صِغر سنِّه، وتخرَّج فيها سنة 1343هـ / 1924م، وبعدَ أن حصلَ على عالمية القضاءِ الشرعيِّ اتجه إلى دارِ العلومِ، فنال شهادةَ الدُّبلوم سنة 1346هـ. عمل في تدريس اللغة العربيةِ بالمدارس الثانويةِ، ثم كُلِّف بتدريس مادة الخطابة والجدل في كلية أصول الدين بالأزهر، وبعدَ أن ذاعَ صيته وبراعته في تدريس مادة الخَطابة اختارته كليةُ الحقوقِ بجامعة القاهرةِ لتدريسِ مادة الخطابةِ بها، وبعدَ مدَّة وجيزة عَهِدت إليه الكلية بتدريس مادة الشريعةِ الإسلاميةِ، فزامَل في قسم الشريعة عددًا من أساطينِ العلماء، مثلَ: أحمد إبراهيم، وأحمد أبي الفتح، وعلي قراعة، وفرج السنهوري، وكان وجود مثل هؤلاء زاده دأبًا وجدَّة في الدرس والبحث حتى ارتقى إلى صفوفهم ومكانتهم الرفيعة، وكانت فيه عزيمةٌ وإصرارٌ وميلٌ إلى حياة الجدِّ التي لا هزلَ فيها، وقد تدرَّج أبو زهرةَ في كلية الحقوقِ التي شهِدَت أخصبَ حياته الفكريةِ حتى ترأَّس قسمَ الشريعة، وشغلَ منصب الوكالة فيها، وأُحيل إلى التقاعدِ سنة 1378هـ / 1958م، وبعد صدورِ قانون تطويرِ الأزهر اختُير الشيخ أبو زهرة عضوًا في مجمع البحوث الإسلامية سنة 1382هـ / 1962م، وهو المَجمَع الذي أُنشئ بديلًا عن هيئةِ كبار العلماء، وإلى جانب هذا كان الشيخ من مؤسِّسي معهد الدراسات الإسلاميةِ بالقاهرة، وكان يُلقي فيه محاضراتِه في الشريعةِ الإسلاميةِ احتسابًا لله دونَ أجرٍ، وكان هذا المعهد قد أُنشئ لمن فاتتْه الدراسةُ في الكلياتِ التي تُعنى بالدراسات العربية والشرعية، فالتحقَ به عددٌ كبير من خريجي الجامعاتِ غير الشرعيةِ الراغبين في مثلِ هذه الدراسات، ولأبي زهرةَ أكثرُ من ثمانين كتابًا في الفقه والتشريع وتراجِم الفقهاء الكبار، وكان أبو زهرة من أعلى الأصوات التي تنادي بتطبيقِ الشريعة الإسلاميةِ في الحياة. توفي الشيخ رحمه الله عن عمر يناهز 76 عامًا."},{"id":5403,"title":"انضمام جمهورية الصومال إلى جامعة الدول العربية .","date":["العام الهجري :1394","الشهر القمري : ربيع الآخر","العام الميلادي :1974"],"text":"انضمَّت جمهوريةُ الصومال إلى جامعة الدول العربيةِ، وقد استقلَّت أرض الصومالِ عن الإدارة الإيطاليةِ في 1 يوليو 1960م، وحصلت على عضويَّةِ الأمم المتحدة في 20/ 9 / 1960م."},{"id":5404,"title":"وفاة المصلح المغربي علال الفاسي .","date":["العام الهجري :1394","الشهر القمري : جمادى الآخرة","العام الميلادي :1974"],"text":"هو محمد علال ابنُ العلَّامة الخطيب عبد الواحد بنِ عبد السلام بنِ علال بنِ عبد الله بنِ المجذوب الفاسي الفِهريُّ نسبًا، ثم الفاسيُّ مولدًا ودارًا ومنشأ. أحد روَّاد الفكر الإسلامي الحديث، ومن كبار الخطباء في المغرب، ينحدِرُ من عائلة عربية عريقة نزحت من موطنها بديار الأندلس إلى المغرب الأقصى فرارًا بدينها وعقيدتها من محاكمِ التفتيشِ الإسبانية، واستوطنت بمدينة فاس تحت اسمِ بني الجدِّ واشتهرت بآل الفاسيِّ الفِهريِّ، وساهمت في جميع المجالات العلمية والمعرفية؛ وهو مؤسِّس حزب الاستقلالِ المغربيِّ، وأحد منظِّري فكرة المغرب العربي الكبير، وُلِدَ بمدينة فاس المغربية، في أواخر شوال عام1326هـ/ 1908م، أدخله والده إلى الكتَّاب لتلقي مبادئ الكتابة والقراءة، وحَفِظ القرآن الكريم في سنٍّ مبكرة، وبعد ذلك نقله والده إلى المدرسة العربيَّة الحرة بفاس القديمة؛ ليتعلَّم مبادئ الدين وقواعدَ اللغة العربيةِ، كان مبرزًا على أقرانه، مفخرة أسرته، بل مفخرة القَرويِّين والمغرب، عِلمًا ونبوغًا، وذكاء، وفي عام 1338هـ التحق بجامع القَرويِّين العامرِ، فدرس فيه المختصرَ بشرح الدرديرِ، والتُّحفةَ بشرح الشيخ التَّاودي بنِ سودة، وجمع الجوامع بشرح المحلِّي، والكامل في الأدب للمبَرِّد، ومقامات الحريري، وعيون الأخبار لابن قتيبةَ، وغيرها من الكتب، وسرد الكتب الستة على أبيه وعمِّه القاضي عبد الله الفاسيِّ، وعلى الشريف السلفيِّ علي الدرقاوي زاد المعاد في هدي خير العباد، وأدب الدنيا والدين، والشمائل المحمدية، وتابع دراستَه حتى حصل على الشهادة العالِميَّة، وفي عام 1380هـ عُيِّن وزيرًا للدولة مكلَّفًا بالشؤون الإسلامية، ثم انسحب منَ الحكومةِ في عام 1382هـ وعُيِّن أستاذًا بكلية الشريعة التابعة لجامعة القرويِّين بظهر المهراز، وكُلِّيتيِ الحقوق والآداب لجامعة محمد الخامس بالرباطِ، وبدار الحديثِ الحسنيَّة بنفس المدينة، وكان عضوًا مقررًا عامًّا في لجنة مدونة الفقه الإسلامي التي شُكِّلت في فجر الاستقلال، ساهم في مقاومة المحتلِّ الفرنسيِّ وجاهد ضده، ودفعته هِمَّته إلى تأليف جمعيةٍ أُطلق عليها (جمعية القَرويِّين لمقاومة المحتلِّين)، تولى رئاسة حزب الاستقلال الذي أُنشئ من قبلُ، واختُير عضوًا رئيسًا في مجلس الدستورِ لوضع دستور البلاد، ثم انتُخِب رئيسًا له، وقدَّم مشروع القانون الأساسيِّ، وشارك في وضع الأُسس الأولى للدستور سنة 1382هـ ودخل الانتخاباتِ التي أُجريت سنة 1383هـ ودخل الوزارة، ومن مصنَّفاته كتاب: ((الحركات الاستقلالية في المغرب العربي))، و((المغرب العربي منذ الحربِ العالميَّة الأولى))، و ((مقاصد الشريعة الإسلاميَّة ومكارمها))، و ((دفاع عن الشريعة))، و ((المدخل للفقه الإسلامي))، و ((تاريخ التشريع الإسلامي))، و ((النقد الذاتي))، و ((معركة اليوم والغد))، و ((دائمًا مع الشعب))، وكتاب ((عقيدة وجهاد)). وكان شاعرًا نبغ في قَرْضه في سِنٍّ مبكرة، فنظم كثيرًا من القصائد: الدينية والسياسية، والاجتماعية والتاريخية.تُوفي وهو في بوخارست عاصمة رومانيا إِثْرَ نوبةٍ قلبيةٍ وهو يعرض على رئيسها انطباعاته عن زيارته التي قام بها وفدُ حزب الاستقلالِ المغربي برئاسته، ويشرح قضيَّة المغرب وصحراء المغرب، ونِضال الشَّعب الفلسطيني في سبيل نَيْل حُريته وأرضه، ونُقِل جثمانه إلى المغرب، فدُفِن بمقبرة الشهداء بحي العلو في مدينة الرباط."},{"id":5405,"title":"وفاة الحاج أمين الحسيني مفتي القدس .","date":["العام الهجري :1394","الشهر القمري : جمادى الآخرة","العام الميلادي :1974"],"text":"هو الحاجُّ محمد أمين بنُ محمد طاهر بن مصطفى الحُسيني مفتي القدس. وُلد في القدسِ سنة 1897م، تربَّى في بيت والدِه الشيخِ طاهر الحسينيِّ مفتي القدس، عُرِف بالحاج أمين الحسينيِّ بعد أن حجَّ برفقة والدتِه. تلقَّى علومه الابتدائيَّة والثانوية في مدارسِ القدسِ، ثم التحق بكلية الفرير بالقدس لتعلُّم اللغةِ الفرنسية، بعدها التحق بجامعة الأزهر، وكان يتردَّد على (دار الدعوة والإرشاد) التي أنشأها الشيخُ محمد رشيد رضا حيث تأثَّر به وبفكره الإصلاحيِّ، ومن خلال معرفته به عرف الكثير عنِ الصهيونية وأطماعِها في فلسطين، وبعدَ نُشوب الحرب العالمية الأولى التحق بكلية الأستانةِ العسكرية وتخرَّج منها ضابطًا، والتحق بالجيش العثماني في ولاية أزمير، وعمل فيه حتى نهاية الحرب؛ مما أكسبه خبرة جيِّدة كان لها الأثرُ الأكبر في شخصيتِه وحياتِه. بعدَ نهاية الحرب عاد الحسينيُّ إلى القدس وهو برتبة ضابطٍ، ملِمًّا بالفكر الإسلاميِّ، والعلوم المفيدةِ، والخبرة العسكريةِ، ويعرفُ منَ اللغات الأجنبية التركيةَ والفرنسيةَ، بالإضافة إلى ذلك كلِّه كان بحكم انتمائه إلى أسرة آل الحسيني مهيَّأً ليكون زعيمًا وداعيةً مسموع الكلمةِ. عندما احتلَّ الإنجليز فلسطين انصرف الحُسينيُّ إلى تنظيم الفلسطينيين في حركة وطنية شاملة ضدَّ الاستعمار والصهيونية، فكوَّنوا في القدس أوَّل منظمة سياسيَّة عرفتها فلسطين هو (النادي العربي)، وانتُخب الحسينيُّ رئيسًا له، وكان لهذا النادي أثر كبير في انطلاق الحركة الوطنية الفلسطينية، وقيام المظاهرات ضد الاحتلالِ. تسلَّم الحسينيُّ منصبَ الإفتاء رسميًّا، فأعاد تنظيم المحاكم الشرعية، واختار لها القضاة، ونظَّم الأوقاف، وأخذ يعمل على تقوية المدارس الإسلامية وتنظيم أمورها، كما شارك في تأسيس مجلس شرعي إسلامي لفلسطين تألَّف من مجموعة من العلماء، وعُين الحسيني رئيسًا لهذا المجلس الذي سُمي (المجلس الإسلامي الأعلى) الذي أصبح على مرِّ الأيام أقوى قوة وطنية إسلامية فلسطينية. كان الحاج أمين القوة الدافعة للحركة الوطنية، ومركز الثقل في المقاومة الفلسطينية؛ مما حفَّز الإنجليز واليهود إلى مقاومته والتخلُّص منه، فخرج الحاجُّ من فلسطين إلى لبنانَ بعد رفضه لقرار التقسيم 1937م وتحريضه للفلسطينيين ضدَّ الاحتلالِ، ومكث في لبنان عامين، ثم فرَّ منها إلى العراق، ولما سمع الحاج بالمآسي التي حلَّت بالشعب البوسني المسلم اجتمع بزعماءِ البوسنة والهرسك في ألمانيا؛ للعمل على منع وقوع المذابحِ فيهم، فحصَل على موافقةِ الحكومة الألمانية على تجنيدِ الشبَّان منهم وتسليحِهم للدفاع عن أنفسهِم وعائلاتهم، وكذلك اتَّفق مع السلطات الألمانية على إنشاء معهد للأئمة؛ لتوزيعِهم على وَحدات الفرق البوسنيَّة الذين زاد عددُهم عن 100 ألف مقاتل مع دول المحورِ، ولما زحف الحلفاء على ألمانيا عام 1945م انتقل الحاج أمين إلى باريس، ومنها إلى مصر، وفي مصر شكَّل الهيئة العربية العليا لفلسطين برئاسته؛ حيثُ نظَّم الحركة الوطنية الفلسطينية تنظيمًا حديثًا، بل ومدَّ نشاطه إلى الدائرة الإسلامية؛ حيث كان يرأس مؤتمرات إسلامية في مكة نشأت عنها مؤسسة دائمة باسم (مؤتمر العالم الإسلامي) برئاسته، وظل يشغل هذا المنصب طيلة حياته إلى أن تُوفي رحمه الله في بيروت ودُفن في مقبرة الشهداء بالحرج."},{"id":5406,"title":"إصدار الحكومة التركية أوامر إلى قواتها العسكرية بالنزول في جزيرة قبرص .","date":["العام الهجري :1394","الشهر القمري : رجب","العام الميلادي :1974"],"text":"أصدرتِ الحكومةُ التركيةُ أوامرها إلى قوَّاتها العسكريةِ بالنزول في جزيرة قُبرص المتنازَع عليها مع اليونانِ، وقد تمكَّنت القواتُ التركية منَ السيطرة على 35% من مساحة الجزيرةِ، حتى وقف إطلاق النار في 16 أغسطس بعدَ إرسال قواتٍ دوليةٍ إلى الجزيرة."},{"id":5407,"title":"استقلال غينيا بيساو .","date":["العام الهجري :1394","الشهر القمري : شعبان","العام الميلادي :1974"],"text":"غينيا بيساو دولة أفريقية صغيرة ذات أغلبية مسلمة كانت تحتَ الاحتلالِ البرتغالي الذي أذاقها الوَيلاتِ حتى اعترفت عام 1392هـ / 1972م لجنة تصفية الاستعمار التابعة للأمم المتحدة بالحزب الإفريقي المطالب باستقلال غينيا بيساو وجزر الجبل الأخضرِ عنِ السيطرة البرتغالية، وفي 1393هـ / 1973م جرت الانتخاباتُ لتشكيلِ مجلس الشعب الوطني وحصلت غينيا بيساو على الاستقلال الذاتي، وتسلَّم لويس كابرال رئاسةَ مجلس الدولة، ثم أُجبرت الحكومة البرتغالية على الانسحاب من غينيا بيساو لتصبح دولة مستقلَّة."},{"id":5408,"title":"حل مشكلة البريمي واعتراف السعودية بدولة الإمارات العربية المتحدة .","date":["العام الهجري :1394","الشهر القمري : شعبان","العام الميلادي :1974"],"text":"في عام 1971م حلَّت السعودية خلافها مع سلطنة عُمان حول واحة البريمي؛ حيثُ قام السلطان قابوس بن سعيد سلطان عمان بزيارة إلى الرياض والتقى مع الملك فيصل في الرياض في تشرين الأول عام 1971م وصدر عن هذه الزيارة بيان مشترك تضمَّن اعتراف السعودية بضم القرى التي سبق أن حصلت عليها سلطنة عمان وفقًا للاتفاق الذي تم بينهما وبين إمارة أبو ظبي برعاية الحكومة البريطانية في ديسمبر 1955م، وهي البريمي وحماسا وصعراء، مقابل بعض التعهُّدات العمانية، وبهذا يكون النزاع بين كل من سلطنة عُمان والسعودية قد انتهى.كذلك تم تسويةُ مشكلة البريمي بين السعودية والإمارات العربيَّة المتَّحدة،  وبموجبه أعلنت السعودية اعترافها بدولة الإمارات العربية المتحدة وتبادل التمثيل الدبلوماسي معها."},{"id":5409,"title":"المعاهدة العراقية الإيرانية .","date":["العام الهجري :1395","العام الميلادي :1975"],"text":"كان من مقرَّراتِ اتفاقيةِ الجزائر بين العراقِ وإيران التي كانت عام 1383هـ / 1963م أن يجتمعَ الطرفانِ في طهرانَ في 15 آذار 1975م / 1395هـ وبناءً على ما جاء من إعادة الثقةِ والعمل على حلِّ مسألة الحدودِ فقد قرَّر الطرفانِ عقدَ المعاهدة وعيَّنا مندوبيهما المفوَّضينِ: رئيسَ الوزراء سعدون حمادي، ووزيرَ خارجية العراق، وشاهِنشاه إيران عباس علي خلعتبري، ووزيرَ خارجية إيران، وبعدَ تبادل وثائق التفويض اتفقا على أحكام المعاهدة التي تدورُ حولَ تحديدِ الحدود البرية والنهريةِ، والرقابة على الحدودِ والملاحة والمسائل الداخليَّة والخارجيَّة، وعدم التدخُّلات في الشؤون الداخلية لكل بلدٍ، وضمَّت أيضًا ملحقًا بالمعاهدة يتعلَّق بموضوع الأمن، وغيرها من الموضوعاتِ."},{"id":5410,"title":"إعلان القبارصة الأتراك إنشاء \"دولة قبرص التركية الفيدرالية\" .","date":["العام الهجري :1395","الشهر القمري : صفر","العام الميلادي :1975"],"text":"ما إن تمكَّنتِ القواتُ العسكريةُ التركية من احتلال حوالي 35 % من مساحة الجزيرة حتى أعلن القبارصةُ الأتراكُ إنشاءَ \"دولة قبرص التركية الفيدرالية\" كإدارة قبرصية تركية مستقلَّة، وذلك بعد فشل المحادثاتِ بين تركيا واليونان حولَ الجزيرةِ."},{"id":5411,"title":"مقتل الملك فيصل بن عبد العزيز آل سعود وتولي أخيه خالد المُلك .","date":["العام الهجري :1395","الشهر القمري : ربيع الأول","العام الميلادي :1975"],"text":"هو المَلِك فيصل بنُ عبدِ العزيز بنِ عبد الرحمن الفيصل آل سعودٍ، الابنُ الثالث لوالده الملك المؤسِّس عبد العزيز رحمهما الله. وُلِد في مدينة الرياض في 14 صفر سنة 1324هـ / 1906م في عام انتصار والده على ابن رشيد في القصيم. شارك في سنٍّ مبكِّرة في المعارك والأحداث التي واكبت نُشوء المملكة؛ ففي عام 1345هـ- 1927م ندبه والده لينوبَ عنه في المباحثاتِ مع بريطانيا التي انتهت بالتوقيع على معاهدة جدَّة في 18 شوال 1345هـ / 20 مايو 1927م التي اعترفت بريطانيا بمقتضاها بحكومةِ الملك عبدِ العزيز بعد ضمِّه للحجاز، ثم قام بعدَها بزيارة معظمِ دول أوروبا وآسيا، ممثلًا بلادَه في مختلِف المؤتمراتِ، وكان هذا الحضور عاملًا لبلورة مَلَكة القيادةِ لديه التي برزت في أخذه المملكة نحوَ آفاق التطوير المدنيِّ والعلميِّ الحديث أثناء تولِّيه رئاسة الحكومة في مملكة الحجازِ، ونيابته عن والدِه، أو رئاسته لمجلس الشورى، أو تولِّيه وزارة الخارجية أو رئاسة مجلس الوكلاء، ثم رئاسة مجلس الوزراء، إلى أن بويعَ بولاية العهد في 11 ربيع الأول 1373 هـ / 9 نوفمبر 1953م، وفي يوم الاثنين 27 جمادي الآخرة عام 1384هـ / 3 نوفمبر 1964 بايع الشعب العربيُّ السعوديُّ بالإجماع الملكَ فيصل بنَ عبدِ العزيز ملكًا شرعيًّا على المملكة العربية السعودية, وكان طوال عهده عُرف بعداوته للتوجُّهات اليسارية الشيوعية سواء كانت في أشخاصٍ أو تياراتٍ أو أنظمة؛ ولهذا السبب كان خلافُه مع جمال عبد الناصر. في صباح يوم الثلاثاء 13 ربيع الأول 1395هـ الموافق 25 مارس كان الملك فيصل يستقبل زوَّارَه بمقرِّ رئاسة الوزراء بالرياض، وكان في غرفة الانتظار وزيرُ النفط الكويتي الكاظمي، ومعه وزير البترول السعودي أحمد زكي يماني. ووصل في هذه الأثناءِ الأميرُ فيصل بنُ مساعد بنِ عبد العزيز أخو الأمير الشاعرُ عبد الرحمن بنُ مساعد، طالبًا الدخول للسلام على عمِّه. وعندما همَّ الوزيرانِ بالدخول على الملك فيصل دخل معهما ابنُ أخيه الأمير فيصل بن مساعد. وعندما همَّ الملك فيصل بالوقوف له لاستقبالِه كعادته مع الداخلينَ عليه للسلامِ، أخرجَ الأميرُ فيصل بن مساعد مسدَّسًا كان يُخفيه في ثيابِه، وأطلق منه ثلاثَ رصاصاتٍ أصابت الملكَ في مقتلٍ في رأسِه. ونُقِل الملك فيصل على وجه السرعةِ إلى المستشفى المركزيِّ بالرياض، ولكنَّه توفِّيَ من ساعته رحمه الله، أما القاتلُ فقد قُبِض عليه، وأودِعَ السجن. وبعد التحقيق معه نُفِّذ فيه حكمُ القِصاصِ قتلًا بالسيفِ في مدينة الرياض، بعد 82 يومًا من قَتلِه للملك فيصل في يوم الأربعاء 9 جمادى الآخرة الموافق 18 يونيه، ثم تولى المُلْك بعده ولي العهد الملك خالد بن عبد العزيز."},{"id":5412,"title":"الحرب الأهلية اللبنانية .","date":["العام الهجري :1395","الشهر القمري : ربيع الآخر","العام الميلادي :1975"],"text":"الحرب الأهليَّة اللبنانيَّة هي حرب دمويَّة وصراعٌ معقَّد استمرَّ في لبنان 15 سنة و6 أشهر ما بين 1975- 1990م، وتعود جذوره للصراعاتِ والتنازلاتِ السياسيَّة في فترة الاستعمار الفرنسيِّ لسوريا ولبنان، وعاد ليثورَ بسبب التغيُّر السكانيِّ (الديمغرافي) في لبنان والنزاع الدينيِّ: الإسلامي النصراني من جهةٍ، والسني الشيعي من جهة أخرى، ومما زاد من حدَّة النزاع تقاربُ هذه العناصر من سوريا أو إسرائيل. وقد ساهَم إنشاءُ دولة إسرائيلَ ونزوحُ مئاتِ الآلاف من اللاجئين الفلسطينيِّين إلى لبنان خلالَ عامي 1948 و1967 في تغيير التوازن الديموغرافي لصالح السكانِ المسلمين. وقد بدأ القتالُ بين الموارنة والقواتِ الفلسطينية (معظمهم من منظمة التحرير الفلسطينية)، ثم شَكَّلت الجماعاتُ اليساريَّة والعربيَّة والإسلاميَّة اللبنانية تحالفًا مع الفلسطينيين خلال فترة القتالِ، وعلاوةً على ذلك شاركت القوى الأجنبية، مثل إسرائيل وسوريا، في الحرب وحاربَت جنبًا إلى جنب مع فصائلَ مختلفةٍ. وبعد توقُّف قصير للمعارك عام 1976م لانعقاد القمَّة العربية عاد الصراع الأهليُّ ليُستكملَ، وعاد ليتركَّز القتالُ في جنوب لبنان بشكل أساسيٍّ، والذي سيطرت عليه بدايةً منظَّمةُ التحريرِ الفلسطينيَّة، ثم قامت إسرائيلُ باحتلالِه. وقد أسفرتْ هذه الحربُ عن مقتل 120 ألفًا، وما يقربُ من 76 ألف شخص مشرَّدين داخلَ لبنان، ومليون نازح خارج لبنان نتيجةَ الحربِ، ولم تسحب سوريا قواتها حتى عام 2005م؛ حيثُ أُجبرت على الانسحاب تحت ضغط المظاهرات اللبنانية والتدخُّل الدبلوماسي المكثَّف من الولايات الأمريكية المتحدة، وفرنسا والأمم المتحدة. وفي أغسطس 1989م تم التوصُّل بوساطة السعودية إلى اتفاق الطائف الذي كان بدايةً لإنهاء الحرب الأهليَّة. ولكن ميشيل عون رفض الاتفاقَ؛ وذلك لأن الاتفاق يقضي بانتشارٍ سوريٍّ على الأراضي اللبنانية، وتم إقصاء ميشيل عون من قصر بعبدا الرئاسيِّ في أكتوبر عام 1990 بعملية لبنانية - سورية مشتركة ومباركة أمريكية؛ حيث اضطر للجوء إلى السفارة الفرنسية، وتوجه من بعدها إلى باريس في منفاه."},{"id":5413,"title":"استقلال جزر القمر .","date":["العام الهجري :1395","الشهر القمري : جمادى الآخرة","العام الميلادي :1975"],"text":"تقع جزرُ القمر (القمر الكبرى وأنجوان وموحلي ومايوت) في المحيط الهنديِّ على مقرُبةٍ من الساحلِ الشرقيِّ لإفريقيا، وأقربُ الدول إليها موزمبيق وتنزانيا ومدغشْقَر وسيشل. أصبحتْ جزرُ القمرِ تحت الحماية الفرنسيةِ بسبب استعانةِ بعض السلاطينِ على بعضِهم بالفرنسيِّين، فأصبحوا يتعاهدون مع الفرنسيِّين ضدَّ بعضهم، واستطاعت فرنسا أن تجعلَ الجزر تحت حمايتِها، ثم ألحقَت جزر القمر بجزيرة مدغشقر المحتلَّة من قِبَل فرنسا أيضًا وبقِيَت عامينِ على هذا، ثم رجعت مستعمَرة فرنسيةً لا ترتبط بغيرها، واستمرَّ الوضعُ على ذلك حتى الحرب العالميَّة الثانية، ثم فرضت إنجلترا سيطرتَها على الجزُرِ في أثناءِ الحرب بعدَ هزيمة فرنسا أمام الألمانِ، وبعدَ الحرب عادت لفرنسا، ثم أيَّدت الجزر دستورَ ديغول الخاصِّ بالدول المستعمرةِ الفرنسية، وبالتالي مُنحت الجزر الحكم الذاتيَّ مع بقاء المطالبةِ بالاستقلال التامِّ عن فرنسا. في عام 1392هـ / 1972م قرَّر المجلس النيابي إصدار بيان يطالبُ فيه بالاستقلالِ التامِّ والانفصال عن فرنسا التي أجرت استفتاءً في ذي الحجة من عام 1394هـ / ديسمبر 1974م؛ حيثُ أيَّد الغالبيةُ العظمى الاستقلالَ التامَّ والانفصال عن فرنسا، ثم أُعلن الاستقلال في 27 جمادى الآخرة 1395هـ / 6 تموز، وأُعلن عن اختيارِ أحمد عبد الله رئيسًا للدولة الجديدةِ، ووافقت فرنسا على استقلالِ الجزرِ عدا جزيرة مايوت؛ فقد كان معظمُ سكَّانها ضد الاستقلال التامِّ أيامَ الاستفتاءِ، ووعدتها فرنسا أنها ستبقى ضمنَ إطار المجموعة الفرنسيةِ، ثم طُولب بوحدةِ جزر القمر كلِّها، ولم تعترف فرنسا باستقلال جزيرة مايوت، ثم تمَّ قبول دولة جزر القمر بالأممِ المتَّحدةِ في عام 1396هـ / 1976م ورضخت فرنسا للأمر الواقع، واعترفت باستقلال الجزرِ جميعها."},{"id":5414,"title":"مشتاق أحمد يترأس بنغلادش بعد انقلاب عسكري على مجيب الرحمن .","date":["العام الهجري :1395","الشهر القمري : رجب","العام الميلادي :1975"],"text":"استبدَّ شيخ مجيب الرحمن بالحكمِ وحلَّ التنظيماتِ السياسيةَ كلَّها سوى حزبه الحاكمِ حزب رابطة عوامي، وبدأ الفسادُ الإداريُّ والفقر ينتشران، وبقِيَت بنغلادش تحت الوصاية الهنديةِ، فخاف الرئيسُ من العسكريِّين فنظم جيشًا سريًّا هو واكي باهيتي لحمايتِه الشخصيَّة. لكن العسكر قاموا بانقلابٍ ضد مجيبِ الرحمن في 28 رجب / 15 أغسطس، فأطاحوا به وبنائبِه ورئيس وزرائه والنظام القائمِ كله، وقُتِل مجيب الرحمنِ، ثم نُصِّب وزير التجارة السابق خاندكار مشتاق أحمد رئيسًا للدولة، وكان ضد الشيوعية، وهو الذي غيَّرَ اسم الدولة الرسمي من بنغلادش إلى جمهورية بنغلادش الإسلامية."},{"id":5415,"title":"وفاة شيخ مجيب الرحمن مؤسس دولة بنغلاديش ورئيسها .","date":["العام الهجري :1395","الشهر القمري : شعبان","العام الميلادي :1975"],"text":"وُلِد شيخ مجيب الرحمن عام 1920م في قرية تونجيبار تبعد 97 كم جنوب غربي دكا، درس مجيب الرحمن في مدارس الإرسالياتِ التنصيريةِ وتربَّى فيها وحصل على درجة البكالوريوس في الآداب من جامعة كالكوتا، كما حصل على شهادة في القانون من جامعة دكا. كان أحد مؤسِّسي رابطة \"عوامي\" العام 1949م، وكان مؤيدًا انفصال باكستان عن الهند. استطاع شيخ مجيب بعد نُشوب حربٍ أهلية شرسةٍ بين شطري باكستان الغربيِّ والشرقيِّ أن ينفصلَ بالشطر الشرقيِّ؛ ففي عام 1970م قاد شيخ مجيب حزبَه إلى فوزٍ كاسحٍ في الانتخاباتِ، فأعلن بعد فوز حزبه قيامَ دولةِ بنغلاديش منفصلةً عن باكستان الغربية التي عانت من مشاكل سياسيَّة واجتماعيَّة واقتصاديَّة؛ فاضطرَّ الرئيس الباكستاني يحيى خان (شيعي) أن يسافرَ إلى الجناح الشرقي من باكستانَ، ويعتقلَ مجيب الرحمن، فتسلَّم رئاسة بنغلاديش نصر الإسلامِ، أما رئاسةُ الحكومة فتسلَّمها تاج الدين أحمد، ولما أُطلق سراح مجيب الرحمن سافر فورًا إلى لندن وأجرى مباحثات مع رئيس وزراء بريطانيا، ثم عاد إلى دكا عاصمة بنغلاديش على طائرة هنديةٍ، فتولَّى رئاسة الوزراء بنفسه، وجعل من منصب رئيس الجمهورية صورة شرفية، ثم أعلن مجيب الرحمن قطعَ علاقة دولتِه بباكستانَ الغربيةِ، فعرض عليه ذو الفقار بوتو التنازلَ له عن السلطةِ في سبيل المحافظة على وحدةِ باكستان لكنَّه رفض، فأصدر دستورًا مؤقتًا ركَّز فيه سلطاتِ الحكم بيده، وتولَّى مجيب وزاراتِ الدفاع والداخليةِ والإعلامِ وشؤون مجلس الوزراء، ثم قرَّر أن يتولَّى رئاسة البلاد في يناير 1975، وركَّز جميع السلطات في يديه، ثم اعتمد نظام الحزب الواحدِ، وطارد المعارضةَ السياسيةَ وجمَّد الدستور، وحلَّ جميع التنظيمات السياسية، وفرض الرقابةَ على الصحافةِ، كل هذه الأمور قوَّت جبهة المعارضين ضدَّه وضد سياساتِه، وفي العام الذي تولَّى فيه رئاسة الدولة حدث انقلابٌ عسكري في 15 أغسطس قام به الجيشُ ضده، وانتهى الأمر بمقتلِه، وقد ترك شيخ مجيب الرحمن خَلْفه ابنتَه شيخة حسينة التي قادت المُعارضة، وفاز حزبُها رابطة عوامي في انتخابات 1996م."},{"id":5416,"title":"انقلاب عسكري يطيح برئيس بنغلاديش ثم انقلاب آخر .","date":["العام الهجري :1395","الشهر القمري : شوال","العام الميلادي :1975"],"text":"بعدَ الانقلابِ على شيخ مجيب الرحمن واغتيالِه في أغسطس تولَّى رئاسة بنغلاديش مشتاق أحمد، وفي 29 شوال / 3 تشرين الثاني قام انقلابٌ ضدَّه بعد أن بقي في الرئاسة فقط ثلاثةَ أشهرٍ، وقاد الانقلابَ العميدُ خالد مشرف الذي أُحضر منَ الهندِ، وكان قائدًا سابقًا لحاميةِ دكا ويوالي الهند، وكان قد عُيِّن رئيسًا لهيئة الأركان، ولكنَّه لم يتولَّ السلطة سوى أربعةِ أيامٍ حتى حدث انقلابٌ آخر أقصاه عن الرئاسةِ، واستولى على السلطةِ ثلاثةُ رؤساء هيئة الأركان، ثم ولَّوْا عليهم رجلًا غيرَ سياسيٍّ هو عبد الستار محمد صايم رئيس قضاة المحكمةِ العليا."},{"id":5417,"title":"إعلان قيام الجمهورية العربية الصحراوية في الصحراء الغربية .","date":["العام الهجري :1396","الشهر القمري : صفر","العام الميلادي :1976"],"text":"أُعلنت الجمهوريةُ العربيةُ الصحراويةُ الديمقراطيَّة يوم 27 فبراير- شباط من قبل جبهة البوليساريو. وفي السادس من مارس- آذار 1976م تم تشكيلُ أولِ حكومةٍ صحراوية برئاسة محمد الأمين أحمد، ضمَّت عددًا من الوزاراتِ الميدانيةِ التي سارعت إلى تنظيمِ واستكمالِ الهياكل التنظيميَّةِ والإدارية \"للدولة الصحراوية\". لا تعترفُ حاليًّا أيُّ دولة كبرى أو دولةٌ عربية - باستثناءِ الجزائر - بهذه الجمهوريةِ المعلنة من طرفٍ واحد."},{"id":5418,"title":"محاولة العقيد محمد نور سعيد الانقلاب على النميري .","date":["العام الهجري :1396","الشهر القمري : رجب","العام الميلادي :1976"],"text":"وقع في السودان انقلابٌ بقيادةِ العقيد محمد نور سعيد بتاريخ 5 رجب / 2 تموز، وهرب الرئيسُ جعفر النميريُّ واحتلَّ الانقلابيون المعسكراتِ ومطارَ الخرطومِ ودار الهاتف، استطاع النميريُّ أن يعودَ بعد يومين إلى مقرِّه وانضمَّت إليه بعض القطاعاتِ، فقادها وقام بعملية مضادَّةٍ، ولم يستطعْ دخولَ دار الهاتف إلا بصعوبةٍ؛ ورفضت جماعة الأنصار التي ساهمت في هذه الحركةِ إطلاقَ سراح المعتقلين السياسيِّين الذين في سجن كوبر، وساعدت مصرُ الحكومةَ السودانية؛ إذ سمحت بانتقالِ ألفٍ وخمسمائة جنديٍّ سودانيٍّ كانوا مرابطين على قناةِ السويس، وقُتِل في هذه الحركةِ ثمانمائة شخص، منهم سبعُمائة من الانقلابيِّين، وأُعدم بعدَ ذلك ما يقرب من المائةِ شخص ممن لهم علاقة بالانقلابِ."},{"id":5419,"title":"وفاة عبد العزيز الميمني الراجكوتي .","date":["العام الهجري :1396","الشهر القمري : ذي القعدة","العام الميلادي :1976"],"text":"هو الأديبُ عبدُ العزيز الميمني الراجكوتي: باحث، ومحقِّق، ولغويٌّ، وخبير بالمخطوطات ونوادر الكتبِ، وأحد المهتمِّين بالثقافةِ العربيةِ. وُلد عبد العزيز الميمني سنة 1306هـ / 1888م ببلدة راجكوت، ومنها جاءت نسبتُه الراجكوتي، وهي تقعُ في إقليم كاتهيا دار بولاية گوجرات التي تُعرَف الآن باسمِ سوراشترا على الساحلِ الغربي للهندِ. التحقَ عبد العزيز الميمني بالكتَّاب، وتعلَّم مبادئ القراءةِ والكتابةِ، وحفِظ القرآنَ الكريم، ثم استكمل دراستَه العالية في \"لكهنو\" و\"رامبور\" و\"دلهي\". وشُغِف الميمني بالعربيةِ، فتعمَّق فيها، وعكف على الشعر العربيِّ قراءةً وحفظًا، حتى إنَّه حفظ ما يزيد على 70 ألف بيت من الشعرِ القديم، وكان يحفظُ ديوان المتنبي كاملًا. وكان قد بدأ حياته بالكلِّية الإسلامية ببيشاور؛ حيثُ قام بتدريس العربية والفارسية، ثم انتقل منها إلى الكلِّية الشرقيةِ بمدينة لاهور عاصمة إقليم البنجابِ، ثم استقرَّ بالجامعة الإسلامية في عليكرة، وظلَّ يتدرَّج بها في المناصب العلميةِ حتى عين رئيسًا للأدب العربيِّ بالجامعة، ومكث بها حتى أُحيل إلى التقاعُدِ. ثم لبَّى دعوة جامعة كراتشي بباكستانَ؛ ليتولَّى رئاسة القسم العربي بها، وأُسندت إليه مناصب علميَّة أخرى، فتولَّى إدارة معهد الدراسات الإسلامية لمعارف باكستانَ، وظلَّ يعمل في هذه الجامعة حتى وفاته. وكان قد أتاح له دأبُه الشديد في مطالعة خزائن الهندِ التي تحوي آلافَ المخطوطات وخبرته وفِطْنته أن يقفَ على النوادر منها، فعَرف من أنباء الثقافة وأخبار العلماء والأدباءِ والشعراء في بلاد الهند وفارس وما يجاوِرهما ما لا يعرفه سواه من أبناء البلادِ العربية، وأن يُتحِفَ المكتبة العربيةَ بما تيسَّر له طبعُه منها."},{"id":5420,"title":"وفاة خير الدين الزركلي صاحب كتاب الأعلام .","date":["العام الهجري :1396","الشهر القمري : ذي الحجة","العام الميلادي :1976"],"text":"هو خيرُ الدين بنُ محمود بنِ محمد بنِ علي فارس الزِّرِكلي وُلِد في بيروت في ليلة 9 من ذي الحجَّة 1310هـ، ونشَأَ في دِمَشقَ حيث موطنُ أبيه وأمِّه، وتعلَّم في إحدى مدارسها الأهليَّة، وأخذ عن عُلَمائها على الطريقة القديمة التي كانت سائدةً آنذاك في التعليم، وأقبَلَ على قراءة كُتُب الأدب، وجرى لسانُهُ بنَظْم الشِّعر، وصحب مخطوطات المكتبة الظاهريَّة، فكان لا يُفارقها إلا لساعاتٍ قليلة. أصدر مجلةً أُسبوعية بعنوان \"الأصمعي\"، والتحَقَ بمدرسة \"اللاييك\" أستاذًا للتاريخ والأدب العربي وهو دون الخامسةِ والعِشرينَ، وأصدر في دمشق جريدةً يوميةً باسم \"المفيد\"، وفي أثناء ذلك كان يَنظِمُ القصائدَ الحماسيَّة التي تتغنَّى بأمجاد الوطن، ويتعلَّق بآمال الحرية والاستقلال حتى دخل الفرنسيُّون دمشق، فغادر إلى عمان. وبعد مغادرته البلاد قرَّر المجلس العسكري التابع للفِرْقة الثانية في الجيش الفرنسي الحُكم غيابيًّا بقتل خير الدين ومُصادرة أملاكه، وفي عمان عُيِّن الزركليُّ مفتشًا عامًّا للمعارف سنة 1340هـ، ثم تولَّى رئاسة ديوان الحكومة. ثم عاد إلى دمشق بعد إيقاف تنفيذ حُكم القتل عليه، وأخذ عائلته واتَّجه إلى القاهرة سنة 1342هـ، وأنشأ بها المطبعة العربيَّة، وطبع بها كتبًا كثيرة. ثم ذهب إلى القُدس سنة 1349هـ وأصدر مع زميل له جريدةَ \"الحياة اليومية\"، لكنَّ الحكومة الإنجليزية عطَّلَتها، واتفق مع أصدقاء آخرين على إصدار جريدةٍ يوميَّةٍ في يافا، وأعدَّ لها مطبعة، لكن الجريدة لم يصدُرْ منها سوى عددٍ واحدٍ، وأُغلقت أبوابها بسبب التحاقه بالعمل الدُّبلوماسي في الحكومة السُّعودية سنة 1353 هـ؛ حيث عمل مُستشارًا بالوكالة في المفوضيَّة العربية للسعودية بمصر، وكان أحدَ المندوبين السُّعوديين في المُداولات التي سبقت إنشاء جامعة الدُّوَل العربية، وفي التوقيع على ميثاقِها، ومثَّل الحكومة السعودية في عدَّة مؤتمراتٍ دوليةٍ، وانتُدِب في سنة 1366هـ لإدارة وزارة الخارجية بجدة متناوبًا مع الشيخ يوسف ياسين وزير الخارجية بالنيابة، ثم عُين وزيرًا مُفوَّضًا ومندوبًا دائمًا لدى الجامعة العربية في سنة 1371هـ، ثم عمل سفيرًا للسعودية بالمغرب سنة 1377هـ. ومن مُؤلَّفاته: ((ما رأيتُ وما سمعتُ))، و ((عامانِ في عمان))، و ((الملك عبد العزيز في ذمَّة التاريخ))، و ((صفحة مجهولة من تاريخ سوريا في العهد الفيصلي))، و ((الأعلام)) وهو أشهر كُتُبه. انتُخب عضوًا بالمجمع العلمي العربي بدمشق سنة 1349هـ، واختُير عضوًا مراسلًا بمجمع اللغة العربية بالقاهرة سنة 1366هـ، وبالمجمع العلمي العراقي سنة1380هـ، وظلَّ بعد خروجه من العمل الدبلوماسي مقيمًا بالقاهرة التي عاش فيها أغلب حياته، وفي إحدى زياراته إلى دِمَشقَ أصابته وَعْكة صحيَّة ألزمته الفِراش بضعة أسابيع، فلمَّا قرُبَ على الشفاء رحل إلى القاهرة للاستِجْمام، لكن الحياة لم تطُلْ به فوافته المنيَّة على ضفاف النيل في الثالث من ذي الحجة. بدأ خيرُ الدين الزِّرِكْلي الكتابةَ في كتابِه المشهورِ ((الأعلام)) عام 1912م بعد الإعداد له قبل ذلك بسنواتٍ، ولم ينفُضْ يده منه طيلةَ ستِّين عامًا، باذلًا فيه ما قدَّره الله عليه من مساعٍ لتطويره، واستمرَّ في بذلها إلى العشية التي وافته فيه المنية، وقد ترجم فيه الزِّرِكْلي لـ 13.435 شخصية من القديم والحديث، ولكِنْ غلبت عليه نزعته القومية العربية، فلم يترجم لأعلام العثمانيين؛ لكراهيتِه للأتراك، في حين وضع تراجِمَ للعديد من المستشرقين!"},{"id":5421,"title":"ضياء الرحمن يتولى رئاسة بنغلادش بعد تنحية عبد الستار صايم .","date":["العام الهجري :1397","الشهر القمري : ربيع الآخر","العام الميلادي :1977"],"text":"في بنغلادش أخذ الفريق أول ضياء الرحمن يستولي على سُلُطات الرئيس الإدارية من الرئيس عبد الستار محمد صايم تبعًا للأحكام العسكرية، حتى تسلَّم أخيرًا كامل السُّلطة، وأعلن نفسه رئيسًا للبلاد وقام بجعل الإسلام نظامَ الدَّولة الأساسي بدلًا من العلمانية؛ إرضاءً للشعب؛ حيث كانوا يعرفون ماضيَه السيِّئ."},{"id":5422,"title":"انقلاب عسكري ضد الرئيس الباكستاني ذي الفقار علي بوتو .","date":["العام الهجري :1397","الشهر القمري : جمادى الآخرة","العام الميلادي :1977"],"text":"وقعت مظاهرات عنيفة في باكستان ضد الرئيس بوتو سقط خلالها حوالي 350 قتيلًا، مع آلاف الجَرْحى من جرَّاء العُنف السياسي؛ فدعا الرئيس بوتو الجيش إلى التدخُّل لمواجهة أعمال العنف، وقَمْع المظاهرات، وتأييد نظامه، إلَّا أن بعض ضُبَّاط الجيش -خاصة القادمين من إقليم البنجاب- رفضوا قمع المظاهرات والاصطدام بالشَّعْب وإطلاق النار على المتظاهرين، وكانت تلك النواة التي هيَّأت لضياء الحق -الذي كان قائدًا عامًّا للجيش- فرصةَ القيام بانقلابٍ عسكريٍّ ضد الرئيس وأعلن ضياء الحق أنَّ الجيش قام لوضع حد لحالة التدهور التي تجتاحُ البلاد، والتي عجز الرئيس بوتو عن حلِّها، وخشيةً من إقحام بوتو للجيش في السياسة واستِخْدامه في عمليات القمع. أعلن ضياء الحق أن عودة الحُكم المَدَني لباكستان ستكون بأسرَعَ ما يمكِنُ، وأكَّد أن الجيش ليست له مطامِعُ سياسية، وأنه سيحتفظ بالسُّلطة لحين إجراء الانتخابات في أكتوبر القادم. وفرَضَ ضياء الحق الأحكام العُرفية في البلاد، وحلَّ الجمعية الوطنيَّة والمجالس التشريعيَّة الإقليميَّة، وأقال حكومات الأقاليم، وشكَّل مجلسًا عسكريًّا من قادة الأسلحة الثلاثة البَريَّة والبحريَّة والجويَّة تحت رئاسته، وعندما ثبَّت ضياء الحق أقدامه بعد انقلابه ضمَّ رئاسة الدولة إلى رئاسة الحكومة، وتسلَّمهما في شوال 1398هـ / سبتمبر 1978م، وقُدم الرئيس ذا الفقار علي بوتو إلى المحاكمة بتُهمة الأمر بقتل أحد المعارضين، وانتهى الأمر بإعدام بوتو في 7 جمادى الأولى 1399هـ / 4 إبريل 1979م رغم الاستياء العالمي الشديد خاصة \"إيران الخميني\"؛ لأن بوتو من عائلة شيعية، ولم تُفلح محاولات طهران للوساطة مع إسلام آباد للعفو عن بوتو."},{"id":5423,"title":"استقلال جيبوتي .","date":["العام الهجري :1397","الشهر القمري : رجب","العام الميلادي :1977"],"text":"كانت جيبوتي (الصُّومال الفرنسي) تحت الاحتلال الفَرَنْسي الذي سامها سوءَ العذاب، ثم بعد الحرب العالمية الثانية جرى التَّصويت على دستور ديغول الخاصِّ بالمستعمرات الفرنسية، وتدخلت فرنسا بالاستفتاء لصالح قَبول الدُّستور، فأصبحت جيبوتي ضمن المجموعة الفرنسيَّة، وفي منتصف عام 1378هـ قامت مظاهراتٌ تطالب بالاستقلال الكُلِّي وتندِّد بالاستفتاء الذي لم يكن حرًّا، وجرى إضراب عامٌّ للعمال، ولكنْ قُمِع بالبطش وبقي أمرُ البلاد تحت النفوذ الفرنسي، وأُعيد تسمية المنطقة من الصومال الفرنسي إلى المنطقة الفرنسية عفر وعيسى (وهما اسما قبيلتينِ فيها)، ثم تمَّ الاتفاق أخيرًا على إجراء استفتاء شَعْبي على الاستقلال، وفي الوقت نفسه تجري انتخاباتٌ لمجموعة من النُّوَّاب في جمادى الأولى 1379هـ / أيار 1977م، وأن الاستقلال يجب أن يتبع ذلك، وبعد شهر اتَّفقت الأحزاب جميعُها على أن يضمَّها حزب واحد يحمل اسمَ التجمُّع الشَّعبي من أجل الاستقلال، وجرى الاستفتاءُ الذي أظهر التأييد التامَّ للاستقلال، وانتُخِب حسن جوليد أبتدون رئيسًا للجمهورية، وأصبحت جيبوتي مستقلة بدءًا من 11 رجب / 27 حزيران."},{"id":5424,"title":"زيارة السادات لإسرائيل المحتلة وعرض  السلام عليها .","date":["العام الهجري :1397","الشهر القمري : ذي الحجة","العام الميلادي :1977"],"text":"أعلن الرئيس المِصْري محمد أنور السادات في 28 ذي القعدة 1397هـ / 9 نوفمبر 1977م أمام مجلس الأُمَّة أنه على استعداد للذَّهاب إلى جنيف؛ للمُفاوضة مع إسرائيل، بل يُمكِن أن يذهب إلى الكنيست ومُناقشة اليهود، وكان هذا نوعًا من جسِّ نَبْض الشعب ورؤية ردِّ الفعل الذي نتج عنه فعلًا استقالة عددٍ من الوزراء، منهم وزير الخارجية، ورئيس مجلس الوزراء نفسه، وتمَّ تعيين بطرس غالي بدلًا عنه، وقام الرئيس السادات بزيارة مُفاجئة لسوريا لإقناع الرئيس حافظ الأسد واستمالته، ولكنه لم يوفَّق في ذلك، ثم قام فعلًا بالسَّفَر إلى القُدس في 8 ذي الحجة 1397هـ / 19 تشرين الثاني؛ ليُباحث اليهود في مسألة السلام، وأثار كل الفئات عليه داخليًّا وخارجيًّا، حتى إن مقرَّ جامعة الدول العربية تحوَّل إلى تونس بعد أن كان بالقاهرة، وكذلك غيرها من المنظَّمات والمؤتمرات العربية والإسلامية، وأُوقِفت عُضوية مِصر في جامعة الدول العربية، واستمَرَّ الموقف ضدَّه إلى أن اغتيل في 1401هـ."},{"id":5425,"title":"تأسيس الجبهة القومية للصمود والتصدي .","date":["العام الهجري :1397","الشهر القمري : ذي الحجة","العام الميلادي :1977"],"text":"تأسَّست الجبهة القوميَّةُ للصمود والتصدِّي ردًّا على زيارة الرئيس المصري أنور السادات للقدس، وبدء المفاوضات المصريةِ؛ لعقدِ صُلح مُنفردٍ مع إسرائيل. وقد ضمَّت الجبهةُ ليبيا وسوريا والجزائر ومُنظمةَ التحرير الفلسطينية واليمنَ الجنوبي."},{"id":5426,"title":"اعتراف بلجيكيا بالدين الإسلامي كدين رسمي في الدولة  .","date":["العام الهجري :1398","الشهر القمري : ربيع الأول","العام الميلادي :1978"],"text":"اعترفتِ الحكومةُ البلجيكية بالدين الإسلاميِّ كأحد الأديان الرئيسيةِ في البلاد. وكان هذا الاعترافُ هو الأولَ من نوعه في أوروبا، وفي عام 1998م وبعدَ حوالي ربعِ قرنٍ على هذا الاعترافِ حقَّق المسلمون نجاحًا آخر عندما خاضوا انتخاباتٍ على مُستوى الأقلِّية لاختيار هيئةٍ موحَّدةٍ تمثِّلهم لدى الحكومةِ، وتكون بمثابة المحاور الرسميِّ للسلطات البلجيكية في شؤون المسلمين."},{"id":5427,"title":"الشيوعيون ينقلبون على الرئيس الأفغاني محمد داود .","date":["العام الهجري :1398","الشهر القمري : جمادى الأولى","العام الميلادي :1978"],"text":"ترأَّس محمد داود أفغانستان بانقلابٍ في 1393 هـ/ 1973م ضدَّ الشاه محمد ظاهر (وهو ابنُ عمِّ الشاه) وكانت ميولُ محمد داود للروس الذين أرادوا منه أن يخنقَ الدعوات الإسلامية في البلاد، ومن ثَم تستطيع الشيوعيةُ أن تنتشرَ فيها، وهذا ما حصل فعلًا في البدايةِ، ولكن لما رأى أن كفَّةَ الشيوعيِّين بدأت ترجحُ وأحسَّ من نفسه بالتبعية لها أرادَ أن يرجعَ عمَّا هو عليه، فبدأ بالتودُّد للدول الإسلامية، كالسعوديةِ وباكستانَ وليبيا، وألقى أيضًا القبضَ على كثير من الزعماءِ الشيوعيين، ومنهم محمد تراقي، وحفيظ الله أمين، وبابرك كارمل، ولكن هذا لم يُعجبِ الشيوعيِّين، وقبل أن يتابع ضرباتِه حدثَ الانقلابُ في 22 جمادى الأولى 1398هـ / 29 نيسان بقيادة \"محمد غلاب زي\" أحد قادةِ جناح خلق (حزب شيوعي) والعميدِ الشيوعيِّ عبد القادر، ضد الرئيس محمد داود وأُلقيَ القبض عليه وسلَّموا السلطة إلى زعيم حزب خلق: نور محمد تراقي، واحتفظ لنفسه برئاسة الحكومة، وجعل بابرك كارمل نائبه، وفي اليوم الأول من الانقلاب قُتِل أكثر من 15 ألفَ نفس، وقُتِل الرئيس محمد داود وأبناؤه وباقي أفراد أسرته، هذا بالإضافة لقتلِه المئات من القادة الإسلاميِّين وعشرات الألوف من العامة غير الذين أودعهم غياهبَ السجون مع التفنُّن بألون العذابِ المرير، وعُرِفت هذه الحركة بثورة ساور، أي: ثَوْرة نيسان."},{"id":5428,"title":"وفاة محمد داود رئيس أفغانستان .","date":["العام الهجري :1398","الشهر القمري : جمادى الأولى","العام الميلادي :1978"],"text":"هو السردارُ محمد داود ابن عمِّ الملك محمد ظاهر شاه، وزوج شقيقتِه، ضابط في الجيش الأفغانيِّ، درس في مدينة كابول، وأتمَّ دراستَه العسكريةَ في فرنسا، عُيِّن عام 1350هـ أيام محمد نادر خان حاكمًا على مقاطعة قندهار، وبعدَ خمس سنواتٍ عُيِّن قائدًا لقوات المنطقة الوسطى، ومديرًا للكلية الحربيةِ، وعُهد إليه برئاسة الوزارة عام 1373هـ فاحتفظ لنفسِه بحقيبتي وزارتي الداخلية والدفاع إضافة إلى رئاسة الحكومة، فحكم البلادَ مدَّة عشر سنواتٍ، ولما عُرف بميوله تجاه الروس وأطماعه بالحكم نُحِّيَ عن رئاسةِ الحكومة عام 1383هـ، ثم قاد الانقلابَ في 17 /6 / 1393هـ 17 /7 / 1973م بدعم من الشيوعيِّين الأفغان الذين جاءتهم الأوامرُ من موسكو بدعم محمد داود، ونجح الانقلاب. كان هدفُ محمد داود من الانقلاب الوصولَ للسلطة والمحافظة عليها؛ لذلك تقرَّب من روسيا وعمِلَ على خنق الدعوة الإسلامية لإرضائها، بينما روسيا لم تكن ترى داود سوى مرحلة -لأنَّه لم يكن شيوعيًّا- لتضعَ الشيوعية يدها على أفغانستان بعد أن يقضيَ على الدعوة الإسلاميةِ، وفي ربيع الأول 1397هـ أعلن تشكيل حكومةٍ مدنية ونهاية الحكم العسكريِّ، فأخذ السُّخط يتزايد عليه خاصَّة من أفراد القوات المسلحةِ، ولما أحسَّ داود بترجُّح كفَّة الشيوعيين خاصَّةً مع وجود 350 خبيرًا من الخبراء الروس الذين جلبهم إلى أفغانستانَ لدعم حكومتِه، بدأ بتصفية الشيوعيِّين والتقرُّب للدول الإسلامية، وفي 19 جمادى الأولى اغتُيل أحد زعماء حزب برشام الشيوعيِّ بتدبير من حزب محمد تراقي الشيوعي، واتُّهم محمد داود بالتآمر على قتلِه، فوقع انقلاب شيوعيٌّ في 22 جمادى الأول 1398هـ على داود، فأُودع السجن مع أفراد أسرتِه واغتُيل في يوم الانقلاب 15 ألفًا، وسلَّم الشيوعيون الرئاسة لأنور محمد تراقي زعيمِ حزب الشعبِ الشيوعيِّ, فأمر محمد تراقي بإخراج محمد داود من السجن، فقُتِل محمد داود وباقي أفراد أُسرته."},{"id":5429,"title":"انقلاب عسكري يطيح بالرئيس الموريتاني مختار ولد داده .","date":["العام الهجري :1398","الشهر القمري : شعبان","العام الميلادي :1978"],"text":"كان أولُ رئيس موريتانيٍّ بعد الاستقلالِ هو مختار ولد داده الذي لم يُبقِ على أي حزبٍ إلا الحزب الحاكم، وبقِيَ رجالُ حزبه يتحكَّمون في البلاد، وازداد الجفافُ والخلافُ على الصحراء المغربيةِ، والحالة الاقتصاديةُ تتأخَّر وتتدهور، وتضايق الناس، وأربكت قضيَّة الصحراء وضعَ البلاد، وانتقل التذمُّر إلى العسكريِّين، فقامت حركةٌ هدفُها تحقيقُ السلام بإخراج البلادِ من حرب الصحراءِ، وتقويم الوضع الاقتصاديِّ، وقادها عددٌ من الضباطِ العسكريِّين، وتمَّت الحركةُ بنجاح تامٍّ في 5 شعبان 1398هـ / 10 تموز، وحلَّت اللجنة العسكريةُ للتصحيحِ الوطنيِّ حزبَ الشعب الجمهوري الموريتاني الحزب الحاكم، واختارتِ العقيدَ ولد مصطفى ولد محمد السالك رئيسًا للجمهوريةِ."},{"id":5430,"title":"مؤتمر كامب ديفيد (مخيم داود) للسلام بين مصر وإسرائيل .","date":["العام الهجري :1398","الشهر القمري : شوال","العام الميلادي :1978"],"text":"بعد أن تولَّى محمد أنور السادات رئاسةَ مصرَ خلفًا لجمال عبد الناصر أعلن سيرَه على نفس الخُطى، إلا أنه بدأ بالميل إلى أمريكا؛ ففتح البابَ كاملًا للأمريكانِ. فاجأ الساداتُ العالمَ أجمعَ العربي والإسلاميَّ بزيارته للقدس، نجم عنها توقيع معاهدةَ السلام المصرية الإسرائيلية (كامب ديفيد) في الولايات المتحدةِ؛ وقَّع المعاهدةَ من الجانب الإسرائيليِّ رئيسُ الوزراء الإسرائيلي مناحيم بيغن، ومن الجانب المصريِّ الرئيسُ المصري أنور السادات، وُقِّعت المعاهدة بعد 12 يومًا من المفاوضات في مُنتجع كامب ديفيد الرئاسيِّ في ولاية ميريلاند القريبِ من عاصمة الولايات المتحدةِ واشنطن؛ حيثُ كانتِ المفاوضاتُ والتوقيع على الاتفاقيةِ تحت إشراف الرئيس الأمريكيِّ كارتر. تُمثل اتفاقية كامب ديفيد تحولًا تاريخيًّا في مجرى الصراع العربيِّ الإسرائيليِّ والقضية الفلسطينية؛ فقد اعترف الساداتُ في هذه الاتفاقية بشرعيةِ الوجود اليهوديِّ في المنطقة، وبحقِّهم في الأمنِ والسلامِ، وإقامة علاقات حُسن جوارٍ وتعاون معه، وأخرج مصر من حلَبة الصراع مع إسرائيلَ دون أن يقابلَ ذلك أيَّ كسب سياسيٍّ وغيره لمصر سوى الجلاء عن سيناءَ بعد إقامة قوى أمريكية في معظم أنحائها، وقد قوبل هذا الاتفاقُ بموجة عارمةٍ من السُّخط العربي والإسلامي، وفي 26 مارس / آذار 1979م بعدَ خمسة أيام من تصديق معاهدة السلام المصريةِ الإسرائيلية عُلِّقَت عضوية مصر في الجامعةِ العربية، ونُقِل مقرُّها من القاهرة إلى تونس."},{"id":5431,"title":"رفض جبهة الصمود والتصدي لاتفاقات كامب ديفيد بين مصر وإسرائيل .","date":["العام الهجري :1398","الشهر القمري : شوال","العام الميلادي :1978"],"text":"أعلنت جبهةُ الصمود والتصدِّي التي تتكوَّن من سوريا والعراق وليبيا واليمنِ الجنوبيِّ والجزائر ومُنظمةِ التحرير الفلسطينية في قمَّتِها الثالثة في دمشقَ رفضَها لاتفاقية كامب ديفيد؛ معاهدة السلام المنفردةِ من قِبَل مصر مع إسرائيلَ التي وقَّعها الساداتُ مع إسرائيل في 17/ 9/ 1978م. دون مراعاةِ مصر للإجماع العربي والمتبِّني في حينِه اللاءات الثلاثة: (لا صُلح، لا اعتراف، لا تفاوض) مع العدو الصهيونيِّ قبل أن يعودَ الحقُّ لأصحابه، والتي اعتمدت في قمَّة الخرطوم في أغسطس 1967م بعد نكسةِ حزيران 67، وقد عرفت تلك القمة \"بقمة اللاءات الثلاثة\"."},{"id":5432,"title":"مأمون عبد القيوم رئيسًا للمالديف خلفا لإبراهيم ناصر .","date":["العام الهجري :1398","الشهر القمري : ذي الحجة","العام الميلادي :1978"],"text":"انتهت ولايةُ الرئيسِ المالديفي إبراهيم ناصر وجرتِ الانتخابات، ولكن دون أن يرشِّح الرئيسُ إبراهيم ناصر نفسَه، واختار المجلس وزيرَ المواصلاتِ مأمون عبد القيوم لمنصب الرئاسةِ، فتسلَّم مهمَّته."},{"id":5433,"title":"مؤتمر القمة العربية التاسع (قمة بغداد) .","date":["العام الهجري :1398","الشهر القمري : ذي الحجة","العام الميلادي :1978"],"text":"عُقد مؤتمر القمَّةِ العربية التاسعُ (قمة بغداد) بناءً على طلبِ العراق على إثرِ توقيع مصر اتفاقية كامب ديفيد للسلام مع إسرائيلَ؛ حيثُ وقَّع أنور السادات معاهدةَ السلام من جانب واحدٍ مع إسرائيلَ، فقرَّر المؤتمر أنَّ الاتفاقاتِ التي وقَّعتْها الحكومةُ المصرية في كامب ديفيد أضرَّت بحقوق الشعبِ الفلسطيني، وتم حثُّ الحكومة المصريةِ على عدم التصديقِ على الاتفاقياتِ، والأهمُّ من ذلك أن الجامعةَ جمَّدت علاقاتِها مع حكومة مصرَ، وشاركت في القمَّةِ عشرُ دول عربية ومنظمةُ التحريرِ :الفلسطينية، ولم يصدُرْ عن المؤتمر بيان ختاميٌّ، وأما أهمُّ قراراتِه فهي:- عدمُ موافقة المؤتمرِ على اتفاقياتِ كامب ديفيد.- توحيدُ الجهودِ العربية من أجل معالجةِ الخلل الاستراتيجيِّ العربي.- دعوةُ مصر إلى العودةِ عنِ اتفاقيات كامب ديفيد.- حظرُ عقد صُلحٍ منفرد مع إسرائيلَ.- دعمُ الجبهة الشمالية والشرقية ومنظمة التحرير الفلسطينية ماديًّا.- نقلُ مقرِّ الجامعة العربيةِ  إلى تونس وتعليقُ عضوية مصر.- تطبيقُ قوانين المقاطعةِ على الشركات والأفراد المتعاملين في مصر مع إسرائيلَ، والتمييز بين الحكومةِ والشعب في مصر.- إلغاءُ القراراتِ التي اتخذها مجلسُ الجامعة العربية بمُقاطعةِ اليمنِ."},{"id":5434,"title":"تنحية الرئيس الموريتاني ولد مصطفى وتولي محمد خونا ولد هيداله .","date":["العام الهجري :1399","العام الميلادي :1978"],"text":"كانت رئاسةُ الرئيس الموريتانيِّ ولد مصطفى بن ولد محمد السالك صوريةً، ولا تصرُّفَ له، بينما المتصرِّف الفعليُّ هو المقدم أحمد بوسيف الذي تُوفِّي في رجب عام 1399هـ فحلَّ محله المقدم محمد خونا ولد هيداله، والذي أصبح بدورِه هو المتصرِّفُ الفعليُّ والرئيس ما يزال بلا سلطةٍ إلى أن قام المقدم محمد خونا بعزلِ ولد مصطفى عن رئاسةِ الجمهوريةِ، وتسلَّم مكانه ورفع رتبتَه إلى لِواء."},{"id":5435,"title":"وفاة الرئيس الجزائري هواري بومدين .","date":["العام الهجري :1399","الشهر القمري : محرم","العام الميلادي :1978"],"text":"هو محمد إبراهيم بوخروبة، المعروفُ باسم هواري بومدين زعيم أمازيغي رئيسُ الجزائر. وهو ابنُ فلاحٍ بسيطٍ من عائلة كبيرةِ العددِ ومتواضعة الحال تَنتمي إلى عرش بني فوغال التي نزحت من ولاية جيجل عندَ بداية الاحتلال الفرنسيِّ، وُلد سنة 1932في دوَّار بني عدي (العرعرة) على بُعد بضعةِ كيلومترات غرب قرية \"قالمة\" من قرى الشرقِ الجزائريِّ، وتعلَّم بها وبقسنطينةَ، والتحقَ في تلك الحِقبة بجامع الزيتونةِ الذي كان يقصِدُه العديدُ من الطلبة الجزائريين، وهو من أبرزِ رجالاتِ السياسةِ بالجزائر في النصف الثاني من القرن العشرين، أصبحَ أحدَ رموز حركة عدم الانحيازِ، ولعِبَ دورًا هامًّا على الساحةِ الإفريقية والعربية، وكان أول رئيسٍ من العالم الثالث تحدَّث في الأمم المتحدة عن نظام دوليٍّ جديدٍ، وقد رفض هواري بومدين خدمة العلَمِ الفرنسيِّ وفرَّ إلى تونس سنة 1949م. ومن تونسَ انتقل إلى القاهرةِ سنة 1950م حيث التحق بجامع الأزهر ودرس فيه وتفوَّق في دراسته. تولَّى بومدين الحكم في الجزائرِ بعد انقلابٍ عسكريٍّ من 19 يونيو 1965م إلى غاية ديسمبر 1978م. فتميَّزت فترة حكمِه بالازدهارِ في الجانب الزراعي، كما قام بتأميمِ المحروقاتِ الجزائرية (البترول)، وأقام أيضًا قواعدَ صناعيةً كبرى ما زالت تعمل إلى حد الساعةِ. وكان في أول الأمرِ رئيسًا لمجلس التصحيح الثوريِّ، تم انتخابه رئيسًا للجمهوريةِ الجزائريةِ عام 1975. مات بعد أن أصيب بمرض عضال في صباح الأربعاء 27 ديسمبر."},{"id":5436,"title":"معاهدة الصداقة الأفغانية- السوفيتية الثنائية .","date":["العام الهجري :1399","الشهر القمري : محرم","العام الميلادي :1978"],"text":"بعد اغتيالِ رئيسِ أفغانستان مُحمد داود وعائلتِه ومعظم مساعديه في مذبحةٍ جماعيَّةٍ بشعةٍ في انقلاب شيوعيٍّ حكم البلادَ أولُ شيوعيٍّ هو نور محمد تراقي مؤسِّس حزب الشعب الشيوعيِّ، وحرص الاتحادُ السوفيتيُّ فورًا على دعم تراقي؛ من أجل إقامة نظامٍ ماركسيٍّ؛ ولذلك أبرمت موسكو بعد قرابة ثمانيةِ أشهرٍ من الانقلاب الشيوعيِّ الدمويِّ معاهدةَ صداقة ثنائية بين البلدينِ في 4 محرم / 5 ديسمبر تمتدُّ لعشرين عامًا، وتعهَّدت موسكو من خلال الزعيم السوفيتيِّ ليونيد بريجنيف بزيادة مُساعداتها الاقتصادية والعسكرية لأفغانستانَ، وقد استُخدِمت هذه المعاهدة فيما بعد لتبريرِ الغزوِ السوفيتيِّ لأفغانستان."},{"id":5437,"title":"وفاة المقرئ الشيخ مصطفى إسماعيل .","date":["العام الهجري :1399","الشهر القمري : محرم","العام الميلادي :1978"],"text":"هو القارئُ المشهورُ مصطفى محمد المرسى إسماعيل. من روَّاد التلاوة والترتيل للقرآن الكريمِ وكان يطلق عليه (كروان المقرئين)، ولد عام 1905 في محافظة الغربية بمصرَ في قرية ميت غزال، وقرَّر جدُّه إلحاقه بكُتَّاب القرية بمجرَّد أن بلغ الخامسة من عمرِه، واستطاع أن يتمَّ حفظ القرآن الكريم كاملًا وهو في سنِّ الثانية عشرة، درس بعدها القراءاتِ القرآنيةَ حتى أجادها وهو في السابعة عشرة من عمره، وسافر بعدها إلى طنطا للالتحاقِ بمعهد الأحمدي الأزهري. يُعدُّ الشيخ مصطفى من أبرز شيوخِ التلاوة في مصر والعالم الإسلاميِّ. أتقن المقامات وقرأ القرآن بأكثر من 19 مقامًا بفروعها، وقد عُرف عنه أنه صاحب نَفَس طويل في القراءة التجويديةِ. كان عضوًا في رابطة تضامُن المقرئين التي كان يرأسها الشيخ محمد الصيفي. كان أولَ قارئ يُسجَّل في الإذاعة المصريةِ دون أن يُمتَحَن فيها، ولما سمع الملكُ فاروقُ تلاوتَه طلب على الفور من مساعده بأن يأتيَ به ليصبحَ قارئ الديوان الملكيِّ خلال شهر رمضانَ، وبالفعل نزلَ الشيخُ ضيفًا على الاستراحة الملكيةِ بفندق شبرد لمدة سبعة أعوامٍ كاملةٍ. واصطحبَه الساداتُ معه في رحلته الشهيرة إلى مدينة القدس عام 1977، وهناك قام بالخطابةِ وإمامةِ صلاة الجمعة في المسجدِ الأقصى. كانت فرنسا، إنجلترا، أمريكا، أستراليا، وبيروت: محطَّات من رحلاتِ الشيخ إلى الخارج، والتي لم تتوقَّف إلا بوفاتِه. أصيب الشيخ بجلطةٍ في دماغه نُقل على إثرها إلى المستشفى بالإسكندريةِ وهو في غيبوبة تامَّةٍ ظلَّ بها عدَّة أيام إلى أن تُوفِّي صباح يوم الثلاثاء 26 ديسمبر، وأُقيمت له جنازة رسميَّة يوم الخميس 28 ديسمبر، ودُفن في مسجده الملحق بداره في قرية ميت غزال بالسنطةِ بمحافظة الغربيةِ."},{"id":5438,"title":"ثورة الخميني في إيران ونهاية حكم الشاه محمد رضا بهلوي .","date":["العام الهجري :1399","الشهر القمري : صفر","العام الميلادي :1979"],"text":"عمِلَ الشاهُ ما سماه الثورة البيضاء والتي هدفُها إخضاعُ رجال الدينِ وأخْذ جزءٍ من ممتلكاتهم أيضًا، وكان الخمينيُّ قد سُجِن بسبب ردِّه على الشاه يوم رفَضَ تعدُّد الزوجات، ثم نُفيَ إلى تركيا، ثم إلى العراق، وعاش في النجف، ثم أُجبر على السفر من العراقِ، ورفضت الكويتُ استقباله فسافر إلى فرنسا، ومع ذلك كانت خُطبه وكلماتُه وحماسه يُنقَل إلى إيران فتحدُث بسببها أعمالُ شغب ومظاهرات، وحدثت عدَّة أعمال عنفٍ في عددٍ من المدن ووقعت الصِّدامات مع الشرطةِ، وكان يسقطُ الكثير من القتلى أثناءَ هذه الصداماتِ، وكلُّ هذه الأمور كانت مقدِّمةً للثورة، ثم أعلن الخمينيُّ من مكان إقامتِه في باريس في 9 ذي القعدة 1398هـ / 10 تشرين الأول 1978م أن الحكومةَ الإيرانيَّةَ قد دعته ليكفَّ عن نشاطه السياسيِّ، مما ألهب المظاهرات في اليوم التالي حتى اقترح حاكمُ طهران العسكري على الشاهِ تدميرَ مدينة قم كلِّها، وأما الخمينيُّ فاجتمعَ في باريس مع قادة المعارضةِ في سبيل التنسيقِ للحركةِ، وفي اليوم التالي لعاشوراء يوم حداد الرافضةِ تدفَّق مليونا متظاهرٍ يلبسون لباسَ الحداد، وهم يهتفون: الله أكبر، وكان الجيشُ على استعداد لأي عملٍ من المتظاهرين، ثم دعا الخمينيُّ الشعبَ إلى الجهادِ، واشتعلت نار الثورةِ وتحوَّلت من مظاهراتٍ إلى ثورة معارضةٍ تطالب بإسقاطِ النظامِ، وبدأ الشاه يسترضي الشعبَ حتى خرج في التلفازِ وقال: إنه سيعمَلُ ما يأمر به الشعبُ، وفي 7 صفر / 7 كانون الثاني 1979م صرَّح حسن منتظري بعد عودته من لقاءِ الخمينيِّ رفضه أية حكومة طالما بقِيَ الشاه، ولن تقبل سوى سقوطِ الشاهِ لإقامة جمهوريةٍ إسلاميةٍ، وذلك أن الشاهَ قد أعلن أنه يريد السفرَ خارجَ البلاد وترْك مجلس وصاية نيابةَ عنه، فغادرَ الشاه إيران في 7 صفر 1399هـ / 7 يناير إلى القاهرةِ، وأعلن الخمينيُّ أنه سيعودُ للبلاد وأنه لا يريد أن يكونَ رئيسًا عليها، ثم وصل الخمينيُّ إلى طهران في 4 ربيع الأول / شباط، وكان في استقبالِه في المطارِ ستَّةُ ملايين شخصٍ، وأحاطت هذه الجموعُ بالرجل ذي 80 عامًا، فاستقلَّ طائرة هليكوبتر ليُكمِلَ رحلته فوق رؤوس البشرِ الذين احتشدوا لاستقبالِه، ومع قدومه ذابتِ الدولةُ وسلطتُها وحكومتُها أمام شخصيتِه، وانضمَّت بعض وحدات الجيش إلى المتظاهرين، وأُعلِنَ أنَّ رحيلَ الشاه نهاية المطافِ؛ فالأهمُّ هو إنهاء التسلُّط الأجنبيِّ، ونقَلَ التلفاز وقائع وصولِه، وأعلن الخمينيُّ عدم شرعية الحكومةِ شهبور بختيار، وعين مهدي بازركان رئيسًا للوزراء، وأعلنت حكومة بختيار رئيس وزراء الشاه منع التجوُّل، لكنَّ الخمينيَّ ردَّ عليه بإعلان العصيان المدني، وكتب ورقةً نُقلت صورتُها على شاشة التلفازِ الذي استولى عليه أنصارُه، فيها: \"تحدَّوا حظرَ التجول\" فتدفَّق الشعب إلى الشارع، وتصاعدتْ حدَّة المواجهات، واستولى المتظاهرون على كميات كبيرةٍ من أسلحةِ الجيش، فجاء القائد الأعلى للقواتِ المسلَّحة الجنرال قرباغي إلى الخمينيِّ وأعلن استسلامَه وحيادَ الجيش في المواجهات التي تحدُث في المدن بين مؤيِّدي النظامين، وعادت القواتُ العسكريةُ إلى مواقِعها، وأعلن الخمينيُّ قيامَ الجمهورية الإسلاميَّة الإيرانية، وفرَّ شهبور بختيار إلى فرنسا؛ حيث اغتالَه هناك الحرسُ الثوريُّ الإيراني في 6 أغسطس عام 1991م. استمرَّت الثورة سنة كاملةً ذهب ضحيَّتها 76.311 قتيلًا وعشرات الآلافِ من الجرحى، ورفعت الثورةُ الإسلامية في إيرانَ الشعاراتِ التي يمكن أن يسيرَ الشعبُ وراءها ويقبلها؛ وذلك لكسبِ التأييد، فطرحت العملَ بالإسلام دون إعلان الانتسابِ الشيعيِّ المرفوض في العالم الإسلاميِّ،  كما أعلنوا معاداةَ الدول الصليبيَّة وخاصَّة أمريكا، وأعلنوا التأييدَ للقضية الفلسطينيةِ وأنها ستعملُ على تخليص أرضِ الشام ممن دنَّسها، وصرَّح الخمينيُّ أنه سيقطع علاقاتِه مع إسرائيلَ، ثم بدا للعالم الإسلامي النوايا عندما أظهر الخميني والقادة معه العقيدةَ الرافضية فخَفَّ التأييد العالمي الإسلامي بل انعدم في أكثرها."},{"id":5439,"title":"تولي الشاذلي بن جديد رئاسة الجزائر بعد وفاة هواري بومدين .","date":["العام الهجري :1399","الشهر القمري : ربيع الأول","العام الميلادي :1979"],"text":"لما تُوفِّي هواري بو مدين في أواخر عام 1398هـ في مدينةِ الجزائرِ اجتمع المجلسُ العسكريُّ وكتم الوفاةَ حتى اتفق أعضاؤه على تسليمِ أحدِهم الرئاسةَ، ووقع الاختيارُ على الشاذلي بن جديد."},{"id":5440,"title":"تَوقيعُ مُعاهدةِ السلام بين مِصرَ وإسرائيلَ .","date":["العام الهجري :1399","الشهر القمري : ربيع الأول","العام الميلادي :1979"],"text":"تُعدُّ مُعاهدةُ السلامِ بين مصرَ وإسرائيلَ عام 1979 أوَّلَ خَرْقٍ عربيٍّ للموقف العربيِّ مِن إسرائيل؛ حيث تعهَّدت الدَّولتانِ بمُوجِب هذه المعاهدةِ على إنهاءِ حالة الحرْبِ وإقامة عَلاقاتٍ وُديَّةٍ بينهما؛ تَمْهيدًا للتسويةِ التي تقومُ على مَبدأ (الأرض مُقابِل السلام)؛ فتَنسحِبُ إسرائيلُ مِن سيناء التي احتلَّتْها عام 1967، مُقابلَ اعترافِ مِصرَ بإسرائيلَ، وتنصُّ المعاهدةُ على: (أنَّ حُكومتي جُمهورية مصرَ العربية ودَولة إسرائيلَ، اقتِناعًا منهما بالضرورةِ الماسَّةِ لإقامةِ سلامٍ عادلٍ وشاملٍ ودائمٍ في الشرْق الأوسَطِ، وَفقًا لقرارَيْ مجلس الأمن 242 و338، إذ تُؤكِّدانِ من جديدٍ الْتزامَهما \"بإطار السلامِ في الشرق الأوسط المتَّفَق عليه في كامَب دِيفيد\" المؤرَّخ في 17 سبتمبر (أيلول) 1978، وإذ تُلاحظانِ أنَّ الإطارَ المشار إليه إنما قُصِدَ به أن يكونَ أساسًا للسلامِ ليس بين مصرَ وإسرائيلَ فحسْبُ، بل أيضًا بيْن إسرائيلَ وأيِّ مِن جِيرانها العرَبِ -كلٌّ فيما يَخُصُّه على مَبدأ (الأرض مُقابِل السلامِ)- ممن يكونُ على استعدادٍ للتفاوُضِ من أجْلِ السلامِ معها على هذا الأساسِ؛ ورغبةً منهما في إنهاء حالةِ الحرْب بينهما، وإقامةِ سلامٍ تَستطيع فيه كلُّ دولةٍ في المنطقة أن تعيشَ في أمْنٍ، واقتناعًا منهما بأنَّ عقْدَ معاهدةِ سلامٍ بين مصرَ وإسرائيلَ يُعدُّ خُطوةً مُهمَّةً في طريق السلامِ الشاملِ في المنطقةِ، والتوصُّلِ إلى تَسويةٍ للنِّزاع العربي الإسرائيليِّ بكافَّة نَواحيه، وإذ تَدْعوان الأطرافَ العربيةَ الأخرى في النِّزاع إلى الاشتراكِ في عملية السلامِ مع إسرائيلَ، على أساسِ مَبادئ إطار السلامِ المشارِ إليها آنفًا، واسْتِرشادًا بها، وإذ تَرْغبان أيضًا في إنماءِ العَلاقات الوُدِّية والتعاوُن بينهما وَفقًا لِميثاقِ الأُمَم المتحدةِ، ومَبادئ القانون الدوليِّ التي تَحكُم العَلاقات الدولية في وقْتِ السِّلمِ).وكان الموقِّعون عن الجانبِ المصري: محمَّد أنور السادات رئيسُ جمهورية مصرَ العربية. وعن الجانبِ الإسرائيليِّ: مناحيم بيغن رئيسُ الوزراء الإسرائيليُّ. وشهِدَ التوقيعَ: جيمي كارتر رئيسُ الولايات المتحدة الأميركية.تاريخُ التوقيعِ: 26 مارس (آذار) 1979- 27 ربيع الثاني 1399هـ."},{"id":5441,"title":"وفاة الرئيس علي ذي الفقار بوتو  .","date":["العام الهجري :1399","الشهر القمري : جمادى الأولى","العام الميلادي :1979"],"text":"هو الرئيس ذو الفقَّار علي بوتو بن شاهنواز سياسيٌّ باكستانيٌّ شِيعيٌّ، تقلَّب في مناصبَ عديدةٍ حتى أصبح رئيسًا لباكستان. وُلِد بوتو في 5 كانون الثاني في بَلْدة لاركانا في مقاطعة السِّنْد، والده شاهنواز من مُلَّاك الأراضي في المنطقة ومن أعْيانها، عُرِف والدُهُ بمقارعته للاستِعْمار البريطاني وبمُطالبتِهِ بإنشاء دَوْلة باكستان. وأُمُّه خورشيد هُندوسيَّة الأصل، تشيَّعت قبل الزَّواج بها. درس تعليمَه الأوَّلي في المدرسة العليا لكاتدرائية بُومباي، ثم في جامعتَيْ كاليفورنيا وبيركلي في الولايات المتحدة، وتابع دراستَه في القانون في جامعة أوكسفورد في بريطانيا. وَرِث بوتو مكانةَ أبيه عند وفاته 1949م، وتزوَّج للمرة الثانية من إيرانيَّةٍ سنة 1950م بعد زواجِهِ الأول من ابنةِ عمِّه، ورُزِق من زواجه الثاني بأربعةِ أطفالٍ، كانت بناظير الثانيةَ فيهم. مارس بوتو المُحاماة في بريطانيا، كما حاضَرَ في جامعة ساوثمبتون في جنوب إنجلترا قبل عَودتِهِ إلى كراتشي 1953م؛ حيث تابع مُزاولةَ المُحاماة إلى أن انتقل لعددٍ من الوظائف، كان آخِرَها أن صار عضوَ وَفدِ بلادِهِ إلى الأُمَم المتحدة 1957م. دخَلَ بوتو الحياةَ السياسيةَ عندما اختاره الجنرال أيُّوب خان (سني) رئيسُ الجمهورية وزيرًا للإشراف على تطوير مصادر الطاقة الطبيعيَّة والمَحْروقات 1958م. ترَكَ ذو الفقار علي بوتو الحكومةَ عام 1966م بعد أن تفاقمتِ الخلافاتُ بينه وبين الرئيس محمد أيُّوب خان بشأن اتفاقيَّة طشقند وأسَّس عام 1967م حزبَ الشَّعْب الباكستاني، واختُير أمينًا عامًّا له، وتولَّى رئاسةَ باكستان بعد هزيمة باكستان في حَرْبها أمام الهِنْد التي كان من أبرَزِ نتائجها انفصالُ باكستان الشرقية، وقيام دولة بنغلاديش، ولم يستطِعْ الرئيس أغا محمد يحيى خان (شيعي) تحمُّل تَبِعات الهزيمة؛ فقَدَّم استقالتَهُ سنة 1973م؛ ليتولَّى الحُكم من بعده ذو الفقَّار علي بوتو. كان بوتو يُؤمِن بالاشتراكية الإسلاميَّة تارةً، والاشتراكيَّة الديمقراطيَّة تارةً أخرى. وارتدى لباسًا يُشبه الزِّيَّ الذي كان يرتديه القادة الاشتراكيُّون في الصين. ظلَّ بوتو رئيسًا لباكستان إلى أن قاد الجنرال ضياء الحق انقلابًا عسكريًّا ضدَّه في ٥ يوليو ١٩٧٧، وألقى القبضَ عليه وأودَعَهُ السجنَ، وفى ٤ أبريل ١٩٧٩ نُفِّذ فيه حكمُ القتل."},{"id":5442,"title":"صدام حسين يزيح الرئيس العراقي أحمد البكر ويتولى الرئاسة .","date":["العام الهجري :1399","الشهر القمري : شعبان","العام الميلادي :1979"],"text":"تسلَّم حِزبُ البَعْث السلطةَ في العراق منذ عام 1388هـ / 1968م، وكان صدَّام حسين التكريتيُّ من المُقرَّبين لأمين الحِزْب أحمد حسن البكر حتى وصَلَ صدَّام إلى مَنصِب الأمين القُطْري لحِزْب البَعْث العربي الاشتراكي، واستطاع أن يُزيحَ من أمامه كلَّ مَن يرى أنهم سيعيقون طُموحَه فأزاح حردان عبد الغفار التكريتيَّ، ثم صالح مهدي، ثم عدنان الحَمْداني، وغيرَهم من القيادة القُطْرية، ومن مَجلِس قيادة الثَّوْرة، ومن الوِزارة، ولم يَبْقَ أمامه سوى الرئيس أحمد البكر الذي بقي صُورةً، وكان صدام حسين هو المُتصَرِّف، وقرَّبَ إليه أيضًا مَن يراهم عونًا له مثل عزت الدوري الذي عُرِف بعزت إبراهيم، وطه ياسين رَمَضان الجزراوي، وطارق حنَّا، ونعيم حداد، وسَعْدون حمادي, وسَعْدون شاكر، وآخرين. ثم في 21 شعبان من عام 1399هـ / 16 تموز 1979م ضرب آخِرَ عَقَبةٍ أمامه، وهو الرئيسُ أحمد حسن البكر بالتَّنحية والإحالة على التقاعُدِ، وشَكَّل مَجلِسَ قيادةِ الثَّوْرة من جديدٍ، فتسلَّمَ رئاستَهُ، وأزاح منه خمسةَ أعضاءٍ، ونصَّبَ نفسَه رئيسًا للجُمهورية، وتسلَّمَ رئاسةَ الحُكومةِ، ورئاسةَ مجلس الثَّوْرة، وبعد تولِّي صدَّام حسين الرئاسةَ حذف من اسمه التكريتيُّ."},{"id":5443,"title":"اشتداد المقاومة الإسلامية بأفغانستان ودخول الوحدات الروسية .","date":["العام الهجري :1399","الشهر القمري : شعبان","العام الميلادي :1979"],"text":"قامت حركاتُ مُقاومةٍ في شرقي البلاد في نورستان حتى اضطرَّ الرئيسُ كارمل للسَّفَر لروسيا لطلَبِ المُساعدةِ المادِّيَّة، ثم اشتدَّت المقاومة، وظهر في الساحة الحزبُ الإسلاميُّ بقيادة قَلْب الدين حكمتيار وأحزابٌ أخرى، وفي ربيع الثاني 1399هـ / آذار 1979م وقَعَت انتفاضةٌ في مُعَسكرات هراة وحَدَثَ تمرُّد عسكريٌّ في الجيش، فأرسل الرُّوس في شعبان أوَّلَ وَحْدة هُجوميةٍ إلى أفغانستان، وهي عبارةٌ عن كتيبةٍ محمولةٍ جوًّا قوامُها أربعُمائةِ مقاتلٍ، واستقَرَّت في مَوقِعِ بغرام على بعد ثلاثينَ كيلو مترا من العاصمةِ كابل، فقامتْ نتيجةَ ذلك ثَوْرةٌ في العاصِمةِ نَفسِها في رَمَضان، وقامتِ الحُكومةُ بقَمعِها بأبشَعِ الطُّرُق."},{"id":5444,"title":"مذابح المسلمين في الحبشة .","date":["العام الهجري :1399","الشهر القمري : رمضان","العام الميلادي :1979"],"text":"وَضَعَ هيلاسيلاسي خُطَّة لإنهاء المسلمين خلال 15 عامًا، وتباهى بخُطَّتِهِ أمام الكونجرس الأمريكي, وقام بإحْراقِ الشُّيوخ والنِّساءِ والأطفالِ بالنَّار والبنزين في قَريةِ جرسم, وأمَرَ بالتَّعْقيم الإجباريِّ للمسلمين رجالًا ونساءً. وقام بعدَه السَّفَّاح منجستو بمذبحةٍ كبيرةٍ؛ حيث أمر بإطلاق النَّار على المَسجِدِ الكبيرِ بمدينةِ ريرادار بإقليم أوجاوين؛ فقُتِل أكثَرُ من ألْفِ مُسلمٍ كانوا يُؤدُّون الصَّلاةَ في رمضان عام 1399هـ، كما تمَّ تشريدُ المُسلمين وحارَبَهم من أجْلِ دينِهِم."},{"id":5445,"title":"تولي حفيظ الله أمين رئاسة أفغانستان بعد اعتقال نور محمد تراقي .","date":["العام الهجري :1399","الشهر القمري : شوال","العام الميلادي :1979"],"text":"تولَّى نور مُحمَّد تراقي الشُّيوعيُّ رئاسةَ الدَّوْلة بعد انقلابِهِ على مُحمَّد داود؛ من أجْلِ أن يُطبِّقَ النِّظام الماركسيَّ في البلاد، فعقدتْ روسيا معه مُعاهدةَ صداقةٍ ثُنائيَّة في 5 ديسمبر؛ لدَعمِهِ اقتصاديًّا وعسكريًّا، ولكن سادتِ البلادَ مَوْجةُ غضبٍ من الأوضاعِ السياسيَّةِ الجديدةِ والغريبةِ على الشعب, فقد سعى تراقي إلى تطبيقِ الماركسيَّةِ على كُلِّ الأصعدة دون اعتبار للتقاليد والأعْراف التي نشَأَ عليها الشَّعْب، فجَرَّ تراقي البلادَ إلى مشارف حَرْبٍ أهليَّةٍ، ولم تُنقِذْهُ معاهدةُ 5 ديسمبر، فوقَعَ خِلافٌ بين الرئيس نور مُحمَّد تراقي وبين رئيس وُزرائِهِ حفيظ الله أمين حول الحُكم، وعندما سافَرَ نور مُحمَّد لحُضور مُؤتمَر عدم الانحياز في هافانا عاصِمة كوبا مرَّ بموسكو، فطُلِبَ منه هناك قَتْلُ حفيظ الله أمين، ثم اجتَمَعَ السَّفير الرُّوسيُّ مع الرئيس نور مُحمَّد وأرسلا وراء حفيظ الله ليقتلوه، لكنَّ حفيظ الله نجا من مُحاولة اغتيالٍ، وفي 22 شوال 1399هـ / 14 أيلول 1979م اعتُقِل نور مُحمَّد تراقي؛ حيث تم اغتيالُهُ على يَدِ رفيقِ دَربِهِ حفيظ الله أمين الذي تولَّى رئاسةَ الجمهورية إضافةً إلى رئاسةِ الوُزراء، ثم بعد شَهرٍ أُعلِنَ عن وَفاةِ الرئيس نور مُحمَّد تراقي."},{"id":5446,"title":"وفاة نور محمد تراقي رئيس أفغانستان .","date":["العام الهجري :1399","الشهر القمري : ذي القعدة","العام الميلادي :1979"],"text":"هو نور مُحمَّد تراقي أوَّلُ رئيسٍ لأفغانستانَ بعدَ الانقِلابِ الشُّيوعيِّ على مُحمَّد داود. وُلِدَ تراقي عامَ 1335هـ 1917م في قريةِ (ميدو) في ولاية غَزْنة، وسافَرَ في 1353هـ / 1934م إلى الهِنْد، وبَقِيَ في بومباي 4 سنواتٍ، وهناك اعتنَقَ الفِكْر الشيوعيَّ، وعندما رجَعَ إلى بلادِهِ عَمِلَ في مُؤسَّسة السُّكَّر التِّجاريَّةِ بوزارةِ الماليَّة، والتَحَقَ أيضًا بجامعةِ كابلَ، ثم ابتُعِثَ إلى أمريكا كمُلحَقٍ ثَقافيٍّ سنةَ 1373هـ، وبقي هناك مُدَّة أربَعِ سنواتٍ، ثم عاد إلى أفغانستانَ، وأسَّسَ عام 1385هـ / 1965م أوَّلَ نواةٍ للحِزْب الشُّيوعي الأفغانيِّ، وكان اللقاءُ الأوَّلُ في بيتِهِ، وانتُخِبَ أمينًا عامًّا للحِزْب بالإجماعِ، وفَشِلَ في الانتخاباتِ العامَّةِ التي جَرَتْ، وتسلَّمَ الحُكمَ نتيجةَ انقِلابٍ على الرئيس مُحمَّد داود، وتسلَّم تراقي رئاسةَ الجُمهوريةِ في جُمادى الأولى 1398هـ / نيسان 1978م واحتفَظَ لنفسه برئاسةِ الحُكومةِ، وعيَّنَ بابرك كارمل نائِبَهُ، واشتدَّتْ في عَهدِهِ أعمالُ العُنفِ في البلادِ، وجرتِ الدِّماءُ، وساد الإرهابُ، وخاف الناسُ، أمَرَ نورُ محمد تراقي بإخراج مُحمَّد داود من السجن، وقُتِلَ هو بعد قَتلِ أبنائِهِ الـ 29 أمامه، كما قَتَل جميعَ مُستشاريه ورجال حُكومتِهِ، كان محمد تراقي يُتقِن لُغةَ الأوردو، واللغةَ الإنجليزيَّةَ إضافةً إلى لُغتِهِ البَشْتو، وألَّفَ عددًا من الكُتُب، منها: (البقرةُ الصَّفْراء)، و (تعالَوْا لنبدأَ العَمَلَ)، و (اللَّحْم المُجفَّفُ)، وكُلُّها استِهْزاءٌ بالإسلامِ. وينتمي هو إلى قَبيلةِ البَشْتو، وكانت نهايةُ محمد تراقي على يَدِ صديقِهِ ورَفيقِهِ حفيظ الله أمين إثْرَ عَودتِهِ من (هافانا) عاصمةِ كوبا."},{"id":5447,"title":"وفاة أبي الأعلى المودودي أمير الجماعة الإسلامية بالهند .","date":["العام الهجري :1399","الشهر القمري : ذي القعدة","العام الميلادي :1979"],"text":"هو أبو الأعْلى المَوْدوديُّ بنُ أحمَدَ حسن مودودي أميرُ الجماعة الإسلامية، وُلِدَ في 3 رجب سنة 1321هـ بمدينة أورَنْج آباد الدكن في حَيْدر آباد، وتلقَّى تعليمَهُ على يد والدِهِ، فتعلَّم المودوديُّ القُرآنَ والعربيةَ والحديثَ والفِقْه حتى حَفِظَ المُوطَّأَ، ثم دخل الثانويَّةَ وهو ابن 11 سنةً لنُبوغِهِ، ثم بعد ذلك بدأ العملَ في الصَّحافةِ التي وجَدَ فيها مجالًا للدَّعْوة والتَّعْليم، وكان يُصدِرُ مجلةَ ترجمان القُرآن، وأسَّس الجماعةَ الإسلاميةَ في لاهورَ بهَدَف الدَّعْوة إلى الإسلام، وتمَّ انتخابُهُ أميرًا لها في 3 شعبان 1360 هـ / 26 أغسطس 1941م، وبعد عامَينِ نقلتِ الجماعةُ الإسلاميةُ مركزَها الرئيسيَّ من لاهورَ إلى دار السَّلام، ومع إعلانِ قيام دَوْلة باكستان 1366 هـ / 1947م عاد المودوديُّ مع زُملائِهِ إلى لاهور مرَّةً أخرى؛ حيث مقرُّ الجماعةِ الإسلاميةِ بها، وبعد قيام باكستان بنحو خمسةِ أشهُرٍ ألقى المودوديُّ أولَ خِطابٍ له في كُلية الحُقوق، وطالب بتشكيلِ النِّظام الباكستاني طِبقًا للقانون الإسلامي، وظلَّ المودوديُّ يُلِحُّ على مُطالبة الحكومة بهذا المطلب، فألقى خطابًا آخَرَ في اجتماعٍ عامٍّ بكراتشي في ربيع الآخر 1367 هـ / مارس 1948م تحت عُنوان \"المُطالبةُ الإسلاميةُ بالنِّظامِ الإسلاميِّ\"، فاعتقلته الحكومة مع عددٍ من قادةِ الجماعةِ الإسلاميةِ في غُرَّة ذي الحِجَّة 1367 هـ / 4 أكتوبر 1948م إلى أن أُطلِقَ سراحُهُ في 11 شعبان 1369 هـ / 28 من مايو 1950م، ثم اعتُقِلَ في 1372هـ، وبعد أربعةِ أيَّامٍ من اعتقاله حُكِمَ عليه بالقتل، ثم تم تَخْفيف حُكم القتل والحُكم عليه بالسَّجْن مدى الحياة، ثم صدر حُكم بالعَفْو عنه في 1374 هـ / 1955م. كانت حياةُ المودوديِّ العِلْميةُ مليئةً بالتَّأليف والعَمَل والنَّشاط؛ فقد ألَّفَ أكثَرَ من مائةٍ وعِشرينَ كتابًا وكُتيِّبًا، غير المُحاضَرات والمَقالات منها: كتاب ((الحِجابُ))، و ((مبادئُ الإسلامِ))، و ((نحن والحَضارةُ الغربيَّةُ))، و ((المُصطَلَحاتُ الأربعةُ في القُرآنِ))، و ((تفسيرُ سُورةِ النُّور))، وغيرُها كثيرٌ، تُوفِّيَ المودوديُّ في الأول من ذي القعدة / 22 أيلول في نيويورك بأمريكا، ونُقِلَ جُثمانُهُ إلى باكستانَ، ودُفِنَ في المَنْصورةِ بلاهورَ."},{"id":5448,"title":"حادثةُ دُخولِ جُهيمان العتيبي ورفاقه الحرمَ المكيَّ الشريف .","date":["العام الهجري :1400","الشهر القمري : محرم","العام الميلادي :1979"],"text":"عَمِلَ جُهيمان بن محمد بن سيف العتيبيُّ في الحرس الوطني السُّعوديُّ لمدة 18 عامًا، ثم انتقل إلى جامعةِ أمِّ القُرى للدراسة فيها، ثم انتقَلَ إلى الجامعة الإسلامية في المدينة المنوَّرةِ، وهناك الْتقى بمحمد بن عبد الله القَحطانيِّ. تزوَّج جُهيمان العتيبي بأختِ محمد القحطانيِّ، وفي غرَّة محرَّم من العام 1400 من الهجرة / 20 تشرين، نوفمبر بعْد صَلاة الفجر دخَل جُهيمان وجماعتُه المسجد الحرامَ في مكة المكرمة لأداء صلاة الفجْرِ، وما إنِ انقضَتْ صلاة الفجرِ حتى قام جهيمان وصِهْرُه أمام المصلِّين في المسجد الحرامِ؛ لِيُعْلِنَ للناس نَبَأ ظُهور المهديِّ المنتظَر، وفِرارَه مِن \"أعداء الله\"، واعتصامَه في المسجد الحرامِ. قدَّم جُهيمان صِهرَه محمدَ بن عبد الله القحطانيَّ بأنه المهديُّ المنتظَرُ، ومُجدِّدُ هذا الدِّين، ثم قام جُهيمان وأتباعُه بمُبايعة \"المهدي المنتظَر\"، وطلَب مِن جُموع المصلِّين مُبايَعتَه، وأوصدَ أبوابَ المسجد الحرامِ، ووجَدَ المصلُّون أنفسهم مُحاصَرين داخِل المسجدِ الحرام. ثم أُخْلِيَ سبيلُ النِّساء والأطفال، فتدافَعَت قوَّات الأمْنِ السعودية مُعزَّزة بقُوات الكوماندوز السُّعودية، وتبادَلَ الطرَفان النِّيرانَ الكثيفةَ، وأصاب المسجِدَ الحرامَ ضررٌ بالغٌ جرَّاء القصفِ، وسقَط مِن أتباع جهيمان صِهْرُه محمدُ بن عبد الله، ونفَرٌ من أتباعِه، واستسْلَمَ جُهيمان ومَن بقِيَ معه، وصدَر حُكْمُ المحكمةِ بقتل 61 منهم، وكان جُهيمان من ضمن قائمةِ المحكوم عليهم بالقتل."},{"id":5449,"title":"مظاهرات الشِّيعة في القَطيفِ .","date":["العام الهجري :1400","الشهر القمري : محرم","العام الميلادي :1979"],"text":"أثناء انْشِغالِ القوَّات الحُكوميَّة في إنهاء حادثة الحرَمِ المكِّيِّ، وخِلافًا لِأوامِرِ الحكومة بمنْعِ المظاهراتِ؛ خرَجَ الشِّيعةُ في القَطيف أثناءَ احتِفالِهم بيومِ عاشوراءَ في مُظاهراتٍ عامَّةٍ، فحاولت قُوَّاتُ الحرَس منْعَ مَواكبِهم الدِّينية من التجمْهُرِ في الشوارع العامَّةِ، إلَّا أنَّ جُموعهم تدفَّقَت ترفَعُ شِعاراتٍ مُعاديةً، ويُردِّدون شعاراتٍ مُؤيِّدةً لِنِظام الخُمينيِّ في إيران، كما قاموا بتَوزيع منشوراتٍ مُحرِّضةٍ على الدولة، واستمرَّت الاضطراباتُ ثلاثةَ أيام حتى تمكَّنَت قوَّاتُ الحرَس من القضاء عليها والسيطرةِ على الوضْعِ، ثم عاود الشِّيعةُ مرَّةً أخرى القيامَ بمُظاهرتينِ مُؤيِّدتينِ لِنِظام الخُمينيِّ بإيران في القَطيف والقُرى المجاورة لها في 8 و21 صفر، إلا أن القوَّاتِ الحكوميةَ تمكَّنت مِن منْعِها."},{"id":5450,"title":"انقلابٌ عسكريٌّ يُطيح بالرئيس الأفغاني حَفيظ الله أمين .","date":["العام الهجري :1400","الشهر القمري : صفر","العام الميلادي :1980"],"text":"لم تَرْضَ روسيا عن حَفيظ الله أمين رغم شُيوعيته؛ فهم لا يَرغبون بشُيوعيةٍ تخرُج عن دائرتِهم، وكان حِزْبُ برشام (الراية) الحزبَ الشيوعيَّ الأقربَ لِمُوسكو؛ فهو يرى الارتباطَ بها، وكان زَعيم الحزب هو بابرك كارمل، وكان لا يَزال في (براغ) عاصمة تشيكسلوفاكيا كلاجئٍ سياسيٍّ، ثم في يوم 6 صفر 1400هـ / 27 ديسمبر حدَث هجومٌ على القصر الجُمهوري برئاسة وزير الدِّفاع محمد أسد وطنجار، واعتُقِلَ رئيسُ الجمهوريةِ حفيظ الله أمين، وفي اليوم التالي لَقِيَ حتْفَه، وعُيِّن بابرك كارمل رئيسًا للجمهوريةِ وهو لا يَزالُ في (براغ)؛ حيث تحرَّك منها إلى موسكو، وألْقى منها بيانًا أعلَنَ فيه أن سلَفَه كان عميلًا لِأمريكا، ثم رجَع إلى كابُلَ مع الجيشِ الرُّوسي الذي كان قد سبَقَه إلى كابُلَ."},{"id":5451,"title":"دَعمُ الاتِّحاد السُّوفيتيِّ نِظامَ بابرك كارمل الشيوعي في كابُلَ  .","date":["العام الهجري :1400","الشهر القمري : صفر","العام الميلادي :1980"],"text":"أرسَلَ الاتِّحادُ السُّوفيتي الجيشَ الأربعينَ لِدَعْمِ نِظام بابرك كارمل الشيوعي في كابُل، والذي قام بانقلابٍ اغتِيلَ فيه الرئيسُ الشيوعي حفيظ الله أمين الذي اتُّهِم بأنه \"عميل لِلأمريكانِ\". جاء كارمل إلى السُّلطة بعد عِدَّة انقلاباتٍ شَهِدتها أفغانستانُ على إثر سُقوط الملَكِيَّة في يوليو 1973م، بعد انقلاب عسكريٍّ قام به محمدُ داود ابن عم الشاه محمد ظاهر وزَوْج شَقيقته، الذي أعلَنَ جُمهورية أفغانستانَ الديمقراطيةَ، وفي 1978م انقلَبَ تراقي على محمد داود وقتَلَه، ثم وقَعَ انقلابٌ على تراقي بقيادةِ رئيسِ الوزراء حَفيظ الله أمين سنة 1979م وقتَلَه، ثم قام كارمل بالانقلابِ الأخيرِ على حَفيظ الله. وقد لقِيَ التَّدخُّل السوفيتي إدانةً دوليةً -خُصوصًا من قِبَل الولايات المتحدة- تجسَّدت في مُقاطعة الألعابِ الأولمبيَّةِ التي جَرَت في مُوسكو في 19 يوليه 1980م، ولم تَنسحِبِ القوَّات السوفيتية إلا في 15 فبراير 1989م بموجِب اتِّفاقِ جِنيف في 14 إبريل 1988م."},{"id":5452,"title":"التدخُّل (الاحتلال) الرُّوسي في أفغانستانَ .","date":["العام الهجري :1400","الشهر القمري : صفر","العام الميلادي :1980"],"text":"الحربُ السُّوفيتية في أفغانستانَ، أو الغزوُ السُّوفيتيُّ لأفغانستانَ؛ هو اسمٌ يُطلَق على حرْبٍ دامتْ عشْرَ سنواتٍ، كان هَدَف السُّوفيت المعلَنُ دعْمَ الحكومة الأفغانيةِ الصَّديقة للاتِّحاد السُّوفيتيِّ، والتي كانت تُعاني مِن هَجَمات الثوَّار المعارضِينَ للسُّوفيت، والذين حَصَلوا على دَعْمٍ مِن مجموعةٍ من الدول المناوئةِ للاتحادِ السُّوفيتي، مِن ضِمْنها الولاياتُ المتحدة الأمريكيةُ، والسُّعودية، وباكستانُ، والصِّين. أدخَلَ السُّوفيت قوَّاته في 25 ديسمبر 1979، وقد بدَأَ التدخل الرُّوسي -أو الاحتلال الرُّوسي- مع الرئيس الجديد بابرك كارمل الذي ما كان سِوى دُميةً يُحرِّكها الروسُ، بينما هم يَصُولون ويَجُولون في أفغانستان كما يَشاؤون.دخَلَ كارمل أفغانستانَ مع القوات الرُّوسية على متن دبَّابة رُوسية من نوع (تي 72)، وكانوا قد سَبَقوه وهو ما يَزال في مُوسكو يُذِيع بَياناتِه على الشعبِ الأفغاني، فاجتازوا نهْرَ جَيحون ممارسينَ الإرهابَ بكلِّ صُوره وأشكالِه، ثم بدَأَ النقلُ الجويُّ الضخم؛ حيث وصَلَ أكثرُ من 300 طائرةِ نقْلٍ ضخمةٍ لنقْلِ الجنود والعَتادِ والمؤنِ إلى كابُلَ، وهاجمت القواتُ الرُّوسية قصرَ الأمانِ ومحطةَ الإذاعةِ، كما جرَّدت وَحدات الجيشِ الأفغاني من سِلاحِها، ثم تَلا ذلك إرسالُ الجيشِ الأربعين الرُّوسي، فتوزَّعت قوَّاته على العواصم الإقليميةِ، ثم نُوقِش مَوضوعُ هذا التدخُّل في هيئة الأُمَمِ، مع المطالَبةِ بالانسحابِ الفوريِّ وغيرِ المشروط، ولكنْ دُون جَدْوى؛ فكالعادةِ عندما يكونُ الأمرُ متعلِّقًا بدولةٍ إسلامية لا يُحرِّكون ساكنًا! واسْتنكَرَت الدولُ الإسلامية هذا التدخُّل السافرَ، ولكنَّ القوَّات الروسيةَ تابعَت تَزايُدَها، فوصَلَ عددُها إلى 75 ألفًا، وأخذَتْ تَستعمِل الغازاتِ السامةَ ضدَّ المجاهدين، وحتى ضدَّ السُّكَّان المحلِّيين، فكَثُرَ اللاجِئون إلى باكستانَ، ولم يَنْقَضِ عام 1400هـ حتى كان عددُ الضحايا المسلمينَ مليونَ شخصٍ، ثم وصَل عددُ القواتِ الروسيةِ بعدَ سنتينِ إلى 150 ألفًا، وتمَّ عقْدُ اتفاقيةٍ مع كابُلَ مُدَّتها خمسُ سنواتٍ، تعهَّدَت فيها موسكو بتأمينِ الخُبراءِ والمعدَّاتِ والتدريبِ؛ حيث لم تَنسحبِ القواتُ السُّوفيتيةُ التي بلَغ عددُها في أفغانستانَ 110 آلاف جُنديٍّ، إلا بمُوجِب اتفاقِ جِنيف الذي وُقِّع في 14 إبريل 1988م، وفي 15 فِبراير 1989م انسحَبَت كافَّة قُوَّات الرُّوس بعد أنْ فَقَدوا 15 ألفَ جُنديٍّ."},{"id":5453,"title":"وُقوع أحداث عُنْف داميةٍ في مَدينة قفصةَ التَّونسيةِ. .","date":["العام الهجري :1400","الشهر القمري : صفر","العام الميلادي :1980"],"text":"وقَعَت أحداثُ عُنْفٍ داميةٍ في مدينةِ قفصةَ جنوب غرب تونس من 26 يناير حتى 3 فبراير 1980م، قام بها كُوماندوس من المعارضينَ التُّونسيين ذي توجُّهٍ عُروبيٍّ تسرَّبوا إلى مدينةِ قفصةَ، وقد تمكَّن المهاجِمون مِن السيطرةِ على أغلَبِ مَراكزِ المدينةِ، إلا أنَّ دَعواتهم للسُّكَّان إلى التمرُّدِ باءتْ بالفشَلِ. وتمكَّن الجيشُ في نِهايةِ الأمْر مِن إعادة السَّيطرةِ على المدينةِ وأسْرِ قائدِ المجموعةِ. وأدَّت العمليةُ إلى تأزُّمٍ حادٍّ في العَلاقاتِ بين تُونس ولِيْبيا؛ فقد كانت أحداثُ قفصةَ مُحاوَلةً مِن القيادةِ اللِّيبية لاحتلال وفرْضِ نُفوذها في تُونس باسمِ الوَحدة بين البلدَينِ في عهْدِ الحَبيب بُورقيبة رئيس دَولة تُونس."},{"id":5454,"title":"أبو الحسنِ بني صدر أوَّلُ رئيسٍ للجُمهورية الإيرانية .","date":["العام الهجري :1400","الشهر القمري : ربيع الأول","العام الميلادي :1980"],"text":"اختار الخُميني أبا الحسنِ بني صدر (وهو الذي كان يُرافِق الخُميني عندما رجَعَ إلى إيرانَ مِن فرنسا، وهو طَبيبٌ إيرانيٌّ متجنِّس بالجِنسيةِ الأمريكية) رئيسًا لِجُمهوريةِ إيرانَ الإسلامية، فرَشَّح نفْسَه يوم 8 ربيعٍ الأول 1400هـ، فحصَلَ على نِسبةٍ عاليةٍ من الأصواتِ، فأصبَحَ أوَّلَ رئيسِ جُمهوريةٍ في إيرانَ، وبقِي هو المشرِفَ على شُؤون الدولة والموجِّهَ لِإدارتها وللرَّعية، وكَلِمتُه هي المسموعةَ، وبيَدِه القوَّةُ الحقيقية، وكذلك أعطى الخُميني رئيسَ جُمهوريته منصبَ القائدِ العامِّ للقوات المسلَّحة، وكان أبو الحسن بني صدر يَعتمِدُ في قُوَّته على (مُجاهدي خلْق)، وعلى جَريدتِه التي تنطِقُ باسمِه (الثورة الإسلامية)، وعلى بعض ضُباط الجيشِ."},{"id":5455,"title":"وَفاة المحامي أحمدَ أسعد الشقيريِّ؛ أوَّلُ رئيسٍ لمنظَّمة التحريرِ الفلسطينية .","date":["العام الهجري :1400","الشهر القمري : ربيع الآخر","العام الميلادي :1980"],"text":"هو المحامي أحمدُ أسعد الشقيريُّ، وهو كاتبٌ ومُحامٍ، وسياسيٌّ ودُبلوماسي، وأوَّلُ رئيسٍ لمنظَّمة التحرير الفلسطينيةِ. وُلِدَ في قَلعةِ تبنين جنوبَ لُبنان عام 1908م، وانتقَلَ إلى عكَّا لِيَعيش في كَنَفِ والدِه بعد وفاةِ والدتِه. أسَّسَ مع رِفاقه «جمعية الوَحدةِ العربية»، وطُرِد مِن بيروتَ، فانتقَلَ إلى القُدس، ودخَل معهد الحُقوق الفِلَسطيني هناك، ثم دخَلَ سِلكَ المحاماةِ، وكتَب في الصُّحف الفلسطينية عن الوَحدة العربيةِ، والخطرِ الصُّهيوني، والاستعمارِ الإنجليزيِّ الذي يُهَيْمِنُ على فِلَسطين، وكانت نتيجةُ ذلك أنْ نَفَتْه السُّلطة المحتلَّة إلى قَرية الزيت الفلسطينيةِ في إقامة جَبْرية. وانتقَلَ بعد نَكبة 1948م للعمل العربيِّ، فاختِيرَ مساعدًا لعبد الرحمن عَزام الأمينِ العام للجامعةِ العربية، وكان مِن دُعاة الوَحدة العربية الأوائلِ. وعندما تأسَّست منظَّمة التحريرِ الفلسطينية سَنة 1964م كان أولَ رئيسٍ لها. وأنشَأَ جَيش التحريرِ الفلسطينيَّ، ثم أنشَأَ قوَّةً فِدائية باسمِ (قوات التحريرِ الشَّعبية) قامت بعمليَّاتٍ في كلِّ الأراضي الفِلَسطينية المحتلَّةِ."},{"id":5456,"title":"اغتيالُ عالِم الذَّرة المصري الدكتور يَحيى المشد في باريسَ .","date":["العام الهجري :1400","الشهر القمري : رجب","العام الميلادي :1980"],"text":"هو الدكتور يَحيى أمين المشد؛ عالِمُ ذَرَّةٍ مصريٌّ وأستاذٌ جامعيٌّ، وُلِد يحيى المشد في مصرَ في مدينةِ بَنْها سنة 1932، وتعلَّم في مدارسِ طنْطا، وتخرَّج من قِسم الكهرباء في كُلِّية الهندسة جامعة الإسكندريةِ سَنة 1952، اختِيرَ لِبَعثة الدكتوراه إلى لَندنَ سنة 1956، لكنَّ العُدوانَ الثُّلاثي على مصرَ حوَّلها إلى مُوسكو، ثم عاد بعدها سَنة 1963 متخصِّصًا في هَندسة المفاعِلات النَّووية. وعندَ عَودتِه انضمَّ إلى هَيئة الطاقة النَّووية المصريةِ؛ حيث كان يقومُ بعمَلِ الأبحاثِ، وانتقَلَ إلى النرويجِ بيْن سَنتيْ 1963 و1964، ثم عاد بعْدَها وعمِلَ أستاذًا مساعدًا بكُلِّية الهندسة بجامعة الإسكندرية، وما لَبِثَ أن تمَّت ترقيتُه إلى دَرجةِ \"أستاذ\"؛ حيث قام بالإشرافِ على الكثيرِ من الرَّسائل الجامعيةِ، ونشَرَ أكثرَ مِن (50) بحثًا. وبعد حَرْب يونيو 1967 تمَّ تَجْميد البرنامج النَّوويِّ المصري؛ مما أدَّى إلى إيقافِ الأبحاث في المجالِ النَّووي، وأصبح الوضعُ أصعَبَ بالنسبةِ له بعد حرْبِ 1973؛ حيث تمَّ تحويلُ الطاقات المصريةِ إلى اتِّجاهات أُخرى. وكان لِتَوقيع صدَّام حسين في 18 نوفمبر 1975 اتِّفاقية التَّعاون النووي مع فَرنسا أثَرُه في جَذْب العُلماء المصريين إلى العراقِ؛ حيث انتقَلَ للعمَلِ هناك، ودرَّسَ في الجامعة التِّكنولوجية في قِسم الهندسةِ الكهربائية. وقام برَفْضِ بعضِ شُحنات اليورانيوم الفَرنسية؛ حيث اعتَبَرها مُخالِفةً للمواصفات، وأصرَّت بعدها فَرنسا على حُضوره شخصيًّا إليها لتَنسيقِ استلام شُحنة اليورانيوم. وفي يومِ السبت 30 رجب / 14 يونيه، وفي حُجرة رقم (941) بفندق المريديان بباريسَ؛ عُثِر على الدكتور يحيى المشد جُثةً هامدةً مهشَّمةَ الرأسِ، ودِماؤه تغطِّي سَجادةَ الحُجْرة. وقد أُغلِقَ التحقيقُ الذي قامت به الشُّرطة الفرنسيَّة على أنَّ الفاعل مَجهولٌ!"},{"id":5457,"title":"الحربُ العِراقيةُ الإيرانيةُ .","date":["العام الهجري :1400","الشهر القمري : ذي القعدة","العام الميلادي :1980"],"text":"بدَأَت الحربُ بين العراقِ وإيرانَ في 13 ذي القعدة عام 1400هـ / 22 أيلول، باندفاعِ القواتِ العراقيةِ داخلَ إيرانَ؛ اعتمادًا على اتِّفاقية الجزائر التي تُطالِبُ الطرفينِ بالانسحابِ مِن المناطق المحتلَّةِ من أرْض الطرَفِ الآخَرِ، غيرَ أن إيرانَ لم تَنسحِبْ من مَنطقة زين القوسِ، وتجاهَلَت مُطالبةَ العراقِ لها بالانسحابِ، ثم قامتْ إيرانُ بهُجومٍ مُعاكس في جُمادى الأولى عام 1402هـ / آذار 1982م، وتمكَّنت مِن استعادة مَدينة المحمرة (خرمشهر) بعدما يَقرُب مِن شَهرينِ مِن بَدْء الهجوم، ثم اشتدَّت المعارضةُ الداخلية في العراقِ على الحرْب مِن عدة أطرافٍ؛ مِن إسلاميين، وشِيعةٍ، وحِزْبيينَ مُوالين لِسُوريَة وأكرادٍ، ولكنَّ الرئيس صدامًا لم يَأْبَه للمعارضين، فهاجَمَ هو أيضًا ناقلات النِّفط في شَهر شوال من عام 1402هـ / آب 1982م، في مُحاولة للضغْطِ على إيرانَ للصُّلح وإيقاف مُساعدتِها للأكرادِ، وشنَّت إيرانُ هُجومًا من الجبهةِ الشَّمالية، واستطاعَتْ احتلالَ ما يَقرُبُ من 700 كم2، وزادت العراقُ مِن الهجماتِ الصاروخيةِ والغاراتِ الجويةِ ضِدَّ المُدن والمنشآتِ النِّفطية في جزيرة خرج، وهدَّدت إيرانُ بإغلاقِ مَضيق هُرْمزَ حتى يتِمَّ حَجْزُ الخليج عن الاتِّصال ببقية البحارِ، وحاولت أمريكا ومِصر وسُوريَة والسُّعودية التوسُّطَ؛ لِيَتِم التفاوض بيْن العراق وإيرانَ، إلا أنَّ إيرانَ رفَضَت إلا بتَنحيةِ صدَّام عن الحكمِ وانسحابِ القوات العراقيةِ من المناطق التي دخلَتْها، ودفْعِ العراقِ تعويضاتٍ عن خسائرِ إيرانَ في هذه الحرب، وحرَصَت كلُّ دولة على التسلُّح بأحدث الأسلحةِ، وأمدَّت مصرُ العراقَ بمعِداتٍ عسكريةٍ تُقارِب ملياريْ دُولارٍ، وباعتِ الصِّين للعراقِ أسلحةً بما يقارب الثلاثةَ مِليارات دُولار، وزوَّدت أمريكا العراقَ بطائرات مروحيةٍ ومُعدات ثقيلةٍ، مع تَصريحِها بالحياد، وزوَّدت رُوسيا العراقَ بالأسلحةِ والصواريخِ، مع إعلانِها هي الأخرى الحيادَ، وباعت الكويتُ والسُّعودية رُبعَ مليونَ برميلٍ من النِّفط يوميًّا من المنطقة المحايدة لصالح العراقِ، أمَّا إيرانُ فاشترَتْ من الصِّين أسلحةً بقيمة 575 مليونَ دولارٍ، واشترَتْ من البرازيلِ وتشيلي، وزوَّدتها أمريكا ورُوسيا أيضًا بالأسلحةِ، وهاتانِ الدولتانِ مِن صالحهما بَقاءُ الحرب، ومن أهمِّ المصالحِ بيعُ الأسلحةِ وغيرها مِن المصالح الأخرى في المنطقة التي يُرِيدون أن تبقى غيرَ مُستقرَّةٍ دائمًا، ثم حشَدَت إيرانُ نِصف مليونَ مقاتلٍ قُرب شطِّ العرب، وأنشأَتِ العراقُ السُّدود والحواجزَ أمام الهجومِ الإيراني الذي قام بضَرْب الناقلاتِ الكويتية والسُّعودية وموانئ الدَّولتينِ النِّفطية، واستأنَفَ العراقُ الهجومَ على ناقلاتِ النِّفط الإيرانية، وفي جمادى الآخرة 1405هـ / آذار 1985م حشَدَت إيرانُ نِصف مليون مقاتل على الجبهةِ الجنوبية شَرق نَهر دِجْلة، وتمكَّنت مِن عُبور النهر، واتَّهَمت العراقَ باستعمالِ الأسلحةِ الكيماوية، وهاجَم العراقُ طَهرانَ بالصواريخ، وثلاثينَ مدينةً أخرى، وردَّت إيرانُ بالمثلِ، وفي شهر شوال / حُزيران احتلَّت العراقُ جَزيرة خرك الإيرانية، وفي مَطلع عام 1407هـ / أيلول 1986م دمَّرت العراق ناقلات النِّفط في جَزيرة لافان، وهاجمَت جزيرة لارك، وتقدَّمت إيرانُ إلى البصرةِ، ثم أخذَتِ التهديداتُ العسكريةُ الإيرانية تقِلُّ، فركَّزت العراقُ على الأكرادِ، وفي 8 جمادى الأولى 1407هـ / 8 كانون الثاني 1987م قامت فِرقةٌ إيرانية تَحمِل اسم (كربلاء 5) بهجومٍ نحوَ البصرة، ولكنها تكبَّدت خسائرَ جسيمةً، ثم أعقَبها هَجمات أخرى على طُول الحدودِ مع العراقِ، وما أنِ انتصَفَ العامُ حتى كان العراقُ قد استعاد كثيرًا من أراضيهِ التي كانت إيرانُ قد احتلَّتْها، وفي بداية النِّصف الثاني من عام 1408هـ / شباط 1988م، استأنَفَت العراقُ قصفَ المُدن بعد انقطاعٍ دامَ أكثر من عامٍ، وسبَقه استئنافُ قَصفِ الناقلاتِ، وفي رجب من العام نفْسِه بدأ جيشُ التحريرِ الوطني -وهو الجناحُ العسكريُّ لتجمُّع المقاومة الإيرانية من مُجاهدي خلق، والمدعومُ مِن العراق- ببَدْءِ عَملياته الهجوميةِ في إقليم عَرَبستان، ثم استعادتِ العراقُ الفاو في شَعبان، وفي ذي الحجة وافقتْ إيرانُ على قَرار مجلس الأمن رقم (598) دون قيدٍ أو شرطٍ بعد أن ماطَلَت أكثرَ من عامٍ، وتقدَّمت السرايا العراقيةُ داخِلَ إيران قبل عمليةِ انسحابِ إيران إلى خلْف الحدود، ودخلَت إيرانَ، وفي أواخر شَهر ذي الحجة دخلَت العراقُ وإيرانُ في مفاوضاتٍ لإنهاء الحرب، وطلَب العراق تأخيرَ تنفيذ وَقفِ إطلاق النار حتى تتمَّ المفاوضات المباشِرةُ مع إيرانَ تحت إشراف الأُمَمِ المتحدة، وفي 8 محرم 1409هـ / 20 آب 1988م توقَّف إطلاقُ النار، ووُضِعَ 350 ضابطًا من الأُمَمِ المتحدة للإشراف على تَنفيذ وقفِ إطلاق النارِ، وأقرَّ مجلسُ الشيوخ الأمريكي فَرْضَ عُقوبة اقتصادية على العراقِ، وامتنَعَت أمريكا مِن استيراد النِّفط العراقي، أمَّا المفاوضاتُ بين العراق وإيرانَ فكانت كلُّ دولةٍ تدَّعي أن شطَّ العرب من حقِّها، وبدأ الاختلافُ على بعضِ القضايا؛ كتَفتيش السُّفن العراقية في مَضيق هُرْمز، ومَن بدَأ بالحربِ، وغير ذلك، وبقِيَ الخلاف مُستحكمًا إلى صفر 1410هـ / أيلول 1989م، ثم في ربيع الثاني / تشرين الثاني وافقَت كلٌّ من العراق وإيرانَ على تبادُلِ الأسرى، بعد أنْ دامت الحربُ أكثرَ من 8 سنوات."},{"id":5458,"title":"الانقلابُ العسكريُّ الثالث في تُركيا على الرئيسِ فخري كوروتورك .","date":["العام الهجري :1400","الشهر القمري : ذي القعدة","العام الميلادي :1980"],"text":"زاد النشاطُ الإسلاميُّ في تُركيا أيامَ حُكومة فخري ثابت كوروتورك، والذي أظهَرَه حِزب السلامة الوطني برئاسة نَجم الدِّين أرْبكان، وهذا ما أخاف الدوائرَ الاستعماريةَ، فكان لا بُد مِن إجراء عمل يحدُّ من نَشاط الإسلاميين، مع الخوف أيضًا من انتشارِ الشُّيوعية وسَيطرتها على الحُكْم، فتَحرَّك الجيش بقيادةِ رئيس الأركان كنعان إيفرين في 3 ذي القعدة 1400هـ / 12 أيلول بانقلابٍ عَسكري ضدَّ الحكومة المدنية المنتخَبةِ، وكان هذا الانقلابُ ثالثَ انقلابٍ عسكري بعد انقلاب 27 أيار / مايو 1960م على عَدنان مندريس، وانقلابِ المذكِّرة في 12 أذار / مارس 1971م، وكانت الفكرةُ التي قام عليها هذا الانقلابُ هي حِماية المبادئ العلمانيةِ التي وضَعها أتاتورك أساسًا للجمهورية التُّركية، فتخوَّف العسكرُ مِن الصعود الملحوظِ للتَّيار الإسلاميِّ في الانتخابات القادمةِ؛ لذلك حصَل هذا الانقلابُ بدعْمٍ من أمريكا بعْد أنْ فقَدَت حليفَها في المنطقة بعدَ الثَّورة الإيرانية 1979م، ومن أهمِّ أسباب الانقلابِ: فشَلُ حِزب الشعب الجمهوري (حزب أتاتورك العلماني) في إدارة البلادِ. شكَّل هذا الانقلابُ ملامحَ تُركيا لثلاثةِ عُقود قادمةٍ، كما يُعدُّ هذا الانقلابُ الأكثرَ دَمويةً؛ لذلك اتَّخذ مجلسُ الأمن القومي -الذي كان يَرأسه الجِنرال كنعان إيفرين، مع عددٍ من الضُّباط الكبار في الجيشِ والقوات المسلحة التُّركية- بعد الانقلاب في 12 أيلول 1980 قراراتٍ عديدةً تتعلَّق بسياسةِ تُركيا وقتها لغاية الانتخابات العامة التي تمَّت عام 1983، والتي أسفَرَت عن انتخابِ إيفرين رئيسًا لِتُركيا في نوفمبر 1982 بنسبةِ 90% من الأصواتِ، ثم قام بعرْضِ دُستور جديد على الاستفتاءِ، قام فيه بتَحصينِ نفْسه وجِنرالات الانقلاب مِن المحاكمة في المادة (15)، وعزَّز الدستورُ من دَور الجيش في الحياة المدنية بذَريعة حِماية الجُمهورية والعلمانية في المادتين (35) و(85) مِن الدُّستور التركي. كما أقدَمَ إيفرين على إغلاقِ كافَّة الأحزاب السياسية، وتمَّ اتخاذ قرارِ مُراقبة زُعماء الأحزاب بشكلٍ دقيقٍ، ومِن ثَم تمَّت مُحاكمتهم، وبالإضافةِ إلى ذلك قامت السُّلطات المَعْنية بأمرٍ من إيفرين كنعان بسحْب الجِنسية التركية من 14 ألفَ شخصٍ، وإعلانِ الأحكام العُرْفية التي استمرَّت 7 سنوات؛ حيث تمَّت مُحاكمة 230 ألف شخصٍ ضمن 210 دعوة قَضائية، وحُكِم على 517 شخصًا بالقتل، وأُعيد تَصميم السياسة التُّركية من جديدٍ بعد ذلك، ومِن بين الآثار السَّلبية لانقلابِ أيلول العسكري: طَرْدُ ما يُقارب 30 ألف شخصٍ من أعمالهم من دون وُجود مُبرِّرات قانونية تَستوجِب عَزْلَهم عن أعمالهم، وإغلاق عددٍ كبير مِن الجمعيات والمؤسسات الإنسانيةِ في البلادِ. أمَّا على الصَّعيد الإعلاميِّ فقد تمَّ منْعُ 937 فيلمًا سينمائيًّا من العرْض، ولم يَستطِعْ ما يقارب مِن 300 صحيفة ممارسةَ أعمال النشْر والطِّباعة، وبعد مُرور 30 عامًا على الانقلابِ، واستجابةً لمطالِب عددٍ كبير من متضرِّري الانقلاب؛ قرَّرت حُكومة رجب طيب أردوغان فتْحَ ملف تحقيقٍ بحقِّ مَسؤولين رَفيعِي المستوى الذين قادوا انقلابَ 12 أيلول، فتَمكَّن حِزب العدالة والتنمية الذي يَقوده أردوغان مِن تعديلِ عشَرات الموادِّ من ذلك الدستور، بما فيها حَصانة العسكرِ، الأمر الذي سمَحَ للمحاكم بمُتابعة الانقلابيينَ، وإصدار حُكم المؤبَّد في حقِّهم."},{"id":5459,"title":"تَوقيعُ مُعاهَدة التعاون والدِّفاع المشترك بين سُوريَة والاتِّحاد السُّوفيتي .","date":["العام الهجري :1400","الشهر القمري : ذي القعدة","العام الميلادي :1980"],"text":"وَرِثت روسيا تَركةَ الاتِّحاد السُّوفيتي القديمِ وعَلاقتَه بالجُمهورية العربية السُّورية، وقد مرَّت عَلاقاتُهما بكثيرٍ من المواقف المختلِفة، ويُلاحَظ أنَّ السُّوفيت لم يَرْكَنوا إلى الحكومات السُّورية المتعاقِبة؛ لِعَدائها جميعًا للحزبِ الشُّيوعي السوري، إلَّا أنهم ارْتاحوا لِرَغبتِها في الحِفاظ على استقلال سُوريَة، وتجنُّب الشِّباك الأمريكية، وقد وقَّعت سُوريَة معاهدةَ صداقةٍ وتعاوُن مع الاتِّحاد السُّوفيتي في يوليه 1980م، وساعد دمشقَ على ذلك عواملُ عِدةٌ؛ أهمُّها: سُوء عَلاقتها مع بَغدادَ وعمَّانَ، وأبرَز ما جاء فيه: 1/ يُعلِنُ الطرفانِ المتعاقدانِ عَزْمَهما على التطويرِ والتعزيز لِرَوابط الصداقةِ والتعاون بيْن كِلْتا الدولتينِ والشعبينِ في المجال السياسيِّ، والاقتصاديِّ، والعسكريِّ، والعِلْميِّ التِّكنيكي، والثقافيِّ، والمجالات الأخرى، على أساسِ مَبادئ التكافؤِ والمنفعة المتبادَلة، واحترام السِّيادة والاستقلال الوطنيِّ، وحُرْمة الأراضي، وعدم التدخُّل في الشُّؤون الداخلية لِبَعضهما البعض.‏ 2/ سوف يَعمل الطرفانِ المتعاقدانِ بكلِّ السُّبل على تعزيز السلامِ، وأمْن الشعب، وانفراجِ التوتُّر الدوليِّ وتجسيده في أشكالٍ ملموسةٍ من التعاون بيْن الدولِ، وتسوية قَضايا الخلافات بالطُّرق السِّلمية، والإقصاء مِن مُمارسات العَلاقاتِ الدوليةِ لأيَّة ظواهر لِسِياسة الهَيمنة والعُدْوان.‏ قدَّمت رُوسيا منذ أيام الاتِّحاد السُّوفيتي الدعمَ العسكريَّ الكبيرَ لِسُوريَة، ولكنه تراجَعَ في التِّسعينيات في عَهدي الرئيسينِ: غورباتشوف، ويلتسين، وعاد الدعمُ الرُّوسي لِسُوريَة في عهد الرئيسِ فلاديمير بوتين، وكان بإعادةِ افتتاح القاعدةِ البحرية الرُّوسية في ميناء طَرطوس، وعَقْد الصفقاتِ العسكرية مع سُوريَة، منها: تَقديم خُبراء عسكريينَ وأسلحةٍ، وتجديد عَتاد الجيشِ السُّوري مِن أسلحة حديثةٍ."},{"id":5460,"title":"زِلزالانِ يَضربانِ مدينة الأصنام (الشلف حاليًّا) بالجزائرِ .","date":["العام الهجري :1400","الشهر القمري : ذي القعدة","العام الميلادي :1980"],"text":"ضرَبَ زِلزالانِ عَنيفانِ متتاليانِ مدينة الأصنام (الشلف حاليًّا) في غرب الجزائرِ، الأول في يوم الجمعة 30 ذي القعدة / 10 أكتوبر، بقوَّة سبْعِ درجاتٍ وثلاثة أعشارِ الدرجةِ، وقد كان زلزالًا عَنيفًا جِدًّا لدرجةِ تَدميره 80 بالمائةِ من المدينةِ، واستمرَّت الهزات الارتداديةُ لهذا الزلزالِ عدَّة أشهرٍ بعد الهزةِ الأولى، فوقَع زلزالٌ ثانٍ بقوَّة ست درجاتٍ وثلاثة أعشار الدرجةِ حسَب مِقياس رِيخترَ، وأدَّيا إلى صَدْع طوله 36 كيلو مترًا، وخسائرَ بشريةٍ بلَغَت 10.000 ضحية، من بينهم نحو ثلاثةُ آلاف قتيلٍ، وتدمير مُعظَم أجزاء المدينةِ."}]
